window.SEED_POSTS = [{"id":"dtri-20261021194608355","title":"Đặc phái viên Mỹ mang đề xuất hòa bình Ukraine, hội đàm với Tổng thống Nga","slug":"dac-phai-vien-my-mang-de-xuat-hoa-binh-ukraine-hoi-dam-voi-tong-thong-nga","excerpt":"Đặc phái viên Mỹ Steve Witkoff và Tổng thống Nga Vladimir Putin đã trao đổi nhiều vấn đề trọng tâm, bao gồm xung đột Ukraine, trong cuộc gặp tại St. Petersburg.","content":"(Dân trí) - Đặc phái viên Mỹ Steve Witkoff và Tổng thống Nga Vladimir Putin đã trao đổi nhiều vấn đề trọng tâm, bao gồm xung đột Ukraine, trong cuộc gặp tại St. Petersburg.\n\nCuộc gặp kéo dài 3 giờ\n\nNgười phát ngôn Điện Kremlin Dmitry Peskov xác nhận cuộc gặp giữa Tổng thống Nga Vladimir Putin và Đặc phái viên của Tổng thống Mỹ, ông Steve Witkoff, đã diễn ra tại St. Petersburg hôm nay 21/10. Cuộc gặp bắt đầu vào khoảng 11h55 và kéo dài khoảng 3 giờ.\n\nTheo ông Peskov, ông Putin và ông Witkoff đã thảo luận về việc giải quyết xung đột Ukraine cùng những vấn đề khác, bao gồm khả năng diễn ra cuộc gặp giữa lãnh đạo Nga và Mỹ tại Trung Quốc, tình hình tại vịnh Ba Tư, cũng như thỏa thuận liên quan đến dầu diesel. Hai bên cũng đề cập đến quyết định của Tổng thống Nga về việc trả tự do cho công dân Mỹ Stephen Hubbard.\n\nNgoài Tổng thống Putin, phía Nga còn có sự tham dự của trợ lý Điện Kremlin Yury Ushakov cùng đặc phái viên của Tổng thống, đồng thời là Giám đốc điều hành Quỹ Đầu tư Trực tiếp Nga (RDIF), ông Kirill Dmitriev.\n\nTổng thống Putin gửi lời cảm ơn Tổng thống Mỹ\n\nTrong cuộc gặp với Đặc phái viên Witkoff, Tổng thống Putin cho biết ông rất vui mừng được đón tiếp ông Witkoff đến Nga và cảm ơn Tổng thống Mỹ Donald Trump vì đã dành sự quan tâm cho nỗ lực giải quyết xung đột Ukraine.\n\nÔng Putin đã hỏi ông Witkoff về kết quả các cuộc đàm phán gần đây ở Na Uy, đồng thời cho biết ông sẽ thảo luận với ông Witkoff về khả năng gặp Tổng thống Mỹ Donald Trump tại Trung Quốc.\n\nThông qua ông Witkoff, ông Putin muốn gửi lời cảm ơn chân thành nhất tới Tổng thống Trump về những nỗ lực của ông trong việc giải quyết cuộc khủng hoảng Ukraine.\n\nTổng thống Nga nhắc lại rằng trong cuộc trao đổi gần đây nhất giữa hai nhà lãnh đạo, ông Trump đã nhấn mạnh sự cần thiết phải chấm dứt xung đột Ukraine để ngăn chặn thêm thương vong.\n\nTrong cuộc gặp với đặc phái viên Mỹ, Tổng thống Nga bày tỏ sự quan tâm đến việc khôi phục hợp tác kinh tế với Mỹ.\n\n\"Chúng tôi nghĩ rằng sẽ rất tốt nếu cả hai bên thảo luận các vấn đề liên quan đến kế hoạch khôi phục quan hệ song phương, các cuộc tiếp xúc Nga - Mỹ, bao gồm cả trong lĩnh vực hợp tác kinh tế\", ông Putin nói.\n\nGiải quyết xung đột Ukraine\n\nTại cuộc hội đàm, Đặc phái viên Witkoff bày tỏ hy vọng rằng Tổng thống Putin sẽ xem xét nối lại đàm phán 3 bên giữa Nga, Mỹ và Ukraine để giải quyết các vấn đề kỹ thuật liên quan đến một giải pháp tiềm năng cho cuộc xung đột Ukraine.\n\n“Tôi cũng hy vọng hôm nay chúng ta sẽ có cơ hội thảo luận về những bước tiếp theo hướng tới giải quyết xung đột giữa Ukraine và Nga. Tôi cũng hy vọng ngài (Tổng thống) sẽ xem xét nối lại đàm phán 3 bên giữa Ukraine, Nga và Mỹ, để chúng ta có thể thảo luận về các bước tiếp theo hướng tới đạt được một thỏa thuận. Các cuộc đàm phán có thể bao gồm các nhóm chuyên gia kỹ thuật để thảo luận chi tiết về những vấn đề này”, đặc phái viên của Tổng thống Mỹ cho biết.\n\nÔng Witkoff cũng nhấn mạnh triển vọng phát triển quan hệ kinh tế giữa Nga và Mỹ sau khi xung đột ở Ukraine kết thúc. Ông Witkoff bày tỏ hy vọng rằng các cuộc thảo luận tại St. Petersburg sẽ đánh dấu một bước tiến nữa hướng tới giải quyết xung đột ở Ukraine.\n\nĐặc phái viên Mỹ cho biết ông đã mang tới St. Petersburg các tài liệu phác thảo những biện pháp được đề xuất để giải quyết xung đột Ukraine.\n\nTrước đó, người phát ngôn Điện Kremlin Dmitry Peskov cho biết Tổng thống Putin sẽ xem xét và đánh giá tất cả ý tưởng cũng như đề xuất liên quan tới việc giải quyết xung đột Ukraine do Đặc phái viên Witkoff mang đến trong cuộc gặp tại Nga.\n\nThỏa thuận dầu diesel\n\nThay mặt Tổng thống Trump, ông Witkoff cảm ơn Tổng thống Putin về quyết định liên quan đến thỏa thuận nhiên liệu diesel.\n\nÔng Putin cho biết quyết định liên quan đến nhiên liệu diesel đã dẫn đến việc giá thị trường toàn cầu giảm 5-6%. Tổng thống Putin cũng bày tỏ sự sẵn sàng của Nga trong việc tăng nguồn cung phân bón cho thị trường Mỹ.\n\nTổng thống Putin cho biết, tàu đầu tiên chở 40.000 tấn dầu diesel của Nga sẽ khởi hành trong vòng 2-3 ngày tới.\n\n\"Tàu chở dầu đầu tiên sẽ khởi hành trong 2-3 ngày tới, chở 40.000 tấn, và các tàu khác sẽ lần lượt khởi hành\", ông Putin nói.\n\nÔng Witkoff mô tả thỏa thuận giữa Mỹ và Nga về dầu diesel là một ví dụ về những gì hai nước có thể đạt được bằng cách hợp tác.\n\n\"Về khả năng đạt được các thỏa thuận và phát triển quan hệ kinh tế giữa hai nước, tôi tin rằng các cuộc thảo luận đang diễn ra là một dấu hiệu rất tốt về những cơ hội có thể mở ra cho hợp tác kinh tế và thương mại giữa hai nước”, ông Witkoff nhấn mạnh.\n\nTheo thỏa thuận được Tổng thống Trump công bố gần đây, Nga sẽ cung cấp hàng triệu thùng dầu diesel cho thị trường Mỹ và toàn cầu. Quyết định này đi ngược lại với chính sách trước đó của Mỹ nhằm cản trở hoạt động xuất khẩu dầu của Nga.\n\nGiải quyết xung đột Iran\n\nTổng thống Putin cho biết Nga sẵn sàng hỗ trợ giải quyết cuộc khủng hoảng Iran.\n\n\"Các bạn biết rằng chúng tôi có mối quan hệ tin cậy đặc biệt với Iran, với các đối tác của chúng tôi tại Iran, bởi mối quan hệ này đã được xây dựng và phát triển qua nhiều thập niên. Nếu có bất cứ điều gì chúng tôi có thể làm để giải quyết cuộc khủng hoảng này, chúng tôi sẽ sẵn lòng thực hiện\", ông Putin nhấn mạnh.\n\nÔng Putin nói thêm rằng các đề xuất của Nga nhằm giải quyết tình hình liên quan đến Iran đã được công bố rộng rãi.","author":"Thành Đạt","category":"Thế giới","publishedAt":"2026-10-21 19:46","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/dac-phai-vien-my-mang-de-xuat-hoa-binh-ukraine-hoi-dam-voi-tong-thong-nga-20261021194608355.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/aL-GBg6Ko0AhvBUVgeIBamxh4S4=/zoom/1200_630/2026/10/21/putin-reuters-cropped-1792586572968.jpg","crawledAt":"2026-10-21T13:42:18.870Z"},{"id":"dtri-20261021194135596","title":"Một người trúng Vietlott hơn 31 tỷ đồng","slug":"mot-nguoi-trung-vietlott-hon-31-ty-dong","excerpt":"Một cá nhân trúng Vietlott trị giá hơn 31 tỷ đồng tối 21/10. Sau khi trừ thuế thu nhập cá nhân, chủ nhân tấm vé độc đắc thực lãnh khoảng 28 tỷ đồng.","content":"(Dân trí) - Một cá nhân trúng Vietlott trị giá hơn 31 tỷ đồng tối 21/10. Sau khi trừ thuế thu nhập cá nhân, chủ nhân tấm vé độc đắc thực lãnh khoảng 28 tỷ đồng.\n\nTối 21/10, Công ty Xổ số Điện toán Việt Nam (Vietlott) cho biết trong kỳ quay cùng ngày, sản phẩm Mega 6/45 ghi nhận một vé trúng giải trị giá hơn 31,2 tỷ đồng.\n\nTấm vé trúng độc đắc có bộ số 04-10-14-22-25-44. Giải thưởng trị giá hơn 31,2 tỷ đồng đã được tích lũy hơn 2 tuần. Thông tin về khách hàng và nơi phát hành vé trúng thưởng chưa được công bố.\n\nTheo quy định hiện hành, thu nhập từ trúng thưởng xổ số có giá trị trên 20 triệu đồng phải chịu thuế thu nhập cá nhân với thuế suất 10% đối với phần giá trị vượt mức miễn thuế. Như vậy, sau khi trừ thuế thu nhập cá nhân theo quy định, chủ nhân tấm vé trúng độc đắc thực lãnh khoảng 28 tỷ đồng.\n\nVietlott được thành lập năm 2011, do Bộ Tài chính làm chủ sở hữu với vốn điều lệ 500 tỷ đồng, là doanh nghiệp Nhà nước do cơ quan này đại diện sở hữu 100% vốn.\n\nNăm ngoái, công ty xổ số này thu 9.686 tỷ đồng, tương ứng mỗi ngày khoảng 26,5 tỷ đồng. Công ty ghi nhận 32 triệu lượt trúng xổ số với tổng giá trị trả thưởng hơn 5.340 tỷ đồng.\n\nNăm nay, công ty đặt mục tiêu tổng doanh thu đạt 10.852 tỷ đồng, tăng khoảng 12% so với năm trước và cũng là mức cao nhất kể từ khi doanh nghiệp này đi vào hoạt động. Mục tiêu này tương ứng doanh số bình quân mỗi ngày khoảng 30 tỷ đồng.\n\nTheo quy định hiện hành, Vietlott trích 55% doanh thu bán vé để lập quỹ trả thưởng. Sau khi trừ các chi phí, công ty dự kiến ghi nhận lợi nhuận trước thuế khoảng 440 tỷ đồng.","author":"Thảo Thu","category":"Kinh doanh","publishedAt":"2026-10-21 19:41","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/mot-nguoi-trung-vietlott-hon-31-ty-dong-20261021194135596.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/FdX1ZIPOozXPV1yToW3Hj10lkmU=/zoom/1200_630/2023/10/31/vietlott-crop-1698755417648.jpeg","crawledAt":"2026-10-21T13:42:52.775Z"},{"id":"dtri-20261021193633037","title":"Ngân hàng OCB có Tổng giám đốc mới","slug":"ngan-hang-ocb-co-tong-giam-doc-moi","excerpt":"Ông Dương Đức Hùng được bổ nhiệm làm Tổng Giám đốc OCB sau 5 tháng “ghế nóng” do chuyên gia người nước ngoài giữ quyền điều hành.","content":"(Dân trí) - Ông Dương Đức Hùng được bổ nhiệm làm Tổng Giám đốc OCB sau 5 tháng “ghế nóng” do chuyên gia người nước ngoài giữ quyền điều hành.\n\nNgân hàng Phương Đông (OCB) vừa công bố quyết định bổ nhiệm ông Dương Đức Hùng giữ chức vụ Tổng Giám đốc từ ngày 26/10.\n\nÔng Dương Đức Hùng có hơn 20 năm kinh nghiệm trong lĩnh vực tài chính ngân hàng, từng đảm nhiệm vai trò quản lý cấp cao tại nhiều tổ chức trong nước và quốc tế. Ông được kỳ vọng sẽ góp phần nâng cao hiệu quả hoạt động, tổ chức thực thi và triển khai chiến lược của ngân hàng.\n\nCùng với việc kiện toàn nhân sự Ban điều hành, ông Chris Shayan được bổ nhiệm vị trí Giám đốc điều hành phụ trách chuyển đổi, số hóa và phát triển kinh doanh phân khúc bán lẻ. Hồi cuối tháng 5, ông Chris Shayan, chuyên gia về công nghệ trí tuệ nhân tạo (AI) được bổ nhiệm giữ chức Quyền Tổng giám đốc của OCB.\n\nTheo ông Trịnh Văn Tuấn, Chủ tịch HĐQT OCB, việc bổ nhiệm nhân sự cấp cao đây là bước đi quan trọng nhằm củng cố năng lực điều hành cho giai đoạn phát triển tiếp theo. Ông Tuấn cho rằng, tăng trưởng không chỉ đòi hỏi một chiến lược đúng đắn, mà còn cần sự kết hợp đồng bộ giữa quản trị, công nghệ và khả năng nắm bắt cơ hội kinh doanh, qua đó mang lại giá trị thiết thực cho thị trường và khách hàng.\n\nNăm nay, OCB đặt mục tiêu lợi nhuận trước thuế 6.960 tỷ đồng, tăng 39% so với năm trước. Tăng vốn điều lệ từ 26.631 tỷ đồng lên 30.625 tỷ đồng.\n\nTính đến cuối tháng 6, ngân hàng này ghi nhận lợi nhuận trước thuế nửa đầu năm gần 2.470 tỷ đồng, tăng hơn 30% so với cùng kỳ. Tổng tài sản của OCB tính tới nửa đầu năm đạt hơn 351.700 tỷ đồng, thuộc top 20 ngân hàng có quy mô tài sản lớn nhất hệ thống.","author":"Lam Giang","category":"Kinh doanh","publishedAt":"2026-10-21 19:36","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/ngan-hang-ocb-co-tong-giam-doc-moi-20261021193633037.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/v9nvKDFs9DjY4cFDZwIEAXGU0I0=/zoom/1200_630/2026/10/21/ocb-cropped-1792586100388.jpg","crawledAt":"2026-10-21T13:42:52.757Z"},{"id":"dtri-20261021192631540","title":"Sư tử trắng quý hiếm cuối cùng ở Thảo Cầm Viên Sài Gòn qua đời","slug":"su-tu-trang-quy-hiem-cuoi-cung-o-thao-cam-vien-sai-gon-qua-doi","excerpt":"Sư tử trắng Mimi, 18 tuổi, qua đời vào chiều 21/10 sau thời gian được điều trị tích cực vì suy giảm sức khỏe do tuổi già. Đây là cá thể sư tử cuối cùng sinh sống tại Thảo Cầm Viên Sài Gòn.","content":"(Dân trí) - Sư tử trắng Mimi, 18 tuổi, qua đời vào chiều 21/10 sau thời gian được điều trị tích cực vì suy giảm sức khỏe do tuổi già. Đây là cá thể sư tử cuối cùng sinh sống tại Thảo Cầm Viên Sài Gòn.\n\nĐại diện Thảo Cầm Viên Sài Gòn cho biết khoảng hai tuần trước khi qua đời, Mimi có dấu hiệu bỏ ăn, sức khỏe suy giảm. Các bác sĩ thú y phối hợp với chuyên gia và Chi cục Thú y TPHCM tổ chức hội chẩn, xác định sư tử bị suy giảm chức năng đa cơ quan do tuổi già. Dù được điều trị và chăm sóc tích cực, Mimi vẫn không qua khỏi.\n\nMimi sinh ngày 15/12/2008, được Thảo Cầm Viên Sài Gòn tiếp nhận từ Nam Phi vào tháng 6/2010 cùng một cá thể sư tử đực.\n\nCá thể sư tử đực này qua đời vào tháng 3/2022 do tuổi già.\n\nMimi tiếp tục được chăm sóc tại đây cho đến khi qua đời, khép lại gần 16 năm gắn bó với vườn thú.\n\nTheo Thảo Cầm Viên Sài Gòn, Mimi có tính tình hiền lành, thường quấn quýt với những nhân viên trực tiếp chăm sóc, được gọi thân mật là “ba nuôi”.\n\nKhi còn khỏe, mỗi lần nghe tiếng gọi quen thuộc hoặc nhìn thấy người chăm sóc đứng trước lớp kính, Mimi thường chạy đến, chồm hai chân trước lên. Con sư tử cũng có thói quen nằm nghỉ trên chiếc sạp ở sân chơi và thường từ từ bước vào chuồng khi nghe ba nuôi gọi vào cuối ngày.\n\nMimi thích ăn thịt gà hơn thịt trâu, thịt bò. Những sở thích và thói quen này được nhân viên ghi nhận trong quá trình chăm sóc hằng ngày.\n\nTrong những ngày cuối đời, khi sức khỏe suy giảm nhanh và không còn đủ sức tự di chuyển, Mimi được đưa vào khu chuồng riêng để theo dõi, điều trị.\n\nNền chuồng được lót rơm, kết hợp sưởi đèn. Mimi cũng được massage và thường xuyên được hỗ trợ trở mình để hạn chế tình trạng tê cứng do nằm lâu. Nhân viên cũng hỗ trợ Mimi ăn uống và theo dõi thể trạng.\n\nTheo Thảo Cầm Viên Sài Gòn, dù có lúc gầm lên vì đau khi truyền dịch hoặc tiêm thuốc, Mimi vẫn nằm yên khi được người chăm sóc dỗ dành, giúp các bác sĩ tiếp tục điều trị.\n\nSự ra đi của Mimi để lại nhiều tiếc nuối cho những nhân viên đã chăm sóc trong nhiều năm. Với họ, Mimi không chỉ là một cá thể động vật được nuôi dưỡng tại vườn thú mà còn là con vật gắn bó qua nhiều năm làm việc.","author":"Mộc Khải","category":"Du lịch","publishedAt":"2026-10-21 19:26","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/su-tu-trang-quy-hiem-cuoi-cung-o-thao-cam-vien-sai-gon-qua-doi-20261021192631540.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/G6rxZh1hf9RCeVXcY9pSfuwHSNs=/zoom/1200_630/2026/10/21/85785014311275761197242235059589899697999577n-cropped-1792585217508.jpg","crawledAt":"2026-10-21T13:42:47.140Z"},{"id":"dtri-20261021192541064","title":"Thể thao Việt Nam giành HCV đầu tiên ở Asian Para Games 2026","slug":"the-thao-viet-nam-gianh-hcv-dau-tien-o-asian-para-games","excerpt":"Vận động viên Đỗ Thanh Hải mang về tấm Huy chương vàng (HCV) cho đoàn thể thao Việt Nam tại Đại hội thể thao người khuyết tật châu Á (Asian Para Games) 2026 tại Nhật Bản.","content":"(Dân trí) - Vận động viên Đỗ Thanh Hải mang về tấm Huy chương vàng (HCV) cho đoàn thể thao Việt Nam tại Đại hội thể thao người khuyết tật châu Á (Asian Para Games) 2026 tại Nhật Bản.\n\nỞ nội dung bơi 100m ếch nam hạng SB5, Đỗ Thanh Hải về nhất với thành tích 1 phút 33 giây 91, trong khi Lê Tiến Đạt cán đích thứ hai sau 1 phút 36 giây 63. Vị trí thứ ba ở nội dung này thuộc về Rashidabadi Ali (Iran) với thành tích 1 phút 47 giây 78.\n\nNhư vậy, VĐV Đỗ Thanh Hải đã mang về tấm HCV đầu tiên cho đoàn thể thao Việt Nam ở Asian Para Games 2026. Ở kỳ Đại hội trước tại Hàng Châu (Trung Quốc) vào năm 2023, Lê Tiến Đạt là người giành HCV nội dung 100m ếch nam SB5, còn Thanh Hải giành HCB. Hai VĐV Việt Nam đang thống trị nội dung này ở đấu trường châu lục.\n\nĐỗ Thanh Hải sinh năm 1990 tại Cần Thơ. Anh là tấm gương về nghị lực và ý chí vươn lên. Anh bị liệt hai chân sau cơn sốt nặng năm 3 tuổi. Đến năm 18 tuổi, Đỗ Thanh Hải bén duyên với bơi lội, tham gia tập luyện tại TPHCM. Anh miệt mài tập luyện, tận dụng sức mạnh đôi tay để bơi và nhanh chóng khẳng định tài năng.\n\nTấm HCV Asian Para Games 2026 là dấu mốc đáng chú ý đối với Thanh Hải, người từng góp mặt ở Paralympic Paris 2024. Tại giải đấu cấp độ thế giới, anh vào chung kết 100m ếch nam SB5 và đạt thành tích 1 phút 35 giây 61, xếp thứ 5.\n\nĐến nay, Đỗ Thanh Hải gặt hái rất nhiều thành công như đoạt 5 HCV, phá 4 kỷ lục ở ASEAN Para Games 11 năm 2022 tại Indonesia. Thanh Hải còn 3 lần góp mặt tại Paralympic gồm Olympic 2016 tại Brazil, Olympic Tokyo 2021 tại Nhật Bản và Olympic Paris năm 2024 tại Pháp. Sau tấm HCV danh giá ở Asian Para Games 2026, Đỗ Thanh Hải hướng đến mục tiêu giành vé tham dự Paralympic 2028 tại Mỹ.\n\nLê Tiến Đạt cũng là một trong những gương mặt giàu kinh nghiệm của đội tuyển bơi Người khuyết tật Việt Nam. Lần đầu tham dự môn bơi tại Paralympic Paris 2024, anh thi đấu xuất sắc giành vị trí thứ tư.\n\nTính đến thời điểm này, đoàn thể thao Việt Nam đã giành 1 HCV, 2 HCB, 1 HCĐ, xếp thứ 18 chung cuộc.","author":"H. Long","category":"Thể thao","publishedAt":"2026-10-21 19:25","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/the-thao-viet-nam-gianh-hcv-dau-tien-o-asian-para-games-2026-20261021192541064.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/lhBBdXctdMU8kjwPbkKYlBuUpWY=/zoom/1200_630/2026/10/21/86062390510622753768436967374857894509178945n-cropped-1792585424158.jpg","crawledAt":"2026-10-21T13:43:03.867Z"},{"id":"dtri-20261021191038112","title":"Đường Nghi Tàm, Yên Phụ nghẹt xe ngày đầu phân luồng thi công cầu Tứ Liên","slug":"duong-nghi-tam-yen-phu-nghet-xe-ngay-dau-phan-luong-thi-cong-cau-tu-lien","excerpt":"Ô tô nối hàng dài, xe máy đi ngược chiều trên đường Nghi Tàm, Yên Phụ (Hà Nội) trong ngày đầu điều chỉnh giao thông phục vụ thi công cầu Tứ Liên.","content":"Hôm nay (21/10), Sở Xây dựng Hà Nội đã chính thức triển khai điều chỉnh tổ chức giao thông tại khu vực Nghi Tàm - Âu Cơ nhằm phục vụ thi công giai đoạn 3 của dự án cầu Tứ Liên và đường dẫn hai đầu cầu, đoạn từ nút giao Nghi Tàm đến nút giao đường Trường Sa. Phương án này sẽ được áp dụng cho đến khi có thông báo mới.\n\nCụ thể, trên đường Nghi Tàm, đơn vị thi công đã dựng bổ sung hàng rào tôn cố định dọc dải phân cách giữa, kéo dài 150m từ khu vực cửa khẩu ngõ 276 Nghi Tàm đến vị trí đối diện số 187 Nghi Tàm. Phạm vi rào chắn rộng 21-22m, khiến phần mặt đường dành cho phương tiện lưu thông chỉ còn khoảng 6-7,5m.\n\nTương tự, tại đường Âu Cơ, hàng rào tôn cố định cũng được lắp đặt trên dải phân cách giữa để phục vụ thi công mố trụ và tường chắn sau mố. Khu vực thi công dài 150m, rộng 16-17m, phần đường còn lại cho các phương tiện di chuyển rộng 6-7,5m.\n\nTheo phương án phân luồng giao thông tại chỗ, hướng từ cầu Nhật Tân vào trung tâm Hà Nội, phương tiện sẽ đi theo đường Âu Cơ, sau đó chuyển vào phố Yên Phụ nhỏ để ra nút giao Thanh Niên - Yên Phụ. Ở chiều ngược lại, phương tiện đến ngõ 276 Nghi Tàm có thể đi qua lối mở tạm trên đường Nghi Tàm hoặc theo tuyến đường sát đê và đường công trường để ra đường Âu Cơ, hướng về cầu Nhật Tân.\n\nKhoảng 17h cùng ngày, dòng phương tiện đã ken đặc trên phố Yên Phụ theo hướng vào trung tâm Hà Nội. Ô tô, xe máy nối đuôi nhau di chuyển qua khu vực, mật độ phương tiện tăng cao vào giờ tan tầm, gây ra tình trạng ùn tắc kéo dài.\n\nTrong ngày đầu áp dụng phương án phân luồng, nhiều người tham gia giao thông chưa quen với lộ trình mới, dẫn đến tình trạng lúng túng, quay đầu đột ngột, khiến giao thông khu vực có thời điểm trở nên lộn xộn.\n\nÔng Văn Thu (phường Hoàn Kiếm) chia sẻ, sáng nay, ông đã mất hơn 10 phút để di chuyển quãng đường hơn 500m qua khu vực rào chắn vào giờ cao điểm. Ông Thu dự đoán tình hình giao thông sẽ tiếp tục khó khăn trong những ngày tới.\n\nĐáng chú ý, một số xe máy đã bất chấp dòng phương tiện đang lưu thông, đi ngược chiều trên đường Nghi Tàm để rút ngắn quãng đường, tiềm ẩn nguy cơ mất an toàn giao thông.\n\nTrong phố Yên Phụ nhỏ, ô tô nối đuôi thành hai hàng dài, dồn về tuyến đường này theo phương án phân luồng mới, gây áp lực lớn lên hạ tầng giao thông.\n\nGiữa dòng phương tiện ùn ứ, một số xe cứu thương cũng phải đứng chờ giữa hàng dài ô tô, xe máy, gặp khó khăn khi di chuyển qua khu vực, gây lo ngại về việc cấp cứu kịp thời.\n\nTại nút giao Thanh Niên - Yên Phụ, cơ quan chức năng đã đóng dải phân cách giữa trên đường Nghi Tàm - Yên Phụ (khu vực dưới gầm cầu vượt An Dương) và đường Thanh Niên (khu vực nút giao Phó Đức Chính), đồng thời điều chỉnh hướng lưu thông của các phương tiện. Theo đó, xe từ đường Thanh Niên và An Dương chủ yếu rẽ phải, sau đó quay đầu tại các điểm được bố trí để đi theo lộ trình mới. Phương tiện từ Yên Phụ đi Thanh Niên được hướng dẫn qua Cửa Bắc - Thụy Khuê, trong khi xe từ Yên Phụ nhỏ có thể đi thẳng về trung tâm thành phố hoặc rẽ phải vào đường Thanh Niên.\n\nSở Xây dựng Hà Nội đã yêu cầu các đơn vị liên quan bố trí đầy đủ hệ thống biển báo, lực lượng hướng dẫn giao thông, đồng thời thường xuyên theo dõi tình hình thực tế để kịp thời điều chỉnh những bất cập, bảo đảm an toàn và hạn chế ùn tắc trong thời gian thi công.\n\nRào chắn thi công trên đường Nghi Tàm, đoạn từ ngõ 276 đến đối diện số 187 Nghi Tàm, và trên đường Âu Cơ, khu vực dải phân cách giữa. Mỗi đoạn rào chắn dài khoảng 150m, khiến mặt đường còn lại rộng 6-7,5m (Ảnh: Google Maps).","author":"Hướng Dương","category":"Thời sự","publishedAt":"2026-10-21 19:10","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/duong-nghi-tam-yen-phu-nghet-xe-ngay-dau-phan-luong-thi-cong-cau-tu-lien-20261021191038112.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/XOoIFcB7uelu9UKiTYHwql7wqzs=/zoom/1200_630/2026/10/21/rao-chan-duong-au-co-nghi-tamthanh-dong-30-cropped-1792584497226.jpg","crawledAt":"2026-10-21T13:42:25.478Z"},{"id":"dtri-20261021190130103","title":"Houthi tuyên bố đánh trúng sở chỉ huy tác chiến của đối phương","slug":"houthi-tuyen-bo-danh-trung-so-chi-huy-tac-chien-cua-doi-phuong","excerpt":"Nhóm vũ trang Houthi tại Yemen tuyên bố đã đánh trúng sở chỉ huy tác chiến của lực lượng do Ả rập Xê út hậu thuẫn tại Aden trong cuộc tấn công ngày 21/10.","content":"(Dân trí) - Nhóm vũ trang Houthi tại Yemen tuyên bố đã đánh trúng sở chỉ huy tác chiến của lực lượng do Ả rập Xê út hậu thuẫn tại Aden trong cuộc tấn công ngày 21/10.\n\nTheo các nguồn tin, khói bốc lên gần một sân bay quan trọng, đánh dấu vụ tấn công thứ ba chỉ trong vòng một tuần nhắm vào nơi đặt căn cứ của lực lượng chính phủ Yemen vốn được Riyadh hậu thuẫn.\n\n\"Các lực lượng vũ trang của chúng tôi đã nhắm mục tiêu vào phòng điều hành của đối thủ Ả rập Xê út tại căn cứ Badr ở Aden bằng tên lửa đạn đạo\", người phát ngôn quân sự của Houthi, ông Yahya Saree, cho biết trong một tuyên bố.\n\nMột quan chức cảnh sát tại Aden cho biết trước đó đã xảy ra một vụ nổ \"do tên lửa của Houthi gây ra\".\n\nHai nguồn tin an ninh khác tại thành phố này chia sẻ rằng, cuộc tấn công nhắm vào một địa điểm gần sân bay, nơi thuộc quyền kiểm soát của các lực lượng thuộc liên minh quân sự do Ả rập Xê út dẫn đầu. Đây là liên minh đang giao tranh với Houthi.\n\nẢ rập Xê út và lực lượng chính phủ Yemen gần đây liên tục trở thành mục tiêu tấn công của Houthi.\n\nDiễn biến này làm thay đổi trọng tâm của cuộc xung đột rộng lớn hơn tại Trung Đông, vốn đã bùng phát sau các cuộc tấn công của Mỹ và Israel nhắm vào Iran từ ngày 28/2.\n\nTrước đó, hôm 16/10, 2 tên lửa đã rơi xuống khu vực sân bay và phía Houthi đã lên tiếng nhận trách nhiệm về vụ tấn công này.\n\nMột ngày trước đó, Houthi tiến hành một vụ tấn công bằng tên lửa gây thương vong tại dinh tổng thống ở Aden, đánh trúng các trung tâm chỉ huy bên trong khuôn viên Dinh Tổng thống Al-Maashiq, nơi được các lực lượng chính phủ và liên minh do Ả rập Xê út dẫn đầu sử dụng.\n\nTrong khi đó, đài truyền hình Al-Jumhuriya đưa tin về các cuộc giao tranh dữ dội mới giữa lực lượng vũ trang Yemen và các tay súng Houthi tại khu vực sân bay cũ và xung quanh núi Han, phía tây thành phố Taiz.\n\nNhững diễn biến này xảy ra trong bối cảnh chính phủ Yemen đang tiến hành chiến dịch quân sự chống lại Houthi ở phía tây nam đất nước.\n\nHôm 20/10, quân đội Yemen cho biết đã tiến hành 744 đợt tấn công nhắm vào Houthi trong vòng 24 giờ, loại khỏi vòng chiến đấu khoảng 200 thành viên Houthi, đồng thời phá hủy hoặc làm hư hại 90 phương tiện và các khí tài quân sự khác.\n\nHồi tháng 7, thỏa thuận ngừng bắn mong manh đạt được năm 2022 đã sụp đổ sau khi Houthi cho phép một máy bay Iran hạ cánh xuống thủ đô Sanaa của Yemen - hành động thách thức quyền kiểm soát của Riyadh đối với không phận Yemen.\n\nĐộng thái này châm ngòi cho một loạt các cuộc tấn công mới. Sau đó, lực lượng Houthi tuyên bố phong tỏa hàng hải đối với Ả rập Xê út, đồng thời bắt đầu tấn công các tàu thuyền, lãnh thổ và cơ sở dầu mỏ của nước này.\n\nTiếp đó, họ thực hiện một chiến dịch chớp nhoáng nhằm chiếm giữ các vùng lãnh thổ do chính phủ Yemen kiểm soát dọc theo bờ biển Đỏ.\n\nĐể đáp trả, không quân Ả rập Xê út đã liên tục nhắm mục tiêu vào lực lượng Houthi nhằm hỗ trợ chính phủ Yemen.","author":"Thanh Thành","category":"Thế giới","publishedAt":"2026-10-21 19:01","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/houthi-tuyen-bo-danh-trung-so-chi-huy-tac-chien-cua-doi-phuong-20261021190130103.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/5qGEynYYUrq31uN9CeYeQVnCaNo=/zoom/1200_630/2026/10/21/unnamed-cropped-1792583922709.jpg","crawledAt":"2026-10-21T13:42:18.937Z"},{"id":"dtri-20261021185935739","title":"Đã quy tập 800 bộ hài cốt liệt sĩ ở Công viên Lê Thị Riêng","slug":"da-quy-tap-800-bo-hai-cot-liet-si-o-cong-vien-le-thi-rieng","excerpt":"Lực lượng chức năng đã quy tập được 800 bộ hài cốt liệt sĩ ở Công viên Lê Thị Riêng sau gần 4 tháng triển khai tìm kiếm ở khu vực này.","content":"(Dân trí) - Lực lượng chức năng đã quy tập được 800 bộ hài cốt liệt sĩ ở Công viên Lê Thị Riêng sau gần 4 tháng triển khai tìm kiếm ở khu vực này.\n\nTối 21/10, Bộ Tư lệnh TPHCM công bố số liệu tìm kiếm hài cốt liệt sĩ ở Công viên Lê Thị Riêng. Lực lượng chức năng đã tìm thấy thêm 11 bộ hài cốt liệt sĩ cùng 2 bộ di vật kèm theo tại khu B.\n\nCùng ngày, lực lượng chức năng đã xử lý hơn 620m3 đất, huy động trang thiết bị để đào, vận chuyển đất, mở rộng phạm vi tìm kiếm tại khu B.\n\nCông tác tìm kiếm, quy tập hài cốt liệt sĩ đang được Bộ Tư lệnh TPHCM triển khai với tinh thần trách nhiệm cao, thể hiện sự tri ân sâu sắc đối với các anh hùng liệt sĩ đã hy sinh vì sự nghiệp đấu tranh giải phóng dân tộc, xây dựng và bảo vệ Tổ quốc.\n\nViệc tìm kiếm, quy tập hài cốt liệt sĩ tại Công viên Lê Thị Riêng đã bước sang ngày thứ 7 của đợt 2. Trước đó, trong đợt 1, lực lượng chức năng đã quy tập được 731 hài cốt liệt sĩ và tổ chức Lễ truy điệu, an táng theo quy định.\n\nTính lũy kế đợt 2, đã có 69 bộ hài cốt liệt sĩ được tìm thấy, nâng tổng số hài cốt được phát hiện tại Công viên Lê Thị Riêng lên 800 bộ.\n\nCông tác tìm kiếm, quy tập hài cốt liệt sĩ tại Công viên Lê Thị Riêng được thực hiện theo kết luận của Phó Thủ tướng Phạm Thị Thanh Trà tại hội thảo xác minh thông tin mộ tập thể liệt sĩ ở khu vực Nghĩa trang Đô Thành - Chí Hòa (nay là Công viên Lê Thị Riêng).","author":"Lê Trai","category":"Nội vụ","publishedAt":"2026-10-21 18:59","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/da-quy-tap-800-bo-hai-cot-liet-si-o-cong-vien-le-thi-rieng-20261021185935739.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/h4TIQVeR6G_X_pV_8IUn89RjgBs=/zoom/1200_630/2026/10/21/1792582993073758951782719242216475895178271924221643a5bc560349a2325a6eb29d8fc6c9342-cropped-1792583880276.jpg","crawledAt":"2026-10-21T13:43:33.421Z"},{"id":"dtri-20261021185451926","title":"Chủ tịch Đắk Lắk: Gắn KPI người đứng đầu với khen thưởng, kỷ luật rõ ràng","slug":"chu-tich-dak-lak-gan-kpi-nguoi-dung-dau-voi-khen-thuong-ky-luat-ro-rang","excerpt":"Để hoàn thành các mục tiêu tăng trưởng trong 3 tháng cuối năm, Chủ tịch UBND tỉnh Đắk Lắk yêu cầu lãnh đạo sở, ngành, địa phương đăng ký KPI và sẽ xem xét điều chuyển người đứng đầu không hoàn thành.","content":"(Dân trí) - Để hoàn thành các mục tiêu tăng trưởng trong 3 tháng cuối năm, Chủ tịch UBND tỉnh Đắk Lắk yêu cầu lãnh đạo sở, ngành, địa phương đăng ký KPI và sẽ xem xét điều chuyển người đứng đầu không hoàn thành.\n\nChiều 21/10, UBND tỉnh Đắk Lắk tổ chức hội nghị quán triệt kịch bản tăng trưởng quý IV/2026, gắn với danh mục sản phẩm, công việc và chỉ số đánh giá hiệu quả thực hiện nhiệm vụ (KPI) của lãnh đạo UBND tỉnh, các sở, ngành và lãnh đạo 102 xã, phường.\n\nTheo kịch bản đề ra, trong 3 tháng cuối năm 2026, Đắk Lắk đặt mục tiêu tăng trưởng GRDP (tổng sản phẩm trên địa bàn) đạt 13,63%; tổng vốn đầu tư đạt 34.586 tỷ đồng; thu ngân sách 7.254 tỷ đồng; doanh thu du lịch 3.390 tỷ đồng và kim ngạch xuất khẩu 765 triệu USD.\n\nĐể hiện thực hóa các mục tiêu này, hội nghị đã thảo luận, thống nhất danh mục đăng ký KPI quý IV của lãnh đạo UBND tỉnh, thủ trưởng các sở, ban, ngành và chủ tịch UBND các xã, phường. Đồng thời, các đơn vị thống nhất cơ chế theo dõi, cập nhật, báo cáo và đánh giá kết quả thực hiện, bảo đảm việc giao nhiệm vụ đi đôi với kiểm tra, giám sát.\n\nÔng Trương Ngọc Tuấn, Giám đốc Sở Nội vụ Đắk Lắk, cho biết người đứng đầu các cơ quan, đơn vị phải chịu trách nhiệm về nội dung đăng ký KPI. Các sở được phân công phụ trách sẽ xác định mức giao, kiểm chứng số liệu và Sở Nội vụ tổng hợp hồ sơ đăng ký, chuyển Văn phòng UBND tỉnh thực hiện các bước tiếp theo.\n\nTheo ông Tuấn, KPI không chỉ là những con số đăng ký mà phải phản ánh kết quả thực chất, có thể đo lường, kiểm tra và kèm theo tài liệu minh chứng. \"Những đơn vị đăng ký KPI thấp hoặc thiếu phải tự chịu trách nhiệm\", Giám đốc Sở Nội vụ Đắk Lắk cho hay.\n\nPhát biểu chỉ đạo tại hội nghị, ông Đỗ Hữu Huy, Chủ tịch UBND tỉnh Đắk Lắk, yêu cầu việc đánh giá KPI phải gắn chặt với nhiệm vụ chính trị của từng cơ quan, đơn vị và trách nhiệm của người đứng đầu. Các sở, ngành, địa phương cần thường xuyên cập nhật kịch bản tăng trưởng theo tuần, theo tháng, tập trung cao độ cho những nhiệm vụ trọng tâm trong quý cuối năm.\n\nChủ tịch UBND tỉnh quán triệt nguyên tắc thực hiện nhiệm vụ phải bảo đảm \"rõ người, rõ việc, rõ sản phẩm, rõ thời hạn\" và mỗi chỉ tiêu chỉ có một người chịu trách nhiệm chính. \"Gắn KPI với người đứng đầu có khen thưởng, kỷ luật rõ ràng\", ông Huy chỉ đạo.\n\nCác chỉ số KPI sẽ được xây dựng trên cơ sở những nhiệm vụ trọng tâm như tăng trưởng của từng ngành, khả năng huy động vốn, giải ngân vốn đầu tư và tạo nguồn thu. Đối với các xã, phường, tỉnh yêu cầu bổ sung những chỉ tiêu liên quan đến giải ngân nguồn vốn tăng thu, tiết kiệm chi; giải ngân vốn các Chương trình mục tiêu quốc gia và công tác quy hoạch xã, phường.\n\nĐể bảo đảm tiến độ, các Phó Chủ tịch UBND tỉnh phụ trách từng lĩnh vực được giao trực tiếp chỉ đạo, đôn đốc các cơ quan, đơn vị triển khai nhiệm vụ, bám sát kịch bản tăng trưởng đã đề ra.\n\nÔng Đỗ Hữu Huy khẳng định sẽ xem xét điều chuyển công tác đối với người đứng đầu không hoàn thành nhiệm vụ. Theo yêu cầu của lãnh đạo tỉnh Đắk Lắk, các cơ quan, đơn vị phải hoàn thiện kịch bản chi tiết, danh mục nhiệm vụ, đăng ký KPI trước ngày 26/10 và các địa phương hoàn thành đăng ký KPI trước ngày 27/10.","author":"Thúy Diễm","category":"Nội vụ","publishedAt":"2026-10-21 18:54","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/chu-tich-dak-lak-gan-kpi-nguoi-dung-dau-voi-khen-thuong-ky-luat-ro-rang-20261021185451926.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/k6m7JBj_NotoJeRQs_EBaSQ8y_k=/zoom/1200_630/2026/10/21/chu-tich-dak-lakthuy-diem-edited-cropped-cropped-1792583593230.jpg?watermark=v1","crawledAt":"2026-10-21T13:43:32.364Z"},{"id":"dtri-20261021185029135","title":"Thành ủy TPHCM điều động nhiều cán bộ về cơ sở","slug":"thanh-uy-tphcm-dieu-dong-nhieu-can-bo-ve-co-so","excerpt":"Thành ủy TPHCM công bố quyết định điều động, phân công 4 cán bộ đến công tác tại các đơn vị, địa phương, nhằm đáp ứng yêu cầu nhiệm vụ trong giai đoạn mới.","content":"(Dân trí) - Thành ủy TPHCM công bố quyết định điều động, phân công 4 cán bộ đến công tác tại các đơn vị, địa phương, nhằm đáp ứng yêu cầu nhiệm vụ trong giai đoạn mới.\n\nChiều 21/10, Phó Bí thư Thành ủy TPHCM Văn Thị Bạch Tuyết chủ trì lễ trao quyết định về công tác cán bộ.\n\nTại hội nghị, ông Phạm Thành Chung, Phó trưởng Ban Tổ chức Thành ủy TPHCM, công bố quyết định điều động bà Trần Minh Xuân, Phó trưởng Ban Nội chính Thành ủy, về Văn phòng Thành ủy và phân công công tác tại Ban Nghiên cứu phát triển TPHCM.\n\nBan Thường vụ Thành ủy TPHCM cũng chỉ định ông Nguyễn Ngọc Văn, Phó Giám đốc Ban Quản lý Dự án đầu tư xây dựng các công trình dân dụng và công nghiệp TPHCM, tham gia Ban Chấp hành Đảng bộ, Ban Thường vụ Đảng ủy, giữ chức Phó Bí thư Đảng ủy phường Bến Thành nhiệm kỳ 2025-2030.\n\nBan Thường vụ Thành ủy TPHCM tiếp nhận, điều động bà Mai Thị Hồng Hoa, Phó Bí thư Đảng ủy, Chủ tịch UBND phường Bến Thành, đến công tác tại Cơ quan Ủy ban MTTQ Việt Nam TPHCM để giới thiệu bầu giữ chức Phó Chủ tịch Hội Liên hiệp Phụ nữ TPHCM.\n\nĐồng thời, Ban Thường vụ Thành ủy TPHCM quyết định tiếp nhận, điều động và chỉ định ông Lê Văn Thinh, Phó Trưởng Ban Quản lý các khu chế xuất và công nghiệp TPHCM, tham gia Ban Chấp hành Đảng bộ, Ban Thường vụ Đảng ủy, giữ chức Bí thư Đảng ủy phường An Lạc nhiệm kỳ 2025-2030.\n\nPhát biểu giao nhiệm vụ, Phó Bí thư Thành ủy TPHCM Văn Thị Bạch Tuyết cho biết, 4 cán bộ được trao quyết định đợt này đều có quá trình công tác lâu dài, nhiều kinh nghiệm trong quản lý, điều hành và hoàn thành tốt nhiệm vụ được giao ở các vị trí công tác trước đây.\n\nĐối với 2 nhân sự được phân công về công tác tại phường, lãnh đạo Thành ủy TPHCM đề nghị các cán bộ nhanh chóng tiếp cận công việc, nắm bắt tình hình thực tế, phối hợp với thường trực cấp ủy lãnh đạo địa phương hoàn thành nhiệm vụ, chỉ tiêu công tác năm 2026.\n\nPhó Bí thư Thành ủy TPHCM cho biết, việc sắp xếp, bố trí cán bộ gắn với thực hiện chủ trương của Đảng, nhằm đào tạo, bồi dưỡng, giúp cán bộ có cơ hội tiếp cận nhiều lĩnh vực công tác khác nhau, từng bước hoàn thiện năng lực, đáp ứng yêu cầu, nhiệm vụ trong giai đoạn mới.","author":"Q.Huy","category":"Thời sự","publishedAt":"2026-10-21 18:50","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/thanh-uy-tphcm-dieu-dong-nhieu-can-bo-ve-co-so-20261021185029135.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/7sWWSNxKURQb1Ql2W3qi0g9VtJs=/zoom/1200_630/2026/10/21/2aobor723mlc6xo388qmmvpfo06ttrp3blimrjey-6392-4092-cropped-1792583366438.jpg","crawledAt":"2026-10-21T13:42:26.662Z"},{"id":"dtri-20261021184823933","title":"10 doanh nghiệp IPO huy động 60.900 tỷ đồng trong 10 tháng","slug":"10-doanh-nghiep-ipo-huy-dong-60900-ty-dong-trong-10-thang","excerpt":"Từ cuối năm 2025 đến tháng 10/2026, 10 doanh nghiệp IPO huy động được 60.900 tỷ đồng, gấp hơn 9 lần tổng vốn của 16 thương vụ trong giai đoạn 2021-2024.","content":"(Dân trí) - Từ cuối năm 2025 đến tháng 10/2026, 10 doanh nghiệp IPO huy động được 60.900 tỷ đồng, gấp hơn 9 lần tổng vốn của 16 thương vụ trong giai đoạn 2021-2024.\n\nTại tọa đàm “Từ IPO đến giá trị dài hạn” chiều 21/10, bà Lê Thị Việt Nga, Phó Chủ tịch Ủy ban Chứng khoán Nhà nước, cho biết thị trường chứng khoán ngày càng thể hiện rõ vai trò cung ứng vốn trung và dài hạn cho nền kinh tế, đáp ứng nhu cầu mở rộng sản xuất, đổi mới công nghệ và chuyển đổi số.\n\nTheo số liệu bà Nga trình bày, tổng giá trị huy động qua thị trường chứng khoán và thị trường trái phiếu doanh nghiệp riêng lẻ tăng từ khoảng 413.000 tỷ đồng năm 2023 lên 550.000 tỷ đồng năm 2024 và 764.000 tỷ đồng năm 2025. Riêng 9 tháng đầu năm nay, con số này đạt 564.000 tỷ đồng.\n\nHoạt động IPO (chào bán cổ phiếu lần đầu ra công chúng) cũng thay đổi đáng kể về quy mô. Giai đoạn 2021-2024, có 16 doanh nghiệp IPO, huy động tổng cộng 6.500 tỷ đồng. Từ cuối năm 2025 đến tháng 10/2026, dù chỉ có 10 doanh nghiệp chào bán, số vốn huy động đạt 60.900 tỷ đồng, gấp hơn 9 lần cả giai đoạn trước. Trong số này, 7 doanh nghiệp đã niêm yết, còn 3 đơn vị đang hoàn tất thủ tục.\n\nBà Nga cho biết những điều chỉnh pháp luật theo hướng gắn IPO với niêm yết đã góp phần rút ngắn thời gian từ chào bán đến niêm yết, từ 90 ngày xuống 30 ngày. Việc này vừa bổ sung nguồn cung cho thị trường, vừa mở rộng khả năng huy động vốn của doanh nghiệp.\n\nTuy nhiên, theo Phó Chủ tịch Ủy ban Chứng khoán Nhà nước, phát triển IPO cần hướng tới giá trị bền vững. “Phát triển thị trường IPO không chỉ là tăng số lượng doanh nghiệp chào bán hay quy mô hoạt động, mà quan trọng hơn là nâng cao chất lượng doanh nghiệp, tính minh bạch và hiệu quả sử dụng nguồn vốn huy động từ công chúng”, bà nhấn mạnh.\n\n4 yếu tố quyết định thành công của một thương vụ IPO\n\nÔng Bùi Thế Anh, Giám đốc EY-Parthenon - Chiến lược và Thực thi, Công ty CP Tư vấn EY Việt Nam (EY Consulting VN), cho rằng một thương vụ IPO thành công cần được đánh giá trên bốn yếu tố.\n\nThứ nhất, tiếp cận đúng nhóm nhà đầu tư. Theo ông Thế Anh, khi tư vấn cho doanh nghiệp, EY nhận thấy năng lực của nhà đầu tư khi tham gia hội đồng quản trị hoặc trở thành thành viên trong câu lạc bộ cổ đông của doanh nghiệp là yếu tố rất quan trọng.\n\nThứ hai, tạo ra sự chuyển đổi thực chất về mô hình quản trị. Theo đó, thương vụ IPO thành công phải tạo ra sự chuyển dịch thực chất trong doanh nghiệp, đặc biệt là mô hình quản trị và cách thức quản lý, vận hành bên trong.\n\nThứ ba, bảo đảm tính bền vững của nguồn vốn huy động. Ông Thế Anh đánh giá việc phát triển thị trường vốn để cung cấp nguồn vốn dài hạn cho doanh nghiệp là vấn đề rất kịp thời trong bối cảnh hiện nay. Theo ông, nguồn vốn dài hạn trên thị trường đang thiếu, trong khi hạn mức tín dụng của nhiều ngân hàng và ngành nghề đã gần cạn.\n\nTrong bối cảnh đó, dòng vốn dài hạn huy động qua IPO có thể giúp doanh nghiệp giảm áp lực trả nợ. Đồng thời, nguồn vốn này tạo cơ hội để doanh nghiệp điều chỉnh, cơ cấu lại các dòng vốn, từng bước chuyển từ tình trạng phụ thuộc nhiều vào vốn ngắn hạn sang sử dụng nguồn vốn dài hạn hơn. Qua đó, doanh nghiệp có thêm điều kiện giảm áp lực tài chính và chủ động hơn trong việc bố trí nguồn vốn phục vụ hoạt động kinh doanh.\n\nThứ tư, duy trì niềm tin đối với những cam kết khi IPO. Theo ông Thế Anh, thành công thực sự của một thương vụ IPO còn nằm ở việc doanh nghiệp có duy trì được niềm tin của công chúng đầu tư đối với những cam kết đã đưa ra hay không. Khi IPO, doanh nghiệp thường công bố kế hoạch kinh doanh và các mục tiêu tăng trưởng với công chúng.\n\nMở rộng kênh huy động vốn, thúc đẩy doanh nghiệp niêm yết\n\nĐể phát triển thị trường ổn định, an toàn, lành mạnh, hiệu quả, bền vững và hội nhập, bà Lê Thị Việt Nga cho biết cơ quan quản lý định hướng mở rộng khả năng tiếp cận vốn cho doanh nghiệp tăng trưởng, đổi mới sáng tạo; thúc đẩy chào bán cổ phiếu, trái phiếu ra công chúng gắn với niêm yết; đa dạng sản phẩm phù hợp nhu cầu vốn dài hạn và khẩu vị rủi ro của nhà đầu tư tổ chức; thu hút dòng vốn dài hạn trong và ngoài nước.\n\nCác định hướng này được triển khai qua 6 nhóm giải pháp: hoàn thiện pháp luật, tăng độ mở thị trường, đa dạng hàng hóa, phát triển cơ sở nhà đầu tư, hiện đại hóa hạ tầng và tăng cường giám sát.\n\nỞ phía doanh nghiệp, bà Nga đề nghị chuẩn hóa quản trị theo thông lệ quốc tế, nâng cao vai trò thành viên hội đồng quản trị độc lập, kiểm soát nội bộ và quản trị rủi ro. Thông tin tài chính, phi tài chính và các yếu tố môi trường, xã hội, quản trị (ESG) cần được công bố đầy đủ, kịp thời, chính xác.\n\n“Minh bạch không còn là một sự lựa chọn mà nó là một yêu cầu bắt buộc tuân thủ theo quy định của pháp luật”, bà Nga nói.","author":"Thảo Thu","category":"Kinh doanh","publishedAt":"2026-10-21 18:48","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/10-doanh-nghiep-ipo-huy-dong-60900-ty-dong-trong-10-thang-20261021184823933.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/uP3lf3Xme9l1_9gp_8eCJzHmBWw=/zoom/1200_630/2026/10/21/2aobor72iolc0sdi85tmbpmglcnimfx0bvbipcr2-cropped-1792583192197.jpg","crawledAt":"2026-10-21T13:42:53.837Z"},{"id":"dtri-20261021183626222","title":"Nga thả cựu quân nhân Mỹ, ông Trump ca ngợi hành động chưa từng có tiền lệ","slug":"nga-tha-cuu-quan-nhan-my-ong-trump-ca-ngoi-hanh-dong-chua-tung-co-tien-le","excerpt":"Nga trả tự do cho cựu quân nhân Mỹ Stephen Hubbard, người từng bị kết án gần 7 năm tù tại Nga với cáo buộc làm lính đánh thuê bên phía Ukraine.","content":"(Dân trí) - Nga trả tự do cho cựu quân nhân Mỹ Stephen Hubbard, người từng bị kết án gần 7 năm tù tại Nga với cáo buộc làm lính đánh thuê bên phía Ukraine.\n\nTrong cuộc hội đàm với Tổng thống Nga Vladimir Putin tại Cung điện Constantine ở St. Petersburg hôm nay 21/10, Đặc phái viên của Tổng thống Mỹ Donald Trump, ông Steve Witkoff, đã gửi lời cảm ơn tới Tổng thống Putin vì đã trả tự do cho cựu quân nhân Không quân Mỹ Stephen Hubbard - người từng bị kết án tại Nga với cáo buộc chiến đấu cho Ukraine.\n\nĐặc phái viên Witkoff đã bày tỏ sự cảm kích với Nga thay mặt cho Tổng thống Trump và người dân Mỹ. Ông Witkoff cho biết trước đó vài ngày đã gặp con trai của ông Hubbard để trao đổi về việc ông bị giam giữ.\n\nTổng thống Putin xác nhận ông Hubbard đã có mặt tại sân bay Pulkovo ở St. Petersburg và đang chuẩn bị rời khỏi Nga.\n\nNgười phát ngôn Điện Kremlin, ông Dmitry Peskov, sau đó xác nhận quyết định trả tự do cho ông Hubbard được đưa ra dựa trên “cơ sở nhân đạo”, đồng thời cho biết Moscow và Washington vẫn duy trì liên lạc về vấn đề trao đổi tù nhân.\n\nTrên mạng xã hội Truth Social, ông Trump xác nhận việc Nga trả tự do cho ông Hubbard, đồng thời nhấn mạnh phía Mỹ “không phải trao đổi bất cứ điều gì” để có được sự tự do của ông Hubbard. Tổng thống Trump gọi đây là trường hợp “chưa từng có tiền lệ đối với Nga”.\n\n“Việc đưa công dân này trở về lẽ ra phải được thực hiện từ lâu dưới thời chính quyền (Tổng thống Joe) Biden, nhưng chính quyền (ông Biden) đã không đạt được kết quả gì trong các cuộc đàm phán với Điện Kremlin”, ông Trump nêu rõ.\n\nÔng Hubbard, 74 tuổi, là một giáo viên đã nghỉ hưu từ bang Michigan và là cựu quân nhân Không quân Mỹ. Ông bị lực lượng Nga bắt giữ tại thành phố Izyum của Ukraine vào tháng 4/2022, ngay sau khi Moscow bắt đầu chiến dịch quân sự tại Ukraine.\n\nÔng Hubbard đã sống tại Ukraine cùng bạn đời người bản địa từ năm 2014 - thời điểm xung đột tại vùng Donbass, miền Đông bùng phát.\n\nNăm 2024, một tòa án Nga đã tuyên phạt ông 6 năm 10 tháng tù với cáo buộc làm lính đánh thuê, do tham gia một đơn vị phòng vệ lãnh thổ của Ukraine và chiến đấu cho Kiev với mức thù lao 1.000 USD mỗi tháng.\n\nEm gái của ông Hubbard khẳng định rằng ông là người có quan điểm ủng hộ Nga, theo chủ nghĩa hòa bình và không phải là người có khuynh hướng quân sự, nên rất khó có khả năng ông cầm vũ khí chiến đấu.\n\nTổng thống Trump ngày 20/10 cho biết chính ông đã trực tiếp đề nghị Tổng thống Putin trả tự do cho ông Hubbard.\n\nViệc ông Hubbard được trả tự do diễn ra sau quyết định đơn phương của Moscow vào tháng 8 nhằm phóng thích cựu lính thủy đánh bộ Mỹ Robert Gilman - người từng bị bắt giữ đầu năm 2022 vì hành vi tấn công một sĩ quan cảnh sát trong tình trạng say xỉn khi đang đi tàu qua Nga.\n\nKhi đó, ông Trump cho biết Tổng thống Putin đã ân xá cho Gilman vì lý do nhân đạo, đồng thời khẳng định không có bất kỳ cuộc trao đổi tù nhân nào diễn ra.\n\nVào tháng 4/2025, Moscow và Washington đã thực hiện một cuộc trao đổi tù nhân: Nga trả tự do cho Ksenia Karelina - một công dân mang hai quốc tịch Mỹ và Nga, từng bị bỏ tù vì quyên góp cho một tổ chức từ thiện hỗ trợ quân đội Ukraine - trong khi Washington trả tự do cho Arthur Petrov, một công dân mang hai quốc tịch Đức và Nga, bị bắt vì cáo buộc xuất khẩu các linh kiện điện tử nhạy cảm.","author":"Thành Đạt","category":"Thế giới","publishedAt":"2026-10-21 18:36","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/nga-tha-cuu-quan-nhan-my-ong-trump-ca-ngoi-hanh-dong-chua-tung-co-tien-le-20261021183626222.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/SMH-gNIWFNIyg3TrIfLVYdCnEQk=/zoom/1200_630/2026/10/21/nga-tha-cuu-quan-nhan-my-ong-trump-ca-ngoi-hanh-dong-chua-tung-co-tien-le-cropped-1792582502273.jpg","crawledAt":"2026-10-21T13:42:20.037Z"},{"id":"dtri-20261021181438002","title":"Thủ tướng yêu cầu khắc phục triệt để tình trạng mua bán xăng dầu lòng vòng, giảm chi phí lưu thông","slug":"thu-tuong-yeu-cau-khac-phuc-triet-de-tinh-trang-mua-ban-xang-dau-long-vong-giam-chi-phi-luu-thong","excerpt":"Lãnh đạo Chính phủ yêu cầu Bộ Công Thương hoàn thiện dự thảo nghị định kinh doanh xăng dầu trước 10/11, trong đó giảm khâu trung gian, tái cơ cấu thương nhân đầu mối và đổi mới cơ chế điều hành giá.","content":"(Dân trí) - Lãnh đạo Chính phủ yêu cầu Bộ Công Thương hoàn thiện dự thảo nghị định kinh doanh xăng dầu trước 10/11, trong đó giảm khâu trung gian, tái cơ cấu thương nhân đầu mối và đổi mới cơ chế điều hành giá.\n\nVăn phòng Chính phủ vừa có văn bản truyền đạt chỉ đạo của Thủ tướng về việc hoàn thiện dự thảo Nghị định thay thế Nghị định 83/2014/NĐ-CP về kinh doanh xăng dầu và các nghị định sửa đổi, bổ sung.\n\nTheo đó, Bộ Công Thương được giao chủ trì, phối hợp với các Bộ Tài chính, Tư pháp, Xây dựng, Công an, Thanh tra Chính phủ và các cơ quan liên quan khẩn trương rà soát, hoàn thiện dự thảo, bảo đảm thực hiện đầy đủ, thực chất chỉ đạo của Thủ tướng.\n\nMột trong những yêu cầu trọng tâm là tái cơ cấu, giảm số lượng thương nhân đầu mối kinh doanh xăng dầu, nâng cao năng lực tạo nguồn, dự trữ và trách nhiệm bảo đảm nguồn cung. Việc thực hiện cần có lộ trình phù hợp, khả thi, không gây xáo trộn thị trường.\n\nThủ tướng cũng yêu cầu cắt giảm tối đa các khâu trung gian không cần thiết, khắc phục tình trạng mua bán xăng dầu lòng vòng nhằm giảm chi phí lưu thông, hướng tới hệ thống phân phối tinh gọn, minh bạch và hiệu quả.\n\nVề điều hành giá, cơ chế mới phải vận hành theo nguyên tắc thị trường có sự quản lý của Nhà nước. Nhà nước cần kiểm soát, giám sát được các yếu tố hình thành giá và giá bán xăng dầu, đồng thời có đầy đủ công cụ điều tiết, bình ổn giá, ngăn chặn tình trạng đầu cơ, thao túng và tăng giá bất hợp lý.\n\nBộ Công Thương cũng phải phối hợp chặt chẽ với Bộ Công an, Thanh tra Chính phủ rà soát, khắc phục những bất cập, sơ hở trong cơ chế, chính sách kinh doanh xăng dầu đã được chỉ ra qua hoạt động thanh tra, không để các tổ chức, cá nhân lợi dụng chính sách để trục lợi, gây thất thoát, lãng phí.\n\nThủ tướng yêu cầu Bộ Công Thương khẩn trương lấy ý kiến các bộ, cơ quan liên quan đối với dự thảo nghị định và các kiến nghị tại tờ trình ngày 8/10. Bộ này có trách nhiệm tiếp thu, giải trình đầy đủ, hoàn thiện hồ sơ và trình Chính phủ chậm nhất trước ngày 10/11.\n\nBộ trưởng Công Thương chịu trách nhiệm trước Chính phủ, Thủ tướng về chất lượng và tiến độ thực hiện.\n\nSong song với việc hoàn thiện chính sách, Bộ Công Thương phải chủ động xây dựng, triển khai các phương án bảo đảm nguồn cung xăng dầu trong mọi tình huống, tuyệt đối không để xảy ra thiếu hụt, đứt gãy nguồn cung.\n\nNguồn cung phải đáp ứng đầy đủ, kịp thời nhu cầu sản xuất, kinh doanh và tiêu dùng của người dân, doanh nghiệp, phục vụ phát triển kinh tế - xã hội và bảo đảm an ninh năng lượng quốc gia.\n\nTheo Bộ Công Thương, việc xây dựng nghị định mới nhằm hoàn thiện khung pháp lý về kinh doanh xăng dầu, bảo đảm an ninh năng lượng và tạo lập thị trường vận hành theo cơ chế thị trường có sự quản lý của Nhà nước. Dự thảo kế thừa các quy định còn phù hợp, đồng thời sửa đổi, bổ sung những nội dung đã bộc lộ bất cập trong thực tiễn.\n\nĐáng chú ý, dự thảo đề xuất đổi mới cơ chế điều hành giá theo hướng tăng quyền chủ động cho doanh nghiệp, đồng thời tăng cường trách nhiệm và giám sát của cơ quan quản lý.\n\nTheo phương án được Bộ Công Thương đề xuất, Nhà nước sẽ không công bố giá cơ sở định kỳ như hiện nay. Thương nhân đầu mối và thương nhân phân phối được tự quyết định, công bố giá bán lẻ trong hệ thống phân phối của mình trên cơ sở công thức giá quy định tại nghị định. Sau khi điều chỉnh giá, thương nhân có trách nhiệm kê khai giá và gửi thông báo đến cơ quan quản lý để phục vụ công tác kiểm tra, giám sát.","author":"Thanh Thương","category":"Kinh doanh","publishedAt":"2026-10-21 18:14","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/thu-tuong-yeu-cau-khac-phuc-triet-de-tinh-trang-mua-ban-xang-dau-long-vong-giam-chi-phi-luu-thong-20261021181438002.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/_qpB8UJWwQXqZJeK7_zafx77Mj0=/zoom/1200_630/2026/10/21/thu-tuong-yeu-cau-khac-phuc-triet-de-tinh-trang-mua-ban-xang-dau-long-vong-giam-chi-phi-luu-thong-cropped-1792584238115.jpg","crawledAt":"2026-10-21T13:42:54.921Z"},{"id":"dtri-20261021180919592","title":"\"Mạng lưới sát thủ\" của Nga rợp trời, loạt mục tiêu Ukraine vào tầm ngắm","slug":"mang-luoi-sat-thu-cua-nga-rop-troi-loat-muc-tieu-ukraine-vao-tam-ngam","excerpt":"Công nghệ chiến trường được Nga tận dụng để biến những bầy đàn UAV tấn công thành \"mạng lưới sát thủ\" tại Ukraine.","content":"(Dân trí) - Công nghệ chiến trường được Nga tận dụng để biến những bầy đàn UAV tấn công thành \"mạng lưới sát thủ\" tại Ukraine.\n\nUAV tầm xa hoạt động như FPV\n\nMột thành phố trải rộng dưới ống kính camera của UAV Nga. Những mục tiêu dần hiện ra khi vũ khí tiến sát chúng. Những đoạn video như vậy đã trở nên quá quen thuộc trong cuộc chiến ở Ukraine, thường được ghi lại bởi các UAV góc nhìn thứ nhất (FPV) cỡ nhỏ săn lùng bất cứ thứ gì di chuyển dọc tiền tuyến, từ binh sĩ, phương tiện trong vùng sát thương.\n\nGiờ đây, camera được gắn trên một UAV tấn công tầm xa của Nga, được điều khiển từ xa ở khoảng cách vượt xa tầm hoạt động của một liên kết vô tuyến trực tiếp thông thường, để săn lùng mục tiêu của Ukraine.\n\nChúng là UAV tầm xa nhưng lại đang hoạt động như UAV FPV. Công nghệ then chốt giúp điều này trở nên khả thi là mạng lưới kết nối dạng lưới (mesh), cho phép UAV và các phương tiện khác được trang bị thiết bị vô tuyến chuyển tiếp thông tin liên lạc cho nhau, mở rộng phạm vi điều khiển vượt quá tầm hoạt động của một thiết bị vô tuyến đơn lẻ.\n\nCông nghệ này cũng cho phép truyền hình ảnh video trực tiếp trở lại qua mạng lưới tới người điều khiển, giúp họ nhìn thấy những gì UAV quan sát được và điều chỉnh đường bay theo thời gian thực.\n\nÔng Serhii “Flash” Beskrestnov, cố vấn của Tổng thống Ukraine về phát triển công nghệ quốc phòng, giải thích rằng trong một bầy đàn UAV hoạt động theo mô hình mạng lưới, nếu có chiếc đảm nhận nhiệm vụ tấn công thì sẽ có chiếc khác bay vòng phía trên. Được trang bị thiết bị vô tuyến kết nối dạng lưới, chiếc UAV thứ hai đóng vai trò chuyển tiếp tín hiệu cho UAV đồng đội, đồng thời quay phim và lập tức truyền về hình ảnh cuộc tấn công.\n\nSau khi SpaceX chặn các thiết bị đầu cuối Starlink không được cấp phép mà lực lượng Nga sử dụng vào đầu tháng 2, Moscow đã tìm những cách khác để duy trì quyền điều khiển UAV từ xa và mạng mesh là ví dụ điển hình.\n\nTừ cuối mùa hè, những đợt UAV Nga sử dụng động cơ phản lực xuất hiện gần như liên tục trên bầu trời Kiev.\n\nThông tin liên lạc dạng lưới đang giúp biến những UAV này thành mối đe dọa đáng gờm, có khả năng trinh sát độ phân giải cao và tiến hành các cuộc tập kích chính xác được điều khiển từ xa ở tầm hoạt động chưa từng có.\n\nMạng lưới \"sát thủ\"\n\nMạng lưới kết nối dạng lưới là một hệ thống thông tin liên lạc phi tập trung, trong đó các nút có thể kết nối với nhiều nút khác và định tuyến dữ liệu linh hoạt qua mạng, thay vì phụ thuộc vào một đường truyền cố định duy nhất.\n\nTrong các ứng dụng UAV, những nút này có thể là thiết bị vô tuyến gắn trên UAV, phương tiện mặt đất, trạm mặt đất hoặc các nền tảng khác. Mỗi nút đều có khả năng chuyển tiếp dữ liệu qua mạng lưới.\n\nTrong các chiến dịch của Nga, chuỗi kết nối này bắt đầu từ những trạm chuyển tiếp tín hiệu từ mặt đất lên không trung, đặt gần tiền tuyến hoặc dọc biên giới.\n\nSau đó, các UAV được trang bị thiết bị kết nối dạng lưới chuyển tiếp kết nối từ máy bay này sang máy bay khác, đưa tín hiệu ngày càng tiến sâu vào lãnh thổ Ukraine.\n\n“Có thể hình dung nó gần giống như một nhóm người chuyền xô nước để dập lửa. Mỗi người chuyền chiếc xô cho người tiếp theo”, ông Michael Bohnert, nhà nghiên cứu quốc phòng tại RAND, nói.\n\n“Với mạng lưới kết nối dạng lưới, thay vì chỉ có một hàng người nối tiếp nhau, bạn có thể có 3-4 hàng song song, và họ có thể chuyền qua lại gần giống như một bàn cờ”, ông giải thích.\n\nLợi thế trực tiếp nhất của mạng mesh là mở rộng tầm hoạt động của cả bầy đàn UAV. Công nghệ này cho phép Nga vận hành UAV ở khoảng cách “xa gấp 2, 3, thậm chí có thể gấp 4 lần” so với khả năng của liên kết vô tuyến trực tiếp.\n\nMạng lưới dạng lưới cũng có khả năng chống gián đoạn tốt hơn. Do thông tin liên lạc có thể truyền qua nhiều tuyến đường khác nhau, việc mất một nút chuyển tiếp không nhất thiết khiến kết nối bị đứt.\n\nTính linh hoạt tương tự cũng có thể khiến các UAV được điều khiển qua mạng lưới dạng lưới khó bị chế áp bằng tác chiến điện tử hơn. Nếu gây nhiễu chặn một liên kết, mạng lưới có thể tìm cách định tuyến thông tin liên lạc qua một đường truyền khác.\n\nKhoảng cách ngắn hơn giữa các nút riêng lẻ cũng có thể khiến bản thân các liên kết khó bị gây nhiễu hơn. Điều đó không có nghĩa mạng lưới dạng lưới miễn nhiễm với tác chiến điện tử. Tuy nhiên, lợi ích nó mang lại là không thể phủ nhận.\n\nCông nghệ mạng lưới dạng lưới mang lại cho Nga một mạng thông tin liên lạc riêng có khả năng thích ứng và duy trì kết nối tốt, truyền lệnh điều khiển, dữ liệu đo xa, hình ảnh video trực tiếp và các dữ liệu khác giữa người điều khiển với UAV.\n\nKết nối này cho phép tiến hành trinh sát, điều chỉnh mục tiêu và thực hiện các cuộc tập kích điều khiển từ xa như những gì đang diễn ra trên bầu trời Kiev.\n\nCông nghệ mesh mang lại cho lực lượng Nga nhiều lợi thế hơn là chỉ mở rộng tầm hoạt động. Nó cho phép người điều khiển thay đổi diễn biến cuộc tấn công ngay cả khi UAV đã ở trên không.\n\nChuyên gia Bohnert mô tả vấn đề này dưới góc độ lý thuyết trò chơi. Nếu tầm hoạt động là ưu tiên hàng đầu, các UAV chuyển tiếp có thể được bố trí thành một chuỗi dài, mỗi chiếc giúp mở rộng kết nối thêm một đoạn. Nếu tác chiến điện tử hoặc các UAV đánh chặn của Ukraine là mối đe dọa lớn hơn, các UAV có thể bay gần nhau hơn, làm giảm tầm hoạt động nhưng tạo ra nhiều liên kết dự phòng hơn.\n\n“Có rất nhiều yếu tố thuộc lý thuyết trò chơi, và mọi thứ thực sự phụ thuộc vào tình huống cụ thể. Đó là lý do công nghệ này nguy hiểm đến vậy”, ông nói.\n\nViệc duy trì kết nối không nhất thiết đòi hỏi người điều khiển phải trực tiếp điều khiển UAV bằng tay trong suốt hành trình. Các hệ thống thị giác máy tính tích hợp AI cũng có thể cho phép người điều khiển chỉ định mục tiêu, sau đó UAV tự động bám theo và tiếp cận mục tiêu trong giai đoạn cuối của cuộc tấn công.","author":"Đức Hoàng","category":"Thế giới","publishedAt":"2026-10-21 18:09","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/mang-luoi-sat-thu-cua-nga-rop-troi-loat-muc-tieu-ukraine-vao-tam-ngam-20261021180919592.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/wl2TU7_gFUO8NWs7u6p4yzYvYIU=/zoom/1200_630/2026/10/21/xac-uav-ngaafp-cropped-1792580523790.jpg","crawledAt":"2026-10-21T13:42:20.014Z"},{"id":"dtri-20261021180817529","title":"Báo Brazil và Tây Ban Nha ấn tượng với SVĐ lớn nhất thế giới ở Việt Nam","slug":"bao-brazil-va-tay-ban-nha-an-tuong-voi-svd-lon-nhat-the-gioi-o-viet-nam","excerpt":"Các tờ báo của Brazil và Tây Ban Nha đều ấn tượng với sân vận động (SVĐ) lớn nhất thế giới đang được xây dựng ở Việt Nam.","content":"(Dân trí) - Các tờ báo của Brazil và Tây Ban Nha đều ấn tượng với sân vận động (SVĐ) lớn nhất thế giới đang được xây dựng ở Việt Nam.\n\nTờ Globo Esporte (Brazil) bình luận: “Sân VinFast - Trống Đồng được thiết kế với sức chứa lên đến 135.000 chỗ ngồi. Nếu hoàn thành theo đúng dự kiến, công trình tại Việt Nam sẽ vượt qua sân Rungrado 1/5 của Triều Tiên để trở thành sân vận động có sức chứa lớn nhất thế giới.\n\nSân VinFast - Trống Đồng còn có thể vượt qua sân Narendra Modi tại Ấn Độ, công trình phục vụ môn cricket với sức chứa khoảng 132.000 khán giả.\n\nĐiều này đồng nghĩa với việc sân VinFast - Trống Đồng sẽ trở thành sân vận động lớn nhất thế giới nếu xét trên tất cả các môn thể thao”.\n\nTờ báo của Brazil viết thêm về sân VinFast - Trống Đồng: “Dự án được khởi công từ tháng 12/2025. Sân vận động gây chú ý với thiết kế mái vòm màu vàng lấy cảm hứng từ trống đồng, biểu tượng văn hóa truyền thống của Việt Nam. Công trình dự kiến hoàn thành vào tháng 7/2027, sớm hơn kế hoạch ban đầu là tháng 8/2028”.\n\nTờ TieneLore (Tây Ban Nha) cũng chú ý tới sức chứa khổng lồ của sân VinFast - Trống Đồng: “Sân Maracana huyền thoại của Brazil chỉ có sức chứa 78.000 chỗ ngồi. Ngay cả sân Bernabeu ở Madrid cũng chỉ có khoảng 83.000 chỗ ngồi. Hai sân vận động này trở nên nhỏ bé nếu sân VinFast - Trống Đồng với sức chứa 135.000 chỗ ngồi hoàn tất.\n\nThậm chí, sân VinFast - Trống Đồng có thể chứa toàn bộ khán giả ở sân Bernabeu và một nửa số khán giả tại sân Wanda Metropolitano của Atletico Madrid (70.000 chỗ ngồi)”.\n\nTờ báo của Tây Ban Nha còn so sánh sân VinFast - Trống Đồng với sân Wembley (Anh) với sức chứa 90.000 chỗ ngồi và sân Camp Nou (Tây Ban Nha) với sức chứa 105.000 chỗ ngồi (vừa được cải tạo).\n\nTờ TieneLore nhắc đến những cột trụ ở sân VinFast - Trống Đồng cao 80 mét, kết cấu thép nặng hơn 15.000 tấn và công trình xây dựng diễn ra cả ngày lẫn đêm. Họ cũng cho biết 4 khán đài A, B, C và D đang được xây dựng đồng thời. Một số khu vực đã tiến hành đổ bê tông sàn mái tầng ba, trong khi hệ thống tháp nâng đang được hoàn thiện để phục vụ việc đưa các mô đun vòm thép lên vị trí lắp đặt.\n\nTheo tiến độ được truyền thông nước ngoài đề cập, phần kết cấu bê tông cốt thép dự kiến hoàn thành vào cuối năm 2026, trước khi chuyển sang các hạng mục mái vòm, hệ thống điện và hoàn thiện. Sân vận động được đặt mục tiêu hoàn thành vào tháng 7/2027, sớm hơn kế hoạch ban đầu là tháng 8/2028.","author":"H. Long","category":"Thể thao","publishedAt":"2026-10-21 18:08","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/bao-brazil-va-tay-ban-nha-an-tuong-voi-svd-lon-nhat-the-gioi-o-viet-nam-20261021180817529.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/J6qbAFUrqU5WJiezo1mcwcrTGN8=/zoom/1200_630/2026/10/21/bao-brazil-va-tay-ban-nha-an-tuong-voi-svd-lon-nhat-the-gioi-o-viet-nam-edited-cropped-1792580773018.jpg","crawledAt":"2026-10-21T13:43:03.823Z"},{"id":"dtri-20261021180348278","title":"Sắp có quỹ hỗ trợ doanh nghiệp vay vốn ưu đãi, giảm chi phí năng lượng","slug":"sap-co-quy-ho-tro-doanh-nghiep-vay-von-uu-dai-giam-chi-phi-nang-luong","excerpt":"Bộ Công Thương đề xuất lập quỹ 500 tỷ đồng, dự kiến hoạt động từ năm 2027, nhằm hỗ trợ doanh nghiệp tiếp cận vốn ưu đãi, giảm chi phí năng lượng.","content":"(Dân trí) - Bộ Công Thương đề xuất lập quỹ 500 tỷ đồng, dự kiến hoạt động từ năm 2027, nhằm hỗ trợ doanh nghiệp tiếp cận vốn ưu đãi, giảm chi phí năng lượng.\n\nBộ Công Thương đang xây dựng Đề án thành lập Quỹ thúc đẩy sử dụng năng lượng tiết kiệm và hiệu quả với vốn điều lệ dự kiến 500 tỷ đồng, nhằm hỗ trợ doanh nghiệp tiếp cận vốn ưu đãi, đổi mới công nghệ, giảm chi phí năng lượng và nâng cao năng lực cạnh tranh.\n\nQuỹ được định hướng là quỹ tài chính nhà nước ngoài ngân sách, hoạt động không vì mục đích lợi nhuận. Thông qua kết nối nguồn lực trong nước, quốc tế và nguồn vốn xã hội hóa, Quỹ được kỳ vọng giúp doanh nghiệp tiếp cận các nguồn vốn ưu đãi, kết hợp hỗ trợ tài chính với hỗ trợ kỹ thuật để triển khai dự án.\n\nBộ Công Thương đang tiếp tục lấy ý kiến các bên liên quan về mô hình tổ chức, cơ chế vận hành và phương án huy động vốn trước khi hoàn thiện hồ sơ trình Thủ tướng xem xét, quyết định.\n\nViệc xây dựng Đề án được thực hiện trên cơ sở Luật số 77/2025/QH15 sửa đổi, bổ sung một số điều của Luật Sử dụng năng lượng tiết kiệm và hiệu quả, phù hợp với định hướng phát triển năng lượng, bảo đảm an ninh năng lượng quốc gia tại Nghị quyết số 70-NQ/TW của Bộ Chính trị.\n\nTheo phương án đang được xây dựng, Quỹ có vốn điều lệ dự kiến được ngân sách nhà nước cấp trong giai đoạn 2027-2029 từ nguồn vốn đầu tư công trung hạn.\n\nQuỹ được định hướng thực hiện sáu nhóm nhiệm vụ, gồm huy động nguồn lực tài chính; cho vay ưu đãi bán buôn; hỗ trợ lãi suất; hỗ trợ kỹ thuật như kiểm toán năng lượng, đào tạo nhân lực; thúc đẩy chuyển đổi thị trường và thực hiện đầu tư chính sách.\n\nTrong đó, Quỹ dự kiến trích tối đa 10% vốn điều lệ lũy kế hàng năm để thực hiện các nghiệp vụ hỗ trợ không hoàn lại, như cấp bù hỗ trợ lãi suất 2%/năm.\n\nVới hoạt động cho vay bán buôn, Quỹ sẽ cung cấp nguồn vốn ưu đãi cho các tổ chức tín dụng để cho doanh nghiệp vay lại, với thời hạn tối đa 10 năm và thời gian ân hạn tối đa 2 năm. Theo phương án đề xuất, các tổ chức tín dụng tham gia phải tự thẩm định và chịu rủi ro tín dụng đối với khách hàng vay vốn.\n\nTheo lộ trình, Bộ Công Thương sẽ hoàn thiện Đề án và trình Thủ tướng xem xét, phê duyệt trong tháng 12. Trường hợp được phê duyệt đúng kế hoạch, Quỹ dự kiến hoạt động từ ngày 1/1/2027 và hoàn tất việc cấp đủ vốn điều lệ vào năm 2029.","author":"Thanh Thương","category":"Kinh doanh","publishedAt":"2026-10-21 18:03","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/sap-co-quy-ho-tro-doanh-nghiep-vay-von-uu-dai-giam-chi-phi-nang-luong-20261021180348278.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/rAe8YlA9yFo_rkTBNcHkW5kG0S0=/zoom/1200_630/2025/04/03/cong-nhan-may-104-1658367206182-crop-1743661379227.jpeg","crawledAt":"2026-10-21T13:42:53.853Z"},{"id":"dtri-20261021174907326","title":"30 ngày thanh tra việc xử lý khiếu nại, tố cáo kéo dài ở Hà Nội và Sơn La","slug":"30-ngay-thanh-tra-viec-xu-ly-khieu-nai-to-cao-keo-dai-o-ha-noi-va-son-la","excerpt":"Ông Ngô Mạnh Hùng, Phó Cục trưởng Cục I - Thanh tra Chính phủ làm trưởng đoàn thanh tra chuyên đề về giải quyết, xử lý các vụ khiếu nại, tố cáo kéo dài, vượt cấp, phức tạp tại Hà Nội và Sơn La.","content":"(Dân trí) - Ông Ngô Mạnh Hùng, Phó Cục trưởng Cục I - Thanh tra Chính phủ làm trưởng đoàn thanh tra chuyên đề về giải quyết, xử lý các vụ khiếu nại, tố cáo kéo dài, vượt cấp, phức tạp tại Hà Nội và Sơn La.\n\nPhó Tổng Thanh tra Chính phủ Nguyễn Văn Cường vừa chủ trì hội nghị công bố quyết định thanh tra chuyên đề về giải quyết, xử lý các vụ việc khiếu nại, tố cáo kéo dài, vượt cấp, phức tạp về an ninh trật tự tại thành phố Hà Nội và tỉnh Sơn La.\n\nĐoàn thanh tra gồm 19 thành viên do ông Ngô Mạnh Hùng, Thanh tra viên cao cấp, Phó Cục trưởng Cục I (Thanh tra Chính phủ) làm trưởng đoàn.\n\nĐối tượng thanh tra gồm UBND thành phố Hà Nội, UBND tỉnh Sơn La cùng cơ quan chuyên môn, UBND xã/phường và tổ chức, đơn vị, cá nhân có liên quan ở hai địa phương này.\n\nCuộc thanh tra có thời hạn 30 ngày kể từ ngày công bố quyết định thanh tra, không tính ngày nghỉ, ngày lễ.\n\nĐể giám sát hoạt động của đoàn, Thanh tra Chính phủ thành lập tổ giám sát do ông Đặng Quốc Tuấn, Trưởng phòng 3 - Cục Giám sát và Thẩm định (Thanh tra Chính phủ) làm tổ trưởng.\n\nTại buổi công bố quyết định, Phó Chủ tịch UBND tỉnh Sơn La Nguyễn Minh Tiến và Chánh Thanh tra thành phố Hà Nội Trần Đức Hoạt đã báo cáo tóm tắt tình hình rà soát, giải quyết các vụ việc khiếu nại, tố cáo trên địa bàn.\n\nĐại diện hai địa phương cam kết chỉ đạo cơ quan, đơn vị chấp hành nghiêm túc quyết định thanh tra và phối hợp cung cấp kịp thời, chính xác mọi hồ sơ, tài liệu liên quan.\n\nÔng Nguyễn Văn Cường cho biết Ban Thường vụ Đảng ủy Thanh tra Chính phủ quyết định tổ chức cuộc thanh tra chuyên đề trên phạm vi cả nước nhằm đánh giá công tác tiếp công dân, giải quyết khiếu nại, tố cáo của các địa phương và cơ quan hành chính.\n\nQua thanh tra sẽ làm rõ trách nhiệm, chỉ ra những tồn tại, hạn chế, bất cập để đề xuất các giải pháp khả thi, đúng quy định pháp luật.\n\nLãnh đạo Thanh tra Chính phủ yêu cầu đoàn thanh tra làm việc khoa học, bài bản, phối hợp với đầu mối là Thanh tra thành phố/tỉnh của hai địa phương.\n\nĐặc biệt, đoàn thanh tra phải giữ nghiêm kỷ luật, kỷ cương, đạo đức công vụ; thực hiện đầy đủ, nghiêm túc các quy định, quy chế của Thanh tra Chính phủ.\n\n\"Tuyệt đối không để xảy ra vi phạm, tiêu cực\", ông Cường nhấn mạnh.\n\nVề phía UBND TP Hà Nội và tỉnh Sơn La, ông Cường đề nghị chấp hành nghiêm quyết định thanh tra, đồng thời thành lập tổ công tác phối hợp làm việc. Cùng với đó, địa phương cung cấp hồ sơ, tài liệu bảo đảm ngăn nắp, khoa học.\n\nTrong thời gian đoàn thanh tra làm việc, ông Cường nhấn mạnh công tác tiếp công dân, giải quyết khiếu nại, tố cáo của các tỉnh, thành phố vẫn phải thực hiện bình thường.\n\nCông bố thanh tra tại 5 địa phương\n\nPhó Tổng Thanh tra Chính phủ Nguyễn Văn Cường cũng vừa chủ trì buổi công bố quyết định thanh tra chuyên đề về giải quyết, xử lý các vụ việc khiếu nại, tố cáo kéo dài, vượt cấp, phức tạp về an ninh, trật tự tại 5 tỉnh, thành phố gồm: Hải Phòng, Bắc Ninh, Lạng Sơn, Tuyên Quang và Cao Bằng.\n\nĐoàn thanh tra gồm 19 thành viên, do ông Nguyễn Duy Đông, Phó Cục trưởng Cục Thanh tra, giải quyết khiếu nại, tố cáo khu vực phía Bắc (Cục I), làm trưởng đoàn.\n\nPhó Tổng Thanh tra Nguyễn Văn Cường yêu cầu mọi nhận định, kết luận, kiến nghị phải có đầy đủ hồ sơ, tài liệu chứng minh, đúng thẩm quyền và căn cứ pháp luật.\n\nĐối với những vụ việc đã được tòa án hoặc cơ quan công an giải quyết, đoàn thanh tra xem xét trong phạm vi quản lý hành chính nhà nước, không đánh giá, can thiệp vào hoạt động xét xử hoặc hoạt động điều tra.\n\nVới những vụ việc đang được các cơ quan có thẩm quyền giải quyết, đoàn thanh tra không đánh giá vào hoạt động thuộc thẩm quyền của những cơ quan này.\n\nNhấn mạnh thời hạn thanh tra trong 30 ngày, lãnh đạo Thanh tra Chính phủ đề nghị 5 địa phương chủ động chuẩn bị hồ sơ, tài liệu ngay từ đầu và khẩn trương hoàn thành các báo cáo, tạo điều kiện thuận lợi để đoàn thanh tra thực hiện nhiệm vụ.\n\nÔng Cường đề nghị các địa phương chủ động nắm chắc tình hình an ninh, trật tự, xây dựng phương án xử lý kịp thời các tình huống phát sinh. Song song với đó tăng cường đối thoại, tuyên truyền, vận động người dân, không để phát sinh điểm nóng, vụ việc khiếu kiện đông người, vượt cấp trong thời gian thanh tra.","author":"Thế Kha","category":"Thời sự","publishedAt":"2026-10-21 17:49","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/30-ngay-thanh-tra-viec-xu-ly-khieu-nai-to-cao-keo-dai-o-ha-noi-va-son-la-20261021174907326.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/2zOWkZDYg8fWIyMAUkFyK2Mu6NQ=/zoom/1200_630/2026/10/21/thanh-tra-chinh-phu-cropped-1792579665832.jpg","crawledAt":"2026-10-21T13:42:24.391Z"},{"id":"dtri-20261021174622173","title":"Trẻ 12 tuổi mắc não mô cầu ở TPHCM, 177 người được giám sát","slug":"tre-12-tuoi-mac-nao-mo-cau-o-tphcm-177-nguoi-duoc-giam-sat","excerpt":"Bệnh nhi 12 tuổi ở ấp Mỹ Lộc khởi phát bệnh từ ngày 13/10, khiến 177 người được giám sát đến 25/10.","content":"(Dân trí) - Bệnh nhi 12 tuổi ở ấp Mỹ Lộc khởi phát bệnh từ ngày 13/10, khiến 177 người được giám sát đến 25/10.\n\nChiều 21/10, UBND xã Thường Tân (TPHCM) cho biết địa phương đang phối hợp với ngành y tế thành phố và các đơn vị liên quan điều tra dịch tễ, giám sát sức khỏe những người tiếp xúc gần với một bệnh nhi mắc viêm não mô cầu tại ấp Mỹ Lộc.\n\nTrước đó, ngày 19/10, Bệnh viện Nhi đồng 2 lấy mẫu xét nghiệm và xác định bệnh nhi dương tính với vi khuẩn não mô cầu. Hiện trẻ được điều trị tại bệnh viện, sức khỏe ổn định.\n\nBệnh nhi này đã tiêm phòng vaccine mũi 1 vào ngày 4/9/2023.\n\nThông tin dịch tễ cho thấy, từ ngày 1/10 đến 13/10, bệnh nhi đi học tại trường trên đường Lý Thái Tổ (phường Bình Dương, TPHCM), và tham gia 4 buổi học thêm tại một trung tâm Anh ngữ ở khu Biconsi (Tân Uyên) vào các ngày 3, 6, 8 và 10/10.\n\nSáng 13/10, trẻ bắt đầu sốt, đau họng, đau cổ và đau đầu nhiều nên nghỉ học.\n\nSáng 14/10, bệnh nhi được đưa đến Bệnh viện Châu Thành, phường Tân Hiệp, TPHCM) khám và được chẩn đoán nhiễm siêu vi. Đến ngày 15/10, do tiếp tục sốt cao, gia đình đưa trẻ đi tái khám và được bác sĩ đề nghị nhập viện.\n\nSau đó, gia đình đưa bệnh nhi đến Bệnh viện Thuận Mỹ, phường Thủ Dầu Một (TPHCM). Qua thăm khám, bác sĩ nghi ngờ viêm màng não nên hướng dẫn gia đình chuyển trẻ đến Bệnh viện Nhi đồng 2 để khám và nhập viện điều trị.\n\nTheo báo cáo của trạm y tế, khi nhập viện, bệnh nhi tỉnh táo, cổ gượng. Trong vòng 2 tuần trước khi mắc bệnh, trẻ sinh hoạt ở nhà, đến trường học và trung tâm Anh ngữ nói trên.\n\nTrạm Y tế xã Thường Tân đã tiến hành xác minh, điều tra dịch tễ, đồng thời hướng dẫn gia đình thực hiện các biện pháp phòng bệnh.\n\nĐịa phương tiếp tục giám sát chặt chẽ sức khỏe bệnh nhi và những người tiếp xúc gần, đồng thời tuyên truyền để người dân nhận biết các dấu hiệu nghi ngờ mắc bệnh và đến cơ sở y tế kịp thời. Ngành y tế khuyến cáo người dân tuyệt đối không tự ý sử dụng thuốc kháng sinh dự phòng khi chưa có chỉ định của nhân viên y tế.\n\nĐể bảo đảm an toàn, Trạm Y tế xã Thường Tân sẽ theo dõi sức khỏe 177 người tiếp xúc gần với bệnh nhi, gồm 163 học sinh và 14 người sống cùng nơi cư trú, đến hết ngày 25/10.\n\nTrước đó, TPHCM ghi nhận chùm 4 ca viêm não mô cầu nhóm B tại một trường học ở xã Hiệp Phước, trong đó có một học sinh tử vong. Sở Y tế TPHCM cho biết, các chuyên gia thống nhất đánh giá chùm 4 ca bệnh này đã được kiểm soát tốt.","author":"Thảo Phương","category":"Sức khỏe","publishedAt":"2026-10-21 17:46","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/tre-12-tuoi-mac-nao-mo-cau-o-tphcm-177-nguoi-duoc-giam-sat-20261021174622173.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/DBzkJz7zxhkJB0yhTCIJlhxJ0kE=/zoom/1200_630/2026/10/21/nao-mo-cau-edited-cropped-1792579454388.jpg","crawledAt":"2026-10-21T13:42:36.810Z"},{"id":"dtri-20261021174343476","title":"Thủ khoa trường quốc tế gây chú ý trước chung kết Hoa hậu Việt Nam 2026","slug":"thu-khoa-truong-quoc-te-gay-chu-y-truoc-chung-ket-hoa-hau-viet-nam","excerpt":"Hoa hậu Việt Nam 2026 đang tiến gần đến đêm chung kết với 25 thí sinh. Trong số đó, những gương mặt như Khánh Linh, Hồng Hạnh, Phương Nghi... nhận được nhiều chú ý.","content":"(Dân trí) - Hoa hậu Việt Nam 2026 đang tiến gần đến đêm chung kết với 25 thí sinh. Trong số đó, những gương mặt như Khánh Linh, Hồng Hạnh, Phương Nghi... nhận được nhiều chú ý.\n\nSau đêm chung khảo, 25 thí sinh được lựa chọn để tiếp tục tranh tài tại Hoa hậu Việt Nam 2026. Một số gương mặt thu hút sự quan tâm nhờ nền tảng học vấn, kinh nghiệm thi sắc đẹp hoặc những lợi thế riêng.\n\nTrần Xuân Khánh Linh sinh năm 2006, là một trong những gương mặt đáng chú ý trong top 25 cuộc thi năm nay. Chưa có nhiều kinh nghiệm tại các cuộc thi sắc đẹp, cô đang làm quen với những yêu cầu về trình diễn và thể hiện bản thân trước công chúng.\n\nKhánh Linh từng là thủ khoa khóa 2024 của APU International School, đồng thời nhận học bổng từ nhiều trường đại học tại Mỹ. Hiện cô theo học ngành truyền thông tại Trường Đại học Anh quốc Việt Nam (British University Vietnam).\n\nNền tảng học tập trong môi trường quốc tế giúp Khánh Linh có lợi thế về tiếng Anh và giao tiếp. Qua các hoạt động của cuộc thi, cô có cơ hội vận dụng những kỹ năng này, đồng thời rèn luyện khả năng trình diễn và làm việc trước ống kính. Ngoài học tập và ngoại ngữ, Khánh Linh còn có khả năng ca hát, chơi piano.\n\nVũ Hồng Hạnh là một trong những thí sinh đã có kinh nghiệm tại các cuộc thi sắc đẹp trước khi tham gia Hoa hậu Việt Nam 2026. Cô từng giành danh hiệu Á hậu 3 Hoa hậu Sinh viên Việt Nam.\n\nTrải nghiệm từ cuộc thi trước giúp Hồng Hạnh làm quen với sân khấu, các phần trình diễn và hoạt động trước ống kính. Cô cũng nhận được sự quan tâm của khán giả trong hành trình tại Hoa hậu Việt Nam năm nay.\n\nViệc lọt vào top 25 tạo cơ hội để Hồng Hạnh tiếp tục phát huy kinh nghiệm sẵn có, đồng thời thể hiện khả năng ứng xử và dấu ấn cá nhân trong những vòng thi tiếp theo.\n\nLê Phương Nghi sinh năm 2006, cao 1,71m, hiện là sinh viên năm hai ngành Kinh tế đối ngoại tại Trường Đại học Ngoại thương TPHCM. Trước khi tham gia Hoa hậu Việt Nam 2026, Phương Nghi từng giành danh hiệu Hoa khôi duyên dáng Ngoại thương.\n\nVề học tập, Phương Nghi có chứng chỉ IELTS 7.5 và tiếng Nhật JLPT N5. Tại cuộc thi năm nay, cô tiếp tục rèn luyện các kỹ năng cần thiết để đáp ứng yêu cầu của những vòng thi tiếp theo.\n\nĐinh Diệu Anh sinh năm 2003, cao 1,68m, là tân cử nhân Đại học Ngoại thương. Cô tốt nghiệp loại xuất sắc chuyên ngành Tiếng Anh thương mại và loại giỏi chuyên ngành Kinh tế đối ngoại. Diệu Anh đạt IELTS 7.5 từ năm lớp 11.\n\nTrước Hoa hậu Việt Nam 2026, cô từng tham gia cuộc thi Duyên dáng Ngoại thương năm 2023 và giành các danh hiệu á khôi. Với kinh nghiệm từ các hoạt động và cuộc thi dành cho sinh viên, Diệu Anh có cơ hội phát huy khả năng giao tiếp, trình bày và thể hiện bản thân tại Hoa hậu Việt Nam 2026.\n\nPhạm Vân Hà sinh năm 2008, vừa hoàn thành kỳ thi tốt nghiệp THPT và là một trong những thí sinh trẻ tuổi nhất của Top 25 Hoa hậu Việt Nam 2026. Ở độ tuổi còn khá trẻ, cô đã có một số thành tích học tập như danh hiệu học sinh giỏi cấp thành phố môn sinh học và giải khuyến khích Olympic Hóa học.\n\nPhạm Vân Hà cao 1,74m, sở hữu IELTS 7.5 và chứng chỉ tiếng Pháp DELF B2. Những lợi thế về hình thể, ngoại ngữ và học tập là cơ sở để cô tiếp tục phát triển các kỹ năng trong quá trình tham gia cuộc thi.\n\nTrước thềm chung kết, top 25 Hoa hậu Việt Nam 2026 tiếp tục tham gia hoạt động huấn luyện, hoàn thiện kỹ năng catwalk, trình diễn sân khấu, giao tiếp và ứng xử. Đây cũng là giai đoạn để mỗi thí sinh thể hiện khả năng thích nghi, cá tính và sự tiến bộ qua từng thử thách.\n\nBên cạnh ngoại hình, nền tảng học vấn hay kinh nghiệm sân khấu, khả năng ứng xử và tinh thần trách nhiệm cũng là những yếu tố được quan tâm trong hành trình tìm kiếm người kế nhiệm vương miện.\n\nĐêm chung kết Hoa hậu Việt Nam 2026 dự kiến diễn ra vào tháng 11 tại Hải Phòng.","author":"Quỳnh Tâm","category":"Giải trí","publishedAt":"2026-10-21 17:43","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/thu-khoa-truong-quoc-te-gay-chu-y-truoc-chung-ket-hoa-hau-viet-nam-2026-20261021174343476.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/B-4ZhCFAexTypb23fh0K1K16UF0=/zoom/1200_630/2026/10/21/eadb8bb9-d4ee-4868-91d2-7632f7a7fa65-cropped-1792579236602.jpg","crawledAt":"2026-10-21T13:43:12.770Z"},{"id":"dtri-20261021172943179","title":"Nhiều nhà dân bị tốc mái do lốc xoáy ở Lâm Đồng","slug":"nhieu-nha-dan-bi-toc-mai-do-loc-xoay-o-lam-dong","excerpt":"Cơn mưa lớn kéo dài kèm lốc xoáy làm 10 căn nhà của người dân ở Lâm Đồng bị tốc mái, nhiều hộ khác bị ngập nước, ảnh hưởng cuộc sống.","content":"(Dân trí) - Cơn mưa lớn kéo dài kèm lốc xoáy làm 10 căn nhà của người dân ở Lâm Đồng bị tốc mái, nhiều hộ khác bị ngập nước, ảnh hưởng cuộc sống.\n\nNgày 21/10, lực lượng chức năng xã Bảo Lâm 1, tỉnh Lâm Đồng, đã phối hợp cùng các đơn vị liên quan hỗ trợ người dân khắc phục thiệt hại sau cơn mưa lớn, lốc xoáy.\n\nTheo chính quyền xã Bảo Lâm 1, cơn mưa kèm lốc xoáy xảy ra vào chiều cùng ngày trên địa bàn thôn 6 của xã làm 10 nhà dân bị tốc mái. Một số nhà dân bị lốc cuốn mái tôn bay ra đường, đè lên các công trình hộ dân bên cạnh.\n\nTrong khi đó, mưa lớn gây ngập 5 hộ trên địa bàn thôn 11, ảnh hưởng đến sinh hoạt của người dân.\n\nNgay sau khi xảy ra dông, lốc, chính quyền xã Bảo Lâm 1 đã huy động 50 người thuộc các lực lượng công an, quân đội, dân quân có mặt tại hiện trường, hỗ trợ người dân khắc phục hậu quả.\n\nHiện, lực lượng chức năng kiểm kê thiệt hại để sớm có phương án hỗ trợ người dân ổn định cuộc sống.","author":"Minh Hậu","category":"Thời sự","publishedAt":"2026-10-21 17:29","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/nhieu-nha-dan-bi-toc-mai-do-loc-xoay-o-lam-dong-20261021172943179.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/HOFZQleLNKEGNb-Vl_sf4fxE7VE=/zoom/1200_630/2026/10/21/locxoay-cropped-1792578505415.jpg","crawledAt":"2026-10-21T13:42:28.880Z"},{"id":"dtri-20261021172747615","title":"Đối tượng có 2 lệnh truy nã bị bắt sau gần 7 năm lẩn trốn","slug":"doi-tuong-co-2-lenh-truy-na-bi-bat-sau-gan-7-nam-lan-tron","excerpt":"Phan Văn Chương bị truy nã về các tội Giết người và Gây rối trật tự công cộng, vừa bị Phòng Cảnh sát hình sự Công an tỉnh Khánh Hòa bắt giữ sau gần 7 năm lẩn trốn.","content":"(Dân trí) - Phan Văn Chương bị truy nã về các tội Giết người và Gây rối trật tự công cộng, vừa bị Phòng Cảnh sát hình sự Công an tỉnh Khánh Hòa bắt giữ sau gần 7 năm lẩn trốn.\n\nNgày 21/10, đại diện Công an tỉnh Khánh Hòa xác nhận Phòng Cảnh sát hình sự đã bắt giữ Phan Văn Chương (SN 1997, trú phường Ba Ngòi, Khánh Hòa) khi đối tượng đang lẩn trốn tại thôn Từ Thiện, xã Phước Dinh, tỉnh Khánh Hòa.\n\nTheo Công an tỉnh Khánh Hòa, tối 26/11/2019, trong lúc ăn nhậu tại nhà một người dân ở xã Cam Thịnh Đông, thành phố Cam Ranh (cũ), nay là xã Nam Cam Ranh, Chương xảy ra mâu thuẫn với anh N.H.P. (SN 1983, trú tại địa phương).\n\nTrong quá trình xô xát, Chương dùng dao gây thương tích cho anh P.. Nạn nhân được đưa đi cấp cứu nhưng tử vong trên đường đến bệnh viện. Sau khi gây án, nghi phạm bỏ trốn khỏi địa phương.\n\nSau đó, Cơ quan Cảnh sát điều tra Công an tỉnh Khánh Hòa ra quyết định khởi tố Chương về tội Giết người. Do bị can bỏ trốn, ngày 3/12/2019, cơ quan điều tra ra quyết định truy nã đối với Phan Văn Chương.\n\nTrước đó, ngày 15/3/2019, Chương gây rối trật tự công cộng tại thôn Phú Sơn, xã Cam Phú, thành phố Cam Ranh (cũ), nay là phường Cam Ranh, rồi bỏ trốn. Trên cơ sở tài liệu, chứng cứ thu thập được, ngày 12/8/2020, cơ quan điều tra khởi tố Chương về tội Gây rối trật tự công cộng.\n\nSáu ngày sau khi khởi tố về tội danh này, Cơ quan Cảnh sát điều tra Công an tỉnh Khánh Hòa tiếp tục ra quyết định truy nã thứ 2 đối với Chương.\n\nSau gần 7 năm lẩn trốn, Phan Văn Chương đã bị lực lượng chức năng bắt giữ. Hiện cơ quan công an hoàn tất hồ sơ, xử lý đối tượng theo quy định pháp luật.","author":"Trung Thi","category":"Pháp luật","publishedAt":"2026-10-21 17:27","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/doi-tuong-co-2-lenh-truy-na-bi-bat-sau-gan-7-nam-lan-tron-20261021172747615.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/oKx19sR8HGfbXTXFIQSfTzzouo0=/zoom/1200_630/2026/10/21/bi-can-trong-vu-an-giet-nguoicong-an-tinh-khanh-hoa-cropped-1792578290506.jpg","crawledAt":"2026-10-21T13:42:31.261Z"},{"id":"dtri-20261021172211745","title":"Ngân hàng Nhà nước chỉ đạo các nhà băng giảm thực chất lãi suất","slug":"ngan-hang-nha-nuoc-chi-dao-cac-nha-bang-giam-thuc-chat-lai-suat","excerpt":"Ngân hàng Nhà nước lại có chỉ đạo nóng về hạ lãi suất và thông báo sẽ giám sát chặt quá trình tuân thủ của các ngân hàng.","content":"(Dân trí) - Ngân hàng Nhà nước lại có chỉ đạo nóng về hạ lãi suất và thông báo sẽ giám sát chặt quá trình tuân thủ của các ngân hàng.\n\nNgân hàng Nhà nước vừa ban hành công văn quán triệt các ngân hàng thương mại thực hiện quyết liệt nhiệm vụ được giao và chịu trách nhiệm trước pháp luật, trước Thống đốc Ngân hàng Nhà nước, các cấp có thẩm quyền về việc giảm mặt bằng lãi suất.\n\nVăn bản này được đưa ra trên cơ sở kết luận của Thống đốc Ngân hàng Nhà nước tại cuộc họp ngày 19/10, quán triệt các ngân hàng quyết liệt triển khai giải pháp giảm mặt bằng lãi suất, góp phần hỗ trợ phát triển sản xuất, kinh doanh theo chỉ đạo của Chính phủ, Thủ tướng Chính phủ.\n\nTheo đó, Ngân hàng Nhà nước yêu cầu các ngân hàng thương mại quán triệt trong toàn hệ thống ngân hàng thương mại, trên tất cả kênh bán hàng tổ chức thực hiện giảm thực chất lãi suất huy động và cho vay theo chỉ đạo.\n\nNgân hàng thương mại thực hiện giảm tối thiểu 0,5%/năm lãi suất tiền gửi bình quân giao dịch phát sinh mới đối với kỳ hạn từ 6 tháng trở lên trong những tháng cuối năm so với mức lãi suất của chính ngân hàng thương mại tại kỳ báo cáo ngày 11/10- 20/10.​\n\nNgân hàng Nhà nước sẽ theo dõi số liệu lãi suất bình quân đối với giao dịch phát sinh mới trong các tháng cuối năm của ngân hàng thương mại thông qua hệ thống báo cáo thống kê.\n\nTrường hợp ngân hàng thương mại không thực hiện chỉ đạo, Ngân hàng Nhà nước sẽ có biện pháp xử lý nghiêm, bao gồm cả việc xem xét giảm hoặc giao thấp chỉ tiêu tăng trưởng tín dụng.\n\nSau cuộc họp với Thống đốc ngày 19/10, có hơn 20 đơn vị đã cập nhật biểu lãi suất tiền gửi mới. Phần lớn giảm 0,5%/năm với kỳ hạn từ 6 tháng trở lên tại cả hai kênh là quầy và online, có đơn vị giảm 0,7%. Với động thái này, lãi suất tiết kiệm kỳ hạn 12 tháng cho khách hàng cá nhân được phần lớn ngân hàng trên thị trường niêm yết dưới 7%/năm.\n\nNgày 21/10, có 6 ngân hàng điều chỉnh giảm lãi suất huy động, gồm ABBank, MBV, PVcomBank, SHB, MB và SeABank.\n\nTrước đó, loạt ngân hàng giảm lãi suất trong ngày 20/10 như ACB, TPBank, Sacombank, PGBank, VCBNeo, BVBank, LPBank, Bac A Bank, OCB, Nam A Bank, BaoVietBank, NCB, VietBank, KienlongBank...","author":"Thảo Thu","category":"Kinh doanh","publishedAt":"2026-10-21 17:22","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/ngan-hang-nha-nuoc-chi-dao-cac-nha-bang-giam-thuc-chat-lai-suat-20261021172211745.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/z0OcY92sPRJ4qye8Kj9giBeEOjU=/zoom/1200_630/2023/11/02/vpbank-giao-dich23-edited-crop-1698915534065.jpeg","crawledAt":"2026-10-21T13:42:56.005Z"},{"id":"dtri-20261021172135995","title":"Nhiều công nhân xây dựng khó tiếp cận nhà ở xã hội","slug":"nhieu-cong-nhan-xay-dung-kho-tiep-can-nha-o-xa-hoi","excerpt":"Gần một nửa trong 500 công nhân xây dựng được khảo sát chưa tiếp cận thông tin về nhà ở xã hội do hạn chế trong việc nắm quyền lợi, xác định đầu mối hỗ trợ và tìm hiểu thủ tục.","content":"(Dân trí) - Gần một nửa trong 500 công nhân xây dựng được khảo sát chưa tiếp cận thông tin về nhà ở xã hội do hạn chế trong việc nắm quyền lợi, xác định đầu mối hỗ trợ và tìm hiểu thủ tục.\n\nThông tin trên được TS Nguyễn Văn Nên, Trường Đại học Kinh tế - Luật, Đại học Quốc gia TPHCM, chia sẻ tại hội thảo khoa học “Hoàn thiện các chính sách, chương trình hỗ trợ công nhân ngành xây dựng hướng đến mục tiêu phát triển con người toàn diện”, do Viện Phát triển chính sách và năng lực lãnh đạo, Đại học Quốc gia TPHCM tổ chức ngày 21/10.\n\nTS Nguyễn Văn Nên cho hay qua khảo sát 500 công nhân xây dựng, dù khung pháp lý về an sinh xã hội cơ bản hoàn thiện, việc tiếp cận chính sách trên thực tế vẫn còn hạn chế.\n\nTrong đó, đáng chú ý, có đến hơn 47% công nhân chưa tiếp cận thông tin về nhà ở xã hội, do hạn chế trong việc nắm quyền lợi, xác định đầu mối hỗ trợ và tìm hiểu thủ tục. Bên cạnh đó, 35,2% không biết liên hệ với ai khi bị nợ lương và 37,2% chưa rõ quyền lợi khi xảy ra tai nạn lao động.\n\nTS Nguyễn Văn Nên cho rằng những hạn chế này xuất phát từ cả phía người lao động và doanh nghiệp. Gần 29% công nhân thiếu động lực tìm hiểu quyền lợi do đặc thù công việc di động, thời gian làm việc kéo dài; hơn 30% gặp khó khăn khi tra cứu thông tin và thực hiện thủ tục. Tại doanh nghiệp, 30,8% công trường thiếu cán bộ hướng dẫn, 28,4% không có tổ chức công đoàn và 31,6% chưa thường xuyên phổ biến chính sách phúc lợi.\n\n“Để cải thiện khả năng tiếp cận, doanh nghiệp cần tăng hướng dẫn trực tiếp tại công trường, đơn giản hóa thủ tục, công khai thông tin dễ hiểu và phân công đầu mối hỗ trợ. Cơ quan quản lý và doanh nghiệp cũng cần tăng giám sát, minh bạch quy trình và thiết lập kênh phản ánh để người lao động tiếp cận đầy đủ hơn các chính sách an sinh, trong đó có nhà ở xã hội”, TS Nên nói.\n\nTheo PGS.TS Đỗ Phú Trần Tình, Quyền Viện trưởng Viện Phát triển chính sách và năng lực lãnh đạo, Đại học Quốc gia TPHCM, ngành xây dựng đóng vai trò quan trọng đối với phát triển hạ tầng và kinh tế, hiện đóng góp khoảng 8% GDP và dự kiến vượt 10% GDP, tương đương trên 50 tỷ USD, trong giai đoạn tới.\n\nÔng cho rằng Việt Nam chỉ còn khoảng 10 năm để tạo bước chuyển nhằm tránh bẫy thu nhập trung bình. Vì vậy, cần thúc đẩy mô hình hợp tác “3 nhà” gồm Nhà nước, nhà khoa học và doanh nghiệp để huy động nguồn lực, xây dựng các chương trình hỗ trợ sát thực tế.\n\nTrước mắt, nhóm nghiên cứu dự kiến tham mưu chính quyền TPHCM xây dựng cơ chế thử nghiệm (sandbox) an sinh dành cho công nhân ngành xây dựng. Về lâu dài, kết quả khảo sát sẽ được sử dụng để tư vấn hoàn thiện chính sách ở cấp quốc gia, trong đó nghiên cứu bổ sung quy định đặc thù hoặc xây dựng nghị định riêng cho lao động ngành xây dựng.\n\nỞ góc độ doanh nghiệp, tại Đại hội đồng cổ đông thường niên năm 2026, ông Trần Ngọc Hải, Phó tổng giám đốc Công ty cổ phần Xây dựng Coteccons, cho biết khoảng một năm trở lại đây, thị trường xây dựng khan hiếm nhân công.\n\nTrong bối cảnh này, đào tạo, phát triển và xây dựng môi trường làm việc an toàn, tích cực là yếu tố quan trọng để thu hút và giữ chân lao động. Coteccons đang triển khai các chương trình chăm lo đời sống công nhân như trao học bổng, chương trình Xây Tết, chăm sóc sức khỏe và tăng cường an toàn tại công trường...","author":"Lê Tỉnh","category":"Bất động sản","publishedAt":"2026-10-21 17:21","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/nhieu-cong-nhan-xay-dung-kho-tiep-can-nha-o-xa-hoi-20261021172135995.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/mGDO4uvBUY5p8Bpbyj0539aE1as=/zoom/1200_630/2026/10/21/do-phu-tran-tinh-cropped-1792577989035.jpg","crawledAt":"2026-10-21T13:42:58.198Z"},{"id":"dtri-20261021171656639","title":"Tàu du lịch quốc tế đưa 2.000 du khách cập cảng biển lớn nhất Đồng Nai","slug":"tau-du-lich-quoc-te-dua-2000-du-khach-cap-cang-bien-lon-nhat-dong-nai","excerpt":"Tàu du lịch quốc tế Carnival Luminosa đưa hơn 2.000 du khách quốc tế cập cảng Phước An (TP Đồng Nai) để tham quan, trải nghiệm các điểm đến hấp dẫn.","content":"(Dân trí) - Tàu du lịch quốc tế Carnival Luminosa đưa hơn 2.000 du khách quốc tế cập cảng Phước An (TP Đồng Nai) để tham quan, trải nghiệm các điểm đến hấp dẫn.\n\nNgày 21/10, tại cảng Phước An (xã Phước An, TP Đồng Nai), tàu du lịch quốc tế Carnival Luminosa, của hãng Carnival Australia đã cập cảng, đưa hơn 2.000 du khách quốc tế lên bờ tham quan các điểm đến di tích lịch sử, danh lam thắng cảnh ở TPHCM.\n\nTàu du lịch quốc tế Carnival Luminosa có hải trình từ Hồng Kông (Trung Quốc) đến Việt Nam và cập bến cảng Phước An.\n\nTàu có sức chứa khoảng 3.000 người, trong đó trên 900 người thuộc thành viên của tàu. Du khách sau khi làm thủ tục nhập cảnh tại cảng Phước An sẽ đi tham quan theo tour và trở về tàu vào buổi chiều cùng ngày, sau đó tàu Carnival Luminosa tiếp tục hải trình đến Singapore.\n\nĐầu năm nay, Đồng Nai đón khoảng 1.000 du khách quốc tế cập cảng Phước An để tham quan các điểm du lịch tại TPHCM. Đây là chuyến tàu du lịch quốc tế đầu tiên đặt chân đến Việt Nam qua cảng biển nước sâu Phước An, TP Đồng Nai. Các tàu quốc tế cập cảng Phước An đã mở ra cơ hội khai thác, phát triển du lịch đường biển cho Đồng Nai nói riêng và khu vực phía Nam nói chung.\n\nThời gian qua, ngành du lịch Đồng Nai đang phối hợp cùng các đơn vị lữ hành khai thác tour du lịch tàu biển, khảo sát các điểm đến gần khu vực gần cảng Phước An để phục vụ nhu cầu tham quan, trải nghiệm và mua sắm của khách du lịch quốc tế cập cảng biển nước sâu lớn nhất TP Đồng Nai.","author":"Phước Tuần","category":"Du lịch","publishedAt":"2026-10-21 17:16","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/tau-du-lich-quoc-te-dua-2000-du-khach-cap-cang-bien-lon-nhat-dong-nai-20261021171656639.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/MHeDUZyKK_rWu4nITN_RVFWmQP0=/zoom/1200_630/2026/10/21/cangphuocan-edited-cropped-1792577682442.jpg","crawledAt":"2026-10-21T13:42:47.169Z"},{"id":"dtri-20261021171415833","title":"Tây Ninh thúc tiến độ giải phóng mặt bằng gần 300 công trình, dự án","slug":"tay-ninh-thuc-tien-do-giai-phong-mat-bang-gan-300-cong-trinh-du-an","excerpt":"Lãnh đạo tỉnh Tây Ninh yêu cầu các sở, ngành, địa phương chủ động tháo gỡ vướng mắc, đẩy nhanh giải phóng mặt bằng, bảo đảm tiến độ thi công tại 282 công trình, dự án.","content":"(Dân trí) - Lãnh đạo tỉnh Tây Ninh yêu cầu các sở, ngành, địa phương chủ động tháo gỡ vướng mắc, đẩy nhanh giải phóng mặt bằng, bảo đảm tiến độ thi công tại 282 công trình, dự án.\n\nNgày 21/10, ông Trương Thanh Liêm, Phó Chủ tịch UBND tỉnh Tây Ninh, chủ trì cuộc họp rà soát tiến độ bồi thường, giải phóng mặt bằng các công trình, dự án trên địa bàn.\n\nTại cuộc họp, Trung tâm Phát triển quỹ đất tỉnh Tây Ninh cho biết, đến ngày 20/10, toàn tỉnh triển khai công tác bồi thường, thu hồi đất đối với 282 công trình, dự án. Lũy kế đến nay, các đơn vị đã chi trả bồi thường cho 62.727 trường hợp, đạt trên 86%, với diện tích hơn 14.346ha, tương đương 83,74%.\n\nSo với kỳ rà soát ngày 13/10, số trường hợp được chi trả tăng thêm 735, diện tích tăng 62,68ha, số tiền tăng 586,77 tỷ đồng.\n\nĐối với các dự án giao thông trọng điểm, đường Vành đai 4 TPHCM đoạn qua Tây Ninh đã chi trả bồi thường đạt 93,72% số trường hợp và 94,7% diện tích. Dự án cao tốc TPHCM - Mộc Bài đạt tỷ lệ chi trả lần lượt 99,6% số trường hợp và 99,68% diện tích.\n\nVới dự án đường Tân An - Bình Hiệp, công tác chi trả bồi thường được triển khai tại 4 xã, phường, với 521 trường hợp, diện tích 95,28ha. Đến nay, có 7/9 xã, phường hoàn thành phê duyệt phương án bồi thường, hỗ trợ, tái định cư.\n\nĐối với dự án mở rộng cao tốc TPHCM - Trung Lương - Mỹ Thuận, cả 7/7 xã, phường có dự án đi qua đã hoàn thành bàn giao ranh mốc, cung cấp bản vẽ và thành lập hội đồng bồi thường. Các địa phương tiếp tục kiểm đếm, hoàn thiện phương án theo quy định.\n\nTrong khi đó, nhóm dự án khu công nghiệp trọng điểm có tổng diện tích đất dự kiến thu hồi 1.436,56ha. Tỷ lệ chi trả đạt 66% số trường hợp và 71,05% diện tích đã được phê duyệt phương án bồi thường.\n\nPhát biểu chỉ đạo tại cuộc họp, ông Trương Thanh Liêm yêu cầu các sở, ngành, địa phương thường xuyên rà soát tiến độ, xác định nguyên nhân vướng mắc và chủ động đề xuất giải pháp xử lý, không để công tác giải phóng mặt bằng ảnh hưởng đến tiến độ dự án.\n\nLãnh đạo tỉnh cũng yêu cầu người đứng đầu địa phương nâng cao trách nhiệm, phối hợp với các đơn vị liên quan đẩy nhanh kiểm đếm, lập và phê duyệt phương án bồi thường, hỗ trợ, tái định cư; tăng cường tuyên truyền, vận động, đối thoại để tạo sự đồng thuận của người dân.\n\nĐối với các công trình trọng điểm, nhất là dự án dự kiến khởi công trong thời gian tới, các đơn vị cần tập trung nguồn lực, phân công nhiệm vụ cụ thể và kịp thời báo cáo những vấn đề vượt thẩm quyền, bảo đảm bàn giao mặt bằng theo kế hoạch.","author":"An Huy","category":"Thời sự","publishedAt":"2026-10-21 17:14","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/tay-ninh-thuc-tien-do-giai-phong-mat-bang-gan-300-cong-trinh-du-an-20261021171415833.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/HCvQE29gbAJTu8SfaGu1yzXZt4I=/zoom/1200_630/2026/10/21/dji0584-2-cropped-1792577551509.jpg","crawledAt":"2026-10-21T13:42:27.750Z"},{"id":"dtri-20261021170628411","title":"Công chức ngại nói với thủ trưởng, đại biểu đề nghị có kênh đại diện","slug":"cong-chuc-ngai-noi-voi-thu-truong-dai-bieu-de-nghi-co-kenh-dai-dien","excerpt":"Công chức ngại trao đổi với thủ trưởng, người giám sát ở cơ sở còn nể nang, các đại biểu đề nghị củng cố kênh tập hợp kiến nghị và trách nhiệm giải trình.","content":"(Dân trí) - Công chức ngại trao đổi với thủ trưởng, người giám sát ở cơ sở còn nể nang, các đại biểu đề nghị củng cố kênh tập hợp kiến nghị và trách nhiệm giải trình.\n\nChiều 21/10, thảo luận tổ về dự án Luật Thực hiện dân chủ ở cơ sở (sửa đổi), đại biểu Lương Quốc Đoàn, Phó Chủ tịch Ủy ban Trung ương Mặt trận Tổ quốc Việt Nam, đề nghị làm rõ cơ chế tập hợp kiến nghị, bảo vệ quyền lợi công chức tại cơ quan không còn công đoàn.\n\nVẫn họp nhưng ít người nêu kiến nghị\n\nDẫn thực tế tại một số đơn vị, ông Đoàn cho biết sau khi không còn công đoàn, các cơ quan vẫn tổ chức họp nhưng số ý kiến, kiến nghị rất ít. Công chức còn e ngại khi trao đổi trực tiếp với người đứng đầu.\n\nVề phía lãnh đạo, ông cho biết sẵn sàng lắng nghe, giải thích, giải quyết tâm tư, nguyện vọng của công chức. Tuy nhiên, để từng cá nhân trực tiếp nêu vấn đề vẫn là điều khó khăn.\n\nTheo đại biểu, nhiều tâm tư về đào tạo, phúc lợi, điều kiện làm việc chưa đến mức phải khiếu nại, tố cáo. Những việc này có thể giải quyết thông qua trao đổi, kiến nghị tập thể, nhưng cần có cơ chế tập hợp ý kiến phù hợp.\n\nTại đơn vị có công đoàn, người lao động có thể góp ý trực tiếp, thông qua công đoàn hoặc Ban Thanh tra nhân dân. Các tổ chức này tập hợp nguyện vọng và kiến nghị người đứng đầu giải trình những vấn đề liên quan đến tập thể.\n\nÔng Đoàn đề nghị phân định rõ cơ chế thực hiện dân chủ tại nơi có và không có công đoàn; nghiên cứu khả năng tổ chức Ban Thanh tra nhân dân theo cơ chế khác hoặc phát huy vai trò của tổ chức hiện có để tập hợp kiến nghị chung.\n\nDự thảo hiện quy định nhiều hình thức góp ý, như qua hội nghị, người phụ trách bộ phận, hòm thư, đường dây nóng, nền tảng số và các tổ chức chính trị - xã hội nếu có. Băn khoăn của ông Đoàn tập trung vào hiệu quả tập hợp tiếng nói chung khi không còn công đoàn, Ban Thanh tra nhân dân.\n\nGiám sát còn nể nang, thiếu thông tin\n\nTừ góc nhìn ở cơ sở, đại biểu Trình Lam Sinh, đoàn An Giang, cho rằng hoạt động của Ban Thanh tra nhân dân và Ban Giám sát đầu tư của cộng đồng còn những hạn chế cần tháo gỡ.\n\nTheo ông, thành viên các ban sinh sống tại địa bàn, có quan hệ láng giềng với lãnh đạo, cán bộ địa phương nên có thể nể nang, lo việc kiến nghị ảnh hưởng đến quan hệ cộng đồng. Điều này làm giảm sự mạnh dạn trong giám sát.\n\nCác ban cũng gặp khó khi tiếp cận thông tin từ chính quyền, chủ đầu tư hoặc người đứng đầu cơ quan, đơn vị. Với công trình, dự án, bản vẽ, dự toán, tiến độ, khối lượng là căn cứ cần thiết. Không được cung cấp đầy đủ tài liệu, người giám sát thiếu dữ liệu để đối chiếu thực tế.\n\nMột hạn chế khác là không phải thành viên nào cũng có chuyên môn về xây dựng, tài chính, đọc bản vẽ hoặc kiểm tra dự toán.\n\nÔng Sinh cũng lưu ý các ban chủ yếu phản ánh, kiến nghị, không có thẩm quyền trực tiếp xử lý. Nếu người có trách nhiệm không tiếp thu, giải trình, các ban thiếu công cụ yêu cầu thực hiện, ảnh hưởng đến hiệu quả giám sát.\n\nTrong khi đó, thành viên các ban trực tiếp sống, làm việc tại địa bàn, có thể theo dõi công trình hằng ngày. Đại biểu ví đây là “tai mắt” trực tiếp của nhân dân, cần được bảo đảm điều kiện hoạt động.\n\nTrả lời khi công trình đã xong sẽ không còn kịp thời\n\nĐể khắc phục, ông Sinh đề nghị cung cấp công cụ số, quyền tiếp cận thông tin cần thiết về tiến độ, tình hình thực hiện dự án, giúp các ban đối chiếu với thực tế.\n\nCùng với kinh phí, cần hỗ trợ chuyên môn, nghiệp vụ; vận động người am hiểu xây dựng, kiến trúc, tài chính, kể cả người nghỉ hưu, tham gia để nâng chất lượng giám sát.\n\nĐại biểu đặc biệt đề nghị quy định thời hạn người đứng đầu chính quyền cấp xã, cơ quan, đơn vị phải công khai việc tiếp thu, giải trình ý kiến góp ý.\n\nTheo ông, nếu chỉ quy định chung mà không có thời hạn, việc trả lời có thể kéo dài một, hai tháng. Khi đó, công trình đã hoàn thành hoặc chính sách đã triển khai xong, việc phản hồi không còn kịp thời.\n\nÔng không đề xuất số ngày cụ thể mà đề nghị nghiên cứu theo tính chất từng nội dung, dự án, công trình. Điều quan trọng là có mốc thời gian để người có trách nhiệm thực hiện, giúp người góp ý biết kiến nghị của mình được tiếp thu, giải trình ra sao.","author":"Hằng T. Nguyễn","category":"Nội vụ","publishedAt":"2026-10-21 17:06","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/cong-chuc-ngai-noi-voi-thu-truong-dai-bieu-de-nghi-co-kenh-dai-dien-20261021170628411.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/9etEDcIk3CpLgV6ZFViC0DpkGuw=/zoom/1200_630/2026/10/21/db-luong-quoc-doan-cropped-1792576479511.jpg","crawledAt":"2026-10-21T13:43:32.344Z"},{"id":"dtri-20261021170016484","title":"Ô tô chở công nhân va chạm xe máy, một người tử vong","slug":"o-to-cho-cong-nhan-va-cham-xe-may-mot-nguoi-tu-vong","excerpt":"Vụ tai nạn giao thông xảy ra trên quốc lộ Nam Sông Hậu ở TP Cần Thơ khiến người đi xe máy tử vong tại chỗ, ô tô chở công nhân bị lật xuống mương.","content":"(Dân trí) - Vụ tai nạn giao thông xảy ra trên quốc lộ Nam Sông Hậu ở TP Cần Thơ khiến người đi xe máy tử vong tại chỗ, ô tô chở công nhân bị lật xuống mương.\n\nNgày 21/10, trên tuyến quốc lộ Nam Sông Hậu, đoạn qua ấp An Phú, xã Thới An Hội, TP Cần Thơ, xảy ra vụ tai nạn giao thông nghiêm trọng khiến một người tử vong tại chỗ, 3 người bị thương.\n\nThông tin ban đầu, khoảng 5h55 cùng ngày, ông T.T.H. (SN 1959, trú tại xã An Thạnh, TP Cần Thơ) điều khiển xe máy lưu thông trên quốc lộ Nam Sông Hậu theo hướng từ xã Thới An Hội đến xã An Lạc Thôn.\n\nKhi đến đoạn đường thuộc ấp An Phú, ông H. điều khiển xe máy vượt lên và va chạm vào phía sau ô tô 4 chỗ do ông T.V.S. (SN 1986, trú tại TP Cần Thơ) điều khiển, đang lưu thông cùng chiều.\n\nCú va chạm khiến xe máy của ông H. đổ sang phần đường bên trái theo hướng di chuyển. Đúng lúc này, ô tô chở công nhân do anh N.H.N. (SN 1994, trú tại xã Thới An Hội) điều khiển, lưu thông theo chiều ngược lại, cán qua người ông H..\n\nSau đó, ô tô chở công nhân bị lật xuống mương ven đường. Vụ tai nạn khiến ông H. tử vong tại chỗ, 3 công nhân trên ô tô bị thương nhẹ.\n\nNguyên nhân vụ tai nạn đang được cơ quan chức năng làm rõ.","author":"Hồng Nhung","category":"Pháp luật","publishedAt":"2026-10-21 17:00","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/o-to-cho-cong-nhan-va-cham-xe-may-mot-nguoi-tu-vong-20261021170016484.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/Y4qebJKDvdx3S7nZTH-BBSpzBgk=/zoom/1200_630/2026/10/21/tai-nan-lat-xe-dua-don-cong-nhan-2-cropped-1792576095883.jpg","crawledAt":"2026-10-21T13:42:31.275Z"},{"id":"dtri-20261021165551260","title":"Báo cáo Bộ Chính trị, trình Hội nghị T.Ư 5 chính sách tiền lương, BHXH mới","slug":"bao-cao-bo-chinh-tri-trinh-hoi-nghi-tu-5-chinh-sach-tien-luong-bhxh-moi","excerpt":"Chính phủ đang xây dựng Đề án, báo cáo Bộ Chính trị và trình Hội nghị Trung ương 5 ban hành nghị quyết mới về chính sách tiền lương và BHXH, để thay thế Nghị quyết số 27 và 28 của Trung ương khóa XII.","content":"Chiều 21/10, Phó Thủ tướng Phạm Thị Thanh Trà góp ý và nêu nhiều định hướng quan trọng về việc sửa đổi các dự án luật, trong đó có Luật sửa đổi, bổ sung một số điều của Bộ luật Lao động; Dự án Luật sửa đổi, bổ sung một số điều của Luật Bảo hiểm xã hội; Dự án Luật Thực hiện dân chủ ở cơ sở (sửa đổi).\n\nChính phủ linh hoạt, chủ động giải quyết những vấn đề phát sinh\n\nVới Luật Bảo hiểm xã hội, Phó Thủ tướng cho biết Chính phủ đang xây dựng đề án báo cáo Bộ Chính trị và trình Hội nghị Trung ương 5 ban hành một nghị quyết mới về chính sách tiền lương và bảo hiểm xã hội, để thay thế Nghị quyết số 27 và 28 của Trung ương khóa XII.\n\n“Khi có một nghị quyết mới của Trung ương, Luật Bảo hiểm xã hội gần như sẽ thay đổi toàn bộ”, Phó Thủ tướng nhấn mạnh.\n\nNêu bối cảnh của cuộc cách mạng sắp xếp tổ chức bộ máy, Phó Thủ tướng cho biết tất cả dự án luật liên quan đều phải tập trung sửa. Mục tiêu ban đầu là phấn đấu đến tháng 3/2027 phải kết thúc toàn bộ việc sửa các dự án luật liên quan, song mốc thời gian này, theo Phó Thủ tướng, khó có thể đạt được, vì số lượng luật cần sửa lên tới 157. Vì thế, Bộ Chính trị quyết định cho kéo dài nhiệm vụ này đến hết năm 2027.\n\nMột định hướng quan trọng khác, Phó Thủ tướng nhấn mạnh, khơi thông mọi điểm nghẽn để tập trung cho kiến tạo và phát triển là yêu cầu vừa mang tính cấp bách trước mắt, vừa mang tính chiến lược lâu dài.\n\nVì vậy, phải tập trung rà soát cắt giảm, đơn giản hóa các thủ tục hành chính, giảm chi phí tuân thủ cho người dân và doanh nghiệp. Đồng thời, những vướng mắc là \"điểm nghẽn thể chế\" phải sửa đổi đồng bộ.\n\n“Chính phủ linh hoạt, chủ động giải quyết những vấn đề xuất phát từ thực tiễn hoặc trong quá trình điều hành có khó khăn, vướng mắc, nhằm khơi thông tất cả nguồn lực cho sự phát triển”, Phó Thủ tướng khẳng định.\n\nVới nhiệm vụ này, bà cho rằng thẩm quyền của Chính phủ được nâng lên nhưng trách nhiệm cũng rất nặng nề, vì thế, phải rất khẩn trương để hoàn thiện các văn bản quy phạm pháp luật hướng dẫn thi hành ngay khi luật được Quốc hội thông qua.\n\nLiên quan đến Luật Việc làm, nội dung sửa đổi cốt lõi được Phó Thủ tướng nhấn mạnh là cắt giảm một loạt giấy phép không cần thiết. Ủng hộ tăng cường hậu kiểm, song mặt khác, Phó Thủ tướng lưu ý vẫn phải kiểm tra, kiểm soát được. Nếu không, thị trường lao động sẽ xuất hiện nhiều vấn đề.\n\n“Chưa bao giờ thị trường lao động diễn biến đa chiều, linh hoạt như hiện nay. Nếu quản lý Nhà nước không có công cụ quản lý tốt sẽ rất khó khăn cho việc điều tiết quan hệ lao động cũng như điều tiết thị trường lao động”, Phó Thủ tướng nêu quan điểm.\n\nTheo dự thảo luật, nội dung này đã được đề cập nhưng sẽ giao thẩm quyền cho Chính phủ quy định chi tiết.\n\nMở rộng diện bao phủ bảo hiểm xã hội\n\nGóp ý vào Luật Bảo hiểm xã hội, theo Phó Thủ tướng, mục tiêu chủ yếu là mở rộng diện bao phủ bảo hiểm xã hội nhằm thực hiện nguyên tắc vừa thúc đẩy thị trường lao động, vừa đảm bảo tỷ lệ bao phủ bảo hiểm xã hội toàn dân.\n\nMục tiêu đặt ra là phấn đấu đến năm 2030 phải bảo đảm bao phủ bảo hiểm xã hội toàn dân và kế hoạch giao đến năm 2026 đạt 95%, Phó Thủ tướng thông tin mục tiêu này đã đạt gần 96%.\n\nCho biết Chính phủ đã thảo luận rất nhiều về nội dung này, Phó Thủ tướng nhấn mạnh mục tiêu được Chính phủ thống nhất là vừa bảo đảm an toàn, bền vững, hiệu quả, vừa bảo đảm nguồn chi trả đúng hạn theo yêu cầu của quyền lợi an sinh lâu dài cho người dân.\n\nPhó Thủ tướng cũng lưu ý việc kiểm soát, bảo toàn, tăng trưởng quỹ và sử dụng hiệu quả nguồn tiền chưa đến hạn chi trả. “Quản lý chặt chẽ nội dung này vừa bảo toàn được nguồn tiền bảo hiểm của người dân, vừa có thể tăng trưởng được quỹ. Từ nguồn quỹ tăng trưởng này, chúng ta lại sử dụng rất hiệu quả để tiếp tục hỗ trợ cho các chính sách an sinh xã hội”, Phó Thủ tướng phân tích.\n\nLiên quan đến Luật Thực hiện dân chủ ở cơ sở, Phó Thủ tướng cho biết nội dung của luật sửa đổi tương đối nhiều. Tới đây, Bộ Chính trị, Ban Bí thư sẽ cho ý kiến và sẽ có kết luận về mô hình tổ chức dân chủ ở cơ sở sau khi thực hiện sắp xếp lại tổ chức bộ máy và đơn vị hành chính, đặc biệt là chính quyền địa phương 2 cấp, nhất là cấp cơ sở.\n\nVì vậy, theo Phó Thủ tướng, phải có những phương thức, cách thức để tiếp tục thúc đẩy phát triển mô hình tự chủ, tự quản và tự chịu trách nhiệm ở cấp cơ sở, đó chính là mô hình tổ chức dân chủ ở cơ sở.\n\nGóp ý việc thực hiện dân chủ trên nền tảng số, Phó Thủ tướng nhìn nhận đây là vấn đề mới. Dự thảo đã mở rộng hình thức họp trực tuyến, trực tuyến kết hợp trực tiếp nhằm đa dạng hóa các hình thức để người dân tham gia trên nền tảng số, thuận tiện hơn cho việc phát huy dân chủ ở cơ sở.\n\n“Nhưng nếu tận dụng tối đa công nghệ mà không tính toán kỹ, hiệu quả sẽ không cao”, Phó Thủ tướng nói và dẫn chứng ở Pháp, áp dụng tuyệt đối xã hội số, tất cả các hoạt động của cộng đồng dân cư đều truyền tải trên môi trường số, dẫn đến khoảng cách giữa người dân và chính quyền có vấn đề đặt ra.","author":"Hoài Thu","category":"Nội vụ","publishedAt":"2026-10-21 16:55","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/bao-cao-bo-chinh-tri-trinh-hoi-nghi-tu-5-chinh-sach-tien-luong-bhxh-moi-20261021165551260.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/2fxw2fI4wPDagCXj6ZZ11NXhXY8=/zoom/1200_630/2026/10/21/pho-thu-tuong-pham-thi-thanh-tra-cropped-1792576134174.jpg","crawledAt":"2026-10-21T13:43:34.492Z"},{"id":"dtri-20261021165003713","title":"Thầy cô, bạn bè xót xa tiễn biệt nam sinh lớp 6 qua đời vì sốt xuất huyết","slug":"thay-co-ban-be-xot-xa-tien-biet-nam-sinh-lop-6-qua-doi-vi-sot-xuat-huyet","excerpt":"Mới làm quen với thầy cô, bạn bè hơn một tháng, nam sinh 12 tuổi ở TPHCM đã qua đời vì bệnh sốt xuất huyết.","content":"(Dân trí) - Mới làm quen với thầy cô, bạn bè hơn một tháng, nam sinh 12 tuổi ở TPHCM đã qua đời vì bệnh sốt xuất huyết.\n\nSáng 21/10, trước cổng Trường THCS Dĩ An, phường Dĩ An, TPHCM, thầy cô và bạn bè đứng lặng lẽ tiễn biệt em Bảo Lâm (12 tuổi), học sinh lớp 6.10 của trường.\n\nSáng sớm, các bạn cùng lớp đã đứng sẵn trước cổng trường để đón Bảo Lâm \"ghé thăm\". Dù mới quen, nhiều em không khỏi xúc động.\n\nMột giáo viên của trường chia sẻ sự ngậm ngùi trước sự ra đi của nam sinh: “Thương con quá… Một chuyến đi còn dang dở, một tuổi đời còn quá trẻ, vậy mà con đã phải rời xa vòng tay gia đình, thầy cô và bạn bè. Mong con từ nay không còn phải chịu đau đớn.\n\nTừ nay, sân trường vẫn còn đó, những hàng ghế thân quen vẫn còn đây, nhưng một dáng hình nhỏ bé sẽ chỉ còn trong ký ức của những người từng gặp gỡ, yêu thương con\".\n\nNhiều phụ huynh, học sinh và thầy cô của trường cũng gửi lời chia buồn đến gia đình nam sinh.\n\nTheo ông Nguyễn Văn Hóa, Hiệu trưởng Trường THCS Dĩ An, Bảo Lâm là học sinh lớp 6 của trường. Em mới làm quen với bạn bè, thầy cô và ngôi trường mới hơn một tháng nay.\n\nTrước đó, ngày 6/10, Bảo Lâm bị sốt, xuất hiện các vết đỏ trên da nên gia đình đưa em đến một bệnh viện gần nhà để điều trị. Ba ngày sau, tình trạng bệnh trở nặng, em được chuyển đến Bệnh viện Nhi đồng 2 TPHCM.\n\nTheo ông Hóa, Bảo Lâm mắc sốt xuất huyết và gặp biến chứng nặng, bị suy tạng, hô hấp yếu. Em phải được hỗ trợ bằng phương pháp ECMO để duy trì sự sống, trong khi hy vọng hồi phục rất mong manh.\n\nTrước tình trạng nguy kịch của con, gia đình phải đối mặt với nhiều khó khăn, đặc biệt là gánh nặng chi phí điều trị và chăm sóc nên ông Nguyễn Văn Hóa đã viết thư ngỏ kêu gọi phụ huynh, thầy cô, cán bộ, nhân viên, học sinh và cộng đồng chung tay hỗ trợ.\n\nTheo ông, nhà trường đã kêu gọi được một khoản chi phí khá lớn để hỗ trợ em điều trị trong điều kiện tốt nhất.\n\nTuy nhiên, dù được tích cực điều trị, em vẫn không qua khỏi.\n\nSự ra đi của Bảo Lâm để lại niềm tiếc thương cho gia đình, thầy cô và bạn bè. Em mới bắt đầu hành trình ở ngôi trường mới, chưa có nhiều thời gian để gắn bó, nhưng sự hiện diện ngắn ngủi ấy vẫn để lại nỗi buồn sâu sắc trong lòng những người ở lại.\n\nSáng nay, thầy cô và bạn bè đứng trước cổng trường tiễn em đoạn đường cuối. Một lời chào tạm biệt quá sớm dành cho cậu học trò mới 12 tuổi.","author":"Loan Nguyễn","category":"Giáo dục","publishedAt":"2026-10-21 16:50","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/thay-co-ban-be-xot-xa-tien-biet-nam-sinh-lop-6-qua-doi-vi-sot-xuat-huyet-20261021165003713.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/4904rgIlVhIiSvhkde72_-Ojk9Y=/zoom/1200_630/2026/10/21/img5294-2-cropped-1792576061642.jpg","crawledAt":"2026-10-21T13:43:21.044Z"},{"id":"dtri-20261021164533132","title":"Khởi tố 84 bị can đường dây lừa đảo, thuê toàn bộ khách sạn để lưu trú","slug":"khoi-to-84-bi-can-duong-day-lua-dao-thue-toan-bo-khach-san-de-luu-tru","excerpt":"Công an tỉnh Thanh Hóa đã khởi tố 84 bị can trong đường dây lừa đảo xuyên quốc gia trên không gian mạng do một người Trung Quốc cầm đầu.","content":"(Dân trí) - Công an tỉnh Thanh Hóa đã khởi tố 84 bị can trong đường dây lừa đảo xuyên quốc gia trên không gian mạng do một người Trung Quốc cầm đầu.\n\nNgày 21/10, Cơ quan An ninh điều tra Công an tỉnh Thanh Hóa đã khởi tố bị can đối với 84 đối tượng về các tội Sử dụng mạng máy tính, mạng viễn thông, phương tiện điện tử thực hiện hành vi chiếm đoạt tài sản; Tổ chức, môi giới cho người khác xuất cảnh, nhập cảnh hoặc ở lại Việt Nam trái phép.\n\nTheo Công an tỉnh Thanh Hóa, tổ chức tội phạm này do Zhao Xuefeng (còn gọi là Đông, SN 1987, quốc tịch Trung Quốc) cầm đầu, điều hành hoạt động của đường dây.\n\nTrước đó, Phòng Quản lý xuất nhập cảnh, Công an tỉnh Thanh Hóa phát hiện một nhóm người nước ngoài mang nhiều quốc tịch khác nhau thuê toàn bộ khách sạn Văn Hoa, tại phường Nghi Sơn, tỉnh Thanh Hóa, để lưu trú.\n\nNhóm người này có biểu hiện sinh hoạt khép kín, bố trí người bảo vệ canh gác nghiêm ngặt, hạn chế người lạ tiếp cận.\n\nBằng các biện pháp nghiệp vụ, lực lượng chức năng xác định các đối tượng từng sinh sống tại Lào, Campuchia. Trong đó, nhiều người nhập cảnh trái phép vào Việt Nam, một số đối tượng bị truy nã ở nước ngoài. Khi nhập cảnh, nhóm này mang theo số lượng lớn máy tính, thiết bị viễn thông đã qua sử dụng.\n\nBước đầu, Cơ quan An ninh điều tra xác định có hơn 100 đối tượng thuộc nhiều quốc tịch hoạt động dưới sự điều hành trực tiếp của Zhao Xuefeng.\n\nĐáng chú ý, các đối tượng không hoạt động riêng lẻ mà phân chia nhiệm vụ theo từng bộ phận, tổ chức thành 6 phòng, tập trung lừa đảo các nhóm khách hàng tại nhiều quốc gia và vùng lãnh thổ.\n\nCác nhóm khách hàng mục tiêu được phân chia theo từng thị trường, gồm Đài Loan (Trung Quốc), Hàn Quốc, Nhật Bản, Ấn Độ, Mỹ và Trung Quốc.\n\nTheo Công an tỉnh Thanh Hóa, các đối tượng sử dụng nhiều thủ đoạn để tiếp cận, lừa đảo nạn nhân.\n\nNhóm này nhắm đến phụ nữ Đài Loan trên 40 tuổi, sử dụng dữ liệu khách hàng để kết bạn, nhắn tin qua các ứng dụng liên lạc, sau đó dụ dỗ đầu tư ngoại hối.\n\nCác đối tượng còn giả danh nhân viên đầu tư để lừa đảo thông qua hình thức mua bán cổ phiếu. Chúng tìm kiếm khách hàng người Hàn Quốc, tự giới thiệu là nhân viên Công ty Nexuswh Investment, tư vấn và mời gọi đầu tư.\n\nSau khi tạo được lòng tin, chúng hướng dẫn khách hàng tải ứng dụng, nạp tiền và thực hiện giao dịch. Khi khách hàng muốn rút tiền hoặc không còn khả năng đầu tư thêm, nhóm lừa đảo chặn liên lạc.\n\nĐối với nhóm khách hàng là phụ nữ Nhật Bản, các đối tượng tìm kiếm, kết bạn trên mạng xã hội, trò chuyện nhằm tạo dựng mối quan hệ, sau đó dẫn dụ nạn nhân đầu tư tiền điện tử.\n\nCác đối tượng còn tổ chức cá cược thể thao trực tuyến; giả danh người thành đạt để dụ dỗ đầu tư tài chính, mua cổ phiếu; giả mạo hoạt động tuyển dụng, đưa ra các công việc trực tuyến nhằm lừa đảo chiếm đoạt tài sản.\n\nCông an tỉnh Thanh Hóa đã bắt giữ 118 đối tượng, trong đó có 113 người nước ngoài và 5 người Việt Nam. Lực lượng công an thu giữ nhiều máy móc, thiết bị điện tử phục vụ hoạt động lừa đảo trên không gian mạng.","author":"Thanh Tùng","category":"Pháp luật","publishedAt":"2026-10-21 16:45","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/khoi-to-84-bi-can-duong-day-lua-dao-thue-toan-bo-khach-san-de-luu-tru-20261021164533132.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/zr2Mhya2-TSnCuSSQwzzEy4ra8I=/zoom/1200_630/2026/10/21/lua-dao-xuyen-quoc-giathanh-hoa19-edited-cropped-1792575765897.jpg","crawledAt":"2026-10-21T13:42:32.447Z"},{"id":"dtri-20261021164425729","title":"Xe tải quay đầu va chạm, người đi xe máy ngã ra đường","slug":"xe-tai-quay-dau-va-cham-nguoi-di-xe-may-nga-ra-duong","excerpt":"Theo hình ảnh do camera giám sát ghi lại, một chiếc xe tải quay đầu tại vị trí có vạch kẻ liền màu vàng và đâm ngã xe máy từ phía sau đi tới, khiến người phụ nữ trên xe máy ngã ra đường, bất tỉnh.","content":"Kinh nghiệm lái xe từ tình huống thực tế:\n\n(Dân trí) - Theo hình ảnh do camera giám sát ghi lại, một chiếc xe tải quay đầu tại vị trí có vạch kẻ liền màu vàng và đâm ngã xe máy từ phía sau đi tới, khiến người phụ nữ trên xe máy ngã ra đường, bất tỉnh.\n\nTình huống được cho là diễn ra vào ngày 19/10 trên đường Đông Nhì, phường Lái Thiêu, TPHCM.\n\nNạn nhân sau đó được người dân hỗ trợ đưa vào lề đường trong tình trạng đa chấn thương. Người nhà nạn nhân cho biết hai bên đang thương lượng phương án giải quyết và bồi thường sau va chạm.\n\nVề nguyên tắc an toàn, người điều khiển phương tiện khi chuyển hướng cần thận trọng quan sát, kiểm soát tốc độ và chú ý nhường đường cho các phương tiện đang đi thẳng, xe đi ngược chiều và người tham gia giao thông khác theo quy định.\n\nViệc này cũng được quy định trong Luật Trật tự, an toàn giao thông đường bộ năm 2024.\n\nTheo đó, trước khi chuyển hướng, người điều khiển phương tiện tham gia giao thông đường bộ phải quan sát, bảo đảm khoảng cách an toàn với xe phía sau, giảm tốc độ và có tín hiệu báo hướng rẽ hoặc có tín hiệu bằng tay theo hướng rẽ đối với xe thô sơ không có đèn báo hướng rẽ, chuyển dần sang làn gần nhất với hướng rẽ.\n\nTín hiệu báo hướng rẽ hoặc tín hiệu bằng tay phải sử dụng liên tục trong quá trình chuyển hướng. Khi bảo đảm an toàn, không gây trở ngại cho người và phương tiện khác mới được chuyển hướng.\n\nKhi chuyển hướng, người lái xe, người điều khiển xe máy chuyên dùng phải nhường đường cho người đi bộ, xe thô sơ, xe đi ngược chiều và chỉ chuyển hướng khi không gây trở ngại hoặc nguy hiểm cho người, phương tiện khác.","author":"Nhật Minh","category":"Xe ++","publishedAt":"2026-10-21 16:44","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/xe-tai-quay-dau-va-cham-nguoi-di-xe-may-nga-ra-duong-20261021164425729.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/vwHk_zLxiDXd08RllCU3kd47g1U=/zoom/1200_630/2026/10/21/xe-tai-quay-dau-cropped-1792574242071.jpg","crawledAt":"2026-10-21T13:43:26.750Z"},{"id":"dtri-20261021164320292","title":"Nhà Trắng phủ nhận liên quan đến quyết định hạn chế Starlink ở Ukraine","slug":"nha-trang-phu-nhan-lien-quan-den-quyet-dinh-han-che-starlink-o-ukraine","excerpt":"Ngoại trưởng Mỹ Marco Rubio khẳng định các quyết định liên quan đến việc Ukraine truy cập vào hệ thống liên lạc vệ tinh Starlink thuộc về SpaceX và tỷ phú Elon Musk, chứ không phải Nhà Trắng.","content":"(Dân trí) - Ngoại trưởng Mỹ Marco Rubio khẳng định các quyết định liên quan đến việc Ukraine truy cập vào hệ thống liên lạc vệ tinh Starlink thuộc về SpaceX và tỷ phú Elon Musk, chứ không phải Nhà Trắng.\n\n\"Starlink là một công ty tư nhân. Họ có hợp đồng. Họ có các điều khoản hợp đồng quy định về cách thức sử dụng công nghệ đó. Điểm quan trọng là chúng tôi không thể chỉ đạo một công ty tư nhân ra quyết định hay không ra quyết định\", Ngoại trưởng Mỹ Marco Rubio phát biểu với các phóng viên ngày 21/10.\n\nPhát biểu này ngầm chỉ ra rằng, nhà sáng lập kiêm giám đốc điều hành tập đoàn SpaceX, tỷ phú Elon Musk, có thể đã chủ động hạn chế Ukraine truy cập Starlink gần đây.\n\nTrước đó, báo Wall Street Journal dẫn nguồn thạo tin cho hay, ông Musk đã trực tiếp chỉ đạo hạn chế truy cập Starlink cấp độ quân sự ở Ukraine.\n\nTheo nguồn tin, ông Musk, Tổng thống Donald Trump và các quan chức Nhà Trắng đã thảo luận về vấn đề này từ trước. Ông Musk và Tổng thống Trump tiếp tục trao đổi về vụ việc trong những ngày sau khi tốc độ kết nối Starlink ở Ukraine bị chậm lại.\n\nAFP dẫn lời hai quan chức Mỹ và một quan chức phương Tây cho hay, quyết định giảm tốc độ truy cập Starlink bản chất xuất phát từ Nhà Trắng. Tổng thống Ukraine Volodymyr Zelensky đưa ra nhận định tương tự, nhưng Nhà Trắng đã phủ nhận.\n\nCác phát biểu của ông Rubio nhiều khả năng sẽ làm gia tăng lo ngại tại Washington liên quan đến khả năng tác động của ông Musk đối với chính sách đối ngoại của Mỹ.\n\nTrước đó, Tổng thống Mỹ Donald Trump công khai tuyên bố ông tin rằng cả ông lẫn tỷ phú Musk đều không đứng sau việc làm chậm kết nối Starlink ở Ukraine.\n\nTuần trước, các quan chức Ukraine cho biết, tốc độ kết nối Starlink ở nước này đã bị hạn chế, ảnh hưởng nghiêm trọng đến các hoạt động tác chiến.\n\nKhi đó, Ngoại trưởng Mỹ Rubio nói rằng: \"Chúng tôi không liên quan gì đến việc đó, không ai ra lệnh làm chậm tốc độ của Starlink cả. Sự việc tự nhiên xảy ra, nhưng theo tôi biết Starlink đã khôi phục kết nối\".\n\nÔng cũng phân biệt giữa phiên bản Starlink dân sự và Starshield quân sự. Ông cho hay, ngay từ đầu, Ukraine chưa bao giờ được truy cập vào Starshield.\n\nTrong khi đó, Tổng thống Ukraine Volodymyr Zelensky cho biết cả Starlink lẫn Starshield tại Ukraine đều bị gián đoạn.\n\nVề phần mình, ông Elon Musk tuyên bố, bất kỳ sự gián đoạn nào mà Ukraine gặp phải khi sử dụng hệ thống liên lạc vệ tinh Starshield đều thuộc trách nhiệm của chính phủ Mỹ.\n\n\"Các hệ thống Starshield (phiên bản quân sự của Starlink) thuộc sở hữu và quyền kiểm soát của chính phủ Mỹ. Mọi hạn chế về tốc độ hay việc sử dụng hệ thống này đều do quân đội và Tổng thống Mỹ quyết định”, ông Musk nhấn mạnh.","author":"Minh Phương","category":"Thế giới","publishedAt":"2026-10-21 16:43","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/nha-trang-phu-nhan-lien-quan-den-quyet-dinh-han-che-starlink-o-ukraine-20261021164320292.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/vHeIQ_l8dJjZ1ZqOKyqhkkrhwBE=/zoom/1200_630/2026/05/06/rubioafp11zon-cropped-1778019486650.jpg","crawledAt":"2026-10-21T13:42:21.087Z"},{"id":"dtri-20261021164010849","title":"Nhạc sĩ Đông Thiên Đức ký độc quyền một ca khúc cho hai ca sĩ gây tranh cãi","slug":"nhac-si-dong-thien-duc-ky-doc-quyen-mot-ca-khuc-cho-hai-ca-si-gay-tranh-cai","excerpt":"Nhạc sĩ Đông Thiên Đức sáng tác một ca khúc được phát hành dưới hai tên “Nếu như duyên mình sai” và “Có phải em đâu”, do Uyên Trang và Kiều Oanh thể hiện.","content":"(Dân trí) - Nhạc sĩ Đông Thiên Đức sáng tác một ca khúc được phát hành dưới hai tên “Nếu như duyên mình sai” và “Có phải em đâu”, do Uyên Trang và Kiều Oanh thể hiện.\n\nNhững ngày gần đây, mạng xã hội xôn xao trước việc hai ca khúc mang tên Có phải em đâu do Nguyễn Kiều Oanh thể hiện và Nếu như duyên mình sai qua giọng hát Uyên Trang đều do nhạc sĩ Đông Thiên Đức sáng tác.\n\nSự trùng khớp này khiến khán giả quan tâm đến quyền khai thác tác phẩm, nhất là khi vấn đề độc quyền.\n\nBà Phương Anh cho hay, ngày 29/9, sau khi thấy thông tin Kiều Oanh chuẩn bị phát hành Có phải em đâu, đại diện ca sĩ Uyên Trang mới liên hệ.\n\nTheo đó, phía Uyên Trang cho biết, ca sĩ đã ký hợp đồng đối với chính ca khúc này nhưng dưới tên Nếu như duyên mình sai. Hợp đồng được ký ngày 6/11/2023, thời hạn đến ngày 6/11/2026. Phía Uyên Trang đồng thời đề nghị tạm dừng việc phát hành sản phẩm âm nhạc của Kiều Oanh.\n\nNhư vậy, theo mốc thời gian được các bên nêu, khi phía Kiều Oanh ký hợp đồng ngày 6/5/2026, thời hạn độc quyền trong hợp đồng trước của Uyên Trang vẫn chưa kết thúc.\n\n“Sau khi nhận được thông tin, chúng tôi lập tức gửi email yêu cầu nhạc sĩ Đông Thiên Đức giải trình. Nhạc sĩ có phản hồi, xác nhận Nếu như duyên mình sai và Có phải em đâu là cùng một ca khúc. Tuy nhiên, chúng tôi chưa nhận được phương án xử lý cụ thể. Phía nhạc sĩ đề nghị chúng tôi lùi ngày phát hành”, bà Phương Anh nói.\n\nTheo đại diện phía Kiều Oanh, Đông Thiên Đức từng đề nghị các bên trao đổi để tìm hướng giải quyết. Tuy nhiên, thời điểm đó, Có phải em đâu đã hoàn tất, được đưa lên các nền tảng nhạc số và triển khai kế hoạch truyền thông, phát hành.\n\nPhía Kiều Oanh cho biết đã ký hợp đồng từ tháng 5, đồng thời đầu tư sản xuất dựa trên quyền được cấp, nên ê-kíp vẫn quyết định phát hành ca khúc theo kế hoạch vào ngày 1/10.\n\nNgày 4/10, Uyên Trang cũng ra mắt ca khúc Nếu như duyên mình sai. Trên YouTube, tiêu đề và phần mô tả video giới thiệu đây là “ca khúc độc quyền”, kèm thông tin “Uyên Trang độc quyền phát hành và sử dụng”.\n\nViệc một ca khúc được hai ca sĩ phát hành thành hai sản phẩm với tên gọi khác nhau, cùng xuất hiện trên YouTube, làm dấy lên nhiều tranh luận.\n\nTheo ghi nhận của phóng viên Dân trí, Có phải em đâu do Nguyễn Kiều Oanh thể hiện đạt hơn 545.000 lượt xem, trong khi Nếu như duyên mình sai của Uyên Trang có hơn 103.000 lượt xem.\n\nPhía ca sĩ Kiều Oanh nhấn mạnh: “Ngay từ đầu, quan điểm của chúng tôi là phía ca sĩ Uyên Trang cũng là một bên bị ảnh hưởng trong câu chuyện này. Chúng tôi muốn làm rõ vấn đề với phía nhạc sĩ Đông Thiên Đức chứ không muốn hai ca sĩ phải giải quyết với nhau”.\n\nTrong quá trình các bên trao đổi, ngày 6/10, phía Uyên Trang đề xuất tổ chức cuộc gặp giữa 3 bên. Cũng trong ngày này, đại diện nữ ca sĩ thông tin đã làm việc với nhạc sĩ Đông Thiên Đức và cho biết các bên “tạm dừng tranh chấp”.\n\nDù vậy, những vướng mắc về bản quyền vẫn tiếp tục ảnh hưởng đến sản phẩm của Kiều Oanh. Ngày 10/10, video Có phải em đâu trên YouTube bị gỡ sau khi phía Uyên Trang gửi yêu cầu liên quan đến bản quyền. Khoảng 1 giờ sau, nền tảng này thông báo yêu cầu đã được rút lại.\n\nCa sĩ Kiều Oanh cho biết cô rất buồn và thất vọng trước sự việc này. Theo nữ ca sĩ, trước đó, Uyên Trang cũng đã gửi email cam kết sẽ không có bất kỳ động thái nào gây ảnh hưởng đến phía Kiều Oanh. Tuy nhiên, sản phẩm của cô sau đó lại gặp vấn đề trên các nền tảng nhạc số và YouTube.\n\n“Tôi nghĩ rằng trách nhiệm cần được làm rõ từ phía nhạc sĩ Đông Thiên Đức, người đã ký kết độc quyền ca khúc với cả hai bên. Tôi mong các bên liên quan có trách nhiệm đối thoại và đưa ra hướng giải quyết thỏa đáng, thay vì để những người đã đầu tư nghiêm túc cho sản phẩm như tôi phải tiếp tục chịu thiệt thòi”, Kiều Oanh bày tỏ.\n\nTrao đổi với phóng viên, nhạc sĩ Đông Thiên Đức cho biết từng chủ động đề nghị hòa giải nhưng đến nay, các bên vẫn chưa tìm được tiếng nói chung. Theo nam nhạc sĩ, nếu không thể đạt được thỏa thuận, vụ việc nên được đưa ra tòa án dân sự giải quyết.\n\nTrước câu hỏi về trách nhiệm của mình với tư cách tác giả và bên cấp quyền khi để xảy ra sự việc, Đông Thiên Đức nói mong muốn vụ việc được giải quyết tại tòa và cho biết sẽ trả lời cụ thể trước tòa.\n\nNam nhạc sĩ cũng nhấn mạnh, khi chưa có kết luận từ cơ quan có thẩm quyền, không nên vội vàng quy kết bên nào đúng, bên nào sai.\n\nĐến thời điểm hiện tại, phía Uyên Trang chưa phản hồi về phạm vi quyền được quy định trong hợp đồng, quá trình làm việc với nhạc sĩ Đông Thiên Đức cũng như quan điểm của nữ ca sĩ trước những vấn đề đang phát sinh.\n\nNhạc sĩ Đông Thiên Đức tên thật là Đặng Hữu Đức, sinh năm 1987 tại Bình Định (nay thuộc tỉnh Gia Lai), trong một gia đình không có truyền thống nghệ thuật.\n\nTừng làm nghề lập trình, anh chuyển hướng sang âm nhạc và dần ghi dấu ấn với loạt ca khúc như Một vòng Việt Nam, Ngày mai người ta lấy chồng, Ai chung tình được mãi, Khóa ly biệt, Sao ta ngược lối...\n\nNhiều sáng tác của Đông Thiên Đức được khán giả yêu thích và được các ca sĩ như Tùng Dương, Hồ Ngọc Hà, Lệ Quyên, Noo Phước Thịnh, Hoài Lâm thể hiện.","author":"Hương Hồ","category":"Giải trí","publishedAt":"2026-10-21 16:40","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/nhac-si-dong-thien-duc-ky-doc-quyen-mot-ca-khuc-cho-hai-ca-si-gay-tranh-cai-20261021164010849.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/4RwoAXdyTYQiSzQPphAzAEIzxOM=/zoom/1200_630/2026/10/21/tai-lieu-khong-co-tieu-de-4-cropped-1792575508470.jpg","crawledAt":"2026-10-21T13:43:09.479Z"},{"id":"dtri-20261021163816843","title":"Đức Phúc \"dao kéo\" lần hai sau 9 năm, Hòa Minzy xót xa","slug":"duc-phuc-dao-keo-lan-hai-sau-9-nam-hoa-minzy-xot-xa","excerpt":"Sau 9 năm kể từ lần phẫu thuật thẩm mỹ đầu tiên, Đức Phúc tiếp tục chỉnh sửa ngoại hình, thu hút sự chú ý của khán giả.","content":"(Dân trí) - Sau 9 năm kể từ lần phẫu thuật thẩm mỹ đầu tiên, Đức Phúc tiếp tục chỉnh sửa ngoại hình, thu hút sự chú ý của khán giả.\n\nMới đây, Đức Phúc thu hút sự chú ý khi công khai việc phẫu thuật thẩm mỹ lần hai, sau 9 năm kể từ lần thay đổi diện mạo đầu tiên. Nam ca sĩ cho biết quyết định này được đưa ra khi anh vừa bước sang tuổi 30, đánh dấu một cột mốc mới trong cuộc sống.\n\nTrên trang cá nhân, Đức Phúc chia sẻ hình ảnh bản thân ở ba cột mốc thay đổi ngoại hình. Năm 2015, khi đăng quang Giọng hát Việt, nam ca sĩ vẫn giữ diện mạo chưa trải qua \"dao kéo\". Hai năm sau, ở tuổi 20, anh quyết định phẫu thuật thẩm mỹ lần đầu, kết hợp giảm cân. Đến năm nay, khi vừa tròn 30 tuổi, Đức Phúc tiếp tục thay đổi diện mạo lần thứ hai.\n\nĐức Phúc cho biết đã thực hiện phẫu thuật lần hai khoảng 1 tháng trước khi chia sẻ thông tin. Anh công khai chuyện này nhằm giúp người hâm mộ yên tâm, tránh lo lắng trong thời gian mình hồi phục.\n\nNam ca sĩ cũng đăng tải video hát để khán giả thấy tình trạng hiện tại. Theo Đức Phúc, dù diện mạo có thay đổi, giọng hát của anh vẫn ổn định, thậm chí ngày càng tiến bộ.\n\nHiện anh chưa tiết lộ cụ thể những thủ thuật đã thực hiện. Tuy nhiên, qua hình ảnh mới, một số khán giả nhận xét gương mặt nam ca sĩ trông thon gọn hơn, cánh mũi, đôi môi cũng có những thay đổi nhất định.\n\nTrước quyết định của Đức Phúc, Hòa Minzy cũng có chia sẻ đáng chú ý về hành trình thay đổi nhan sắc của đàn em. Nữ ca sĩ cho biết ban đầu cô tưởng Đức Phúc chỉ nói đùa, cho đến khi anh gọi video để cho cô xem diện mạo mới.\n\nHòa Minzy viết: \"Khi em đi làm, em vừa đùa vừa thật nên chị không tin cho đến khi em gọi video cho chị thấy. Chị cười cười cho em thoải mái chứ thật tâm là chị xót lắm\".\n\nNữ ca sĩ cho biết từng nghe Đức Phúc kể về những đau đớn, vất vả khi phẫu thuật thẩm mỹ. Vì vậy, cô nhiều lần khuyên đàn em không cần tiếp tục chỉnh sửa ngoại hình, bởi tình cảm khán giả dành cho anh không chỉ đến từ diện mạo mà còn từ giọng hát và tính cách.\n\n“Em quyết định thay đổi bản thân một lần nữa để tự tin hơn, đẹp hơn và hạnh phúc hơn. Mỗi cuộc đại phẫu đều đầy đau đớn, nhưng với em, đó lại là một lần tái sinh trong cuộc đời. Dù em có như thế nào, khán giả vẫn yêu quý và ở bên em bởi giọng hát cùng trái tim giàu tình yêu thương”, Hòa Minzy nhắn nhủ.\n\nDù xót xa và lo lắng cho đàn em, Hòa Minzy cho biết cô vẫn vui khi Đức Phúc cảm thấy tự tin hơn với diện mạo mới. Nữ ca sĩ cũng tiết lộ nam ca sĩ rất mong chờ ngày xuất hiện trở lại để khán giả nhìn thấy sự thay đổi của mình.\n\nNăm 2015, Đức Phúc vượt qua nhiều đối thủ để giành ngôi quán quân Giọng hát Việt. Khi đó, giọng hát giàu cảm xúc giúp anh chinh phục khán giả, nhưng ngoại hình lại khiến nam ca sĩ trở thành mục tiêu của những lời chê bai.\n\nĐức Phúc từng kể anh bị gọi là “quán quân xấu nhất lịch sử”. Những lời miệt thị khiến nam ca sĩ buồn lòng, chịu áp lực trong những năm đầu hoạt động nghệ thuật và không ít lần bật khóc.\n\nĐể cải thiện vóc dáng, anh từng nỗ lực giảm cân. Năm 2017, ở tuổi 20, Đức Phúc quyết định phẫu thuật thẩm mỹ với mong muốn tự tin hơn khi xuất hiện trước công chúng.\n\nNam ca sĩ từng chia sẻ: “Ngoại hình và giọng hát phải song hành cùng nhau. Khi thay đổi ngoại hình, tôi được khán giả đón nhận nhiều hơn, ngoại hình trở thành cầu nối đưa tôi đến gần công chúng”.\n\nSau lần thay đổi diện mạo, Đức Phúc tiếp tục khẳng định năng lực qua nhiều ca khúc được khán giả yêu thích. Anh dần tạo dựng vị trí trong làng nhạc Việt, đồng thời nhận được sự quan tâm nhờ tính cách duyên dáng, hài hước.","author":"Quỳnh Tâm","category":"Giải trí","publishedAt":"2026-10-21 16:38","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/duc-phuc-dao-keo-lan-hai-sau-9-nam-hoa-minzy-xot-xa-20261021163816843.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/MBdgvcsi_sw3kbM5M5NbdIfz5Lw=/zoom/1200_630/2026/10/21/81445324713378350382000308982191478122900486n-cropped-1792575049230.jpg","crawledAt":"2026-10-21T13:43:10.547Z"},{"id":"dtri-20261021163622901","title":"Tuyến đường bị đất đá vùi lấp ở Nghệ An đã thông trở lại","slug":"tuyen-duong-bi-dat-da-vui-lap-o-nghe-an-da-thong-tro-lai","excerpt":"Sau gần một tháng bị khoảng 30.000m3 đất đá vùi lấp do mưa lớn, tuyến tỉnh lộ 543C qua xã Yên Na (Nghệ An) đã thông trở lại, giúp người dân đi lại, vận chuyển hàng hóa thuận tiện hơn.","content":"(Dân trí) - Sau gần một tháng bị khoảng 30.000m3 đất đá vùi lấp do mưa lớn, tuyến tỉnh lộ 543C qua xã Yên Na (Nghệ An) đã thông trở lại, giúp người dân đi lại, vận chuyển hàng hóa thuận tiện hơn.\n\nNgày 21/10, ông Thái Lương Thiện, Chủ tịch UBND xã Yên Na, tỉnh Nghệ An, cho biết tuyến tỉnh lộ 543C, đoạn qua khu vực núi Nứa Bàn, bản Huồi Pai, đã được khắc phục sạt lở, thông tuyến sau gần một tháng bị đất đá vùi lấp do mưa lớn.\n\nTheo ông Thiện, sau khi xảy ra sạt lở, chính quyền địa phương phối hợp cùng đơn vị quản lý tuyến tỉnh lộ 543C, huy động lực lượng, máy móc, phương tiện khẩn trương san gạt, thu dọn đất đá nhằm sớm khôi phục giao thông, bảo đảm việc đi lại cho người dân.\n\nDo khối lượng đất đá sạt lở lớn, địa hình miền núi phức tạp, công tác khắc phục gặp không ít khó khăn. Tuy nhiên, với sự nỗ lực của các lực lượng, đến nay, đất đá trên mặt đường đã được thu dọn, phương tiện có thể lưu thông trở lại.\n\nGhi nhận tại khu vực núi Nứa Bàn cho thấy đoạn đường trước đó bị đất đá vùi lấp đã được giải phóng, xe máy, ô tô có thể qua lại. Việc thông tuyến giúp người dân các bản thuận tiện hơn trong sinh hoạt, vận chuyển nông sản, hàng hóa và giao thương.\n\nTrước đó, như Dân trí đã thông tin, ngày 19/9, mưa lớn kéo dài khiến khu vực núi Nứa Bàn, bản Huồi Pai, xã Yên Na xảy ra sạt lở nghiêm trọng. Khoảng 30.000m3 đất đá từ sườn núi đổ xuống, vùi lấp tỉnh lộ 543C, gây ách tắc giao thông.\n\nChính quyền địa phương đã di dời 38 hộ dân với 169 nhân khẩu đến nơi an toàn, đồng thời tổ chức đưa 172 học sinh ra khỏi khu vực nguy hiểm; triển khai các biện pháp bảo đảm an toàn, huy động lực lượng khắc phục, từng bước giải phóng khối lượng lớn đất đá trên tuyến đường.\n\nMặc dù giao thông đã được khôi phục, chính quyền địa phương vẫn cảnh báo nguy cơ sạt lở tái diễn tại khu vực núi Nứa Bàn.\n\nTheo Chủ tịch UBND xã Yên Na, hiện khu vực miền núi vẫn trong mùa mưa, đất đá trên các sườn núi còn tơi xốp, tiềm ẩn nguy cơ tiếp tục sạt trượt, nhất là khi xuất hiện mưa lớn kéo dài.\n\n\"Người dân khi lưu thông qua khu vực Huồi Pai cần chú ý quan sát, giảm tốc độ, không dừng đỗ lâu tại những vị trí có nguy cơ sạt lở để bảo đảm an toàn\", ông Thiện khuyến cáo.\n\nViệc thông tuyến tỉnh lộ 543C sau gần một tháng không chỉ đáp ứng nhu cầu đi lại của người dân mà còn góp phần ổn định đời sống, khôi phục hoạt động sản xuất, giao thương tại địa phương sau thiên tai.","author":"Nguyễn Phê","category":"Thời sự","publishedAt":"2026-10-21 16:36","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/tuyen-duong-bi-dat-da-vui-lap-o-nghe-an-da-thong-tro-lai-20261021163622901.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/SKiT6T-Xazu8HBFlg6KjVgO3EIw=/zoom/1200_630/2026/10/21/yen-na-nghe-an-sat-lo-nguyen-phe-2-edited-cropped-1792575038886.jpg","crawledAt":"2026-10-21T13:42:28.862Z"},{"id":"dtri-20261021162933568","title":"Sự thật về vật thể lạ trong bát mì của khách tại quán ăn Trung Quốc","slug":"su-that-ve-vat-the-la-trong-bat-mi-cua-khach-tai-quan-an-trung-quoc","excerpt":"Đoạn video ghi cảnh thực khách gắp từ bát mì ốc một vật thể lạ màu nâu vàng có hình dáng giống miếng lót đế giày, gây xôn xao dư luận nước này. Nhiều người cho rằng đây là sự cố an toàn thực phẩm.","content":"(Dân trí) - Đoạn video ghi cảnh thực khách gắp từ bát mì ốc một vật thể lạ màu nâu vàng có hình dáng giống miếng lót đế giày, gây xôn xao dư luận nước này. Nhiều người cho rằng đây là sự cố an toàn thực phẩm.\n\nVị khách cho biết, khi ăn bát bún ốc, cô giật mình khi thấy một vật lạ nằm trong bát có hình dáng như miếng lót đế giày.\n\nĐoạn video ghi lại cảnh này đã thu hút hàng triệu lượt xem, trong đó nhiều ý kiến bày tỏ sự lo ngại về vấn đề vệ sinh an toàn thực phẩm. Một số nhận định lại cho rằng đây chỉ là một loại đồ ăn có hình dạng đặc biệt.\n\nDựa vào thông tin trong video, phóng viên của tờ Jimu News đã liên hệ với quán mì ốc nơi vị khách tới ăn. Người này khẳng định, vật thể xuất hiện trong video không phải là miếng lót đế giày, mà là đậu phụ khô được chế biến giống hình dạng vật dụng này.\n\nMột cửa tiệm nằm gần Đại học Nông nghiệp Hoa Nam ở Quảng Châu xác nhận, đây cũng là món ăn đặc trưng của quán. Mỗi miếng bán giá 3 tệ (11.000 đồng) và nhiều khách muốn thưởng thức. Sản phẩm có hình dáng đặc biệt với kích thước tương đương cỡ giày 38, dài khoảng 24cm.\n\nĐược biết, mì ốc vốn là món ăn nổi tiếng tại Trung Quốc với mùi đặc trưng khá nồng. Khi miếng đậu phụ khô hình lót giày ngấm đầy nước dùng, khoảnh khắc này khiến nhiều cư dân mạng gọi đùa món ăn là “miếng lót giày bốc mùi”.\n\nMột số thực khách cho rằng chỉ nhìn qua màn ảnh cũng có thể tưởng tượng ra mùi vị, thậm chí cảm thấy mất ngon.\n\nTrên mạng xã hội Weibo, một số tài khoản hài hước nhận xét, họ bất ngờ trước sức sáng tạo có phần khác thường của ẩm thực Quảng Đông.\n\nThực tế, đậu phụ khô tạo hình giống miếng lót giày không chỉ xuất hiện trong các quán mì ốc. Theo truyền thông nước này, một số cửa hàng tiện lợi tại Thành Đô, tỉnh Tứ Xuyên, cũng bán món đậu phụ khô tẩm gia vị có hình dáng tương tự.\n\nThực khách có thể chấm món này với nước sốt cay riêng và bột ớt. Sản phẩm có nhiều kích cỡ. Cụ thể, loại lớn dài 24cm, giá 3 tệ (khoảng 11.000 đồng). Loại nhỏ dài 16cm, giá 2,5 tệ (khoảng 9.000 đồng).\n\nCách bày bán và lựa chọn kích cỡ khiến món ăn trông giống như một sản phẩm đang được khách thử tại cửa hàng giày.\n\nKhông chỉ đậu phụ khô, một số cơ sở kinh doanh đồ nướng còn sáng tạo món khoai tây được cắt thành miếng có kích thước tương đương miếng lót giày, rắc bột ớt và thì là, sau đó phủ thêm chả tôm rồi đem nướng. Hình thức khác lạ được các cửa hàng tận dụng để thu hút thực khách.\n\nVụ việc một lần nữa cho thấy những món ăn có hình dáng độc đáo có thể nhanh chóng thu hút sự chú ý trên mạng xã hội.\n\nTheo Jimu News","author":"Huy Hoàng","category":"Du lịch","publishedAt":"2026-10-21 16:29","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/su-that-ve-vat-the-la-trong-bat-mi-cua-khach-tai-quan-an-trung-quoc-20261021162933568.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/5hydpmH5yu-xIbU1d_o7dSZM-Dc=/zoom/1200_630/2026/10/21/1-cropped-1792574838466.jpg","crawledAt":"2026-10-21T13:42:48.414Z"},{"id":"dtri-20261021162058942","title":"Một xã ở Cà Mau hoàn thiện dữ liệu đất đai đạt 0%","slug":"mot-xa-o-ca-mau-hoan-thien-du-lieu-dat-dai-dat","excerpt":"Có 19 xã, phường ở Cà Mau thực hiện nhiệm vụ hoàn thiện cơ sở dữ liệu đất đai đạt tỷ lệ dưới 30%. Trong đó, một địa phương chưa ghi nhận kết quả, tỷ lệ hoàn thành là 0%.","content":"(Dân trí) - Có 19 xã, phường ở Cà Mau thực hiện nhiệm vụ hoàn thiện cơ sở dữ liệu đất đai đạt tỷ lệ dưới 30%. Trong đó, một địa phương chưa ghi nhận kết quả, tỷ lệ hoàn thành là 0%.\n\nNgày 21/10, UBND tỉnh Cà Mau cho biết đã đánh giá tiến độ thực hiện nhiệm vụ đo đạc, lập bản đồ địa chính, đăng ký đất đai, lập hồ sơ địa chính và hoàn thiện cơ sở dữ liệu đất đai tại các xã, phường trên địa bàn.\n\nTheo thống kê đến ngày 12/10, có 11 xã, phường đạt tỷ lệ thực hiện trên 70%. Trong đó, địa phương có kết quả cao nhất đạt 107%, còn địa phương thấp nhất đạt khoảng 71,5%.\n\nĐáng chú ý, xã Quách Phẩm có khối lượng rà soát 42 hồ sơ nhưng số hồ sơ thu thập được là 45, tương ứng tỷ lệ thực hiện vượt 100%.\n\nChủ tịch UBND tỉnh Cà Mau ghi nhận, biểu dương những địa phương đạt kết quả tích cực, đồng thời đề nghị tiếp tục phát huy, duy trì tiến độ và hoàn thành các nhiệm vụ theo kế hoạch.\n\nỞ chiều ngược lại, tỉnh đã nhắc nhở 19 xã, phường có kết quả thực hiện còn thấp, với tỷ lệ hoàn thành dưới 30%. Trong nhóm này, địa phương đạt cao nhất chỉ hơn 24%, trong khi một địa phương chưa ghi nhận kết quả, tỷ lệ hoàn thành là 0%.\n\nChủ tịch UBND tỉnh Cà Mau yêu cầu UBND các xã, phường chậm tiến độ khẩn trương rà soát nguyên nhân, chấn chỉnh những hạn chế và xây dựng các giải pháp khắc phục cụ thể.\n\nĐặc biệt, chủ tịch UBND các xã, phường phải trực tiếp lãnh đạo, chỉ đạo, kiểm tra, giám sát quá trình thực hiện; đồng thời chịu trách nhiệm về tiến độ, chất lượng và kết quả hoàn thiện cơ sở dữ liệu đất đai tại địa phương.\n\nUBND tỉnh cũng giao các sở, ngành liên quan tăng cường theo dõi, đôn đốc, hướng dẫn các địa phương tháo gỡ khó khăn về chuyên môn, nghiệp vụ. Việc hỗ trợ có thể thực hiện thông qua hướng dẫn bằng văn bản, trao đổi trực tiếp, điện thoại hoặc họp trực tuyến, tùy tình hình thực tế.\n\nTỉnh Cà Mau yêu cầu các địa phương tập trung khắc phục những hạn chế, đẩy nhanh tiến độ thực hiện, bảo đảm chất lượng và hoàn thành nhiệm vụ theo kế hoạch đề ra.","author":"Nhật Linh Đan","category":"Thời sự","publishedAt":"2026-10-21 16:20","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/mot-xa-o-ca-mau-hoan-thien-du-lieu-dat-dai-dat-0-20261021162058942.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/Zdzg8ls4dP-I8YvBYvrq8_sAI6Y=/zoom/1200_630/2026/10/21/anh-minh-hoa-so-doctv-cropped-cropped-1792573977106.jpg","crawledAt":"2026-10-21T13:42:26.684Z"},{"id":"dtri-20261021161913879","title":"Xác minh thông tin mộ tập thể 120 bộ đội tại cứ điểm Ngok Tavak","slug":"xac-minh-thong-tin-mo-tap-the-120-bo-doi-tai-cu-diem-ngok-tavak","excerpt":"Từ thông tin của một cựu chiến binh cung cấp khu vực chôn cất khoảng 120 bộ đội sau các trận đánh năm 1968 tại xã Phước Năng, lực lượng chức năng Đà Nẵng đã khảo sát hiện trường và phát hiện dị vật.","content":"(Dân trí) - Từ thông tin của một cựu chiến binh cung cấp khu vực chôn cất khoảng 120 bộ đội sau các trận đánh năm 1968 tại xã Phước Năng, lực lượng chức năng Đà Nẵng đã khảo sát hiện trường và phát hiện dị vật.\n\nNgày 21/10, ông Lê Viết Thắng, Chủ tịch UBND xã Phước Năng, cho biết đội quy tập của Bộ Chỉ huy Quân sự thành phố Đà Nẵng đã tổ chức khảo sát bằng radar xuyên đất tại điểm cao 474, Cứ điểm Ngok Tavak (thuộc thị trấn Khâm Đức, huyện Phước Sơn, tỉnh Quảng Nam cũ; nay là xã Phước Năng, Đà Nẵng) và phát hiện dị vật, dấu hiệu bất thường trong kết cấu đất.\n\nĐây là khu vực được ông Nguyễn Quốc Nhung (SN 1947, trú phường Vĩnh Yên, tỉnh Phú Thọ), cựu chiến binh Sư đoàn 2, cung cấp thông tin chôn cất nhiều bộ đội giải phóng. Ông là người tham gia trận đánh Cứ điểm Ngok Tavak trong các ngày 10-12/5/1968.\n\nTheo lãnh đạo xã Phước Năng, ông Nhung đã cung cấp thông tin đến lực lượng chức năng thành phố Đà Nẵng, tại cứ điểm Ngok Tavak có khu mộ tập thể khoảng 200 người, trong đó khoảng 120 người là quân giải phóng và 80 lính đối phương.\n\nTiếp nhận thông tin của ông Nhung, Bộ Chỉ huy Quân sự thành phố Đà Nẵng chỉ đạo Ban Chỉ huy Quân sự xã Phước Năng phối hợp khảo sát, đối chiếu sơ đồ nhân chứng cung cấp với tư liệu lịch sử và thông tin từ người dân.\n\nKết quả, bước đầu lực lượng chức năng ghi nhận một số dấu hiệu bất thường trong kết cấu đất, cần tiếp tục kiểm tra, làm rõ.\n\nHiện nay, Ban Chỉ huy Quân sự xã Phước Năng đã thành lập một tổ công tác để phối hợp với nhân chứng trao đổi thêm thông tin, khảo sát, xác định vị trí theo sơ đồ cung cấp tại vị trí ngoài thực địa.\n\nLãnh đạo xã Phước Năng cho biết chiều 22/10, UBND xã sẽ tổ chức cuộc họp Ban chỉ đạo tìm kiếm, quy tập và xác định danh tính hài cốt liệt sĩ trên điểm cao 474, Cứ điểm Ngok Tavak.\n\nDự kiến ngày 24/10, Bộ Chỉ huy Quân sự thành phố Đà Nẵng sẽ tổ chức quy tập.","author":"Công Bính","category":"Nội vụ","publishedAt":"2026-10-21 16:19","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/xac-minh-thong-tin-mo-tap-the-120-bo-doi-tai-cu-diem-ngok-tavak-20261021161913879.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/q6uIvJRhNzvr-V8xwmbWYLpDElk=/zoom/1200_630/2026/10/21/khu-vuc-nghi-chon-cat-bo-doi-edited-cropped-1792572873857.jpg","crawledAt":"2026-10-21T13:43:34.513Z"},{"id":"dtri-20261021161438614","title":"Vụ hàng loạt tảng đá \"găm\" trên vỉa hè trường học: Không để tái diễn","slug":"vu-hang-loat-tang-da-gam-tren-via-he-truong-hoc-khong-de-tai-dien","excerpt":"Trước việc nhiều tảng đá được dựng trên vỉa hè trường học tại Đắk Lắk nghi để ngăn ô tô đỗ, gây bức xúc, lãnh đạo địa phương đã chỉ đạo tháo dỡ đá và yêu cầu không được để tình trạng này tái diễn.","content":"(Dân trí) - Trước việc nhiều tảng đá được dựng trên vỉa hè trường học tại Đắk Lắk nghi để ngăn ô tô đỗ, gây bức xúc, lãnh đạo địa phương đã chỉ đạo tháo dỡ đá và yêu cầu không được để tình trạng này tái diễn.\n\nNgày 21/10, lãnh đạo phường Buôn Ma Thuột (Đắk Lắk) cho biết đã chỉ đạo các đơn vị liên quan và Trường THCS Đoàn Thị Điểm không để xảy ra tình trạng đặt đá tảng trên vỉa hè, gây mất mỹ quan đô thị và tiềm ẩn nguy cơ mất an toàn cho học sinh, người đi đường.\n\nTheo lãnh đạo địa phương, nhà trường được yêu cầu tăng cường kiểm tra, giám sát khu vực trước cổng trường. Khi phát hiện đá tảng bị đặt trên vỉa hè, đơn vị cần kịp thời báo cáo cơ quan chức năng để xử lý, không để tình trạng này tái diễn.\n\nThực hiện chỉ đạo của cơ quan chức năng, các tảng đá trát vữa cố định trên vỉa hè đã được tháo dỡ, trả lại mặt bằng thông thoáng, sạch sẽ.\n\nQua ghi nhận, 11 tảng đá với nhiều kích cỡ khác nhau trước Trường THCS Đoàn Thị Điểm đã được di dời. Quá trình tháo dỡ không làm tác động, hư hỏng gạch lát vỉa hè.\n\nTrước đó, hình ảnh những tảng đá nằm dọc vỉa hè trước trường học được một số phụ huynh đưa đón con chụp lại, đăng tải lên mạng xã hội, thu hút sự chú ý của nhiều người.\n\nNhiều ý kiến bày tỏ bức xúc, đặt vấn đề việc làm trên có dấu hiệu xâm phạm tài sản công, gây mất mỹ quan đô thị. Những tảng đá nằm trên lối đi bộ cũng có thể trở thành chướng ngại vật nguy hiểm đối với học sinh và người đi đường, nhất là vào ban đêm.\n\nLiên quan đến sự việc, lãnh đạo Trường THCS Đoàn Thị Điểm khẳng định nhà trường không phải là đơn vị đặt những tảng đá nêu trên.\n\nTheo nhận định của lãnh đạo trường, có thể một số người buôn bán gần khu vực này cảm thấy bất tiện khi ô tô thường xuyên dừng, đỗ trên vỉa hè nên đã đặt đá để ngăn phương tiện.","author":"Trương Nguyễn","category":"Thời sự","publishedAt":"2026-10-21 16:14","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/vu-hang-loat-tang-da-gam-tren-via-he-truong-hoc-khong-de-tai-dien-20261021161438614.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/88tAY8-iWdowWo1_NKNNmwPAtVY=/zoom/1200_630/2026/10/20/da1ctv-edited-cropped-1792500216249.jpg","crawledAt":"2026-10-21T13:42:27.767Z"},{"id":"dtri-20261021161020066","title":"Bị chia tay, người đàn ông khóa cửa đốt phòng trọ của tình cũ","slug":"bi-chia-tay-nguoi-dan-ong-khoa-cua-dot-phong-tro-cua-tinh-cu","excerpt":"Bị người yêu chia tay, Lương Văn Tuấn mang xăng đến phòng trọ của bạn gái cũ, khóa cửa từ bên ngoài rồi châm lửa đốt. Hai người bên trong may mắn được giải cứu.","content":"(Dân trí) - Bị người yêu chia tay, Lương Văn Tuấn mang xăng đến phòng trọ của bạn gái cũ, khóa cửa từ bên ngoài rồi châm lửa đốt. Hai người bên trong may mắn được giải cứu.\n\nNgày 21/10, TAND TP Hà Nội tuyên phạt bị cáo Lương Văn Tuấn (46 tuổi, quê Hưng Yên) mức án 12 năm 9 tháng tù về các tội Giết người và Cố ý làm hư hỏng tài sản.\n\nTheo cáo trạng, khoảng năm 2018, Tuấn có quan hệ tình cảm với chị N.T.K.T. (39 tuổi, cùng quê Hưng Yên).\n\nSau nhiều năm yêu đương, ngày 21/12/2025, chị T. chủ động đề nghị chấm dứt mối quan hệ.\n\nTuy nhiên, Tuấn không chấp nhận, nhiều lần tìm cách níu kéo và luôn bị người yêu từ chối. Bực tức vì bị chia tay, đồng thời biết chị T. có người đàn ông khác, Tuấn nảy sinh ý định sát hại người yêu cũ.\n\nKhoảng 6h30 ngày 24/12/2025, bị cáo điều khiển xe máy đến khu vực cổng thoát hiểm của Công ty Cao su Sao Vàng, đối diện số 79 đường Khương Đình (Hà Nội), nhặt một chai nhựa loại 1,5 lít.\n\nSau đó, bị cáo di chuyển đến đầu ngõ 41 Khương Đình, rút xăng từ xe máy đổ đầy chai nhựa rồi cất vào túi đeo chéo.\n\nChuẩn bị xong, Tuấn tiếp tục điều khiển xe đến khu nhà trọ của chị T. tại phường Khương Đình. Đến nơi, bị cáo dựng xe ở đầu ngõ rồi đi bộ vào trước cửa phòng trọ số 7.\n\nPhát hiện xe máy của chị T. dựng bên ngoài, Tuấn biết người yêu cũ đang ở trong phòng.\n\nLúc này, Tuấn lấy chiếc khóa chữ U mang theo khóa cửa sắt phòng trọ từ bên ngoài, nhằm ngăn người bên trong thoát ra. Tiếp đó, bị cáo lấy chai xăng đổ lên khu vực cửa sắt, cửa sổ bằng gỗ và yên xe máy của chị T.\n\nSau khi tưới xăng, Tuấn đặt chai nhựa lên yên xe máy rồi dùng bật lửa đốt. Khi ngọn lửa bùng lên dữ dội, bị cáo nhanh chóng rời khỏi hiện trường, điều khiển xe máy bỏ trốn. Thời điểm xảy ra vụ cháy, bên trong phòng trọ có chị T. và anh N.C.H. (38 tuổi, ở Hà Nội).\n\nKhi chuẩn bị đi làm, chị T. phát hiện lửa bùng cháy phía ngoài cửa sắt và cửa sổ phòng trọ nên hoảng hốt hô hoán, kêu cứu. Nghe tiếng kêu cứu, những người sống cùng khu trọ lập tức chạy đến dập lửa, đồng thời phá khóa cửa để giải cứu hai người mắc kẹt bên trong.\n\nSau khi thoát nạn, chị T. phát hiện chiếc khóa chữ U dùng để khóa cửa phòng trọ là loại khóa mà trước đó chị từng cho Tuấn sử dụng nên nghi ngờ người yêu cũ chính là thủ phạm.\n\nChị T. gọi điện qua Zalo cho Tuấn nhưng không được. Một lúc sau, Tuấn gọi lại và nói: “Em không bị làm sao à? Chỉ cần em ở bên cạnh tôi thì sẽ không bị làm sao”.\n\nTừ lời nói của Tuấn, chị T. càng có cơ sở nghi ngờ người yêu cũ là người phóng hỏa phòng trọ nên trình báo Công an phường Khương Đình.\n\nVề phía Tuấn, sau khi gây án, bị cáo điều khiển xe máy lên cầu Vĩnh Tuy với ý định tự tử. Tuy nhiên, khi biết chị T. vẫn còn sống, Tuấn từ bỏ ý định nhảy cầu rồi đi lang thang.\n\nĐến khoảng 5h ngày 25/12/2025, bị cáo đến cơ quan công an đầu thú và khai nhận toàn bộ hành vi phạm tội.\n\nQuá trình điều tra xác định, chiếc xe máy của chị T. bị hư hỏng trong vụ phóng hỏa, giá trị tài sản được xác định hơn 2,7 triệu đồng.\n\nVề trách nhiệm dân sự, chị T. và anh H. đều không yêu cầu bị cáo bồi thường thiệt hại về sức khỏe, tài sản.\n\nCả hai nạn nhân còn có đơn đề nghị cơ quan tố tụng xem xét giảm nhẹ hình phạt cho Tuấn.","author":"Nguyễn Hải","category":"Pháp luật","publishedAt":"2026-10-21 16:10","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/bi-chia-tay-nguoi-dan-ong-khoa-cua-dot-phong-tro-cua-tinh-cu-20261021161020066.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/heBqaLw5D_Krc6jDO6o9Wk4Q5YY=/zoom/1200_630/2026/10/21/img9152-cropped-1792573712237.jpg","crawledAt":"2026-10-21T13:42:33.518Z"},{"id":"dtri-20261021160837591","title":"Gã đàn ông đột nhập nhà dân trộm 2,5 cây vàng giữa ban ngày","slug":"ga-dan-ong-dot-nhap-nha-dan-trom-25-cay-vang-giua-ban-ngay","excerpt":"Chủ nhà chỉ đi vắng một lúc, khi trở về phát hiện két sắt bị cạy, 2,5 cây vàng “bốc hơi”.","content":"(Dân trí) - Chủ nhà chỉ đi vắng một lúc, khi trở về phát hiện két sắt bị cạy, 2,5 cây vàng “bốc hơi”.\n\nNgày 21/10, Phòng Cảnh sát hình sự Công an tỉnh Nghệ An đang tạm giữ hình sự Nguyễn Đình An (SN 1993, trú tại xã Yên Trung, tỉnh Nghệ An) về hành vi trộm cắp tài sản.\n\nNgày 8/10, một hộ dân tại xã Nam Đàn (Nghệ An) đến Công an xã trình báo việc bị kẻ gian đột nhập, lấy đi lượng lớn tài sản.\n\nTheo trình bày, cùng ngày, do có việc nên người dân rời nhà một lúc. Khi trở về, chủ nhà tá hỏa phát hiện két sắt bị đục phá, 25,5 chỉ vàng (giá trị khoảng 350 triệu đồng) cất giữ trong két đã “bốc hơi”.\n\nCông an xã Nam Đàn có mặt tại hiện trường, ghi nhận dấu vết ban đầu, đồng thời báo cáo Công an tỉnh Nghệ An về vụ việc.\n\nBằng biện pháp nghiệp vụ, đến ngày 18/10, Phòng Cảnh sát hình sự Công an tỉnh Nghệ An và Công an xã Nam Đàn đồng chủ trì, phối hợp phòng nghiệp vụ (Bộ Công an), Phòng nghiệp vụ Công an tỉnh và công an các địa phương bắt giữ Nguyễn Đình An - nghi can gây ra vụ trộm táo tợn kể trên.\n\nTại cơ quan điều tra, An khai nhận hành vi phạm tội của mình. Để tránh sự phát hiện của cơ quan chức năng, người này tháo biển số xe, dùng khẩu trang và mặc áo dài tay nhằm che giấu nhân dạng.\n\nNguyễn Đình An chia nhỏ số vàng trộm được, đưa đến các tỉnh khác nhau bán để tiêu xài, đánh bạc.\n\nTheo thông tin từ công an, Nguyễn Đình An có 7 tiền án về trộm cắp tài sản và cố ý gây thương tích. An vừa chấp hành xong bản án về tội Trộm cắp tài sản vào tháng 5.","author":"Hoàng Lam","category":"Pháp luật","publishedAt":"2026-10-21 16:08","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/ga-dan-ong-dot-nhap-nha-dan-trom-25-cay-vang-giua-ban-ngay-20261021160837591.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/iGEDrq-OS1MfgCqica3TWO0Nr70=/zoom/1200_630/2026/10/21/7-tien-antrom-vangnghe-anvan-hau-cropped-1792573428149.jpg","crawledAt":"2026-10-21T13:42:30.148Z"},{"id":"dtri-20261021160832930","title":"VN-Index bứt phá, nhóm cổ phiếu của tỷ phú Phạm Nhật Vượng đua tăng trần","slug":"vn-index-but-pha-nhom-co-phieu-cua-ty-phu-pham-nhat-vuong-dua-tang-tran","excerpt":"VN-Index tăng vọt hơn 46 điểm lên 1.738 điểm, khối ngoại bất ngờ đảo chiều mua ròng sau 7 phiên bán liên tiếp, kéo sắc xanh lan rộng toàn thị trường. Điểm nhấn là cổ phiếu VIC, VHM, VRE tăng trần.","content":"(Dân trí) - VN-Index tăng vọt hơn 46 điểm lên 1.738 điểm, khối ngoại bất ngờ đảo chiều mua ròng sau 7 phiên bán liên tiếp, kéo sắc xanh lan rộng toàn thị trường. Điểm nhấn là cổ phiếu VIC, VHM, VRE tăng trần.\n\nKết phiên ngày 21/10, VN-Index tăng hơn 46 điểm, lên 1.738 điểm với 246 mã tăng và 78 mã giảm. Thanh khoản đạt 20.290 tỷ đồng, tương ứng 947 triệu đơn vị được giao dịch.\n\nĐáng chú ý, khối ngoại quay lại mua ròng giá trị 192 tỷ đồng, chấm dứt chuỗi 7 phiên bán ròng liên tiếp. Trong đó, các mã cổ phiếu được nhà đầu tư nước ngoài mua mạnh gồm TCB với 289 tỷ đồng, MSN với 144 tỷ đồng và VIC với 90 tỷ đồng.\n\nỞ chiều ngược lại, cổ phiếu FPT bị bán ròng mạnh nhất với giá trị 173 tỷ đồng, VCB 105 tỷ đồng và ACB 102 tỷ đồng.\n\nNhóm cổ phiếu vốn hóa lớn cũng đồng loạt tăng mạnh. VN30 tăng 35 điểm, lên 1.880 điểm, với khối lượng khớp lệnh 333 triệu đơn vị và thanh khoản đạt 10.350 tỷ đồng.\n\nCổ phiếu VIC của Tập đoàn Vingroup bất ngờ tăng trần 6,99% lên tới 223.600 đồng, đóng góp tới hơn 23 điểm vào đà đi lên của chỉ số chung. Các cổ phiếu khác trong họ Vingroup gồm VHM, VRE, VPL cũng tăng trần hoặc đóng cửa trong sắc xanh.\n\nỞ chiều ngược lại, cổ phiếu PNJ của Công ty cổ phần Vàng bạc đá quý Phú Nhuận (PNJ) quay đầu giảm sau một phiên tăng trần, đóng cửa ở mức 19.200 đồng, giảm 2,78% so với phiên trước.\n\nTrong nhóm cổ phiếu có thanh khoản cao, cổ phiếu VIX của Công ty cổ phần Chứng khoán VIX gây chú ý khi dẫn đầu toàn thị trường về khối lượng khớp lệnh, đạt 51,7 triệu đơn vị. Cổ phiếu này chốt phiên tại 12.650 đồng/đơn vị, tăng 4% so với phiên trước.\n\nĐáng chú ý, diễn biến giao dịch của VIX diễn ra trong bối cảnh kết quả kinh doanh của doanh nghiệp giảm mạnh. Theo báo cáo tài chính quý III vừa công bố, VIX đạt gần 174 tỷ đồng lợi nhuận sau thuế, giảm 93% so với cùng kỳ năm trước. Lũy kế 9 tháng, lợi nhuận sau thuế đạt 388 tỷ đồng, giảm gần 91% so với mức 4.123 tỷ đồng cùng kỳ. Nguyên nhân chủ yếu đến từ sự sụt giảm của mảng tự doanh.\n\nNăm nay, công ty đặt mục tiêu lợi nhuận sau thuế 2.800 tỷ đồng, giảm 48% so với mức kỷ lục 5.410 tỷ đồng đạt được trong năm ngoái. Sau 3/4 chặng đường của năm, VIX mới thực hiện gần 14% kế hoạch lợi nhuận đề ra.","author":"Lê Tỉnh","category":"Kinh doanh","publishedAt":"2026-10-21 16:08","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/vn-index-but-pha-nhom-co-phieu-cua-ty-phu-pham-nhat-vuong-dua-tang-tran-20261021160832930.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/aZ9QLsN9B-fZSMjYnd87NcaUCpk=/zoom/1200_630/2026/10/21/giao-dich-chung-khoan-cropped-cropped-1792573611639.jpg","crawledAt":"2026-10-21T13:42:56.021Z"},{"id":"dtri-20261021160145061","title":"Mỹ đưa đề xuất mới về Ukraine, Nga nêu lập trường ngừng bắn","slug":"my-dua-de-xuat-moi-ve-ukraine-nga-neu-lap-truong-ngung-ban","excerpt":"Nga tuyên bố không ủng hộ lệnh ngừng bắn tạm thời, đồng thời mong muốn Ukraine tham gia vào tiến trình giải quyết xung đột.","content":"(Dân trí) - Nga tuyên bố không ủng hộ lệnh ngừng bắn tạm thời, đồng thời mong muốn Ukraine tham gia vào tiến trình giải quyết xung đột.\n\nNgười phát ngôn Điện Kremlin Dmitry Peskov hôm nay 21/10 cho biết lập trường của Nga về khả năng đạt được một \"thỏa thuận ngừng bắn trong lĩnh vực năng lượng\" với Ukraine vẫn không thay đổi.\n\nTheo ông Peskov, Moscow tìm kiếm hòa bình lâu dài, chứ không phải một lệnh ngừng bắn tạm thời.\n\n\"Không có gì thay đổi. Chúng tôi cần hòa bình, chứ không phải một lệnh ngừng bắn”, ông Peskov nêu rõ.\n\nTrước đó, ngày 11/10, Tổng thống Mỹ Donald Trump bất ngờ tuyên bố trên mạng xã hội rằng Nga và Ukraine đã đồng ý ngừng bắn về năng lượng. Tuy nhiên, chỉ vài ngày sau, thực tế trên chiến trường và các phát ngôn chính thức từ Moscow cũng như Kiev cho thấy “lệnh ngừng bắn năng lượng” này gần như tan vỡ ngay từ khi chưa kịp hình thành.\n\nĐến giữa tháng 10, các cuộc tấn công lẫn nhau vào cơ sở hạ tầng năng lượng vẫn tiếp diễn. Phía Ukraine cáo buộc quân đội Nga vi phạm lệnh ngừng bắn, trong khi Điện Kremlin khẳng định không thể nói đến việc vi phạm lệnh ngừng bắn vì các điều khoản chưa được xác định rõ ràng.\n\nNga nhiều lần phản đối đề xuất ngừng bắn tạm thời với Ukraine. Moscow cho rằng lệnh ngừng bắn sẽ cho phép Kiev có thêm thời gian để tái vũ trang và tiến hành các đợt tấn công mới, thay vì giải quyết triệt để cuộc xung đột.\n\nSự tham gia của Ukraine\n\nNgười phát ngôn Điện Kremlin Dmitry Peskov hôm nay nhấn mạnh, không thể đạt được giải pháp toàn diện cho cuộc xung đột Ukraine nếu thiếu sự tham gia của Kiev.\n\n“Không thể giải quyết triệt để vấn đề Ukraine mà không có đại diện từ phía Kiev. Do vậy, cần ai đó ở Kiev đưa ra một quyết định có trách nhiệm. Điều này vô cùng cần thiết”, ông Peskov nói thêm.\n\nTrước đó, trong tuyên bố ngày 19/10, ông Peskov cũng khẳng định, đối với Nga, điều quan trọng là các cuộc đàm phán hòa bình phải có sự tham gia của một đại diện hợp pháp từ chính quyền Ukraine - người sẵn sàng đưa ra quyết định nhằm chấm dứt xung đột.\n\n\"Điều quan trọng đối với chúng tôi là phải đảm bảo có một đại diện hợp pháp của chính quyền, người sẵn sàng chịu trách nhiệm và đưa ra những quyết định cần thiết để chấm dứt cuộc chiến\", ông Peskov nói thêm.\n\nTuyên bố của ông Peskov được đưa ra sau khi Tổng thống Trump nói rằng Ukraine nên tìm kiếm một người khác đại diện cho Kiev để đàm phán chấm dứt xung đột với Nga, thay vì Tổng thống Volodymyr Zelensky.\n\nTrước đó, vào ngày 10/10, ông Trump cũng kêu gọi Ukraine tìm nhà lãnh đạo mới có thể đạt thỏa thuận với Nga. Nhà lãnh đạo Mỹ cho rằng Ukraine nên tiến hành bầu cử trong bối cảnh nhiệm kỳ của Tổng thống Zelensky đã kết thúc.\n\nTheo đánh giá của ông Trump, ông Zelensky không có nhiều nỗ lực để góp phần đưa cuộc chiến đi đến hồi kết.\n\nGần đây ông Trump liên tục chỉ trích ông Zelensky, cho rằng nhà lãnh đạo Ukraine đã bỏ lỡ cơ hội đạt được thỏa thuận hòa bình tốt hơn với Nga. Theo ông Trump, Tổng thống Zelensky chưa bao giờ muốn chấm dứt xung đột với Nga.\n\nÔng Trump cũng cáo buộc Ukraine cố tình nhắm mục tiêu vào các nhà máy lọc dầu của Nga nhằm gây tổn hại cho đảng Cộng hòa Mỹ trong cuộc bầu cử giữa kỳ ngày 3/11. Theo ông Trump, các cuộc tấn công của Ukraine cũng gây tổn hại nghiêm trọng đến thị trường dầu diesel toàn cầu, trong đó có cả thị trường Mỹ, và khiến giá dầu tăng vọt.\n\nVề phần mình, Tổng thống Zelensky tuyên bố Ukraine sẵn sàng ngừng các cuộc tấn công vào các nhà máy lọc dầu của Nga trong 30 ngày theo yêu cầu của Tổng thống Trump, với điều kiện Washington cung cấp cho Kiev các tên lửa đánh chặn Patriot.\n\nTổng thống Putin tiếp Đặc phái viên Mỹ\n\nTrợ lý Điện Kremlin, ông Yury Ushakov, cho biết Tổng thống Nga Vladimir Putin sẽ tiếp Đặc phái viên Mỹ Steve Witkoff vào cuối ngày 21/10.\n\nÔng Ushakov xác nhận cuộc gặp này đã được lên kế hoạch và thống nhất từ ​​trước. Theo ông, các cuộc thảo luận giữa Tổng thống Nga và Đặc phái viên Mỹ sẽ tập trung vào việc giải quyết xung đột tại Ukraine.\n\n\"Sự kiện hôm nay tất nhiên sẽ xoay quanh các cuộc đàm phán về xung đột ở Ukraine”, trợ lý Điện Kremlin nhấn mạnh.\n\nTrợ lý Điện Kremlin tiết lộ ông Kirill Dmitriev, đặc phái viên của Tổng thống Nga về hợp tác đầu tư và kinh tế với nước ngoài, đồng thời là người đứng đầu Quỹ Đầu tư Trực tiếp Nga (RDIF), sẽ cùng tham gia cuộc gặp giữa ông Putin và ông Witkoff tại St. Petersburg.\n\nTrước chuyến thăm của Đặc phái viên Mỹ tới Nga, Đặc phái viên Witkoff đã có cuộc gặp với Tổng thống Zelensky và các nhà lãnh đạo châu Âu và NATO.\n\nNgoại trưởng Mỹ Marco Rubio xác nhận ông Witkoff “được trang bị những đề xuất mới về hòa bình và sẽ chia sẻ với phía Nga” trong chuyến thăm lần này.\n\nKhi chia sẻ về kỳ vọng đối với các cuộc đàm phán sắp tới của ông Witkoff tại St. Petersburg, nhà ngoại giao hàng đầu của Mỹ cho biết sự kiện này sẽ cho thấy liệu có thể đạt được tiến triển nào hướng tới việc giải quyết xung đột Ukraine hay không.\n\n\"Tuy nhiên, như tôi đã nói, những vấn đề này rất phức tạp. Nếu đây là một cuộc chiến dễ giải quyết, thì nó đã được giải quyết từ lâu rồi\", ông Rubio nhận định.","author":"Thành Đạt","category":"Thế giới","publishedAt":"2026-10-21 16:01","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/my-dua-de-xuat-moi-ve-ukraine-nga-neu-lap-truong-ngung-ban-20261021160145061.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/hz4QahloU9Ps99PgMdyIEL0ob_I=/zoom/1200_630/2026/10/21/peskov-tass-1-cropped-1792573241504.jpg","crawledAt":"2026-10-21T13:42:21.106Z"},{"id":"dtri-20261021154934690","title":"Tài xế taxi chạy ngược chiều tại trạm thu phí ở TPHCM bị phạt 19 triệu đồng","slug":"tai-xe-taxi-chay-nguoc-chieu-tai-tram-thu-phi-o-tphcm-bi-phat-19-trieu-dong","excerpt":"Tài xế taxi công nghệ chạy ngược chiều tại khu vực trạm thu phí xa lộ Hà Nội (TPHCM) vừa bị CSGT lập biên bản xử phạt 19 triệu đồng và trừ 4 điểm giấy phép lái xe.","content":"(Dân trí) - Tài xế taxi công nghệ chạy ngược chiều tại khu vực trạm thu phí xa lộ Hà Nội (TPHCM) vừa bị CSGT lập biên bản xử phạt 19 triệu đồng và trừ 4 điểm giấy phép lái xe.\n\nNgày 21/10, Đội CSGT Cát Lái thuộc Phòng CSGT (PC08, Công an TPHCM) đã lập biên bản vi phạm hành chính đối với một tài xế taxi có hành vi chạy ngược chiều tại khu vực trạm thu phí xa lộ Hà Nội.\n\nTheo quy định, tài xế này bị xử phạt 19 triệu đồng và trừ 4 điểm giấy phép lái xe.\n\nTrước đó, chiều 17/9, nam tài xế điều khiển taxi chạy ngược chiều trên đường Võ Nguyên Giáp, đoạn qua khu vực trạm thu phí xa lộ Hà Nội (phường Thủ Đức, TPHCM), dù tại đây có biển báo cấm đi ngược chiều.\n\nSự việc được camera hành trình của một người đi đường ghi lại, sau đó gửi đến cơ quan chức năng phản ánh.\n\nTiếp nhận thông tin, Đội CSGT Cát Lái đã gửi thông báo, yêu cầu chủ phương tiện và tài xế đến trụ sở làm việc để xác minh, xử lý theo quy định.\n\nTại cơ quan công an, nam tài xế thừa nhận hành vi vi phạm và chấp hành việc xử lý theo quy định pháp luật.\n\nLực lượng CSGT khuyến cáo, người tham gia giao thông nghiêm chỉnh chấp hành hệ thống báo hiệu đường bộ, tuyệt đối không đi ngược chiều, đặc biệt tại các trạm thu phí và nút giao có mật độ phương tiện cao. Hành vi này tiềm ẩn nguy cơ va chạm trực diện, có thể dẫn đến tai nạn giao thông nghiêm trọng.\n\nCơ quan chức năng cũng khuyến khích người dân cung cấp hình ảnh, video ghi nhận các hành vi vi phạm giao thông để lực lượng chức năng tiếp nhận, xác minh và xử lý theo quy định pháp luật.","author":"Hoàng Hướng","category":"Pháp luật","publishedAt":"2026-10-21 15:49","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/tai-xe-taxi-chay-nguoc-chieu-tai-tram-thu-phi-o-tphcm-bi-phat-19-trieu-dong-20261021154934690.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/Ko86H6TDzle_boAQe9NyraS-iKg=/zoom/1200_630/2026/10/21/nca-cropped-cropped-1792572521068.jpg","crawledAt":"2026-10-21T13:42:32.423Z"},{"id":"dtri-20261021153245494","title":"Tuồn 400 tấn heo bệnh ra thị trường, thu lợi 10 tỷ đồng ở Đồng Nai","slug":"tuon-400-tan-heo-benh-ra-thi-truong-thu-loi-10-ty-dong-o-dong-nai","excerpt":"Công an TP Đồng Nai đã khởi tố, bắt tạm giam 9 người trong đường dây thu mua, giết mổ và tiêu thụ khoảng 400 tấn heo bệnh, heo chết làm thực phẩm, với số tiền thu lợi bất chính hơn 10 tỷ đồng.","content":"(Dân trí) - Công an TP Đồng Nai đã khởi tố, bắt tạm giam 9 người trong đường dây thu mua, giết mổ và tiêu thụ khoảng 400 tấn heo bệnh, heo chết làm thực phẩm, với số tiền thu lợi bất chính hơn 10 tỷ đồng.\n\nNgày 21/10, Cơ quan Cảnh sát điều tra Công an TP Đồng Nai đã khởi tố vụ án, khởi tố bị can, bắt tạm giam 9 đối tượng về tội Vi phạm quy định về an toàn thực phẩm.\n\nCác bị can gồm: Trần Văn Hùng (SN 1975, cầm đầu đường dây), Huỳnh Thị Hiếu Em (vợ Hùng), Trần Thị Cẩm Bào (SN 1992), Nguyễn Thị Thu Phượng (SN 1975), Nguyễn Hồng Phúc (SN 2002), Phạm Thị Hân (cùng ngụ TP Đồng Nai); Trịnh Thanh Lâm (SN 1987), Lê Quốc Phó (SN 2000, cùng ngụ tỉnh An Giang) và Nguyễn Thành Trung (SN 2005, ngụ tỉnh Lâm Đồng).\n\nTrước đó, đầu tháng 9, lực lượng chức năng phát hiện nhóm đối tượng chuyên thu gom, vận chuyển, giết mổ heo bệnh, heo chết để bán ra thị trường tại phường Xuân Lộc, xã Xuân Hòa và khu vực lân cận. Đến ngày 5/10, công an đồng loạt kiểm tra 5 địa điểm thu gom, giết mổ, chế biến, qua đó thu giữ khoảng 7 tấn thịt heo chết nhiễm virus dịch tả heo châu Phi cùng nhiều tang vật liên quan.\n\nTheo điều tra ban đầu, từ năm 2024, Hùng và vợ tổ chức thu mua heo bệnh, heo chết từ nhiều cá nhân, điểm thu gom và trạm trung chuyển đưa về địa điểm giết mổ tại phường Xuân Lộc. Tại đây, Hùng thuê Lâm lái xe vận chuyển, đồng thời chỉ đạo các nhân công giết mổ, pha lóc thành thịt nạc, ba chỉ, thịt đùi, còn phần da và mỡ tiếp tục chế biến.\n\nSau đó, Hùng giao cho Bào liên hệ tiêu thụ, bán cho Phượng với giá 25.000-40.000 đồng/kg. Phượng tiếp tục bán trực tiếp cho người dân tại khu vực cổng Khu công nghiệp Xuân Lộc và cung cấp cho Hân làm giò chả với giá 35.000-55.000 đồng/kg.\n\nDù biết rõ nguồn gốc heo bệnh, heo chết nhưng các đối tượng vẫn tổ chức giết mổ, chế biến bán ra thị trường. Cơ quan công an xác định từ năm 2024 đến nay, đường dây này đã giết mổ khoảng 400 tấn heo bệnh, heo chết, thu lợi bất chính hơn 10 tỷ đồng.\n\nHiện vụ án được tiếp tục điều tra mở rộng.","author":"Phước Tuần","category":"Pháp luật","publishedAt":"2026-10-21 15:32","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/tuon-400-tan-heo-benh-ra-thi-truong-thu-loi-10-ty-dong-o-dong-nai-20261021153245494.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/78REtleQmTTw0_C6H9qobNe9lfQ=/zoom/1200_630/2026/10/21/heo3-edited-cropped-1792571482213.jpg","crawledAt":"2026-10-21T13:42:33.538Z"},{"id":"dtri-20261021152812494","title":"Cuộc sống của người Việt những ngày biểu tình căng thẳng ở Pháp","slug":"cuoc-song-cua-nguoi-viet-nhung-ngay-bieu-tinh-cang-thang-o-phap","excerpt":"Đang đi mua sắm, chị Nguyệt Ánh bất ngờ gặp đoàn biểu tình và nhìn rõ các đám khói mù mịt. Người phụ nữ nhanh chóng trở về nhà để đảm bảo an toàn.","content":"(Dân trí) - Đang đi mua sắm, chị Nguyệt Ánh bất ngờ gặp đoàn biểu tình và nhìn rõ các đám khói mù mịt. Người phụ nữ nhanh chóng trở về nhà để đảm bảo an toàn.\n\nLo lắng an toàn, bố mẹ khuyên con về nước\n\nNgày 21/10, Minh Hằng, du học sinh Việt Nam tại Pháp nhận thông báo trở lại học trực tiếp sau một số ngày trường học đóng cửa vì bị ảnh hưởng bởi các cuộc biểu tình.\n\nKhông chỉ học tập, cuộc sống của cô gái cũng ít nhiều chịu xáo trộn khi làn sóng biểu tình bạo lực lan rộng ở Paris và các thành phố tại Pháp.\n\nTrước đó, cô đã sống ở Hà Lan 3 năm và từng chứng kiến một số cuộc biểu tình diễn ra dưới hình thức tuần hành, hô khẩu hiệu. Bởi vậy, khi chứng kiến cảnh người biểu tình đập phá, đốt đồ đạc, cô rất hoảng sợ.\n\nNgày 17/10, Hằng đến trường học nhưng trường thông báo đóng cửa. Trên đường về, cô thấy rất đông thanh niên, người lao động xuống đường. Một số có hành vi quá khích, đập phá cửa hàng, phóng hỏa, gây hỗn loạn. Cô liền nhanh chóng trở về nhà để đảm bảo an toàn.\n\nQuan sát nhanh cô nhận thấy, người biểu tình chủ yếu tập trung ở khu vực trung tâm, nơi dễ thu hút sự chú ý. Các khu dân cư nhìn chung ít bị ảnh hưởng trực tiếp.\n\nTheo lời kể của Hằng, lực lượng an ninh được huy động đến các khu vực biểu tình. Tuy nhiên, trước số lượng người tham gia đông, tình hình tại một số điểm vẫn diễn biến phức tạp.\n\nBạn trai người Pháp của Minh Hằng chia sẻ với cô rằng, cuộc biểu tình năm nay căng thẳng hơn nhiều năm trước đó. Cơ sở làm việc của anh cũng bị ảnh hưởng và buộc phải đóng cửa sớm vào 15h mỗi ngày thay vì 20h như thường lệ.\n\nCác cuộc biểu tình cũng khiến giao thông bị gián đoạn. Hằng cho biết, trong một số ngày, phương tiện giao thông công cộng bị chậm chuyến hoặc hủy chuyến khiến cô phải chờ lâu, đi bộ về hoặc tìm phương án di chuyển khác. Trong khi đó, việc mua sắm thực phẩm và các nhu yếu phẩm vẫn diễn ra tương đối bình thường.\n\nNhững hình ảnh hỗn loạn khiến gia đình Hằng ở Việt Nam không khỏi lo lắng. Bố mẹ cô khuyên con gái cân nhắc trở về nước vì sợ con gặp nguy hiểm.\n\nHằng cho biết, cô hiểu sự lo lắng của gia đình, nhưng bản thân đã sang Pháp học tập, đóng học phí và bắt đầu ổn định cuộc sống nên không muốn trở về chỉ vì tình hình căng thẳng nhất thời. Khi nhận thấy mọi thứ dần trở lại bình thường, cô cũng yên tâm hơn.\n\nHạn chế ra ngoài, không đến nơi tập trung đông người\n\nSinh sống ở Strasbourg, Pháp khoảng 3 năm, chị Vũ Nguyệt Ánh cho biết, những ngày qua gia đình chị hạn chế đi ra ngoài và không đến những khu vực tập trung đông người.\n\nTrước đó, ngày 17/10, chị đưa con trai vào trung tâm thành phố để mua đồ chuẩn bị cho buổi gặp gỡ bạn bè người Việt ngày 20/10. Đến nơi, chị thấy cảnh sát mặc đồ bảo hộ xuất hiện trên đường.\n\nDi chuyển tiếp một đoạn, chị gặp các đoàn người dài dằng dặc, vừa đi vừa hô khẩu hiệu, giơ biểu ngữ. Thỉnh thoảng, chị lại nghe rõ tiếng ầm lớn và nhìn thấy các đám khói mù mịt.\n\n“Lúc đó tôi rất lo lắng, vừa đi vừa run. May mắn khi ấy có lực lượng cảnh sát đảm bảo an ninh, người biểu tình cũng chưa có biểu hiện gì quá khích, nên tôi nhanh chóng mua đồ rồi trở về nhà”, chị Nguyệt Ánh nhớ lại.\n\nVề nhà theo dõi tin tức, người phụ nữ Việt nhận ra, ở nhiều nơi trên nước Pháp, người dân cũng có những cuộc xuống đường tương tự.\n\nTheo chị Nguyệt Ánh, các cuộc biểu tình khiến giao thông một số tuyến phố trung tâm bị ùn tắc, người dân mất nhiều thời gian di chuyển. Nhiều cửa hàng bị đập phá, một số công trình công cộng bị tấn công.\n\nCuộc sống ở các khu dân cư về cơ bản vẫn diễn ra bình thường. Tại nơi chị sinh sống, các gia đình vẫn có thể đi siêu thị, đưa con đi học gần nhà.\n\n“Dù cuộc sống không bị xáo trộn quá nhiều, song tôi mong tình hình sớm ổn định”, người phụ nữ Việt cho biết.\n\nLiên quan đến các cuộc biểu tình ở Pháp vừa qua, Tổng thống Pháp Emmanuel Macron đã lên tiếng chỉ trích tình trạng bạo lực khi các nhóm phá hoại lợi dụng những cuộc biểu tình ôn hòa để thực hiện hành vi cướp bóc, đốt phá.\n\n“Khi xem những hình ảnh này, tất cả chúng ta đều tự hỏi làm sao người Pháp có thể làm những điều như vậy với nước Pháp?”, ông nói trong bài phát biểu được truyền hình trực tiếp.\n\nÔng Macron tuyên bố không gì có thể biện minh cho các hành vi bạo lực và cho biết các quan chức nhà nước tại địa phương có thể cấm một số cuộc tụ tập trên đường phố nếu xét thấy cần thiết.\n\nÔng nói cần phân biệt giữa những người biểu tình thực sự, ôn hòa, đưa ra các đề xuất liên quan đến chi phí sinh hoạt và hệ thống giáo dục, với những đối tượng “phá hoại, đập phá và cướp bóc”.\n\nTrước đó, phong trào tuần hành ở Pháp đã thu hút hàng chục nghìn người tham gia. Họ tiến hành một cách ôn hòa, trong trật tự ở các thành phố lớn, trong đó có Paris, để ủng hộ yêu cầu của học sinh về việc tăng số lượng giáo viên và sửa chữa trường học bị xuống cấp.\n\nTuy nhiên, tách biệt với những cuộc biểu tình ôn hòa này, nhiều nhóm đối tượng đã liên tục di chuyển giữa các địa điểm tụ tập, phóng hỏa rải rác, dựng rào chắn trên đường phố và đụng độ với cảnh sát tại các thành phố như Paris, Bordeaux, Nice và Marseille. Sau đó, nhiều phần tử đã lợi dụng tình hình để tiến hành các vụ cướp bóc cửa hàng, đập phá bạo lực.","author":"Hồng Anh","category":"Đời sống","publishedAt":"2026-10-21 15:28","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/cuoc-song-cua-nguoi-viet-nhung-ngay-bieu-tinh-cang-thang-o-phap-20261021152812494.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/MJr1TjFXt_LNGcmozMbj1PL1F0g=/zoom/1200_630/2026/10/21/phap-2-cropped-1792571150812.jpg","crawledAt":"2026-10-21T13:42:41.148Z"},{"id":"dtri-20261021152512917","title":"Nhật Kim Anh tái xuất điện ảnh sau 3 năm, phim mới bất ngờ dời lịch chiếu","slug":"nhat-kim-anh-tai-xuat-dien-anh-sau-3-nam-phim-moi-bat-ngo-doi-lich-chieu","excerpt":"Phim “Mẹ Mìn” đánh dấu sự trở lại màn ảnh rộng của Nhật Kim Anh sau 3 năm. Mới đây, nhà sản xuất bất ngờ thông báo dời lịch khởi chiếu sát ngày ra rạp.","content":"(Dân trí) - Phim “Mẹ Mìn” đánh dấu sự trở lại màn ảnh rộng của Nhật Kim Anh sau 3 năm. Mới đây, nhà sản xuất bất ngờ thông báo dời lịch khởi chiếu sát ngày ra rạp.\n\nNhà sản xuất phim Mẹ Mìn vừa thông báo dời lịch khởi chiếu từ ngày 23/10 sang 27/11, muộn hơn một tháng so với kế hoạch ban đầu. Thông tin được công bố sát ngày phim dự kiến ra rạp, thu hút sự chú ý của khán giả.\n\nTheo nhà sản xuất, việc điều chỉnh lịch phát hành nhằm có thêm thời gian hoàn thiện tác phẩm, mang đến trải nghiệm điện ảnh chỉn chu hơn cho người xem.\n\n“Chúng tôi mong muốn Mẹ Mìn khi ra mắt có thể truyền tải trọn vẹn tinh thần và cảm xúc mà bộ phim hướng đến. Việc điều chỉnh lịch chiếu là cơ hội để ê-kíp tiếp tục hoàn thiện tác phẩm, từ những yếu tố kinh dị, tâm linh đến chiều sâu tâm lý nhân vật”, đại diện nhà sản xuất chia sẻ.\n\nMẹ Mìn do Jack Carry On đạo diễn, thuộc thể loại tâm lý, giật gân pha trộn yếu tố kỳ bí. Bộ phim khai thác hình tượng “mẹ mìn” trong những câu chuyện truyền miệng dân gian, vốn từng là nỗi khiếp sợ của nhiều thế hệ trẻ em Việt Nam.\n\nCùng với thông báo dời lịch, nhà sản xuất tung trailer mới, hé lộ thêm nhiều tình tiết đáng chú ý xoay quanh các nhân vật do Minh Hằng, Nhật Kim Anh, Khương Lê và Rima Thanh Vy đảm nhận.\n\nTrong phim, Mẹ Mìn (Minh Hằng) là một thực thể bí ẩn có khả năng biến những điều ước của con người thành hiện thực. Tuy nhiên, để đạt được mong muốn, mỗi người phải chấp nhận một bản giao kèo với những điều kiện khắt khe cùng cái giá đắt đỏ.\n\nMẹ Mìn cũng đánh dấu sự trở lại màn ảnh rộng của Nhật Kim Anh sau 3 năm vắng bóng. Nữ diễn viên đảm nhận vai mẹ Hạnh, một người phụ nữ có cuộc sống hôn nhân nhiều sóng gió, mang tổn thương và nỗi day dứt về quá khứ.\n\n“Đây là nhân vật người mẹ mà tôi rất thương và vô cùng tâm huyết trong lần trở lại”, Nhật Kim Anh chia sẻ.\n\nDù bận rộn chăm sóc con nhỏ, Nhật Kim Anh vẫn cố gắng sắp xếp, cân bằng thời gian giữa gia đình và công việc để trở lại nghệ thuật.\n\n“Tôi vừa làm cha vừa làm mẹ nên rất cực. Nhưng lần này, kịch bản hay và ê-kíp làm phim chuyên nghiệp khiến tôi hào hứng. Tôi cũng có áp lực, lo lắng không biết sự trở lại của mình có đủ tốt và được khán giả đón nhận hay không”, Nhật Kim Anh bộc bạch.\n\nNữ diễn viên cũng dành lời khen cho bạn diễn Khương Lê. “Khương Lê là một diễn viên trẻ, tuy chưa có nhiều vai diễn nhưng tôi thấy kỹ năng diễn xuất của bạn vô cùng chuyên nghiệp và bạn có tâm với nghề”, cô nhận xét.\n\nỞ tuổi 41, Nhật Kim Anh chấp nhận cô bước qua thời đỉnh cao của danh xưng “nữ hoàng phim truyền hình”, song cô không bận tâm chuyện ganh đua vị trí. Hiện cô ưu tiên lựa chọn những kịch bản phù hợp, dành thời gian đầu tư cho từng nhân vật và xây dựng dấu ấn riêng trong diễn xuất.\n\n“Tính tôi không bao giờ chạy show hay nhận đóng nhiều phim cùng lúc. Phải hoàn thành một bộ phim, tôi mới tính đến dự án tiếp theo để không ảnh hưởng đến cảm xúc dành cho từng vai diễn. Đó cũng là lý do mọi người thấy tôi ít đóng phim”, nữ diễn viên chia sẻ.","author":"Bích Phương","category":"Giải trí","publishedAt":"2026-10-21 15:25","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/nhat-kim-anh-tai-xuat-dien-anh-sau-3-nam-phim-moi-bat-ngo-doi-lich-chieu-20261021152512917.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/nW8kztLd3dxytBQ_7xFm4wEod-8=/zoom/1200_630/2026/10/21/2aobor72fnx4fnggq7nphgyvjfxp9rwlyqhsn7b2-cropped-1792570983002.jpg","crawledAt":"2026-10-21T13:43:13.885Z"},{"id":"dtri-20261021151937781","title":"Vinhomes có động thái mới tại siêu dự án 926.000 tỷ đồng ở Hà Nội","slug":"vinhomes-co-dong-thai-moi-tai-sieu-du-an-926000-ty-dong-o-ha-noi","excerpt":"Vinhomes vừa thông qua việc sửa đổi hợp đồng liên danh thực hiện dự án Khu đô thị thể thao quốc tế Hà Nội, bổ sung cơ chế huy động vốn và sử dụng tài sản dự án để bảo đảm nghĩa vụ.","content":"(Dân trí) - Vinhomes vừa thông qua việc sửa đổi hợp đồng liên danh thực hiện dự án Khu đô thị thể thao quốc tế Hà Nội, bổ sung cơ chế huy động vốn và sử dụng tài sản dự án để bảo đảm nghĩa vụ.\n\nCông ty cổ phần Vinhomes (mã chứng khoán: VHM) vừa công bố thông tin về việc Hội đồng quản trị (HĐQT) thông qua sửa đổi, bổ sung hợp đồng liên danh chủ đầu tư dự án Khu đô thị thể thao quốc tế Hà Nội.\n\nTheo đó, ngày 19/10, HĐQT Vinhomes ban hành Nghị quyết số 55 thông qua việc điều chỉnh hợp đồng liên danh ký ngày 10/12/2025. Những thay đổi tập trung vào cơ cấu thành viên, tổ chức quản lý dự án và cơ chế huy động vốn.\n\nCụ thể, sau quá trình sáp nhập doanh nghiệp, Công ty cổ phần Đầu tư Bất động sản Ngọc Hồi đã sáp nhập vào Công ty cổ phần VinFast Việt Nam. Trong khi đó, Công ty cổ phần Nghiên cứu Đầu tư và Phát triển Tương Lai sáp nhập vào Công ty cổ phần Sản xuất và Kinh doanh VinFast. Doanh nghiệp nhận sáp nhập sau đó đổi tên thành Công ty cổ phần Sản xuất, Đầu tư và Phát triển Tương Lai.\n\nHai doanh nghiệp nhận sáp nhập kế thừa toàn bộ quyền, nghĩa vụ và tư cách thành viên của các pháp nhân trước đó trong hợp đồng liên danh.\n\nSau điều chỉnh, liên danh thực hiện dự án gồm Vinhomes, VinFast Việt Nam, Công ty TNHH Đầu tư và Phát triển Thương mại Ngọc Quý và Công ty cổ phần Sản xuất, Đầu tư và Phát triển Tương Lai. Trong đó, VinFast Việt Nam và Công ty cổ phần Sản xuất, Đầu tư và Phát triển Tương Lai là các bên liên quan của Vinhomes.\n\nBên cạnh việc thay đổi thành viên, hợp đồng liên danh được bổ sung quy định về tổ chức quản lý và huy động vốn. Theo đó, liên danh sẽ thành lập Ban Quản lý dự án để quản lý hoạt động đầu tư, vận hành dự án. Mỗi thành viên có trách nhiệm và được phép đại diện liên danh huy động vốn phục vụ quá trình triển khai.\n\nĐáng chú ý, Vinhomes, với tỷ lệ tham gia liên danh 35%, được quyền sử dụng tài sản hoặc quyền tài sản thuộc dự án để bảo đảm nghĩa vụ của doanh nghiệp, với điều kiện có sự đồng ý của các thành viên còn lại.\n\nVinhomes cũng có thể sử dụng phần tài sản dự án được phân bổ tương ứng với tỷ lệ tham gia 35% để bảo đảm nghĩa vụ của bất kỳ thành viên nào trong liên danh, bao gồm VinFast Việt Nam và Công ty cổ phần Sản xuất, Đầu tư và Phát triển Tương Lai. Giá trị nghĩa vụ được bảo đảm phải nằm trong thẩm quyền phê duyệt của Hội đồng quản trị Vinhomes.\n\nKhu đô thị thể thao quốc tế Hà Nội có diện tích khoảng 9.171ha, tổng vốn đầu tư dự kiến khoảng 925.700 tỷ đồng. Dự án được định hướng phát triển thành khu đô thị kết hợp các công trình thể thao, thương mại, dịch vụ và nhà ở tại khu vực phía nam Thủ đô.\n\nMột trong những hạng mục đáng chú ý là sân vận động VinFast - Trống Đồng, dự kiến có sức chứa 135.000 chỗ ngồi.","author":"Ghi Du","category":"Bất động sản","publishedAt":"2026-10-21 15:19","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/vinhomes-co-dong-thai-moi-tai-sieu-du-an-926000-ty-dong-o-ha-noi-20261021151937781.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/xYvbByQ_bFibUCkZNYWCDr2z4o8=/zoom/1200_630/2026/10/21/vinhomes-co-dong-thai-moi-tai-sieu-du-an-926-edited-cropped-1792570711955.jpg","crawledAt":"2026-10-21T13:42:58.218Z"},{"id":"dtri-20261021150833029","title":"Xe Lexus của bà Trương Mỹ Lan có chủ mới với giá 600 triệu đồng","slug":"xe-lexus-cua-ba-truong-my-lan-co-chu-moi-voi-gia-600-trieu-dong","excerpt":"Sau nhiều lần đấu giá không thành, chiếc ô tô Lexus liên quan bà Trương Mỹ Lan đã được bán thành công với giá 600 triệu đồng, thấp hơn hơn 150 triệu đồng so với mức khởi điểm ban đầu.","content":"(Dân trí) - Sau nhiều lần đấu giá không thành, chiếc ô tô Lexus liên quan bà Trương Mỹ Lan đã được bán thành công với giá 600 triệu đồng, thấp hơn hơn 150 triệu đồng so với mức khởi điểm ban đầu.\n\nNgày 21/10, Thi hành án dân sự TPHCM thông báo chấm dứt áp dụng biện pháp tạm dừng đăng ký, chuyển quyền sở hữu, sử dụng và thay đổi hiện trạng đối với ô tô biển số 51A-942.85 liên quan bà Trương Mỹ Lan.\n\nTheo cơ quan thi hành án, căn cứ kết quả đấu giá thành công chiếc xe do Trung tâm Dịch vụ đấu giá tài sản TPHCM tổ chức, việc tiếp tục áp dụng biện pháp ngăn chặn nhằm tránh chuyển quyền sở hữu, sử dụng, tẩu tán, hủy hoại hoặc thay đổi hiện trạng tài sản là không còn cần thiết.\n\nHồi tháng 9, Trung tâm Dịch vụ đấu giá tài sản TPHCM đã đấu giá thành công chiếc Lexus 5 chỗ, màu đen, biển số 51A-942.85, với giá 600 triệu đồng. Người trúng đấu giá là ông T. (ngụ TPHCM).\n\nChiếc xe được đưa ra đấu giá lần đầu vào tháng 5, với giá khởi điểm hơn 750 triệu đồng. Sau nhiều lần đấu giá không thành và giảm giá, tài sản được bán thành công ở mức 600 triệu đồng.\n\nNhiều bất động sản liên quan bà Trương Mỹ Lan tiếp tục được đấu giá\n\nTrong tháng 10 và tháng 11, Thi hành án dân sự TPHCM dự kiến tổ chức đấu giá nhiều bất động sản liên quan bà Trương Mỹ Lan nhằm thu hồi tiền thi hành án, bảo đảm nghĩa vụ hoàn trả hơn 30.081 tỷ đồng cho hơn 43.100 bị hại mua trái phiếu.\n\nTài sản thứ nhất là nhà đất tại số 142 Võ Văn Tần, phường Xuân Hòa, với giá khởi điểm hơn 94 tỷ đồng. Tài sản thứ hai là căn biệt thự tại số 22B Nguyễn Thị Diệu, phường Xuân Hòa, có giá khởi điểm hơn 202,5 tỷ đồng.\n\nTài sản thứ ba là căn hộ tại tầng 2, số 25 Đồng Khởi, phường Sài Gòn, với giá khởi điểm hơn 41 tỷ đồng. Tài sản thứ tư là nhà đất tại số 151 Đồng Khởi, phường Sài Gòn, có giá khởi điểm hơn 37,3 tỷ đồng.\n\nNgày 12/11, cơ quan thi hành án dự kiến tổ chức đấu giá hai tài sản tại số 7 Hàm Nghi, phường Sài Gòn, với tổng giá khởi điểm hơn 161,2 tỷ đồng.\n\nCũng trong ngày 12/11, tài sản tại số 12-14 Nguyễn Thiệp (tầng 4), phường Sài Gòn, dự kiến được đưa ra đấu giá với giá khởi điểm 19,5 tỷ đồng.\n\nBên cạnh các tài sản đã có lịch đấu giá, một số bất động sản liên quan bà Trương Mỹ Lan đã được định giá và đang chờ xác định thời gian bán đấu giá với trị giá hơn 1.000 tỷ đồng.\n\nTrước đó, Thi hành án dân sự TPHCM đã đấu giá thành công nhiều bất động sản liên quan bà Lan. Trong đó, nhà đất tại số 44 Trần Đình Xu, phường Cầu Ông Lãnh, được bán với giá 635 tỷ đồng; nhà đất tại số 64-68 Trần Quốc Thảo, phường Xuân Hòa, có giá trúng đấu giá 647 tỷ đồng.\n\nNgoài bất động sản, nhiều tài sản khác liên quan bà Lan cũng đã được đấu giá thành công, gồm hai chiếc túi Hermès với tổng giá trúng đấu giá 13,3 tỷ đồng, ô tô Maybach giá 16,6 tỷ đồng, ô tô BMW giá 879 triệu đồng và bộ trang sức kim cương với giá trúng đấu giá gần 25 tỷ đồng.","author":"Xuân Duy","category":"Xe ++","publishedAt":"2026-10-21 15:08","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/xe-lexus-cua-ba-truong-my-lan-co-chu-moi-voi-gia-600-trieu-dong-20261021150833029.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/__ZibVFLHSFv7ExlChsUOau4IEE=/zoom/1200_630/2026/10/21/179256996413118668955814270010228059889764723040908d752669b561313615d039a082fe2bb41-cropped-1792570040217.jpg","crawledAt":"2026-10-21T13:43:26.786Z"},{"id":"dtri-20261021150534556","title":"Xác minh clip 2 cô giáo mầm non ở Thanh Hóa tát học sinh tại lớp học","slug":"xac-minh-clip-2-co-giao-mam-non-o-thanh-hoa-tat-hoc-sinh-tai-lop-hoc","excerpt":"Một clip ghi lại cảnh 2 giáo viên mầm non ở Thanh Hóa có hành vi đánh học sinh ngay tại lớp học đang gây bức xúc trên mạng xã hội.","content":"(Dân trí) - Một clip ghi lại cảnh 2 giáo viên mầm non ở Thanh Hóa có hành vi đánh học sinh ngay tại lớp học đang gây bức xúc trên mạng xã hội.\n\nTheo nội dung clip được đăng tải, trong giờ học vẽ, một bé gái đang học bài, bị 2 cô giáo dùng tay tát vào má. Hai giáo viên còn có lời nói to tiếng với cháu bé.\n\nQua tìm hiểu, sự việc xảy ra tại phân hiệu mầm non Lộc Tân, Trường Mầm non Hậu Lộc, xã Hậu Lộc, tỉnh Thanh Hóa.\n\nChiều 21/10, bà Nguyễn Thị Liên, Hiệu trưởng Trường Mầm non Hậu Lộc, xác nhận sự việc xảy ra vào trưa cùng ngày tại phân hiệu mầm non Lộc Tân. Hai giáo viên xuất hiện trong clip được xác định là cô B. và cô L..\n\nTheo bà Liên, sau khi tiếp nhận thông tin, nhà trường đang yêu cầu các giáo viên liên quan viết bản tường trình, đồng thời xác minh vụ việc để xử lý theo quy định.","author":"Khôi Nguyên","category":"Giáo dục","publishedAt":"2026-10-21 15:05","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/xac-minh-clip-2-co-giao-mam-non-o-thanh-hoa-tat-hoc-sinh-tai-lop-hoc-20261021150534556.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/g6uRcYz_Wiv7drjq6j0mWFRB2Ho=/zoom/1200_630/2026/10/21/mam-nonthanh-hoa2311111-edited-cropped-1792569759408.jpg","crawledAt":"2026-10-21T13:43:21.077Z"},{"id":"dtri-20261021150356930","title":"Thu Minh nói về Hương Tràm sau 14 năm: \"Em xứng đáng với mọi thứ đang có\"","slug":"thu-minh-noi-ve-huong-tram-sau-14-nam-em-xung-dang-voi-moi-thu-dang-co","excerpt":"Sau 14 năm kể từ Giọng hát Việt 2012, Thu Minh và Hương Tràm mới có dịp đứng chung sân khấu. Suốt quãng thời gian đó, mối quan hệ thầy trò giữa hai ca sĩ từng vướng không ít đồn đoán.","content":"(Dân trí) - Sau 14 năm kể từ Giọng hát Việt 2012, Thu Minh và Hương Tràm mới có dịp đứng chung sân khấu. Suốt quãng thời gian đó, mối quan hệ thầy trò giữa hai ca sĩ từng vướng không ít đồn đoán.\n\nGần đây, sự xuất hiện của Thu Minh trong liveshow Phao cứu sinh của Hương Tràm tại Hà Nội thu hút sự chú ý. Thu Minh và Hương Tràm bén duyên từ chương trình Giọng hát Việt 2012. Khi ấy, Hương Tràm mới 17 tuổi, được Thu Minh dìu dắt và trở thành quán quân cuộc thi. Sau hơn một thập kỷ, cả hai mới có dịp tái ngộ trên sân khấu liveshow riêng của Hương Tràm tại Hà Nội.\n\nMới đây, Hương Tràm chia sẻ đoạn video ghi lại buổi tập luyện bí mật cùng giọng ca Đường cong. Trong clip, Thu Minh đã có những chia sẻ đầy cảm xúc về hành trình trưởng thành của học trò.\n\n“Tôi rất tự hào về Hương Tràm. Cô bé này đến với tôi từ năm 17 tuổi. Đây thực sự là một trong những giọng ca nội lực hàng đầu Việt Nam”, Thu Minh nói.\n\nNữ ca sĩ cho biết cô tự hào khi được chứng kiến những ngày đầu Hương Tràm bước vào con đường ca hát, nhìn thấy nội lực tiềm tàng và sự nỗ lực của đàn em. Thu Minh nói, nếu tại Giọng hát Việt 2012, cô là huấn luyện viên tìm cách giúp học trò tỏa sáng, thì hiện tại, cô nhìn Hương Tràm như một đồng nghiệp.\n\n“Ngày đó, ở vai trò là người thầy, tôi phải giúp thí sinh Hương Tràm nổi bật hết cỡ. Nhưng hôm nay, Hương Tràm đã là một cộng sự, một đồng nghiệp của tôi. Tôi sẽ không \"nương tay\" khi đứng chung sân khấu và Hương Tràm sẽ phải tự mình chứng minh năng lực”, Thu Minh chia sẻ.\n\nTrong đêm nhạc, Thu Minh cũng xúc động khi nhắc đến những thăng trầm mà cả hai đã trải qua. Cô cho rằng những niềm vui, nỗi buồn, thành công và vấp ngã đều là hành trang giúp mỗi người trưởng thành, mạnh mẽ hơn.\n\n“Suốt 14 năm qua, chị chưa bao giờ nhìn em khác đi. You are always my baby (tạm dịch: Em luôn là em gái nhỏ của chị - PV)\", Thu Minh nói với học trò.\n\nĐáp lại những lời tâm tình của Thu Minh, Hương Tràm nghẹn ngào nhìn lại hành trình sau Giọng hát Việt 2012. Nữ ca sĩ cho biết cô đã trải qua nhiều chặng đường, có thành công và cả những lần vấp ngã, nhưng chưa bao giờ cảm thấy mình phải đơn độc.\n\n“Mỗi lần em nhắn tin cho chị, dù là lúc vui hay lúc khó khăn nhất, chị đều luôn trả lời, luôn lắng nghe và ở đó để động viên em”, Hương Tràm chia sẻ.\n\nVới nữ ca sĩ, việc vẫn được Thu Minh gọi là “baby của chị” sau nhiều năm là điều hạnh phúc và quý giá. Cô gửi lời cảm ơn người thầy vì đã luôn tin tưởng, yêu thương và dõi theo mình trên chặng đường đã qua.\n\nKhông chỉ bày tỏ niềm tự hào, Thu Minh còn gửi lời động viên học trò trong lần trở lại này. Cô mong Hương Tràm bình tâm trước những vui buồn trong sự nghiệp, đồng thời xem giai đoạn chững lại như khoảng thời gian cần thiết để tìm lại sự bình yên.\n\n“Chúc những bước đi sắp tới của em sẽ nhận được sự đồng cảm, ủng hộ của khán giả. Với giọng ca của Hương Tràm, chắc chắn em sẽ làm được nhiều hơn nữa. Hãy làm Thu Minh tự hào vì đã có một người học trò như Hương Tràm nhé”, nữ ca sĩ nhắn nhủ.","author":"Quỳnh Tâm","category":"Giải trí","publishedAt":"2026-10-21 15:03","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/thu-minh-noi-ve-huong-tram-sau-14-nam-em-xung-dang-voi-moi-thu-dang-co-20261021150356930.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/nAOkv5Wjg97FsZuoVZQzuSIZooE=/zoom/1200_630/2026/10/21/76399264615852761363013699125032825167320312n-cropped-1792569558512.jpg","crawledAt":"2026-10-21T13:43:10.572Z"},{"id":"dtri-20261021150252471","title":"Đặc phái viên Mỹ mang đề xuất hòa bình Ukraine mới đến Nga","slug":"dac-phai-vien-my-mang-de-xuat-hoa-binh-ukraine-moi-den-nga","excerpt":"Đặc phái viên của Tổng thống Mỹ Donald Trump, ông Steve Witkoff, hôm nay 21/10 đã tới thành phố St. Petersburg để thảo luận với Tổng thống Nga Vladimir Putin về xung đột Ukraine.","content":"(Dân trí) - Đặc phái viên của Tổng thống Mỹ Donald Trump, ông Steve Witkoff, hôm nay 21/10 đã tới thành phố St. Petersburg để thảo luận với Tổng thống Nga Vladimir Putin về xung đột Ukraine.\n\nTheo hãng tin TASS, đặc phái viên Nga về đầu tư, ông Kirill Dmitriev, đã đón ông Witkoff tại sân bay Pulkovo. Các video được chia sẻ trên mạng xã hội cho thấy đoàn xe của ông Witkoff rời sân bay.\n\nCác cuộc đàm phán đang được tổ chức có từ thế kỷ 18, nằm cách thành phố St. Petersburg khoảng 20 km về phía đông nam.\n\nTrợ lý chính sách đối ngoại của Điện Kremlin, ông Yury Ushakov, cho biết cuộc hội đàm giữa ông Putin và ông Witkoff sẽ diễn ra tại Cung điện Constantine, xoay quanh cuộc xung đột tại Ukraine. Ông tiết lộ thêm rằng cuộc gặp đã được lên kế hoạch từ vài ngày trước.\n\nÔng cho hay, phía Mỹ đã thông báo con rể Tổng thống Mỹ Donald Trump, doanh nhân Jared Kushner, bị ốm nên không đến St. Petersburg tham dự cuộc hội đàm theo kế hoạch ban đầu.\n\nÔng Ushakov cũng khẳng định các quan chức Nga không có bất kỳ tiếp xúc nào với Tổng thống Ukraine Volodymyr Zelensky ở thời điểm hiện tại.\n\nTrước cuộc đàm phán tại St. Petersburg, người phát ngôn Điện Kremlin Dmitry Peskov Peskov cho biết Moscow đánh giá mỗi cuộc gặp giữa ông Putin và các đặc phái viên của ông Trump là \"rất quan trọng và đúng thời điểm\".\n\nÔng cũng nêu rõ, Moscow không thay đổi lập trường về một lệnh ngừng bắn năng lượng tiềm tàng với Ukraine. Ông nhấn mạnh, Nga “cần hòa bình, chứ không phải một lệnh đình chiến\".\n\nNgoại trưởng Nga Sergei Lavrov cũng tuyên bố Nga sẽ cân nhắc các sáng kiến kinh tế \"có lợi cho chúng tôi\", nhưng loại trừ khả năng đưa ra các nhượng bộ chính trị đơn phương, đồng thời lưu ý rằng các chính quyền Mỹ trong tương lai sẽ không bị ràng buộc bởi quyết định của những người tiền nhiệm.\n\nChuyến thăm của ông Witkoff diễn ra ngay sau cuộc hội đàm của ông với Tổng thống Ukraine Volodymyr Zelensky và các nhà lãnh đạo châu Âu và NATO.\n\nNgoại trưởng Mỹ Marco Rubio mô tả các cuộc thảo luận trên là \"tích cực\". Ông cho biết, đặc phái viên Witkoff \"giờ đây, được trang bị những đề xuất mới về hòa bình và sẽ chia sẻ với phía Nga. “Hãy cùng chờ xem liệu chúng ta có thể đạt được tiến triển nào không\", ông nói.\n\nMột quan chức Mỹ giấu tên chia sẻ, các cuộc đàm phán tại Oslo đã bao hàm các cam kết bảo đảm an ninh, một kế hoạch kinh tế hậu chiến và một cấu trúc an ninh rộng lớn hơn cho châu Âu. Washington hy vọng nỗ lực tiếp cận này sẽ mở đường cho các cuộc đàm phán 3 bên trực tiếp giữa Nga, Ukraine và Mỹ.\n\nTrong các cuộc đàm phán tại Oslo, các đặc phái viên đã gây áp lực buộc Ukraine phải dừng các cuộc tấn công vào các nhà máy lọc dầu của Nga.","author":"Minh Phương","category":"Thế giới","publishedAt":"2026-10-21 15:02","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/dac-phai-vien-my-mang-de-xuat-hoa-binh-ukraine-moi-den-nga-20261021150252471.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/3GeyXgAWokzqxCrAnUB3GB1Uxtw=/zoom/1200_630/2026/10/21/dac-phai-vien-my-reuters011zon-cropped-1792569711050.jpg","crawledAt":"2026-10-21T13:42:22.191Z"},{"id":"dtri-20261021145625109","title":"Trung Quốc: Thót tim cảnh giải cứu bé 3 tuổi mắc kẹt lơ lửng ở tầng 12","slug":"trung-quoc-thot-tim-canh-giai-cuu-be-3-tuoi-mac-ket-lo-lung-o-tang","excerpt":"Bé gái 3 tuổi bị kẹt đầu vào ban công, trong khi phần dưới lơ lửng tại tầng 12 của một tòa nhà tại Trung Quốc.","content":"(Dân trí) - Bé gái 3 tuổi bị kẹt đầu vào ban công, trong khi phần dưới lơ lửng tại tầng 12 của một tòa nhà tại Trung Quốc.\n\nCảnh sát, người dân, lực lượng cứu hỏa Trung Quốc đã chung tay giải cứu một bé gái 3 tuổi bị treo lơ lửng bên ngoài cửa sổ một tòa nhà cao tầng, trong khi đầu mắc kẹt giữa các thanh chắn an toàn.\n\nBé gái suýt gặp thảm kịch sau khi trèo ra khỏi căn hộ ở tầng 12, nhưng những người hàng xóm nhanh trí đã lập tức hành động, cứu bé khỏi bị trượt xuống thấp hơn.\n\nĐoạn video ghi lại vụ việc diễn ra tại một khu chung cư ở tỉnh Phúc Kiến, ven biển phía đông nam Trung Quốc, hôm 17/10.\n\nTrong một đoạn video, có thể thấy hai người đàn ông từ căn hộ bên dưới vươn tay lên, đồng thời giữ một chiếc ghế bên dưới bé gái.\n\nSau đó, một cảnh sát xuất hiện, hỗ trợ 2 người đàn ông và giữ chiếc ghế cố định cho đến khi lực lượng cứu hỏa đến.\n\nTrong đoạn video sau đó, một lính cứu hỏa dùng dụng cụ cắt xuyên qua các thanh chắn kim loại, khiến tia lửa bắn tung tóe, nhằm giải phóng phần đầu bị mắc kẹt của bé gái.\n\nSau đó, bé được bế ra nơi an toàn. Theo SCMP, mẹ của bé đã để con ngủ một mình trong căn hộ, trong lúc bà ra ngoài mua thực phẩm.\n\nBé gái được đưa đến bệnh viện để kiểm tra nhưng không bị thương.\n\nVụ việc xảy ra chỉ vài tuần sau khi hai người đàn ông Trung Quốc cứu một bé trai 5 tuổi bị treo bên ngoài cửa sổ tầng 6 tại thành phố Sóc Châu, Trung Quốc.","author":"Đức Hoàng","category":"Thế giới","publishedAt":"2026-10-21 14:56","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/trung-quoc-thot-tim-canh-giai-cuu-be-3-tuoi-mac-ket-lo-lung-o-tang-12-20261021145625109.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/WwFfojmahsyeIYN1nKP8lamJ9hg=/zoom/1200_630/2026/10/21/trung-quoc-thot-tim-canh-giai-cuu-be-3-tuoi-mac-ket-lo-lung-o-tang-12-cropped-1792569231184.jpg","crawledAt":"2026-10-21T13:42:22.170Z"},{"id":"dtri-20261021144853398","title":"Khởi tố nam sinh lớp 12 đấm cô giáo trên bục giảng ở Hà Nội","slug":"khoi-to-nam-sinh-lop-12-dam-co-giao-tren-buc-giang-o-ha-noi","excerpt":"Theo cơ quan chức năng, trong tiết toán sáng 19/10, V. và một số bạn khác bị phạt đứng góc lớp do không làm bài tập về nhà. Bực tức, V. đã đánh cô giáo chủ nhiệm của mình.","content":"(Dân trí) - Theo cơ quan chức năng, trong tiết toán sáng 19/10, V. và một số bạn khác bị phạt đứng góc lớp do không làm bài tập về nhà. Bực tức, V. đã đánh cô giáo chủ nhiệm của mình.\n\nNgày 21/10, Cơ quan Cảnh sát điều tra Công an TP Hà Nội đã khởi tố bị can, bắt tạm giam L.V.H. (17 tuổi, nam sinh lớp 12 trường THPT Mạc Đĩnh Chi) về tội Cố ý gây thương tích.\n\nTrước đó liên quan vụ nam sinh đấm cô giáo tại trường THPT Mạc Đĩnh Chi, ngày 21/10, Công an xã Nội Bài, TP Hà Nội, đã tạm giữ khẩn cấp nam sinh L.H.V. để điều tra về hành vi cố ý gây thương tích.\n\nLúc 10h10 ngày 19/10, trong tiết toán do cô Lê Thị Hòa giảng dạy tại lớp 12D5, V. và một số bạn không làm bài tập về nhà nên bị cô Hòa phạt đứng góc lớp trên bục giảng.\n\nBực tức vì bị phạt, trong lúc cô Hòa đang đứng quay lưng về phía V., nam sinh này đã tiến đến đánh cô Hòa. Khi được các bạn trong lớp can ngăn, V. dừng lại. Cô Hòa được đưa đi cấp cứu tại Bệnh viện Lạc Việt, tỉnh Phú Thọ, trong tình trạng gãy mũi phải.\n\nTheo nhà chức trách, cô Lê Thị Hòa là giáo viên chủ nhiệm của V. từ năm lớp 10 đến nay, đồng thời đang là giáo viên dạy bộ môn toán lớp 12D5.\n\nCông an xã Nội Bài đang phối hợp với các cơ quan chức năng tiến hành điều tra, xử lý theo quy định","author":"Hải Nam","category":"Pháp luật","publishedAt":"2026-10-21 14:48","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/khoi-to-nam-sinh-lop-12-dam-co-giao-tren-buc-giang-o-ha-noi-20261021144853398.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/o8hyB8SHm9_HIVbJFOXtNbyCVsw=/zoom/1200_630/2026/10/21/anh-man-hinh-2026-10-21-luc-085230-1792547728238811453767-cropped-1792568886552.jpg","crawledAt":"2026-10-21T13:42:34.627Z"},{"id":"dtri-20261021143931184","title":"Ukraine báo động về kho vũ khí Nga: 700 tên lửa đạn đạo, 6.200 UAV","slug":"ukraine-bao-dong-ve-kho-vu-khi-nga-700-ten-lua-dan-dao-6200-uav","excerpt":"Theo Cơ quan Tình báo Quốc phòng Ukraine (HUR), Nga đã tích lũy tới 700 tên lửa đạn đạo, vài nghìn tên lửa hành trình và hơn 6.000 UAV tấn công để tập kích Ukraine.","content":"(Dân trí) - Theo Cơ quan Tình báo Quốc phòng Ukraine (HUR), Nga đã tích lũy tới 700 tên lửa đạn đạo, vài nghìn tên lửa hành trình và hơn 6.000 UAV tấn công để tập kích Ukraine.\n\nCác số liệu do hãng truyền thông Ukraine NV công bố cho thấy Moscow tiếp tục mở rộng sản xuất vũ khí, đồng thời duy trì lượng dự trữ đáng kể để tiến hành các cuộc tấn công kéo dài.\n\nSản lượng phương tiện bay không người lái (UAV) hằng tháng của Nga đã đạt 10.000 chiếc, bao gồm UAV tấn công và UAV mồi nhử được thiết kế nhằm gây quá tải cho hệ thống phòng không Ukraine.\n\nTheo HUR, Nga hiện có khoảng 115 tên lửa đạn đạo Iskander-M trong kho dự trữ và sản xuất tới 65 quả mỗi tháng.\n\nMoscow cũng đang phát triển phiên bản cải tiến của hệ thống này, với tầm bắn ước tính 550-700km, so với 500km của phiên bản hiện tại.\n\nTên lửa hành trình Kh-101 tiếp tục là một vũ khí chủ lực trong các cuộc tập kích quy mô lớn của Nga nhằm vào Ukraine, với sản lượng hằng tháng vượt 80 quả.\n\nNga cũng sở hữu hơn 450 tên lửa hành trình phóng từ biển Kalibr, với sản lượng khoảng 29 quả mỗi tháng. HUR cho biết hiệu quả của hệ thống phòng không Ukraine đã khiến Nga phải đưa phần lớn tên lửa Kalibr mới sản xuất vào kho dự trữ chiến lược và sử dụng số tên lửa này để trang bị cho các hạm đội.\n\nKho vũ khí của Nga còn có tới 400 tên lửa RM-48U, được cải biến từ tên lửa của các hệ thống phòng không S-300PM và S-400 để tấn công các mục tiêu mặt đất. Nga sản xuất khoảng 40 quả tên lửa thuộc loại này mỗi tháng.\n\nMoscow sở hữu hơn 600 tên lửa chống hạm Oniks phiên bản cải tiến, có tầm bắn xa hơn và đầu đạn mạnh hơn. Hơn 55 quả tên lửa đã được sản xuất trong 7 tháng đầu năm 2026.\n\nKho dự trữ của Nga còn có hơn 120 tên lửa siêu vượt âm Zircon, mặc dù sản lượng vẫn tương đối thấp, với chỉ hơn 30 quả được sản xuất kể từ đầu năm.\n\nTheo HUR, Nga đã tạm ngừng sản xuất tên lửa đạn đạo phóng từ trên không Kinzhal, đồng thời chuyển năng lực sản xuất sang các loại tên lửa đạn đạo thông thường.\n\nNga đã mở rộng đáng kể hoạt động sản xuất UAV cảm tử tầm xa tại Khu kinh tế đặc biệt Alabuga, thuộc vùng Tatarstan.\n\nTheo tình báo Ukraine, đơn đặt hàng của nhà nước Nga đối với UAV tấn công Geran và UAV mồi nhử đã vượt 100.000 chiếc trong năm nay.\n\nNga hiện duy trì lượng dự trữ tác chiến khoảng 6.200 UAV Geran thuộc nhiều biến thể, trong đó có các mẫu sử dụng động cơ phản lực.\n\nKể từ mùa hè, Moscow tập trung sản xuất các UAV Geran-4 và Geran-5 sử dụng động cơ phản lực, với sản lượng lên tới 4.000 chiếc mỗi tháng.\n\nNga tiếp tục sản xuất tới 2.000 UAV Geran-2 mỗi tháng, bên cạnh hàng trăm UAV mồi nhử Gerbera giá rẻ hơn, được chế tạo từ ván ép và xốp.\n\nCác UAV mồi nhử này nhằm làm cạn kiệt nguồn lực phòng không Ukraine và giúp Nga xác định vị trí các hệ thống tên lửa đất đối không của Ukraine.\n\nHUR cho biết sản lượng UAV ngày càng tăng của Nga phản ánh chiến lược có hệ thống nhằm bào mòn năng lực phòng không Ukraine thông qua các đợt tập kích liên tiếp.\n\nNhững đánh giá mới nhất được đưa ra sau một loạt cảnh báo của tình báo Ukraine về khả năng duy trì chiến dịch tập kích bằng tên lửa của Nga.\n\nHồi tháng 6, HUR cho biết Nga có thể phóng tới 100 tên lửa đạn đạo mỗi tháng mà không làm cạn kiệt kho dự trữ chủ lực.\n\nTháng 8, ông Vadym Skibitsky, Phó Cục trưởng HUR, cho biết tổ hợp công nghiệp - quân sự Nga đã vượt chỉ tiêu sản xuất tên lửa từ 110% đến 120%, đồng thời cảnh báo không nên kỳ vọng các cuộc tập kích sẽ tạm dừng.\n\nTháng 9, ông Skibitsky cho biết Nga dự kiến hoàn tất thử nghiệm một loại tên lửa đạn đạo mới có tầm bắn lên tới 800km vào cuối năm 2026.","author":"Đức Hoàng","category":"Thế giới","publishedAt":"2026-10-21 14:39","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/ukraine-bao-dong-ve-kho-vu-khi-nga-700-ten-lua-dan-dao-6200-uav-20261021143931184.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/zDQ-lc9nKUwNp_zua7JhkIh2DTg=/zoom/1200_630/2026/10/21/ten-lua-ngaafp-cropped-1792568224584.jpg","crawledAt":"2026-10-21T13:42:23.250Z"},{"id":"dtri-20261021143810680","title":"Hà Nội: Nam thanh niên bị vòng kim loại siết chặt vùng bìu suốt 10 ngày","slug":"ha-noi-nam-thanh-nien-bi-vong-kim-loai-siet-chat-vung-biu-suot-10-ngay","excerpt":"Vì tò mò và mong muốn có trải nghiệm mới lạ, một nam thanh niên 24 tuổi ở Hà Nội đã tự đeo vòng kim loại không rõ nguồn gốc vào vùng bìu.","content":"(Dân trí) - Vì tò mò và mong muốn có trải nghiệm mới lạ, một nam thanh niên 24 tuổi ở Hà Nội đã tự đeo vòng kim loại không rõ nguồn gốc vào vùng bìu.\n\nBệnh viện Bệnh Nhiệt đới Trung ương vừa tiếp nhận, phẫu thuật cấp cứu cho anh K.V. (24 tuổi, Hà Nội) trong tình trạng tổn thương vùng bìu nghiêm trọng do bị chiếc vòng kim loại siết chặt kéo dài.\n\nTheo thông tin từ người bệnh, với mong muốn kéo dài thời gian cương cứng và khiến vùng kín trông to, đầy đặn hơn, anh V. đã tự sử dụng một chiếc vòng kim loại đeo quanh vùng bìu.\n\nTuy nhiên, chiếc vòng có đường kính chỉ khoảng 3cm không co giãn, khiến vùng bìu bị thắt chặt ngay sau khi đeo. Vùng bìu bị thắt lại phù nề, sưng to làm cho vòng càng thít chặt hơn.\n\nAnh V. nhiều lần tìm cách tự tháo vòng tại nhà nhưng không thành công. Mỗi lần cố tháo vòng, vùng bìu càng sưng nề, đau nhức dữ dội.\n\nDo vòng kim loại cứng liên tục chèn ép và cọ xát, vùng da ở gốc bìu và hai bên bẹn của người bệnh dần bị trợt loét, nhiễm trùng và chảy mủ. Dù tình trạng ngày càng nghiêm trọng, vì tâm lý e ngại, xấu hổ, anh V. vẫn chần chừ và chỉ đến Bệnh viện Bệnh Nhiệt đới Trung ương sau 10 ngày gặp sự cố.\n\nBSCKI Trần Duy Hiến, khoa Ngoại Tổng hợp Tiết niệu và Nam học, cho biết, khi nhập viện, vùng bìu của người bệnh sưng to nghiêm trọng, vùng gốc bìu chảy mủ, tổn thương da có dấu hiệu hoại tử.\n\n“Ngay lập tức, chúng tôi khẩn trương chuyển người bệnh lên phòng mổ cấp cứu để can thiệp. Điều lo ngại nhất là tình trạng chèn ép kéo dài suốt 10 ngày có thể đã khiến máu không lưu thông đầy đủ đến hai bên tinh hoàn, dẫn đến hoại tử và buộc phải cắt bỏ”, BSCKI Trần Duy Hiến cho biết.\n\nViệc tháo chiếc vòng gặp nhiều khó khăn do kim loại rất cứng, có độ dày khoảng 3mm.\n\nĐể tránh gây thêm tổn thương cho các mô mềm xung quanh, ê-kíp phẫu thuật phải sử dụng dụng cụ chuyên dụng, cẩn trọng cắt đứt hai bên vòng kim loại mới có thể giải phóng vùng bìu bị chèn ép.\n\nRất may, sau khi tháo vòng, các bác sĩ kiểm tra và nhận thấy hai bên tinh hoàn vẫn còn hồng hào, chưa có dấu hiệu hoại tử. Ê-kíp tiếp tục loại bỏ những phần da bị loét, hoại tử do chèn ép và cọ xát, làm sạch vết thương, đặt ống dẫn lưu và khâu tạo hình vùng tổn thương.\n\nTừ trường hợp trên, các bác sĩ khuyến cáo nam giới cần thận trọng khi sử dụng các dụng cụ tác động trực tiếp lên vùng sinh dục. Khi xảy ra sự cố mắc kẹt vòng, sưng đau hoặc tổn thương vùng kín, cần đến ngay cơ sở y tế để được xử trí kịp thời.\n\nTuyệt đối không cố tự tháo vòng bằng các dụng cụ không phù hợp. Đặc biệt, không vì tâm lý e ngại, xấu hổ mà trì hoãn thăm khám, bởi việc xử trí chậm trễ có thể khiến tổn thương nghiêm trọng hơn, đe dọa chức năng sinh dục và sức khỏe sinh sản.","author":"Minh Nhật","category":"Sức khỏe","publishedAt":"2026-10-21 14:38","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/ha-noi-nam-thanh-nien-bi-vong-kim-loai-siet-chat-vung-biu-suot-10-ngay-20261021143810680.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/phNsw5tzP2omvU1JtE3p5n-v1dY=/zoom/1200_630/2026/10/21/biu-2-cropped-1792568146978.jpg","crawledAt":"2026-10-21T13:42:36.828Z"},{"id":"dtri-20261021143857503","title":"4 game thủ Việt Nam dự siêu giải đấu ở Hàn Quốc với tiền thưởng 6,5 tỷ đồng","slug":"4-game-thu-viet-nam-du-sieu-giai-dau-o-han-quoc-voi-tien-thuong-65-ty-dong","excerpt":"Hôm nay (21/10), 4 game thủ Việt Nam là Anh Tú, Hoàng Bảo, Gia Nam và Công Đạo sẽ tranh tài tại FC Pro Mobile World Championship 2026, giải đấu cao nhất trong hệ thống thi đấu của môn bóng đá điện tử.","content":"(Dân trí) - Hôm nay (21/10), 4 game thủ Việt Nam là Anh Tú, Hoàng Bảo, Gia Nam và Công Đạo sẽ tranh tài tại FC Pro Mobile World Championship 2026, giải đấu cao nhất trong hệ thống thi đấu của môn bóng đá điện tử.\n\nGiải FC Pro Mobile World Championship 2026 diễn ra từ ngày 21/10 đến ngày 25/10 tại Seoul (Hàn Quốc). Giải đấu quy tụ 32 game thủ vượt qua các vòng tuyển chọn quốc tế, khu vực và quốc nội.\n\nTổng quỹ thưởng của siêu giải đấu này là 250.000 USD (khoảng 6,5 tỉ đồng), trong đó nhà vô địch nhận 60.000 USD, á quân nhận 40.000 USD. Đây cũng là giải vô địch thế giới (World Championship) đầu tiên của hệ thống FC Pro Mobile.\n\nBốn đại diện của Việt Nam thi đấu cá nhân, mỗi người cạnh tranh một vị trí và danh hiệu riêng. Điều đó có nghĩa rằng họ hoàn toàn có thể đối đầu với nhau trên hành trình chinh phục chức vô địch.\n\nHành trình giành vé của các game thủ đi qua hai con đường. Phạm Anh Tú và Nguyễn Hoàng Bảo lần lượt vô địch, á quân FC Mobile Vietnam Super League mùa xuân 2026 (FVSL Spring). Nhờ đó, họ góp mặt ở Mid-Season Playoffs ở Bangkok, Thái Lan, từ ngày 6/8 đến ngày 9/8.\n\nTại giải đấu đó, Anh Tú đã giành ngôi á quân, còn Hoàng Bảo lọt top 8 game thủ xuất sắc nhất. Do đó, họ đủ điều kiện giành vé tham dự World Championship.\n\nHai suất còn lại thuộc về Lê Gia Nam và Nguyễn Công Đạo, những người lần lượt đứng thứ ba, thứ tư tại FVSL Summer 2026. Họ được tham dự khi hai người đứng đầu là Anh Tú và Hoàng Bảo có suất tham dự thông qua giải quốc tế.\n\nTheo quy định EA, một tuyển thủ chỉ nhận suất qua một con đường. Nếu vé trùng được chuyển theo điều lệ giải liên quan. Vì thế, Việt Nam có hai đại diện từ Mid-Season và hai người thông qua giải quốc nội.\n\nTrong 4 game thủ của Việt Nam, Anh Tú là người được kỳ vọng nhất. Anh từng giành ngôi á quân ở giải Mid-Season (Thái Lan) và nhận 20.000 USD tiền thưởng. Trước đó, VĐV này vô địch FVSL Spring với tiền thưởng 80 triệu đồng.\n\nHoàng Bảo là đương kim vô địch giải FVSL Summer (thắng Anh Tú trong trận chung kết). Gia Nam sinh năm 1998. Game thủ này đăng quang Invitation Cup tại Vietnam GameVerse ngày 9-5, nhận 7.000 USD. Tại giải đấu đó, Gia Nam từng thắng cả Hoàng Bảo lẫn Anh Tú. Ở giải FVSL Summer, Gia Nam xếp thứ 3. Công Đạo duy trì sự ổn định khi xếp thứ 4 ở cả FVSL Spring và FVSL Summer.\n\nTại World Championship, 32 tuyển thủ chia thành tám bảng, mỗi bảng chọn 2 người đi tiếp. Vòng 16 người đánh tối đa 3 ván; tứ kết, bán kết tối đa 5 ván; chung kết tối đa 7 ván. Người thắng 4 ván ở trận cuối sẽ trở thành nhà vô địch FC Pro Mobile thế giới đầu tiên.","author":"H. Long","category":"Thể thao","publishedAt":"2026-10-21 14:38","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/4-game-thu-viet-nam-du-sieu-giai-dau-o-han-quoc-voi-tien-thuong-65-ty-dong-20261021143857503.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/_wyWpf5D_l8cC41vPp_wt_cxkSY=/zoom/1200_630/2026/10/21/images-cropped-1792568270727.jpg","crawledAt":"2026-10-21T13:43:06.088Z"},{"id":"dtri-20261021143740323","title":"Trứng gà thả vườn giá gấp đôi gà công nghiệp vẫn hút khách","slug":"trung-ga-tha-vuon-gia-gap-doi-ga-cong-nghiep-van-hut-khach","excerpt":"Trứng gà thả vườn, chăn nuôi theo hướng nhân đạo có giá bán gấp đôi trứng công nghiệp nhưng vẫn hút khách. Đây là hướng đi giúp hộ chăn nuôi nhỏ lẻ tìm chỗ đứng trước sức ép từ trang trại lớn.","content":"(Dân trí) - Trứng gà thả vườn, chăn nuôi theo hướng nhân đạo có giá bán gấp đôi trứng công nghiệp nhưng vẫn hút khách. Đây là hướng đi giúp hộ chăn nuôi nhỏ lẻ tìm chỗ đứng trước sức ép từ trang trại lớn.\n\nTại Triển lãm Quốc tế chuyên ngành Chăn nuôi, Thức ăn chăn nuôi và Chế biến thịt tại Việt Nam (Vietstock 2026), diễn ra sáng 21/10 tại TPHCM, bài toán nâng cao sức cạnh tranh của ngành chăn nuôi tiếp tục được đặt ra, nhất là với các hộ nông dân có quy mô sản xuất nhỏ.\n\nÔng Phạm Kim Đăng, Phó Cục trưởng Cục Chăn nuôi và Thú y (Bộ Nông nghiệp và Môi trường) cho biết, trong 9 tháng đầu năm nay, tăng trưởng ngành chăn nuôi đạt gần 5%.\n\nTổng sản lượng thịt hơi các loại đạt 6,83 triệu tấn, tăng 5%. Sản lượng trứng đạt 15,7 tỷ quả, sữa tươi khoảng 1 triệu tấn. Xuất khẩu sản phẩm chăn nuôi ước đạt 564 triệu USD, tăng 24,6% so với cùng kỳ năm 2025.\n\nDù duy trì đà tăng trưởng, ngành vẫn đối mặt nhiều sức ép từ chi phí đầu vào, dịch bệnh, biến đổi khí hậu và yêu cầu ngày càng cao về an toàn thực phẩm, truy xuất nguồn gốc. Những khó khăn này càng rõ nét ở các hộ chăn nuôi nhỏ lẻ, hạn chế về vốn, công nghệ và khả năng tiếp cận thị trường.\n\nChăn nuôi nhỏ lẻ khó chạy đua về sản lượng\n\nÔng Nguyễn Thanh Chiêu, Giám đốc Dự án, HTX Dịch vụ, Sản xuất và Chăn nuôi Đồng Hiệp (TP Đồng Nai) cho biết, những năm gần đây, chăn nuôi trang trại phát triển mạnh, cung cấp lượng lớn sản phẩm ra thị trường. Trong khi đó, nhiều hộ chăn nuôi nhỏ lẻ ngày càng khó khăn vì không đủ tiềm lực đầu tư vốn, kỹ thuật và cơ sở vật chất... dẫn đến liên tục thua lỗ.\n\nÔng Nguyễn Trí Công, Chủ tịch Hiệp hội Chăn nuôi TP Đồng Nai, cho biết khoảng 10 năm trước, chăn nuôi công nghiệp chỉ chiếm 30% sản lượng sản phẩm chăn nuôi, còn các hộ nhỏ lẻ cung cấp 70%.\n\nThế nhưng hiện nay, tỷ lệ này gần như đã đảo chiều. Chăn nuôi công nghiệp cung cấp phần lớn sản lượng trứng, thịt, trong khi số lượng nông hộ sống bằng nghề chăn nuôi dù lớn nhưng chỉ cung cấp khoảng 30% tổng sản lượng.\n\nSự thay đổi này cho thấy lợi thế về quy mô, công nghệ và chi phí đang nghiêng về các doanh nghiệp, trang trại lớn. Với sản xuất nhỏ lẻ, chi phí cao, nguồn cung thiếu ổn định, việc kết nối với các kênh phân phối hiện đại ngày càng khó khăn hơn.\n\nÁp lực càng lớn khi thức ăn chiếm khoảng 70-75% giá thành chăn nuôi. Theo Hiệp hội Chăn nuôi TP Đồng Nai, giá thức ăn tăng khoảng 40% trong hơn 12 năm qua đã đẩy chi phí nuôi một con heo đạt 100 kg từ khoảng 3,5 triệu đồng lên 5,5-5,8 triệu đồng. Trong khi đó, giá bán ra không tăng tương ứng, hiện chỉ ở mức 48.000-53.000 đồng/kg.\n\nTuy vậy, theo ông Công, chăn nuôi quy mô nhỏ vẫn có lợi thế riêng nếu biết lựa chọn hướng đi phù hợp.\n\n“Lợi thế của nông hộ là nắm giữ quy trình chăn nuôi quy mô nhỏ, tạo ra các sản phẩm thuần tự nhiên. Đây cũng là một ngách thị trường đang có xu hướng tăng trong thời gian qua”, ông Công nhận định.\n\nTìm thị trường ngách bằng sản phẩm chất lượng cao\n\nThay vì cạnh tranh trực tiếp về sản lượng và giá bán, một hướng đi được đặt ra là phát triển các sản phẩm có đặc tính riêng, phục vụ nhóm khách hàng sẵn sàng trả giá cao cho chất lượng.\n\nTheo ông Công, với trứng gà, các hộ có thể hợp tác với doanh nghiệp để phát triển mô hình chăn nuôi nhân đạo, hướng đến nhóm khách hàng như nhà hàng, khách sạn và người tiêu dùng có yêu cầu cao về chất lượng.\n\nỞ mô hình này, mỗi hộ nuôi khoảng 2.000-3.000 con gà nhằm bảo đảm điều kiện sống, chăm sóc vật nuôi và chất lượng sản phẩm. Quy mô không lớn nhưng có thể tạo ra sản phẩm khác biệt so với trứng gà công nghiệp đại trà.\n\n“Trứng gà nhân đạo có giá bán gấp đôi so với trứng gà công nghiệp, nhu cầu thị trường cũng đang rất lớn, tạo cơ hội cho chăn nuôi nông hộ có thể bám trụ với nghề”, ông Công cho biết.\n\nTrên thị trường, trứng gà nuôi không lồng (cage-free) hiện có giá khoảng 27.800-36.500 đồng cho hộp 6 quả, tương đương khoảng 4.600đ-6.000 đồng/quả, trong khi trứng gà công nghiệp giao động từ 2.000-3.000 đồng/quả.\n\nDù vậy, để mô hình phát triển, nông hộ khó có thể tự xoay xở nếu thiếu đầu ra và nguồn vốn. Việc liên kết với doanh nghiệp thu mua, kết hợp ngân hàng tài trợ vốn được kỳ vọng giúp người nuôi có điều kiện đầu tư chuồng trại, duy trì quy trình sản xuất nhằm đáp ứng yêu cầu của thị trường.\n\nVới chăn nuôi heo, hướng đi tương tự là lựa chọn các giống đặc sản phù hợp với điều kiện địa phương, chú trọng chất lượng thịt thay vì sản xuất đại trà để cạnh tranh về giá. Tuy nhiên, sản phẩm đặc sản chỉ có thể tạo lợi thế khi đáp ứng được yêu cầu về chất lượng ổn định, an toàn thực phẩm và có liên kết với kênh tiêu thụ phù hợp.\n\nBên cạnh đó, kiểm soát dịch bệnh, minh bạch nguồn gốc vẫn là điều kiện quan trọng. Việc tái đàn thiếu kiểm soát có thể làm tăng nguy cơ lây lan dịch tả lợn châu Phi, gây thiệt hại cho người nuôi. Các hộ nhỏ lẻ cũng cần được tiếp cận dịch vụ thú y, kỹ thuật chăn nuôi an toàn, quy trình xử lý chất thải phù hợp.\n\nTại triển lãm đang diễn ra ở TPHCM, các doanh nghiệp, chuyên gia và cơ quan quản lý giới thiệu nhiều giải pháp về dinh dưỡng vật nuôi, vắc xin, con giống, thiết bị trang trại, tự động hóa và quản lý chất thải... phù hợp với nhiều mô hình chăn nuôi khác nhau, trong đó có chăn nuôi nông hộ.\n\nNhững giải pháp này được kỳ vọng có thể hỗ trợ ngành giảm chi phí, nâng hiệu quả sản xuất và đáp ứng các tiêu chuẩn thị trường.\n\nTheo ông Phạm Kim Đăng, bên cạnh mục tiêu duy trì tăng trưởng, ngành chăn nuôi cần giải quyết những hạn chế về an toàn sinh học, kiểm soát dịch bệnh, truy xuất nguồn gốc và giảm phát thải.\n\n“Với các hộ nhỏ lẻ, tăng sức cạnh tranh không nhất thiết đồng nghĩa với mở rộng đàn bằng mọi giá, mà cần tìm được phân khúc phù hợp, nâng chất lượng sản phẩm và tăng liên kết với doanh nghiệp để duy trì đầu ra ổn định”, ông Đăng nhận định.","author":"Thuận Hải","category":"Kinh doanh","publishedAt":"2026-10-21 14:37","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/trung-ga-tha-vuon-gia-gap-doi-ga-cong-nghiep-van-hut-khach-20261021143740323.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/2PU3u8C7_COtqPMGAA6MXnhl4TM=/zoom/1200_630/2026/10/21/3-cropped-1792568141712.jpg","crawledAt":"2026-10-21T13:42:57.094Z"},{"id":"dtri-20261021143646532","title":"Đội tuyển U17 Việt Nam thua đậm tại Hàn Quốc","slug":"doi-tuyen-u17-viet-nam-thua-dam-tai-han-quoc","excerpt":"Ở trận đấu đầu tiên trong chuyến tập huấn tại Hàn Quốc, U17 Việt Nam thua U18 FC Seoul với tỷ số đậm 1-4.","content":"(Dân trí) - Ở trận đấu đầu tiên trong chuyến tập huấn tại Hàn Quốc, U17 Việt Nam thua U18 FC Seoul với tỷ số đậm 1-4.\n\nTrận đấu này diễn ra sáng nay (21/10). Với mục tiêu tạo điều kiện thi đấu cho các cầu thủ, HLV Cristiano Roland (người Brazil) bố trí nhiều phương án nhân sự khác nhau. Vị HLV người Brazil trao cơ hội ra sân cho hầu hết các thành viên trong đội ở trận đấu này.\n\nTrước đối thủ có ưu thế về thể hình và thể lực, U17 Việt Nam vẫn nỗ lực triển khai lối chơi, duy trì khả năng phối hợp, nhưng chúng ta chưa tận dụng tốt các cơ hội tạo ra. Chung cuộc, U17 Việt Nam để thua với tỷ số 1-4 trước U18 FC Seoul.\n\nBàn thắng duy nhất của U17 Việt Nam được ghi bởi Trần Mạnh Quân trên chấm phạt đền. Trong tình huống dẫn đến quả phạt đền này, các cầu thủ U17 Việt Nam phối hợp trung lộ, giúp Ngọc Sơn thoát xuống, xâm nhập khu vực cấm địa của đối phương.\n\nNgọc Sơn bị phạm lỗi trong vòng cấm, trọng tài cho các cầu thủ U17 Việt Nam được hưởng quả đá phạt 11m. Trần Mạnh Quân ghi bàn từ khoảng cách 11m.\n\nDù thua đậm 1-4, nhưng trận đấu với U18 FC Seoul mang lại những dữ liệu chuyên môn cần thiết, để HLV Cristiano Roland tiếp tục đánh giá khả năng vận hành chiến thuật, sự phối hợp giữa các vị trí trước đối thủ chơi với tốc độ và cường độ cao.\n\nĐây cũng là nội dung quan trọng trong quá trình chuẩn bị cho vòng chung kết World Cup U17 năm 2026 của U17 Việt Nam.\n\nTheo kế hoạch, U17 Việt Nam sẽ tiếp tục có trận đấu tập thứ hai tại Hàn Quốc, gặp đội U18 Cheonan City FC vào lúc 15h30 ngày 26/10 (theo giờ địa phương).","author":"Trọng Vũ","category":"Thể thao","publishedAt":"2026-10-21 14:36","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/doi-tuyen-u17-viet-nam-thua-dam-tai-han-quoc-20261021143646532.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/7txb12xE_9Gy_s4KTR5jJlllnKQ=/zoom/1200_630/2026/10/21/u17vn3vff15-10-26-cropped-1792567790379.jpg","crawledAt":"2026-10-21T13:43:04.996Z"},{"id":"dtri-20261021143525713","title":"Nữ sinh “sập bẫy\" lừa đảo trực tuyến, bị đưa đi từ tỉnh này đến tỉnh khác","slug":"nu-sinh-sap-bay-lua-dao-truc-tuyen-bi-dua-di-tu-tinh-nay-den-tinh-khac","excerpt":"Theo chuyên gia, vấn đề cần quan tâm hiện nay liên quan tới học sinh, sinh viên là bắt cóc trực tuyến, khi kẻ xấu lợi dụng không gian mạng để thực hiện hành vi phạm tội.","content":"(Dân trí) - Theo chuyên gia, vấn đề cần quan tâm hiện nay liên quan tới học sinh, sinh viên là bắt cóc trực tuyến, khi kẻ xấu lợi dụng không gian mạng để thực hiện hành vi phạm tội.\n\n300.000 cuộc gọi, hỗ trợ gần 2.000 vụ trẻ em bị xâm hại\n\nBên lề “Diễn đàn kết nối và tập huấn an toàn số học đường toàn Thủ đô”, ngày 21/10 tại Trường Phổ thông Liên cấp Song ngữ Quốc tế Wellspring Hanoi, Đại tá, PGS.TS Nguyễn Minh Hiển, Trưởng khoa Nghiệp vụ, Học viện Cảnh sát Nhân dân đưa đến câu chuyện một nữ sinh bị lừa trực tuyến tại Tây Nguyên.\n\nTheo chuyên gia này, bằng nhiều kịch bản, đối tượng xấu đã lừa nữ sinh đi hết tỉnh này đến tỉnh khác. Chỉ đến khi mượn được điện thoại, nữ sinh gọi điện đến công an hỗ trợ và giải cứu.\n\nCũng theo ông Hiển, hiện rất nhức nhối tình trạng bắt cóc trực tuyến. Do đó, ông đưa câu chuyện trên để làm bài học cho các học sinh, sinh viên khác.\n\nBà Nguyễn Thuận Hải, Trưởng phụ trách Tổng đài Quốc gia Bảo vệ trẻ em 111, cho biết trong 10 tháng đầu năm, tổng đài đã tiếp nhận trên 300.000 cuộc gọi liên quan đến trẻ em. Trong đó, tổng đài phải kết nối và hỗ trợ can thiệp gần 2.000 vụ trẻ em bị xâm hại.\n\nXâm hại có nhiều hình thức khác nhau như: Bạo lực học đường, bạo lực trẻ em, xâm hại tình dục trẻ em, bóc lột trẻ em, mua bán trẻ em, sao nhãng bỏ rơi/bỏ mặc trẻ em...\n\n“Số liệu này tăng khoảng 20% so với cùng kỳ năm 2025. Điều này cũng cho thấy tình trạng trẻ em bị xâm hại đang trở nên nghiêm trọng và cần có sự vào cuộc hỗ trợ để giảm thiểu tình trạng này”, theo bà Hải.\n\nĐặc biệt, bà Hải cho biết trong số liệu đó, rất nhiều vụ việc trẻ em bị xâm hại trên môi trường mạng bằng các hình thức phổ biến: Bắt nạt học đường thông qua nhắn tin, đe dọa; lừa đảo trực tuyến; đăng tải hình ảnh nhạy cảm để thao túng tâm lý các em…\n\nDấu hiệu nhận biết “sập bẫy\" trực tuyến\n\nĐại tá, PGS.TS Nguyễn Minh Hiển cho hay, các đối tượng lừa đảo ngày càng tinh vi với nhiều kịch bản thay đổi liên tục. Trong khi học sinh, sinh viên lại thiếu kiến thức tự bảo vệ bản thân hoặc xung quanh không có ai đủ tin tưởng để các em làm chỗ dựa tinh thần.\n\nTrước mắt học sinh, sinh viên phải tự bảo vệ bản thân bằng các kỹ năng nhận diện và xử lý tình huống.\n\nTheo ông, các dấu hiệu nhận biết lừa đảo như: Dùng số điện thoại lạ, thông báo nạn nhân liên quan đến tổ chức ma túy, rửa tiền, tội phạm. Đối tượng cũng giả danh công an, làm cho nạn nhân hoang mang sợ sệt, hỗn loạn tâm lý, mất kiểm soát.\n\nSau khi nạn nhân bị tịch thu phương tiện liên lạc, tinh thần bị thao túng, đối tượng yêu cầu gia đình chuyển tiền hoặc đưa nạn nhân buôn bán đến các quốc gia khác.\n\n“Các cơ quan Công an, Viện kiểm sát…, không bao giờ làm việc qua điện thoại. Chúng tôi làm việc với công dân phải có giấy mời, thời gian, địa điểm, không thông báo đột xuất. Do đó các em hoàn toàn không nên tin tưởng các cuộc gọi này.\n\nĐối với các cuộc gọi lạ, thông báo trúng giải thưởng, học bổng, các em tuyệt đối không nghe và nhanh chóng báo cáo với gia đình, người thân, cơ quan công an…, để giải quyết ”, ông Hiển đưa ra lời khuyên.\n\nBà Hải cho hay, lừa đảo trực tuyến có thể thông qua nhiều kịch bản như: Người thân bị tai nạn cần chuyển tiền để vào viện cấp cứu, hoặc lừa nạn nhân có liên quan đến pháp luật, để thao túng tâm lý…\n\n\"Trẻ em cần phải nhận diện các vấn đề, nguy cơ trên môi trường mạng và dũng cảm lên tiếng để cơ quan chức năng có thể hỗ trợ. Các em cũng nên báo với cơ quan chức năng nếu nghi người thân, bạn bè rơi vào mối đe dọa\", bà Hải nói.\n\nDưới góc độ nhà trường, bà Lê Thị Mai Hương, Phó Tổng Hiệu trưởng Trường Phổ thông Liên cấp Song ngữ Quốc tế Wellspring Hanoi, cho biết nhà trường triển khai đồng bộ các giải pháp theo hướng phòng ngừa sớm, trang bị kỹ năng và xây dựng mạng lưới bảo vệ học sinh.\n\nTheo đó, nội dung an toàn số được lồng ghép trong chương trình kỹ năng sống, các hoạt động giáo dục và sinh hoạt lớp, giúp học sinh nhận diện những thủ đoạn như giả mạo danh tính, thao túng tâm lý, dụ dỗ, đe dọa, lừa đảo và “bắt cóc trực tuyến”.\n\nCác hoạt động này giúp các em biết cách kiểm chứng thông tin, bảo vệ dữ liệu cá nhân và tìm kiếm sự hỗ trợ khi gặp nguy hiểm.","author":"Mỹ Hà","category":"Giáo dục","publishedAt":"2026-10-21 14:35","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/nu-sinh-sap-bay-lua-dao-truc-tuyen-bi-dua-di-tu-tinh-nay-den-tinh-khac-20261021143525713.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/pqKDljLAqQPBbeULOV8SVGyRoRU=/zoom/1200_630/2026/10/21/ognhien2-myha-edited-cropped-1792568004516.jpg","crawledAt":"2026-10-21T13:43:22.193Z"},{"id":"dtri-20261021140527356","title":"Cơ hội nào để Williams Minh Hoàng, Ngô Đăng Khoa góp mặt ở U23 Việt Nam?","slug":"co-hoi-nao-de-williams-minh-hoang-ngo-dang-khoa-gop-mat-o-u23-viet-nam","excerpt":"Một loạt cầu thủ U23 Việt Nam hiện nay sẽ quá tuổi dự SEA Games 34 năm 2027 và giải U23 châu Á 2028, điều đó đặt ra bài toán lực lượng mới cho HLV Kim Sang Sik giai đoạn tới.","content":"(Dân trí) - Một loạt cầu thủ U23 Việt Nam hiện nay sẽ quá tuổi dự SEA Games 34 năm 2027 và giải U23 châu Á 2028, điều đó đặt ra bài toán lực lượng mới cho HLV Kim Sang Sik giai đoạn tới.\n\nTheo quy định của nội dung bóng đá nam SEA Games 34 năm 2027 và vòng loại giải U23 châu Á 2028 (dự kiến diễn ra tháng 6/2027), các cầu thủ tham dự những sân chơi này phải sinh từ năm 2005 trở về sau (22 tuổi vào năm tới, 21 tuổi trong năm nay).\n\nĐiều đó có nghĩa là một loạt cầu thủ vừa tham dự nội dung bóng đá nam Asiad 20 Aichi-Nagoya (Nhật Bản) trong năm nay sẽ quá tuổi để tham dự SEA Games 34 và vòng loại giải U23 châu Á, diễn ra trong năm 2027.\n\nNhững cầu thủ quá tuổi gồm hậu vệ Phạm Lý Đức (23 tuổi), Nguyễn Đức Anh (23), Đặng Tuấn Phong (23), tiền vệ Nguyễn Thái Quốc Cường (22), Nguyễn Xuân Bắc (23), Nguyễn Phi Hoàng (23), Phạm Minh Phúc (22), tiền đạo Nguyễn Thanh Nhàn (23), Nguyễn Quốc Việt (23), Nguyễn Ngọc Mỹ (22 tuổi).\n\nĐội tuyển U23 Việt Nam sẽ tham dự giải giao hữu tứ hùng quốc tế tại Gia Lai, từ ngày 10/11 đến 14/11. Đây là giải đấu mà đội tuyển U23 Việt Nam chuẩn bị cho vòng loại U23 châu Á 2028, SEA Games 34 (dự kiến diễn ra tháng 9/2027) và vòng chung kết U23 châu Á 2028 (tháng 1/2028, nếu đội tuyển U23 Việt Nam vượt qua vòng loại).\n\nChính vì thế, đội tuyển U23 Việt Nam nhiều khả năng sẽ không sử dụng những cầu thủ đã quá tuổi tham dự các giải đấu kể trên. Thay vào đó, HLV Kim Sang Sik sẽ gọi những cầu thủ trong lứa tuổi 21.\n\nBóng đá Việt Nam hiện nay không thiếu những cầu thủ U21 có tiềm năng, sẵn sàng thay những cầu thủ trụ cột của U23 Việt Nam đã hết tuổi dự SEA Games vào năm sau.\n\nNhững cầu thủ trong lứa U21, rất giàu tiềm năng, nhưng không có tên trong thành phần tham dự Asiad 20 gồm thủ môn Nguyễn Tân (21 tuổi), Phạm Đình Hải (20), hậu vệ Nguyễn Mạnh Hưng (21), Nguyễn Bảo Long (21), Mai Quốc Tú (21), tiền vệ Trần Thành Trung (21), Nguyễn Công Phương (20), tiền đạo Nguyễn Minh Tâm (20), Nguyễn Đăng Dương (21), Trần Gia Bảo (18 tuổi)…\n\nNgay cả hai cầu thủ Việt kiều Wiliams Minh Hoàng (19 tuổi) và Ngô Đăng Khoa (20 tuổi) cũng có cơ hội khoác áo đội tuyển U23 Việt Nam trong thời gian tới. Những cầu thủ này gây thất vọng khi khoác áo đội tuyển quốc gia ở FIFA ASEAN Cup 2026.\n\nNguyên nhân khiến họ chơi không tốt là do họ thiếu kinh nghiệm, thiếu bản lĩnh khi đối diện với các đối thủ dày dạn. Do đó, cách tốt nhất để họ tăng kinh nghiệm, đó là để họ có thêm cơ hội cọ xát quốc tế ở cấp độ thấp hơn cấp độ đội tuyển quốc gia. Việc thi đấu cho đội tuyển U23 Việt Nam là phù hợp với Williams Minh Hoàng và Ngô Đăng Khoa vào lúc này.\n\nTại giải tứ hùng quốc tế ở Gia Lai trong những ngày tới, U23 Việt Nam sẽ chạm trán với các đối thủ mạnh gồm U23 Thái Lan, Qatar và Singapore. Các trận đấu sẽ diễn ra trên sân Pleiku (Gia Lai).","author":"Trọng Vũ","category":"Thể thao","publishedAt":"2026-10-21 14:05","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/co-hoi-nao-de-williams-minh-hoang-ngo-dang-khoa-gop-mat-o-u23-viet-nam-20261021140527356.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/SDvMMbCQcVh_09R6pqg7dpXQm-g=/zoom/1200_630/2026/10/19/vn5vff2-10-26-cropped-cropped-1792406363421.jpg","crawledAt":"2026-10-21T13:43:04.940Z"},{"id":"dtri-20261021135507812","title":"Vì sao Quả bóng vàng 2026 lần đầu được trao tại Anh?","slug":"vi-sao-qua-bong-vang-2026-lan-dau-duoc-trao-tai-anh","excerpt":"Sự kiện Quả bóng vàng 2026 sẽ diễn ra vào rạng sáng 27/10 (giờ Việt Nam) tại London (Anh) với cuộc cạnh tranh đáng chú ý giữa Lionel Messi, Lamine Yamal, Harry Kane và Kylian Mbappe.","content":"(Dân trí) - Sự kiện Quả bóng vàng 2026 sẽ diễn ra vào rạng sáng 27/10 (giờ Việt Nam) tại London (Anh) với cuộc cạnh tranh đáng chú ý giữa Lionel Messi, Lamine Yamal, Harry Kane và Kylian Mbappe.\n\nLễ trao giải Quả bóng vàng (Ballon d'Or) 2026 sẽ diễn ra vào ngày 26/10 tại nhà hát London Palladium, thủ đô London (Anh). Sự kiện chính thức bắt đầu lúc 20h giờ địa phương, tức 3h sáng ngày 27/10 (giờ Việt Nam), với các hoạt động thảm đỏ đón tiếp dàn sao khởi động từ 1h cùng ngày.\n\nĐây là sự kiện mang ý nghĩa đặc biệt khi đánh dấu cột mốc tròn 70 năm ra đời của danh hiệu cao quý này. Lần đầu tiên trong lịch sử, lễ trao giải được chuyển địa điểm từ Paris (Pháp) sang London nhằm tri ân huyền thoại người Anh Stanley Matthews, cầu thủ đầu tiên đoạt Quả bóng vàng vào năm 1956. Hai nhân vật nổi tiếng đảm nhiệm vai trò dẫn chương trình năm nay là cựu danh thủ Thierry Henry và nữ MC Kate Scott.\n\nCuộc đua kịch tính giữa các siêu sao: Lamine Yamal, Harry Kane chiếm ưu thế\n\nDanh sách 30 đề cử nam năm nay quy tụ những cái tên xuất sắc nhất thế giới như Harry Kane, Lamine Yamal, Kylian Mbappe, Lionel Messi, Erling Haaland, Vinicius Junior, Rodri và Ousmane Dembele.\n\nTrong đó, Lamine Yamal nổi lên như ứng viên sáng giá hàng đầu nhờ phong độ chói sáng trong màu áo Barcelona và chiến tích cùng đội tuyển Tây Ban Nha bước lên ngôi vô địch World Cup 2026. Đối trọng lớn của thần đồng người Tây Ban Nha là tiền đạo Harry Kane sau mùa giải ghi bàn bùng nổ cùng Bayern Munich.\n\nBên cạnh đó, Kylian Mbappe cũng sở hữu lợi thế lớn với danh hiệu Vua phá lưới World Cup 2026. Siêu sao Lionel Messi ghi dấu ấn khi trở lại danh sách đề cử sau hai năm vắng bóng, mở ra cơ hội cạnh tranh Quả bóng vàng thứ 9 trong sự nghiệp. Đáng chú ý, Cristiano Ronaldo tiếp tục vắng mặt trong danh sách 30 ứng viên.\n\nỞ các hạng mục dành cho những người đang giữ danh hiệu, Ousmane Dembele tham dự với tư cách chủ nhân Quả bóng vàng nam 2025, còn Aitana Bonmati là người chiến thắng ở hạng mục nữ mùa trước.\n\nThể lệ bầu chọn khắt khe và các hạng mục vinh danh\n\nGiải thưởng Quả bóng vàng 2026 đánh giá toàn diện thành tích của các cầu thủ trong giai đoạn từ 3/8/2025 đến 19/7, bao gồm mùa giải cấp câu lạc bộ và các giải đấu quốc tế lớn, trọng tâm là World Cup 2026.\n\nKết quả được xác định qua phiếu bầu của 100 nhà báo thể thao quốc tế từ các quốc gia dẫn đầu bảng xếp hạng FIFA (50 đại diện đối với hạng mục nữ). Mỗi nhà báo chọn ra 10 cầu thủ xếp theo thứ tự điểm số lần lượt là 15, 12, 10, 8, 7, 5, 4, 3, 2 và 1 điểm. Ba tiêu chí đánh giá ưu tiên gồm: Thành tích cá nhân và tầm ảnh hưởng trên sân; Thành tích tập thể và các danh hiệu đạt được; Đẳng cấp và tinh thần fair play.\n\nBên cạnh Quả bóng vàng nam và nữ, ban tổ chức sẽ trao hàng loạt giải thưởng phụ như: Kopa Trophy (Cầu thủ trẻ xuất sắc), Yashin Trophy (Thủ môn xuất sắc), Johan Cruyff Trophy (HLV xuất sắc), Gerd Muller Trophy (Tiền đạo xuất sắc), giải CLB nam/nữ xuất sắc nhất và giải Socrates dành cho các hoạt động cộng đồng.","author":"Quyết Thắng","category":"Thể thao","publishedAt":"2026-10-21 13:55","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/vi-sao-qua-bong-vang-2026-lan-dau-duoc-trao-tai-anh-20261021135507812.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/ntw3OuGVuuuTWtGSovydndIih2w=/zoom/1200_630/2026/10/21/gettyimages-1244039852-612x612-cropped-1792565542407.jpg","crawledAt":"2026-10-21T13:43:06.069Z"},{"id":"dtri-20261021134410333","title":"Mô hình CARE gợi mở cách chọn nghề cho Gen Z","slug":"mo-hinh-care-goi-mo-cach-chon-nghe-cho-gen-z","excerpt":"Giữa những ngành đang lên ngôi, điều khó nhất với Gen Z không chỉ là tìm một ngành phù hợp và có tiềm năng, mà còn là lựa chọn môi trường đào tạo có thể giúp mình tiến gần hơn tới mục tiêu nghề nghiệp. Mô hình CARE sẽ giúp giải quyết bài toán này.","content":"(Dân trí) - Giữa những ngành đang lên ngôi, điều khó nhất với Gen Z không chỉ là tìm một ngành phù hợp và có tiềm năng, mà còn là lựa chọn môi trường đào tạo có thể giúp mình tiến gần hơn tới mục tiêu nghề nghiệp. Mô hình CARE sẽ giúp giải quyết bài toán này.\n\nHọc tốt toán, vật lý và yêu thích công nghệ có đồng nghĩa với việc phù hợp ngành công nghệ bán dẫn? Một ngành đang thiếu nhân lực liệu có bảo đảm cơ hội việc làm sau tốt nghiệp? Và khi đã xác định được hướng đi, đâu là môi trường đại học giúp người học tiến gần hơn đến mục tiêu nghề nghiệp?\n\nNhững câu hỏi này phản ánh bài toán hướng nghiệp của nhiều học sinh THPT trước ngưỡng cửa đại học. Theo TS Hoàng Việt Hà - Viện trưởng Viện Đại học Quốc tế FPT - lựa chọn ngành nghề cần được xem xét có hệ thống, dựa trên sự phù hợp giữa năng lực cá nhân, nhu cầu thị trường và điều kiện đào tạo.\n\nTrên cơ sở đó, ông xây dựng mô hình định hướng nghề nghiệp CARE.\n\nC - Clarity about Yourself (Thấu hiểu bản thân)\n\nBước đầu tiên của CARE giúp học sinh xác định những ngành nghề phù hợp thông qua việc đối chiếu sở thích, năng lực và thế mạnh cá nhân với tính chất công việc, yêu cầu chuyên môn và môi trường nghề nghiệp.\n\nChẳng hạn, cùng học tốt toán, vật lý và yêu thích công nghệ nhưng mỗi học sinh có thể phù hợp với những hướng đi khác nhau. Người hứng thú với nguyên lý hoạt động của linh kiện, thiết bị và các bài toán kỹ thuật đòi hỏi độ chính xác cao có thể cân nhắc ngành công nghệ bán dẫn. Trong khi đó, người có thế mạnh về lập trình và xử lý dữ liệu có thể quan tâm nhiều hơn đến phát triển phần mềm hoặc trí tuệ nhân tạo.\n\nCác công cụ hướng nghiệp như Holland/RIASEC và phỏng vấn chuyên sâu có thể hỗ trợ nhận diện thiên hướng cá nhân, song cần kết hợp với đánh giá năng lực và trải nghiệm thực tế.\n\nA - Awareness of the Career Market (Nắm bắt xu hướng nghề nghiệp)\n\nSau khi nhận diện nhóm ngành phù hợp, người học cần đặt lựa chọn đó trong bối cảnh thị trường lao động. Awareness tập trung vào triển vọng ngành, nhu cầu tuyển dụng và những năng lực doanh nghiệp có thể cần trong tương lai.\n\nNgành công nghệ bán dẫn là một ví dụ điển hình. Sự phát triển của AI và các thiết bị công nghệ đang thúc đẩy nhu cầu sử dụng chip bán dẫn. Khi nhu cầu chip gia tăng, các hoạt động thiết kế, chế tạo, đóng gói và kiểm thử cũng có thêm động lực phát triển, mở ra cơ hội việc làm ở nhiều lĩnh vực chuyên môn.\n\nTheo các dự báo về nhân lực, ngành bán dẫn toàn cầu có thể thiếu khoảng một triệu nhân sự vào năm 2030. Tại Việt Nam, mục tiêu đào tạo ít nhất 50.000 nhân lực trình độ đại học trở lên phục vụ ngành công nghiệp bán dẫn đến năm 2030 cũng cho thấy định hướng đầu tư phát triển nguồn nhân lực cho lĩnh vực này.\n\nDù vậy, mỗi vị trí trong ngành lại có yêu cầu chuyên môn khác nhau. Người theo đuổi thiết kế vi mạch cần những năng lực khác với người làm việc trong lĩnh vực vật liệu, thiết bị hay quy trình sản xuất.\n\nVì thế, Awareness giúp học sinh nhìn nhận cơ hội nghề nghiệp cụ thể trong một ngành đang phát triển, từ đó lựa chọn hướng đi phù hợp với năng lực bản thân và nhu cầu thực tế của thị trường.\n\nR - Right University Choice (Lựa chọn trường đại học phù hợp)\n\nKhi đã xác định ngành học, CARE gợi ý lựa chọn trường dựa trên các yếu tố như năng lực học thuật, thế mạnh đào tạo ngành, môi trường học tập, vị trí và khả năng tài chính.\n\nUy tín học thuật của một trường có thể được tham chiếu qua các bảng xếp hạng quốc tế từ những tổ chức như THE hoặc QS. Các trường nằm trong nhóm top 500 đại học thế giới thường có vị thế học thuật và mức độ quốc tế hóa đáng chú ý.\n\nVới những học sinh đang quan tâm đến ngành công nghệ bán dẫn, chương trình đại học Gachon University Program là một lựa chọn đáng tìm hiểu.\n\nVề học thuật, Đại học Gachon thuộc nhóm 451-500 đại học tốt nhất thế giới (theo bảng xếp hạng World University Rankings 2027 của Times Higher Education), đồng thời sở hữu College of Semiconductors chuyên biệt.\n\nSinh viên Gachon University Program có thể phát triển theo hai hướng: Thiết kế hệ thống bán dẫn (System Semiconductor Design) và Kỹ thuật bán dẫn (Semiconductor Engineering), tương ứng với những vị trí khác nhau trong chuỗi giá trị ngành.\n\nTrong hai năm đầu tại Việt Nam, sinh viên xây dựng kiến thức cơ sở, phát triển ngoại ngữ, kỹ năng học tập và khả năng thích nghi với môi trường quốc tế trong hệ sinh thái giáo dục, công nghệ của FPT.\n\nHai năm tiếp theo tại Đại học Gachon, sinh viên chuyển sang môi trường đào tạo chuyên sâu, với hệ thống phòng thí nghiệm, hoạt động nghiên cứu và các học phần liên quan đến công nghệ bán dẫn.\n\nLợi thế của giai đoạn học tập tại Hàn Quốc còn đến từ hệ sinh thái công nghệ xung quanh Đại học Gachon. Trường tọa lạc tại Seongnam, gần Pangyo Techno Valley - một trong những trung tâm công nghệ lớn của quốc gia này, đồng thời có các hoạt động kết nối với doanh nghiệp và tổ chức nghiên cứu như Samsung Electronics, SK hynix, DB HiTek và ETRI.\n\nỞ bài toán chi phí, mô hình 2 năm tại Việt Nam - 2 năm tại Hàn Quốc, cùng các mức học bổng lên đến 100% học phí giai đoạn chuyên ngành tại Việt Nam, giúp sinh viên phân bổ nguồn lực theo từng giai đoạn thay vì bắt đầu toàn bộ hành trình du học từ năm nhất.\n\nE - Effective Success Path (Xây dựng lộ trình phát triển hiệu quả)\n\nChọn đúng trường là chưa đủ, người học còn cần một lộ trình phù hợp và sự chủ động để từng bước tiến gần mục tiêu nghề nghiệp.\n\nEffective Success Path tập trung vào việc xây dựng kế hoạch phát triển cá nhân, xác định những kiến thức, kỹ năng và trải nghiệm cần tích lũy qua từng giai đoạn học tập.\n\nTùy hướng chuyên môn, người học có thể tích lũy năng lực qua dự án kỹ thuật, nghiên cứu, chứng chỉ chuyên môn và trải nghiệm thực tập. Các sản phẩm, báo cáo hay kinh nghiệm giải quyết vấn đề trở thành minh chứng cho quá trình phát triển.\n\nViệc xây dựng hồ sơ năng lực sớm cũng giúp sinh viên nhận diện khoảng cách giữa năng lực hiện tại và yêu cầu của vị trí mong muốn, từ đó điều chỉnh kế hoạch học tập và chuẩn bị cho quá trình ứng tuyển sau tốt nghiệp.\n\nGiá trị của Effective Success Path nằm ở khả năng biến một lộ trình đào tạo thành những mục tiêu và kết quả cụ thể của từng cá nhân, để sinh viên có cơ sở đánh giá sự tiến bộ của bản thân trong suốt hành trình đại học.\n\nMô hình CARE có thể được khái quát qua công thức: Clarity x Awareness x Right University x Effective Success Path = Career Success (Thành công nghề nghiệp).\n\nTrong đó, bốn thành tố có mối quan hệ bổ trợ, giúp học sinh kết nối việc hiểu bản thân, nắm bắt thị trường, lựa chọn môi trường học tập và xây dựng lộ trình phát triển trong một quyết định có cơ sở.\n\nTìm hiểu thêm về Gachon University Program tại:\n\nWebsite: Tại đây\n\nFanpage: Tại đây\n\nHotline: 024 7306 2289 (Hà Nội) / 028 7890 0289 (TPHCM)","author":"Tiến Thịnh","category":"Giáo dục","publishedAt":"2026-10-21 13:44","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/mo-hinh-care-goi-mo-cach-chon-nghe-cho-gen-z-20261021134410333.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/hvhbx0JYvzj1PybNQd0Ssg_xHPs=/zoom/1200_630/2026/10/21/dai-hoc-gachon-cropped-1792564892042.jpg","crawledAt":"2026-10-21T13:43:23.380Z"},{"id":"dtri-20261021133712012","title":"Đề xuất cấm hút thuốc ở khách sạn, vũ trường, kiên quyết như \"cấm đốt pháo\"","slug":"de-xuat-cam-hut-thuoc-o-khach-san-vu-truong-kien-quyet-nhu-cam-dot-phao","excerpt":"Việc chuyển một số địa điểm như khách sạn, quán bar, karaoke, vũ trường… từ mô hình có khu vực hút thuốc riêng sang cấm hút thuốc hoàn toàn như Chính phủ đề xuất, được Chủ tịch Quốc hội đồng tình.","content":"(Dân trí) - Việc chuyển một số địa điểm như khách sạn, quán bar, karaoke, vũ trường… từ mô hình có khu vực hút thuốc riêng sang cấm hút thuốc hoàn toàn như Chính phủ đề xuất, được Chủ tịch Quốc hội đồng tình.\n\nSáng 21/10, các đại biểu Quốc hội thảo luận ở tổ về dự án Luật sửa đổi, bổ sung một số điều của Luật Phòng, chống tác hại của thuốc lá.\n\nTại tổ TPHCM, Chủ tịch Quốc hội Trần Thanh Mẫn đề nghị làm rõ phạm vi cấm trưng bày sản phẩm thuốc lá, đồng thời mở rộng địa điểm cấm hút thuốc hoàn toàn.\n\nDự thảo luật sửa đổi cấm hoàn toàn việc trưng bày sản phẩm, bao bì, hình ảnh và tên nhãn hiệu thuốc lá tại điểm bán, thay vì cho phép trưng bày nhãn hiệu, bao bì như luật hiện hành.\n\nChủ tịch Quốc hội cho rằng cần đánh giá tính khả thi của quy định trong thực tế, nhất là tại các cửa hàng miễn thuế, ga hàng không, khu vực biên giới.\n\nViệc quy định tủ đựng thuốc lá kín, không để lộ sản phẩm, theo Chủ tịch Quốc hội, là phù hợp với mục tiêu giảm kích thích mua thuốc lá. Tuy nhiên, cần có hướng dẫn cụ thể và chế tài đủ mạnh để tránh tình trạng quy định cấm nhưng việc thực hiện lại hình thức.\n\nVề mở rộng địa điểm cấm hút thuốc hoàn toàn, Chính phủ đề xuất chuyển một số địa điểm như khách sạn, quán bar, karaoke, vũ trường, nhà hàng từ mô hình có khu vực hút thuốc riêng sang cấm hút thuốc hoàn toàn; đồng thời bổ sung tàu thủy, tàu hỏa vào nhóm phương tiện giao thông công cộng cấm hút thuốc hoàn toàn.\n\nĐồng tình với việc mở rộng các khu vực không khói thuốc, Chủ tịch Quốc hội nhấn mạnh quyền được bảo vệ sức khỏe của người không hút thuốc; đồng thời cho rằng, việc bố trí các điểm hút thuốc cần được thực hiện rõ ràng, đúng quy định.\n\nDẫn kinh nghiệm Singapore về xử phạt hành vi vứt tàn thuốc nơi công cộng, chỉ cần vứt tàn thuốc ra đường, nếu bị camera ghi lại, người vi phạm có thể bị phạt 300 đô la Singapore, Chủ tịch Quốc hội cho rằng, quy định chỉ phát huy hiệu quả khi có cơ chế kiểm tra, giám sát và xử phạt nghiêm minh.\n\nBên cạnh đó, Chủ tịch Quốc hội cũng lưu ý việc mở rộng địa điểm cấm hút thuốc cần có lộ trình rõ ràng, giai đoạn chuyển tiếp hợp lý và hỗ trợ doanh nghiệp điều chỉnh hoạt động, bảo đảm thực thi đồng bộ.\n\nVới đề xuất tăng diện tích cảnh báo sức khỏe trên bao bì thuốc lá từ 50% lên 85% trên mỗi mặt chính trước và sau bao thuốc, đồng thời bổ sung số điện thoại tổng đài hỗ trợ cai nghiện và thay đổi mẫu cảnh báo định kỳ, theo Chủ tịch Quốc hội, cảnh báo sức khỏe là cần thiết nhưng chưa đủ để thay đổi hành vi của người nghiện thuốc lá.\n\nDo đó, chính sách cần kết hợp giữa cảnh báo với các biện pháp quản lý, phòng ngừa và hỗ trợ cai nghiện hiệu quả.\n\nĐối với thuốc lá điện tử, thuốc lá nung nóng và các sản phẩm thuốc lá mới, Chủ tịch Quốc hội cho biết trước đây có ý kiến khác nhau giữa các cơ quan về việc cấm hoàn toàn hay chỉ thí điểm cấm thuốc lá điện tử, thuốc lá nung nóng.\n\nSong thể hiện quan điểm của mình, Chủ tịch Quốc hội cho rằng \"không thí điểm đối với những sản phẩm đã được xác định là có tác hại đến sức khỏe”. Thay vào đó, khi cơ quan y tế xác định rõ tác hại thì cần có biện pháp quản lý kiên quyết.\n\nNgoài ra, Chủ tịch Quốc hội Trần Thanh Mẫn đề nghị đánh giá tác động của các quy định đối với tình trạng buôn lậu thuốc lá và nguồn thu ngân sách.\n\nTheo Chủ tịch Quốc hội, không nên chỉ nhìn vào lợi ích kinh tế hay số thu ngân sách. Nếu các quy định góp phần phòng, chống tác hại của thuốc lá, bảo vệ sức khỏe cộng đồng và ngăn ngừa các hành vi vi phạm pháp luật thì lợi ích xã hội mang lại sẽ rất lớn.\n\nCùng tổ thảo luận, đại biểu Phạm Trọng Nhân cho rằng để giải quyết triệt để “bài toán” thuốc lá, cần vạch ra hai con đường cốt lõi.\n\nMột là không để phát sinh người hút thuốc mới, hai là giúp những người đang hút cai nghiện.\n\nBên cạnh việc đấu tranh bảo vệ người dân trước tác hại của thuốc lá truyền thống, ông đặc biệt nhấn mạnh thái độ xử lý đối với các sản phẩm mới (thuốc lá điện tử, thuốc lá nung nóng, túi ngậm nicotine, shisha...).\n\n\"Tôi kiên quyết đề nghị giữ danh mục cấm ngay trong luật này. Chúng ta phải cương quyết như trước đây cấm đốt pháo hay kiên quyết bắt buộc phải đội mũ bảo hiểm”, ông Nhân nói, đồng thời nhấn mạnh cần cấm toàn diện các sản phẩm thuốc lá mới.","author":"Hoài Thu","category":"Thời sự","publishedAt":"2026-10-21 13:37","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/de-xuat-cam-hut-thuoc-o-khach-san-vu-truong-kien-quyet-nhu-cam-dot-phao-20261021133712012.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/15UcnU1SRQixn8QQpSfxv9hiq2A=/zoom/1200_630/2026/10/21/de-xuat-cam-hut-thuoc-o-khach-san-quan-bar-karaoke-vu-truong-cropped-1792564962796.jpg","crawledAt":"2026-10-21T13:42:24.412Z"},{"id":"dtri-20261021133008548","title":"Nữ diễn viên \"Hương vị tình thân\" kết hôn ở tuổi 24, hé lộ về bạn đời","slug":"nu-dien-vien-huong-vi-tinh-than-ket-hon-o-tuoi-24-he-lo-ve-ban-doi","excerpt":"Ở tuổi 24, Thục Anh - nữ diễn viên từng gây chú ý với vai “tiểu tam” Dương trong phim \"Hương vị tình thân\" - quyết định lên xe hoa vào tháng 11 tới.","content":"(Dân trí) - Ở tuổi 24, Thục Anh - nữ diễn viên từng gây chú ý với vai “tiểu tam” Dương trong phim \"Hương vị tình thân\" - quyết định lên xe hoa vào tháng 11 tới.\n\nMới đây, nữ diễn viên Đào Hiền Thục Anh khiến nhiều đồng nghiệp và khán giả bất ngờ khi chia sẻ những hình ảnh ngọt ngào trong lễ dạm ngõ, diễn ra vào ngày 16/10.\n\nTrò chuyện với phóng viên Dân trí, Thục Anh cho biết, hiện hai người và gia đình hai bên đã chuẩn bị phần lớn công việc cho đám cưới dự kiến diễn ra vào tháng 11. Nữ diễn viên chưa công bố ngày cụ thể, mong hôn lễ có đầy đủ gia đình, bạn bè và đồng nghiệp.\n\nThục Anh thừa nhận, có nhiều cảm xúc đan xen khi bước vào giai đoạn mới của cuộc đời. Cô vừa vui mừng, háo hức, vừa có chút bỡ ngỡ vì mọi việc diễn ra nhanh hơn cảm nhận của bản thân.\n\n“Bình thường, tôi vẫn là một cô gái đi làm, đi quay, chạy sự kiện rồi lo công việc riêng. Vậy mà chỉ một thời gian nữa thôi, tôi sẽ bước sang một vai trò mới trong cuộc sống”, cô bày tỏ.\n\nDù đã làm lễ dạm ngõ và chuẩn bị cho đám cưới, Thục Anh tiết lộ vẫn chưa được cầu hôn chính thức. Do cả hai đều bận rộn với công việc, thời gian gần đây lại tập trung chuẩn bị hôn lễ nên bạn đời đã hứa sẽ dành cho cô một lời cầu hôn bất ngờ.\n\nĐiều khiến nữ diễn viên trân trọng ở người bạn đời là sự trưởng thành và tinh thần trách nhiệm. Theo cô, trưởng thành không đồng nghĩa với việc lúc nào cũng nghiêm túc hay biết tất cả mọi chuyện, mà thể hiện ở cách một người đối diện với vấn đề, chịu trách nhiệm với lựa chọn của mình và suy nghĩ cho người bên cạnh.\n\nVới Thục Anh, cảm xúc là yếu tố quan trọng khi lựa chọn người kết hôn, nhưng tình yêu thôi chưa đủ. Cô cần một người khiến mình cảm thấy an toàn, một người không chỉ là người yêu mà còn có thể trở thành bạn đồng hành, có thể cùng định hướng tương lai, chia sẻ những mục tiêu trong sự nghiệp và xây dựng cuộc sống chung.\n\nThục Anh bộc bạch: “Tôi là người khá nhiều công việc, đôi khi cũng có những mục tiêu và áp lực riêng. Vì thế, điều bản thân trân trọng ở một mối quan hệ là tôi có thể được là chính mình, được làm công việc mình yêu thích, theo đuổi những điều mình muốn, nhưng đồng thời vẫn có một người ở bên để chia sẻ và cùng mình đi qua những giai đoạn khác nhau của cuộc sống. Tôi nghĩ đó là một trong những điều khiến mình muốn gắn bó lâu dài với anh”.\n\nNhiều người hỏi Thục Anh kết hôn sớm có tiếc nuối hay không. Nữ diễn viên kể, nhiều khán giả nghĩ cô khoảng 28-29 tuổi, thậm chí hơn 30 tuổi, bởi thấy cô xuất hiện trên truyền thông và tham gia nhiều dự án nghệ thuật thời gian dài.\n\n“Khi biết tôi mới 24 tuổi, nhiều người còn bất ngờ vì nghĩ ở tuổi này làm sao tôi đã có từng ấy năm hoạt động nghệ thuật”, cô thổ lộ.\n\nThục Anh hiểu vì sao khán giả đặt câu hỏi về việc lập gia đình khi còn trẻ, nhất là với người làm nghệ thuật. Tuy nhiên, cô không cho rằng kết hôn sớm đồng nghĩa với việc phải đánh đổi sự nghiệp.\n\nTheo nữ diễn viên, thành công của một người phụ nữ không chỉ có một con đường duy nhất. “Tôi không xem việc kết hôn ở thời điểm này là sớm hay muộn. Tôi chỉ cảm thấy đây là thời điểm phù hợp với bản thân, khi đã gặp được người mà mình muốn cùng xây dựng cuộc sống”, Thục Anh tâm sự.\n\nNữ diễn viên cũng không cho rằng hôn nhân sẽ khiến mọi thứ tự nhiên trở nên hoàn hảo bởi cuộc sống gia đình chắc chắn đi kèm trách nhiệm và những điều cả hai phải học cách thích nghi. Cô nói: “Đôi khi, đó còn là động lực để tôi cố gắng nhiều hơn”.\n\nThục Anh chia sẻ thêm, cô đã dẫn chương trình tại VTVcab khoảng 3 năm nay và xem đây là công việc được mình theo đuổi lâu dài và đầu tư nghiêm túc. Dù vậy, cô vẫn mong có cơ hội tham gia những dự án phim hay, thử sức với các vai diễn thú vị để tiếp tục gặp gỡ khán giả trên màn ảnh.\n\nDiễn viên Đào Hiền Thục Anh sinh năm 2002, tốt nghiệp Đại học Ngoại thương. Cô từng tham gia “Vietnam’s Got Talent” với vai trò vũ công và được khán giả truyền hình biết đến qua các phim Hương vị tình thân, Nơi giấc mơ tìm về...\n\nHiện tại, bên cạnh diễn xuất, cô tập trung nhiều hơn cho công việc dẫn chương trình, trong đó có vai trò MC thể thao tại VTVcab.","author":"Hương Hồ","category":"Giải trí","publishedAt":"2026-10-21 13:30","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/nu-dien-vien-huong-vi-tinh-than-ket-hon-o-tuoi-24-he-lo-ve-ban-doi-20261021133008548.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/6TFQX0qocrYX1ZKyvEuOUx6SqcU=/zoom/1200_630/2026/10/21/thuc-anh4-cropped-1792563891441.jpg","crawledAt":"2026-10-21T13:43:11.663Z"},{"id":"dtri-20261021131601409","title":"Cần Thơ quy tập 158 liệt sĩ, hoàn tất lấy mẫu hài cốt 5.000 mộ khuyết danh","slug":"can-tho-quy-tap-158-liet-si-hoan-tat-lay-mau-hai-cot-5000-mo-khuyet-danh","excerpt":"Cần Thơ đã quy tập 158 hài cốt liệt sĩ, hoàn thành lấy mẫu sinh phẩm hơn 5.000 ngôi mộ thiếu thông tin ở 17 nghĩa trang để phục vụ việc giám định ADN, xác định danh tính liệt sĩ.","content":"(Dân trí) - Cần Thơ đã quy tập 158 hài cốt liệt sĩ, hoàn thành lấy mẫu sinh phẩm hơn 5.000 ngôi mộ thiếu thông tin ở 17 nghĩa trang để phục vụ việc giám định ADN, xác định danh tính liệt sĩ.\n\nNgày 21/10, Ban Chỉ đạo 515 TP Cần Thơ tổ chức hội nghị tổng kết công tác tìm kiếm, quy tập và xác định danh tính hài cốt liệt sĩ còn thiếu thông tin năm 2026; sơ kết giai đoạn 1 Chiến dịch 500 ngày đêm đẩy mạnh tìm kiếm, quy tập và xác định danh tính hài cốt liệt sĩ.\n\nNăm 2026, dù gặp nhiều khó khăn do địa hình thay đổi, thời tiết thất thường và nhân chứng ngày càng ít, thành phố vẫn vượt chỉ tiêu tìm kiếm, quy tập hài cốt liệt sĩ được giao, đồng thời hoàn thành lấy mẫu tại các nghĩa trang liệt sĩ.\n\nCụ thể, các lực lượng chuyên trách đã khảo sát 12 điểm thuộc 8 xã, phường, quy tập thành công 158 hài cốt liệt sĩ. Cần Thơ\n\nSau đó, thành phố tổ chức 2 đợt lễ viếng, truy điệu và an táng 158 hài cốt liệt sĩ, bảo đảm trang nghiêm, đúng quy định.\n\nĐối với công tác lấy mẫu sinh phẩm phục vụ giám định ADN, Ban Chỉ đạo 515 thành phố thành lập 2 đội lấy mẫu với 94 cán bộ, chiến sĩ và tổ công tác liên ngành theo dõi, đôn đốc thực hiện.\n\nĐến nay, Cần Thơ hoàn thành lấy mẫu tại 17/17 nghĩa trang liệt sĩ trên địa bàn. Các lực lượng đã khai quật 5.038 mộ, lấy 4.122 mẫu sinh phẩm hài cốt liệt sĩ, bàn giao 3.784 mẫu cho Viện Pháp y Quân đội; 338 mẫu còn lại được lưu trữ.\n\nSong song đó, Công an TP Cần Thơ thu nhận 3.562 mẫu sinh phẩm ADN của thân nhân liệt sĩ để phục vụ xác định danh tính. Qua các phương pháp nghiệp vụ, Sở Nội vụ thành phố đã xác định được danh tính 9 trường hợp bằng giám định ADN và 22 trường hợp bằng phương pháp thực chứng.\n\nPhát biểu tại hội nghị, ông Nguyễn Văn Khởi, Phó Chủ tịch UBND TP Cần Thơ, Trưởng Ban Chỉ đạo 515 thành phố, nhấn mạnh công tác tìm kiếm, quy tập và xác định danh tính hài cốt liệt sĩ là nhiệm vụ chính trị quan trọng, thể hiện nghĩa tình sâu nặng đối với những người đã hy sinh vì Tổ quốc.\n\nBước sang giai đoạn 2 Chiến dịch 500 ngày đêm, ông Khởi đề nghị các cấp, ngành nâng cao trách nhiệm người đứng đầu, đẩy mạnh tuyên truyền, rà soát thông tin, khảo sát các khu vực có mộ liệt sĩ; đồng thời bảo đảm lực lượng, phương tiện, kinh phí và thực hiện tốt chế độ, chính sách.\n\nDịp này, UBND TP Cần Thơ khen thưởng 27 tập thể và 116 cá nhân có thành tích xuất sắc trong công tác tìm kiếm, quy tập, xác định danh tính hài cốt liệt sĩ và tổ chức lễ viếng, truy điệu trong giai đoạn 1 chiến dịch.","author":"Hồng Nhung","category":"Nội vụ","publishedAt":"2026-10-21 13:16","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/can-tho-quy-tap-158-liet-si-hoan-tat-lay-mau-hai-cot-5000-mo-khuyet-danh-20261021131601409.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/ycJU_QcAauCcaSyoHwhqsi12d1k=/zoom/1200_630/2026/10/21/hai-co-liet-si-can-tho-1-cropped-1792563074280.jpg","crawledAt":"2026-10-21T13:43:33.438Z"},{"id":"dtri-20261021131018369","title":"Vì sao ông Zelensky chấp nhận rủi ro, công khai phản ứng lại ông Trump?","slug":"vi-sao-ong-zelensky-chap-nhan-rui-ro-cong-khai-phan-ung-lai-ong-trump","excerpt":"Theo giới chức Ukraine, việc giữ im lặng lúc này rủi ro hơn nhiều so với việc lên tiếng, trong bối cảnh Tổng thống Mỹ Donald Trump đang đi xa hơn bao giờ hết trong việc ưu tiên lợi ích của Nga.","content":"(Dân trí) - Theo giới chức Ukraine, việc giữ im lặng lúc này rủi ro hơn nhiều so với việc lên tiếng, trong bối cảnh Tổng thống Mỹ Donald Trump đang đi xa hơn bao giờ hết trong việc ưu tiên lợi ích của Nga.\n\nTổng thống Mỹ Donald Trump gần đây liên tục gia tăng sức ép đối với Ukraine. Kiev đã rơi vào tình thế này trước đây, song lần này, Kiev gặp khó khăn hơn khi Washington có xu hướng ưu tiên lợi ích của Nga nhiều hơn.\n\nTổng thống Ukraine Volodymyr Zelensky đã chọn một chiến thuật khác: công khai phản ứng. Một quan chức cấp cao của Ukraine ví hành động này như cơ hội cuối cùng để phát đi cảnh báo khi một “trận sóng thần” đang tới gần.\n\nNgay cả trước khi xảy ra căng thẳng mới nhất với ông Trump, tình hình đối với Ukraine đã vô cùng khó khăn. Chiến dịch không kích của Nga đã phá hủy nghiêm trọng hạ tầng năng lượng và nền kinh tế của Ukraine. Hệ thống phòng không của Ukraine đã cạn kiệt khi mùa đông khắc nghiệt đang đến gần.\n\nTrong khi đó, mới đây, ông Trump công bố thỏa thuận cho phép Nga xuất khẩu hàng triệu tấn dầu diesel vào Mỹ và thị trường thế giới, dỡ bỏ các lệnh trừng phạt đối với Nga và gây áp lực buộc Ukraine dừng các cuộc tấn công vào nhà máy lọc dầu Nga.\n\nChưa dừng lại, Lầu Năm Góc bị cáo buộc đã hạn chế Ukraine sử dụng hệ thống liên lạc vệ tinh Starlink, ngừng chia sẻ thông tin tình báo quân sự và hoãn giao tên lửa Patriot. Giới chức Mỹ phủ nhận các cáo buộc này, song Ukraine cho biết, họ đã không nhận được cảnh báo sớm về một số cuộc tấn công gần đây của Nga.\n\nCăng thẳng leo thang lên một nấc mới khi ông Trump cho rằng “Nga đã cư xử ổn ở Ukraine và họ chưa làm gì nhiều\".\n\nCác nhà lãnh đạo Ukraine cho rằng ông Trump đang đặt lợi ích của Nga lên trên an ninh của Ukraine và Ukraine không còn cách nào khác là “phản pháo”, ngay cả khi đối mặt với những nguy cơ đi kèm.\n\n\"Ông Trump đang công khai ép chúng tôi phải hàng phục. Đó chính là thực trạng lúc này\", Mykhailo Samus, một chuyên gia an ninh và quân sự Ukraine, nhận định.\n\nTrước đây, Kiev cố giữ tông giọng ngoại giao bất chấp sức ép từ Washington. Ví dụ, sau cuộc tranh cãi nảy lửa tại Phòng Bầu dục vào tháng 2/2025 giữa hai Tổng thống, Kiev đã nhanh chóng cảm ơn và ca ngợi sự hỗ trợ của Mỹ. Ukraine tiếp tục nhấn mạnh tầm quan trọng của việc duy trì mối quan hệ đối tác với Mỹ khi ông Trump tìm cách kết thúc cuộc xung đột. Trong vòng một tháng, Kiev đã đề xuất một lệnh ngừng bắn ngay lập tức, vô điều kiện, mặc dù Nga không chấp nhận.\n\nKhi đó cũng như bây giờ, Ukraine hy vọng tránh được việc Mỹ cắt giảm nguồn hỗ trợ quân sự và tình báo quan trọng. Kiev có thể sẽ hướng tới việc hạ nhiệt căng thẳng, sau khi đã phát đi thông điệp cứng rắn về những động thái của chính quyền Tổng thống Trump.\n\nSau khi trao đổi với Ngoại trưởng Mỹ Marco Rubio đầu tuần này, ông Zelensky đã viết trên mạng xã hội: \"Cảm ơn tất cả mọi người ở Mỹ đã hỗ trợ các cách tiếp cận công bằng”. Tuy nhiên, ông không nhắc tới ông Trump.\n\nVitaly Portnikov, một nhà bình luận chính trị tại Ukraine, nhận định những động thái của ông Trump đã đẩy ông Zelensky vào một tình thế bất đắc dĩ. Dù có những lúc công kích tính cách của ông Trump, nhưng ông Zelensky đã chọn cách nhấn mạnh vào thực địa, công khai thừa nhận những khó khăn mà Ukraine phải đối mặt do các hạn chế từ Mỹ.\n\nÔng Zelensky đã nhắc lại những vấn đề đó trong cuộc gọi video với một nhóm nghị sĩ lưỡng đảng Mỹ hồi đầu tuần, với hy vọng áp lực chính trị nội địa sẽ ngăn ông Trump đi xa hơn.\n\nÔng Portnikov coi cuộc đối thoại của ông Zelensky với ông Rubio là một tín hiệu tốt.\n\n“Nếu Tổng thống Ukraine đưa ra những tuyên bố cứng rắn hướng tới Mỹ, trong khi Ngoại trưởng Mỹ vẫn dành thời gian nói chuyện với ông trong chuyến công du châu Á, điều đó cho thấy chính quyền ông Trump chưa sẵn sàng để quan hệ Mỹ - Ukraine đổ vỡ”, ông Portnikov nhận định.","author":"Minh Phương","category":"Thế giới","publishedAt":"2026-10-21 13:10","source":"dantri.com.vn","url":"https://dantri.com.vn/the-gioi/vi-sao-ong-zelensky-chap-nhan-rui-ro-cong-khai-phan-ung-lai-ong-trump-20261021131018369.htm","categories":["Thế giới"],"categoryIds":["the-gioi"],"thumbnail":"https://cdnphoto.dantri.com.vn/g-8L5INajHugF6OAjLpOQUaLpgg=/zoom/1200_630/2026/10/21/trump-zelensky-reuters-cropped-1792567263420.jpg","crawledAt":"2026-10-21T13:42:23.270Z"},{"id":"dtri-20261021130723320","title":"Đất Thủ Thiêm hơn 1 tỷ đồng/m2, căn hộ xung quanh đắt cỡ nào?","slug":"dat-thu-thiem-hon-1-ty-dongm2-can-ho-xung-quanh-dat-co-nao","excerpt":"Căn hộ tại Thủ Thiêm chủ yếu thuộc phân khúc cao cấp, hạng sang, giá phổ biến 200-500 triệu đồng/m2, nhiều căn có giá vượt 100 tỷ đồng.","content":"(Dân trí) - Căn hộ tại Thủ Thiêm chủ yếu thuộc phân khúc cao cấp, hạng sang, giá phổ biến 200-500 triệu đồng/m2, nhiều căn có giá vượt 100 tỷ đồng.\n\nUBND TPHCM vừa duyệt giá khởi điểm đấu giá 3 khu đất tại Khu đô thị mới Thủ Thiêm, phường An Khánh, với tổng diện tích hơn 23.600m2. Tổng giá khởi điểm của 3 lô đất vượt 14.500 tỷ đồng.\n\nTrong đó, lô 1.K3.5.HH (3-12) có giá khởi điểm hơn 10.198 tỷ đồng; lô 1.K3.1.OD (3-8) hơn 2.632 tỷ đồng và lô 1.K3.3.HH (3-9) gần 1.745 tỷ đồng. Riêng lô 1.K3.5.HH, trước đây là lô 3-12, rộng hơn 10.000m2, được quy hoạch phát triển công trình hỗn hợp nhóm nhà ở và dịch vụ, trong đó chức năng ở chiếm 95%. Công trình được xây tối đa 25 tầng, quy mô dân số tối đa 3.420 người. Giá khởi điểm khu đất này tương đương hơn 1 tỷ đồng/m2.\n\nTheo ghi nhận, giá căn hộ tại khu vực này hiện phổ biến từ khoảng 180 triệu đồng/m2, nhiều dự án ở mức 200-500 triệu đồng/m2. Phần lớn nguồn cung thuộc phân khúc cao cấp, hạng sang, với giá mỗi căn từ hơn 10 tỷ đồng đến hàng chục tỷ đồng, thậm chí trên 100 tỷ đồng.\n\nCụ thể, The Metropole Thủ Thiêm hiện có giá khoảng 300-350 triệu đồng/m2, một số căn được rao gần 500 triệu đồng/m2 tùy vị trí và diện tích. Căn 2 phòng ngủ có giá khoảng 22-23 tỷ đồng, trong khi những căn diện tích lớn khoảng 280m2 được rao bán hơn 110 tỷ đồng.\n\nGiá rao bán tại đây giảm 3,5% trong một năm qua và thấp hơn khoảng 34% so với đỉnh hồi tháng 2. Dự án do Công ty cổ phần Quốc Lộc Phát làm chủ đầu tư, Sơn Kim Land phát triển, quy mô khoảng 7,6ha với khoảng 1.300 căn hộ. Phân khu đầu tiên được bàn giao cuối năm 2021.\n\nCùng khu vực, Empire City đang có giá căn hộ khoảng 200-300 triệu đồng/m2, tăng hơn 27% so với năm ngoái nhưng giảm 5,4% so với tháng 4. Căn 1 phòng ngủ có giá khoảng 12-16 tỷ đồng, 2 phòng ngủ khoảng 19-28 tỷ đồng, còn căn 3 phòng ngủ có thể lên 30-60 tỷ đồng. Dự án rộng khoảng 14,5ha, do liên doanh Keppel Land, Tiến Phước, Trần Thái và Gaw Capital phát triển. Những căn hộ đầu tiên được bàn giao từ năm 2020.\n\nMức giá tại The River Thủ Thiêm thấp hơn một số dự án trên, nhưng vẫn thuộc nhóm cao cấp với khoảng 150-300 triệu đồng/m2. Căn 1 phòng ngủ được rao khoảng 10-11 tỷ đồng, 2 phòng ngủ khoảng 16-25 tỷ đồng và 3 phòng ngủ khoảng 28-30 tỷ đồng. Dự án do Refico phát triển, gồm 525 căn hộ và 17 căn thương mại, đã được bàn giao và vận hành từ năm 2022.\n\nTrong khi đó, Thủ Thiêm Zeit River có giá khoảng 180-300 triệu đồng/m2. Căn 1 phòng ngủ khoảng 12-15 tỷ đồng, 2 phòng ngủ 18-22 tỷ đồng và 3 phòng ngủ 26-36 tỷ đồng. Dự án do GS E&C phát triển, giai đoạn đầu có khoảng 300 căn hộ, các tòa tháp đầu tiên được bàn giao trong giai đoạn 2024-2025. Giá tại đây tăng khoảng 26% trong một năm nhưng giảm 7,8% so với tháng 3.\n\nỞ phân khúc thấp hơn so với các dự án ven sông, căn hộ tại Khu đô thị Sala hiện có giá khoảng 150-200 triệu đồng/m2. Giá tăng hơn 23% trong một năm nhưng giảm khoảng 2% so với đầu năm. Khu đô thị do Đại Quang Minh phát triển, quy mô khoảng 227ha, gồm căn hộ, biệt thự, nhà phố thương mại và các công trình dịch vụ. Các dự án căn hộ tại đây đã được bàn giao từ nhiều năm và hiện chủ yếu giao dịch trên thị trường thứ cấp.\n\nKhông xa Thủ Thiêm, tại khu vực trung tâm TPHCM, một dự án có tên One Central Saigon đang gây chú ý bởi mặt bằng giá dự kiến rất cao, chạm mốc 1 tỷ đồng/m2. Dự án nằm đối diện chợ Bến Thành, trên khu đất khoảng 8.500m2 thuộc khu tứ giác Bến Thành, với 4 mặt tiền đường Phạm Ngũ Lão, Calmette, Lê Thị Hồng Gấm và Phó Đức Chính.\n\nSau khi tái khởi động từ giữa tháng 3, dự án dự kiến hoàn thành sau khoảng 30 tháng thi công. One Central Saigon do Công ty TNHH Saigon Glory làm chủ đầu tư, Masterise Homes tham gia phát triển, được quy hoạch thành tổ hợp bất động sản cao cấp gồm căn hộ hàng hiệu, khách sạn, văn phòng và thương mại.\n\nDự án gồm 2 tòa tháp cao khoảng 47-56 tầng, 6 tầng hầm, tổng diện tích sàn khoảng 195.000m2. Khu căn hộ mang thương hiệu The Ritz-Carlton Residences, hướng tới nhóm khách hàng siêu giàu.\n\nSáng 21/10, cầu đi bộ qua sông Sài Gòn tại TPHCM đã hợp long sau hơn một năm thi công. Công trình dài 720m, có thiết kế hình lá dừa, tổng vốn đầu tư gần 1.000 tỷ đồng, kết nối Bến Bạch Đằng với khu đô thị Thủ Thiêm. Điều này được kỳ vọng tạo thêm điểm kết nối giữa khu vực trung tâm TPHCM với Thủ Thiêm, đồng thời góp phần hình thành không gian công cộng ven sông và điểm nhấn mới cho khu vực.","author":"Lê Tỉnh","category":"Bất động sản","publishedAt":"2026-10-21 13:07","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/dat-thu-thiem-hon-1-ty-dongm2-can-ho-xung-quanh-dat-co-nao-20261021130723320.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/hjbo8YQlxy2ulOtYg_dmjHhl4uI=/zoom/1200_630/2026/10/21/khu-can-ho-cao-cap-tai-thu-thiem-cropped-cropped-1792562629135.jpg","crawledAt":"2026-10-21T13:42:59.268Z"},{"id":"dtri-20261021130349688","title":"Hơn 203 triệu đồng tiếp sức người con từng được mẹ hiến thận","slug":"hon-203-trieu-dong-tiep-suc-nguoi-con-tung-duoc-me-hien-than","excerpt":"“Mẹ ơi, bán nhà đi! Nếu mẹ con mình mất thì xin vào chùa...”","content":"Mã số: 5998\n\n(Dân trí) - Từng được mẹ hiến thận cứu sống, nay anh Phạm Ngọc Chiến bị suy thận giai đoạn cuối, mong ghép thận lần hai. Bạn đọc Dân trí và các nhà hảo tâm cảm thương đã chung tay hỗ trợ anh hơn 203 triệu đồng.\n\nVừa qua, báo Dân trí đã phối hợp cùng khoa Nội thận lọc máu và phòng Công tác xã hội, Bệnh viện Trung ương Quân đội 108, trao biển biểu trưng số tiền 183.268.558 đồng bạn đọc hỗ trợ tới anh Phạm Ngọc Chiến (SN 1991, trú tại thôn 10 Nghĩa Thái, xã Nghĩa Hưng, tỉnh Ninh Bình).\n\nBên cạnh đó, Quỹ Thiện Tâm ủng hộ 20 triệu đồng, nâng tổng số tiền anh Chiến nhận được lên hơn 203 triệu đồng.\n\nAnh Chiến là nhân vật trong bài viết “Mẹ ơi, bán nhà đi! Nếu mẹ con mình mất thì xin vào chùa...”, đăng trên chuyên mục Tấm lòng Nhân ái của báo Dân trí.\n\nĐón nhận sự hỗ trợ nghĩa tình, anh Chiến xúc động gửi lời cảm ơn tới bạn đọc Dân trí và các nhà hảo tâm.\n\n“Số tiền hơn 203 triệu đồng đã giúp tôi trang trải được rất nhiều chi phí trong thời gian chờ nguồn thận hiến mới để ghép thận lần thứ 2. Tôi thực sự biết ơn bạn đọc báo Dân trí cùng các nhà hảo tâm!”, anh Chiến chia sẻ.\n\nAnh Chiến phát hiện mắc bệnh thận từ năm 2019. Tháng 8 cùng năm, anh được mẹ là bà Nguyễn Thị Mỹ hiến 1 quả thận. Ca ghép khi ấy thắp lên hy vọng về một cuộc sống khỏe mạnh hơn cho anh.\n\nTuy nhiên, đầu năm 2025, quả thận ghép bắt đầu suy giảm chức năng nghiêm trọng. Đến tháng 3/2026, anh Chiến phải trở lại bệnh viện chạy thận nhân tạo. Hiện, anh duy trì lịch chạy thận định kỳ 2 lần/tuần.\n\nTheo các bác sĩ, ghép thận lần thứ 2 là cơ hội để anh Chiến cải thiện sức khỏe, hướng tới cuộc sống bình thường. Thế nhưng, chi phí ghép thận và điều trị sau ghép ước tính khoảng 1,6 tỷ đồng, vượt xa khả năng tài chính của gia đình.\n\nBố mất sớm, anh Chiến và mẹ nương tựa nhau trong căn nhà nhỏ. Bà Mỹ đã dành gần như toàn bộ tiền bạc, sức lực để chạy chữa cho con. Chi phí điều trị trước đó ước tính khoảng 500-600 triệu đồng. Tiền dành dụm đã cạn, những khoản vay mượn vẫn chưa thể trả hết.\n\nTrong lúc bế tắc, anh Chiến từng nghẹn ngào xin mẹ bán nhà để trang trải nợ nần, mong mẹ đỡ vất vả. Thế nhưng, căn nhà là nơi nương náu duy nhất của 2 mẹ con. Nếu bán đi, họ sẽ không còn chỗ ở.\n\nSự chung tay của bạn đọc Dân trí và các nhà hảo tâm đã tiếp thêm nguồn lực để anh Chiến duy trì điều trị, giúp 2 mẹ con vơi bớt gánh nặng kinh tế. Dù chặng đường phía trước còn nhiều khó khăn, sự sẻ chia ấy đã thắp thêm hy vọng để anh tiếp tục chờ cơ hội ghép thận, hướng tới cuộc sống tốt đẹp hơn.","author":"Nguyễn Thùy Hương","category":"Nhân ái","publishedAt":"2026-10-21 13:03","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/hon-203-trieu-dong-tiep-suc-nguoi-con-tung-duoc-me-hien-than-20261021130349688.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/MKqAuNJQZuPtIebIiTqTzFkZVm0=/zoom/1200_630/2026/10/21/nhan-ai-trao-tien-anh-chien-1-cropped-1792560800315.jpg?watermark=v1","crawledAt":"2026-10-21T13:43:37.741Z"},{"id":"dtri-20261021125430546","title":"Bắt thêm 2 người liên quan vụ án Hải \"Sapa TV\"","slug":"bat-them-2-nguoi-lien-quan-vu-an-hai-sapa-tv","excerpt":"Hai người vừa bị khởi tố, bắt giữ là kế toán và thủ quỹ của Công ty Cổ phần Sản xuất và Thương mại tổng hợp Hoàng Nam.","content":"(Dân trí) - Hai người vừa bị khởi tố, bắt giữ là kế toán và thủ quỹ của Công ty Cổ phần Sản xuất và Thương mại tổng hợp Hoàng Nam.\n\nTiếp tục điều tra mở rộng vụ án liên quan tới Hải \"Sapa TV\", ngày 21/10, Công an tỉnh Lào Cai cho biết đã ra quyết định khởi tố bị can, thi hành lệnh bắt bị can để tạm giam với Lê Thanh Hiển (SN 1981) và Đỗ Kim Chung (SN 1992, cùng ở phường Lào Cai) về tội Vi phạm quy định về kế toán gây hậu quả nghiêm trọng.\n\nTheo cảnh sát, hai người này là kế toán và thủ quỹ của Công ty Cổ phần Sản xuất và Thương mại tổng hợp Hoàng Nam.\n\nCông an tỉnh Lào Cai đang tiếp tục điều tra, làm rõ vai trò, hành vi của các cá nhân, tổ chức có liên quan tới vụ án để xử lý nghiêm theo quy định của pháp luật.\n\nTrước đó, Công an tỉnh Lào Cai đã khởi tố, bắt bị can để tạm giam đối với Vũ Hoàng Hải (tức Hải \"Sapa TV\", SN 1986, ở phường Lào Cai) để điều tra về tội Lừa dối khách hàng.\n\nNgoài Hải, Công an tỉnh Lào Cai cũng khởi tố Phạm Văn Hà (SN 1982, ở phường Lào Cai, tỉnh Lào Cai), Giám đốc Công ty CP sản xuất và Thương mại tổng hợp Hoàng Nam và Bùi Thị Kim Tuyên (SN 1988), vợ của Vũ Hoàng Hải, về tội Vi phạm quy định về công tác kế toán gây hậu quả nghiêm trọng.\n\nLực lượng chức năng xác định, Vũ Hoàng Hải lợi dụng ảnh hưởng trên các nền tảng mạng xã hội, chỉ đạo vợ là Bùi Thị Kim Tuyên ký hợp đồng tiêu thụ bán sản phẩm thịt trâu sấy khô tê cay do Công ty CP sản xuất và Thương mại tổng hợp Hoàng Nam sản xuất từ nguyên liệu là thịt trâu đông lạnh Ấn Độ.\n\nSau đó Vũ Hoàng Hải và vợ quảng cáo trên các nền tảng mạng xã hội là \"Thịt trâu sấy đặc sản Tây Bắc\" và in logo của Hải \"Sapa TV\" để bán ra thị trường.\n\nQuá trình điều tra từ năm 2022 đến năm 2025, Bùi Thị Kim Tuyên đã mua của Công ty CP sản xuất và Thương mại tổng hợp Hoàng Nam số lượng lớn thịt trâu sấy khô tê cay với số tiền 30 tỷ đồng để bán ra thị trường.","author":"Trần Thanh","category":"Pháp luật","publishedAt":"2026-10-21 12:54","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/bat-them-2-nguoi-lien-quan-vu-an-hai-sapa-tv-20261021125430546.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/zaLuv0TuOnmeCm5Mwey5RW7rBuo=/zoom/1200_630/2026/10/21/khoi-to-edited-cropped-1792561928999.jpg","crawledAt":"2026-10-21T13:42:30.168Z"},{"id":"dtri-20261021124432251","title":"Thứ trưởng Bộ Nội vụ làm tổ trưởng xây dựng vị trí việc làm, biên chế","slug":"thu-truong-bo-noi-vu-lam-to-truong-xay-dung-vi-tri-viec-lam-bien-che","excerpt":"Bộ Nội vụ thành lập Tổ công tác rà soát, hoàn thiện vị trí việc làm, xác định nhu cầu nhân lực và xây dựng phương án biên chế giai đoạn 2027-2031 của Bộ.","content":"(Dân trí) - Bộ Nội vụ thành lập Tổ công tác rà soát, hoàn thiện vị trí việc làm, xác định nhu cầu nhân lực và xây dựng phương án biên chế giai đoạn 2027-2031 của Bộ.\n\nBộ Nội vụ vừa ban hành quyết định về việc thành lập Tổ công tác rà soát, hoàn thiện vị trí việc làm, xác định nhu cầu nhân lực và xây dựng phương án biên chế giai đoạn 2027-2031 của Bộ.\n\nTổ trưởng Tổ công tác là Thứ trưởng Bộ Nội vụ Trương Hải Long.\n\nTổ công tác có nhiệm vụ tham mưu Bộ trưởng chỉ đạo, tổ chức thực hiện việc rà soát, hoàn thiện vị trí việc làm, xác định nhu cầu nhân lực và xây dựng phương án biên chế giai đoạn 2027-2031 đối với các cơ quan, đơn vị thuộc, trực thuộc Bộ theo yêu cầu của cấp có thẩm quyền.\n\nĐơn vị này cũng hướng dẫn các cơ quan, đơn vị thuộc, trực thuộc Bộ rà soát chức năng, nhiệm vụ, quyền hạn; xác định công việc, sản phẩm, trách nhiệm và yêu cầu năng lực; rà soát danh mục vị trí việc làm, bản mô tả công việc, khung năng lực; thống kê khối lượng, thời gian thực hiện công việc, nhân lực và biên chế hiện có theo hướng dẫn của Ban Tổ chức Trung ương.\n\nBên cạnh nhiệm vụ theo dõi, kiểm tra tiến độ, chất lượng thực hiện; đối chiếu hồ sơ, tài liệu, dữ liệu và kết quả kê khai..., Tổ công tác còn tổng hợp kết quả rà soát; tham mưu hoàn thiện vị trí việc làm, xác định nhu cầu nhân lực, đề xuất bố trí, sử dụng, cơ cấu lại đội ngũ và xây dựng phương án biên chế giai đoạn 2027-2031 của Bộ; hoàn thiện hồ sơ, báo cáo Bộ trưởng xem xét, quyết định hoặc trình cấp có thẩm quyền theo quy định.\n\nTổ công tác còn phối hợp với các cơ quan, đơn vị liên quan chuẩn hóa, tổng hợp và cung cấp dữ liệu thuộc phạm vi quản lý của Bộ, phục vụ xây dựng cơ sở dữ liệu vị trí việc làm theo yêu cầu của cấp có thẩm quyền...\n\nTổ công tác làm việc theo chế độ kiêm nhiệm. Tổ trưởng chỉ đạo, điều hành hoạt động, phân công nhiệm vụ cho Tổ phó và các thành viên; quyết định chương trình, kế hoạch làm việc, tổ chức họp và làm việc với các cơ quan, đơn vị theo yêu cầu nhiệm vụ.","author":"Hoa Lê","category":"Nội vụ","publishedAt":"2026-10-21 12:44","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/thu-truong-bo-noi-vu-lam-to-truong-xay-dung-vi-tri-viec-lam-bien-che-20261021124432251.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/1wHKTevxLHoIQocPAE9KihcYbhA=/zoom/1200_630/2026/10/21/17924900354452431454763168732891243145476316873289155e440a874098fb656a55af11fa04140-cropped-1792561371151.jpg","crawledAt":"2026-10-21T13:43:35.574Z"},{"id":"dtri-20261021123826748","title":"Cô gái 23 tuổi được tư vấn căng da mặt sau 4 lần phẫu thuật thẩm mỹ","slug":"co-gai-23-tuoi-duoc-tu-van-cang-da-mat-sau-4-lan-phau-thuat-tham-my","excerpt":"Tiếp nhận trường hợp cô gái 23 tuổi được tư vấn căng da mặt sau 4 lần phẫu thuật thẩm mỹ, bác sĩ bất ngờ trước những thông tin về quá trình can thiệp trước đó.","content":"(Dân trí) - Tiếp nhận trường hợp cô gái 23 tuổi được tư vấn căng da mặt sau 4 lần phẫu thuật thẩm mỹ, bác sĩ bất ngờ trước những thông tin về quá trình can thiệp trước đó.\n\nTrao đổi với phóng viên Dân trí ngày 21/10, TS.BS Nguyễn Phan Tú Dung, Giám đốc bệnh viện đa khoa ở TPHCM cho biết, thời gian qua ông đã tiếp nhận một trường hợp bệnh nhân đến tư vấn để căng da mặt khi tuổi còn rất trẻ.\n\nBệnh nhân là một cô gái 23 tuổi, vào viện trong tình trạng da mặt chảy xệ. Khai thác bệnh sử, bệnh nhân cho biết trước đó đã xem thông tin làm đẹp trên mạng và được một phụ nữ tư vấn, giới thiệu đến can thiệp tại một cơ sở y tế chuyên khoa thẩm mỹ lớn.\n\nTại đây, người tư vấn dẫn bệnh nhân đến gặp một người mặc áo blouse. Người tư vấn giải thích đây là một bác sĩ nổi tiếng nhưng rất \"kín tiếng\", không xuất hiện trên mạng nên sẽ không thể tìm thấy thông tin.\n\nSau khi được tư vấn can thiệp để xử lý tình trạng móm và hô cùng những vấn đề khác trên mặt, cô gái đã thực hiện tổng cộng 4 lần can thiệp thẩm mỹ, trong đó có hạ gò má và trượt cằm. Tuy nhiên, hậu phẫu một thời gian, khuôn mặt cô không cải thiện như mong muốn, đồng thời xuất hiện tình trạng da chảy xệ.\n\nKhi quay lại bệnh viện, cô tiếp tục được tư vấn căng da mặt. Lúc này, bệnh nhân quyết định đổi sang nơi khác xử lý.\n\nBác sĩ Tú Dung cho biết, qua thăm khám, ông rất bất ngờ khi xem hình ảnh mặt cô gái trước phẫu thuật, vì hình ảnh không cho thấy tình trạng móm, hô đến mức cần thực hiện hàng loạt can thiệp như bệnh nhân mô tả.\n\nTheo bác sĩ, các chỉ định can thiệp trong trường hợp này cần được xem xét về tính phù hợp.\n\n\"Tôi thực sự giật mình và bức xúc trước việc một người còn rất trẻ phải trải qua nhiều cuộc phẫu thuật thẩm mỹ, sau đó lại đứng trước đề nghị tiếp tục can thiệp để khắc phục tình trạng không mong muốn.\n\nĐiều cần xem xét trong trường hợp này là tính phù hợp của chỉ định ban đầu. Việc tiếp tục đề nghị bệnh nhân căng da mặt sau các can thiệp trước đó đặt ra câu hỏi về quá trình tư vấn và trách nhiệm chuyên môn trong việc tư vấn, điều trị cho người bệnh.\n\nTôi đề nghị cô gái cung cấp tên bác sĩ mổ để kiểm tra, nhưng cũng không tìm được thông tin tương ứng trên mạng\", bác sĩ Tú Dung nói.\n\nQua trường hợp trên, bác sĩ Tú Dung cảnh báo, người có nhu cầu làm đẹp cần bình tĩnh kiểm chứng thông tin trước khi quyết định phẫu thuật.\n\nViệc được đưa đến một bệnh viện lớn hay được giới thiệu về một bác sĩ nổi tiếng không thể thay thế việc xác định rõ người chịu trách nhiệm chuyên môn đối với ca mổ.\n\nNgười bệnh cần biết tên bác sĩ, tìm hiểu thông tin hành nghề trên cổng thông tin của ngành y tế và làm rõ ai sẽ thực hiện, ai chịu trách nhiệm trong quá trình điều trị. Những lời giới thiệu như \"nổi tiếng nhưng kín tiếng\" không nên trở thành lý do khiến khách hàng bỏ qua việc kiểm tra.\n\n\"Sự thận trọng ngay từ khâu lựa chọn và tư vấn có thể giúp người bệnh tránh rơi vào tình trạng phải tiếp tục khắc phục sau những can thiệp thiếu phù hợp\", BS nhấn mạnh.","author":"Hoàng Lê","category":"Sức khỏe","publishedAt":"2026-10-21 12:38","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/co-gai-23-tuoi-duoc-tu-van-cang-da-mat-sau-4-lan-phau-thuat-tham-my-20261021123826748.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/LzUC3bhM4x8RbhKPL1aujYpGZ0U=/zoom/1200_630/2026/10/21/cang-da-mat-cropped-1792560990030.jpg","crawledAt":"2026-10-21T13:42:35.750Z"},{"id":"dtri-20261021123742201","title":"Tỷ phú Hong Kong từng đi cọ toilet, cuối đời hiến hết gia sản làm từ thiện","slug":"ty-phu-hong-kong-tung-di-co-toilet-cuoi-doi-hien-het-gia-san-lam-tu-thien","excerpt":"Từ người lao động chân tay tại Hong Kong (Trung Quốc), Yu Pang Lin vươn lên trở thành ông trùm bất động sản, khách sạn với khối tài sản hàng tỷ USD. Cuối đời, ông không để lại thừa kế cho con.","content":"(Dân trí) - Từ người lao động chân tay tại Hong Kong (Trung Quốc), Yu Pang Lin vươn lên trở thành ông trùm bất động sản, khách sạn với khối tài sản hàng tỷ USD. Cuối đời, ông không để lại thừa kế cho con.\n\nMột câu nói nổi tiếng của ông được lưu truyền tới bây giờ: “Kể cả khi phải cọ toilet, tôi cũng cố gắng là người cọ sạch nhất”.\n\nTừ người lao động nghèo đến tỷ phú bất động sản\n\nYu Pang Lin (Dư Bành Niên) sinh năm 1922 tại tỉnh Hồ Nam (Trung Quốc). Ông lớn lên trong bối cảnh không có nhiều điều kiện thuận lợi để xây dựng sự nghiệp. Sau thời gian làm việc tại Thượng Hải, năm 1958, ông chuyển đến Hong Kong (Trung Quốc) để tìm kiếm cơ hội đổi đời.\n\nNhững ngày đầu tại vùng đất mới, Yu Pang Lin không sở hữu khối tài sản đáng kể. Ông từng làm công việc dọn dẹp, cọ toilet, lao động phụ và công nhân xây dựng để trang trải cuộc sống. Hành trình từ người làm thuê đến doanh nhân của ông bắt đầu bằng những công việc bình thường.\n\nBước ngoặt trong sự nghiệp kinh doanh của Yu Pang Lin đến khi ông tham gia lĩnh vực bất động sản. Ông có cơ hội theo chân một người chủ trong ngành này sang Đài Loan (Trung Quốc), từ đó từng bước xây dựng hoạt động kinh doanh riêng. Sau này, ông mở rộng đầu tư, mua những bất động sản có giá trị và bán lại với mức giá cao hơn nhiều lần so với ban đầu.\n\nKhông chỉ hoạt động trong lĩnh vực địa ốc, Yu Pang Lin còn phát triển kinh doanh khách sạn. Ông trở thành người đứng đầu khách sạn Panglin tại Thâm Quyến (Trung Quốc), đồng thời xây dựng đế chế kinh doanh bất động sản gắn với tên tuổi của mình.\n\nThành công của ông không đến từ một thương vụ duy nhất mà là quá trình tích lũy, đầu tư và mở rộng hoạt động kinh doanh trong nhiều năm. Từ một người lao động phải tự trang trải cuộc sống, Yu Pang Lin dần sở hữu những tài sản có giá trị lớn tại Trung Quốc.\n\nChủ nhân căn nhà cũ của huyền thoại võ thuật Lý Tiểu Long\n\nMột trong những bất động sản gắn liền với tên tuổi Yu Pang Lin là căn nhà từng thuộc sở hữu của huyền thoại võ thuật và điện ảnh Lý Tiểu Long tại khu Cửu Long Đường, Hong Kong.\n\nNăm 1974, Yu Pang Lin mua căn nhà với giá khoảng 1 triệu HKD (hơn 3,2 tỷ đồng). Ngôi nhà từng được sử dụng làm khách sạn cho thuê phòng theo giờ, trước khi câu chuyện về tương lai của bất động sản này thu hút sự quan tâm của người hâm mộ Lý Tiểu Long.\n\nNăm 2008, tỷ phú này đưa ra kế hoạch bán một số bất động sản để gây quỹ cứu trợ sau trận động đất ở Tứ Xuyên, trong đó có căn nhà cũ của Lý Tiểu Long.\n\nTheo The Guardian, năm 2009, Yu Pang Lin dự định sửa sang căn nhà, biến thành bảo tàng tưởng niệm ngôi sao võ thuật, với không gian trưng bày hiện vật, tư liệu về cuộc đời và sự nghiệp của ông.\n\nTuy nhiên, kế hoạch không được triển khai như kỳ vọng do những bất đồng về phương án phục dựng và quản lý. Căn nhà \bvẫn trở thành một phần đáng chú ý trong câu chuyện về di sản của Yu Pang Lin.\n\nTừ trải nghiệm cá nhân đến hành trình giúp người nghèo tìm lại ánh sáng\n\nNếu bất động sản giúp Yu Pang Lin xây dựng khối tài sản lớn, hoạt động thiện nguyện lại là lĩnh vực làm nên dấu ấn riêng của ông.\n\nTheo South China Morning Post, năm 2003, ông thành lập chương trình Pang Lin Bright Project, dành khoảng 500 triệu NDT (hơn 1.900 tỷ đồng) để tài trợ phẫu thuật đục thủy tinh thể miễn phí cho những bệnh nhân nghèo.\n\nĐộng lực của chương trình xuất phát một phần từ trải nghiệm cá nhân. Yu Pang Lin từng trải qua phẫu thuật đục thủy tinh thể và hiểu được ý nghĩa của việc khôi phục thị lực. Ông muốn những người có hoàn cảnh khó khăn cũng được điều trị, thay vì phải sống chung với nguy cơ mất khả năng nhìn chỉ vì thiếu tiền.\n\nTừ năm 2003 đến 2010, quỹ của ông đã tài trợ hơn 150.000 ca phẫu thuật đục thủy tinh thể trên khắp Trung Quốc. Từ năm 1984, sau chuyến trở về quê nhà và chứng kiến điều kiện chăm sóc y tế còn thiếu thốn tại các vùng nông thôn, ông đã bắt đầu quan tâm đến việc hỗ trợ cộng đồng.\n\nBan đầu, ông quyên tặng xe cứu thương cho các bệnh viện địa phương. Tuy nhiên, trải nghiệm này khiến ông nhận ra rằng việc trao tiền hoặc tài sản đơn thuần chưa chắc bảo đảm nguồn lực được sử dụng đúng mục đích.\n\nSau đó, ông hướng đến việc xây dựng tổ chức thiện nguyện riêng để chủ động hơn trong quá trình hỗ trợ người nghèo. Hoạt động từ thiện trở thành một phần quan trọng trong cuộc đời và cách ông nhìn nhận giá trị của tài sản.\n\nTheo Sina, Yu Pang Lin từng được ghi nhận là một trong những nhà từ thiện hào phóng nhất Trung Quốc. Ông đứng đầu bảng xếp hạng từ thiện Hurun trong nhiều năm liên tiếp và được tạp chí Time đưa vào danh sách 14 nhà từ thiện hàng đầu thế giới năm 2007.\n\nQuyết định không để lại tài sản cho con\n\nNăm 2010, ở tuổi 88, Yu Pang Lin tuyên bố dành toàn bộ tài sản trị giá khoảng 1,28 tỷ USD cho hoạt động từ thiện. Quyết định này gây chú ý bởi nhiều doanh nhân thường xem việc truyền lại gia sản cho thế hệ kế tiếp là mục tiêu quan trọng. Yu Pang Lin lại lựa chọn hướng đi khác. Ông muốn phần lớn thành quả của mình được sử dụng để hỗ trợ những người cần giúp đỡ.\n\nÔng lý giải rằng nếu con cái đủ năng lực, chúng không cần dựa vào tiền của cha; còn nếu không có năng lực, khối tài sản lớn có thể gây hại cho chúng. Ông cũng cho biết đã tạo điều kiện để các con trưởng thành trong môi trường đầy đủ và được học tập ở nước ngoài.\n\nĐây là quan điểm thể hiện cách nhìn của Yu Pang Lin về sự độc lập. Ông không xem tiền bạc là thứ mặc nhiên phải được chuyển giao cho con cháu, mà muốn thế hệ sau tự xây dựng cuộc sống bằng năng lực của mình.\n\nYu Pang Lin qua đời tại Thâm Quyến vào tháng 5/2015, hưởng thọ 93 tuổi. Việc thực hiện di chúc của ông không hoàn toàn thuận lợi. Khi ông mất, vấn đề pháp lý liên quan đến di sản đã được đưa ra tòa tại Hong Kong.\n\nNăm 2018, Tòa án cấp cao Hong Kong xác nhận tính hợp lệ của di chúc lập năm 2011. Phán quyết giúp thực hiện nguyện vọng mà Yu Pang Lin đã theo đuổi trong những năm cuối đời. Đó chính là sử dụng tài sản để phục vụ các mục đích thiện nguyện, thay vì phân chia như một khoản thừa kế thông thường.\n\nNhìn lại cuộc đời Yu Pang Lin, điều đáng chú ý không chỉ là hành trình từ người làm công việc dọn dẹp đến tỷ phú. Đó còn là quá trình chuyển đổi cách sử dụng tài sản: Từ phương tiện để tạo dựng sự nghiệp thành nguồn lực hỗ trợ y tế, giáo dục và những người có hoàn cảnh khó khăn.","author":"Mi Vân","category":"Đời sống","publishedAt":"2026-10-21 12:37","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/ty-phu-hong-kong-tung-di-co-toilet-cuoi-doi-hien-het-gia-san-lam-tu-thien-20261021123742201.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/zdx8Szx_hXWSolBUXUVHr4Phnzk=/zoom/1200_630/2026/10/21/yu-pang-linscmp-cropped-1792559729474.jpg","crawledAt":"2026-10-21T13:42:41.168Z"},{"id":"dtri-20261021120331235","title":"Honda Civic Type R ít sử dụng vẫn mất giá hơn 800 triệu đồng sau 9 tháng","slug":"honda-civic-type-r-it-su-dung-van-mat-gia-hon-800-trieu-dong-sau-9-thang","excerpt":"Honda Civic Type R là mẫu xe hiệu năng cao của thương hiệu Nhật Bản, nhưng sắp bị ngừng phân phối tại Việt Nam.","content":"(Dân trí) - Honda Civic Type R là mẫu xe hiệu năng cao của thương hiệu Nhật Bản, nhưng sắp bị ngừng phân phối tại Việt Nam.\n\nĐược mở bán từ cuối năm 2022 dưới dạng đặt hàng, Honda Civic Type R từng gây bất ngờ về khả năng giữ giá, khi những chiếc xe “lướt” (có số km sử dụng thấp) được rao bán lại với giá cao hơn xe mới.\n\nTuy nhiên, tình hình đã đảo chiều sau khi giá xe tăng lên 2,999 tỷ đồng từ đầu năm 2025 và hãng chuẩn bị ngừng bán mẫu xe này tại Việt Nam.\n\nTrên thị trường ô tô đã qua sử dụng, một cơ sở kinh doanh tư nhân tại Hà Nội đang chào bán một chiếc Honda Civic Type R màu xanh, sản xuất năm 2025 và đăng ký lần đầu vào tháng 1/2026, với mức giá 2,49 tỷ đồng. Đáng chú ý, người bán cho biết chiếc xe này mới đi khoảng 400km.\n\nChủ nhân ban đầu của chiếc Honda Civic Type R trong bài viết được cho là đã chi tổng cộng khoảng 3,32 tỷ đồng sau khi cộng thêm các khoản thuế, phí đăng ký.\n\nNhư vậy, dù mới đi khoảng 400km, chiếc xe hiệu năng cao này đã mất giá tới 829 triệu đồng chỉ sau 9 tháng kể từ khi đăng ký lần đầu. Số tiền này tương đương giá niêm yết của một mẫu SUV hạng C trên thị trường, chẳng hạn Ford Territory (giá từ 739 triệu đồng).\n\nCuối tháng 10/2025, Honda Việt Nam thông báo sẽ chính thức ngừng phân phối Civic Type R sau khi nhận đặt cọc 10 suất xe cuối cùng. Lô xe này dự kiến được hãng bàn giao từ tháng 12/2026 trong một sự kiện đặc biệt, kèm chứng nhận dành cho những khách hàng cuối cùng sở hữu mẫu xe hiệu năng cao này tại Việt Nam.\n\nViệc Honda Civic Type R rời thị trường để lại nhiều tiếc nuối trong giới mộ xe, nhưng nhìn vào tình hình kinh doanh thực tế, mẫu xe này ngày càng kén khách sau khi ra mắt. Cụ thể, Civic Type R ghi nhận doanh số 19 chiếc trong năm 2023, giảm xuống 11 xe trong năm 2024 và tiếp tục giảm còn 2 chiếc vào năm 2025, sau đợt tăng giá.\n\nHonda Civic Type R hiện hành được phát triển từ thế hệ thứ 11 của Civic, trong khi dòng sedan hạng C này đã được nâng cấp giữa vòng đời tại Việt Nam từ cuối năm 2024. So với phiên bản thường, Civic Type R sở hữu ngoại hình hầm hố hơn hẳn, với cánh gió lớn và hệ thống 3 ống xả trung tâm.\n\nBên dưới nắp ca-pô, Honda Civic Type R được trang bị động cơ tăng áp 2.0L, đi kèm hộp số sàn 6 cấp và hệ dẫn động cầu trước. Cấu hình này sản sinh công suất tối đa 315 mã lực và mô-men xoắn cực đại 420Nm.\n\nĐáng chú ý, hộp số sàn có công nghệ vù ga tự động (Rev Match), giúp xe tự động điều chỉnh vòng tua động cơ khi người lái về số thấp, qua đó hạn chế cảm giác giật, khựng.\n\nNếu không lựa chọn Honda Civic Type R, người dùng Việt vẫn có thể cân nhắc một số mẫu xe hiệu năng cao giá dễ tiếp cận hơn, ví dụ như Volkswagen Golf R Performance 4Motion (1,898 tỷ đồng) hay Skoda Octavia RS (1,608 tỷ đồng). Trong đó, Golf R sở hữu sức mạnh ngang ngửa Civic Type R.","author":"Nguyễn Lâm","category":"Xe ++","publishedAt":"2026-10-21 12:03","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/honda-civic-type-r-it-su-dung-van-mat-gia-hon-800-trieu-dong-sau-9-thang-20261021120331235.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/rH5Os99tDuTrYWcI2FoDzKB-eo4=/zoom/1200_630/2026/10/21/honda-civic-type-r-it-su-dung-van-mat-gia-hon-800-trieu-dong-sau-9-thang-anh1-cropped-1792558861970.jpg","crawledAt":"2026-10-21T13:43:27.865Z"},{"id":"dtri-20261021115825703","title":"Thành Cát Tư Hãn: Cuộc đời lẫy lừng và ngôi mộ bí ẩn 800 năm chưa tìm thấy","slug":"thanh-cat-tu-han-cuoc-doi-lay-lung-va-ngoi-mo-bi-an-800-nam-chua-tim-thay","excerpt":"Từ một cậu bé bị bỏ rơi trên thảo nguyên, Thành Cát Tư Hãn đã dựng nên một đế chế lớn mạnh trong lịch sử. Nhưng gần 800 năm sau khi ông qua đời, nơi chôn cất của ông vẫn là bí ẩn lớn trên thế giới.","content":"(Dân trí) - Từ một cậu bé bị bỏ rơi trên thảo nguyên, Thành Cát Tư Hãn đã dựng nên một đế chế lớn mạnh trong lịch sử. Nhưng gần 800 năm sau khi ông qua đời, nơi chôn cất của ông vẫn là bí ẩn lớn trên thế giới.\n\nTuổi thơ nhiều biến cố\n\nThành Cát Tư Hãn tên thật là Thiết Mộc Chân (Temüjin). Theo tài liệu cổ ghi chép, ông sinh năm 1162 gần hồ Baikal trên vùng đất nay thuộc biên giới giữa Mông Cổ và Siberia (Nga).\n\nTuổi thơ của Thiết Mộc Chân trải qua nhiều biến cố. Sau khi cha ông - một tù trưởng nổi tiếng nhờ tài quân sự - qua đời, gia đình mất đi chỗ dựa quan trọng. Mẹ ông phải một mình xoay xở cùng 7 đứa con giữa thảo nguyên khắc nghiệt.\n\nKể từ đó, Thiết Mộc Chân phải trưởng thành giữa các cuộc tranh chấp, sự bất ổn và nguy cơ bị những nhóm đối địch đe dọa. Những năm tháng ấy thường được nhắc đến như một phần quan trọng trong hành trình hình thành con người ông sau này.\n\nNăm 1178, ông kết hôn với người vợ có tên Bột Nhi Thiếp (Börte). Người vợ sinh cho ông 4 con trai.\n\nKhi vợ bị một bộ lạc đối địch bắt cóc, Thiết Mộc Chân khi đó kịp chạy lên đỉnh Burkhan Khaldun - ngọn núi linh thiêng thuộc dãy Khentii ở miền đông Mông Cổ.\n\nSau khi thoát nạn, ông bắt đầu xây dựng liên minh để đánh bại người Merkit và giải cứu người vợ. Kể từ đó, ông từng bước thống nhất các bộ lạc trong khu vực, tập hợp binh sĩ, gây dựng uy tín.\n\nNăm 1206, các thủ lĩnh bộ lạc tôn ông làm Thành Cát Tư Hãn. Theo cách giải thích của Albert Lin - nhà khoa học kiêm nhà khảo cổ học người Mỹ, danh hiệu này có thể hiểu khái quát là \"Vua của tất cả\".\n\nSau đó, Thành Cát Tư Hãn thống nhất các bộ lạc du mục Mông Cổ và xây dựng đế chế mang tên mình. Đế chế này sau đó mở rộng khắp một vùng rộng lớn của châu Á, từ Trung Á đến nhiều khu vực thuộc Trung Quốc, Ba Tư và Nga.\n\nNhà nhân chủng học Jack Weatherford - tác giả cuốn \"Genghis Khan and the Making of the Modern World\" (tạm dịch: Thành Cát Tư Hãn và sự hình thành thế giới hiện đại) - nhận định, Thành Cát Tư Hãn là người sáng lập quốc gia và là cha của người Mông Cổ.\n\nÔng đã thống nhất các bộ lạc, đặt tên cho quốc gia, quy định một hệ chữ viết và xây dựng hệ thống luật lệ. Sử sách cũng ghi nhận những chính sách đi trước thời đại của ông.\n\nCụ thể, ông cho phép tự do tôn giáo, khuyến khích thương mại và trao quyền miễn trừ ngoại giao cho các sứ thần nước ngoài. Ông cũng ban hành lệnh cấm, bắt cóc phụ nữ.\n\nBách khoa toàn thư Britannica gọi đây là đế chế liền một dải rộng nhất lịch sử. Sau khi Thành Cát Tư Hãn qua đời vào năm 1227, đế chế mà ông gây dựng vẫn tiếp tục mở rộng dưới quyền các hậu duệ.\n\nTrong những thập niên tiếp theo, các chiến dịch của quân Mông cổ đưa quyền lực của họ tiến xa hơn ở châu Á và sang một phần châu Âu. Ở thời kỳ cực thịnh, đế chế Mông Cổ rộng khoảng 24 triệu km2, thậm chí gần bằng diện tích châu Phí (hơn 30,2 triệu km2).\n\nCái chết năm 1227 và đám tang phủ đầy bí ẩn\n\nThành Cát Tư Hãn qua đời trong chiến dịch chống Tây Hạ, một thế lực ở khu vực phía tây bắc Trung Quốc ngày nay. Năm mất của ông được các tài liệu lịch sử ghi nhận là 1227, nhưng những chi tiết về hoàn cảnh cuối đời, nguyên nhân cái chết và nghi thức an táng vẫn còn nhiều bí ẩn.\n\nCác sử gia đời sau đưa ra nhiều giả thuyết về cái chết của ông, từ việc ngã ngựa cho tới trúng tên của kẻ thù.\n\nSau khi qua đời, thi thể Thành Cát Tư Hãn được cho là đã đưa về Mông Cổ để an táng trong bí mật. Các chuyên gia cho rằng việc không để lại thông tin rõ ràng về nơi an táng có thể là chủ ý, nhằm ngăn kẻ thù xâm phạm mộ phần hoặc làm tổn hại đến linh hồn Thành Cát Tư Hãn.\n\nNhà khoa học người Mỹ Albert Lin giải thích, trong quan niệm truyền thống của người Mông Cổ, mộ phần tổ tiên gắn với sức mạnh tinh thần của người đã khuất. Vì vậy, kẻ muốn chiếm đất hoặc triệt tiêu ảnh hưởng tinh thần của một cộng đồng có thể tìm cách phá hủy những ngôi mộ tổ tiên của cộng đồng đó.\n\nTrong khi đó, theo nhà khảo cổ học Jan Bemmann - Giáo sư khảo cổ học tiền sử và lịch sử sơ kỳ tại Đại học Bonn, Đức, tầng lớp tinh hoa Mông Cổ thế kỷ 13 có thể được chôn trong quan tài gỗ tại những khu vực hẻo lánh trên các dãy núi.\n\nNhững vị thủ lĩnh như Thành Cát Tư Hãn có thể được an táng cùng các vật dụng gắn với thân phận chiến binh, chẳng hạn bao đựng tên hoặc đồ dùng cưỡi ngựa.\n\nMột khả năng khác là ông không được chôn cất theo cách thông thường. Theo nhà khoa học Albert Lin, một số cộng đồng Mông Cổ từng thực hành hình thức thiên táng, đưa thi thể lên đỉnh núi rồi để lại đó.\n\nDù hình thức an táng thực sự là gì, nhiều người vẫn tin rằng nơi an nghỉ cuối cùng của Thành Cát Tư Hãn nằm ở Burkhan Khaldun. Ngọn núi này được xem là địa điểm linh thiêng, gắn với sự che chở, chuyển hóa và đời sống tinh thần của người Mông Cổ. Khu vực núi cùng cảnh quan linh thiêng xung quanh đã được UNESCO công nhận là Di sản thế giới.\n\nTuy nhiên, các nhà khảo cổ không thể tùy ý khảo sát toàn bộ ngọn núi để tìm mộ. Burkhan Khaldun là địa điểm linh thiêng đối với Hoàng tộc Mông Cổ và nằm trong khu vực được bảo vệ nghiêm ngặt. Việc tiếp cận cần có sự cho phép đặc biệt của nhà nước Mông Cổ.\n\nCông nghệ hiện đại và cuộc truy tìm ngôi mộ\n\nNăm 2008, nhà khoa học Albert Lin đề xuất sử dụng những công nghệ tiên tiến để khảo sát núi Burkhan Khaldun mà không làm xáo trộn địa hình. Các phương tiện được đề cập gồm ảnh vệ tinh, thiết bị bay không người lái, radar xuyên đất, phương pháp đo từ trường và cảm ứng điện từ.\n\nDự án mang tên \"Valley of the Khans\" (Thung lũng các Khan) do Hiệp hội Địa lý Quốc gia Mỹ tài trợ, đã giúp nhóm của nhà thám hiểm Lin phát hiện hàng nghìn hiện vật, trong đó có ngói lợp, gỗ cháy và răng ngựa. Những dấu tích này được xác định có niên đại vào thời điểm Thành Cát Tư Hãn qua đời hoặc không lâu sau đó.\n\nNhóm nghiên cứu cũng phát hiện một gò đất và một công trình lớn trên đỉnh núi, được mô tả là một đền thờ quy mô lớn. Ông cho rằng người Mông Cổ vốn là dân du mục, thường không xây dựng những công trình kiên cố để sinh hoạt hằng ngày. Do đó, sự hiện diện của một công trình cố định trên núi có thể cho thấy nơi này từng phục vụ các nghi lễ.\n\nCuộc tìm kiếm bằng ảnh vệ tinh và công nghệ hiện đại vì thế mới chỉ giúp khoanh vùng các địa điểm tiềm năng, chứ chưa tìm ra bằng chứng xác nhận vị trí lăng mộ Thành Cát Tư Hãn.\n\nTuy nhiên, trở ngại hiện nay không hẳn nằm ở công nghệ, mà ở quyết định của người Mông Cổ đương đại về việc có muốn tìm hiểu những gì đang nằm dưới công trình hay không.\n\nNhà khảo cổ Joshua Wright (Đại học Aberdeen, Anh) nhận định, người Mông Cổ \"sẽ không chấp nhận\" việc ngôi mộ bị tìm thấy vì lo ngại vấn đề phá hoại, trộm cắp. Ông cũng cho rằng, Thành Cát Tư Hãn mong thi hài mình được yên, nên việc tìm mộ là hành vi thiếu tôn trọng.\n\nTrong khi lăng mộ thật vẫn nằm đâu đó dưới thảo nguyên, người đời sau tưởng nhớ ông ở một nơi khác. Đó là lăng Thành Cát Tư Hãn tại thành phố Ngạc Nhĩ Đa Tư (Ordos) thuộc khu tự trị Nội Mông (Trung Quốc) dù đây không phải nơi chôn hài cốt.\n\nNăm 2006, lễ tế Thành Cát Tư Hãn được đưa vào danh mục di sản văn hóa phi vật thể cấp quốc gia đợt đầu tiên của Trung Quốc.\n\nGần 8 thế kỷ trôi qua, vị thủ lĩnh từng khiến cả lục địa Á - Âu rung chuyển vẫn giữ được điều ông mong muốn. Đó là một giấc ngủ ngàn thu không bị ai quấy rầy.","author":"Huy Hoàng","category":"Đời sống","publishedAt":"2026-10-21 11:58","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/thanh-cat-tu-han-cuoc-doi-lay-lung-va-ngoi-mo-bi-an-800-nam-chua-tim-thay-20261021115825703.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/scPrzRoed7cmlQsdmDTljORn21I=/zoom/1200_630/2026/10/21/7-cropped-cropped-1792558572975.jpg","crawledAt":"2026-10-21T13:42:44.365Z"},{"id":"dtri-20261021115815225","title":"Tìm người biết thông tin liệt sĩ hy sinh trong Tết Mậu Thân 1968 ở Hội An","slug":"tim-nguoi-biet-thong-tin-liet-si-hy-sinh-trong-tet-mau-than-1968-o-hoi-an","excerpt":"Ban Chỉ huy Quân sự phường Hội An thông báo tìm kiếm nhân chứng có thông tin về trận chiến trong Tết Mậu Thân 1968, tại khu vực Công viên Hội An ngày nay, nhằm xác minh thông tin liệt sĩ hy sinh.","content":"(Dân trí) - Ban Chỉ huy Quân sự phường Hội An thông báo tìm kiếm nhân chứng có thông tin về trận chiến trong Tết Mậu Thân 1968, tại khu vực Công viên Hội An ngày nay, nhằm xác minh thông tin liệt sĩ hy sinh.\n\nNgày 21/10, ông Nguyễn Ngọc Toàn, Phó Chỉ huy Trưởng Ban Chỉ huy Quân sự phường Hội An (Đà Nẵng), cho biết đơn vị đang tìm kiếm nhân chứng, các cựu chiến binh đã từng chiến đấu, người dân biết về sự kiện Tết Mậu Thân 1968 tại thị xã Hội An, thuộc đặc khu Quảng Đà cũ.\n\nTheo tài liệu của Ban Chỉ huy Quân sự phường Hội An, trong Tết Mậu Thân 1968, Tiểu đoàn 2, Tiểu đoàn 3 Mặt trận 4 Quảng Đà tấn công vào Khu Công binh và Trại Chi Lăng (thị xã Hội An cũ).\n\nKết quả, bộ đội ta tiêu diệt trên 600 quân địch, phá hủy nhiều xe, súng…, chiếm được mục tiêu, sau đó địch phản kích, ta rút về căn cứ. Tuy nhiên, lực lượng vũ trang và quần chúng cũng có thương vong.\n\nTheo Ban Chỉ huy Quân sự phường Hội An, cuộc tiến công và nổi dậy tại Hội An có giá trị, ý nghĩa lịch sử sâu sắc, tạo nên bước ngoặt lịch sử của cuộc kháng chiến chống Mỹ cứu nước.\n\nĐể tìm kiếm thông tin bộ đội hy sinh trong trận chiến Mậu Thân 1968, Ban Chỉ huy Quân sự phường Hội An đã gặp và trao đổi thông tin với một số nhân chứng từng chiến đấu tại Hội An.\n\nMột trong những nhân chứng từng chiến đấu tại Hội An là ông Đinh Văn Lời (SN 1950). Năm 1968, ông là Đội trưởng Biệt động Hội An.\n\nTheo thông tin ông Lời cung cấp cho Ban Chỉ huy Quân sự phường Hội An, trong trận chiến Mậu Thân 1968 tại Hội An, bộ đội hy sinh ở Khu Công binh và Trại Chi Lăng. Có thể địch chôn tập thể ở khu vực này nhưng không biết vị trí chính xác.\n\nKhu Công binh nay là Công viên Hội An, bao quanh bởi các tuyến đường Trần Hưng Đạo - Phạm Hồng Thái - Lý Thường Kiệt. Trại Chi Lăng (cứ điểm Chi Lăng) hiện nay có thể là đường Lý Nam Đế.\n\nBan Chỉ huy Quân sự phường Hội An đang phối hợp với phường Hội An Đông và Hội An Tây xác minh bộ đội hy sinh trong Tết Mậu Thân 1968, ở khu Công binh và cứ điểm Chi Lăng để phục vụ Chiến dịch 500 ngày đêm tìm kiếm, quy tập và xác định danh tính hài cốt liệt sĩ.\n\nNgoài ra, Ban Chỉ huy Quân sự phường Hội An cũng kêu gọi nhân dân, cựu chiến binh, nhân chứng lịch sử… có thông tin về vị trí chôn tập thể cung cấp về đơn vị tại địa chỉ 82 Trần Hưng Đạo, phường Hội An, Đà Nẵng.","author":"Công Bính","category":"Nội vụ","publishedAt":"2026-10-21 11:58","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/tim-nguoi-biet-thong-tin-liet-si-hy-sinh-trong-tet-mau-than-1968-o-hoi-an-20261021115815225.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/WgmSS3e92ZrxeaLj9zQZNSIkgpg=/zoom/1200_630/2026/10/21/cong-vien-hoi-an-edited-cropped-1792558501738.jpg","crawledAt":"2026-10-21T13:43:35.591Z"},{"id":"dtri-20261021112941302","title":"Phú Quốc ghi nhận hơn 1.000 ca sốt xuất huyết, nhu cầu tiêm vaccine tăng","slug":"phu-quoc-ghi-nhan-hon-1000-ca-sot-xuat-huyet-nhu-cau-tiem-vaccine-tang","excerpt":"Sốt xuất huyết tại Phú Quốc tăng mạnh, với hơn 1.000 ca mắc, riêng An Thới chiếm phần lớn. Nhu cầu tư vấn, tiêm vaccine phòng bệnh cũng tăng gần gấp đôi.","content":"(Dân trí) - Sốt xuất huyết tại Phú Quốc tăng mạnh, với hơn 1.000 ca mắc, riêng An Thới chiếm phần lớn. Nhu cầu tư vấn, tiêm vaccine phòng bệnh cũng tăng gần gấp đôi.\n\nMới đây, UBND đặc khu Phú Quốc (tỉnh An Giang) ban hành kế hoạch về việc triển khai chiến dịch diệt lăng quăng, bọ gậy và phòng, chống bệnh sốt xuất huyết trước tình hình dịch bệnh này đang diễn biến phức tạp tại 8 khu phố thuộc địa bàn An Thới.\n\nSốt xuất huyết tại Phú Quốc tăng mạnh\n\nTheo số liệu thống kê, tính đến nay, toàn đặc khu ghi nhận hơn 1.000 trường hợp mắc bệnh, tăng 6,9 lần so với cùng kỳ năm 2025. Riêng khu vực An Thới ghi nhận 672 ca, chiếm 65,11% tổng số trường hợp mắc trên địa bàn.\n\nNguyên nhân được xác định do điều kiện thời tiết mưa xen kẽ nắng nóng làm phát sinh nhiều vật chứa nước tự nhiên và nhân tạo.\n\nBên cạnh đó, mật độ dân cư, hoạt động du lịch, dịch vụ và sự biến động dân số tăng đột biến với hơn 10.000 công nhân lao động tại các công trình đã gây khó khăn cho công tác quản lý và tuyên truyền.\n\nTrước xu hướng gia tăng ca mắc sốt xuất huyết và các biện pháp tăng cường phòng, chống dịch tại Phú Quốc, ghi nhận tại Trung tâm Tiêm chủng Long Châu Phú Quốc cho thấy nhu cầu tư vấn, tiêm vaccine phòng bệnh tăng rõ rệt, gần gấp đôi so với tháng trước.\n\nTheo BS.CKI Lê Thị Giao Thi, Hệ thống Nhà thuốc và Tiêm chủng Long Châu, xu hướng này phản ánh ý thức chủ động bảo vệ sức khỏe của người dân trên đảo. Bên cạnh vệ sinh môi trường, diệt lăng quăng theo khuyến cáo của địa phương, nhiều người đã tìm hiểu giải pháp phòng bệnh bằng vaccine.\n\nNhu cầu tiêm tăng ở ba nhóm chính đó là người trưởng thành (đặc biệt là lao động thường xuyên làm việc ngoài trời), trẻ từ 4 tuổi trở lên được phụ huynh đưa đi tiêm và người từng mắc sốt xuất huyết.\n\nĐể đáp ứng nhu cầu, Long Châu chủ động lên kế hoạch vận chuyển, dự trữ vaccine Qdenga tại trung tâm ở Phú Quốc, hạn chế gián đoạn nguồn cung. Quy trình bảo quản dây chuyền lạnh theo tiêu chuẩn GSP, khám sàng lọc tiền sử bệnh và hướng dẫn theo dõi sức khỏe sau tiêm được thực hiện nghiêm ngặt.\n\nChủ động phòng bệnh trước mùa mưa, chú ý dấu hiệu cảnh báo\n\nTheo BS Thi, sốt xuất huyết có thể xuất hiện quanh năm tại Việt Nam, nhưng thường gia tăng vào mùa mưa. Thời tiết nóng ẩm, mưa nhiều tạo điều kiện cho muỗi vằn truyền virus Dengue sinh sản. Nước đọng trong chai lọ, lốp xe cũ, chậu cây và dụng cụ chứa nước không đậy kín là những nơi muỗi có thể đẻ trứng, làm tăng nguy cơ lây truyền bệnh.\n\nNgười dân cần chủ động phòng bệnh quanh năm, không chờ đến khi dịch bùng phát mới hành động. Các biện pháp quan trọng gồm loại bỏ nước đọng, diệt lăng quăng, diệt muỗi, đậy kín dụng cụ chứa nước, ngủ màn kể cả ban ngày và tránh muỗi đốt.\n\nTrẻ em và thanh thiếu niên là những nhóm cần được quan tâm. Ở trẻ nhỏ, dấu hiệu ban đầu đôi khi khó nhận biết; trong khi đó, thanh thiếu niên dù khỏe mạnh vẫn có nguy cơ diễn tiến nặng. Các biến chứng nguy hiểm có thể gồm sốc sốt xuất huyết, xuất huyết nặng và suy tạng.\n\nKhi trẻ hoặc thanh thiếu niên đột ngột sốt cao, đau đầu, đau nhức cơ thể, buồn nôn hoặc phát ban, nhất là tại khu vực có ca bệnh, gia đình nên đưa người bệnh đi khám sớm.\n\nCần đến cơ sở y tế ngay nếu xuất hiện các dấu hiệu như đau bụng nhiều hoặc liên tục, nôn ói nhiều, chảy máu mũi hoặc chân răng, mệt lả, li bì, bứt rứt bất thường, không uống được, tiểu ít hoặc tay chân lạnh. Khó thở, lơ mơ, nôn ra máu hoặc đi ngoài phân đen là những dấu hiệu cần cấp cứu khẩn cấp.\n\n“Đặc biệt, giai đoạn nguy hiểm của sốt xuất huyết thường rơi vào ngày thứ 3 đến ngày thứ 7, kể cả khi người bệnh bắt đầu giảm hoặc hết sốt. Vì vậy, gia đình không nên chủ quan, cần theo dõi sát sức khỏe, tuân thủ lịch tái khám và hướng dẫn của bác sĩ”, BS Thi khuyến cáo.\n\nVaccine bổ trợ cho các biện pháp kiểm soát muỗi\n\nVaccine là giải pháp bổ sung quan trọng trong phòng, chống sốt xuất huyết. Tại Việt Nam, vaccine Qdenga được cấp phép sử dụng cho người từ 4 tuổi trở lên, với lịch tiêm gồm hai mũi cách nhau ba tháng.\n\nVaccine hướng đến tạo đáp ứng miễn dịch với cả bốn tuýp virus Dengue, giúp giảm nguy cơ mắc bệnh có triệu chứng và nhập viện; mức độ bảo vệ có thể khác nhau giữa các tuýp virus.\n\nTheo chuyên gia, người dân nên tham khảo ý kiến bác sĩ để được tư vấn về độ tuổi, lịch tiêm và tình trạng sức khỏe phù hợp, đồng thời cân nhắc tiêm chủng sớm thay vì chờ đến mùa dịch. Việc khám sàng lọc trước tiêm và theo dõi sau tiêm cần được thực hiện theo hướng dẫn chuyên môn.\n\n\"Vaccine không bảo vệ tuyệt đối trước sốt xuất huyết, không ngăn muỗi đốt và không làm giảm số lượng muỗi trong môi trường. Vì vậy, tiêm chủng phải đi đôi với kiểm soát muỗi, diệt lăng quăng và loại bỏ nơi sinh sản của muỗi.\n\n“Chủ động tiêm chủng kết hợp duy trì các biện pháp phòng muỗi là cách tiếp cận toàn diện nhằm giảm nguy cơ mắc bệnh và hạn chế biến chứng do sốt xuất huyết”, BS Thi nhấn mạnh.","author":"Thảo Phương","category":"Sức khỏe","publishedAt":"2026-10-21 11:29","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/phu-quoc-ghi-nhan-hon-1000-ca-sot-xuat-huyet-nhu-cau-tiem-vaccine-tang-20261021112941302.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/rsJ_R_2BczWChWGO82DiDQ18SZo=/zoom/1200_630/2026/10/21/sot-xuat-huyet-1-cropped-1792556867021.jpg","crawledAt":"2026-10-21T13:42:38.966Z"},{"id":"dtri-20261021112848515","title":"Sẽ có tiêu chí chấm điểm mô hình xây dựng người Hà Nội thanh lịch, văn minh","slug":"se-co-tieu-chi-cham-diem-mo-hinh-xay-dung-nguoi-ha-noi-thanh-lich-van-minh","excerpt":"Hà Nội đặt ra yêu cầu đưa các quy tắc ứng xử, xây dựng người Hà Nội thanh lịch, văn minh vào thực tiễn bằng 10 mô hình cụ thể và có tiêu chí đánh giá rõ ràng.","content":"(Dân trí) - Hà Nội đặt ra yêu cầu đưa các quy tắc ứng xử, xây dựng người Hà Nội thanh lịch, văn minh vào thực tiễn bằng 10 mô hình cụ thể và có tiêu chí đánh giá rõ ràng.\n\nSáng 21/10, Sở Văn hóa, Thể thao và Du lịch Hà Nội tổ chức Hội nghị phát động hưởng ứng thực hiện Quy tắc ứng xử, xây dựng người Hà Nội thanh lịch, văn minh và cuộc thi cuộc thi trực tuyến “Văn hoá từ mỗi hành động”.\n\nPhát biểu tại buổi lễ, ông Phạm Tuấn Long, Giám đốc Sở Văn hóa, Thể thao và Du lịch Hà Nội nhấn mạnh, Thăng Long - Hà Nội hơn nghìn năm văn hiến được bồi đắp bởi cốt cách thanh lịch, nghĩa tình và tinh thần trách nhiệm.\n\nNhững giá trị ấy được trao truyền sống động khi hiện diện trong lời nói, hành vi và cách mỗi người đối xử với cộng đồng. Sau gần 10 năm Hà Nội triển khai Quy tắc ứng xử, nhiều chuyển biến tích cực đã được ghi nhận.\n\nÔng Phạm Tuấn Long cho hay, thiện Nghị quyết số 80-NQ/TW và Nghị quyết số 02-NQ/TW của Bộ Chính trị, xây dựng người Hà Nội thanh lịch, văn minh cần gắn với việc phát huy giá trị “Văn hiến - Bản sắc - Sáng tạo” và nâng cao chất lượng cuộc sống, hạnh phúc của nhân dân.\n\nKết quả phải được cảm nhận từ một công sở tận tâm hơn, một gia đình yêu thương hơn, một trường học thân thiện hơn, một khu dân cư nghĩa tình hơn và một không gian mạng có trách nhiệm hơn.\n\nNăm nay, Thành phố tập trung vào 10 mô hình gắn với đời sống hằng ngày:\n\n1. Tuyến phố, khu dân cư văn minh sáng - xanh - sạch - đẹp;\n\n2. Công sở văn hóa - kỷ cương - trách nhiệm - tận tình - thân thiện;\n\n3. Trường học thân thiện - nói lời hay, làm việc tốt - cảnh quan đẹp;\n\n4. Thiết chế văn hóa - thể thao thân thiện - kết nối văn hóa cộng đồng;\n\n5. Gia đình văn hóa - Dòng họ văn minh - Khu dân cư nghĩa tình;\n\n6. Di tích, lễ hội văn minh - an toàn - hiện đại;\n\n7. Thư viện mở - không gian đọc thanh lịch;\n\n8. Người Hà Nội ứng xử đẹp trên không gian mạng;\n\n9. Chợ văn minh - tiểu thương thân thiện;\n\n10. Công dân xanh - hội nhập - thanh lịch, văn minh.\n\nTheo lãnh đạo Sở Văn hóa, Thể thao và Du lịch Hà Nội, 10 mô hình đồng thời là 10 không gian để thực hành nếp sống văn hóa. Mỗi địa phương cần chọn việc thiết thực, tập trung giải quyết vấn đề người dân quan tâm và duy trì đến khi tạo được thay đổi rõ nét.\n\nĐiểm mới quan trọng là mỗi mô hình đều có bộ tiêu chí và thang điểm riêng, xác định rõ việc cần làm, kết quả cần đạt và minh chứng cần có.\n\nBộ tiêu chí, thang điểm và minh chứng là công cụ để đánh giá khách quan, coi trọng kết quả và sự hài lòng của người dân. Đây là cơ sở để địa phương tự đánh giá, thành phố sẽ theo dõi, lựa chọn mô hình tiêu biểu để lan toả, nhân rộng.\n\nĐến nay, 126/126 xã, phường đã ban hành kế hoạch và đăng ký mô hình phù hợp, Văn phòng Hội đồng nhân dân Thành phố và 9 sở, ngành đã đăng ký mô hình thực hiện Quy tắc ứng xử.\n\nNhững con số cho thấy sự hưởng ứng rộng khắp, tạo nền tảng để đưa các chuẩn mực ứng xử vào không gian của đời sống.\n\nĐể đợt phát động đạt kết quả thiết thực, ông Long cho rằng cần tập trung thực hiện tốt các nhiệm vụ: Đề cao trách nhiệm nêu gương của người đứng đầu và đội ngũ cán bộ, công chức, viên chức; tổ chức thực hiện hiệu quả các mô hình đã đăng ký bằng nhiệm vụ cụ thể, phân công rõ người, rõ việc, rõ tiến độ.\n\nBên cạnh đó, cần đổi mới công tác tuyên truyền theo hướng gần gũi, thiết thực, lấy hành động đẹp, câu chuyện thật và cách làm hiệu quả làm trung tâm.\n\nCác xã phường, cơ quan… cần khuyến khích các tầng lớp nhân dân tham gia cuộc thi trực tuyến “Văn hóa từ mỗi hành động”, bằng những video ngắn, câu chuyện văn hóa, hành vi ứng xử đẹp và sáng kiến thiết thực.\n\nGiám đốc Sở Văn hóa, Thể thao và Du lịch Hà Nội nhấn mạnh, cần thực hiện nghiêm việc tự đánh giá, chấm điểm theo bộ tiêu chí; bảo đảm số liệu, hồ sơ minh chứng và kết quả kiểm tra thực tế thống nhất, trung thực.\n\n\"Mỗi cơ quan làm tốt hơn trách nhiệm của mình, mỗi gia đình vun đắp nếp sống đẹp hơn, mỗi người dân ứng xử có trách nhiệm hơn - đó chính là những nền tảng thiết thực để xây dựng Hà Nội văn hiến, văn minh, hiện đại”, ông Phạm Tuấn Long nhấn mạnh.","author":"Hồng Anh","category":"Đời sống","publishedAt":"2026-10-21 11:28","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/se-co-tieu-chi-cham-diem-mo-hinh-xay-dung-nguoi-ha-noi-thanh-lich-van-minh-20261021112848515.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/CsCAWSdEWcQKVBCYrgbsd3L8zTA=/zoom/1200_630/2026/10/21/anh-2-cropped-1792564259140.jpg","crawledAt":"2026-10-21T13:42:43.290Z"},{"id":"dtri-20261021112245313","title":"Bị tuyên tử hình, kẻ sát hại 3 mẹ con ở Đồng Nai xin giảm nhẹ hình phạt","slug":"bi-tuyen-tu-hinh-ke-sat-hai-3-me-con-o-dong-nai-xin-giam-nhe-hinh-phat","excerpt":"Sau khi sát hại 3 mẹ con trong gia đình ở Đồng Nai và gây thương tật 76% cho người chồng, Nguyễn Đức Anh bị tuyên án tử hình. Bị cáo vừa kháng cáo xin giảm nhẹ hình phạt.","content":"(Dân trí) - Sau khi sát hại 3 mẹ con trong gia đình ở Đồng Nai và gây thương tật 76% cho người chồng, Nguyễn Đức Anh bị tuyên án tử hình. Bị cáo vừa kháng cáo xin giảm nhẹ hình phạt.\n\nNgày 21/10, bị cáo Nguyễn Đức Anh (21 tuổi, ngụ phường Hố Nai) đã kháng cáo xin giảm nhẹ hình phạt tử hình.\n\nTrước đó, xử sơ thẩm, TAND TP Đồng Nai tuyên phạt bị cáo Nguyễn Đức Anh mức án tử hình về các tội Giết người và Sử dụng trái phép vũ khí quân dụng. Về dân sự, HĐXX tuyên buộc bị cáo bồi thường cho bị hại hơn 1,1 tỷ đồng.\n\nNói lời sau cùng trước khi HĐXX vào nghị án, Nguyễn Đức Anh tỏ ra bình thản. Khi được HĐXX hỏi có điều gì muốn trình bày, bị cáo chỉ trả lời ngắn gọn: “Không có gì để nói”.\n\nTheo cáo trạng, do bị Đ.T.P.A. (17 tuổi) chia tay, trong cuộc nhậu vào chiều tối 2/9, Đức Anh nói với nhóm bạn về ý định giết người yêu để trả thù.\n\nSau cuộc nhậu, Đức Anh nhờ một người bạn chở đi và nói dối rằng mình đi đòi nợ. Trên đường đi, bị cáo quay về phòng trọ lấy hung khí. Sau đó, Đức Anh nhờ bạn chở đi quanh nhà P.A. 3 lần để tìm cách đột nhập. Thấy vậy, người bạn can ngăn và chở Đức Anh về nhà.\n\nRạng sáng 3/9, Đức Anh mang theo hung khí, một mình chạy xe máy quay lại nhà P.A và tìm cách trèo vào nhà. Khi bị cha của người yêu cũ phát hiện và dọa báo công an, Đức Anh quay xuống.\n\nLúc này, Đức Anh phát hiện có thể trèo từ nhà hàng xóm sang nhà P.A. nên đột nhập vào nhà ông N.V.Q. (40 tuổi).\n\nSau khi mở cửa tầng 2 rồi đi xuống tầng trệt, Đức Anh bị ông Q. phát hiện. Bị cáo rút hung khí truy sát ông Q., sau đó lần lượt tấn công vợ và 2 con của ông.\n\nVụ án khiến vợ và 2 con ông Q. (11 tuổi và 1 tuổi) tử vong tại chỗ. Riêng ông Q. bị thương nặng, với tỷ lệ tổn thương cơ thể 76%.","author":"Xuân Duy","category":"Pháp luật","publishedAt":"2026-10-21 11:22","source":"dantri.com.vn","url":"https://dantri.com.vn/phap-luat/bi-tuyen-tu-hinh-ke-sat-hai-3-me-con-o-dong-nai-xin-giam-nhe-hinh-phat-20261021112245313.htm","categories":["Pháp luật"],"categoryIds":["phap-luat"],"thumbnail":"https://cdnphoto.dantri.com.vn/2_caNUldW-5O5VJeotIz-RIC4eY=/zoom/1200_630/2026/10/21/179125224385610694929991672664331069492999167266433e252685f46ade8ef1e4e9536544cfe71-edited-cropped-cropped-cropped-1792556525310.jpg","crawledAt":"2026-10-21T13:42:34.645Z"},{"id":"dtri-20261021111436423","title":"\"Thiên thần nội y\" 45 tuổi có 3 con, vẫn là biểu tượng gợi cảm","slug":"thien-than-noi-y-45-tuoi-co-3-con-van-la-bieu-tuong-goi-cam","excerpt":"Adriana Lima từng là gương mặt tiêu biểu của kỷ nguyên siêu mẫu. Gần 30 năm sau khi bước lên sàn diễn, chân dài Brazil vẫn duy trì sức hút, trở thành hình mẫu truyền cảm hứng cho thế hệ người mẫu trẻ.","content":"Tại Victoria’s Secret Fashion Show 2026, Adriana Lima gây chú ý khi trở lại sàn diễn bên cạnh dàn người mẫu trẻ. Ở tuổi 45, chân dài Brazil vẫn thể hiện phong thái tự tin, thần thái cuốn hút và khả năng làm chủ sân khấu sau nhiều thập kỷ hoạt động trong ngành thời trang.\n\nKhông chỉ gây ấn tượng bởi ngoại hình, cô còn mang đến sức hút của một siêu mẫu dày dạn kinh nghiệm, từng gắn bó với Victoria’s Secret qua nhiều giai đoạn thăng trầm.\n\nAdriana Lima sinh năm 1981 tại Salvador, bang Bahia (Brazil). Trước khi nổi tiếng, cô từng mơ trở thành bác sĩ nhi khoa chứ không có kế hoạch theo đuổi nghề người mẫu. Cơ duyên với thời trang đến khá tình cờ.\n\nỞ tuổi 15, Lima tham gia cuộc thi tìm kiếm người mẫu Ford Supermodel of Brazil vì lời rủ của một người bạn, nhưng cuối cùng giành chiến thắng. Năm 1996, cô tiếp tục đạt vị trí á quân tại cuộc thi Ford Models Supermodel of the World, mở ra cơ hội bước vào thị trường quốc tế.\n\nSau đó, Lima chuyển đến New York (Mỹ), ký hợp đồng với công ty quản lý người mẫu Elite Model Management và bắt đầu xây dựng sự nghiệp tại kinh đô thời trang. Năm 1997, cô ra mắt sàn diễn tại Tuần lễ thời trang New York trong show của nhà thiết kế Anna Sui. Từ một cô gái tuổi teen đến từ Brazil, Lima dần xuất hiện trong các chiến dịch quảng cáo, tạp chí thời trang và những show diễn của các nhà mốt lớn.\n\nĐiểm nổi bật ở Lima là sự kết hợp giữa đôi mắt xanh nổi bật, mái tóc sẫm màu, gương mặt góc cạnh và thần thái mạnh mẽ. Vẻ đẹp của cô vừa phù hợp với những bộ ảnh thời trang giàu tính nghệ thuật, vừa tạo được sức hút trong các chiến dịch quảng cáo đại chúng.\n\nNăm 1998, cô xuất hiện trên bìa Marie Claire Brazil, sau đó tiếp tục ghi dấu tại các ấn phẩm Vogue và hợp tác với nhiều nhiếp ảnh gia nổi tiếng.\n\nKhông chỉ gắn bó với thời trang cao cấp, Lima còn trở thành gương mặt quảng cáo quen thuộc của Maybelline trong giai đoạn 2003-2009. Cô từng làm việc với nhiều thương hiệu lớn như Versace, Prada, Dior, Louis Vuitton, Givenchy và Balmain.\n\nSự hiện diện ở cả sàn diễn, tạp chí lẫn quảng cáo giúp nữ người mẫu xây dựng danh tiếng vượt khỏi phạm vi một thị trường hay một thương hiệu.\n\nBước ngoặt lớn nhất trong sự nghiệp của Adriana Lima đến từ Victoria’s Secret. Cô lần đầu trình diễn tại Victoria’s Secret Fashion Show năm 1999, sau đó trở thành một trong những “thiên thần” tiêu biểu của thương hiệu từ năm 2000.\n\nTrong gần 20 năm gắn bó, Lima góp phần định hình hình ảnh người mẫu nội y của thương hiệu với phong thái tự tin, năng lượng mạnh mẽ và khả năng làm chủ sân khấu.\n\nMột trong những dấu mốc đáng nhớ nhất của cô là lần trình diễn Fantasy Bra (áo lót đặc biệt) năm 2008. Đây là thiết kế nội y đính đá quý được chế tác riêng, có giá trị được công bố ở mức hơn 5 triệu USD.\n\nNhững màn xuất hiện của Lima với đôi cánh lớn và các thiết kế cầu kỳ trở thành hình ảnh gắn liền với thời kỳ hoàng kim của Victoria’s Secret Fashion Show.\n\nNăm 2014, Forbes xếp cô thứ 2 trong danh sách những người mẫu có thu nhập cao nhất thế giới, với thu nhập ước tính 8 triệu USD trong năm.\n\nNăm 2018, Lima chia tay Victoria’s Secret trong sự xúc động sau gần 20 năm đồng hành. Thời điểm đó, cô được xem là một trong những gương mặt có mối liên hệ lâu dài nhất với thương hiệu. Việc rời sàn diễn nội y mở ra một giai đoạn mới để cô cân bằng công việc, gia đình và những lựa chọn cá nhân.\n\nNếu Victoria’s Secret đưa Adriana Lima đến gần công chúng đại chúng, các sàn diễn thời trang cao cấp lại khẳng định khả năng hoạt động đa dạng của cô. Mỹ nhân Brazil cũng tham gia các hoạt động ngoài lĩnh vực người mẫu, trong đó có vai trò phóng viên về văn hóa và ẩm thực cho NBC tại Olympic Rio 2016.\n\nTờ Vogue España từng nhận xét rằng sự quan tâm của thế hệ trẻ dành cho Lima cho thấy sức hút của cô vượt qua giới hạn thế hệ. Nếu trước đây, các show diễn nội y thường nhấn mạnh vẻ đẹp hình thể và tính trình diễn, những cuộc thảo luận hiện nay ngày càng chú trọng sự đa dạng, tính đại diện và cách phụ nữ được nhìn nhận.\n\nTrong cuộc phỏng vấn với Vogue España năm 2024, Lima cũng bày tỏ sự ủng hộ đối với xu hướng tôn vinh nhiều kiểu phụ nữ khác nhau.\n\nVới hành trình kéo dài gần 30 năm, Lima là ví dụ cho thấy một người mẫu có thể duy trì sự nghiệp không chỉ nhờ diện mạo mà còn nhờ khả năng thích nghi với những thay đổi của ngành công nghiệp.\n\nỞ tuổi 45, Adriana Lima hoạt động trong ngành thời trang, đồng thời dành nhiều thời gian cho gia đình. Cô có 2 con gái Valentina (SN 2009) và Sienna (SN 2012) với chồng cũ là cầu thủ bóng rổ Marko Jarić. Hai người kết hôn năm 2009, thông báo ly thân năm 2014 và hoàn tất thủ tục ly hôn năm 2016.\n\nNăm 2022, Lima sinh con trai Cyan với nhà sản xuất phim Andre Lemmers, người cô bắt đầu hẹn hò từ năm 2021. Thời điểm này người đẹp đã 41 tuổi.\n\nLàm mẹ trở thành một phần quan trọng trong cuộc sống của Lima. Trong cuộc phỏng vấn với Vogue España năm 2024, cô chia sẻ rằng việc trở lại vóc dáng và nhịp sống sau sinh cần thời gian, đồng thời nhấn mạnh mỗi giai đoạn cuộc đời đều có những ưu tiên riêng.\n\nNữ người mẫu cũng từng phản đối việc công chúng quá chú trọng những thay đổi ngoại hình của cô sau khi sinh con, cho rằng lúc đó cô có những điều quan trọng hơn cần quan tâm.\n\nTháng 10/2024, Lima trở lại sàn diễn Victoria’s Secret Fashion Show sau 6 năm vắng bóng. Màn tái xuất gây chú ý không chỉ bởi sự trở lại của một gương mặt biểu tượng, mà còn bởi việc cô tiếp tục trình diễn sau khi sinh con thứ 3.\n\nNăm 2025, thương hiệu tiếp tục chào đón cô trở lại show diễn và trong năm 2026, cô tiếp tục sải bước trên sàn diễn nội y danh tiếng.\n\nTrả lời People sau show diễn, cô cho biết các con là những người cổ vũ lớn nhất, thậm chí cùng cô đến phòng tập và theo dõi chế độ ăn uống trong quá trình chuẩn bị. Nữ người mẫu cũng tiết lộ 2 con gái đang quan tâm đến nghề người mẫu và cô sẵn sàng ủng hộ lựa chọn của các con.\n\nNhững lần trở lại liên tiếp cho thấy Lima vẫn có chỗ đứng trong lịch trình thời trang quốc tế, thay vì chỉ được nhắc đến như một biểu tượng của quá khứ.","author":"Mi Vân","category":"Giải trí","publishedAt":"2026-10-21 11:14","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/thien-than-noi-y-45-tuoi-co-3-con-van-la-bieu-tuong-goi-cam-20261021111436423.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/rVWIcHa93i86yeLN9yStF-vQPzg=/zoom/1200_630/2026/10/21/adriana-lima-getty-35-cropped-1792554347373.jpg","crawledAt":"2026-10-21T13:43:13.917Z"},{"id":"dtri-20261021111057968","title":"Volvo, BMW, Microsoft, Meta lùng mua \"thép xanh\", cuộc đua xuất hiện","slug":"volvo-bmw-microsoft-meta-lung-mua-thep-xanh-cuoc-dua-xuat-hien","excerpt":"Ngành thép xả tới 9% khí thải toàn cầu. Giữa sức ép thuế carbon CBAM, liệu doanh nghiệp có làm ra được \"thép xanh\" thực thụ khi chi phí và công nghệ vẫn là bài toán nan giải?","content":"(Dân trí) - Ngành thép xả tới 9% khí thải toàn cầu. Giữa sức ép thuế carbon CBAM, liệu doanh nghiệp có làm ra được \"thép xanh\" thực thụ khi chi phí và công nghệ vẫn là bài toán nan giải?\n\nMột chiếc ô tô điện bóng bẩy xuất xưởng hay một trung tâm dữ liệu quy mô lớn mọc lên đều cần đến hàng nghìn tấn thép. Lâu nay, phần lớn người tiêu dùng chỉ quan tâm đến độ bền, độ dày hay giá thành của từng thanh sắt, cuộn thép. Ít ai để ý rằng, để làm ra mỗi tấn thép thô bằng lò cao truyền thống, nhà máy phải thải vào bầu khí quyển khoảng 1,8-2,2 tấn khí CO2.\n\nThế nhưng cuộc chơi vật liệu xây dựng và chế tạo đang đổi chiều nhanh chóng. Các tập đoàn sản xuất xe hơi như Volvo, BMW, Mercedes hay những công ty công nghệ như Microsoft, Meta đang chủ động lùng mua \"thép xanh\", thậm chí chấp nhận trả thêm hàng triệu đồng cho mỗi tấn vật liệu phát thải thấp.\n\nĐiều này đặt ra câu hỏi lớn cho toàn ngành sản xuất, đó là thép xanh rốt cuộc được luyện ra thế nào, và liệu đây có phải là lời giải thực tế hay chỉ là tấm nhãn dán đắt đỏ?\n\nCông nghệ luyện thép sạch vận hành ra sao?\n\nTheo tổ chức nghiên cứu và dữ liệu Sylvera, sản xuất thép hiện chiếm khoảng 7-9% tổng lượng phát thải CO2 toàn cầu. Khác với ngành xi măng có thể cải tạo từng phần dây chuyền, ngành luyện kim muốn giảm triệt để phát thải thường phải đập bỏ và thay thế toàn bộ quy trình cốt lõi.\n\nHiện nay, khái niệm thép xanh không phải là một nhãn phân loại tuyệt đối chỉ có hai trạng thái \"xanh\" hoặc \"không xanh\". Sylvera cho rằng nên nhìn nhận đây là một phổ các mức phát thải giảm dần. Ở phương pháp truyền thống, các lò cao kết hợp lò thổi oxy cơ bản (chiếm 70% sản lượng toàn cầu) dùng than cốc để tách oxy khỏi quặng sắt, khiến phản ứng hóa học tự nhiên giải phóng một lượng CO2 khổng lồ rất khó loại bỏ.\n\nĐể xanh hóa, hướng đi đầu tiên là nấu chảy thép phế liệu bằng lò điện hồ quang. Nếu dùng hoàn toàn điện tái tạo, lượng phát thải có thể giảm ngoạn mục xuống còn 0,2-0,5 tấn CO2 trên mỗi tấn thép. Tuy nhiên, nguồn phế liệu trên thế giới có giới hạn nhất định, trong khi nhiều chi tiết công nghiệp phức tạp vẫn bắt buộc phải luyện từ quặng sắt mới.\n\nVì vậy, con đường tạo ra thép nguyên sinh không phát thải nằm ở công nghệ hoàn nguyên trực tiếp kết hợp lò điện hồ quang (DRI-EAF) sử dụng khí hydro. Khi hydro thay thế than cốc, phản ứng tách quặng sắt chỉ tạo ra hơi nước thay vì khí nhà kính. Dù có thể ép phát thải xuống mức kỷ lục 0,3-0,5 tấn CO2/tấn thép, phương pháp này đòi hỏi nguồn vốn đầu tư khổng lồ vào nhà máy mới, kèm theo nguồn điện sạch và hydro dồi dào - những điều kiện mà không phải quốc gia nào cũng sẵn có.\n\nChấp nhận trả giá cao hay chờ nộp phạt thuế carbon?\n\nDù giá thành sản xuất còn đắt đỏ, thị trường thép phát thải thấp đang chứng kiến làn sóng đặt hàng chủ động từ các nhà tiêu thụ lớn. Nhiều hãng xe ký trước các thỏa thuận bao tiêu sản phẩm dài hạn để phục vụ mục tiêu giảm phát thải gián tiếp trong toàn bộ chuỗi cung ứng.\n\nTheo thông tin từ hội nghị chuyên ngành do Dow Jones Energy tổ chức tại Düsseldorf (Đức) được Eurometal ghi nhận, người mua tại thị trường châu Âu hiện sẵn sàng trả mức giá chênh lệch 150- 160 euro (khoảng 4-4,3 triệu đồng) cho mỗi tấn thép xanh trong các đợt giao dịch thử nghiệm. Đối với các đơn hàng giao ngay khối lượng lớn hơn, mức chênh lệch giá vẫn duy trì ở khoảng 100 euro/tấn.\n\nĐộng lực thúc đẩy mức chi trả này không chỉ đến từ trách nhiệm bảo vệ môi trường, mà đến từ chính túi tiền của các nhà nhập khẩu. Cơ chế điều chỉnh biên giới carbon (CBAM) của Liên minh châu Âu chính thức bước vào giai đoạn thực thi, buộc hàng nhập khẩu phải chịu chi phí tương ứng với lượng khí thải hàm chứa trong từng sản phẩm. Cường độ phát thải càng cao, tiền nộp mua chứng chỉ carbon càng lớn.\n\nNhận định về diễn biến thị trường, bà Shona Crawford-Smith, phụ trách nhóm hàng hóa phân biệt theo mức phát thải carbon tại Sylvera cho biết, một thị trường vận hành hiệu quả cần phản ánh lợi thế về giá tương ứng với mức độ sạch của sản phẩm, bởi mỗi bước giảm phát thải đều cần mang lại lợi ích tài chính tương xứng cho nhà sản xuất.\n\nTuy nhiên, sự phức tạp trong chuỗi thủ tục hành chính, quy định xác minh nguồn gốc xuất xứ và kiểm định nơi đúc phôi thép đang tạo nên không ít áp lực tuân thủ cho các doanh nghiệp.\n\nBài toán cạnh tranh của các nhà sản xuất\n\nTại Việt Nam, sức ép xanh hóa cũng đang hiện hữu rõ nét trước làn sóng bảo hộ thương mại và các hàng rào tiêu chuẩn xanh quốc tế. Việc chuyển đổi từ phương thức đốt than truyền thống sang công nghệ sạch không còn là bài toán xa vời mà gắn liền với năng lực tồn tại của toàn ngành công nghiệp nặng.\n\nTheo Bộ Công Thương, ngành thép trong nước đang đứng trước sức ép chuyển đổi chưa từng có từ các tiêu chuẩn carbon toàn cầu. Đánh giá về vấn đề này, ông Nghiêm Xuân Đa, Chủ tịch Hiệp hội Thép Việt Nam (VSA) khẳng định chuyển đổi xanh không còn là một xu hướng mang tính lựa chọn mà đã trở thành yêu cầu tất yếu để duy trì năng lực cạnh tranh và mở rộng thị trường xuất khẩu.\n\n\"Thách thức lớn nhất hiện nay là làm sao cân bằng giữa mục tiêu giảm phát thải với yêu cầu duy trì hiệu quả sản xuất kinh doanh và năng lực cạnh tranh của doanh nghiệp thép\", ông Nghiêm Xuân Đa nhấn mạnh. Vị chuyên gia phân tích thêm rằng ngành thép tiêu thụ năng lượng rất lớn, trong khi các công nghệ giảm phát thải tiên tiến đều cần lượng vốn đầu tư khổng lồ và thời gian thu hồi vốn kéo dài.\n\nCũng theo thông tin được Bộ Công Thương chia sẻ, để ngành sản xuất có thể vượt qua rào cản này, giải pháp đột phá phải nằm ở việc xây dựng một hệ sinh thái đồng bộ gồm 3 trụ cột là công nghệ xanh (đầu tư dây chuyền, tối ưu hóa năng lượng), nguyên liệu và năng lượng xanh (tăng dùng phế liệu, tiếp cận điện sạch), cùng hệ thống cơ chế chính sách hoàn chỉnh (tín dụng xanh, vận hành thị trường định giá carbon minh bạch).\n\nCuộc chuyển dịch sang thép xanh đang vẽ lại bản đồ thương mại kim loại toàn cầu. Giữa các quy chuẩn kỹ thuật ngặt nghèo và chi phí đầu tư đắt đỏ, những nhà máy chậm chân trong việc đo lường, kiểm kê và giảm lượng khí thải sẽ dần mất đi lợi thế cạnh tranh trên thị trường xuất khẩu.","author":"Cẩm Hà","category":"Kinh doanh","publishedAt":"2026-10-21 11:10","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/volvo-bmw-microsoft-meta-lung-mua-thep-xanh-cuoc-dua-xuat-hien-20261021111057968.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/9dp3szHSHYx0FjaH5jX0NzVQ9AY=/zoom/1200_630/2026/10/21/shutterstocksteel-cropped-1792554955346.jpg","crawledAt":"2026-10-21T13:42:57.110Z"},{"id":"dtri-20261021110109465","title":"Dân trí 360: Hành trình thiêng liêng xác minh danh tính hơn 8.000 liệt sĩ","slug":"hanh-trinh-thieng-lieng-xac-minh-danh-tinh-hon-8000-liet-si","excerpt":"Dân trí 360 (Dân trí) - Ngày 21/10, 8.453 mẫu sinh phẩm hài cốt liệt sĩ được vận chuyển bằng máy bay quân sự từ Cảng hàng không quốc tế Cần Thơ ra Hà Nội để giám định ADN, phục vụ xác định danh tính các liệt sĩ.","content":"Dân trí 360 (Dân trí) - Ngày 21/10, 8.453 mẫu sinh phẩm hài cốt liệt sĩ được vận chuyển bằng máy bay quân sự từ Cảng hàng không quốc tế Cần Thơ ra Hà Nội để giám định ADN, phục vụ xác định danh tính các liệt sĩ.","author":"Dân trí","category":"Nội vụ","publishedAt":"2026-10-21 11:01","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/hanh-trinh-thieng-lieng-xac-minh-danh-tinh-hon-8000-liet-si-20261021110109465.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/-5PaZnl7cK72L-vwQLbIiies4Is=/zoom/1200_630/2026/10/21/le-tien-dua-8-cropped-1792555193415.jpg","crawledAt":"2026-10-21T13:43:36.653Z"},{"id":"dtri-20261021105144703","title":"Lịch thi đấu của đội tuyển Việt Nam ở Asian Cup 2027 mới nhất","slug":"lich-thi-dau-cua-doi-tuyen-viet-nam-o-asian-cup-2027-moi-nhat","excerpt":"Liên đoàn bóng đá châu Á (AFC) đã công bố lịch thi đấu ở Asian Cup 2027. Trong đó, đội tuyển Việt Nam đều ra sân vào giờ đẹp.","content":"(Dân trí) - Liên đoàn bóng đá châu Á (AFC) đã công bố lịch thi đấu ở Asian Cup 2027. Trong đó, đội tuyển Việt Nam đều ra sân vào giờ đẹp.\n\nBất chấp việc giải Asian Cup 2027 chưa chắc tổ chức như dự kiến vì tình hình an ninh bất ổn ở Saudi Arabia, AFC vẫn công bố lịch thi đấu cụ thể của giải đấu này, bao gồm các trận vòng bảng, vòng 16 đội và tứ kết, bán kết, cũng như trận chung kết.\n\nTheo đó, các trận đấu ở Asian Cup 2027 diễn ra vào các thời điểm 17h30, 20h30, 23h30 và 0h (theo giờ Việt Nam). Trận khai mạc giữa chủ nhà Saudi Arabia và Palestine diễn ra vào lúc 0h ngày 8/1/2027.\n\nỞ vòng bảng, đội tuyển Việt Nam nằm ở bảng E với các đối thủ Hàn Quốc, UAE và Yemen. Đoàn quân HLV Kim Sang Sik đều thi đấu ở khung giờ đẹp với người hâm mộ Việt Nam.\n\nCụ thể, đội tuyển Việt Nam sẽ ra quân gặp UAE vào lúc 20h30 ngày 11/1. Tiếp đó, đoàn quân HLV Kim Sang Sik sẽ đối đầu với Hàn Quốc vào lúc 17h30 ngày 15/1. Cuối cùng, “Những chiến binh sao vàng” chạm trán với Yemen vào lúc 20h30 ngày 20/1.\n\nĐội tuyển Việt Nam đã có kế hoạch chuẩn bị cho Asian Cup 2027. Theo đó, vào tháng 11 tới đây, đội bóng đang được dẫn dắt bởi HLV Kim Sang Sik sẽ thi đấu giao hữu với đội tuyển Đài Loan (ngày 11/11) và đội tuyển Kyrgyzstan (ngày 15/11). Sau đó, vào tháng 12, đội tuyển Việt Nam dự kiến sẽ thi đấu giao hữu với đội tuyển Qatar.\n\nHôm qua (20/10), AFC đã có buổi họp bất thường nhưng chưa công bố quyết định cuối cùng có hoãn Asian Cup 2027 hay không. Theo tờ Sponichi (Nhật Bản), cơ quan quản lý bóng đá châu Á sẽ đưa ra phán quyết trong cuộc họp diễn ra vào tháng 11 tại Bangkok (Thái Lan).","author":"H. Long","category":"Thể thao","publishedAt":"2026-10-21 10:51","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/lich-thi-dau-cua-doi-tuyen-viet-nam-o-asian-cup-2027-moi-nhat-20261021105144703.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/0iZKujzawQO30Qr3_noR0MubP9s=/zoom/1200_630/2026/10/21/lich-thi-dau-cua-doi-tuyen-viet-nam-o-asian-cup-2027-moi-nhat-cropped-1792554544767.jpg","crawledAt":"2026-10-21T13:43:07.172Z"},{"id":"dtri-20261021104301603","title":"Nữ giáo viên xinh đẹp bất ngờ “gây sốt”","slug":"nu-giao-vien-xinh-dep-bat-ngo-gay-sot","excerpt":"Cô giáo Tôn Nữ Diệu Hạnh đã kết nối yêu thương để tiếp sức học sinh miền núi đến trường và được vinh danh “Thanh niên sống đẹp” cấp thành phố Đà Nẵng.","content":"(Dân trí) - Cô giáo Tôn Nữ Diệu Hạnh đã kết nối yêu thương để tiếp sức học sinh miền núi đến trường và được vinh danh “Thanh niên sống đẹp” cấp thành phố Đà Nẵng.\n\nNhững ngày qua, cô giáo Tôn Nữ Diệu Hạnh (33 tuổi, trú phường An Hải, thành phố Đà Nẵng) thu hút sự chú ý sau khi được trao giải thưởng “Thanh niên sống đẹp” cấp thành phố Đà Nẵng năm 2026.\n\nHình ảnh nữ giáo viên trẻ trung, xinh đẹp trong màu áo xanh nhận giải khiến nhiều người quan tâm đến câu chuyện phía sau.\n\nChị Tôn Nữ Diệu Hạnh cho biết đây là giải thưởng được Hội Liên hiệp Thanh niên Việt Nam thành phố Đà Nẵng trao tặng ngày 11/10, dành cho các tấm gương có hành động dũng cảm, lối sống nghĩa tình, giàu lòng nhân ái, tích cực vì cộng đồng và vươn lên trong cuộc sống.\n\nChị Hạnh chia sẻ bản thân là giáo viên môn âm nhạc Trường Tiểu học Tiểu La (phường An Hải). Chị bắt đầu hành trình thiện nguyện từ năm 2023, sau chuyến đi đầu tiên đến một điểm trường miền núi tỉnh Quảng Nam (cũ).\n\nChứng kiến học sinh nơi đây còn nhiều thiếu thốn, chị cùng nhóm thiện nguyện của mình tổ chức vận động quần áo, sách vở trao tặng các em hay lắp đặt điện năng lượng mặt trời cho điểm trường miền núi xã Trà Vân (Đà Nẵng).\n\nLà giáo viên, chị Hạnh hiểu rằng những món quà chỉ mang lại niềm vui nhất thời, còn để học sinh khó khăn duy trì việc học cần sự đồng hành lâu dài. Vì vậy, nhóm của chị Hạnh cũng tổ chức các hoạt động khuyến học, trong đó hỗ trợ 20 học sinh tại một điểm trường, mỗi em 200.000 đồng/tháng trong suốt một năm.\n\nTrong năm học 2025-2026, chị còn phối hợp vận động tiền, sách vở, đồ dùng học tập, nhu yếu phẩm hỗ trợ học sinh và người dân bị ảnh hưởng bởi bão lũ. Chị cũng hai lần tham gia hiến máu nhân đạo.\n\nKhi nhắc đến giải thưởng “Thanh niên sống đẹp”, chị Hạnh chia sẻ đó là sự động viên để tiếp tục hành trình đã chọn, đồng thời nhắc nhở bản thân sống có trách nhiệm hơn với cộng đồng.\n\n“Với tôi, mỗi chuyến đi không chỉ là hành trình mang quà lên núi, mà còn là cách gieo thêm niềm vui học tập, nuôi dưỡng hy vọng cho những học trò nhỏ. Chừng nào còn có thể góp sức, tôi vẫn muốn tiếp tục hành trình ấy”, chị Hạnh chia sẻ.\n\nBà Nguyễn Thị Thanh Long, Bí thư Đoàn Thanh niên Cộng sản Hồ Chí Minh phường An Hải, cho biết giáo viên tham gia công tác Đoàn phải cân đối giữa nhiệm vụ chuyên môn và hoạt động phong trào. Dù vậy, chị Diệu Hạnh cùng các đoàn viên vẫn nỗ lực khắc phục khó khăn, hoàn thành tốt nhiệm vụ được giao.","author":"Hoài Sơn","category":"Giáo dục","publishedAt":"2026-10-21 10:43","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/nu-giao-vien-xinh-dep-bat-ngo-gay-sot-20261021104301603.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/MNcvb5zOgnTj9M3a29IDMQLhsb4=/zoom/1200_630/2026/10/21/co-giao-dieu-hanha-nui4-cropped-1792553013547.jpg","crawledAt":"2026-10-21T13:43:23.331Z"},{"id":"dtri-20261021103913787","title":"Lo ngại não mô cầu, phụ huynh TPHCM cấp tập đưa con đi tiêm mũi đầu tiên","slug":"lo-ngai-nao-mo-cau-phu-huynh-tphcm-cap-tap-dua-con-di-tiem-mui-dau-tien","excerpt":"Sau khi ghi nhận chùm ca mắc não mô cầu tại trường học, nhiều phụ huynh ở TPHCM lo lắng, đưa con đi tiêm vaccine phòng bệnh. Một cơ sở ghi nhận số lượt tiêm tăng gấp 7-8 lần thường ngày.","content":"Trong bối cảnh TPHCM ghi nhận chùm ca mắc não mô cầu tại trường học, nhiều phụ huynh lo ngại đã ồ ạt đưa con đi tiêm vaccine ngừa bệnh. Trong đó nhiều trẻ đã đi học và lần đầu tiêm vaccine này.\n\nVì lo lắng nên đưa con đi tiêm mũi đầu tiên\n\nTheo ghi nhận của Dân trí, tại Bệnh viện Nhi đồng 1 (TPHCM), chị Trần Thị Nguyên (38 tuổi, ngụ TPHCM) đưa con gái 12 tuổi đi tiêm vaccine phòng bệnh não mô cầu để chủ động bảo vệ sức khỏe cho trẻ.\n\nTheo chị Nguyên, đây là lần đầu tiên con chị tiêm vaccine phòng não mô cầu. Sau khi được bác sĩ tư vấn, chị dự định đưa con đi tiêm mũi tiếp theo sau một tháng theo lịch hẹn. Ngày hôm sau, chị cũng sẽ đưa người 7 tuổi đi tiêm phòng.\n\nChị Nguyên cho biết, khi biết thông tin về bệnh não mô cầu lây lan, có thể diễn tiến nhanh; các triệu chứng ban đầu của bệnh có thể giống những bệnh hô hấp thông thường như ho, sốt, rất khó nhận biết, chị thấy lo lắng nên xin cho con nghỉ học để tranh thủ đi tiêm phòng.\n\nBên cạnh việc tiêm vaccine, chị cho biết gia đình chú trọng giữ gìn vệ sinh nhà cửa sạch sẽ, thông thoáng, thường xuyên rửa tay và sát khuẩn các vật dụng. Theo chị, chủ động phòng bệnh không chỉ giúp bảo vệ sức khỏe của trẻ mà còn giúp phụ huynh yên tâm hơn khi con đến trường.\n\nTại Trung tâm Tiêm chủng & Khám, tư vấn sức khỏe trẻ em, Bệnh viện Nhi đồng 1, anh Hồ Minh Chí (32 tuổi, ngụ TPHCM) cũng đưa con gái 9 tuổi đi tiêm vaccine phòng bệnh não mô cầu.\n\nTheo anh Chí, những thông tin về các chùm ca bệnh não mô cầu trong trường học gần đây khiến gia đình lo lắng, nên quyết định xin cho con nghỉ học một buổi để đi tiêm phòng.\n\nGia đình anh có hai con. Trước đó, người con nhỏ 3 tuổi cũng đã được mẹ đưa đi tiêm vaccine phòng não mô cầu tại một cơ sở tiêm chủng.\n\n“Bé 9 tuổi đi học, tiếp xúc với nhiều người, lại có bệnh nền tiểu đường nên tôi nghĩ cần phòng ngừa trước. Theo tôi, việc chủ động tiêm vaccine không chỉ giúp bảo vệ sức khỏe của trẻ mà còn giúp gia đình an tâm hơn khi các con đến trường, hạn chế nỗi lo trước nguy cơ lây nhiễm bệnh”, anh Chí chia sẻ.\n\nSố lượt tiêm vaccine tăng mạnh\n\nTrao đổi với phóng viên Dân trí, BS Nguyễn Hồng Phong, Trung tâm Tiêm chủng & Khám, tư vấn sức khỏe trẻ em, Bệnh viện Nhi đồng 1, cho biết số lượng phụ huynh đưa con đến tiêm vaccine phòng bệnh não mô cầu những ngày gần đây tăng mạnh so với trước.\n\n“Lượng người đến tiêm tăng mạnh trong đợt dịch này, chủ yếu là trẻ ở độ tuổi đi học. Trước đây, mỗi ngày chỉ có khoảng 5-6 ca tiêm vaccine não mô cầu rải rác, nhưng hiện nay con số này tăng lên khoảng 20-30 ca mỗi ngày.\n\nĐây vốn là nhóm thường ít đi tiêm trong thời gian học tập, nhưng trước thông tin về các ca bệnh não mô cầu, nhiều phụ huynh đã chủ động đưa con đi tiêm, thậm chí có trường hợp xin cho trẻ nghỉ học để đi tiêm phòng”, BS Phong chia sẻ.\n\nBS Phong cho biết, phần lớn trẻ đến tiêm trong đợt này là tiêm mũi đầu tiên. Trong khi đó, trẻ dưới 1 tuổi thường được gia đình đưa đi tiêm đúng lịch và đã hoàn thành hai mũi theo chỉ định. Ngược lại, một số trẻ ở độ tuổi đi học có thể đã bỏ qua mũi tiêm phòng não mô cầu trước đó.\n\nNgoài ra, cũng có một số phụ huynh đưa con đến tiêm vaccine phòng não mô cầu nhóm B dù trẻ đã tiêm các chủng vaccine khác trước đây, tuy nhiên số trường hợp này không nhiều.\n\nBS Phong khuyến cáo phụ huynh nên chủ động đưa trẻ đi tiêm vaccine phòng não mô cầu càng sớm càng tốt, đồng thời tham khảo ý kiến nhân viên y tế để lựa chọn loại vaccine và lịch tiêm phù hợp với độ tuổi, tình trạng tiêm chủng của trẻ.\n\nTại Viện Pasteur TPHCM, số lượt tiêm vaccine não mô cầu cũng có xu hướng tăng mạnh. Những ngày trước đây, mỗi ngày chỉ có khoảng 15-20 trường hợp đến tiêm ngừa vaccine não mô cầu. Tuy nhiên, từ cuối tuần đến nay, số lượng người dân đến tiêm loại vaccine này tăng khoảng 7-8 lần so với ngày thường.\n\nNgoài não mô cầu, trong cộng đồng vẫn luôn tiềm ẩn nhiều bệnh truyền nhiễm nguy hiểm khác đã có vaccine bảo vệ như cúm mùa, phế cầu, sởi, thủy đậu... Do đó, các chuyên gia khuyến cáo khi đến cơ sở y tế, người dân nên chủ động tiêm phòng đầy đủ các loại vaccine cần thiết để bảo vệ sức khỏe cho bản thân và gia đình từ sớm.\n\nVaccine không bảo vệ tuyệt đối\n\nTheo chuyên gia, vaccine giúp giảm nguy cơ mắc bệnh não mô cầu do các nhóm huyết thanh được vaccine bao phủ, nhưng không tạo miễn dịch bảo vệ tuyệt đối.\n\nCác nhóm A, B, C, W và Y đều có thể gây bệnh nghiêm trọng, trong đó có viêm màng não và nhiễm khuẩn huyết. Hiện có các loại vaccine phòng nhóm B, vaccine cộng hợp phòng 4 nhóm A, C, W, Y (ACWY) và vaccine phòng 2 nhóm B, C (BC). Vì vậy, tiêm vaccine phòng một nhóm không đồng nghĩa với được bảo vệ trước tất cả các nhóm còn lại.\n\nBác sĩ khuyến cáo phụ huynh kiểm tra lịch sử tiêm chủng của trẻ, tham khảo ý kiến chuyên môn để lựa chọn vaccine và hoàn thiện lịch tiêm phù hợp với độ tuổi, tình trạng sức khỏe và nguy cơ phơi nhiễm.\n\nĐối với kháng sinh dự phòng, người đã tiêm vaccine không cần sử dụng thường quy nếu không có chỉ định. Tuy nhiên, người tiếp xúc gần với ca bệnh não mô cầu xâm lấn vẫn cần được đánh giá nguy cơ và sử dụng kháng sinh dự phòng theo chỉ định của bác sĩ, bất kể đã tiêm vaccine hay chưa.\n\nKháng sinh dự phòng cần được sử dụng càng sớm càng tốt sau khi xác định có phơi nhiễm nguy cơ cao, nhằm giảm nguy cơ phát bệnh. Người dân không nên tự ý mua kháng sinh mà cần liên hệ cơ sở y tế để được hướng dẫn biện pháp dự phòng phù hợp.","author":"Thảo Phương","category":"Sức khỏe","publishedAt":"2026-10-21 10:39","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/lo-ngai-nao-mo-cau-phu-huynh-tphcm-cap-tap-dua-con-di-tiem-mui-dau-tien-20261021103913787.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/rj1YoVAfrz_5dJLcfMXQ3WvqDrI=/zoom/1200_630/2026/10/21/d6fe094baf6e2f30767f8-edited-cropped-1792553037927.jpg?watermark=v1","crawledAt":"2026-10-21T13:42:37.883Z"},{"id":"dtri-20261021102410651","title":"Lịch chi trả lương hưu tháng 11, cách thức nhận hưu trí mới từ 2027","slug":"lich-chi-tra-luong-huu-thang-11-cach-thuc-nhan-huu-tri-moi-tu","excerpt":"Có 21 tỉnh thành chi trả lương hưu, trợ cấp bảo hiểm xã hội qua tài khoản cá nhân ngay ngày làm việc đầu tiên của tháng 11. Số tỉnh thành còn lại sẽ chi trả vào ngày làm việc thứ hai của tháng.","content":"(Dân trí) - Có 21 tỉnh thành chi trả lương hưu, trợ cấp bảo hiểm xã hội qua tài khoản cá nhân ngay ngày làm việc đầu tiên của tháng 11. Số tỉnh thành còn lại sẽ chi trả vào ngày làm việc thứ hai của tháng.\n\nLịch chi trả lương hưu, trợ cấp của 34 tỉnh thành\n\nBảo hiểm xã hội Việt Nam đã có hướng dẫn Bảo hiểm xã hội các tỉnh, thành phố về việc chi trả lương hưu, trợ cấp hằng tháng cho người hưởng.\n\nTheo đó, có 21 tỉnh thành chi trả lương hưu, trợ cấp qua tài khoản cá nhân vào ngày làm việc đầu tiên của tháng; 13 tỉnh thành chi trả vào ngày làm việc thứ hai của tháng.\n\nCác tỉnh, thành chi trả qua tài khoản vào ngày làm việc đầu tiên của tháng - ngày 2/11 (thứ hai): Sơn La, Điện Biên, Lạng Sơn, Nghệ An, Quảng Ninh, Cao Bằng, Bắc Ninh, Hưng Yên, Ninh Bình, Phú Thọ, Tuyên Quang, Huế, Khánh Hòa, Lâm Đồng, Đắk Lắk, TPHCM, Cần Thơ, Vĩnh Long, Cà Mau, Gia Lai, An Giang.\n\nCòn các tỉnh, thành chi trả qua tài khoản vào ngày làm việc thứ 2 của tháng - ngày 3/11 (thứ ba): Hà Nội, Lai Châu, Thanh Hóa, Thái Nguyên, Hải Phòng, Hà Tĩnh, Quảng Trị, Lào Cai, Quảng Ngãi, Đà Nẵng, Đồng Nai, Tây Ninh, Đồng Tháp.\n\nLịch chi trả trên là lịch chung và có thể được điều chỉnh tùy theo tình hình của các địa phương. Người hưởng lương hưu có thể liên hệ với cơ quan Bảo hiểm xã hội địa phương hoặc bưu điện để có thông tin chi tiết và chính xác nhất về lịch chi trả tại khu vực của mình.\n\nHình thức chi trả lương hưu, trợ cấp thất nghiệp qua VNeID\n\nTheo Kế hoạch triển khai sử dụng tài khoản hưởng an sinh xã hội trong chi trả các chế độ bảo hiểm xã hội, bảo hiểm thất nghiệp, trong tháng 10, cơ quan Bảo hiểm xã hội tập trung hoàn thiện phương án kết nối, tích hợp, trao đổi dữ liệu với hệ thống định danh điện tử.\n\nNhững đơn vị này cũng hướng dẫn liên quan đến việc xác định, sử dụng tài khoản hưởng an sinh xã hội phục vụ chi trả chế độ cũng được xây dựng trong giai đoạn này.\n\nPhương thức nhận tiền được thiết kế theo hướng linh hoạt. Người hưởng có thể liên kết tài khoản thanh toán, ví điện tử hoặc tài khoản tiền di động với tài khoản hưởng an sinh xã hội trên VNeID. Song song với quá trình chuẩn bị kỹ thuật, thông tin của người đang hưởng chế độ cũng như người mới tham gia sẽ được rà soát, chuẩn hóa.\n\nTrong tháng 11 và 12, Bảo hiểm xã hội Việt Nam dự kiến hoàn thành kết nối hệ thống phần mềm với hệ thống định danh điện tử, tạo nền tảng khai thác, đối soát thông tin phục vụ việc chi trả.\n\nCùng với hoàn thiện hạ tầng kỹ thuật, ngành Bảo hiểm xã hội sẽ tăng cường tuyên truyền, hướng dẫn người dân đăng ký, tích hợp, sử dụng tài khoản hưởng an sinh xã hội. Đây là bước chuẩn bị để phương thức chi trả mới được triển khai rộng rãi đối với các chế độ bảo hiểm xã hội, bảo hiểm thất nghiệp từ năm 2027.\n\nĐáng chú ý, việc chuyển đổi phương thức nhận tiền được thực hiện theo lộ trình, bảo đảm quyền lợi của người thụ hưởng. Trường hợp người dân chưa đủ điều kiện nhận tiền qua tài khoản hưởng an sinh xã hội trên VNeID vẫn được chi trả bằng phương thức phù hợp, tránh gián đoạn lương hưu, trợ cấp hoặc các chế độ đang hưởng.\n\nTài khoản hưởng an sinh xã hội là thông tin được tích hợp trên VNeID, cho phép người dân liên kết phương tiện thanh toán để nhận các khoản tiền thuộc chính sách an sinh. Từ ngày 28/9, người dân đã có thể nhận lương hưu, trợ cấp cùng các khoản an sinh xã hội thông qua tài khoản này theo quy định tại Nghị định số 320/2026/NĐ-CP.","author":"Lê Thanh Xuân","category":"Nội vụ","publishedAt":"2026-10-21 10:24","source":"dantri.com.vn","url":"https://dantri.com.vn/noi-vu/lich-chi-tra-luong-huu-thang-11-cach-thuc-nhan-huu-tri-moi-tu-2027-20261021102410651.htm","categories":["Nội vụ"],"categoryIds":["noi-vu"],"thumbnail":"https://cdnphoto.dantri.com.vn/qvbCJBu8tW4Yn5uNynmuoBM6nCA=/zoom/1200_630/2026/07/21/uy-quyen-luong-huu-2-edited-cropped-1784620297226.jpg","crawledAt":"2026-10-21T13:43:36.647Z"},{"id":"dtri-20261021101726826","title":"Người vợ Trung Quốc nhập viện vì gãy 5 xương sườn sau cái ôm của chồng","slug":"nguoi-vo-trung-quoc-nhap-vien-vi-gay-5-xuong-suon-sau-cai-om-cua-chong","excerpt":"Sau khi nhận cái ôm lãng mạn từ chồng, một phụ nữ Trung Quốc đã phải nhập viện vì bị gãy 5 xương sườn. Sự việc khiến nhiều người bất ngờ và tìm hiểu kỹ hơn về nguy cơ chấn thương sau mỗi cái ôm.","content":"(Dân trí) - Sau khi nhận cái ôm lãng mạn từ chồng, một phụ nữ Trung Quốc đã phải nhập viện vì bị gãy 5 xương sườn. Sự việc khiến nhiều người bất ngờ và tìm hiểu kỹ hơn về nguy cơ chấn thương sau mỗi cái ôm.\n\nChấn thương xương sườn sau cái ôm bất ngờ\n\nTheo truyền thông Trung Quốc, chủ đề cái ôm chứa đầy yêu thương bất ngờ gây ra tai nạn đang được bàn luận sôi nổi trên các nền tảng mạng xã hội nước này.\n\nTheo đó, nhiều người đã chia sẻ đoạn video quay lại cảnh một người đàn ông ôm vợ rất chặt. Không ngờ sau chiếc ôm, người vợ đau đớn đến mức không thể đứng thẳng và phải đến bệnh viện chụp CT lồng ngực. Kết quả cho thấy, chị bị gãy 5 xương sườn, 1 xương sườn khác bị nứt.\n\nSau sự việc, người chồng vô cùng áy náy. Anh chia sẻ vốn chỉ muốn ôm vợ thật chặt để cô ấy cảm nhận được tình yêu nồng nhiệt của mình. Anh không ngờ cái ôm ấy lại khiến vợ gặp chấn thương nặng.\n\nBan đầu, nhiều người cho rằng, đây chỉ là một trường hợp cá biệt. Song trên thực tế, tai nạn do ôm người khác dẫn đến gãy xương đã từng xảy ra.\n\nTháng 4 năm nay, một chàng trai bắt chước video đang thịnh hành trên mạng, bất ngờ vòng tay ôm bạn gái từ phía sau, nhấc cô lên rồi xoay vòng.\n\nThời điểm ấy, cô gái không cảm nhận được cảm giác đau rõ rệt, nhưng sau đó, cơn đau ở thành ngực bên trái ngày càng dữ dội, đến mức việc hít thở hay ho cũng khiến cô đau đớn. Kết quả kiểm tra tại bệnh viện cho thấy xương sườn thứ năm bên trái của cô gái đã bị gãy.\n\nTrong suy nghĩ của nhiều người, hành động ôm từ phía sau rồi nhẹ nhàng nhấc đối phương lên là cử chỉ thân mật đầy lãng mạn. Thế nhưng, ít ai ngờ, đằng sau động tác tưởng chừng ngọt ngào ấy lại tiềm ẩn nguy cơ chấn thương.\n\nBác sĩ cảnh báo nguy cơ gãy xương sườn khi ôm, nhấc người đột ngột\n\nCác bác sĩ tim mạch, lồng ngực cảnh báo, lực ôm và nhấc người đột ngột từ phía sau có thể tạo ra áp lực chèn ép không đồng đều lên lồng ngực, từ đó gây tổn thương xương sườn.\n\nXét về mặt cơ sinh học, xương sườn thứ năm đến thứ tám có độ cong lớn và khả năng chịu lực nén tương đối hạn chế. Khi chịu tác động mạnh, đột ngột từ bên ngoài, những xương này dễ bị gãy.\n\nTheo bác sĩ, điều này không có nghĩa là mọi người phải tránh ôm nhau trong sinh hoạt hàng ngày. Song cần lưu ý khi ôm, nhấc người khác cần kiểm soát lực tác động và thực hiện đúng cách.\n\nCác bác sĩ cũng chỉ ra các cách bảo vệ xương, phòng ngừa chấn thương\n\n- Tránh ôm siết hoặc nhấc người đột ngột từ phía sau: Đặc biệt cần thận trọng khi đối phương có thể trạng gầy hoặc khối lượng xương thấp. Khi ôm, nên thực hiện nhẹ nhàng, tránh bất ngờ dùng lực mạnh để siết chặt lồng ngực.\n\n- Tránh tạo áp lực trực tiếp lên vùng xương sườn: Khi ôm, không nên dùng tay siết chặt quanh khu vực lồng ngực. Có thể vòng tay quanh vùng eo hoặc lưng, tránh chèn ép trực tiếp vào ngực.\n\n- Không ôm siết hoặc đùa nghịch mạnh khi đối phương bị đau ngực: Nếu người kia đã có cảm giác đau âm ỉ ở ngực hoặc xương sườn, cần tránh những động tác gây áp lực mạnh lên khu vực này.\n\n- Bổ sung đầy đủ dinh dưỡng để bảo vệ xương: Cần bảo đảm cung cấp đủ protein chất lượng cao và canxi thông qua các thực phẩm như sữa, chế phẩm từ sữa, đậu nành, cá và tôm. Không nên duy trì chế độ ăn kiêng quá mức trong thời gian dài. Đồng thời, cần hạn chế tiêu thụ quá nhiều cà phê và trà đặc.\n\n- Tiếp xúc với ánh nắng mặt trời hợp lý: Có thể dành khoảng 15-20 phút mỗi ngày ở ngoài trời, để da vùng cánh tay hoặc mặt tiếp xúc với ánh nắng phù hợp, hỗ trợ cơ thể tổng hợp vitamin D và hấp thụ canxi. Tuy nhiên, thời gian tiếp xúc cần điều chỉnh theo cường độ tia cực tím, loại da và điều kiện thời tiết; không nên cố phơi nắng khi chỉ số UV cao.\n\n- Duy trì vận động thường xuyên: Nên thực hiện các bài tập chịu trọng lượng và tập sức mạnh như đi bộ nhanh, tập tạ hoặc tập kháng lực phù hợp với thể trạng. Việc tăng cường khối lượng cơ giúp nâng đỡ, bảo vệ xương tốt hơn.\n\n- Kiểm tra mật độ xương khi cần thiết: Phụ nữ sau mãn kinh, người ăn kiêng kéo dài hoặc có cân nặng thấp nên trao đổi với bác sĩ về việc kiểm tra mật độ xương định kỳ. Nếu phát hiện tình trạng suy giảm khối lượng xương, cần can thiệp sớm và sử dụng thuốc khi có chỉ định của bác sĩ.\n\n- Đừng chủ quan khi đau ngực sau một cái ôm: Nếu sau khi ôm hoặc chịu một lực tác động nhẹ, một người xuất hiện tình trạng đau ngực kéo dài, đau tăng khi hít thở sâu hoặc ho, không dám xoay người vì đau, cần nhanh chóng đến cơ sở y tế để được kiểm tra.\n\nTheo Sohu","author":"Hồng Anh","category":"Đời sống","publishedAt":"2026-10-21 10:17","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/nguoi-vo-trung-quoc-nhap-vien-vi-gay-5-xuong-suon-sau-cai-om-cua-chong-20261021101726826.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/MTXmmiIM71ShQDfSP1VTkaNC5VY=/zoom/1200_630/2026/10/21/om-2-cropped-1792552496786.jpg","crawledAt":"2026-10-21T13:42:44.386Z"},{"id":"dtri-20261021101035615","title":"Siêu bão Champi mạnh lên cấp 17, có thể gây gió mạnh ở Biển Đông","slug":"sieu-bao-champi-manh-len-cap-17-co-the-gay-gio-manh-o-bien-dong","excerpt":"Siêu bão Champi đã mạnh lên cấp 17, giật trên cấp 17, cơn bão mạnh nhất trên khu vực Tây Bắc Thái Bình Dương trong năm 2026. Dự báo dù không đi vào Biển Đông nhưng bão sẽ gây gió mạnh ở khu vực này.","content":"(Dân trí) - Siêu bão Champi đã mạnh lên cấp 17, giật trên cấp 17, cơn bão mạnh nhất trên khu vực Tây Bắc Thái Bình Dương trong năm 2026. Dự báo dù không đi vào Biển Đông nhưng bão sẽ gây gió mạnh ở khu vực này.\n\nTrung tâm Dự báo khí tượng thủy văn quốc gia cho biết sáng 21/10, siêu bão Champi có vị trí khoảng 18,1 độ Vĩ Bắc; 130,2 độ Kinh Đông, cường độ mạnh cấp 17, giật trên cấp 17. Hiện siêu bão cách đảo Lu Dông (Philippines) khoảng 800km về phía Đông Đông Nam.\n\nTheo các số liệu phân tích vệ tinh mới nhất, siêu bão Champi có sức gió mạnh nhất khoảng 210km/giờ, Champi tương đương siêu bão cấp 5 theo phân loại của cơ quan khí tượng Mỹ.\n\nVới số liệu phân tích hiện nay, siêu bão Champi hiện được đánh giá là cơn bão mạnh nhất trên khu vực Tây Bắc Thái Bình Dương trong năm 2026, vượt qua cường độ của siêu bão Sinlaku. Hiện tại với mắt bão rộng khoảng 80km, rõ nét và khá đối xứng.\n\nCơ quan khí tượng cho biết siêu bão đang hoạt động trên vùng biển có nhiệt độ mặt nước khoảng 29-30 độ C, là điều kiện thuận lợi để duy trì cường độ mạnh. Dự báo trong khoảng 24 giờ tới, bão vẫn có khả năng duy trì cường độ cấp 17, giật trên cấp 17, di chuyển chủ yếu theo hướng Tây Tây Bắc với tốc độ khoảng 20-25km/h.\n\nDự báo từ ngày 22/10, Champi có xu hướng chuyển dần sang hướng Tây Bắc. Khi di chuyển về phía Bắc và đi vào khu vực có nhiệt độ mặt nước biển thấp hơn, cường độ bão được dự báo suy yếu dần.\n\nSo với các phiên dự báo 2 ngày qua, dự báo mới nhất của nhiều cơ quan khí tượng quốc tế như Nhật Bản, Hàn Quốc, Trung Quốc, Mỹ… đã có xu hướng thống nhất hơn về kịch bản đường đi của bão Champi, theo đó bão ít khả năng đổ bộ trực tiếp vào Đài Loan (Trung Quốc).\n\nTheo cơ quan khí tượng, đến khoảng ngày 24/10, khi di chuyển đến vùng biển phía Đông Đài Loan (Trung Quốc), cường độ siêu bão Champi được dự báo giảm xuống khoảng cấp 10, giật cấp 13, sau đó bão có khả năng chuyển hướng Đông Bắc, di chuyển về phía khu vực Nhật Bản và Hàn Quốc.\n\nĐến ngày 25/10, khi tiến về khu vực phía Nam Nhật Bản và Hàn Quốc, bão Champi tiếp tục suy yếu, với cường độ dự báo khoảng cấp 8, giật cấp 10.\n\nCơ quan khí tượng nhận định siêu bão Champi sẽ không di chuyển vào Biển Đông, tuy nhiên với cường độ mạnh cấp 16-17, bán kính ảnh hưởng rộng thì hoàn lưu phía Tây của siêu bão có thể gây gió mạnh cấp 6-7, giật cấp 8-9 kèm sóng biển cao 2-4m ở khu vực Đông Bắc của vùng biển phía Bắc Biển Đông.","author":"Bạch An","category":"Thời sự","publishedAt":"2026-10-21 10:10","source":"dantri.com.vn","url":"https://dantri.com.vn/thoi-su/sieu-bao-champi-manh-len-cap-17-co-the-gay-gio-manh-o-bien-dong-20261021101035615.htm","categories":["Thời sự"],"categoryIds":["thoi-su"],"thumbnail":"https://cdnphoto.dantri.com.vn/_CR2CIkyu4gNvPeA5WBx8JG1ZKI=/zoom/1200_630/2026/10/21/bao-cropped-1792551271273.jpg","crawledAt":"2026-10-21T13:42:25.494Z"},{"id":"dtri-20261021101007000","title":"Khách Việt tấp nập sang Trung Quốc đông thứ 3 thế giới","slug":"khach-viet-tap-nap-sang-trung-quoc-dong-thu-3-the-gioi","excerpt":"Trong quý 3 năm nay, Việt Nam trở thành thị trường gửi khách lớn thứ 3 tới Trung Quốc. Chính sách quá cảnh miễn visa 240 giờ áp dụng từ tháng 8 được cho là góp phần tạo nên dòng khách này.","content":"(Dân trí) - Trong quý 3 năm nay, Việt Nam trở thành thị trường gửi khách lớn thứ 3 tới Trung Quốc. Chính sách quá cảnh miễn visa 240 giờ áp dụng từ tháng 8 được cho là góp phần tạo nên dòng khách này.\n\nKhách Việt đi Trung Quốc tăng vọt, hưởng lợi từ chính sách miễn visa\n\nTheo số liệu Cục Quản lý Di dân Quốc gia Trung Quốc (NIA) công bố ngày 20/10, 10 quốc gia có lượng khách nhập cảnh Trung Quốc lớn nhất trong quý 3 lần lượt là Nga, Hàn Quốc, Việt Nam, Malaysia, Mỹ, Mông Cổ, Nhật Bản, Singapore, Thái Lan và Australia.\n\nKhách từ 10 quốc gia này chiếm 63,9% tổng lượng khách nước ngoài nhập cảnh.\n\nSố liệu từ Cổng thông tin Chính phủ Trung Quốc cho thấy, trong 6 tháng đầu năm nay, Việt Nam là nguồn khách lớn thứ 4, xếp sau Hàn Quốc, Nga và Malaysia.\n\nTính chung trong quý 3, Trung Quốc ghi nhận 192 triệu lượt xuất nhập cảnh, tăng 7,9% so với cùng kỳ năm trước. Người nước ngoài có 11,6 triệu lượt nhập cảnh, tăng 15,6%. Trong đó, gần 9 triệu lượt nhập cảnh theo diện miễn thị thực, chiếm 77,5% và tăng 24,1%.\n\nTrước đó từ 20/8, Việt Nam và Kyrgyzstan được Trung Quốc bổ sung vào danh sách các nước hưởng chính sách quá cảnh miễn thị thực 240 giờ. Danh sách này hiện có 57 quốc gia.\n\nCụ thể, công dân Việt Nam mang hộ chiếu phổ thông, có vé liên chặng xác nhận ngày giờ đi tiếp sang nước hoặc vùng lãnh thổ thứ ba, có thể nhập cảnh qua 65 cửa khẩu trên khắp Trung Quốc và lưu trú tối đa 10 ngày mà không cần visa.\n\nKhách được phép du lịch, công tác, thăm thân, giao lưu. Các hoạt động như làm việc, học tập hay tác nghiệp báo chí vẫn phải xin thị thực phù hợp.\n\nCũng từ ngày 20/8, khách Việt được hưởng chính sách miễn visa 30 ngày khi đến đảo Hải Nam.\n\nNgay sau khi chính sách có hiệu lực, nhiều đoàn khách Việt đã nhanh chóng sang Trung Quốc. Theo kênh CCTV+, một đoàn 240 du khách Việt Nam đã qua cửa khẩu Đông Hưng (Quảng Tây).\n\nCùng thời điểm, 2 chuyến bay chở 306 hành khách từ Việt Nam hạ cánh xuống sân bay Giao Đông ở Thanh Đảo (Sơn Đông). Truyền thông Trung Quốc cho biết hơn 80% số ghế trên các chuyến bay từ Việt Nam sang Trung Quốc đã được lấp đầy trong cuối tuần đầu tiên áp dụng chính sách.\n\nBên cạnh chính sách miễn visa, việc nối lại và mở rộng các chuyến bay thẳng, tuyến đường sắt xuyên biên giới cũng giúp việc đi lại thuận tiện hơn.\n\nBà Tưởng Y Y - Viện trưởng Viện Thể thao Giải trí và Du lịch thuộc Đại học Thể thao Bắc Kinh - cho rằng, sự tăng trưởng của khách quốc tế đến từ chính sách được cải thiện, giao thông kết nối tốt hơn và sản phẩm du lịch đa dạng hơn từ chính sách được cải thiện, giao thông kết nối tốt hơn và sản phẩm du lịch đa dạng hơn.\n\nTừ du lịch tới chi tiêu mua sắm\n\nỞ các tỉnh giáp Việt Nam, lượng khách Việt tăng rõ rệt. Theo thống kê từ CCTV+, trong 7 tháng đầu năm, Quảng Tây ghi nhận hơn 4,1 triệu lượt khách Việt Nam xuất nhập cảnh, tăng 10,1% so với cùng kỳ.\n\nViệt Nam tiếp tục là nguồn khách quốc tế hàng đầu của tỉnh Quảng Tây. Số liệu từ China News Service cũng cho thấy, lượng khách Việt lưu trú qua đêm tại tỉnh này trong nửa đầu năm tăng 81%.\n\nTại cửa khẩu Hà Khẩu (tỉnh Vân Nam), từ đầu năm đến ngày 13/8 ghi nhận hơn 4 triệu lượt người qua lại biên giới Việt - Trung, tăng 5,24%. Sân bay Trường Thủy ở Côn Minh hiện khai thác hơn 570 chuyến bay quốc tế mỗi tuần, trong đó có các đường bay tới Hà Nội, TPHCM, Nha Trang và Phú Quốc.\n\nKhông chỉ tham quan, mua sắm đang trở thành một phần quan trọng trong hành trình của khách quốc tế tới Trung Quốc.\n\nMột tiểu thương bán đồ điện tử thông minh ở Nghĩa Ô (Chiết Giang) cho biết từ tháng 9, lượng khách nước ngoài đến cửa hàng tăng rõ. Trong đó, các sản phẩm tích hợp AI (trí tuệ nhân tạo) được nhiều người quan tâm.\n\nChị Maria, du khách Brazil, mua dây đeo điện thoại, móc treo túi và 5 hộp quà bí ẩn (blind box). Theo cô, một chiếc móc điện thoại tương tự ở Brazil có giá hơn 200 tệ (775.000 đồng), trong khi ở Trung Quốc chỉ 20-30 nhân dân tệ (77.000 đồng - 115.000 đồng).\n\nHoạt động mua sắm còn được thúc đẩy nhờ chính sách hoàn thuế. Theo Tổng cục Thuế Trung Quốc, trong 6 tháng đầu năm nay, số khách nước ngoài được hoàn thuế khi xuất cảnh tăng 366%. Doanh số hàng hóa thuộc diện hoàn thuế và tổng số tiền hoàn đều tăng 69%.\n\nTheo Global Times, CCTV+","author":"Huy Hoàng","category":"Du lịch","publishedAt":"2026-10-21 10:10","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/khach-viet-tap-nap-sang-trung-quoc-dong-thu-3-the-gioi-20261021101007000.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/p4oKvXrG4bONcq8uAn8DCYXpg9g=/zoom/1200_630/2026/10/21/khach-viet-sang-trung-quoc-dong-thu-3-the-gioi-chi-xep-sau-nga-va-han-quoc-1-edited-cropped-cropped-1792552074866.jpg","crawledAt":"2026-10-21T13:42:48.395Z"},{"id":"dtri-20261021094852493","title":"BYD Sealion 5 giá từ 739 triệu đồng tại Việt Nam, tham vọng đấu CX-5","slug":"byd-sealion-5-gia-tu-739-trieu-dong-tai-viet-nam-tham-vong-dau-cx","excerpt":"Mức giá niêm yết của BYD Sealion 5 thấp hơn mặt bằng giá của nhiều mẫu SUV hạng C, đồng thời mẫu xe này có lợi thế về trang bị, công nghệ và động cơ PHEV.","content":"(Dân trí) - Mức giá niêm yết của BYD Sealion 5 thấp hơn mặt bằng giá của nhiều mẫu SUV hạng C, đồng thời mẫu xe này có lợi thế về trang bị, công nghệ và động cơ PHEV.\n\nTại thị trường Việt Nam, BYD Sealion 5 có hai phiên bản, gồm Essential và Premium, với giá bán niêm yết lần lượt là 739 triệu đồng và 789 triệu đồng.\n\nHãng xe Trung Quốc áp dụng ưu đãi giảm 80 triệu đồng cho 1.000 khách hàng đầu tiên đặt cọc trước ngày 30/11, đưa giá bán thực tế xuống 659 triệu đồng và 709 triệu đồng.\n\nĐộng cơ hybrid sạc ngoài (PHEV) là lợi thế của Sealion 5, trong bối cảnh chưa có nhiều mẫu xe SUV hạng C tại Việt Nam sử dụng hệ truyền động này.\n\nCụ thể, xe sử dụng công nghệ DM-i Hybrid, kết hợp động cơ xăng 1.5L và một mô-tơ điện, sản sinh tổng công suất 214 mã lực và mô-men xoắn cực đại 210Nm, kết hợp với hệ dẫn động cầu trước.\n\nỞ chế độ thuần điện, Sealion 5 có phạm vi di chuyển 110km với bản Premium và hơn 82km với bản Essential, theo chuẩn NEDC. Khi kết hợp với động cơ xăng, phạm vi di chuyển tăng lên 1.200km ở bản Premium và 1.150km ở bản Essential.\n\nMẫu SUV Trung Quốc dùng bộ pin BYD LFP Blade dung lượng 13,08kWh trên bản Essential và 18,3kWh trên bản Premium. Bản Essential dùng cổng sạc AC công suất 3,3kW, trong khi bản Premium được trang bị cả sạc AC 3,3kW và sạc DC 18kW.\n\nKhác với công nghệ mild hybrid và hybrid tự sạc (HEV), hệ thống PHEV cần bộ pin dung lượng lớn. Do đó, người dùng vẫn cần tính toán đến vấn đề sạc ngoài nếu muốn khai thác tối đa khả năng vận hành thuần điện. Theo công bố của hãng, ở trạng thái đầy pin, bản Premium chỉ tiêu thụ 0,8 lít/100km.\n\nTrong trường hợp pin cạn, Sealion 5 vẫn có động cơ xăng để duy trì khả năng vận hành. Đây là một lợi thế về tính linh hoạt, đồng thời giúp người dùng giảm mức độ phụ thuộc vào hạ tầng trạm sạc so với xe điện thuần túy. Nhưng nếu ít sạc và thường xuyên chạy đường dài bằng động cơ xăng, một phần lợi thế của hệ thống PHEV sẽ không được phát huy.\n\nSealion 5 thuộc dải sản phẩm Dynasty của BYD, với thiết kế ngoại hình có một số điểm tương đương với các mẫu Sealion 8 và Atto 3 đang được hãng phân phối tại Việt Nam.\n\nSealion 5 sở hữu kích thước dài x rộng x cao lần lượt là 4.735 x 1.860 x 1.710mm, chiều dài cơ sở 2.712mm và khoảng sáng gầm xe 175mm. Xe có 5 chỗ ngồi và được trang bị bộ mâm 18 inch đi kèm lốp 225/60.\n\nSo với CX-5, Sealion 5 dài hơn 145mm, rộng hơn 15mm, cao hơn 30mm và chiều dài cơ sở lớn hơn 12mm, nhưng khoảng sáng gầm thấp hơn, ở mức 175mm so với 200mm của CX-5.\n\nKhông gian bên trong tạo điểm nhấn với màn hình thông tin giải trí kích thước 12,8 inch và màn hình hiển thị thông tin sau vô lăng 8,8 inch (trên bản Premium). Giống như các mẫu BYD khác đang bán tại Việt Nam, Sealion 5 có thiết kế khoang lái tối giản các nút bấm vật lý. Để điều khiển các tính năng, người dùng phải thao tác trên màn hình thông tin giải trí.\n\nMột vài trang bị đáng chú ý gồm: cần số sau vô lăng, ghế da tổng hợp, điều khiển giọng nói, cổng sạc Type C và A, kết nối Apple CarPlay và Android Auto, cập nhật phần mềm qua OTA, ổ cắm nguồn 12V, thẻ khóa NFC, cốp dung tích 530L và có thể tăng lên 1.482L khi gập hàng ghế thứ hai…\n\nSealion 5 được trang bị khá nhiều tính năng hỗ trợ lái và an toàn, nhưng phần lớn các công nghệ đáng chú ý chỉ xuất hiện trên phiên bản Premium.\n\nCụ thể, bản cao cấp có các tính năng như camera 360 độ xuyên thấu, kiểm soát hành trình thích ứng, nhận diện biển báo giao thông, cảnh báo xe phía trước đã khởi hành, hỗ trợ giữ làn khẩn cấp, hỗ trợ lệch làn, cảnh báo lệch làn, cảnh báo va chạm phía trước/sau, phanh tự động và hệ thống kiểm soát khoảng cách đỗ xe,...\n\nViệc các công nghệ hỗ trợ lái tập trung ở bản Premium đồng nghĩa người mua bản Essential phải chấp nhận ít trang bị tiện nghi và tính năng hỗ trợ lái hơn đáng kể.","author":"Phùng Thế Anh","category":"Xe ++","publishedAt":"2026-10-21 09:48","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/byd-sealion-5-gia-tu-739-trieu-dong-tai-viet-nam-tham-vong-dau-cx-5-20261021094852493.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/oviP7kraIEdX4YsH1cFqzshGoUo=/zoom/1200_630/2026/10/21/dscf9145-cropped-1792552974391.jpg","crawledAt":"2026-10-21T13:43:29.053Z"},{"id":"dtri-20261021091901360","title":"CLB Thái Lan lên tiếng trước tin đồn sa thải HLV Park Hang Seo","slug":"clb-thai-lan-len-tieng-truoc-tin-don-sa-thai-hlv-park-hang-seo","excerpt":"Chủ tịch Prawat Kithammakunnit của Kanchanaburi FC đã lên tiếng khẳng định vẫn đặt niềm tin dài hạn vào HLV Park Hang Seo dù CLB không có kết quả tốt.","content":"(Dân trí) - Chủ tịch Prawat Kithammakunnit của Kanchanaburi FC đã lên tiếng khẳng định vẫn đặt niềm tin dài hạn vào HLV Park Hang Seo dù CLB không có kết quả tốt.\n\nTrái với kỳ vọng, CLB Kanchanaburi thi đấu không tốt ở mùa giải này. Họ chỉ giành chiến thắng trong 2/7 trận đấu đầu tiên ở mùa giải này và xếp thứ 6 trên bảng xếp hạng giải hạng 2 Thái Lan khi có 10 điểm, kém đội đầu bảng Khonkaen Utd 5 điểm.\n\nKhông những vậy, HLV Park Hang Seo còn nhiều lần có hành động nổi nóng với trọng tài, khiến người hâm mộ Thái Lan không hài lòng.\n\nTrước tình hình đó, nhiều nguồn tin cho rằng CLB Kanchanaburi sẽ sớm sa thải HLV người Hàn Quốc. Tuy nhiên, Chủ tịch CLB Kanchanaburi, ông Prawat Kithammakunnit đã bác bỏ thông tin này. Ông khẳng định sẽ không sa thải HLV Park Hang Seo, ngay cả khi Kanchanaburi FC không thể lên hạng ở mùa này.\n\nNgười đứng đầu CLB Kanchanaburi cho biết: “Mọi người không cần lo lắng. Chúng tôi đang xây dựng đội bóng theo kế hoạch dài hạn. Ngay cả khi không thể thăng hạng trong năm nay, chúng tôi chắc chắn cũng không sa thải HLV Park Hang Seo.\n\nTôi đang rất hào hứng với quá trình xây dựng đội bóng, gieo trồng và kiên nhẫn chờ đợi thành quả của Kanchanaburi FC”.\n\nHồi đầu mùa giải, Kanchanaburi FC đã đặt mục tiêu giành tấm vé thăng hạng, HLV Park Hang Seo được cung cấp khá nhiều ngôi sao chất lượng. Ngoài ra, chiến lược gia người Hàn Quốc còn nắm giữ vai trò then chốt trong việc hoạch định và tái cấu trúc lại toàn bộ hệ thống đào tạo trẻ, tạo nền móng vững chắc cho sự phát triển lâu dài của câu lạc bộ.\n\nSau khi trận đấu Muang Loei ở giải hạng 2 Thái Lan vào cuối tuần qua kết thúc, HLV Park Hang Seo đã bức xúc vì cho rằng trọng tài không công tâm khi bù giờ nhiều hơn thời gian công bố trước đó.\n\nHLV người Hàn Quốc tuyên bố: “Tôi không bàn đến bàn thua nhưng trọng tài làm việc thiếu công tâm khiến trận đấu hỏng hết. Bao nhiêu mồ hôi công sức của mọi người đổ sông đổ bể. Tôi chỉ rời đi là xong nhưng nếu các bạn cứ làm bóng đá thế này thì không phát triển được đâu. Trọng tài làm việc phải bằng lương tâm chứ”.","author":"H. Long","category":"Thể thao","publishedAt":"2026-10-21 09:19","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/clb-thai-lan-len-tieng-truoc-tin-don-sa-thai-hlv-park-hang-seo-20261021091901360.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/TOQtNYubjbJ-5v-iPLf9fZUUing=/zoom/1200_630/2026/10/21/clb-thai-lan-len-tieng-truoc-tin-don-sa-thai-hlv-park-hang-seo-cropped-1792548839964.jpg","crawledAt":"2026-10-21T13:43:07.219Z"},{"id":"dtri-20261021090516378","title":"Sắp diễn ra ESG Company Tour về tự động hóa, tài chính xanh","slug":"sap-dien-ra-esg-company-tour-ve-tu-dong-hoa-tai-chinh-xanh","excerpt":"Sự kiện ESG Company Tour 2026 số 2 kết hợp tham quan nhà máy Nhựa Bình Minh với phần tham quan nhà máy và phiên thảo luận về tự động hóa, tối ưu nguồn lực và cơ hội tiếp cận tài chính xanh.","content":"(Dân trí) - Sự kiện ESG Company Tour 2026 số 2 kết hợp tham quan nhà máy Nhựa Bình Minh với phần tham quan nhà máy và phiên thảo luận về tự động hóa, tối ưu nguồn lực và cơ hội tiếp cận tài chính xanh.\n\nNgày 29/10, ESG Company Tour 2026 số 2 với chủ đề “Tự động hóa - Hiệu quả - Tài chính xanh” sẽ diễn ra tại nhà máy Nhựa Bình Minh, tỉnh Tây Ninh. Chương trình do báo Dân trí chủ trì, phối hợp tổ chức cùng SCG và BM Plasco, tạo cơ hội để doanh nghiệp tìm hiểu thực tiễn triển khai ESG trong sản xuất và trao đổi giải pháp nâng cao hiệu quả vận hành gắn với mục tiêu phát triển bền vững.\n\nTrong bối cảnh doanh nghiệp sản xuất chịu áp lực nâng cao năng suất, kiểm soát chi phí và đáp ứng các yêu cầu môi trường, đầu tư công nghệ cần được cân nhắc trên cơ sở hiệu quả thực tế. Làm thế nào để lựa chọn đúng công đoạn cần tự động hóa, tối ưu nguồn lực và tiếp cận nguồn vốn phù hợp là những vấn đề được đặt ra tại chương trình.\n\nTại nhà máy Nhựa Bình Minh, người tham dự sẽ có cơ hội tìm hiểu hành trình phát triển bền vững và các thực hành ESG trong quản trị sản xuất, tối ưu nguồn lực, tiết kiệm năng lượng, bảo đảm an toàn người lao động, quản trị rủi ro và đổi mới công nghệ. Những nội dung này gợi mở cách doanh nghiệp đưa mục tiêu phát triển bền vững vào hoạt động vận hành hằng ngày.\n\nMột trọng tâm của chương trình là bài toán lựa chọn và đánh giá hiệu quả đầu tư tự động hóa. Công nghệ có thể hỗ trợ cải thiện năng suất, chất lượng sản phẩm và mức độ ổn định của quy trình, nhưng không phải giải pháp nào cũng phù hợp với mọi nhà máy. Hiệu quả phụ thuộc vào điểm nghẽn cần xử lý, quy mô sản xuất, khả năng tích hợp với dây chuyền hiện có và năng lực vận hành sau đầu tư.\n\nVì vậy, doanh nghiệp cần xác định rõ vấn đề trước khi lựa chọn công nghệ, đồng thời lượng hóa lợi ích dự kiến thông qua các chỉ số như năng suất, tỷ lệ lỗi, thời gian dừng máy, mức tiêu hao năng lượng và nguyên liệu. Đây cũng là cơ sở để đánh giá thời gian hoàn vốn, kiểm soát rủi ro và lựa chọn phương án đầu tư phù hợp với nguồn lực.\n\nBên cạnh công nghệ và hiệu quả, tài chính xanh là một khía cạnh quan trọng của quá trình chuyển đổi. Các dự án tiết kiệm năng lượng, sử dụng tài nguyên hiệu quả hoặc giảm tác động môi trường có thể mở ra cơ hội tiếp cận những nguồn vốn phù hợp nếu đáp ứng điều kiện của bên tài trợ. Tuy nhiên, doanh nghiệp vẫn cần chứng minh tính khả thi của dự án, hiệu quả tài chính, khả năng trả nợ và các tiêu chí liên quan. Việc gắn mục tiêu môi trường với kế hoạch đầu tư và dữ liệu có thể kiểm chứng vì thế ngày càng quan trọng.\n\nThông qua hoạt động tham quan và thảo luận, ESG Company Tour tạo không gian để doanh nghiệp chia sẻ kinh nghiệm triển khai ESG, trao đổi về những khó khăn trong quản trị và vận hành, đồng thời tìm kiếm giải pháp phù hợp với điều kiện thực tế. Chương trình cũng thúc đẩy kết nối giữa doanh nghiệp, chuyên gia, hiệp hội và các tổ chức liên quan, góp phần mở rộng cơ hội hợp tác trong cộng đồng hướng tới phát triển bền vững.\n\nESG Company Tour là hoạt động vệ tinh thuộc Diễn đàn ESG Việt Nam 2026 với chủ đề “Nắm bắt cơ hội - Dẫn dắt tăng trưởng”. Trước đó, tour số 1 diễn ra ngày 12/8 tại Nhà máy Prime Tiền Phong, tỉnh Phú Thọ, tập trung vào chuyển đổi xanh và quản trị hiệu quả cho doanh nghiệp nhỏ và vừa.\n\nVới chuỗi ESG Company Tour, Diễn đàn ESG Việt Nam 2026 tiếp tục lan tỏa các mô hình và kinh nghiệm thực tiễn, hỗ trợ doanh nghiệp tiếp cận ESG từ góc độ quản trị, hiệu quả hoạt động và năng lực cạnh tranh.\n\nSự kiện ngày 29/10 tại nhà máy Nhựa Bình Minh kỳ vọng góp phần gợi mở cách tiếp cận thiết thực để doanh nghiệp từng bước chuyển mục tiêu phát triển bền vững thành những hành động phù hợp với nguồn lực và chiến lược dài hạn.\n\nESG Company Tour 2026 với chủ đề “Tự động hoá - Hiệu quả - Tài chính xanh” sẽ diễn ra ngày 29/10 tại nhà máy Nhựa Bình Minh, Tây Ninh. Chương trình tạo cơ hội để doanh nghiệp tìm hiểu thực tế mô hình vận hành, ứng dụng tự động hóa, nâng cao hiệu quả sản xuất và tiếp cận các góc nhìn về tài chính xanh.\n\nThông qua hoạt động tham quan nhà máy và trao đổi với chuyên gia, đại diện doanh nghiệp, ngân hàng, chương trình hướng tới những giải pháp thiết thực giúp doanh nghiệp xác định lộ trình đầu tư công nghệ phù hợp, đánh giá hiệu quả và từng bước tích hợp ESG vào hoạt động sản xuất, kinh doanh.\n\nESG Company Tour là hoạt động vệ tinh của Diễn đàn ESG Việt Nam 2026 với chủ đề “Nắm bắt cơ hội - Dẫn dắt tăng trưởng”, do báo Dân trí khởi xướng và tổ chức. Tour đầu tiên đã diễn ra ngày 12/8 tại nhà máy Prime Tiền Phong (Phú Thọ) với chủ đề “Chuyển đổi xanh và quản trị hiệu quả cho doanh nghiệp SME”.\n\nDiễn đàn ESG Việt Nam là sự kiện thường niên do báo Dân trí khởi xướng và tổ chức từ năm 2024. Điểm nhấn của Diễn đàn là chuỗi hoạt động hội thảo, tọa đàm, company tour và lễ vinh danh Vietnam ESG Awards tôn vinh các đơn vị thực thi tốt ESG.\n\nDiễn đàn ESG Việt Nam 2026 diễn ra vào tháng 12/2026 có chủ đề “Nắm bắt cơ hội - Dẫn dắt tăng trưởng”. Chủ đề của Diễn đàn được lựa chọn trong bối cảnh các tiêu chuẩn về môi trường, xã hội và quản trị (ESG) ngày càng trở thành yếu tố then chốt quyết định năng lực cạnh tranh của doanh nghiệp.\n\nDiễn đàn năm nay không chỉ tập trung vào tính cấp thiết của việc hành động sớm mà còn đặt trọng tâm vào vai trò tiên phong của doanh nghiệp và tổ chức trong việc chuyển hóa thách thức thành động lực dẫn dắt tăng trưởng bền vững.","author":"Cẩm Hà","category":"Kinh doanh","publishedAt":"2026-10-21 09:05","source":"dantri.com.vn","url":"https://dantri.com.vn/kinh-doanh/sap-dien-ra-esg-company-tour-ve-tu-dong-hoa-tai-chinh-xanh-20261021090516378.htm","categories":["Kinh doanh"],"categoryIds":["kinh-doanh"],"thumbnail":"https://cdnphoto.dantri.com.vn/wjYi_X8KJXBzDuwvV4-i0bsOIhM=/zoom/1200_630/2026/10/21/kv-companytour-10-cropped-1792547561508.jpg","crawledAt":"2026-10-21T13:42:54.943Z"},{"id":"dtri-20261021085115849","title":"Thông tư 85 không yêu cầu dừng tất cả chương trình liên kết","slug":"thong-tu-85-khong-yeu-cau-dung-tat-ca-chuong-trinh-lien-ket","excerpt":"Thông tư 85 không yêu cầu chấm dứt tất cả chương trình liên kết. Việc triển khai phải phù hợp điều kiện thực tế, đồng thời bảo đảm quyền lợi và sự công bằng cho học sinh.","content":"(Dân trí) - Thông tư 85 không yêu cầu chấm dứt tất cả chương trình liên kết. Việc triển khai phải phù hợp điều kiện thực tế, đồng thời bảo đảm quyền lợi và sự công bằng cho học sinh.\n\nNgày 21/10, Sở GD&ĐT TPHCM tổ chức hội thảo trao đổi về việc triển khai Thông tư 85/2026/TT-BGDĐT, với sự tham dự trực tuyến của ông Thái Văn Tài, Vụ trưởng Vụ Giáo dục Phổ thông, Bộ GD&ĐT.\n\nHội thảo diễn ra trong bối cảnh nhiều trường học băn khoăn về cách tổ chức các chương trình liên kết, hoạt động giáo dục tăng cường và hoạt động theo nhu cầu người học khi Thông tư 85 có hiệu lực từ ngày 15/11.\n\nPhát biểu tại hội thảo, ông Nguyễn Bảo Quốc, Phó Giám đốc Sở GD&ĐT TPHCM, cho biết văn bản dù chưa có hiệu lực đã nhận được sự quan tâm từ các cơ sở giáo dục, phụ huynh. Trong quá trình triển khai, các trường có cách hiểu khác nhau và gửi nhiều băn khoăn lên Sở. Vì vậy, Sở tổ chức hội thảo để tiếp tục lắng nghe ý kiến từ cơ sở, giải đáp vướng mắc và thống nhất định hướng thực hiện.\n\nBà Phạm Thị Bé Hiền, Trưởng phòng Giáo dục Phổ thông, Sở GD&ĐT TPHCM, bày tỏ mọi sự điều chỉnh, sắp xếp của các nhà trường phải thực hiện trên tinh thần đảm bảo quyền lợi của học sinh, hạn chế tối đa việc xáo trộn khung giờ học tập và lịch đưa đón của phụ huynh học sinh.\n\nKhông phải tất cả chương trình liên kết đều phải dừng\n\nMột trong những vấn đề được các trường quan tâm là liệu Thông tư 85 có buộc chấm dứt các chương trình liên kết đang tổ chức hay không.\n\nTại hội thảo, nội dung được làm rõ là Thông tư 85 không yêu cầu tất cả trường học phải dừng tất cả chương trình liên kết. Việc tiếp tục, điều chỉnh hay chấm dứt từng hoạt động cần căn cứ vào nội dung, mục tiêu, điều kiện tổ chức và quy định hiện hành.\n\nTheo định hướng của Bộ GD&ĐT, các trường cần rà soát kế hoạch, nội dung, hình thức tổ chức, đối tác và các điều kiện liên quan; xác định hoạt động nào thuộc nhóm giáo dục tăng cường, hoạt động nào thực sự xuất phát từ nhu cầu riêng của học sinh. Những nội dung không phù hợp quy định phải được điều chỉnh.\n\nTheo Thông tư 85, hoạt động giáo dục tăng cường (không thu phí) được tổ chức ngoài thời lượng chính khóa nhằm bổ sung những nội dung giáo dục cần thiết, tăng cường thực hành, trải nghiệm, vận dụng kiến thức và phát triển phẩm chất, năng lực học sinh theo mục tiêu Chương trình giáo dục phổ thông.\n\nCác nội dung có thể gồm khoa học, công nghệ, tin học, năng lực số, trí tuệ nhân tạo (AI), giáo dục STEM, thực hành, trải nghiệm, củng cố năng lực ngoại ngữ, hướng nghiệp phổ cập và kỹ năng sống ở mức độ cơ bản, cần thiết chung cho người học.\n\nTại hội thảo, ông Tài nhấn mạnh yêu cầu công bằng trong tiếp cận giáo dục. Theo định hướng này, không thể để học sinh có điều kiện kinh tế, có khả năng đóng tiền được tiếp cận các nội dung giáo dục cần thiết, trong khi học sinh ở những địa bàn khó khăn lại không có cơ hội tương tự.\n\nNhà trường cần chủ động xây dựng kế hoạch giáo dục tăng cường phù hợp với học sinh, đội ngũ và điều kiện thực tế, đồng thời thực hiện đúng quy định về nguồn kinh phí và tổ chức hoạt động.\n\nLấy ví dụ từ các chương trình, đề án đặc thù đang được TPHCM triển khai rất hiệu quả, ông Thái Văn Tài cho rằng khi vận hành theo bối cảnh quy định mới của Thông tư 85, ngành giáo dục Thành phố cần rà soát và bóc tách nội dung một cách căn cơ, chính xác.\n\nTheo ông Tài, tên gọi của một đề án hay chương trình không quyết định đó là hoạt động tăng cường hay theo nhu cầu người học, mà bản chất nằm ở nội hàm kiến thức được thiết kế truyền tải.\n\nVí dụ đối với chương trình trí tuệ nhân tạo (AI), các nội dung nào mà bất kỳ học sinh nào cũng cần được trang bị thì sẽ là hoạt động tăng cường, Nhà nước và ngân sách địa phương sẽ bảo đảm chi trả, học sinh được thụ hưởng miễn phí để bảo đảm tính công bằng giáo dục.\n\nNội dung giáo dục theo nhu cầu người học là những phần kiến thức mở rộng, nâng cao, chuyên sâu hoặc năng khiếu. Phần nội dung này mới thực hiện theo cơ chế xã hội hóa và thỏa thuận thu chi đúng quy định.\n\nTừ phân tích trên, Vụ trưởng đề nghị TPHCM đánh giá lại toàn bộ các đề án hiện hành để phân định mạch lạc: Phần nội dung nào là tăng cường chung cho toàn bộ học sinh thì đưa vào kế hoạch giáo dục chính thức của nhà trường và sử dụng nguồn lực Nhà nước bảo đảm; phần nội dung nào thuộc về nguyện vọng riêng thì xếp vào nhóm hoạt động theo nhu cầu.\n\nHoạt động theo nhu cầu phải thực sự tự nguyện\n\nKhác với hoạt động tăng cường, hoạt động giáo dục theo nhu cầu người học nhằm đáp ứng nhu cầu mở rộng, nâng cao hoặc chuyên sâu, sở thích, năng khiếu và định hướng phát triển cá nhân của học sinh.\n\nNhững nội dung chuyên sâu về ngoại ngữ, lập trình, robot, công nghệ hoặc các hoạt động phát triển năng khiếu văn hóa, nghệ thuật, thể thao có thể được xem xét tổ chức theo nhu cầu người học nếu đáp ứng các điều kiện theo quy định.\n\nNhóm hoạt động này được tổ chức trên cơ sở tự nguyện. Việc tham gia hay không tham gia không được trở thành căn cứ để gây áp lực, phân biệt đối xử hoặc ảnh hưởng đến việc đánh giá kết quả học tập của học sinh. Việc thu kinh phí phải tuân thủ các quy định tương ứng; nhà trường không thể chỉ đổi tên một chương trình tăng cường thành hoạt động theo nhu cầu để thu tiền.\n\nTại hội thảo, ông Tài cũng lưu ý việc bảo đảm công bằng không đồng nghĩa với cào bằng. Với hoạt động tăng cường, nhà trường cần bảo đảm cơ hội tiếp cận những nội dung cần thiết cho mọi học sinh theo kế hoạch.\n\nVới hoạt động theo nhu cầu, sự công bằng còn thể hiện ở việc tôn trọng lựa chọn thực chất của từng người học. Ví dụ, việc học sinh lựa chọn 2/4 hay 3/4 môn theo đúng nguyện vọng hoàn toàn không vi phạm nguyên tắc công bằng.\n\nTheo đó, học sinh có thể lựa chọn những nội dung phù hợp với nguyện vọng, năng lực và điều kiện của mình, miễn là việc tổ chức đáp ứng đúng quy định và không ảnh hưởng đến quyền lợi của những học sinh khác.\n\nTại hội thảo, lãnh đạo Sở GD&ĐT TPHCM cho biết thành phố có những mô hình và chương trình đặc thù như tiếng Anh tích hợp, tin học, ngoại ngữ và trường học tiên tiến, hội nhập. Sở đang nghiên cứu để có hướng dẫn cụ thể, phù hợp với điều kiện thực tế và đặc điểm của từng mô hình.\n\nĐây cũng là vấn đề các trường mong muốn được làm rõ, bởi việc phân định hoạt động tăng cường với hoạt động theo nhu cầu không chỉ ảnh hưởng đến nội dung giáo dục mà còn liên quan đến cách bố trí thời khóa biểu, đội ngũ giáo viên, kinh phí và quyền lựa chọn của phụ huynh, học sinh.\n\nVụ trưởng Vụ Giáo dục phổ thông cũng giải tỏa áp lực cho các hiệu trưởng khi khẳng định: Thông tư 85 là định hướng pháp lý cho cả một chặng đường phát triển lâu dài, không phải là văn bản mang tính chất bắt buộc tất cả các trường học phải đáp ứng ngay lập tức 100% điều kiện cơ sở vật chất và nhân sự từ ngày 15/11.\n\nÔng Thái Văn Tài gợi ý trong năm đầu tiên triển khai, các hiệu trưởng cần hết sức linh hoạt. Nhà trường nên chọn các nội dung giáo dục tăng cường một cách nhẹ nhàng, dễ thực hiện, dựa trên cơ sở vật chất và đội ngũ hiện có (như các hoạt động trải nghiệm liên môn, củng cố kiến thức). Các trường không nên bê nguyên cơ học kế hoạch của các năm trước sang năm nay khi bối cảnh pháp lý đã thay đổi.","author":"Huyên Nguyễn","category":"Giáo dục","publishedAt":"2026-10-21 08:51","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/thong-tu-85-khong-yeu-cau-dung-tat-ca-chuong-trinh-lien-ket-20261021085115849.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/sAwjrq7dBoEZ8Otszy7c3DUxAWI=/zoom/1200_630/2026/10/21/hoc-lien-ket-huyen-nguyen-cropped-1792547300380.jpg","crawledAt":"2026-10-21T13:43:22.222Z"},{"id":"dtri-20261021081245121","title":"Chật vật tìm bãi xe gần bệnh viện, phải tính toán cả phí đỗ mỗi lần đi khám","slug":"chat-vat-tim-bai-xe-gan-benh-vien-phai-tinh-toan-ca-phi-do-moi-lan-di-kham","excerpt":"Hơn 7h sáng, trước cổng các bệnh viện tuyến cuối ở nội đô, bãi đỗ trong viện nhanh chóng kín chỗ. Những chiếc ô tô đến sau đành quay đầu, tìm điểm gửi ngoài phố hoặc theo chỉ dẫn của bảo vệ đi xa hơn.","content":"(Dân trí) - Hơn 7h sáng, trước cổng các bệnh viện tuyến cuối ở nội đô, bãi đỗ trong viện nhanh chóng kín chỗ. Những chiếc ô tô đến sau đành quay đầu, tìm điểm gửi ngoài phố hoặc theo chỉ dẫn của bảo vệ đi xa hơn.\n\nVới người nhà bệnh nhân, thời gian đi khám không chỉ kéo dài 30 phút đến 1 tiếng. Nhiều người phải ở lại cả buổi, thậm chí gần trọn ngày, khiến chi phí gửi xe tăng theo từng giờ.\n\nBãi gần viện hết chỗ, gửi tư nhân 180.000 đồng/5 tiếng\n\nBa tháng nay, anh Phạm Văn H. (44 tuổi, quê Nam Định) thường xuyên phải đưa bố đi điều trị ngoại trú tại một bệnh viện tuyến Trung ương.\n\nTrao đổi với phóng viên, anh kể mình phải gửi xe tại một bãi tư nhân trên đường Giải Phóng cách cổng bệnh viện khoảng 80m.\n\n“Đến nơi thì bãi trong viện hết chỗ, bảo vệ chỉ tôi ra đây. Gửi 5 tiếng hết 180.000 đồng. Mình đang cần gửi xe nên không có lựa chọn nào khác”, anh H. nói.\n\nAnh kể, ngày đi khám, anh khó đoán trước giờ về. Có hôm anh khám xong trong buổi sáng, có hôm phải chờ kết quả đến chiều. Theo tính toán của anh, chi phí gửi xe mỗi tháng vào khoảng 720.000 đồng.\n\nChi phí mỗi tháng của gia đình anh gồm khoảng 2,4 triệu đồng tiền khám, xét nghiệm và thuốc thuộc phần tự chi trả, 1,2 triệu đồng tiền xăng và 720.000 đồng tiền gửi xe. Tổng cộng, gia đình phải chi khoảng 4,32 triệu đồng mỗi tháng, trong đó tiền gửi xe chiếm gần 17%.\n\n“Tiền thuốc men tôi có thể dự trù trước, nhưng tiền gửi xe tưởng nhỏ, cộng lại mới thấy cũng đáng kể”, anh H. cho biết.\n\nĐi hơn một cây số để tìm chỗ gửi xe \"gần cổng viện nhất\"\n\nTại một số bãi đỗ xe trên đường Trường Chinh, khách quen phần lớn là người nhà bệnh nhân. Bãi cách Bệnh viện Tai Mũi Họng Trung ương khoảng 1,2km và cách cụm Bệnh viện Bạch Mai, Bệnh viện Việt Pháp, Bệnh viện Da liễu Trung ương... khoảng 1,4km.\n\nGiá gửi tại đây thấp hơn so với lòng đường: 30.000 đồng/giờ nếu gửi theo giờ, 50.000 đồng/buổi, gửi cả ngày khoảng 100.000 đồng. Nhưng đổi lại, quãng đường đến nơi khám chữa bệnh khá xa.\n\nChị Nguyễn Thị M. (36 tuổi, quê Ninh Bình) đã đưa mẹ đến Bệnh viện Bạch Mai khám và điều trị ngoại trú trong khoảng 5 tháng nay.\n\nTrung bình mỗi tháng hai mẹ con lên Hà Nội khoảng hai lần. Do các điểm gửi xe gần bệnh viện thường kín chỗ, chị chọn một bãi đỗ xe trên đường Trường Chinh cách bệnh viện hơn 1km, phí trông giữ xe 50.000 đồng/buổi.\n\n“So với gửi ngoài phố thì rẻ hơn nhiều, nhưng từ bãi vào viện hơn một cây số, mẹ tôi đi lại khó khăn nên tôi phải gọi xe công nghệ, mỗi chiều khoảng 25.000 đồng. Có hôm mẹ bảo thôi gửi gần viện cho đỡ đi lại, nhưng những chỗ gần thì hết chỗ rồi”, chị M. chia sẻ.\n\nVới quãng đường khoảng 60km mỗi chiều từ Ninh Bình lên Hà Nội, mỗi chuyến đi còn phát sinh đáng kể chi phí nhiên liệu. Theo mức tiêu hao nhiên liệu giả định của ô tô, 2 chuyến khứ hồi mỗi tháng có thể tốn khoảng 450.000 đồng tiền xăng.\n\nCộng thêm 100.000 đồng tiền gửi xe và khoảng 100.000 đồng tiền xe công nghệ để di chuyển từ bãi đỗ đến bệnh viện và ngược lại, tổng chi phí đi lại vào khoảng 650.000 đồng mỗi tháng.\n\nNếu tính thêm khoảng 1,5 triệu đồng tiền khám, xét nghiệm và thuốc men mà gia đình phải tự chi trả, tổng chi phí mỗi tháng có thể vượt 2 triệu đồng.\n\nVới chị M., tiền gửi xe có thể không phải khoản chi lớn nhất. Tuy nhiên, việc phải trả thêm chi phí di chuyển do không tìm được chỗ đỗ gần bệnh viện khiến hành trình khám chữa bệnh trở nên tốn kém hơn.\n\nTheo bảng giá niêm yết tại một bệnh viện lớn trong khu vực, các phương tiện được miễn phí nếu gửi dưới 20 phút. Với ô tô đến 9 chỗ ngồi và xe tải từ 2 tấn trở xuống, giá gửi xe là 20.000 đồng/lượt/giờ. Mức giá đối với xe từ 10 chỗ ngồi trở lên và xe tải trên 2 tấn là 25.000 đồng/lượt/giờ.\n\nMức giá này thấp hơn đáng kể so với mức 50.000 đồng/60 phút tại khu vực đô thị lõi và 45.000 đồng/60 phút tại các tuyến còn lại trong Vành đai 1. Trong khi đó, bãi xe tư nhân nơi anh H. gửi xe có mức giá 180.000 đồng/5 tiếng, tương đương khoảng 36.000 đồng/giờ. Tuy nhiên, số chỗ đỗ trong bệnh viện có hạn, nên những người đến muộn thường phải tìm bãi gửi xe bên ngoài.\n\nVới gia đình có người bệnh, chi phí khám chữa bệnh gồm nhiều khoản như viện phí, thuốc men, xét nghiệm, ăn uống và đi lại. Tiền xăng phụ thuộc vào quãng đường di chuyển, trong khi tiền gửi xe tăng theo thời gian người nhà phải ở lại chờ khám hoặc nhận kết quả xét nghiệm.\n\nThực tế, các điểm trông giữ xe quanh bệnh viện áp dụng nhiều mức giá khác nhau. Vì vậy, người nhà bệnh nhân nên hỏi rõ giá và cách tính phí trước khi gửi xe, đồng thời cân nhắc đến sớm hoặc so sánh giá tại các bãi xe lân cận để chủ động hơn về chi phí.\n\nTrần Long","author":"CTV","category":"Xe ++","publishedAt":"2026-10-21 08:12","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/chat-vat-tim-bai-xe-gan-benh-vien-phai-tinh-toan-ca-phi-do-moi-lan-di-kham-20261021081245121.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/SoV3Uw-EZd9FPNK1QxwOy5bBsks=/zoom/1200_630/2026/10/21/di-hon-1km-tim-bai-xe-gan-benh-vien-phai-tinh-ca-phi-do-moi-lan-di-kham-cropped-1792568191064.jpg","crawledAt":"2026-10-21T13:43:27.896Z"},{"id":"dtri-20261021075403433","title":"Liverpool ngược dòng thắng nghẹt thở Villarreal trong trận cầu 7 bàn thắng","slug":"liverpool-nguoc-dong-thang-nghet-tho-villarreal-trong-tran-cau-7-ban-thang","excerpt":"Liverpool đã giành chiến thắng 4-3 trước Villarreal trong trận đấu ở lượt trận thứ ba vòng phân hạng Champions League diễn ra vào đêm qua.","content":"(Dân trí) - Liverpool đã giành chiến thắng 4-3 trước Villarreal trong trận đấu ở lượt trận thứ ba vòng phân hạng Champions League diễn ra vào đêm qua.\n\nLiverpool có lợi thế sân nhà Anfield khi đón tiếp Villarreal ở lượt trận thứ ba vòng phân hạng Champions League vào rạng sáng 21/10 (theo giờ Việt Nam). Tuy nhiên, đội chủ nhà Anfield lại thi đấu không thực sự tốt trong thời gian đầu trận đấu.\n\nHàng thủ của Liverpool thi đấu lỏng lẻo và thiếu tập trung. Ngay ở phút thứ 4, The Kop đã phải vào lưới nhặt bóng. Van Dijk mắc sai lầm cơ bản khi phá bóng, tạo điều kiện cho Georges Mikautadze băng xuống, hạ gục thủ thành Alisson, mở tỷ số cho Villarreal.\n\nChưa kịp bừng tỉnh sau bàn thua, Liverpool lại chịu bàn thua thứ hai ở phút 29. Thêm một lần, hàng thủ của CLB vùng Merseyside mắc sai lầm. Sergi Cardona băng xuống, dễ dàng đánh bại thủ thành Alisson trong tư thế đối mặt, nâng tỷ số lên 2-0 cho đại diện của Tây Ban Nha.\n\nTới lúc này, Liverpool mới bừng tỉnh. Phút 36, Mac Allister bật cao đánh đầu từ tình huống phạt góc, rút ngắn tỷ số xuống 1-2. Ngay trước giờ nghỉ, Ronald Araujo đã san bằng tỷ số 2-2 sau tình huống đánh đầu cận thành từ pha tạt bóng của Rio Ngumoha.\n\nSang hiệp 2, Liverpool tiếp tục làm chủ thế trận. Phút 65, Rio Ngumoha có pha đột phá vô cùng tốc độ, trước khi căng ngang vào vòng cấm cho Mac Allister dứt điểm cận thành tung lưới Villarreal, nâng tỷ số lên 3-2.\n\nTiếp đà hưng phấn, Liverpool có bàn thắng thứ 4 ở phút 68 sau pha dứt điểm của Florian Wirtz trong vòng cấm.\n\nTới cuối trận, Villarreal chỉ gỡ được một bàn thắng do công của Tani Oluwaseyi. Trận đấu kết thúc với tỷ số 4-3 nghiêng về Liverpool.\n\nNhư vậy, tính tới sáng 21/10, Liverpool đang cùng PSG là hai đội duy trì thành tích toàn thắng sau 3 trận đấu ở Champions League mùa này. The Kop xếp thứ hai do kém PSG hiệu số bàn thắng bại.","author":"H. Long","category":"Thể thao","publishedAt":"2026-10-21 07:54","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/liverpool-nguoc-dong-thang-nghet-tho-villarreal-trong-tran-cau-7-ban-thang-20261021075403433.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/d8YyRzrgNISm1owEsqdN7f1V2Q0=/zoom/1200_630/2026/10/21/liverpool-nguoc-dong-thang-nghet-tho-villarreal-trong-tran-cau-7-ban-thang-cropped-1792543871658.jpg","crawledAt":"2026-10-21T13:43:08.304Z"},{"id":"dtri-20261021073523119","title":"HLV Michael Carrick lên tiếng về nguy cơ bị Man Utd sa thải","slug":"hlv-michael-carrick-len-tieng-ve-nguy-co-bi-man-utd-sa-thai","excerpt":"Huấn luyện viên (HLV) Michael Carrick đã lên tiếng về tương lai của mình trước thềm lượt trận vòng 3 Champions League giữa Man Utd và Como.","content":"(Dân trí) - Huấn luyện viên (HLV) Michael Carrick đã lên tiếng về tương lai của mình trước thềm lượt trận vòng 3 Champions League giữa Man Utd và Como.\n\n“Có chứ, tại sao lại không? Tôi đang đảm nhiệm vai trò này và có mối quan hệ rất tốt với mọi người ở Man Utd. Thực sự, không có vấn đề hay bất đồng nào với bất kỳ bên nào”, HLV Michael Carrick thẳng thắn trả lời trong buổi họp báo khi được hỏi liệu ban lãnh đạo Man Utd có tiếp tục ủng hộ anh sau chuỗi trận thất vọng của “Quỷ đỏ” ở đầu mùa giải hay không.\n\nĐoàn quân của HLV Carrick chỉ thắng 2 trong 10 trận đầu tiên và mới có 1 chiến thắng tại Ngoại hạng Anh, khiến đội bóng tụt xuống vị trí thứ 13 trên bảng xếp hạng. Đây là thành tích khởi đầu tệ nhất của Man Utd trong 40 năm qua, kể từ mùa giải 1986-1987.\n\nCarrick đã ký hợp đồng có thời hạn 2 năm vào tháng 5, sau khi giúp đội chủ sân Old Trafford giành vé trở lại Champions League. Tuy nhiên, phong độ sa sút gần đây của đội bóng đã làm dấy lên những nghi ngờ về tương lai của nhà cầm quân người Anh.\n\nTrước trận đấu thứ ba vòng bảng Champions League của Man Utd gặp Como, đội bóng do cựu danh thủ Barcelona là Cesc Fabregas dẫn dắt, Carrick khẳng định ông không cần bất kỳ sự đảm bảo nào về tương lai từ Giám đốc điều hành Omar Berrada hay Giám đốc bóng đá Jason Wilcox.\n\n“Chắc chắn là không. Tôi không cần bất kỳ sự trấn an nào cả. Mọi thứ đều khá rõ ràng. Tôi biết vai trò và trách nhiệm của mình. Tôi không cần ai khác phải nói cho tôi biết điều đó, hay chỉ ra khi nào mọi việc đang diễn ra tốt đẹp và khi nào chúng tôi cần cải thiện. Tôi tự biết điều đó. Tôi hiểu rõ thực tế và không có vấn đề gì với điều đó.\n\nMọi chuyện đã rất rõ ràng, nên tôi không có gì để nói thêm. Tôi biết chúng tôi phải giành chiến thắng trong các trận đấu thì mọi thứ mới diễn ra suôn sẻ và đi đúng hướng”, HLV Michael Carrick khẳng định.\n\nTrước cuộc đối đầu với Como, Man Utd gặp khó khăn do cuộc khủng hoảng chấn thương. Các cầu thủ Rashford, Ayden Heaven, Luke Shaw, Kobbie Mainoo, Benjamin Sesko, Patrick Dorgu, Lisandro Martinez và Manuel Ugarte đều đang dính chấn thương hoặc không có thể trạng tốt nhất. Trong khi đó, Leny Yoro bị treo giò sau khi nhận thẻ đỏ trong trận đấu với Atletico Madrid tuần trước.\n\nỞ chiều ngược lại, hậu vệ trái 19 tuổi Harry Amass đủ điều kiện ra sân và có cơ hội đá chính lần đầu tiên cho Man Utd kể từ tháng 5/2025. Ngoài ra trung vệ Matthijs de Ligt có thể ra sân lần đầu tiên sau 11 tháng vắng mặt vì chấn thương lưng.\n\n\"Thật tuyệt khi cậu ấy trở lại. Cậu ấy đã trải qua một hành trình dài, kiên nhẫn và nỗ lực rất nhiều. Chúng tôi rất vui mừng khi cậu ấy trở lại. Cậu ấy khỏe mạnh, sẵn sàng, đã tập luyện trong nhiều tuần nay, vì vậy cậu ấy đang ở trong trạng thái rất tốt\", Carrick bày tỏ về sự trở lại của trung vệ người Hà Lan.\n\n“Hiện tại, tất cả mọi người đều có ý chí, quyết tâm cao độ và mong muốn cải thiện thành tích. Các cầu thủ cũng muốn làm điều đó vì nhau, và đây là yếu tố rất quan trọng. Vì vậy, xét về tinh thần đoàn kết của tập thể, tôi thực sự không thể đòi hỏi gì hơn ở sự gắn kết giữa các thành viên”, HLV Michael Carrick kết luận về quyết tâm của đội bóng trước trận gặp Como.","author":"Sông Lam","category":"Thể thao","publishedAt":"2026-10-21 07:35","source":"dantri.com.vn","url":"https://dantri.com.vn/the-thao/hlv-michael-carrick-len-tieng-ve-nguy-co-bi-man-utd-sa-thai-20261021073523119.htm","categories":["Thể thao"],"categoryIds":["the-thao"],"thumbnail":"https://cdnphoto.dantri.com.vn/C_tb7P8pHpSoMeT39hRaC6wl69E=/zoom/1200_630/2026/10/21/5efcb528-8efd-4b12-872f-d01c1e5a508e-cropped-1792542399323.jpg","crawledAt":"2026-10-21T13:43:08.270Z"},{"id":"dtri-20261021004543178","title":"Ford Ranger 2027 có thể có tùy chọn động xăng V6 3.0L","slug":"ford-ranger-2027-co-the-co-tuy-chon-dong-xang-v6-30l","excerpt":"Phiên bản mới của dòng bán tải Ford Ranger có thể được trang bị động cơ xăng V6 3.0L như trên Ranger Raptor, tuy nhiên công suất sẽ giảm bớt.","content":"(Dân trí) - Phiên bản mới của dòng bán tải Ford Ranger có thể được trang bị động cơ xăng V6 3.0L như trên Ranger Raptor, tuy nhiên công suất sẽ giảm bớt.\n\nTheo Motor1, phiên bản 2027 của dòng bán tải Ford Ranger sẽ được nâng cấp tương tự chiếc Ford Bronco. Cụ thể, hệ thống động cơ V6 3.0L trên chiếc Ranger Raptor sẽ được tinh chỉnh lại để sử dụng cho Ranger.\n\nCũng theo Motor1, thông tin cụ thể về việc động cơ V6 3.0L được tinh chỉnh như thế nào để lắp cho Ford Ranger vẫn chưa được hé lộ. Tuy nhiên, rất có thể thay đổi về công suất động cơ sẽ giống như trên Ford Bronco (công suất 380 mã lực, mô-men xoắn 597Nm).\n\nBên cạnh những nâng cấp về động cơ, dòng bán tải Ford Ranger 2027 còn được tinh chỉnh về thiết kế.\n\nỞ phiên bản mới, các chi tiết như lưới tản nhiệt, kích cỡ mâm xe, màu sơn ngoại thất, kích cỡ màn hình thông tin giải trí hay hệ thống điều hòa được trang bị tiêu chuẩn cho xe cũng sẽ được nâng cấp đáng kể.\n\nCũng theo Motor1, Ford có thể mang tới chiếc Ranger tùy chọn gói trang bị ngoại thất cao cấp mang tên Bronze Graphics. Gói trang bị này sẽ gồm các chi tiết lắp thêm như đèn viền nội thất, cần gạt mưa tự động, gương chiếu hậu mới, ghế lái có chức năng nhớ vị trí, sưởi, hệ thống âm thanh B&O gồm 10 loa.\n\nTuy nhiên, Motor1 không tiết lộ những nâng cấp này sẽ được áp dụng cho dòng bán tải Ford Ranger tại thị trường nào.\n\nTrước đó, trong một cuộc phỏng vấn với tờ Drive, ông Fadi Mawal, Chủ tịch kiêm Giám đốc điều hành Ford Australia, cho biết một nhóm khoảng 1.500 kỹ sư đang làm việc trong dự án Ranger thế hệ tiếp theo. Trong đó, một số là những người đã tham gia thiết kế Ranger thế hệ hiện hành, và dẫn dắt quá trình phát triển thế hệ T6 trước đó (ra mắt cuối năm 2010).\n\nHiện tại, Ford chưa tiết lộ thông tin cụ thể về sản phẩm, nhưng nhiều khả năng Ranger thế hệ mới sẽ có thân xe được thiết kế lại hoàn toàn, đi kèm khoang nội thất nhiều nút bấm vật lý hơn, êm ái và tinh tế hơn. Cũng chưa rõ khung gầm body-on-frame sẽ được phát triển mới hay kế thừa từ nền tảng hiện tại.\n\nRất có thể, ở phiên bản mới, dòng bán tải Ranger sẽ có thêm tùy chọn động cơ hybrid cắm sạc (PHEV). Thông tin về phiên bản thuần điện của dòng bán tải này không được tiết lộ.\n\nTại thị trường Việt Nam, trong năm 2026, Ford Việt Nam đã có những thay đổi đáng chú ý về tùy chọn động cơ cho dòng bán tải Ranger.\n\nCụ thể, Ford Ranger Wildtrak được lắp động cơ dầu 3.0L V6 hoàn toàn mới, vẫn đi kèm hộp số tự động 10 cấp và hệ dẫn động 4 bánh toàn thời gian.","author":"Hội An","category":"Xe ++","publishedAt":"2026-10-21 00:45","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/ford-ranger-2027-co-the-co-tuy-chon-dong-xang-v6-30l-20261021004543178.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/uCDi4kMrrWSrhPppCStGPVpCCAo=/zoom/1200_630/2026/10/21/ford-ranger-nang-cap-cropped-1792518161916.jpg","crawledAt":"2026-10-21T13:43:28.986Z"},{"id":"dtri-20261020235132179","title":"Lý do que thăm dầu dần biến mất trên ô tô hiện đại","slug":"ly-do-que-tham-dau-dan-bien-mat-tren-o-to-hien-dai","excerpt":"Ngày nay, đèn cảnh báo trên bảng đồng hồ và thông báo trên màn hình cảm ứng đang dần thay thế các phương pháp kiểm tra truyền thống.","content":"(Dân trí) - Ngày nay, đèn cảnh báo trên bảng đồng hồ và thông báo trên màn hình cảm ứng đang dần thay thế các phương pháp kiểm tra truyền thống.\n\nTrong nhiều thập kỷ, que thăm dầu là dụng cụ quen thuộc giúp chủ xe kiểm tra mức dầu động cơ. Chỉ với thao tác rút que thăm, lau sạch, cắm lại và rút ra lần nữa, người dùng có thể xác định mức dầu thông qua các vạch đánh dấu.\n\nTuy nhiên, trên một số mẫu xe đời mới, dụng cụ này không còn xuất hiện. Thay vào đó, hệ thống điện tử đo mức dầu và hiển thị kết quả trên bảng đồng hồ hoặc màn hình trung tâm.\n\nQue thăm dầu giúp người dùng kiểm tra trực tiếp mức dầu động cơ và quan sát màu sắc, dấu hiệu bất thường của dầu. Đây là thao tác đơn giản, nhưng cần thực hiện đúng hướng dẫn của nhà sản xuất để có kết quả đáng tin cậy.\n\nMột bước thụt lùi?\n\nNgày nay, nhiều mẫu xe không còn được trang bị dụng cụ đơn giản này. Thay vào đó, các hãng xe sử dụng hệ thống giám sát điện tử với thông tin hiển thị trên màn hình. Điều này có thể khiến những người thích tự bảo dưỡng ô tô cảm thấy đây là một bước thụt lùi. Tuy nhiên, có lý do cho sự thay đổi này.\n\nNăm 2024, trang Automotive News đã trực tiếp hỏi các hãng xe về lý do loại bỏ que thăm dầu và nhận được câu trả lời từ chính các nhà sản xuất.\n\n“Người tiêu dùng ngày nay không ưu tiên việc tự kiểm tra mức dầu bằng tay. Với cảm biến, thông tin này được hiển thị mỗi khi họ bật khóa điện. Đây là giải pháp kỹ thuật hướng đến khách hàng”, ông Dale Jewett, người phát ngôn của Stellantis, cho biết.\n\nĐại diện Mercedes-Benz USA cũng đưa ra quan điểm tương tự.\n\n“Với phương pháp đo mức dầu bằng kỹ thuật số, khách hàng có thể dễ dàng theo dõi lượng dầu của xe trên màn hình dành cho người lái và nhận cảnh báo kịp thời nếu mức dầu nằm ngoài giới hạn bình thường. Cách tiếp cận chủ động này giúp ngăn ngừa nguy cơ hư hỏng động cơ”, ông Andrew Brudnicki, đại diện Mercedes-Benz, cho biết.\n\nMột yếu tố quan trọng khác là không phải người dùng nào cũng biết cách đọc chính xác mức dầu qua que thăm.\n\nThay đổi thói quen của người dùng\n\nTrên một số que thăm dầu có các vạch đánh dấu nhỏ, trong khi một số khác có phần uốn cong tích hợp trên thân que. Một số loại khác được in các ký hiệu như “Min” (tối thiểu) và “Max” (tối đa) bằng cỡ chữ rất nhỏ. Ngoài ra, có loại sử dụng đầu nhựa với các vạch giới hạn để giúp người dùng xác định mức dầu khi cần bổ sung.\n\nTrong trường hợp cần châm thêm dầu, chủ xe có thể gặp khó khăn khi xác định lượng dầu cần bổ sung, đặc biệt nếu chưa quen với quy trình này. Cả việc châm thiếu dầu lẫn đổ quá nhiều dầu đều có thể gây ra hậu quả nghiêm trọng.\n\nCũng theo đại diện Mercedes-Benz, việc sử dụng thiết bị đo kỹ thuật số giúp quá trình kiểm tra mức dầu chính xác hơn, không phụ thuộc vào kinh nghiệm của người dùng.\n\n“Phép đo kỹ thuật số loại bỏ nguy cơ sai sót do con người và những yếu tố bên ngoài có thể dẫn đến việc đọc sai mức dầu. Chẳng hạn, xe không đỗ trên bề mặt bằng phẳng, sự khác biệt giữa phép đo khi động cơ nguội và nóng, hoặc góc quan sát que thăm dầu”, đại diện hãng giải thích.\n\nÔng Michael Crossen, trưởng nhóm dự án thử nghiệm tại Consumer Reports, đưa ra thêm một tình huống có thể xảy ra.\n\n“Cũng có trường hợp khách hàng kiểm tra dầu bằng que thăm và nhận thấy mức dầu hơi thấp. Họ muốn bổ sung thêm dầu. Tuy nhiên, khách hàng có thể đổ quá nhiều, điều này không tốt. Bên cạnh đó, nhiều mẫu xe yêu cầu sử dụng loại dầu có thông số rất cụ thể. Các nhà sản xuất không muốn người dùng tùy tiện đổ bất kỳ loại dầu nào có sẵn trong nhà vào động cơ”, ông nói.\n\nHãng xe không muốn người dùng tự kiểm tra dưới nắp ca-pô\n\n“Các nhà sản xuất thực sự không còn muốn người lái xe, tức khách hàng của họ, phải mở nắp ca-pô để tự kiểm tra như trước. Nhiều mẫu ô tô hiện nay là xe hybrid, sử dụng hệ thống điện áp cao, nên nguy cơ mất an toàn cũng lớn hơn”, ông Michael Crossen nhận định.\n\nCó thể hiểu được lý do đằng sau xu hướng này. Như đã đề cập, người không có chuyên môn rất dễ sử dụng nhầm loại dầu cho hộp số hoặc động cơ, hoặc châm dầu vượt mức quy định. Những sai sót này đều có thể gây phiền phức cho chủ xe và ảnh hưởng đến độ bền của động cơ.\n\nVới những động cơ hiện đại có kết cấu phức tạp và yêu cầu vận hành khắt khe hơn, các hãng xe có lẽ cũng muốn hạn chế nguy cơ xảy ra những hư hỏng nghiêm trọng.\n\nNgoài ra, các nhà sản xuất ô tô có thể giảm chi phí sản xuất bằng cách loại bỏ những chi tiết không còn được xem là cần thiết. Nếu xe đã có màn hình kỹ thuật số tích hợp các chức năng kiểm tra động cơ, việc bổ sung thông tin về mức dầu lên màn hình cũng là một lựa chọn, thay vì tiếp tục trang bị que thăm dầu truyền thống.","author":"Nhật Minh","category":"Xe ++","publishedAt":"2026-10-20 23:51","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/ly-do-que-tham-dau-dan-bien-mat-tren-o-to-hien-dai-20261020235132179.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/Ndc6DXPEU8wOfFqUsXtetf7I0BM=/zoom/1200_630/2026/10/20/que-than-daublkstudioshutterstock-cropped-1792468526231.jpg","crawledAt":"2026-10-21T13:43:30.119Z"},{"id":"dtri-20261020232342789","title":"Trái phiếu bất động sản: Áp lực đáo hạn lớn, lãi suất cao","slug":"trai-phieu-bat-dong-san-ap-luc-dao-han-lon-lai-suat-cao","excerpt":"Trong quý IV, nhóm bất động sản tiếp tục là khu vực chịu áp lực lớn nhất với giá trị đáo hạn trái phiếu khoảng 46,9 nghìn tỷ đồng, tương đương gần một nửa tổng giá trị đáo hạn toàn thị trường.","content":"(Dân trí) - Trong quý IV, nhóm bất động sản tiếp tục là khu vực chịu áp lực lớn nhất với giá trị đáo hạn trái phiếu khoảng 46,9 nghìn tỷ đồng, tương đương gần một nửa tổng giá trị đáo hạn toàn thị trường.\n\nBáo cáo thị trường trái phiếu doanh nghiệp quý III của S&I Rating vừa công bố cho thấy, bức tranh phát hành trái phiếu tăng chậm lại trong môi trường lãi suất cao.\n\nTheo đó, trong quý III, thị trường trái phiếu doanh nghiệp ghi nhận 153 đợt phát hành thành công với tổng giá trị phát hành đạt 179,4 nghìn tỷ đồng, giảm mạnh 26% so với quý trước.\n\nDù thị trường chung chậm lại, kênh phát hành ra công chúng lại ghi nhận kết quả ấn tượng với 16 đợt thành công trong quý III, tương đương tổng giá trị 31,6 nghìn tỷ đồng, tăng 55% so với cùng kỳ năm trước, là mức cao nhất ghi nhận được từ trước đến nay. Các ngân hàng thương mại vẫn là những chủ thể phát hành có lợi thế lớn và chiếm tỷ trọng lớn nhất ở hình thức này, với 8/16 đợt phát hành được thực hiện.\n\nMột số ngân hàng đã phát hành trái phiếu ra công chúng huy động hàng ngàn tỷ đồng, tiêu biểu như Agribank phát hành thành công 15 nghìn tỷ đồng. Các tổ chức phát hành phi ngân hàng cũng tham gia nhiều hơn vào kênh công chúng, với 8 đợt phát hành của các công ty chứng khoán ACBS, TCBS; công ty tài chính như F88; doanh nghiệp tiêu dùng như Masan Meatlife, Thuận Đức… Tuy nhiên, quy mô phát hành của các đơn vị này khá nhỏ, phần lớn dưới 1.000 tỷ đồng.\n\nLũy kế 9 tháng đầu năm, đã có 464,1 nghìn tỷ trái phiếu được phát hành. Trong khi đó, giá trị trái phiếu đáo hạn và mua lại trước hạn là 132,8 nghìn tỷ và 228,6 nghìn tỷ.\n\nTheo các chuyên gia của S&I Rating, so với tốc độ tăng trưởng GDP là 9,01% trong 9 tháng đầu năm và tăng trưởng tín dụng là 11,59%, thị trường trái phiếu doanh nghiệp tăng trưởng tương đối chậm trong năm nay. Nhu cầu tín dụng cao đã đẩy mặt bằng lãi suất tăng mạnh, tác động đáng kể tới chi phí vốn của các doanh nghiệp.\n\nMột diễn biến đáng chú ý trong quý III vừa qua là lãi suất trái phiếu doanh nghiệp đang tiệm cận mức đỉnh giai đoạn 2022-2023. Lãi suất phát hành có xu hướng tăng tiếp diễn ở tất cả nhóm ngành, như nhóm ngân hàng đạt 8,85%/năm - chính thức vượt đỉnh năm 2022 (trung bình là 8,7%/năm, cao nhất là 9,7%/năm). Một số lô trái phiếu của vài ngân hàng vượt 10% như Sacombank (lãi suất cố định 10%/năm) và PVcomBank (bình quân lãi suất tiết kiệm cá nhân 12 tháng + 4,6%/năm, hiện tương đương khoảng 10,4%/năm).\n\nLãi suất trái phiếu của các nhóm bất động sản và nhóm doanh nghiệp khác cũng đã tăng rất mạnh lên tới 12,5% - 13%/năm nhưng chưa bằng mức đỉnh giai đoạn trước (14%-14,5%/năm).\n\nNhận định về triển vọng thị trường này cuối năm nay và năm 2027, các chuyên gia cho rằng áp lực đáo hạn gia tăng trong bối cảnh chi phí vốn duy trì cao.\n\nCụ thể, bước sang quý IV, áp lực đáo hạn trái phiếu doanh nghiệp sẽ gia tăng đáng kể khi tổng giá trị trái phiếu đến hạn thanh toán ước khoảng 93 nghìn tỷ đồng, mức cao nhất trong năm. Trong đó, nhóm bất động sản tiếp tục là khu vực chịu áp lực lớn nhất với giá trị đáo hạn khoảng 46,9 nghìn tỷ đồng, tương đương gần một nửa tổng giá trị đáo hạn toàn thị trường.\n\nTheo S&I Ratings, hoạt động phát hành mới trong thời gian tới không chỉ nhằm đáp ứng nhu cầu huy động vốn cho các dự án mới mà còn đóng vai trò quan trọng trong việc cơ cấu lại các khoản nợ hiện hữu.\n\nNhu cầu vốn trung và dài hạn của nền kinh tế đang bước vào chu kỳ tăng mạnh để phục vụ hàng loạt đại dự án bất động sản, khu đô thị, hạ tầng giao thông, năng lượng và công nghiệp. Trong bối cảnh đó, trái phiếu doanh nghiệp tiếp tục được kỳ vọng là kênh huy động vốn quan trọng giúp bổ sung nguồn lực trung và dài hạn cho nền kinh tế.\n\nTuy nhiên, khả năng hấp thụ vốn của thị trường có thể chịu ảnh hưởng bởi bối cảnh lãi suất toàn cầu và trong nước duy trì ở mặt bằng cao. Kỳ vọng lạm phát còn tiềm ẩn nhiều rủi ro cùng xu hướng lợi suất trái phiếu chính phủ quốc tế neo ở mức cao có thể khiến mặt bằng lãi suất duy trì ở mức cao ít nhất trong nửa đầu năm 2027. Đối với doanh nghiệp phát hành, điều này đồng nghĩa với chi phí vốn gia tăng, đặc biệt đối với các doanh nghiệp có hệ số đòn bẩy cao hoặc nhu cầu huy động vốn lớn.","author":"Lam Giang","category":"Bất động sản","publishedAt":"2026-10-20 23:23","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/trai-phieu-bat-dong-san-ap-luc-dao-han-lon-lai-suat-cao-20261020232342789.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/wg1vjHnBmR7saCft4BPHl84DDOQ=/zoom/1200_630/2023/03/04/ngan-hangbanktien-matcash10-crop-crop-crop-1677904268831.jpeg","crawledAt":"2026-10-21T13:43:00.354Z"},{"id":"dtri-20261020230606907","title":"Cầm bằng giỏi, xuất sắc vẫn rớt tuyển dụng: Doanh nghiệp \"chê\" điều gì?","slug":"cam-bang-gioi-xuat-sac-van-rot-tuyen-dung-doanh-nghiep-che-dieu-gi","excerpt":"Khi bằng giỏi, xuất sắc ngày càng phổ biến, danh hiệu loại ưu không còn là “kim bài” tuyển dụng. Khảo sát cho thấy tân cử nhân chỉ đạt 1/7 năng lực cốt lõi mà doanh nghiệp yêu cầu.","content":"Kỳ 1: Thủ khoa, sinh viên tốt nghiệp xuất sắc cũng… chật vật tìm việc\n\nKỳ 2: Giảng viên ngại cho điểm kém vì sợ bị \"bóc phốt\", liệt vào danh sách đen\n\nSau câu chuyện nhiều sinh viên tốt nghiệp loại giỏi, xuất sắc vẫn chật vật tìm việc và những băn khoăn về cách chấm điểm ở giảng đường, câu hỏi đặt ra là tấm bằng đại học đang phản ánh đến đâu năng lực của người học.\n\nKhảo sát gần 400 doanh nghiệp tại Hà Nội và TPHCM cho thấy tân cử nhân mới chỉ đáp ứng 1/7 năng lực mà nhà tuyển dụng yêu cầu.\n\nBáo động từ con số: Cử nhân chỉ đáp ứng 1/7 năng lực cốt lõi\n\nCon số đáng chú ý này đến từ Báo cáo Nâng tầm nhân lực Việt Nam 2026 do Đại học Anh Quốc Việt Nam (BUV) và Decision Lab công bố tại Hội nghị Quốc tế về Hợp tác Giáo dục do Bộ GD&ĐT tổ chức cách đây 2 tuần.\n\nKhảo sát được thực hiện trên 375 doanh nghiệp trong và ngoài nước tại Hà Nội và TPHCM; thuộc 6 nhóm ngành trọng điểm: Công nghệ và kinh tế số, Kinh doanh và tiếp thị, Hậu cần và chuỗi cung ứng, Khách sạn và du lịch, Sản xuất và công nghiệp 4.0, Tài chính và ngân hàng.\n\nTrong số 7 năng lực cốt lõi được đánh giá - bao gồm quản lý thời gian, giải quyết vấn đề, giao tiếp, tính thích ứng, tư duy phản biện, làm việc nhóm và năng lực số - tân cử nhân chỉ đáp ứng được duy nhất 1 năng lực.\n\nNói về thực trạng này, GS. Rick Bennett, Phó Hiệu trưởng kiêm Phó Chủ tịch BUV, thừa nhận việc rất nhiều sinh viên cầm bằng giỏi nhưng không đáp ứng được yêu cầu tuyển dụng đang trở thành niềm trăn trở lớn.\n\nVới kết quả khảo sát cho thấy người mới ra trường chỉ đáp ứng vỏn vẹn 1/7 tiêu chí đòi hỏi người trẻ phải rèn luyện rất nhiều kỹ năng mềm bên cạnh tấm bằng đại học, nhất là trong bối cảnh công nghệ đang thay đổi công việc với tốc độ chóng mặt, GS. Rick Bennett chia sẻ.\n\nĐiểm sáng duy nhất giúp tân cử nhân vượt kỳ vọng của doanh nghiệp 3% chính là năng lực số. Thế nhưng, điểm tựa này cũng không hề an toàn khi có tới 94% nhà tuyển dụng khẳng định họ đã nâng cao tiêu chuẩn về kỹ năng số và AI so với 2-3 năm trước.\n\nỞ cả 6 nhóm năng lực còn lại, sinh viên hoàn toàn hụt hơi trước yêu cầu của thị trường lao động.\n\nKỹ năng quản lý thời gian hiện là \"lỗ hổng\" lớn nhất của tân cử nhân khi chỉ đạt 54% hiệu suất thực tế, trong khi có tới 80% nhà tuyển dụng đánh giá đây là yếu tố cốt lõi.\n\nTương tự, ở năng lực giải quyết vấn đề, doanh nghiệp đặt mức độ quan trọng tới 84% nhưng người mới tốt nghiệp chỉ đáp ứng được 61%.\n\nVới kỹ năng giao tiếp, khoảng chênh lệch thu hẹp hơn nhưng vẫn hiện hữu (84% thị trường đòi hỏi so với 72% khả năng đáp ứng).\n\nSự chênh lệch trên cho thấy giá trị của tân cử nhân không dừng ở những gì họ biết, mà ở mức độ vận dụng kiến thức đó nơi công sở. Nhà tuyển dụng hiện nay cần cả nền tảng chuyên môn lẫn kỹ năng mềm.\n\nKhi “lạm phát” bằng giỏi, xuất sắc… điểm số không tạo ra sự khác biệt\n\nTrong bức tranh đó, bằng cấp, chứng chỉ hay kỳ thực tập chỉ đóng vai trò là thông tin nhận diện ban đầu, còn hiệu suất công việc và năng lực thể hiện mới là câu trả lời cuối cùng.\n\nBà Ngô Thị Ngọc Lan, Giám đốc điều hành Công ty tuyển dụng Navigos, nhận định các doanh nghiệp hiện nay đã thay đổi hoàn toàn tư duy tuyển dụng, không còn đặt nặng vấn đề bằng cấp hay chuyên môn quá sâu - tất nhiên có thì càng tốt.\n\nĐiều họ thực sự tìm kiếm ở một nhân sự mới ra trường là thái độ: liệu bạn có đủ bền bỉ để vượt qua thử thách hay sẽ “ba bữa nhảy việc” và bạn có năng lực tự định hình, quản lý tốt thời gian cùng công việc của mình hay không.\n\nĐồng quan điểm, ông Trần Anh Tuấn, chuyên gia dự báo nhân lực, Phó Chủ tịch Hội Giáo dục nghề nghiệp TPHCM, cho rằng cần phân biệt thành tích học tập với năng lực nghề nghiệp.\n\nTheo ông, bằng tốt nghiệp loại giỏi, xuất sắc là kết quả đáng ghi nhận, có thể phản ánh khả năng tiếp thu kiến thức, tính kỷ luật và nỗ lực của sinh viên. Tuy nhiên, đây chưa phải căn cứ đầy đủ để khẳng định một người đã sẵn sàng đáp ứng tốt yêu cầu công việc.\n\nTrong trường đại học, sinh viên thường được đánh giá qua các học phần, bài thi, bài tập và đồ án. Môi trường doanh nghiệp lại đòi hỏi hệ năng lực rộng hơn, trong đó có khả năng vận dụng kiến thức để giải quyết vấn đề, tư duy phản biện, giao tiếp, làm việc nhóm, quản lý thời gian và chịu trách nhiệm với kết quả.\n\nMột sinh viên có thể đạt điểm cao ở các môn chuyên ngành nhưng lúng túng khi gặp tình huống chưa có đáp án mẫu, phải tự xác định vấn đề, tìm kiếm thông tin và đề xuất phương án. Ngược lại, người có điểm số không nổi trội bằng nhưng từng tham gia dự án thực tế, biết phân tích tình huống và phối hợp với đồng nghiệp có thể thích nghi với công việc nhanh hơn.\n\n“Doanh nghiệp cần đánh giá ứng viên trên cả ba phương diện: biết gì, làm được gì và có khả năng phát triển đến đâu”, ông Tuấn nhận định.\n\nTheo ông Tuấn, điều đó không có nghĩa bằng giỏi, xuất sắc mất hoàn toàn giá trị. Với sinh viên mới tốt nghiệp, chưa có nhiều kinh nghiệm, thành tích học tập vẫn là tín hiệu ban đầu về khả năng tiếp thu kiến thức, sự kiên trì và tính kỷ luật. Ở một số vị trí đòi hỏi nền tảng học thuật vững chắc, kết quả học tập còn là tiêu chí sàng lọc quan trọng.\n\nTuy nhiên, khi nhiều ứng viên cùng sở hữu hồ sơ học tập tốt, điểm số khó tạo ra khác biệt đủ lớn để quyết định toàn bộ kết quả tuyển dụng. Khi ấy, nhà tuyển dụng cần những căn cứ khác để xác định ai thực sự phù hợp với công việc.\n\nTheo ông Tuấn, khả năng tìm việc còn phụ thuộc vào ngành học, nhu cầu tuyển dụng, khu vực địa lý, mức lương kỳ vọng, kinh nghiệm thực tế và mức độ phù hợp giữa năng lực ứng viên với vị trí công việc.\n\n“Vấn đề cần xem xét là liệu những gì sinh viên được học và được đánh giá trong nhà trường đã tương thích với yêu cầu thực tế của doanh nghiệp hay chưa”, Phó Chủ tịch Hội Giáo dục nghề nghiệp TPHCM bày tỏ.\n\nÔng dẫn chứng, nếu chương trình đào tạo thiên về truyền đạt kiến thức, trong khi cơ hội thực hành, làm dự án, thực tập và tiếp xúc với doanh nghiệp chưa đủ sâu, sinh viên có thể tốt nghiệp với nền tảng lý thuyết tương đối tốt nhưng ít kinh nghiệm xử lý công việc.\n\nTương tự, nếu việc đánh giá chủ yếu dựa vào khả năng ghi nhớ, tái hiện kiến thức hoặc hoàn thành nhiệm vụ có cấu trúc rõ ràng, kết quả học tập có thể chưa phản ánh đầy đủ năng lực tư duy độc lập và vận dụng kiến thức.\n\nMặt khác, ông Tuấn chỉ ra doanh nghiệp cũng cần nhìn lại yêu cầu tuyển dụng. Một số vị trí được mô tả dành cho người chưa có kinh nghiệm nhưng lại đòi hỏi ứng viên có thể làm việc độc lập, sử dụng thành thạo nhiều công cụ và tạo ra kết quả ngay từ đầu. Nếu chỉ tìm kiếm người đã thành thạo công việc mà không đầu tư đào tạo ban đầu, khoảng cách giữa nhà trường và thị trường lao động khó được thu hẹp.\n\nSinh viên tại TPHCM trong một Ngày hội việc làm (Ảnh: Huyên Nguyễn).\n\nTheo TS Nguyễn Thị Thu Anh, thành viên Hội đồng Quốc gia Giáo dục và Phát triển nhân lực, nguyên Hiệu trưởng Trường THCS và THPT Nguyễn Tất Thành, các trường đại học cần chủ động kết nối với doanh nghiệp, mời doanh nghiệp tham gia vào hoạt động dạy học, đóng góp vào quá trình xây dựng chương trình và đánh giá người học.\n\nĐổi lại, sinh viên phải thể hiện kiến thức học thuật, tính chuyên nghiệp và tinh thần trách nhiệm để những mối quan hệ hợp tác này có thể duy trì bền vững, bà Thu Anh bày tỏ.\n\nTheo các chuyên gia, giá trị của giáo dục đại học không chỉ nằm ở số lượng sinh viên tốt nghiệp với điểm số cao, mà còn ở việc người học có thể vận dụng những gì đã học để giải quyết vấn đề, thích nghi với thay đổi và tạo ra giá trị trong công việc hay không.\n\nĐó cũng là thước đo để phân biệt một thành tích học tập đáng ghi nhận với năng lực nghề nghiệp được chứng minh trong thực tế.\n\nThay đổi kiểm tra, đánh giá trước “bão” AI\n\nĐể tấm bằng đại học phản ánh sát hơn năng lực thực tế và hạn chế tình trạng sinh viên mượn AI làm hộ bài tập, TS Trần Thế Vinh, Phụ trách ngành Khoa học dữ liệu, Trường Đại học Giao thông vận tải TPHCM, đề xuất giải pháp kiểm tra thực chất hơn.\n\nTheo ông, khi sinh viên nộp bài hay đồ án, giảng viên nên kết hợp đánh giá sản phẩm với vấn đáp ngắn. Chỉ cần 1-2 câu hỏi phỏng vấn trực tiếp, người dạy sẽ nhận biết ngay sinh viên có thực sự hiểu bản chất quy trình hay chỉ phụ thuộc vào công cụ AI.","author":"Huyên Nguyễn","category":"Giáo dục","publishedAt":"2026-10-20 23:06","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/cam-bang-gioi-xuat-sac-van-rot-tuyen-dung-doanh-nghiep-che-dieu-gi-20261020230606907.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/3Zy_lmO-jAIYDqUglKGQ0_tPBcQ=/zoom/1200_630/2026/10/19/bang-tot-nghiep-cropped-1792424067503.jpg","crawledAt":"2026-10-21T13:43:25.590Z"},{"id":"dtri-20261020224401134","title":"Vụ nam sinh lao lên bục giảng đánh cô giáo, nhà trường báo cáo gì?","slug":"vu-nam-sinh-lao-len-buc-giang-danh-co-giao-nha-truong-bao-cao-gi","excerpt":"Theo báo cáo của nhà trường, nam sinh lớp 12 đã có hành vi bạo lực với cô giáo chủ nhiệm trong giờ chữa bài kiểm tra.","content":"(Dân trí) - Theo báo cáo của nhà trường, nam sinh lớp 12 đã có hành vi bạo lực với cô giáo chủ nhiệm trong giờ chữa bài kiểm tra.\n\nLiên quan đến vụ học sinh lao lên bục giảng đánh vào đầu cô giáo, Sở GD&ĐT đã có đoàn làm việc với nhà trường vào sáng nay, 21/10.\n\nTheo báo cáo ban đầu của nhà trường, sáng 19/10, trong giờ chữa bài kiểm tra, một nam học sinh lớp 12 đã có hành vi bạo lực đối với giáo viên chủ nhiệm.\n\nNhà trường đã kịp thời can thiệp, đưa giáo viên đến cơ sở y tế thăm khám, đồng thời phối hợp với gia đình học sinh và cơ quan công an giải quyết vụ việc.\n\nSức khỏe và tinh thần của giáo viên đã ổn định; giáo viên đang nghỉ ngơi, tiếp tục được theo dõi, điều trị theo hướng dẫn của cơ sở y tế.\n\n\"Sở GD&ĐT Hà Nội tiếp tục theo dõi, chỉ đạo nhà trường phối hợp với cơ quan công an trong quá trình giải quyết với quan điểm đảm bảo tính giáo dục, sự nghiêm minh và an toàn trường học\", theo đại diện Sở GD&ĐT Hà Nội.\n\nĐược biết sau khi xảy ra vụ việc, Ban Giám hiệu nhà trường đã trực tiếp thăm hỏi, động viên giáo viên; tổ chức họp Hội đồng trường, trao đổi với đội ngũ giáo viên, học sinh và cha mẹ học sinh để ổn định tâm lý, duy trì hoạt động dạy học.\n\nNhà trường đã cung cấp thông tin, tài liệu phục vụ công tác xác minh của cơ quan công an. Gia đình học sinh đã phối hợp với nhà trường và có mặt khi cơ quan công an làm việc với học sinh.\n\nSở GD&ĐT yêu cầu nhà trường tiếp tục hỗ trợ giáo viên trong quá trình điều trị, phục hồi sức khỏe và ổn định tâm lý.\n\nCơ quan này yêu cầu Trường THPT Mạc Đĩnh Chi rà soát, tăng cường các biện pháp bảo đảm an toàn trường học, phòng ngừa bạo lực học đường; nâng cao hiệu quả công tác tư vấn tâm lý, giáo dục kỹ năng ứng xử cho học sinh; phối hợp thường xuyên với cha mẹ học sinh để kịp thời nắm bắt những khó khăn, diễn biến tâm lý, xử lý các nguy cơ, phòng ngừa bạo lực học đường.\n\nSáng 21/10, một lãnh đạo Công an TP Hà Nội xác nhận cơ quan công an đã bắt khẩn cấp nam sinh có hành vi bạo lực với cô giáo.\n\nTrước đó, một đoạn video ngắn ghi lại cảnh cô giáo đang giảng bài trên bục giảng, xung quanh có nhiều học sinh. Đột nhiên một nam sinh từ phía sau lao lên đánh vào đầu cô giáo. Khi cả lớp la ó và lao vào can ngăn, nam sinh ngừng tay.\n\nTuy nhiên, khi cô giáo chạy thoát thân ra phía bàn giáo viên, nam sinh tiếp tục lao lên để đánh tiếp lần nữa.\n\nSự việc được cho xảy ra lúc 11h trưa 19/10, tại Trường THPT Mạc Đĩnh Chi, xã Kim Anh, Hà Nội.\n\nNgay khi sự việc xảy ra, nhà trường đã báo cáo đến cơ quan công an, phối hợp xác minh để làm rõ.","author":"Mỹ Hà","category":"Giáo dục","publishedAt":"2026-10-20 22:44","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/vu-nam-sinh-lao-len-buc-giang-danh-co-giao-nha-truong-bao-cao-gi-20261020224401134.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/vU6QiErkwLefy8unotLk5LuDrAQ=/zoom/1200_630/2026/10/21/anh-man-hinh-2026-10-20-luc-21-cropped-cropped-1792563157017.jpg","crawledAt":"2026-10-21T13:43:24.460Z"},{"id":"dtri-20261020224133105","title":"Hoàng Thùy Linh tuổi 38: Nhan sắc trẻ trung, ảnh chụp với Đen Vâu gây chú ý","slug":"hoang-thuy-linh-tuoi-38-nhan-sac-tre-trung-anh-chup-voi-den-vau-gay-chu-y","excerpt":"Ở tuổi 38, Hoàng Thùy Linh trở lại với âm nhạc sau 2 năm vắng bóng. Thời gian qua, cô vẫn duy trì lịch trình biểu diễn nhưng kín tiếng chuyện đời tư.","content":"Gần đây, Hoàng Thùy Linh thu hút sự chú ý khi trở lại đường đua âm nhạc với MV Thầy Dùi, sau 2 năm yên ắng kể từ MV Miền đất hứa kết hợp cùng rapper Đen Vâu phát hành năm 2023.\n\nTheo chia sẻ của nữ ca sĩ, đây là sản phẩm được đầu tư kỳ công nhất trong sự nghiệp của cô tính đến hiện tại, với 315 người đã tham gia quá trình ghi hình, với quy mô dàn dựng được xây dựng như một bộ phim điện ảnh.\n\nSản phẩm mới tiếp tục mang màu sắc âm nhạc và hình ảnh quen thuộc của Hoàng Thùy Linh, với sự kết hợp giữa âm nhạc và các yếu tố văn hóa. Dù được đầu tư về quy mô, MV chưa tạo được sức lan tỏa nổi bật như một số sản phẩm trước đây của nữ ca sĩ. Sau 5 ngày phát hành, sản phẩm mới cán mốc 1 triệu lượt xem.\n\nThời gian qua, Hoàng Thùy Linh khá yên ắng trên mạng xã hội. Cô chỉ chia sẻ thông tin liên quan đến công việc. Nữ ca sĩ biểu diễn tại nhiều sự kiện lớn ở TPHCM và các tỉnh, thành. Mỗi lần xuất hiện, cô chú trọng trang phục sân khấu, có ê-kíp hỗ trợ và chuẩn bị chỉn chu cho phần trình diễn. Sau chương trình, cô cũng có những khoảnh khắc gần gũi khi nán lại chụp ảnh cùng người hâm mộ.\n\nHoàng Thùy Linh cũng thường góp mặt tại các sự kiện thời trang của những thương hiệu xa xỉ. Mỗi lần xuất hiện, nữ ca sĩ đều chăm chút diện mạo từ trang phục, kiểu tóc đến lối trang điểm, tôn lên vẻ sang trọng và sắc vóc nổi bật. Dù đứng chung khung hình với nhiều mỹ nhân, cô vẫn thu hút sự chú ý nhờ thần thái tự tin và phong cách riêng.\n\nTrong dịp sinh nhật tuổi 38, Hoàng Thùy Linh chia sẻ những suy ngẫm về hành trình đã qua: “Ngày sinh nhật hàng năm là để nhắc tôi rằng có bao nhiêu bài học đã qua và bao nhiêu điều hạnh phúc đang có, chặng đường này không hề dễ dàng nhưng những điều ở lại luôn tràn đầy yêu thương, bao dung, lòng tốt và sự biết ơn”.\n\nTrên mạng xã hội, Hoàng Thùy Linh thỉnh thoảng chia sẻ hình ảnh đời thường, thu hút sự chú ý nhờ nhan sắc trẻ trung và vóc dáng quyến rũ ở tuổi 38.\n\nTrong một bộ ảnh, nữ ca sĩ diện chân váy lụa hồng kết hợp áo cardigan cùng tông. Lối trang điểm nhẹ nhàng, mái tóc buông tự nhiên giúp cô tôn lên vẻ nữ tính, mềm mại. Ở những khoảnh khắc dạo phố, uống cà phê, cô cũng ghi điểm với phong cách thời trang đa dạng, trẻ trung.\n\nDù được công chúng quan tâm, Hoàng Thùy Linh hiếm khi chia sẻ cụ thể về đời tư. Trong khoảng 2 năm qua, mối quan hệ giữa cô và rapper Đen Vâu luôn trở thành chủ đề được bàn luận. Cả hai vướng tin đồn đã tổ chức lễ ăn hỏi và có con, nhưng chưa lên tiếng xác nhận hay phủ nhận những thông tin này.\n\nTrong một lần chia sẻ với truyền thông, Hoàng Thùy Linh cho biết bản thân đang hạnh phúc, trân trọng cuộc sống và những người luôn yêu thương mình, thay vì trực tiếp đề cập đến các đồn đoán.\n\nSau nhiều dự án âm nhạc hợp tác chung, Hoàng Thùy Linh và Đen Vâu vẫn giữ sự thoải mái khi đứng chung sân khấu hoặc góp mặt tại các sự kiện, chương trình.\n\nTại sự kiện kỷ niệm 70 năm Ngày truyền thống Hội Liên hiệp Thanh niên Việt Nam (15/10/1956-15/10/2026) mới đây, Hoàng Thùy Linh chia sẻ ảnh chụp cùng Đen Vâu. Khoảnh khắc chung khung hình của cả hai thu hút sự chú ý, nhận được nhiều lời khen từ khán giả.\n\nTrước đó, hồi tháng 8, hai nghệ sĩ cùng biểu diễn tại một đêm nhạc ở Hà Nội. Không chỉ hát chung, họ còn có những màn tương tác như nắm tay trên sân khấu giữa trời mưa. Chia sẻ hình ảnh đứng chung sân khấu với Đen Vâu, Hoàng Thùy Linh gửi lời cảm ơn nam rapper vì lần đầu cùng cô mang ca khúc Miền đất hứa trình diễn để dành tặng khán giả Hà Nội.","author":"Quỳnh Tâm","category":"Giải trí","publishedAt":"2026-10-20 22:41","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/hoang-thuy-linh-tuoi-38-nhan-sac-tre-trung-anh-chup-voi-den-vau-gay-chu-y-20261020224133105.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/vukO6_4_2HRc3-PLCxH-KQRUarU=/zoom/1200_630/2026/10/20/hoangthuylinh20-cropped-cropped-1792510246161.jpg","crawledAt":"2026-10-21T13:43:09.429Z"},{"id":"dtri-20261020223326638","title":"Hà Nội: Xác minh thông tin học sinh lao lên bục giảng đánh cô giáo","slug":"ha-noi-xac-minh-thong-tin-hoc-sinh-lao-len-buc-giang-danh-co-giao","excerpt":"Một video ngắn ghi lại cảnh học sinh lao lên bục giảng đánh cô giáo đang lan truyền trên mạng xã hội khiến nhiều người bức xúc.","content":"(Dân trí) - Một video ngắn ghi lại cảnh học sinh lao lên bục giảng đánh cô giáo đang lan truyền trên mạng xã hội khiến nhiều người bức xúc.\n\nTheo đoạn video ngắn ghi lại, cô giáo đang giảng bài trên bục giảng, xung quanh có nhiều học sinh. Tuy vậy, đột nhiên một nam sinh từ phía sau lao lên đánh vào đầu cô giáo. Khi cả lớp la ó và lao vào can ngăn, nam sinh ngừng tay.\n\nTuy nhiên, khi cô giáo chạy thoát thân ra phía bàn giáo viên, nam sinh tiếp tục lao lên lần nữa để đánh.\n\nSự việc được cho xảy ra trong giờ học môn toán ngày 19/10 tại Trường THPT Mạc Đĩnh Chi, xã Kim Anh, Hà Nội.\n\nTrả lời nhanh phóng viên Dân trí, lãnh đạo nhà trường cho biết, đã nắm được thông tin phản ánh.\n\nNgay sau khi sự việc xảy ra, nhà trường đã làm việc trực tiếp với cơ quan công an để phối hợp giải quyết vụ việc, đồng thời báo cáo về Sở GD&ĐT Hà Nội.\n\n\"Hiện sức khỏe, tinh thần cô giáo đã ổn định và đang nghỉ ngơi tại nhà. Các nội dung liên quan đang được cơ quan an ninh xác minh, làm rõ và chờ kết luận của cơ quan chức năng\", theo đại diện nhà trường.\n\nTrả lời phóng viên Dân trí, Giám đốc Sở GD&ĐT Hà Nội, cho biết đã nắm được thông tin và sẽ có văn bản chỉ đạo!\n\nChúng tôi sẽ tiếp tục theo dõi sự việc!","author":"Mỹ Hà","category":"Giáo dục","publishedAt":"2026-10-20 22:33","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/ha-noi-xac-minh-thong-tin-hoc-sinh-lao-len-buc-giang-danh-co-giao-20261020223326638.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/M0Xx-cL_yguC6BFcNZb-CxX7uL4=/zoom/1200_630/2026/10/20/anh-man-hinh-2026-10-20-luc-21-cropped-1792509980080.jpg","crawledAt":"2026-10-21T13:43:25.572Z"},{"id":"dtri-20261020221051491","title":"Doanh số bán nhà tại Mỹ giảm mạnh trong tháng 9, xuống mức thấp kỷ lục","slug":"doanh-so-ban-nha-tai-my-giam-manh-trong-thang-9-xuong-muc-thap-ky-luc","excerpt":"Doanh số bán nhà đã qua sử dụng chờ hoàn tất giao dịch tại Mỹ đã rơi xuống mức thấp kỷ lục trong tháng 9, khi lãi suất thế chấp cao tiếp tục đè nặng lên nhu cầu mua nhà.","content":"(Dân trí) - Doanh số bán nhà đã qua sử dụng chờ hoàn tất giao dịch tại Mỹ đã rơi xuống mức thấp kỷ lục trong tháng 9, khi lãi suất thế chấp cao tiếp tục đè nặng lên nhu cầu mua nhà.\n\nTheo số liệu công bố hôm thứ ba (20/10), chỉ số hợp đồng ký kết của Hiệp hội Môi giới Bất động sản Quốc gia (NAR) giảm 7,3% xuống còn 66 điểm trong tháng trước - mức thấp nhất kể từ khi số liệu bắt đầu được ghi nhận vào năm 2001. Mức giảm này sâu hơn mọi dự báo của các nhà kinh tế trong khảo sát của Bloomberg.\n\nCon số ảm đạm này là báo cáo mới nhất trong loạt dữ liệu cho thấy thị trường nhà ở Mỹ vẫn đang bế tắc do chi phí vay vốn và giá nhà ở mức cao. Lãi suất thế chấp đã liên tục tăng kể từ khi bùng phát xung đột Trung Đông và hiện ở mức cao nhất trong gần ba năm qua.\n\nSố liệu chưa điều chỉnh theo yếu tố mùa vụ cho thấy, lượng hợp đồng ký kết đã giảm gần 13% so với cùng kỳ năm ngoái.\n\n“Điều kiện thị trường suy yếu trong tháng 9 do lãi suất thế chấp tăng nhanh”, ông Lawrence Yun, Kinh tế trưởng của NAR, cho biết trong một tuyên bố.\n\nTheo ông, \"có thể cả người mua lẫn người bán đều đang chờ đợi cho đến khi lãi suất thế chấp diễn biến thuận lợi hơn”.\n\nThông thường, hợp đồng được ký kết trước khi hoàn tất giao dịch từ một đến hai tháng, nên từ trước đến nay chỉ số này được xem là tín hiệu dự báo sớm cho doanh số bán nhà đã qua sử dụng.\n\nDoanh số bán nhà chờ hoàn tất sụt giảm ở tất cả khu vực của Mỹ. Miền Tây ghi nhận mức giảm sâu nhất là 9,2%, trong khi miền Nam - khu vực có lượng nhà bán ra lớn nhất - giảm 8,2%.\n\nMột số liệu khác cũng được công bố hôm thứ ba cho thấy hoạt động khởi công xây nhà mới đã chậm lại trong tháng trước, xuống một trong những mức yếu nhất kể từ năm 2020.","author":"Xuân Hoa","category":"Bất động sản","publishedAt":"2026-10-20 22:10","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/doanh-so-ban-nha-tai-my-giam-manh-trong-thang-9-xuong-muc-thap-ky-luc-20261020221051491.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/Z_I_jFTo45Zeed4NV4KCFhehftU=/zoom/1200_630/2026/10/20/ban-nha-cropped-1792508946109.jpg","crawledAt":"2026-10-21T13:43:01.431Z"},{"id":"dtri-20261020203720502","title":"Cúm có thể trở nặng, Bộ Y tế khuyến cáo 8 biện pháp phòng bệnh","slug":"cum-co-the-tro-nang-bo-y-te-khuyen-cao-8-bien-phap-phong-benh","excerpt":"Cúm mùa thường gây triệu chứng nhẹ nhưng có thể dẫn đến biến chứng nguy hiểm, nhất là ở người cao tuổi, trẻ nhỏ, phụ nữ mang thai và người mắc bệnh nền.","content":"(Dân trí) - Cúm mùa thường gây triệu chứng nhẹ nhưng có thể dẫn đến biến chứng nguy hiểm, nhất là ở người cao tuổi, trẻ nhỏ, phụ nữ mang thai và người mắc bệnh nền.\n\nTheo Bộ y tế, cúm mùa là bệnh truyền nhiễm cấp tính do virus cúm gây ra, lưu hành quanh năm tại Việt Nam. Số ca mắc có thể gia tăng vào một số thời điểm trong năm, tùy theo khu vực và điều kiện thời tiết, đặc biệt cần lưu ý trong thời điểm giao mùa và những tháng có thời tiết lạnh trong mùa thu - đông.\n\nBệnh lây truyền chủ yếu từ người sang người qua các hạt dịch tiết đường hô hấp chứa virus được phát tán khi người mắc bệnh ho, hắt hơi hoặc nói chuyện. Nguy cơ lây nhiễm tăng khi tiếp xúc gần với người mắc bệnh, tại những nơi tập trung đông người, như trường học, cơ sở y tế, phương tiện giao thông công cộng hoặc trong không gian kín, thông khí kém.\n\nPhần lớn người mắc cúm có biểu hiện nhẹ và tự hồi phục. Tuy nhiên, bệnh có thể diễn biến nặng, gây biến chứng, đặc biệt ở người có nguy cơ cao gồm người trên 65 tuổi, trẻ em dưới 5 tuổi, phụ nữ mang thai (đặc biệt trong 3 tháng cuối thai kỳ) hoặc phụ nữ mới sinh trong vòng 2 tuần, người có bệnh nền (như bệnh tim mạch, phổi mạn tính, suy thận, xơ gan, đái tháo đường...).\n\nĐể chủ động bảo vệ sức khỏe của bản thân, gia đình và cộng đồng, Cục Phòng bệnh, Bộ Y tế khuyến cáo người dân thực hiện các biện pháp sau:\n\n- Đeo khẩu trang đúng cách khi đến cơ sở y tế, trên phương tiện giao thông công cộng, tại nơi đông người hoặc trong không gian kín, thông khí kém.\n\n- Che miệng, mũi khi ho hoặc hắt hơi bằng khăn giấy dùng một lần hoặc khuỷu tay áo; bỏ khăn giấy đã sử dụng đúng nơi quy định và rửa tay ngay sau đó.\n\n- Giữ vệ sinh cá nhân; rửa tay thường xuyên bằng xà phòng và nước sạch hoặc dung dịch sát khuẩn tay; hạn chế đưa tay lên mắt, mũi, miệng.\n\n- Hạn chế tiếp xúc gần với người mắc hoặc nghi mắc bệnh đường hô hấp.\n\n- Duy trì lối sống lành mạnh, rèn luyện thân thể, ăn uống đủ chất, ngủ đủ giấc và thường xuyên giữ ấm cơ thể để nâng cao sức đề kháng.\n\n- Người có triệu chứng sốt, ho, đau họng, sổ mũi nên hạn chế tiếp xúc với người khác, nghỉ ngơi và theo dõi sức khỏe và cần đeo khẩu trang khi tiếp xúc với người khác. Không tự ý sử dụng thuốc kháng virus, thuốc kháng sinh khi chưa có chỉ định của nhân viên y tế.\n\n- Thường xuyên vệ sinh, làm sạch các bề mặt thường xuyên tiếp xúc; bảo đảm thông thoáng nơi ở, nơi làm việc, lớp học và tăng cường thông khí tại không gian kín.\n\n- Người thuộc nhóm có nguy cơ diễn biến nặng khi mắc cúm cần hạn chế đến nơi tập trung đông người để giảm nguy cơ lây nhiễm; khi có triệu chứng cần chủ động liên hệ hoặc đến cơ sở y tế để được tư vấn, khám và xử trí kịp thời.\n\nCục Phòng bệnh cho biết sẽ tiếp tục phối hợp chặt chẽ với các đơn vị liên quan theo dõi sát diễn biến bệnh cúm mùa; cập nhật thông tin kịp thời và triển khai các biện pháp phòng, chống phù hợp.\n\nBSCKII Phạm Công Khắc, Phó Giám đốc Trung tâm Nhi khoa, Bệnh viện Bạch Mai (Hà Nội), trẻ thường khởi phát bệnh cúm khá đột ngột với sốt, ho, đau họng, nghẹt hoặc chảy nước mũi, đau đầu, đau mỏi cơ và mệt nhiều. Trẻ nhỏ có thể biểu hiện không điển hình như quấy khóc, bú kém, nôn, tiêu chảy hoặc li bì.\n\nPhần lớn trẻ mắc cúm có thể hồi phục sau vài ngày đến khoảng một tuần nếu được chăm sóc và theo dõi phù hợp. Tuy nhiên, không nên vì vậy mà coi cúm mùa là một bệnh hoàn toàn lành tính.\n\nCúm có thể gây ra nhiều biến chứng như viêm tai giữa, viêm xoang, mất nước và làm nặng thêm bệnh hen phế quản hoặc các bệnh mạn tính sẵn có.\n\nCác biến chứng nặng hơn bao gồm viêm phổi do virus cúm, bội nhiễm vi khuẩn, suy hô hấp, viêm cơ tim, viêm não hoặc bệnh não do cúm, co giật, viêm cơ, tiêu cơ vân, sốc và suy đa cơ quan. Một số trường hợp có thể phải điều trị hồi sức tích cực, thở máy và vẫn có nguy cơ tử vong.","author":"Nam Phương","category":"Sức khỏe","publishedAt":"2026-10-20 20:37","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/cum-co-the-tro-nang-bo-y-te-khuyen-cao-8-bien-phap-phong-benh-20261020203720502.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/va8ULxKsXPWndHR6DYk97Lk3hLU=/zoom/1200_630/2026/10/20/benhcum-cropped-1792503337679.jpg","crawledAt":"2026-10-21T13:42:40.061Z"},{"id":"dtri-20261020185918580","title":"Ba nguyên hiệu trưởng xuống làm giáo viên, Gia Lai chỉ đạo tổng kiểm tra","slug":"ba-nguyen-hieu-truong-xuong-lam-giao-vien-gia-lai-chi-dao-tong-kiem-tra","excerpt":"Trước phản ánh 3 nguyên hiệu trưởng ở phường Quy Nhơn Nam xuống làm giáo viên sau sắp xếp trường học, lãnh đạo tỉnh Gia Lai yêu cầu tổng kiểm tra, làm rõ và xử lý nghiêm nếu phát hiện sai phạm.","content":"(Dân trí) - Trước phản ánh 3 nguyên hiệu trưởng ở phường Quy Nhơn Nam xuống làm giáo viên sau sắp xếp trường học, lãnh đạo tỉnh Gia Lai yêu cầu tổng kiểm tra, làm rõ và xử lý nghiêm nếu phát hiện sai phạm.\n\nTại buổi họp báo thông tin tình hình kinh tế - xã hội 9 tháng đầu năm và nhiệm vụ trọng tâm 3 tháng cuối năm vào chiều 20/10, việc 3 nguyên hiệu trưởng được bố trí làm giáo viên sau sắp xếp trường học tại phường Quy Nhơn Nam nhận được sự quan tâm.\n\nTheo ông Trần Bá Công, Phó Giám đốc Sở Giáo dục và Đào tạo tỉnh Gia Lai, Sở đã thành lập đoàn công tác, làm việc với UBND phường Quy Nhơn Nam trong 2 buổi và báo cáo kết quả kiểm tra với UBND tỉnh.\n\nĐại diện Sở Nội vụ tỉnh Gia Lai thông tin thêm, cùng ngày UBND tỉnh đã tổ chức cuộc họp để làm rõ một số nội dung liên quan. Thời gian tới, tỉnh sẽ có thông báo kết luận.\n\nBà Nguyễn Thị Thanh Lịch, Phó Chủ tịch UBND tỉnh Gia Lai, cho biết tỉnh sẽ tổng kiểm tra việc sắp xếp trường lớp, bố trí nhân sự tại các cơ sở giáo dục nhằm kịp thời chấn chỉnh những bất cập, bảo đảm yêu cầu dạy và học.\n\n“Quan điểm của tỉnh là chấn chỉnh, xử lý nghiêm nếu phát hiện sai phạm trong công tác bố trí nhân sự tại các cơ sở giáo dục trên địa bàn, kiên quyết không bao che”, bà Lịch nhấn mạnh.\n\nTrước đó đầu tháng 9, Thường trực Tỉnh ủy Gia Lai nhận được đơn của công dân phản ánh, kiến nghị kiểm tra công tác sắp xếp, bố trí nhân sự tại các cơ sở giáo dục sau sáp nhập trên địa bàn phường Quy Nhơn Nam.\n\nNgày 12/10, Sở Giáo dục và Đào tạo báo cáo UBND tỉnh Gia Lai kết quả kiểm tra, xác minh. Theo kết quả xác minh, Trường Tiểu học Kim Đồng (mới) được thành lập trên cơ sở sáp nhập Trường Tiểu học Kim Đồng (cũ) và Trường Tiểu học Nguyễn Văn Cừ.\n\nĐáng chú ý, sau sắp xếp, bà Đ.T.T.H., nguyên Hiệu trưởng Trường Tiểu học Võ Văn Dũng (phường Quy Nhơn Nam) được điều động, bổ nhiệm làm Hiệu trưởng Trường Tiểu học Kim Đồng mới.\n\nTrong khi đó, bà H.T.H.T., nguyên Hiệu trưởng Trường Tiểu học Kim Đồng cũ và bà M.H.T.Q, nguyên Hiệu trưởng Trường Tiểu học Nguyễn Văn Cừ, được bố trí làm giáo viên.\n\nSở Giáo dục và Đào tạo tỉnh Gia Lai cho rằng hồ sơ, tài liệu chưa thể hiện đầy đủ việc đối chiếu điều kiện, tiêu chuẩn và thứ tự ưu tiên giữa 2 nguyên hiệu trưởng với những người được bố trí làm phó hiệu trưởng tại trường mới.\n\nBà C.T.H.N., nguyên Hiệu trưởng Trường THCS Quang Trung cũ, còn 21 tháng công tác đến tuổi nghỉ hưu, được bố trí làm giáo viên. Theo đại diện Sở GD&ĐT tỉnh Gia Lai, sau sáp nhập trường, tiêu chuẩn bổ nhiệm hiệu trưởng phải có thời gian công tác còn lại từ đủ 36 tháng trở lên.\n\nTrong trường hợp này, Sở Giáo dục và Đào tạo đề nghị UBND phường Quy Nhơn Nam làm rõ căn cứ không tiếp tục bố trí chức vụ quản lý đối với bà N., đối chiếu điều kiện, tiêu chuẩn, thời gian công tác còn lại, phương án bố trí phó hiệu trưởng và chính sách áp dụng theo Nghị quyết số 37/2026/NQ-CP; không suy đoán quyền đương nhiên được bổ nhiệm chỉ căn cứ vào thời gian còn công tác.\n\nSở Giáo dục và Đào tạo tỉnh Gia Lai đề nghị UBND phường Quy Nhơn Nam bổ sung, làm rõ căn cứ lựa chọn, bố trí nhân sự hiệu trưởng, phó hiệu trưởng tại các trường trên địa bàn phường.","author":"Doãn Công","category":"Giáo dục","publishedAt":"2026-10-20 18:59","source":"dantri.com.vn","url":"https://dantri.com.vn/giao-duc/ba-nguyen-hieu-truong-xuong-lam-giao-vien-gia-lai-chi-dao-tong-kiem-tra-20261020185918580.htm","categories":["Giáo dục"],"categoryIds":["giao-duc"],"thumbnail":"https://cdnphoto.dantri.com.vn/_2N1AFg8zvDPyAqUEx3bFW58s6o=/zoom/1200_630/2026/10/20/giao-duc-3-nguyen-hieu-truong-xuong-lam-giao-vien-gia-lai-chi-dao-tong-kiem-tradoan-cong-1-cropped-1792497427929.jpg","crawledAt":"2026-10-21T13:43:24.498Z"},{"id":"dtri-20261020175811750","title":"Sếp Coteccons nói \"không ngại cạnh tranh\" khi thị trường xuất hiện đối thủ lớn","slug":"sep-coteccons-noi-khong-ngai-canh-tranh-khi-thi-truong-xuat-hien-doi-thu-lon","excerpt":"Sự tham gia của VinCons và Tân Minh Nhân được Coteccons nhìn nhận tích cực, khi cạnh tranh có thể giúp chủ đầu tư đánh giá đúng hơn giá trị nhà thầu.","content":"(Dân trí) - Sự tham gia của VinCons và Tân Minh Nhân được Coteccons nhìn nhận tích cực, khi cạnh tranh có thể giúp chủ đầu tư đánh giá đúng hơn giá trị nhà thầu.\n\nĐây là chia sẻ của lãnh đạo Công ty cổ phần Xây dựng Coteccons (mã chứng khoán: CTD) tại Đại hội đồng cổ đông thường niên năm 2026 diễn ra ngày 20/10.\n\nTrả lời câu hỏi về việc các nhà thầu lớn như VinCons (thuộc Vingroup) và Tân Minh Nhân đang tham gia sâu vào lĩnh vực xây dựng, ông Nguyễn Hồng Sơn, Phó giám đốc Tài chính Coteccons, cho rằng sự xuất hiện của các doanh nghiệp này nên được nhìn nhận theo hướng tích cực.\n\nTheo ông Sơn, chủ sở hữu của VinCons và Tân Minh Nhân cũng là đối tác của Coteccons. Việc các doanh nghiệp này trực tiếp tham gia xây dựng sẽ giúp chủ đầu tư có cơ sở so sánh rõ hơn giữa việc tự tổ chức thực hiện dự án và thuê một nhà thầu chuyên nghiệp.\n\n“Sau việc này, tôi rất tự tin vào hai điều. Thứ nhất, chủ đầu tư sẽ tôn trọng chúng ta hơn vì họ hiểu chúng ta làm việc như thế nào. Thứ hai, ngành xây dựng sẽ được nâng lên một cấp độ mới”, ông Sơn nói.\n\nTheo lãnh đạo Coteccons, khi trực tiếp tham gia lĩnh vực xây dựng, các đơn vị chủ quản của VinCons và Tân Minh Nhân sẽ có cái nhìn đầy đủ hơn về ngành, từ đó chấp nhận mức giá cao hơn, tương xứng với công sức của các kỹ sư trên công trường cũng như mức độ phức tạp trong quản lý dự án, thay vì nhìn nhận đơn giản về công việc này.\n\n“Đây là điểm tích cực, chứ không phải điều gì tiêu cực. Còn về cạnh tranh thị trường, chúng ta chấp nhận điều đó. Không có VinCons hay Tân Minh Nhân thì sẽ có công ty A, B, C, D. Nếu một thị trường không có cạnh tranh thì thị trường đó cần được xem xét lại, bởi có lẽ không còn ai muốn tham gia nữa”, ông Sơn nói.\n\nÔng nhấn mạnh Coteccons không lo ngại cạnh tranh. Điều doanh nghiệp mong muốn là các chủ đầu tư, những người sử dụng dịch vụ, đánh giá và nhìn nhận lại giá trị của Coteccons. “Đó là điều lớn nhất mà sự cạnh tranh này có thể mang lại cho ngành xây dựng”, ông nói.\n\nDù cạnh tranh gia tăng, Coteccons cho biết không chạy đua bằng mọi giá. Ông Nguyễn Chí Thiện, Phó Tổng giám đốc Coteccons, cho hay trong quá khứ, doanh nghiệp từng trả giá và chịu thua lỗ khi tham gia một số dự án không được đánh giá cẩn trọng. Vì vậy, Coteccons duy trì nguyên tắc “không tăng trưởng bằng mọi giá”, không lấy dự án bằng mọi giá mà tập trung vào các dự án phức tạp, quy mô lớn với mức giá hợp lý.\n\nVề định hướng kinh doanh, ông Bolat Duisenov, Chủ tịch HĐQT Coteccons, cho hay trong năm tài chính 2027, mảng xây dựng ngoài nhà ở, gồm xây dựng công nghiệp, hạ tầng và các sản phẩm, dịch vụ chuyên sâu, dự kiến chiếm khoảng 50% tổng doanh thu.\n\nNăm tài chính 2027, Coteccons đặt mục tiêu doanh thu hợp nhất 42.000 tỷ đồng, lợi nhuận sau thuế hợp nhất 1.050 tỷ đồng, tăng lần lượt 22% và 34% so với mức thực hiện năm tài chính 2026. Dài hạn, doanh nghiệp hướng đến doanh thu 68.000 tỷ đồng vào năm tài chính 2030, đồng thời đặt mục tiêu tỷ suất lợi nhuận trên vốn chủ sở hữu (ROE) trong khoảng 15-18%.\n\nTrong quý I năm tài chính 2027, Coteccons đạt 11.270 tỷ đồng doanh thu hợp nhất và 306 tỷ đồng lợi nhuận sau thuế hợp nhất. Giá trị hợp đồng ký mới đạt 14.519 tỷ đồng, giảm 25% so với cùng kỳ năm trước do công ty chủ trương chọn lọc khách hàng và dự án khắt khe hơn.\n\nỞ góc độ ngành, ông Nguyễn Quang Thuân, Chủ tịch FiinGroup, nhận định dư địa tăng trưởng của doanh nghiệp xây dựng không còn nằm ở việc mở rộng quy mô bằng mọi giá mà phụ thuộc nhiều hơn vào năng lực quản trị rủi ro, kiểm soát dòng tiền và lựa chọn dự án. Doanh nghiệp cần tạo khác biệt về chất lượng, kỹ thuật và dịch vụ để cạnh tranh bằng giá trị thay vì giá thấp.\n\nMột hướng đi đáng chú ý là mở rộng sang nhóm khách hàng FDI và các dự án hạ tầng, nơi yêu cầu cao về năng lực tài chính, tiến độ, chất lượng và tiêu chuẩn ESG. “Khi dư địa cạnh tranh bằng giá ngày càng hạn chế, doanh nghiệp xây dựng cần chuyển từ chạy theo sản lượng sang chú trọng chất lượng dự án, sức khỏe tài chính và năng lực đáp ứng các tiêu chuẩn quốc tế”, ông Thuân nói.","author":"Lê Tỉnh","category":"Bất động sản","publishedAt":"2026-10-20 17:58","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/sep-coteccons-noi-khong-ngai-canh-tranh-khi-thi-truong-xuat-hien-doi-thu-lon-20261020175811750.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/bpD_J55Ebpbu8fsLNs46o-zfvTI=/zoom/1200_630/2026/10/20/ong-bolat-chu-tich-cottecons-cropped-cropped-1792493629625.jpg","crawledAt":"2026-10-21T13:43:01.447Z"},{"id":"dtri-20261020171722264","title":"Cụ ông 80 tuổi vẫn tặng hoa người vợ đã khuất mỗi dịp 20/10","slug":"cu-ong-80-tuoi-van-tang-hoa-nguoi-vo-da-khuat-moi-dip","excerpt":"Suốt nhiều năm sau ngày vợ qua đời, ông Thanh ở Hà Tĩnh vẫn đều đặn mua hoa tươi, mang đến mộ bà mỗi dịp 20/10. Hành động lặng lẽ của cụ ông khiến nhiều người xúc động.","content":"(Dân trí) - Suốt nhiều năm sau ngày vợ qua đời, ông Thanh ở Hà Tĩnh vẫn đều đặn mua hoa tươi, mang đến mộ bà mỗi dịp 20/10. Hành động lặng lẽ của cụ ông khiến nhiều người xúc động.\n\nHai ngày qua, clip ghi lại cảnh cụ ông chở bó hoa tươi trên xe máy, đi về phía nghĩa trang ở Hà Tĩnh, thu hút sự chú ý của cộng đồng mạng. Câu chuyện phía sau càng khiến nhiều người xúc động khi hình ảnh xuất hiện đúng dịp Ngày Phụ nữ Việt Nam 20/10.\n\nTheo thông tin người đăng tải chia sẻ, cụ ông có thói quen mua hoa tươi, mang hương đến thăm mộ vợ mỗi năm, dù bà đã mất gần 2 thập kỷ.\n\nHình ảnh được ghi lại trên một cung đường ở phường Sông Trí, tỉnh Hà Tĩnh, khu vực trước đây thuộc thị xã Kỳ Anh.\n\nClip nhanh chóng nhận được hàng nghìn lượt yêu thích, bình luận và chia sẻ. Nhiều người bày tỏ sự xúc động, ngưỡng mộ tình cảm thủy chung, son sắt của cụ ông dành cho người vợ quá cố.\n\nKhông ít ý kiến cho rằng, câu chuyện giản dị ấy gợi nhắc về giá trị của tình yêu và nghĩa tình vợ chồng, khi sự quan tâm dành cho người thương vẫn được gìn giữ qua năm tháng.\n\nChiều 20/10, trao đổi với phóng viên Dân trí, Tiến sĩ Trần Thị Mai Loan (SN 1984), giảng viên Trường Đại học Lao động - Xã hội (Hà Nội), xác nhận người đàn ông trong clip là bố chị - ông Trần Xuân Thanh (80 tuổi, trú phường Sông Trí, Hà Tĩnh), thương binh hạng 2.\n\nTheo chị Loan, bố chị từng nhập ngũ năm 18 tuổi, sớm đứng vào hàng ngũ của Đảng. Ngày 2/9 vừa qua, ông được trao tặng Huy hiệu 60 năm tuổi Đảng.\n\nVợ ông Thanh trước đây làm giáo viên, mất vì bệnh hiểm nghèo cách đây 19 năm. Từ ngày vợ qua đời, ông ở vậy, một mình nuôi dạy 7 người con, gồm 5 trai và 2 gái, trưởng thành.\n\nSuốt nhiều năm qua kể từ ngày bà mất, vào các dịp 20/10, 20/11 và 8/3, ông đều mua hoa, mang hương đến thăm mộ vợ và mẹ. Việc làm ấy đã trở thành thói quen, được ông lặng lẽ duy trì qua từng năm.\n\n\"Trước đây, khi mạng xã hội chưa phát triển, việc làm của bố chỉ có con cháu, họ hàng biết. Hôm qua, một người đi đường tình cờ ghi lại cảnh bố chở bó hoa rồi hỏi chuyện, sau đó đăng clip lên mạng nên nhiều người mới biết đến\", chị Loan kể.\n\nBiết câu chuyện của bố được nhiều người quan tâm, chị Loan vừa nhớ mẹ, vừa thương bố. Người con gái cho hay nếu có ngày nghỉ dịp này, chị muốn về nhà ngay để ở bên ông.\n\nChị cho biết thêm bố rất yêu thích thể thao, đặc biệt đam mê bóng đá. Nhờ duy trì thói quen vận động, ông có sức khỏe khá tốt. Tuy nhiên, khoảng 3 năm nay, các con khuyên ông hạn chế những hoạt động mạnh, chuyển sang các môn nhẹ nhàng hơn như đi bộ để phù hợp với tuổi tác.\n\n\"Bố sống tình cảm, luôn dành cho mẹ sự quan tâm dù bà đã mất 19 năm. Tôi rất xúc động và thương bố. Với chúng tôi, cách sống, đức tính của bố luôn là tấm gương sáng để con cháu học hỏi, noi theo\", chị Loan chia sẻ.","author":"Dương Nguyên","category":"Đời sống","publishedAt":"2026-10-20 17:17","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/cu-ong-80-tuoi-van-tang-hoa-nguoi-vo-da-khuat-moi-dip-2010-20261020171722264.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/2xJAQ9x6a9o9TLWjgSbxkakIFCs=/zoom/1200_630/2026/10/20/phunu11a-cropped-1792490892749.jpg","crawledAt":"2026-10-21T13:42:45.444Z"},{"id":"dtri-20261020170036248","title":"BTV Hồng Nhung VTV: 19 năm lên sóng, chọn sống bình yên bên 2 con","slug":"btv-hong-nhung-vtv-19-nam-len-song-chon-song-binh-yen-ben-2-con","excerpt":"BTV Hồng Nhung có 19 năm gắn bó với truyền hình, được khán giả VTV yêu mến bởi giọng đọc truyền cảm. Ngoài công việc, cô dành phần lớn thời gian cho các con và gia đình.","content":"BTV Nguyễn Hồng Nhung (SN 1990) bước vào lĩnh vực truyền hình từ khi còn là sinh viên năm nhất. Cô cho biết, thời gian đầu, bản thân luôn háo hức thể hiện mình, muốn nói nhiều nên thường dẫn nhanh, vội. Qua năm tháng, cô học cách khiêm nhường, lắng nghe, chọn lọc lời nói và biết chia sẻ, đồng cảm với nhân vật. Nhờ đó, nữ BTV được khán giả truyền hình yêu thích bởi lối dẫn truyền cảm, chân thành, giọng đọc chạm đến trái tim.\n\nNăm 2018, Hồng Nhung được nhà báo Tạ Bích Loan và nhà báo Vũ Thanh Hường trao cơ hội thực hiện số đầu tiên của Giai điệu tự hào. Với cô, đây là dấu mốc đặc biệt bởi chương trình đòi hỏi người dẫn vừa nắm vững kiến thức lịch sử, văn hóa, nghệ thuật, vừa điều phối những cuộc đối thoại, tranh luận với chuyên gia, nhà văn hóa và nghệ sĩ trong thời lượng 70-80 phút phát sóng trực tiếp.\n\nMột trải nghiệm đáng nhớ khác của BTV - MC Hồng Nhung là bản tin đặc biệt Rạng rỡ Việt Nam, chào đón lễ kỷ niệm 80 năm Cách mạng tháng Tám thành công và Quốc khánh 2/9, phát sóng sáng 2/9/2025. Dù đã có nhiều năm dẫn chương trình trực tiếp, Hồng Nhung cho biết cô và MC Hạnh Phúc vẫn chịu áp lực lớn bởi tầm vóc của sự kiện.\n\n“Đó là khoảnh khắc mà lịch sử chỉ đi qua có một lần. Đó không phải là bản tin mà Hạnh Phúc, Hồng Nhung dẫn dắt hay được thực hiện bởi một cái tên cụ thể nào đó, mà là bản tin dành cho một sự kiện đặc biệt quan trọng mà cả đất nước đều hướng về”, cô nói.\n\nSau khi hoàn thành phần dẫn, Hồng Nhung cùng ê-kíp theo dõi những hình ảnh trực tiếp từ Quảng trường Ba Đình. Hình ảnh quốc kỳ tung bay trong tiếng hát Quốc ca, các khối lực lượng diễu binh và người dân trên khắp phố phường khiến cô xúc động.\n\n“Chúng tôi bật khóc ngay sau khi chương trình kết thúc, hiểu thế nào là vỡ òa, thế nào là những giọt nước mắt hạnh phúc”, nữ BTV nhớ lại.\n\nTrong những trải nghiệm làm nghề, Hồng Nhung nhớ nhất khoảnh khắc tại chương trình Điểm tựa Việt Nam, được thực hiện sau bão Yagi năm 2024 nhằm chia sẻ với đồng bào vùng bị ảnh hưởng. Một em nhỏ có mặt tại trường quay từng chứng kiến bố và chị gái bị nước lũ cuốn trôi. Ê-kíp thống nhất không đặt thêm câu hỏi để tránh khơi sâu tổn thương của em.\n\nTuy nhiên, khi trực tiếp ôm em trên sân khấu, Hồng Nhung quyết định hỏi: “Hình ảnh con nhớ nhất về bố là gì?”. Em bé trả lời: “Bố chơi với con ạ”. Nói về quyết định khi đó, nữ BTV giải thích: \"Tôi nghĩ khi con nói ra được, khóc lên được cũng là một cách để giải tỏa. Cũng là một người mẹ, tôi tin rằng có những ký ức không thể cứ cố là sẽ quên, không phải không nhắc đến là sẽ bớt đau”.\n\nHồng Nhung thừa nhận quyết định đặt câu hỏi đồng nghĩa với việc cô làm trái với thống nhất của ê-kíp và đạo diễn. Tuy vậy, nếu được trở lại thời điểm ấy, cô vẫn muốn xin phép người thầy cho mình được hành động theo cảm xúc.\n\nVới nữ BTV, người dẫn chương trình không chỉ cần kỹ năng mà còn phải có kiến thức, sự chân thành và trách nhiệm với nhân vật. Trong bối cảnh khán giả có nhiều lựa chọn tiếp nhận thông tin, cô cho rằng điều quan trọng không chỉ là thu hút người xem mà còn là tạo dựng niềm tin.\n\n“Uy tín không được tạo nên bởi một lần xuất hiện xuất sắc mà bởi sự nhất quán qua hàng ngàn lần xuất hiện”, cô nói.\n\nNgoài công việc, Hồng Nhung cho biết, làm mẹ là ưu tiên hàng đầu của cô. Cô luôn tự tay chăm sóc các con từ nhỏ, cố gắng sắp xếp lịch làm việc để có mặt bên gia đình. Khi đi công tác, cô thường chọn chuyến bay sáng sớm để có thể trở về nhà vào buổi tối. Nếu kết thúc chương trình muộn ở tỉnh khác, cô sẵn sàng di chuyển trong đêm.\n\nNữ BTV thừa nhận từng quá khắt khe với bản thân, muốn mọi việc trong gia đình diễn ra theo kế hoạch. Sự kỳ vọng mọi thứ hoàn hảo có lúc khiến cô kiệt sức và tạo áp lực cho người thân.\n\n“Dần dần tôi phải tự điều chỉnh. Các con có thể làm hỏng, có thể ngủ muộn, nhà cửa có thể bẩn hơn một chút, đồ đạc có thể không gọn gàng, mẹ có thể xa các con lâu hơn một chút, mọi thứ rồi cũng sẽ đâu vào đấy, sẽ ổn theo một định nghĩa khác”, cô chia sẻ.\n\nHồng Nhung từng trở lại làm việc chỉ 17 ngày sau khi sinh mổ con thứ hai. Khi em bé tròn 1 tháng tuổi, cô đưa các con cùng đi chuyến công tác đầu tiên vào dịp giáp Tết. Dù không hối tiếc về quyết định khi ấy, nữ BTV thừa nhận việc đi làm sớm ảnh hưởng đến sức khỏe, khiến cô thường xuyên gặp những cơn đau lưng, đau đầu và phải trải qua các đợt điều trị kéo dài.\n\nỞ thời điểm hiện tại, Hồng Nhung cho biết cô ít nghĩ về khái niệm thành công hơn trước, thay vào đó trân trọng những khoảnh khắc bên các con. Mỗi sáng, cô dành thời gian ngắm bọn trẻ ngủ, đôi khi bật cười vì dáng ngủ ngộ nghĩnh của chúng. Cô cũng cố gắng dành nhiều thời gian hơn cho các cháu ở bên ông bà.\n\nHồng Nhung cũng không đặt mục tiêu xây dựng hình ảnh hoàn hảo ngoài đời. Cô muốn gia đình và các con có thể tự hào về hành trình làm nghề của mình, nhưng cũng chủ động giữ cuộc sống riêng tư ngoài công việc.\n\nNgoài giờ làm, cô ít tham gia sự kiện, thích đọc sách, nghe nhạc khi di chuyển và tận hưởng những khoảng thời gian một mình. Hồng Nhung cho biết, điều cô tìm kiếm là cảm giác an toàn và bình yên bên gia đình.","author":"Mai Châm","category":"Giải trí","publishedAt":"2026-10-20 17:00","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/btv-hong-nhung-vtv-19-nam-len-song-chon-song-binh-yen-ben-2-con-20261020170036248.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/DAcmGnOxjJbp38CM0_ztjm8sMD8=/zoom/1200_630/2026/10/20/btv-hong-nhung-vtv24-cropped-1792486272455.jpg","crawledAt":"2026-10-21T13:43:11.685Z"},{"id":"dtri-20261020165559018","title":"Đoàn tàu kết nối di sản miền Trung lọt top 10 được yêu thích nhất thế giới","slug":"doan-tau-ket-noi-di-san-mien-trung-lot-top-10-duoc-yeu-thich-nhat-the-gioi","excerpt":"Đoàn tàu du lịch kết nối di sản miền Trung nằm trong top 10 hành trình tàu hỏa được yêu thích nhất thế giới năm 2026, đi qua cung đường sắt đẹp nhất Việt Nam.","content":"(Dân trí) - Đoàn tàu du lịch kết nối di sản miền Trung nằm trong top 10 hành trình tàu hỏa được yêu thích nhất thế giới năm 2026, đi qua cung đường sắt đẹp nhất Việt Nam.\n\nCầu vòm Đồn Cả tại km764+531, trên tuyến đường sắt Bắc - Nam nằm giữa núi rừng hùng vĩ Bắc đèo Hải Vân (thuộc địa phận xã Chân Mây - Lăng Cô, thành phố Huế) từ lâu đã trở thành địa điểm tham quan, trải nghiệm của nhiều du khách.\n\nChị Phương Nguyễn Silk, làm việc tại Đà Nẵng cho biết bản thân đã đi du lịch, khám phá nhiều địa điểm nổi tiếng của Việt Nam. Tại cầu vòm Đồn Cả, chị được trải nghiệm cảm giác leo núi, ngắm biển và chụp ảnh tại địa điểm cụ thể trong khung cảnh tựa như một thước phim.\n\n\"Mỗi lần đứng dưới chân cầu nhìn các đoàn tàu, nhất là tàu du lịch kết nối di sản miền Trung chạy qua luôn mang lại cho tôi cảm giác đặc biệt vì bản thân đã từng đi tàu trải nghiệm\", chị Silk chia sẻ.\n\nTheo một nhân viên tại ga Hải Vân Bắc, cầu vòm Đồn Cả được xây dựng cách đây hơn 100 năm. Cây cầu được thiết kế theo dạng cổng mái vòm, gác trên các trụ bằng đá, bắc qua khe suối có độ cao 20m, dài khoảng 100m.\n\nKhe suối dưới chân cầu có nước trong vắt, bắt nguồn từ đỉnh đèo Hải Vân, nhiều năm qua đã trở thành địa điểm check-in thu hút đông đảo du khách trong và ngoài nước bởi vẻ đẹp hoang sơ.\n\nCung đường dài 19,8km, một bên dựa vào núi cao sừng sững, một bên hướng ra biển sâu thẳm, tạo nên cảnh sắc độc đáo.\n\nÔng Lương Xuân Thường, Giám đốc Chi nhánh Vận tải đường sắt Đồng Hới, Công ty cổ phần đường sắt, cho biết mới đây tạp chí du lịch Conde Nast Traveler (Mỹ) đã công bố danh sách 20 hành trình tàu hỏa được yêu thích nhất thế giới năm 2026, do độc giả bình chọn. Đoàn tàu kết nối di sản miền Trung (đi qua cung đường Hải Vân) được vinh danh ở vị trí thứ 10.\n\nTheo ông Thường, các đoàn tàu du lịch được đưa vào khai thác từ tháng 3/2024. Đến ngày 26/3, đoàn tàu được nâng cấp giao diện mới, với nội thất sang trọng, mang dấu ấn di sản văn hóa của cố đô Huế và phố cổ Hội An.\n\nMỗi đoàn tàu có 5 toa xe ghế mềm điều hòa, có thể xoay 180 độ theo hướng tàu chạy, 1 toa xe cao cấp gồm 32 chỗ ngồi hướng ra biển để hành khách tiện ngắm vẻ đẹp thiên nhiên hùng vĩ suốt hành trình.\n\nTrong khoảng 3 giờ di chuyển, hành khách có thể chiêm ngưỡng hệ sinh thái đầm phá Tam Giang - Cầu Hai, vịnh Lăng Cô và cung đường đèo Hải Vân hùng vĩ. Du khách còn được thưởng thức các chương trình biểu diễn nghệ thuật hấp dẫn, sản phẩm ẩm thực đặc trưng của Huế và Đà Nẵng. Ngành đường sắt cũng chú trọng bố trí phòng chờ cao cấp tại ga Huế, Đà Nẵng để nâng cao sự thoải mái cho hành khách.\n\n“Để có thêm các sản phẩm trải nghiệm mới lạ, mới đây ngành đường sắt đã khai trương đoàn tàu cố đô Huế - Phong Nha (Quảng Trị): kết nối di sản Thế giới. Dự kiến trong thời gian tới sẽ có thêm tàu hỏa chạy bằng đầu máy hơi nước đi vào hoạt động trên cung đường Hải Vân”, ông Thường cho hay.\n\nTổng công ty Đường sắt Việt Nam sẽ tổ chức 2 đôi tàu/ngày kết nối di sản miền Trung giữa Huế - Đà Nẵng.\n\nNăm 2024, đoàn tàu dẫn đầu bình chọn hạng mục top 9 sản phẩm du lịch ấn tượng thành phố Huế.\n\nTháng 6/2025, tạp chí du lịch Lonely Planet công bố 24 hành trình tàu hỏa tuyệt vời nhất thế giới nên trải nghiệm trong năm.\n\nTàu Thống Nhất - tuyến đường sắt Bắc - Nam của Việt Nam đứng đầu danh sách. Chuyến tàu dài hơn 1.700km, băng qua nhiều địa hình, nổi bật nhất là đoạn qua đèo Hải Vân, nơi có cảnh quan hùng vĩ, cùng Thiên hạ đệ nhất hùng quan trên đỉnh.\n\nTừ khi nâng cấp giao diện mới đến nay, các đoàn tàu du lịch kết nối di sản miền Trung đã vận chuyển 215.000 lượt khách, tăng 40% so với cùng kỳ. Đặc biệt, khách quốc tế có sự tăng đột biến, hơn 70% so với cùng kỳ 2025.","author":"Vi Thảo","category":"Du lịch","publishedAt":"2026-10-20 16:55","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/doan-tau-ket-noi-di-san-mien-trung-lot-top-10-duoc-yeu-thich-nhat-the-gioi-20261020165559018.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/eDBqgXdAYrXCDZEeVLQx5Uj7riM=/zoom/1200_630/2026/10/20/du-lich-doan-tau-du-lich-duoc-yeu-thich-nhat-the-gioi-cropped-1792489373359.jpg","crawledAt":"2026-10-21T13:42:49.480Z"},{"id":"dtri-20261020161708860","title":"Cụ bà có 10 người con, 23 cháu, 26 chắt, mỗi lần sum vầy làm 10 mâm cơm","slug":"cu-ba-co-10-nguoi-con-23-chau-26-chat-moi-lan-sum-vay-lam-10-mam-com","excerpt":"Cụ bà 91 tuổi ở Thanh Hóa có 10 người con, 23 người cháu và 26 người chắt. Chồng mất khi sớm, nhưng cụ một mình làm muối nuôi các con học hành, khôn lớn.","content":"(Dân trí) - Cụ bà 91 tuổi ở Thanh Hóa có 10 người con, 23 người cháu và 26 người chắt. Chồng mất khi sớm, nhưng cụ một mình làm muối nuôi các con học hành, khôn lớn.\n\nỞ tổ dân phố Tiền Phong, phường Hải Bình, tỉnh Thanh Hóa có một cụ bà đặc biệt với 10 người con, 23 cháu và 26 chắt. Đó là cụ Nguyễn Thị Doãn (91 tuổi), được người dân địa phương gọi bằng cái tên thân thuộc là cụ cố Lài.\n\nBà Lê Thị Huệ (64 tuổi, con gái thứ 5 của cụ Doãn) chia sẻ dù đã ở tuổi “xưa nay hiếm”, mẹ của bà vẫn khá minh mẫn, có thể tự lo các sinh hoạt cá nhân hằng ngày.\n\nTheo bà Huệ, trước đây gia đình có hoàn cảnh khó khăn, vất vả. Trong số 10 người con của cụ Doãn, có 5 trai, 5 gái. Năm 1975, khi cụ đang mang thai người con thứ 10, chồng qua đời.\n\nKể từ đó, một mình cụ Doãn lam lũ với nghề làm muối để mưu sinh, nuôi nấng các con. Dù gia đình đông con, cụ vẫn quyết tâm cho các con đến trường, biết chữ.\n\n“Ở làng biển ngày đó, kiếm ăn đã khó, gia đình lại đông con nhưng mẹ tôi vẫn quyết tâm cho các con đi học biết chữ. Nhiều người còn bảo mẹ tôi dại vì kiếm tiền nuôi các con ăn đã khó, bà lại tự làm khó mình hơn vì cho con đi học”, bà Huệ nhớ lại.\n\nTheo bà Huệ, vì gia đình đông con, cụ Doãn phải vất vả lắm mới nuôi các con khôn lớn. Đến từng bộ quần áo, chị em bà Huệ phải chia ra mặc lại của nhau.\n\nTừ nhỏ, bà Huệ và các anh chị em thường xuyên ra đồng muối phụ mẹ làm việc. “Cứ đứa này lớn lên lại bế đứa khác. Chúng tôi thay nhau giúp mẹ làm việc, chăm sóc các em và lo việc nấu ăn. Mẹ tôi bảo dù khó khăn đến mấy cũng phải nuôi chúng tôi biết chữ”, bà Huệ nhớ lại.\n\nNhờ sự kiên trì của cụ Doãn, cả 10 người con đều được đến trường. Đến nay, nhiều người thành đạt, công tác trong cơ quan nhà nước, làm kinh doanh.\n\nTheo bà Huệ, trong số 10 anh chị em, bà Lê Thị Hoa (con gái thứ 2 của cụ Doãn) là người vất vả nhất. Khi học đến lớp 7, vì hoàn cảnh gia đình khó khăn, bố mất sớm, bà Hoa đành gác lại việc học để ở nhà cùng mẹ kiếm sống, chăm lo cho các em.\n\n“Đến bây giờ, chị em chúng tôi vẫn không thể quên công ơn của chị. Tôi vẫn thường nhắc nhở các con cần ghi nhớ và giúp đỡ chị Hoa mỗi khi cần”, bà Huệ nói.\n\nTheo bà Huệ, dù đã 91 tuổi, cụ Doãn vẫn nhớ tên từng người con, cháu và chắt trong gia đình. Đặc biệt, mỗi dịp giỗ, Tết, con cháu đi làm ăn xa lại trở về sum họp, tạo nên không khí ấm cúng, đoàn viên. Có những dịp con cháu về đông đủ, gia đình phải chuẩn bị tới 10 mâm cơm mới đủ chỗ cho mọi người.\n\nNhớ lại những tháng ngày đã qua, bà Huệ không giấu được sự xúc động và niềm tự hào về công ơn sinh thành, dưỡng dục của mẹ. “Mẹ tôi đã vất vả rất nhiều để chúng tôi có được như ngày hôm nay. Chúng tôi chỉ mong sao mẹ có sức khỏe để các con được báo hiếu, chăm sóc những tháng ngày còn lại”, bà Huệ nói.\n\nÔng Lê Trọng Lương, Chủ tịch Hội người cao tuổi phường Hải Bình, cho biết toàn phường có 4.900 hội viên người cao tuổi. Trong đó số người trong độ tuổi từ 90 đến hơn 100, có khoảng 200 hội viên.\n\nTheo ông Lương, do đặc thù vùng ven biển, trước đây các cụ cao niên trong phường thường đẻ nhiều để lấy lao động đi đánh bắt. “Tỷ lệ gia đình có 6-9 người con rất nhiều, nhưng có tận 10 người con thì hiếm. Đáng nói, gia đình đông con nhưng được đi học như gia đình cụ Doãn là rất đặc biệt. Cụ Doãn ở địa phương là người hiền lành, chịu khó, được người dân rất yêu quý”, ông Lương nói.","author":"Thanh Tùng","category":"Đời sống","publishedAt":"2026-10-20 16:17","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/cu-ba-co-10-nguoi-con-23-chau-26-chat-moi-lan-sum-vay-lam-10-mam-com-20261020161708860.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/Wf0egJF3LLpBnytGCPdRnNm5Ujw=/zoom/1200_630/2026/10/20/cu-ba-thanh-hoa1-cropped-1792487680838.jpg","crawledAt":"2026-10-21T13:42:45.427Z"},{"id":"dtri-20261020154535705","title":"Mô tô Anh Quốc giới hạn 750 chiếc về Việt Nam có giá đắt hơn Mazda CX-5","slug":"mo-to-anh-quoc-gioi-han-750-chiec-ve-viet-nam-co-gia-dat-hon-mazda-cx","excerpt":"Triumph Speed Twin 1200 TFC chỉ được sản xuất giới hạn 750 chiếc trên toàn cầu cũng được phân phối chính hãng tại Việt Nam, và chiếc đầu tiên về nước đã có chủ sở hữu.","content":"(Dân trí) - Triumph Speed Twin 1200 TFC chỉ được sản xuất giới hạn 750 chiếc trên toàn cầu cũng được phân phối chính hãng tại Việt Nam, và chiếc đầu tiên về nước đã có chủ sở hữu.\n\nRa mắt vào năm 2019, Triumph Factory Custom (TFC) là phân nhánh chuyên độ xe chính hãng cao cấp của hãng mô tô Anh Quốc, với số lượng giới hạn trên toàn cầu. Sản phẩm mới nhất của bộ phận này là mẫu Triumph Speed Twin 1200 TFC, được giới thiệu vào tháng 7 và hiện đã được đưa về Việt Nam.\n\nTương tự các mẫu xe từng xuất xưởng, Triumph Speed Twin 1200 TFC được phân phối giới hạn 750 chiếc trên toàn cầu. Theo chia sẻ của giới tư vấn bán hàng, số lượng xe được mở bán chính hãng tại Việt Nam rất ít, đồng thời mẫu mô tô này có giá bán lẻ đề xuất lên tới 899,9 triệu đồng.\n\nMức giá này cao ngang giá niêm yết của Triumph Rocket 3 GT (899 triệu đồng) – mẫu mô tô đầu bảng (flagship) của hãng xe Anh Quốc, đồng thời đắt hơn giá bán lẻ đề xuất của một mẫu ô tô gầm cao hạng C như Mazda CX-5 (cao nhất 869 triệu đồng).\n\nKhác với dòng Speed Twin 1200 tiêu chuẩn, phiên bản TFC được trang bị tay lái dạng clip-on. Xe được khắc laser số thứ tự sản xuất kèm logo TFC trên chảng ba nhôm CNC, đi kèm giấy chứng nhận xác thực có chữ ký cùng bộ phụ kiện gồm bạt trùm xe trong nhà và bọc yên chống thấm nước.\n\nTrang bị nổi bật có cặp ống xả Akrapovič chất liệu titan đi kèm nắp chụp được làm bằng sợi carbon, “dàn chân” gây ấn tượng với phuộc Ohlins trước/sau tùy chỉnh toàn phần, đi kèm cụm phanh Brembo Stylema, cùm phanh Brembo MCS và bộ lốp Metzeler Racetec RR K3.\n\nVề khả năng vận hành, Triumph Speed Twin 1200 TFC được trang bị động cơ 2 xi-lanh song song, dung tích 1.200cc, làm mát bằng dung dịch, kết hợp với hộp số côn tay 6 cấp. Cấu hình này sản sinh công suất tối đa 103 mã lực tại tua máy 7.750 vòng/phút và mô-men xoắn cực đại đạt 112Nm tại 4.250 vòng/phút.\n\nCông nghệ hỗ trợ trên mẫu xe mô tô này gồm hệ thống sang số nhanh Triumph Shift Assist, ga điện tử có 3 chế độ lái (Đường trường, Mưa và Thể thao), phanh chống bó cứng ABS và kiểm soát lực kéo biến thiên khi vào cua.\n\nDù sở hữu giá bán đắt đỏ nhưng với số lượng giới hạn, Triumph Speed Twin 1200 TFC vẫn hứa hẹn sẽ thu hút được những nhà sưu tập. Đồng thời, những trang bị hiệu năng cao trên mẫu xe này được đăng ký chính hãng, phù hợp với quy định tham gia giao thông, và không bị xem là thay đổi kết cấu như người dùng tự độ.","author":"Nguyễn Lâm","category":"Xe ++","publishedAt":"2026-10-20 15:45","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/mo-to-anh-quoc-gioi-han-750-chiec-ve-viet-nam-co-gia-dat-hon-mazda-cx-5-20261020154535705.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/yiJ9IS99aS2eUONWSINaFhRQW0s=/zoom/1200_630/2026/10/20/triumph-speed-twin-1200-tfc-ve-viet-nam-co-gia-dat-hon-mazda-cx-5-anh1-cropped-1792485726089.jpg","crawledAt":"2026-10-21T13:43:31.233Z"},{"id":"dtri-20261020151314579","title":"TPHCM thu hồi hơn 19ha đất của dự án Công viên Thiên niên kỷ","slug":"tphcm-thu-hoi-hon-19ha-dat-cua-du-an-cong-vien-thien-nien-ky","excerpt":"TPHCM đã thu hồi hơn 19ha đất thực hiện dự án đầu tư “Xây dựng Công viên Thiên niên kỷ” tại Khu Công nghệ cao. Dự án đã chấm dứt hoạt động và doanh nghiệp tự nguyện trả lại đất thuê.","content":"(Dân trí) - TPHCM đã thu hồi hơn 19ha đất thực hiện dự án đầu tư “Xây dựng Công viên Thiên niên kỷ” tại Khu Công nghệ cao. Dự án đã chấm dứt hoạt động và doanh nghiệp tự nguyện trả lại đất thuê.\n\nUBND TPHCM vừa quyết định thu hồi khu đất gần 19,2ha tại Khu Công nghệ cao, phường Tăng Nhơn Phú, do Công ty Cổ phần Dệt may Sài Gòn thuê để thực hiện dự án đầu tư “Xây dựng Công viên Thiên niên kỷ”. Khu đất này được Ban Quản lý Khu Công nghệ cao cho Công ty Cổ phần Dệt may Sài Gòn thuê theo hợp đồng ký từ năm 2017.\n\nLý do thu hồi là dự án “Xây dựng Công viên Thiên niên kỷ” đã chấm dứt hoạt động theo thông báo của Ban Quản lý Khu Công nghệ cao. Sau đó, doanh nghiệp có văn bản tự nguyện trả lại đất thuê.\n\nUBND TPHCM giao Ban Quản lý Khu Công nghệ cao chủ trì, phối hợp với Sở Nông nghiệp và Môi trường, doanh nghiệp cùng các đơn vị liên quan kiểm tra hiện trạng, xác nhận diện tích, ranh giới và tài sản gắn liền với đất; lập biên bản tiếp nhận, bàn giao theo quy định.\n\nSau khi tiếp nhận, Ban Quản lý Khu Công nghệ cao có trách nhiệm quản lý chặt chẽ khu đất, không để xảy ra tình trạng lấn chiếm, xây dựng trái phép. Việc khai thác, sử dụng đất và lựa chọn nhà đầu tư mới phải tuân thủ quy định pháp luật.\n\nCông ty Cổ phần Dệt may Sài Gòn có trách nhiệm thực hiện các nghĩa vụ tài chính về đất đai còn phải nộp (nếu có), phối hợp kiểm kê tài sản, bàn giao đất và giấy tờ về quyền sử dụng đất theo quy định. Thuế TPHCM được giao xác định thời điểm chấm dứt nghĩa vụ tiền thuê đất, số tiền còn phải nộp và xử lý các khoản tài chính phát sinh.","author":"Q.Huy","category":"Bất động sản","publishedAt":"2026-10-20 15:13","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/tphcm-thu-hoi-hon-19ha-dat-cua-du-an-cong-vien-thien-nien-ky-20261020151314579.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/l1sfVvQH8pAgaasCpdxkqxl_Z_Y=/zoom/1200_630/2026/10/20/tphcm-thu-hoi-hon-19ha-dat-cua-du-an-cong-vien-thien-nien-ky-cropped-1792483899719.jpg","crawledAt":"2026-10-21T13:43:02.546Z"},{"id":"dtri-20261020134104178","title":"Về Cà Mau dự Festival tôm, chạm Đất Mũi, khám phá U Minh Hạ","slug":"ve-ca-mau-du-festival-tom-cham-dat-mui-kham-pha-u-minh-ha","excerpt":"Cà Mau tổ chức hoạt động xúc tiến du lịch với chương trình kích cầu “Về Cà Mau dự Festival tôm, chạm Đất Mũi, khám phá U Minh Hạ\", phục vụ du khách đến vùng đất địa đầu cực Nam của Tổ quốc.","content":"(Dân trí) - Cà Mau tổ chức hoạt động xúc tiến du lịch với chương trình kích cầu “Về Cà Mau dự Festival tôm, chạm Đất Mũi, khám phá U Minh Hạ\", phục vụ du khách đến vùng đất địa đầu cực Nam của Tổ quốc.\n\nNgày 20/10, ông Lý Vỹ Triều Dương, Phó Giám đốc Sở Văn hóa, Thể thao và Du lịch tỉnh Cà Mau, cho biết tỉnh sẽ tổ chức sự kiện chào mừng Ngày Văn hóa Việt Nam (24/11) và Festival tôm Cà Mau lần thứ II năm 2026.\n\nKhẳng định vị thế ngành tôm Cà Mau\n\nSự kiện này có chủ đề \"Bừng sáng bản sắc văn hóa - Tôm Cà Mau vươn tầm thế giới\", với quy mô hàng nghìn người tham dự, diễn ra từ 21 đến 25/11.\n\nTheo kế hoạch, chương trình khai mạc dự kiến diễn ra tối 21/11 và bế mạc ngày 25/11 tại Quảng trường Phan Ngọc Hiển, phường An Xuyên.\n\nSự kiện Festival tôm sẽ có nhiều hoạt động như: Không gian trưng bày các sản phẩm đặc trưng của Cà Mau và các địa phương; hội nghị phát triển ngành hàng tôm Việt Nam; ngày hội việc làm; quảng diễn chế biến món ăn từ tôm, cua Cà Mau.\n\nNgoài ra, còn có các hoạt động vui chơi giải trí nhằm thu hút khách tham quan, dự kiến có bắt tôm trong hồ/bể nhanh nhất, câu tôm càng xanh, phân loại tôm nhanh, xếp hình mô hình \"con tôm Cà Mau\", biểu diễn hóa trang \"tôm vui\".\n\nVới sự kiện chào mừng Ngày Văn hóa Việt Nam, có các hoạt động nổi bật như: Trình diễn nghệ thuật đêm hội văn hóa các dân tộc tỉnh Cà Mau; không gian văn hóa, ẩm thực và làng nghề truyền thống; liên hoan đờn ca tài tử Nam bộ;…\n\nBên cạnh đó, hoạt động xúc tiến du lịch với chương trình kích cầu \"Về Cà Mau dự Festival tôm, chạm Đất Mũi, khám phá U Minh Hạ\", phục vụ du khách đến vùng đất địa đầu cực Nam của Tổ quốc cũng được tỉnh Cà Mau triển khai dịp này.\n\n\"Chương trình với sự liên kết doanh nghiệp xây dựng các tour, combo ưu đãi Festival - Đất Mũi - U Minh Hạ - du lịch cộng đồng, triển khai ưu đãi lưu trú, ăn uống, vận chuyển, tham quan và trải nghiệm\", theo lãnh đạo Sở Văn hóa, Thể thao và Du lịch tỉnh Cà Mau.\n\nQua sự kiện này, Cà Mau kỳ vọng thu hút du khách, khuyến khích khách tham quan nhiều điểm, lưu trú lâu hơn, tăng chi tiêu, góp phần quảng bá, khơi dậy niềm tự hào và khát vọng xây dựng quê hương Cà Mau phát triển bền vững.\n\nTheo UBND tỉnh Cà Mau, sự kiện chào mừng Ngày Văn hóa Việt Nam và Festival tôm Cà Mau được tổ chức nhằm tuyên truyền, giới thiệu, tôn vinh những giá trị tốt đẹp của văn hóa Việt Nam và văn hóa, con người vùng đất Cà Mau.\n\nĐồng thời, qua sự kiện này quảng bá hình ảnh, tiềm năng, khẳng định vị thế ngành tôm Cà Mau, góp phần nâng cao giá trị và sức cạnh tranh, thương hiệu tôm Cà Mau trên thị trường trong nước và quốc tế.\n\nĐâu là điểm nhấn của sự kiện?\n\nTrả lời câu hỏi của phóng viên Dân trí về điểm nhấn của sự kiện Ngày Văn hóa Việt Nam, ông Dương cho biết tinh thần của sự kiện là sự lan tỏa rộng khắp, để tất cả người dân cùng hưởng thụ, trải nghiệm giá trị văn hóa, trong đó có đồng bào 3 dân tộc Kinh, Hoa, Khmer.\n\nTheo ông Dương, điểm nhấn chính là hoạt động đêm hội văn hóa các dân tộc tỉnh Cà Mau diễn ra ngày 22/11, gắn với chương trình diễu hành, biểu diễn đường phố của 64 xã, phường.\n\n\"Hoạt động này sẽ hình thành không gian văn hóa đặc sắc của các dân tộc, địa phương\", ông Dương cho hay.\n\nVề điểm nhấn của sự kiện Festival tôm Cà Mau, ông Phạm Văn Mười, Phó Giám đốc Sở Nông nghiệp và Môi trường tỉnh Cà Mau, cho biết tất cả các hoạt động của sự kiện đều gắn với ngành tôm.\n\n\"Trọng tâm là tổ chức hội nghị ngành tôm, kết nối cung cầu do Bộ Nông nghiệp và Môi trường cùng UBND tỉnh chủ trì. Các hội nghị mong muốn góp phần thúc đẩy, quảng bá ngành tôm Cà Mau với thị trường trong và ngoài nước\", ông Mười thông tin.","author":"Huỳnh Hải","category":"Du lịch","publishedAt":"2026-10-20 13:41","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/ve-ca-mau-du-festival-tom-cham-dat-mui-kham-pha-u-minh-ha-20261020134104178.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/oCICS8zz4u3vTuJ6t9flWzDwXBg=/zoom/1200_630/2026/10/20/tom-ca-mauhuynh-hai-cropped-1792485053033.jpg?watermark=v1","crawledAt":"2026-10-21T13:42:50.584Z"},{"id":"dtri-20261020110946650","title":"Đại Quang Minh bị phạt vì bán nhà cho người nước ngoài nhưng chậm thông báo","slug":"dai-quang-minh-bi-phat-vi-ban-nha-cho-nguoi-nuoc-ngoai-nhung-cham-thong-bao","excerpt":"UBND TPHCM xử phạt Công ty Địa ốc Đại Quang Minh số tiền 875 triệu đồng do chậm thông báo đến Sở Xây dựng khi bán 87 căn hộ cho tổ chức, cá nhân nước ngoài tại Thủ Thiêm.","content":"(Dân trí) - UBND TPHCM xử phạt Công ty Địa ốc Đại Quang Minh số tiền 875 triệu đồng do chậm thông báo đến Sở Xây dựng khi bán 87 căn hộ cho tổ chức, cá nhân nước ngoài tại Thủ Thiêm.\n\nUBND TPHCM vừa ban hành quyết định xử phạt vi phạm hành chính đối với Công ty CP Đầu tư Địa ốc Đại Quang Minh với tổng số tiền phạt là 875 triệu đồng. Doanh nghiệp này bị phạt do không thực hiện đúng quy định về việc thông báo thông tin khi bán nhà cho các tổ chức, cá nhân nước ngoài.\n\nTheo quyết định xử phạt, Công ty Đại Quang Minh đã có hành vi bán căn hộ cho nhóm khách hàng nước ngoài nhưng chậm gửi thông báo bằng thư điện tử và văn bản đến Sở Xây dựng về tên người mua, địa chỉ nhà ở đã bán tại các dự án thuộc Khu đô thị mới Thủ Thiêm, phường An Khánh.\n\nCụ thể, doanh nghiệp này chậm thông báo đối với 9 căn hộ tại dự án Khu nhà ở thấp tầng (Khu II), trong đó có 6 căn thuộc dự án thành phần 2 và 3 căn thuộc chung cư thấp tầng C1 (dự án thành phần 6).\n\nCùng lỗi vi phạm này, công ty còn chậm thông báo về việc bán 16 căn hộ cho khách nước ngoài tại chung cư C1 thuộc dự án Khu nhà ở thấp tầng (Khu III) và 62 căn hộ tại lô 6-9 thuộc dự án Khu nhà ở phức hợp, thương mại, dịch vụ tổng hợp đa chức năng và bệnh viện quốc tế (Khu VI).\n\nCăn cứ Điều 64 Nghị định số 339/2026/NĐ-CP, nhà chức trách áp dụng mức phạt 295 triệu đồng cho nhóm 9 căn hộ đầu tiên do có một tình tiết tăng nặng, đồng thời phạt 290 triệu đồng cho mỗi nhóm hành vi vi phạm còn lại. Tổng mức phạt là 875 triệu đồng.\n\nDoanh nghiệp không bị áp dụng hình thức phạt bổ sung hay biện pháp khắc phục hậu quả, nhưng buộc phải nộp đủ tiền phạt vào tài khoản Kho bạc Nhà nước trong thời hạn 10 ngày kể từ ngày nhận quyết định; nếu quá hạn sẽ phải chịu thêm tiền phạt chậm nộp 0,05% mỗi ngày trên tổng số tiền phạt chưa nộp.\n\nTheo Luật Nhà ở 2023, tổ chức, cá nhân nước ngoài chỉ được mua và sở hữu không quá 30% số căn hộ trong một tòa chung cư (hoặc không quá 250 căn nhà trong một khu vực có quy mô dân số tương đương một phường).\n\nĐể giám sát tỷ lệ trên, quy định hiện hành yêu cầu bên bán nhà hay căn hộ trong thời hạn tối đa 3 ngày làm việc, kể từ ngày ký hợp đồng mua bán, phải thông báo bằng thư điện tử và bằng văn bản về tên người mua, địa chỉ nhà ở đã bán đến cơ quan quản lý nhà ở cấp tỉnh (Sở Xây dựng) để đăng tải trên cổng thông tin điện tử của cơ quan này.","author":"Ngọc Tân","category":"Bất động sản","publishedAt":"2026-10-20 11:09","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/dai-quang-minh-bi-phat-vi-ban-nha-cho-nguoi-nuoc-ngoai-nhung-cham-thong-bao-20261020110946650.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/2KZQIzTy-EBsk0fn7-q-Vodykxk=/zoom/1200_630/2026/10/20/thuthiembaoquyen-1779468695333-cropped-1792467307697.jpg","crawledAt":"2026-10-21T13:43:02.579Z"},{"id":"dtri-20261020105907856","title":"Cà Mau thông báo cho thuê 22 cơ sở nhà, đất dôi dư","slug":"ca-mau-thong-bao-cho-thue-22-co-so-nha-dat-doi-du","excerpt":"Nhiều cơ sở nhà, đất, trụ sở dôi dư được tỉnh Cà Mau cho thuê trong khoảng thời gian 3-5 năm.","content":"(Dân trí) - Nhiều cơ sở nhà, đất, trụ sở dôi dư được tỉnh Cà Mau cho thuê trong khoảng thời gian 3-5 năm.\n\nTrung tâm Phát triển quỹ đất tỉnh Cà Mau vừa có thông báo cho thuê 22 cơ sở nhà, đất dôi dư tại các xã, phường do đơn vị này quản lý, khai thác.\n\nTại khu vực Bạc Liêu có 11 cơ sở, được cho thuê theo phương thức chào giá cạnh tranh, với giá sàn cho thuê từ 287.000 đồng đến hơn 2,5 triệu đồng/m2/năm.\n\nCụ thể, cơ sở nhà, đất trụ sở UBND phường 7 (cũ) có diện tích đất hơn 1.172m2, sàn sử dụng nhà khoảng 710m2.\n\nCơ sở này nằm ngay góc ngã tư đường Trần Phú và Trần Huỳnh, được đánh giá là một trong những vị trí đẹp của trung tâm phường Bạc Liêu, cho thuê cao nhất với giá sàn hơn 2,5 triệu đồng/m2/năm.\n\nThấp nhất là cơ sở nhà, đất Hội Cựu tù chính trị, cựu thanh niên xung phong (phường Vĩnh Trạch) có diện tích đất 203m2, sàn nhà 495m2, được cho thuê giá 287.000 đồng/m2/năm,...\n\nTại khu vực Cà Mau có 11 khu đất, thửa đất được cho thuê ngắn hạn trong thời gian 3 năm, với giá từ 1.237 đồng đến 682.000 đồng/m2/năm.\n\nĐơn cử như khu đất Công ty Cổ phần văn hóa tổng hợp Cà Mau (phường An Xuyên) có diện tích 654m2, được cho thuê với giá 682.605 đồng/m2/năm.\n\nTrong khi đó, có 4 khu đất được cho thuê với giá dưới 10.000 đồng/m2/năm. Cụ thể, thấp nhất là khu đất Nhà máy đường xã Trí Phải, diện tích hơn 66.600m2, giá cho thuê chỉ 1.237 đồng/m2/năm.\n\nTiếp đó là khu đất Trường Cao đẳng cộng đồng cơ sở 2 (phường An Xuyên) có diện tích hơn 407m2, với giá cho thuê 3.896 đồng/m2/năm.\n\nKhu đất trạm y tế xã Đất Mới cũ (xã Đất Mới) có diện tích 345m2, được cho thuê giá 5.640 đồng/m2/năm,...\n\nTheo Trung tâm Phát triển quỹ đất tỉnh Cà Mau, các tổ chức, cá nhân có nhu cầu thuê nhà, đất có thể liên hệ trung tâm để thực hiện các thủ tục cần thiết.","author":"Huỳnh Hải","category":"Bất động sản","publishedAt":"2026-10-20 10:59","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/ca-mau-thong-bao-cho-thue-22-co-so-nha-dat-doi-du-20261020105907856.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/jnrnC4cY07kJUg68WbIRcyDrrXE=/zoom/1200_630/2026/10/21/co-so-nha-dat-doi-du-ca-mauhuynh-hai-cropped-1792547743427.jpg?watermark=v1","crawledAt":"2026-10-21T13:42:59.292Z"},{"id":"dtri-20261020103504921","title":"4 cách dùng đá và gạch ốp lát nâng tầm nhà đẹp, sang trọng","slug":"4-cach-dung-da-va-gach-op-lat-nang-tam-nha-dep-sang-trong","excerpt":"Không cần chi tiền tỷ đập đi xây lại, bạn chỉ cần phối hợp khéo léo đá tự nhiên và gạch ốp lát theo 4 cách dưới đây để biến từng góc nhỏ trong nhà trở nên sang trọng, tinh tế hơn.","content":"(Dân trí) - Không cần chi tiền tỷ đập đi xây lại, bạn chỉ cần phối hợp khéo léo đá tự nhiên và gạch ốp lát theo 4 cách dưới đây để biến từng góc nhỏ trong nhà trở nên sang trọng, tinh tế hơn.\n\nNhiều người có quan niệm rằng muốn nhà sang thì phải ốp đá kín mít từ sàn lên tường. Cách làm này không chỉ tốn kém mà còn dễ khiến không gian sinh hoạt trở nên lạnh lẽo, nặng nề.\n\nThực tế, một ngôi nhà đẹp chỉ cần vài nét chấm phá vừa vặn. Khéo léo đưa đá tự nhiên và gạch ốp lát vào các vị trí đắt giá, tổ ấm của bạn sẽ toát lên vẻ chỉn chu và bừng sáng diện mạo mới.\n\nTạo ấn tượng ở lối vào bằng gạch ghép hoa văn\n\nKhu vực cửa chính hay tiền sảnh là nơi đón tiếp khách quý, đồng thời tạo cảm giác thư thái khi bạn trở về nhà sau ngày dài. Thay vì chọn gạch men trơn quen thuộc, bạn hãy thử lát sàn lối vào bằng gạch ghép hoa văn từ đá cẩm thạch.\n\nNhững đường lượn sóng hoặc họa tiết hình học cổ điển trên nền đá sáng giúp phân tách không gian sảnh rất tinh tế. Chuyên gia nội thất khuyên bạn nên chọn kích cỡ gạch nhỏ nhắn, vừa vặn với diện tích tiền sảnh để tạo nét duyên dáng mà không làm không gian bị chật chội.\n\nBiến bàn đảo bếp thành tâm điểm cuốn hút\n\nCăn bếp trong các gia đình ngày nay là trung tâm kết nối mọi người cùng nấu nướng, quây quần. Nếu có điều kiện đầu tư, một chiếc bàn đảo ốp đá cẩm thạch với đường vân lớn uốn lượn sẽ là tác phẩm nghệ thuật nổi bật nhất gian bếp.\n\nBạn có thể ốp đá tràn từ mặt bàn xuống các cạnh tủ bên dưới để tạo cảm giác nguyên khối vững chãi. Để tổng thể liền mạch, chuyên gia gợi ý bạn dùng thêm gạch đá ốp tường bếp phía sau bồn rửa và bệ cửa sổ, vừa giúp việc lau chùi dầu mỡ dễ dàng, vừa tăng chiều sâu cho căn phòng.\n\nĐưa trải nghiệm thư giãn vào phòng tắm\n\nSau giờ làm việc căng thẳng, phòng tắm là nơi mọi người trút bỏ mệt mỏi. Bạn hoàn toàn có thể biến nơi này thành góc thư giãn đậm chất nghỉ dưỡng nhờ việc kết hợp hai loại vân đá đối lập nhau.\n\nBạn hãy dùng gạch đá cẩm thạch tông sáng lát nền và ốp quanh tường nhằm mở rộng không gian. Tiếp đó, bạn tạo điểm nhấn thị giác bằng phiến đá có đường vân đậm màu quanh bồn tắm hoặc tại các hốc tường để dầu gội, sữa tắm. Sự kết hợp khéo léo này giúp phòng tắm luôn sạch sẽ, thoáng mát và sang trọng như spa.\n\nLàm mới phòng khách bằng bàn trà mặt đá\n\nNếu ngại việc sửa nhà bụi bặm, bạn chỉ cần bổ sung một món đồ rời bằng đá tự nhiên. Một chiếc bàn trà hoặc bàn phụ có mặt đá cẩm thạch đặt cạnh bộ ghế sofa sẽ thay đổi diện mạo cả căn phòng ngay tức thì.\n\nMặt đá mát lạnh, phẳng phiu tạo sự tương phản đầy thú vị với các chất liệu mềm mại như thảm trải sàn, rèm cửa hay đệm bọc ghế. Chuyên gia khuyên bạn nên chọn mặt đá có tông màu ấm như san hô, hổ phách hoặc vàng kem để phòng khách luôn giữ được cảm giác ấm áp và gần gũi.","author":"Niên Vũ","category":"Bất động sản","publishedAt":"2026-10-20 10:35","source":"dantri.com.vn","url":"https://dantri.com.vn/bat-dong-san/4-cach-dung-da-va-gach-op-lat-nang-tam-nha-dep-sang-trong-20261020103504921.htm","categories":["Bất động sản"],"categoryIds":["bat-dong-san"],"thumbnail":"https://cdnphoto.dantri.com.vn/5SVPgXgbM3xsqGj0ZX3tVvKuQfM=/zoom/1200_630/2025/10/23/how-to-choose-kitchen-countertops-realsimple-gettyimages-673984158-c0472518759444d68bd9ee1d95306308-cropped-1761208551485.jpg","crawledAt":"2026-10-21T13:43:00.370Z"},{"id":"dtri-20261020102745731","title":"TPHCM mở rộng diện khám sức khỏe miễn phí cho người chưa đăng ký tạm trú","slug":"tphcm-mo-rong-dien-kham-suc-khoe-mien-phi-cho-nguoi-chua-dang-ky-tam-tru","excerpt":"TPHCM mở rộng diện khám sức khỏe định kỳ miễn phí cho người chưa đăng ký thường trú, tạm trú nhưng có thông tin nơi ở được xác thực qua VNeID mức độ 2.","content":"(Dân trí) - TPHCM mở rộng diện khám sức khỏe định kỳ miễn phí cho người chưa đăng ký thường trú, tạm trú nhưng có thông tin nơi ở được xác thực qua VNeID mức độ 2.\n\nPGS.TS.BS Tăng Chí Thượng, Giám đốc Sở Y tế TPHCM, cho biết UBND TPHCM đã chấp thuận mở rộng đối tượng thụ hưởng chính sách khám sức khỏe định kỳ miễn phí.\n\nTheo đó, công dân Việt Nam chưa đủ điều kiện đăng ký thường trú, tạm trú tại thành phố nhưng có thông tin nơi ở hiện tại trên địa bàn được xác thực bằng tài khoản định danh điện tử mức độ 2 trên VNeID sẽ được tổ chức khám sức khỏe miễn phí.\n\nChủ trương này nhằm tạo điều kiện để người dân đang sinh sống thực tế tại TPHCM được tiếp cận chương trình, mở rộng độ bao phủ và hạn chế bỏ sót đối tượng.\n\nTheo số liệu tính đến ngày 19/10, TPHCM ghi nhận hơn 6,3 triệu người được khám sức khỏe, khám sàng lọc.\n\nTrong đó, có hơn 1,2 triệu người lao động (27,7%), gần 2,3 triệu học sinh (87,1%) và gần 130.000 sinh viên (29,3%).\n\nTiến độ khám sức khỏe đối với học sinh đạt tỷ lệ khá cao, trong khi nhóm người lao động và sinh viên cần tiếp tục được tập trung triển khai trong thời gian tới.\n\nVề kết quả thực hiện tại địa phương, có 86/168 phường, xã, đặc khu đạt tỷ lệ cộng dồn từ 50% trở lên. Trong đó, 47 địa phương đạt từ 60%, 22 địa phương đạt từ 70% và 7 địa phương đạt từ 80% trở lên.\n\nHiện còn 2 địa phương có tỷ lệ dưới 30% là phường Cầu Ông Lãnh và phường Phú Thạnh.\n\nTrong công tác đánh giá chất lượng khám sức khỏe toàn dân, tính đến ngày 19/10, Sở Y tế TPHCM đã kiểm tra, đánh giá 50 cơ sở. Kết quả, có 22 cơ sở xếp loại A, chiếm 44%; 28 cơ sở xếp loại B, chiếm 56%; chưa ghi nhận cơ sở xếp loại C.\n\nMột số đơn vị đạt kết quả nổi bật gồm Bệnh viện Đa khoa Bình Dương, Bệnh viện Nhân dân 115, Bệnh viện Đa khoa khu vực Củ Chi, Trung tâm Y tế khu vực Dĩ An và Bệnh viện Lê Văn Thịnh.\n\nTheo đánh giá của ngành y tế, kết quả bước đầu cho thấy các cơ sở đã nỗ lực trong tổ chức triển khai và đáp ứng yêu cầu của Bộ tiêu chí đánh giá chất lượng khám sức khỏe toàn dân.\n\nThời gian tới, Sở Y tế sẽ tiếp tục mở rộng hoạt động đánh giá đến các phòng khám đa khoa tư nhân; hướng dẫn, hỗ trợ các cơ sở cải tiến chất lượng, đồng thời phát hiện và giới thiệu nhân rộng những mô hình, cách làm hiệu quả.\n\nSở Y tế đề nghị UBND 168 phường, xã, đặc khu tiếp tục duy trì, đẩy mạnh tổ chức khám sức khỏe cho người dân trên địa bàn, nhất là người lao động, sinh viên và các nhóm chưa được khám.\n\nCác địa phương được yêu cầu khẩn trương rà soát, bổ sung danh sách những đối tượng mới được mở rộng. Ngoài ra phối hợp với công an địa phương xác thực thông tin cư trú trên VNeID, lập dự toán kinh phí và tổ chức khám sức khỏe theo quy định.","author":"Thảo Phương","category":"Sức khỏe","publishedAt":"2026-10-20 10:27","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/tphcm-mo-rong-dien-kham-suc-khoe-mien-phi-cho-nguoi-chua-dang-ky-tam-tru-20261020102745731.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/t0NjoIc65IoZNJJEyCGY1_yJnDg=/zoom/1200_630/2026/10/20/kham-suc-khoe-cropped-1792466766424.jpg?watermark=v1","crawledAt":"2026-10-21T13:42:37.899Z"},{"id":"dtri-20261020101529140","title":"“Chàng Kiều Phong” lãng tử của màn ảnh Hoa ngữ Hồ Quân giờ ra sao?","slug":"chang-kieu-phong-lang-tu-cua-man-anh-hoa-ngu-ho-quan-gio-ra-sao","excerpt":"Hơn 20 năm sau khi “Thiên long bát bộ” lên sóng, Hồ Quân vẫn được nhắc đến khi khán giả nói về nhân vật Kiều Phong. Vẻ ngoài phong trần, khí chất hào sảng tạo nên hình tượng anh hùng võ hiệp khó quên.","content":"Vai diễn để đời trong \"Thiên long bát bộ\" 2003\n\nTrong số những diễn viên từng hóa thân thành Kiều Phong trên màn ảnh, Hồ Quân là một trong những gương mặt để lại dấu ấn sâu đậm. Phiên bản Kiều Phong của anh được yêu thích nhờ sự kết hợp giữa vẻ mạnh mẽ, ngang tàng của một cao thủ võ lâm và những giằng xé nội tâm của người anh hùng mang số phận bi thương.\n\nRa mắt năm 2003, Thiên long bát bộ do Trương Kỷ Trung sản xuất quy tụ dàn diễn viên gồm Hồ Quân, Lâm Chí Dĩnh, Cao Hổ, Lưu Diệc Phi, Lưu Đào và Trần Hảo. Tác phẩm được đầu tư lớn về bối cảnh, phục trang và các cảnh võ thuật, trở thành một trong những bản chuyển thể đáng nhớ từ tiểu thuyết cùng tên của nhà văn Kim Dung.\n\nTrong phim, Hồ Quân đảm nhận vai Kiều Phong, bang chủ Cái Bang nổi tiếng với võ công cao cường, tính cách hào sảng và tinh thần trọng nghĩa. Cuộc đời nhân vật bước sang bi kịch khi thân thế người Khiết Đan bị phơi bày, khiến anh từ một anh hùng được kính trọng trở thành người bị đồng đạo võ lâm nghi kỵ.\n\nKhông chỉ gây ấn tượng trong những màn giao đấu, Hồ Quân còn thể hiện thuyết phục sự cô độc, đau đớn của Kiều Phong khi phải lựa chọn giữa tình riêng, nghĩa lớn và những xung đột dân tộc. Mối tình với A Châu do Lưu Đào thủ vai càng khiến bi kịch của nhân vật trở nên ám ảnh.\n\nChính sự kết hợp giữa khí chất anh hùng và nỗi đau của một con người bị đặt giữa những xung đột không thể hóa giải đã giúp Kiều Phong trở thành vai diễn có sức sống lâu dài. Nhà sản xuất Trương Kỷ Trung từng chấm phần thể hiện Kiều Phong của Hồ Quân 90 điểm, đồng thời đánh giá đây là vai diễn nổi bật nhất trong dàn nhân vật của phim.\n\nTrước đó, khi tuyển diễn viên cho Tiếu ngạo giang hồ, ông từng gặp Hồ Quân nhưng không chọn anh vào vai Lệnh Hồ Xung vì cho rằng ánh mắt nam diễn viên quá dữ dội. Tuy nhiên, Trương Kỷ Trung vẫn tin hai người sẽ có cơ hội hợp tác và sau đó chủ động mời anh đóng Kiều Phong. Quyết định này được xem là một trong những lựa chọn diễn viên đáng nhớ của nhà sản xuất.\n\nNăm 2004, bộ phim đứng đầu bảng xếp hạng 10 phim truyền hình được yêu thích nhất Trung Quốc. Phim cũng tạo cơn sốt khi ra mắt khán giả Việt Nam.\n\nMột chi tiết hậu trường cho thấy mức độ đầu tư của nam diễn viên là cảnh thi triển tuyệt kỹ Hàng Long Thập Bát Chưởng. Hồ Quân kể đoàn phim sử dụng hai máy thổi gió để tạo hiệu ứng cho mái tóc và trang phục bay lên, làm nổi bật uy lực của chưởng pháp.\n\nTuy nhiên, gió mạnh khiến tóc che mặt hoặc cát bay vào mắt, buộc ê-kíp quay đi quay lại trong gần 3 giờ. Anh phải liên tục hô lớn khi xuất chưởng, đến mức đau đầu sau cảnh quay. Những nỗ lực đó góp phần tạo nên một Kiều Phong có vẻ ngoài mạnh mẽ và giàu sức thuyết phục.\n\nTừ diễn viên chuyên vai phụ đến ngôi sao được khán giả nhớ mặt\n\nHồ Quân sinh năm 1968 tại Bắc Kinh (Trung Quốc) trong một gia đình có truyền thống nghệ thuật. Cha anh là ca sĩ Hồ Bảo Thiện, còn bác ruột là ca sĩ Hồ Tùng Hoa. Dù lớn lên trong môi trường nghệ thuật, con đường diễn xuất của Hồ Quân không trải đầy thuận lợi.\n\nSau khi tốt nghiệp Học viện Hý kịch Trung ương Trung Quốc, anh hoạt động chủ yếu trên sân khấu kịch nói. Trong những năm đầu sự nghiệp, nam diễn viên thường đảm nhận vai phụ, chưa có nhiều cơ hội thể hiện khả năng ở những dự án lớn.\n\nBước ngoặt đến với Hồ Quân khi anh tham gia bộ phim điện ảnh Lam Vũ (2001), đóng cùng Lưu Diệp. Tác phẩm khai thác chuyện tình giữa hai người đàn ông trong bối cảnh xã hội Trung Quốc đương đại, giúp Hồ Quân nhận được sự chú ý của giới chuyên môn. Vai diễn mang về cho anh đề cử Nam diễn viên chính xuất sắc tại Liên hoan phim Kim Mã năm 2001.\n\nThành công của Lam Vũ góp phần khẳng định năng lực diễn xuất của Hồ Quân, nhưng chính Thiên long bát bộ mới giúp anh mở rộng độ nhận diện với khán giả truyền hình. Từ một diễn viên được giới chuyên môn biết đến qua các vai diễn giàu tính nghệ thuật, anh trở thành gương mặt gắn liền với hình tượng anh hùng võ hiệp.\n\nĐáng chú ý, Hồ Quân từng không đặc biệt yêu thích phim cổ trang. Anh cho biết tình yêu dành cho tiểu thuyết Kim Dung và sự hấp dẫn của nhân vật Kiều Phong là những lý do khiến mình nhận lời tham gia dự án.\n\nKhi đảm nhận vai diễn, anh hiểu sẽ phải đối diện với sự so sánh từ khán giả vốn đã quen thuộc với những phiên bản trước, trong đó có Kiều Phong do Huỳnh Nhật Hoa thể hiện.\n\nThay vì cố gắng sao chép hình tượng có sẵn, Hồ Quân lựa chọn xây dựng nhân vật theo cách riêng. Vóc dáng cao lớn, gương mặt góc cạnh, giọng nói trầm và phong thái có phần hoang dã giúp anh tạo nên một Kiều Phong khác biệt.\n\nVai Kiều Phong cũng giúp Hồ Quân mở rộng đáng kể độ nhận diện, đặc biệt trong nhóm khán giả yêu thích phim kiếm hiệp. Trả lời Sina, khi được hỏi về vai diễn, Hồ Quân cho biết đây là một trong những bộ phim khiến anh cảm thấy thoải mái nhất trong quá trình làm việc.\n\nSau thành công của bộ phim, Hồ Quân tiếp tục tham gia nhiều dự án điện ảnh và truyền hình thuộc các thể loại khác nhau. Anh góp mặt trong Thập diện mai phục, Xích Bích và Trường Tân Hồ. Các vai diễn cho thấy nam diễn viên không chỉ phù hợp với hình tượng võ hiệp mà còn có khả năng đảm nhận những nhân vật lịch sử, quân nhân và người đàn ông mang nội tâm phức tạp.\n\nCuộc hôn nhân bền bỉ với người vợ cùng trường\n\nNếu trên màn ảnh, Hồ Quân gắn liền với hình tượng người đàn ông hào sảng, mạnh mẽ, thì ngoài đời, anh được chú ý bởi cuộc sống gia đình kín tiếng bên người vợ Lư Phương.\n\nHồ Quân hạnh phúc bên vợ và các con (Ảnh: Weibo).\n\nHai người quen nhau khi cùng theo học tại Học viện Hý kịch Trung ương. Sau khi tốt nghiệp, con đường sự nghiệp của họ có những khác biệt. Lư Phương sớm có cơ hội đảm nhận vai chính trên sân khấu, trong khi Hồ Quân vẫn trải qua giai đoạn khó khăn với những vai diễn nhỏ.\n\nDù vậy, khoảng cách trong sự nghiệp không khiến tình cảm của hai người rạn nứt. Họ kết hôn năm 1999 và lần lượt đón con gái Hồ Duyệt Gia vào năm 2001, con trai Hồ Hạo Khang vào năm 2008.\n\nLư Phương là diễn viên sân khấu có năng lực, từng tham gia nhiều vở kịch tại Nhà hát Nghệ thuật Nhân dân Bắc Kinh. Sau khi lập gia đình, cô giảm bớt hoạt động nghệ thuật để dành nhiều thời gian chăm sóc các con.\n\nTrong những cuộc phỏng vấn, Hồ Quân từng bày tỏ sự trân trọng đối với những đóng góp của vợ cho gia đình và sự nghiệp của anh. Nam diễn viên cũng thường chia sẻ những khoảnh khắc bên các con, cho thấy một hình ảnh đời thường gần gũi hơn so với vẻ ngoài mạnh mẽ trên màn ảnh.\n\nNăm 2015, anh cùng con trai tham gia chương trình truyền hình thực tế Bố ơi, mình đi đâu thế? mùa thứ ba tại Trung Quốc, qua đó được khán giả biết đến nhiều hơn trong vai trò người cha.\n\nCuộc hôn nhân của Hồ Quân và Lư Phương không thường xuyên trở thành đề tài bàn tán trên truyền thông. Sau hơn 20 năm chung sống, cả hai vẫn giữ lối sống tương đối kín tiếng, hạn chế đưa chuyện riêng tư ra trước công chúng.\n\nỞ tuổi 58 vẫn hoạt động nghệ thuật\n\nBước sang tuổi 58 trong năm 2026, Hồ Quân chưa rời xa màn ảnh. Anh không còn xuất hiện dày đặc như giai đoạn đỉnh cao, nhưng vẫn duy trì hoạt động diễn xuất và lựa chọn các dự án phù hợp. Ngoài các bộ phim truyền hình và điện ảnh, Hồ Quân tham gia một số chương trình giải trí.\n\nHồ Quân đã xây dựng sự nghiệp qua nhiều thể loại, từ sân khấu kịch nói đến điện ảnh nghệ thuật, phim thương mại và truyền hình. Dù vậy, Kiều Phong vẫn là nhân vật gắn bó đặc biệt với tên tuổi nam diễn viên.\n\nHơn 20 năm sau ngày Thiên long bát bộ 2003 ra mắt, hình ảnh người anh hùng mang vẻ ngoài phong trần, trọng nghĩa nhưng phải đối diện với số phận bi thương vẫn được nhiều khán giả nhớ đến. Đó cũng là minh chứng cho sức sống của một vai diễn được xây dựng bằng cả ngoại hình, khí chất và chiều sâu diễn xuất.","author":"Mi Vân","category":"Giải trí","publishedAt":"2026-10-20 10:15","source":"dantri.com.vn","url":"https://dantri.com.vn/giai-tri/chang-kieu-phong-lang-tu-cua-man-anh-hoa-ngu-ho-quan-gio-ra-sao-20261020101529140.htm","categories":["Giải trí"],"categoryIds":["giai-tri"],"thumbnail":"https://cdnphoto.dantri.com.vn/10N2YIsdPmgwQSG-n_NL3LNaG0o=/zoom/1200_630/2026/10/20/ho-quansina-cropped-1792463874828.jpg","crawledAt":"2026-10-21T13:43:12.799Z"},{"id":"dtri-20261020093935017","title":"Làm vườn ở resort 30 triệu đồng/đêm, người phụ nữ hé lộ điều nghiêm ngặt","slug":"lam-vuon-o-resort-30-trieu-dongdem-nguoi-phu-nu-he-lo-dieu-nghiem-ngat","excerpt":"Đến resort để mưu sinh, Ry Nguyễn chọn ở lại vì cây cối và con người. Trò chuyện với phóng viên Dân trí, cô chia sẻ những điều ít biết về công việc chăm vườn tại resort giá hàng chục triệu đồng/đêm.","content":"Một ngày của người chăm cây tại resort cao cấp\n\nSau khi bơi xong vào khoảng 6h30, vị khách người Mỹ cùng con trai thong thả đi bộ trở về villa riêng tại Four Seasons Resort The Nam Hai (Hội An, Đà Nẵng).\n\nTrời trong và mát, hai cha con tản bộ dưới những hàng dừa, đi qua lối nhỏ với hàng cây xanh thẳng tắp và những bụi hoa đang nở ven đường. Người cha quay sang nói với con trai: “What a lovely morning” (tạm dịch: “Buổi sáng thật đẹp”).\n\nVới du khách, đó là một khoảnh khắc thư thái trong kỳ nghỉ.\n\nNhưng để duy trì không gian xanh mát, đội ngũ cảnh quan phải chăm sóc từng ngày. Đứng sau công việc ấy là Ry Nguyễn (SN 1991), quản lý cảnh quan tại khu nghỉ dưỡng, hiện phụ trách gần 100 nhân viên chăm sóc khoảng 35ha cảnh quan.\n\nTốt nghiệp ngành nông nghiệp tại Đại học Nông Lâm TPHCM, cô đã gắn bó với công việc này tại Four Seasons Resort The Nam Hai suốt 10 năm qua.\n\nĐây là khu nghỉ dưỡng nằm bên bãi biển Hà My (Đà Nẵng), có tuổi đời gần 20 năm, gồm 100 biệt thự riêng biệt nằm xen giữa những hàng dừa và khu vườn nhiệt đới hướng ra biển Hà My. Khu nghỉ dưỡng có 8 năm liên tiếp được Forbes Travel Guide xếp hạng 5 sao. Sau gần hai thập kỷ hoạt động, khu nghỉ dưỡng vẫn là một trong những địa chỉ quen thuộc của nhóm khách nghỉ dưỡng cao cấp đến miền Trung.\n\nGhi nhận trên website của khu nghỉ dưỡng, trong tháng 10, giá một số villa dao động khoảng 25-90 triệu đồng/đêm. Chẳng hạn, một villa hướng vườn hiện có giá từ hơn 26 triệu đồng/đêm, dành cho 2-3 người lớn và một trẻ nhỏ.\n\nNếu lựa chọn không gian hướng biển, kèm hồ bơi riêng, mức giá có thể tăng thêm vài chục triệu đồng.\n\nBên cạnh những căn villa có giá hàng chục triệu đồng mỗi đêm, không gian cảnh quan rộng khoảng 35ha phủ kín cây xanh cũng là một điểm tạo ấn tượng với du khách.\n\nNổi bật nhất là hơn 4.500 cây dừa tạo thành những mảng xanh lớn, vừa che bóng vừa bao bọc các khu villa. Xen kẽ là những hàng cây, các loại hoa được chăm chút dọc lối đi và khu vườn canh tác theo hướng hữu cơ rộng 20.000m2, trồng rau, củ, hoa cùng nhiều loại cây ăn trái.\n\nNhìn từ bên ngoài, cảnh quan ấy tạo cảm giác tự nhiên, thoáng đãng và gần như không có sự can thiệp quá rõ của con người. Nhưng để duy trì vẻ “tự nhiên” đó, đội ngũ cảnh quan của Ry Nguyễn phải tuân thủ hàng loạt tiêu chuẩn cụ thể.\n\n“Sự chỉn chu của khu vườn bắt đầu từ những việc rất nhỏ. Cỏ được giữ ở độ cao không quá 5cm, lối đi gọn gàng. Hồ nước được kiểm tra thường xuyên, không được để có rêu hay lá úa. Từ bãi cỏ, lối đi, hồ nước đến bờ biển dài gần 1km, chúng tôi đều chăm chút mỗi ngày để cảnh quan luôn xanh mát, sạch sẽ và tươm tất.\n\nNghe qua có vẻ khắt khe, nhưng khi người làm vườn dành thời gian quan sát và đặt tình yêu vào từng góc nhỏ, việc chăm sóc trở nên dễ dàng hơn”, Ry Nguyễn chia sẻ với phóng viên Dân trí.\n\nTheo Ry Nguyễn, gần 100 nhân viên được phân công chăm sóc từng khu vực, từ tưới cây, chăm hoa đến cắt tỉa và theo dõi thảm cỏ.\n\nNgày làm việc của đội cảnh quan thường bắt đầu từ 6h sáng, khi khu nghỉ dưỡng còn khá yên tĩnh. Những phần việc bên ngoài các villa được ưu tiên hoàn thành trong khoảng thời gian này. Sau giờ nghỉ trưa, đội ngũ tiếp tục công việc từ 13h đến 17h.\n\nVới Ry Nguyễn, việc chăm sóc khu vườn diễn ra cẩn thận và tỉ mỉ, nhưng vẫn luôn giữ gìn không gian riêng của mỗi du khách. Nếu đang làm việc gần hồ bơi nhưng nhận thấy khách đang thư giãn, nhân viên sẽ chủ động chuyển sang khu vực khác và quay lại sau. Đó không hẳn là một quy định bắt buộc, mà dần trở thành sự tinh tế trong cách những người làm vườn làm nghề.\n\n“Chúng tôi muốn mỗi du khách khi đến đây đều có cảm giác như đang trở về nhà, có một không gian riêng để nghỉ ngơi. Vì vậy, người làm vườn luôn biết quan sát để công việc của mình không làm ảnh hưởng đến trải nghiệm của khách”, cô nói.\n\nMột trong những công việc đòi hỏi đội ngũ cảnh quan phải theo dõi thường xuyên là hệ thống cây dừa trải rộng trong khu nghỉ dưỡng. Gần 5.000 cây dừa vừa tạo bóng mát, vừa góp phần hình thành cảnh quan đặc trưng của một khu nghỉ dưỡng ven biển, nhưng đồng thời cũng đặt ra yêu cầu nghiêm ngặt về an toàn.\n\n“Để đảm bảo an toàn cho du khách, chúng tôi không để dừa ra quả. Ngay từ khi cây bắt đầu ra hoa, đội ngũ đã phải kiểm tra và xử lý, không chờ đến khi quả hình thành mới dọn. Công việc này được thực hiện theo một lịch trình liên tục”, cô chia sẻ.\n\nChủ động học tiếng Anh để gần du khách hơn\n\nSinh ra ở Đà Nẵng, lớn lên trong một gia đình làm nông, Ry Nguyễn từ nhỏ đã quen với đất, cây cối và những công việc tưởng như rất đỗi bình thường của nhà nông. Những năm tháng ấy đã gieo vào cô sự gắn bó với thiên nhiên, nên sau này cô chọn học ngành nông nghiệp tại Đại học Nông Lâm TPHCM và tiếp tục theo đuổi công việc chăm sóc cảnh quan.\n\nCô gia nhập Four Seasons Resort The Nam Hai vào năm 2016, đến nay đã tròn 10 năm gắn bó. Với cô, nơi đây dần trở thành “ngôi nhà thứ hai” của mình.\n\n“Khi mới bắt đầu, tôi còn khá trẻ nên đôi lúc thiếu tự tin. Nhưng vì yêu cây cỏ, tôi cứ làm, vừa làm vừa học hỏi. Đến giờ, nhìn những gì mình vun đắp phát triển tốt lên từng ngày, tôi cảm thấy hạnh phúc, giống như người nông dân đến mùa gặt lúa.\n\nNiềm vui ấy không chỉ riêng tôi mà còn là cảm xúc chung của những người làm vườn ở đây. Mỗi lần xuống vườn, thấy một bông hoa mới nở hay một cái cây mình chăm từ lúc còn nhỏ nay phát triển xanh tốt, chúng tôi đều vui. Đó là cảm giác được nhìn thấy thành quả từ chính công sức của mình”, chị Ry chia sẻ.\n\nQuãng thời gian gắn bó với công việc cũng khiến cô có cách nhìn khác về nghề cảnh quan. Nếu trước đây, công việc có thể được hiểu đơn giản là trồng và chăm sóc cây để tạo nên một khu vườn đẹp, thì càng làm lâu, Ry Nguyễn càng nhận ra phía sau những mảng xanh ấy là cả một quá trình tính toán về cây trồng, đất, nước, thời tiết và chu kỳ sinh trưởng.\n\n“Một bông hoa mà du khách nhìn thấy hôm nay có thể đã được đội ngũ lên kế hoạch từ nhiều tháng trước”, cô nói.\n\nMột trong những dấu ấn của Ry Nguyễn là chương trình ủ phân khép kín, tận dụng chất thải hữu cơ từ cắt tỉa và thực phẩm để tạo phân bón cho khu vườn, qua đó giảm rác thải và hạn chế sử dụng phân bón hóa học. “Đó cũng là cách một khu vườn được nuôi dưỡng từ chính những gì nó tạo ra”, cô nói thêm.\n\nLàm việc trong môi trường nghỉ dưỡng quốc tế, tiếng Anh cũng từng là một thử thách với Ry Nguyễn và các nhân viên cảnh quan.\n\n“Với những nhân viên lớn tuổi, có thể chưa giao tiếp tốt, nhưng chúng tôi luôn niềm nở, giao tiếp bằng nụ cười hoặc ngôn ngữ cơ thể. Những câu “Good morning”, “How can I help you” (Chào buổi sáng, Tôi có thể giúp gì cho bạn)... cũng rất đáng quý”, Ry Nguyễn chia sẻ.\n\nBên cạnh công việc chuyên môn, Ry Nguyễn vẫn chủ động trau dồi tiếng Anh để giao tiếp với du khách. Cô duy trì việc học trực tuyến vào khoảng 5h sáng mỗi ngày, tranh thủ thời gian trước khi bắt đầu công việc.\n\n“Việc học giúp tôi tự tin hơn khi có khách dừng lại bên khu vườn, hỏi về một loài hoa hay đơn giản là muốn trò chuyện vài câu”, cô chia sẻ.\n\nKhi được hỏi điều gì khiến mình gắn bó hơn một thập kỷ với khu nghỉ dưỡng, Ry Nguyễn trầm ngâm một lúc rồi chia sẻ: “Ban đầu, có thể tôi đến đây để mưu sinh, nhưng chọn ở lại vì cây cối và con người”.\n\nTình cảm dành cho những người cộng sự cũng là một phần khiến Ry Nguyễn thêm yêu công việc. Theo nữ quản lý, trong đội ngũ có những nhân viên lớn tuổi, nhưng vẫn luôn dành nhiều tâm huyết cho từng hàng cây, khóm hoa, luống rau.\n\n“Có người vào ngày nghỉ phép vẫn quay lại resort một, hai tiếng để tưới cây, kiểm tra thảm cỏ, thăm nom khu vực mình phụ trách rồi mới yên tâm trở về. Nhìn mọi người gắn bó với khu vườn như vậy, tôi càng trân trọng công việc và những người đồng hành cùng mình.\n\nĐôi khi niềm vui của chúng tôi rất đơn giản, chỉ là thấy một vị khách dừng lại chụp ảnh một bụi hoa. Với người làm vườn, đó đã là một thành công rồi”, Ry Nguyễn chia sẻ.","author":"Quỳnh Tâm","category":"Du lịch","publishedAt":"2026-10-20 09:39","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/lam-vuon-o-resort-30-trieu-dongdem-nguoi-phu-nu-he-lo-dieu-nghiem-ngat-20261020093935017.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/D6ijzRbS58DaddNnSRrhNNhzpV4=/zoom/1200_630/2026/10/20/2aobor6kxpupa10melpog59vhkwvmnigpt7put0a-cropped-1792463848330.jpg","crawledAt":"2026-10-21T13:42:50.567Z"},{"id":"dtri-20261020080725335","title":"Phát hiện mới về thuyền cổ được tìm thấy dưới ao ở Bắc Ninh","slug":"phat-hien-moi-ve-thuyen-co-duoc-tim-thay-duoi-ao-o-bac-ninh","excerpt":"Sau khi có kết quả xác định niên đại, nhóm nghiên cứu phân tích các loại hạt, quả được tìm thấy bên trong lòng thuyền cổ ở Bắc Ninh.","content":"(Dân trí) - Sau khi có kết quả xác định niên đại, nhóm nghiên cứu phân tích các loại hạt, quả được tìm thấy bên trong lòng thuyền cổ ở Bắc Ninh.\n\nChuyên gia đánh giá đây là \"báu vật\"\n\nNhư Dân trí đã thông tin, hồi năm 2025, khi cải tạo ao nuôi cá, một nông dân ở khu phố Công Hà (phường Hà Mãn, thị xã Thuận Thành nay là phường Song Liễu, TP Bắc Ninh), tình cờ tìm thấy 2 con thuyền cổ.\n\nSau khi hiện vật phát lộ, các chuyên gia đã lấy mẫu vật, bằng phương pháp C14 đã xác định niên đại của thuyền cổ ở Bắc Ninh khoảng thế kỷ thứ 2, cách ngày nay gần 2.000 năm, tức giai đoạn Đông Sơn muộn.\n\nTrong 1 năm qua, quá trình nghiên cứu vẫn được tiếp tục. Tại Hội thảo \"Báo cáo Khảo cổ học toàn quốc - năm 2026\" mới đây ở Hà Nội, các chuyên gia cũng đưa ra một số thông tin liên quan đến thuyền cổ này.\n\nĐánh giá về cấu trúc 2 thuyền cổ được tìm thấy ở Bắc Ninh, ông Đỗ Thái Bình (Chuyên gia ngành đóng tàu), cho rằng \"báu vật\" này cần được bảo tồn và trưng bày xứng tầm thế giới.\n\nTheo ông Bình, đây là thuyền song thân tức gồm 2 thân được liên kết với nhau, có tác dụng như chiếc phao, tạo sức nổi cho toàn bộ cấu trúc phía trên.\n\nHiện vật thuộc họ thuyền \"phản\", có ở Việt Nam, Nhật Bản, Trung Quốc, không liên quan đến họ thuyền ở phía Nam của Đông Nam Á.\n\nQua tìm hiểu, vị chuyên gia cũng nhận thấy, thanh phụ nằm ở giữa có tác dụng kết nối hai bên yếu nên đã bị mất, còn thanh chính ở đầu đóng vai trò chịu lực chính.\n\n\"Với kết cấu yếu, khả năng đây là phương tiện phục vụ việc di chuyển trên sông, không ra biển hoặc cửa biển - nơi có sóng lớn\", ông Bình nói.\n\nVị chuyên gia cho rằng, phần cấu trúc phía trên rộng hơn 100m2 có thể là lầu - nơi sinh hoạt cho các bậc quyền quý, vua chúa hoặc tộc trưởng. Thuyền di chuyển bằng mái chèo, sào và điều chỉnh hướng bằng hai bánh lái ở đuôi.\n\nNêu quan điểm về vấn đề này, TS Nguyễn Việt (Giám đốc Trung tâm Tiền sử Đông Nam Á), cho rằng qua nghiên cứu, ông nhận thấy cấu trúc thuyền được phát hiện ở Bắc Ninh đang bị nghiêng khoảng 10 độ. Một phía hướng về bờ, còn một đầu hướng ra sông nên tình trạng bảo tồn hai bên không giống nhau.\n\n\"Tôi nghi ngờ đây là cấu trúc nổi được liên kết với khu vực ven bờ, cần mở rộng phạm vi khai quật để tìm hiểu mối liên hệ giữa bờ với cấu trúc này\", vị chuyên gia khảo cổ học nói.\n\nTheo ông Việt, một điểm đáng chú ý là cấu trúc này có phần đáy tương đối cân bằng, các bộ phận được bố trí theo chiều ngang và hai đầu có hình dáng gần giống nhau, chưa phân biệt rõ ràng đầu và đuôi. Bên cạnh đó, các nhà khảo cổ học cũng chưa tìm được bằng chứng về bộ phận tạo lực đẩy, dây kéo hay cột chèo...\n\n\"Tôi thiên về giả thuyết đây là một cấu trúc nổi, thay vì một con thuyền thông thường vốn có hình dạng đầu và đuôi được thiết kế khác nhau nhằm đáp ứng yêu cầu di chuyển trên mặt nước\", vị chuyên gia bày tỏ.\n\nPhân tích hạt, quả bên trong\n\nThời gian qua, nhóm nghiên cứu đã lấy mẫu đất trong các khoang thuyền, tiến hành sàng nhằm tìm hiểu giá trị kinh tế, văn hóa của bộ sưu tập thực vật hàng hóa hay lắng đọng tự nhiên.\n\nTheo TS Nguyễn Thị Mai Hương (Viện Khảo cổ học), thuyền chìm trong môi trường đất ngập nước ven sông (yếm khí) - tạo yếu tố cốt lõi ngăn chặn phân hủy sinh học. Trầm tích sét bùn bao phủ, tạo vi môi trường bảo quản gần như cách ly hoàn toàn với không khí và nước ngầm giàu oxy.\n\nQua quá trình xử lý và phân loại sơ bộ, nhóm nhận thấy độ phong phú của bộ sưu tập. Trong 12 khoang có ghi nhận được hạt mơ, mận, sấu, đậu, quả gỗ kích thước lớn và trám.\n\nVật liệu thực vật được phân bố khá đồng đều từ khoang 1 đến khoang 6 ở hai thuyền, mật độ tăng dần từ mũi (khoang 1) đến vị trí lái thuyền (khoang 6). Trong đó, các khoang gần lái có mật độ mảnh hạt/quả cao nhất. Điều này có thể nhận định giữa và đuôi thuyền được dùng chứa hàng hóa lương thực dự trữ.\n\nỞ thuyền 1, các chuyên gia tìm thấy cuống quả dẻ, hạt xoan, hạt sấu, vỏ hạt mơ/mận và 48 mẫu là hạt không xác định được.\n\nỞ thuyền 2, các khoang 5 và 6 gần vị trí lái ghi nhận mức độ tích tụ dày đặc nhất. Khoang 6 có 1.842 mảnh hạt và quả và 255 mảnh gỗ không xác định.\n\nCó những mẫu không xuất hiện ở thuyền 1 như hạt gấc, vỏ cây dứa dại, hạt sứ quân tử, quả hạt của nhóm sanh, si, sung/vả...\n\nTrong số các mẫu tìm được, cây ăn quả bản địa chiếm số lượng lớn nhất. Cụ thể, hạt/quả sấu có tới 129 mẫu. Cây sấu phân bố nhiều ở Bắc Bộ, dùng nấu canh, làm mứt...\n\nMảnh vỏ hạt thuộc họ mơ/mận phần lớn là mảnh vỡ, có thể do chế biến thực phẩm hoặc quá trình trầm tích lắng đọng lại.\n\nNgoài ra, nhóm nghiên cứu xác định được 53 mẫu là hạt xoan, 31 mẫu hạt trám, 30 mẫu hạt táo, và 11 mẫu sơ ri.\n\nVề các loại cây có hạt và quả gỗ, TS Nguyễn Thị Mai Hương cho biết, có 13 mẫu cuống quả dẻ - đây là cây rừng lớn, phân bố chủ yếu ở đồi núi trung du.\n\n\"Sự xuất hiện cuống quả dẻ trong thuyền đồng bằng gợi ý giao lưu thương mại giữa miền núi - đồng bằng sông Hồng\", vị chuyên gia nói.\n\nTrong khi đó, gai cây gạo có 28 mẫu. Đây là loài bản địa vùng nhiệt đới ẩm, có thể phản ánh vị trí neo đậu dưới tán cây gạo ven sông...\n\nTuy nhiên, không phải mọi hạt, quả được tìm thấy đều là hàng hóa. Dựa theo các tiêu chí phân loại, nhóm nhận định hàng hóa vận chuyển là trám, cuống quả dẻ, sứ quân tử, gấc được đưa từ vùng núi xuống. Còn gai cây gạo, dây leo, mảnh gỗ không xác định được là lắng đọng tự nhiên. Trong khi đó, hạt sấu, xoan, táo ta, sơ ri có thể là hàng hóa và lắng đọng tự nhiên.\n\n\"Sự xuất hiện của sản phẩm rừng nhiệt đới (dứa dại, gấc) và sản phẩm ôn đới vùng cao (dẻ, mơ/mận) là bằng chứng sinh động về mạng lưới trao đổi hàng hóa, giao lưu thương mại bằng đường sông phát triển mạnh mẽ\", bà Hương đánh giá.","author":"Trần Thành Công","category":"Đời sống","publishedAt":"2026-10-20 08:07","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/phat-hien-moi-ve-thuyen-co-duoc-tim-thay-duoi-ao-o-bac-ninh-20261020080725335.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/C0tGMK323721_iGBwCY1sPhIxoQ=/zoom/1200_630/2025/03/24/thuyen-co-bac-ninh-3-crop-crop-1742801378119.jpeg","crawledAt":"2026-10-21T13:42:43.309Z"},{"id":"dtri-20261019235948208","title":"Khách Việt chi 65 triệu đồng, tới ga tàu như cung điện lòng đất ở Nga","slug":"khach-viet-chi-65-trieu-dong-toi-ga-tau-nhu-cung-dien-long-dat-o-nga","excerpt":"Trong chuyến đi tới Nga kéo dài hơn 10 ngày, anh Trịnh Ngọc Sáng dành 3 ngày khám phá thủ đô Moscow. Vị khách đặc biệt ấn tượng với các ga tàu điện ngầm thiết kế như cung điện dưới lòng đất.","content":"Trong chuyến du lịch tới Nga hơn 10 ngày cùng nhóm bạn, anh Trịnh Ngọc Sáng đến từ Hà Nội có hành trình từ thủ đô Moscow tới Murmansk ngắm cực quang. Sau đó, nhóm khách Việt trải nghiệm cảnh sắc ở hồ nước ngọt lớn nhất thế giới - hồ Baikal đóng băng vào mùa đông.\n\nAnh Sáng dành 3 ngày để vui chơi tại Moscow. Trong đó, vị khách Hà Nội đặc biệt ấn tượng với hệ thống ga tàu điện ngầm của thủ đô nước Nga - nơi được thiết kế như những cung điện ngầm dưới lòng đất.\n\nTrong 3 ngày, anh Sáng mua vé không giới hạn lượt đi với giá 800 ruble (250.000 đồng). Nếu khách đi một ngày có thể chọn loại vé có giá 400 ruble (125.000 đồng).\n\n\"Du khách tới Nga thường chọn đi tàu điện ngầm vì chi phí tốt, tiện lợi. Hầu như các điểm du lịch chỉ cách ga tàu điện ngầm vài trăm mét. Mỗi ngày tôi đi metro gần 10 lượt để trải nghiệm trọn vẹn\", anh Sáng nói.\n\nTàu điện ngầm ở Moscow bắt đầu hoạt động từ tháng 5/1935 với 13 nhà ga, 12 đoàn tàu và tuyến đường dài 11,2km. Sau hơn 90 năm xây dựng và phát triển, tàu điện ngầm trở thành phương tiện giao thông phổ biến nhất ở thủ đô Moscow.\n\nHiện hệ thống có 15 tuyến đường và 271 nhà ga với tổng chiều dài trên 600km. Đây cũng là một trong những hệ thống tàu điện ngầm lớn và đẹp nhất thế giới.\n\nDù đã trải nghiệm nhiều ga tàu điện ngầm ở các nước trên thế giới, khi bước xuống ga metro ở Moscow, anh Sáng không khỏi trầm trồ bởi kiến trúc thiết kế ấn tượng như những cung điện dưới lòng đất.\n\nTrong hình là ga Komsomolskaya - nơi sở hữu phần mái vòm đẹp nhất ở Moscow với lối kiến trúc tráng lệ như một Hoàng cung.\n\nGa Komsomolskaya được khánh thành năm 1952. Các bức tranh trên mái vòm là một trong những bộ tranh Mosaic nổi tiếng nhất của hệ thống tàu điện ngầm của Nga, do họa sĩ Pavel Korin thiết kế mô tả các vị anh hùng và những chiến thắng lớn trong lịch sử của Nga.\n\nTrong khi đó, ga Kievskaya lại mang phong cách Hoàng gia lộng lẫy với tranh khảm tinh xảo. Nhà ga nổi bật với hệ thống đèn chùm rực rỡ và các phù điêu lịch sử về Nga – Ukraine.\n\nNhiều tạp chí du lịch đánh giá đây là một trong những ga tàu điện ngầm đẹp nhất thế giới, mang đậm hơi thở cổ điển và quyền quý.\n\nVị khách Việt trầm trồ khi bước chân tới ga Mayakovskaya. Nơi đây nổi tiếng nhờ phong cách nghệ thuật hiện đại. Những bức tranh mosaic (tranh khảm) trên trần mô tả bầu trời Moscow khiến không gian trở nên rộng mở và đầy cảm hứng.\n\nĐây là biểu tượng kiến trúc của ga metro ở Moscow - nơi bất kỳ du khách nào cũng muốn check-in.\n\nMột trong những điểm thú vị nhất khi khám phá các ga metro là di chuyển bằng thang cuốn dài. Có những nhà ga nằm sâu hàng chục mét dưới lòng đất, tạo cảm giác như chuyến thám hiểm kỳ bí.\n\nĐể tới thăm Quảng trường Đỏ - trái tim của Moscow, du khách không thể bỏ lỡ nhà ga Ploshchad Revolyutsii thuộc Quảng trường Cách Mạng. Nơi này được khánh thành vào ngày 13/3/1938.\n\nĐiểm ấn tượng nhất của ga Ploshchad Revolyutsii là các tác phẩm điêu khắc bằng đồng mô tả những tầng lớp người dân Liên Xô với tổng cộng 76 tác phẩm.\n\nĐáng chú ý nhất là bức tượng người lính biên phòng dắt chó. Người dân Moscow luôn tin rằng, các học sinh, sinh viên khi xoa mõm chú chó có thể vượt qua những kỳ thi tốt nghiệp khó nhất.\n\nChính vì thế mõm chú chó bằng đồng bị xoa mòn và bạc đến mức có thể nhìn thấy rõ. Tương tự, các tượng chú gà thậm chí còn sáng bóng toàn thân do nhỏ hơn so với chú chó nên dễ sờ chạm hơn. Trong ảnh, mõm của chú chó bằng đồng bị du khách và người dân sờ tới mức trơn nhẵn.\n\nTrong khi đó, nhà ga Belorusskaya được xem như “cánh cổng châu Âu” của Moscow. Kiến trúc trang nhã, hoạ tiết đậm dấu ấn Belarus cùng những mái vòm cổ điển tạo nên vẻ đẹp tinh tế đầy tính nghệ thuật.\n\nĐây là nơi du khách vừa có thể di chuyển thuận tiện, vừa có thể chụp ảnh “chất như điện ảnh”.\n\nĐể thuận tiện di chuyển giữa các nhà ga, anh Sáng sử dụng ứng dụng Yandex Metro để tra cứu tuyến đường, các điểm chuyển tàu và lựa chọn lộ trình phù hợp.\n\nTheo anh, nhờ ứng dụng này, việc khám phá hệ thống metro Moskva trở nên dễ dàng hơn, ngay cả khi anh chưa quen với mạng lưới giao thông tại thành phố.\n\nBên cạnh metro, Moskva còn có tàu Aeroexpress (ảnh), chuyên kết nối khu vực trung tâm thành phố với các sân bay quốc tế.\n\nĐây là dịch vụ đường sắt riêng, tách biệt với hệ thống metro, do đó hành khách cần mua vé riêng khi sử dụng.\n\nTheo vị khách Việt, mỗi nhà ga mang một dáng vẻ riêng, từ những sảnh rộng với mái vòm cao, đèn chùm và cột đá cẩm thạch đến các bức tranh khảm, tượng đồng, cửa kính màu được trang trí công phu.\n\nVì thế, với anh, đi metro không chỉ là cách di chuyển giữa các điểm đến mà còn là dịp khám phá những công trình kiến trúc và nghệ thuật độc đáo dưới lòng thành phố.\n\nTổng chi phí chuyến đi khoảng 65 triệu/người, trong đó riêng tiền vé máy bay khứ hồi khoảng 30 triệu đồng.\n\nChi phí lưu trú: Nhóm khách 6 người đặt phòng tại các căn hộ kiểu Airbnb với mức giá từ 2 triệu đến 3 triệu đồng/ngày.\n\nChi phí ăn uống: Từ 400.000 đồng đến 500.000 đồng/người/ngày.\n\nTừ ngày 15/10/2026, Nga chính thức áp dụng chính sách miễn thị thực (visa) cho công dân Việt Nam mang hộ chiếu phổ thông đến ngày 15/10/2027.\n\nThời gian áp dụng tối đa 30 ngày cho mỗi lần nhập cảnh.\n\nMục đích chuyến đi: Du lịch, thăm thân, công tác, tham gia các hoạt động khoa học, văn hóa, chính trị - xã hội, kinh tế, thể thao hoặc quá cảnh.\n\nTrường hợp không áp dụng: Người đến Nga với mục đích làm việc (bao gồm cả phóng viên, nhà báo), học tập hoặc cư trú lâu dài/định cư.","author":"Việt Hà","category":"Du lịch","publishedAt":"2026-10-19 23:59","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/khach-viet-chi-65-trieu-dong-toi-ga-tau-nhu-cung-dien-long-dat-o-nga-20261019235948208.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/WcJlnugShOMW6Nt04L7iQWRv2GM=/zoom/1200_630/2026/10/20/02metromoscow-cropped-1792429295454.jpg","crawledAt":"2026-10-21T13:42:51.647Z"},{"id":"dtri-20261019150803969","title":"Dẹp biển hiệu toàn tiếng nước ngoài ở “phố Tây” Ninh Bình","slug":"dep-bien-hieu-toan-tieng-nuoc-ngoai-o-pho-tay-ninh-binh","excerpt":"Khu du lịch Tam Cốc được ví như “phố Tây” ở Ninh Bình, vì thế nhiều cơ sở lưu trú đã tự ý đặt tên, sử dụng biển hiệu bằng tiếng nước ngoài hoặc sử dụng các từ ngữ chưa đúng quy định của pháp luật.","content":"(Dân trí) - Khu du lịch Tam Cốc được ví như “phố Tây” ở Ninh Bình, vì thế nhiều cơ sở lưu trú đã tự ý đặt tên, sử dụng biển hiệu bằng tiếng nước ngoài hoặc sử dụng các từ ngữ chưa đúng quy định của pháp luật.\n\nUBND phường Nam Hoa Lư vừa có văn bản yêu cầu Công an phường, các phòng chức năng, tổ dân phố rà soát, lắp đặt biển tên các cơ sở khách sạn, villa, homestay trên địa bàn phường đảm bảo quy định của pháp luật.\n\nLãnh đạo phường Nam Hoa Lư nêu rõ, thời gian qua, hoạt động kinh doanh dịch vụ lưu trú du lịch trên địa bàn có những bước phát triển mạnh mẽ, góp phần thúc đẩy kinh tế địa phương.\n\nTuy nhiên, qua công tác kiểm tra, quản lý, UBND phường nhận thấy còn một số cơ sở lưu trú tự ý đặt tên, sử dụng biển hiệu bằng tiếng nước ngoài hoặc sử dụng các từ ngữ chưa đúng quy định của pháp luật, gây nhầm lẫn cho khách du lịch và ảnh hưởng đến công tác quản lý nhà nước.\n\nĐể chấn chỉnh tình trạng trên, căn cứ Luật Du lịch năm 2017, Luật Quảng cáo năm 2012 và các văn bản hướng dẫn thi hành, UBND phường Nam Hoa Lư yêu cầu các tổ chức, cá nhân và hộ kinh doanh dịch vụ lưu trú nghiêm túc thực hiện việc treo biển đúng theo quy định của pháp luật.\n\nCụ thể, đối với tên gọi và biển hiệu của cơ sở phải được thể hiện bằng chữ tiếng Việt. Trường hợp dùng tiếng nước ngoài thì khổ chữ nước ngoài không được quá ba phần tư khổ chữ tiếng Việt và phải đặt bên dưới chữ tiếng Việt.\n\nCơ sở chỉ được đặt tên kèm theo các từ ngữ như: Khách sạn (Hostel), biệt thự du lịch (Villa), nhà ở có phòng cho khách du lịch thuê (Homestay/Hostel) khi đáp ứng đủ điều kiện cơ sở vật chất kỹ thuật, dịch vụ tương ứng theo quy định tại Điều 48 Luật Du lịch 2017.\n\nTuyệt đối không tự ý sử dụng từ ngữ \"Sao\" (hoặc ký hiệu hình ngôi sao) trên biển hiệu, trang thông tin điện tử, mạng xã hội (Facebook, Booking, Agoda...) khi chưa được cơ quan quản lý nhà nước có thẩm quyền công nhận hạng cơ sở lưu trú du lịch.\n\nTrao đổi với phóng viên Dân trí, lãnh đạo Phòng Văn hóa – Xã hội phường Nam Hoa Lư cho biết, sau khi tuyên truyền, hướng dẫn các hộ kinh doanh thực hiện, UBND phường sẽ chỉ đạo các cơ quan chức năng tiến hành kiểm tra liên ngành.\n\n“Các trường hợp cố tình vi phạm về đặt tên, biển hiệu và quảng cáo sai sự thật sẽ bị xử lý nghiêm theo quy định của pháp luật”, lãnh đạo Phòng Văn hóa – Xã hội nhấn mạnh.","author":"Thái Bá","category":"Du lịch","publishedAt":"2026-10-19 15:08","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/dep-bien-hieu-toan-tieng-nuoc-ngoai-o-pho-tay-ninh-binh-20261019150803969.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/rCuafgr1YbACW--8iyTXZsOS1jA=/zoom/1200_630/2026/10/19/pho-tay-1-cropped-1792397160945.jpg","crawledAt":"2026-10-21T13:42:51.663Z"},{"id":"dtri-20261019150641073","title":"Người đàn ông ho ra đờm mùi hôi nồng nặc, phát hiện bệnh cực hiếm","slug":"nguoi-dan-ong-ho-ra-dom-mui-hoi-nong-nac-phat-hien-benh-cuc-hiem","excerpt":"Trải qua nhiều lần phẫu thuật ổ bụng, người bệnh 54 tuổi bất ngờ sốt cao, ho ra đờm có mùi lạ.","content":"(Dân trí) - Trải qua nhiều lần phẫu thuật ổ bụng, người bệnh 54 tuổi bất ngờ sốt cao, ho ra đờm có mùi lạ.\n\nLỗ rò khiến bệnh nhân ho ra đờm mùi hôi nồng nặc\n\nNam bệnh nhân người Hà Tĩnh nhập viện trong tình trạng sốt cao kéo dài, ho nhiều đờm có mùi hôi bất thường. Kết quả chụp cắt lớp vi tính (CT) phát hiện bệnh nhân có tổn thương từ đại tràng lan lên vùng dưới gan, gây hoại tử và thủng cơ hoành, hình thành đường thông lên phổi phải dẫn đến áp xe phổi và nhiễm khuẩn huyết.\n\nBS Tạ Quang Hiện, Khoa Ngoại Tổng hợp, Bệnh viện Bệnh Nhiệt đới Trung ương cho biết, người bệnh có tiền sử u đại tràng trái, đã được phẫu thuật cắt u tại địa phương khoảng 3 tháng trước.\n\nSau mổ, người bệnh liên tiếp xuất hiện biến chứng. Khoảng 2 tháng trước khi vào Bệnh viện Bệnh Nhiệt đới Trung ương, người bệnh được phẫu thuật nội soi gỡ dính ruột do tắc ruột. Sau đó, tình trạng đau bụng tiếp tục tái diễn, người bệnh được chẩn đoán rò miệng nối đại tràng và làm hậu môn nhân tạo bên trái.\n\nKhoảng 10 ngày trước khi chuyển viện, người bệnh bắt đầu sốt cao liên tục, ho nhiều đờm có mùi hôi nồng nặc.\n\nNgười bệnh điều trị tại cơ sở y tế trong 2 ngày nhưng không cải thiện, sau đó được chuyển đến Bệnh viện Bệnh Nhiệt đới Trung ương với chẩn đoán nhiễm khuẩn huyết, áp xe phổi.\n\nTại Bệnh viện Bệnh Nhiệt đới Trung ương, kết quả chụp CT ngực và bụng của bệnh nhân ghi nhận ổ áp xe lớn ở phổi phải thông với ổ dịch vùng dưới gan qua một lỗ thủng cơ hoành, đồng thời có ổ dịch vùng thành bụng trái.\n\nCác bác sĩ xác định người bệnh có nhiều tổn thương phối hợp: áp xe phổi phải, thủng cơ hoành, áp xe dưới gan do thủng đại tràng phải và rò miệng nối đại tràng trái.\n\nBS Tạ Quang Hiện cho biết, điểm đặc biệt của trường hợp này nằm ở việc tổn thương trong ổ bụng đã tạo thành một đường thông bất thường qua cơ hoành lên khoang ngực. Đây chính là cơ chế khiến dịch nhiễm khuẩn từ hệ tiêu hóa có thể lan lên phổi, gây hình thành ổ áp xe lớn, khiến người bệnh ho ra đờm có mùi đặc trưng.\n\n“Ở một người bệnh đã trải qua nhiều cuộc phẫu thuật ổ bụng, khi xuất hiện ho đờm có mùi hôi bất thường kèm sốt kéo dài, cần nghĩ đến khả năng có một đường rò bất thường giữa đường tiêu hóa và hệ hô hấp. Nếu bỏ sót nguồn nhiễm, tình trạng nhiễm khuẩn có thể tiếp tục tiến triển rất nặng”, BS Hiện cho biết.\n\nCa mổ cân não\n\nDo tổn thương phức tạp, liên quan cả ổ bụng và lồng ngực, các bác sĩ xác định đây là ca bệnh khó, cần phẫu thuật sớm để kiểm soát nguồn nhiễm. Hai kíp phẫu thuật được huy động.\n\nKíp phẫu thuật lồng ngực tiến hành mở ngực, làm sạch và dẫn lưu ổ áp xe phổi phải. Tuy nhiên, ổ áp xe ở thùy dưới phổi phải rất lớn và dính nhiều tổ chức xung quanh, khiến việc tiếp cận lỗ thủng cơ hoành từ phía lồng ngực gặp nhiều khó khăn.\n\nVì vậy ê-kíp tập trung làm sạch và dẫn lưu ổ áp xe phổi. Sau đó, kíp phẫu thuật ổ bụng tiến hành thám sát, phát hiện một lỗ thủng đại tràng phải lan lên vùng dưới gan, gây hoại tử cơ hoành rồi dẫn đến thủng cơ hoành, tạo đường thông lên phổi phải.\n\nĐáng chú ý, tại vùng hậu môn nhân tạo bên trái, các bác sĩ không ghi nhận đây là vị trí thủng chính. Vị trí rò thực sự nằm tại miệng nối đại tràng trái của lần phẫu thuật cắt u trước đó.\n\nÊ-kíp tiến hành làm sạch ổ bụng, hạ dây chằng gan để tiếp cận vùng cơ hoành, khâu phục hồi lỗ thủng cơ hoành qua đường bụng. Đồng thời, hai vị trí tổn thương ở đại tràng phải và đại tràng trái được đưa ra làm hậu môn nhân tạo nhằm kiểm soát nguồn nhiễm.\n\nBS Tạ Quang Hiện nhấn mạnh, với những ca nhiễm khuẩn phức tạp như vậy, chỉ dẫn lưu áp xe phổi hoặc chỉ dùng kháng sinh là chưa đủ. Điều quan trọng nhất là phải tìm được và xử lý triệt để nguồn gây nhiễm, trong trường hợp này chính là các vị trí thủng, rò ở đại tràng và đường thông qua cơ hoành.","author":"Minh Nhật","category":"Sức khỏe","publishedAt":"2026-10-19 15:06","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/nguoi-dan-ong-ho-ra-dom-mui-hoi-nong-nac-phat-hien-benh-cuc-hiem-20261019150641073.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/Dr_XEiMWYN3zM-MK_Yz1pjFd_oU=/zoom/1200_630/2026/10/19/ho-cropped-1792397063514.jpg","crawledAt":"2026-10-21T13:42:38.948Z"},{"id":"dtri-20261019145900451","title":"Tiệm trà đạo gây tò mò với dàn máy giặt độc lạ ở TPHCM","slug":"tiem-tra-dao-gay-to-mo-voi-dan-may-giat-doc-la-o-tphcm","excerpt":"Đang dạo trong một con hẻm ở TPHCM, Tay (Singapore) bắt gặp một nơi trông giống quán cà phê nhưng bên trong lại có hàng loạt máy giặt, máy sấy. Tò mò bước vào, cô bất ngờ khi biết đây là một tiệm trà.","content":"(Dân trí) - Đang dạo trong một con hẻm ở TPHCM, Tay (Singapore) bắt gặp một nơi trông giống quán cà phê nhưng bên trong lại có hàng loạt máy giặt, máy sấy. Tò mò bước vào, cô bất ngờ khi biết đây là một tiệm trà.\n\nTay cho biết nhìn từ bên ngoài, tiệm khá nhỏ nhắn. Nhưng khi bước vào trong, cô thấy không gian thoáng đãng, dễ chịu với ánh đèn vàng ấm áp.\n\n“Lúc đi ngang tiệm, nhìn không gian, tôi cứ nghĩ đây là quán cà phê. Nhìn kỹ hơn, tôi thấy nơi này khá ấm cúng như một căn nhà, nhưng lại có những chiếc máy giặt, máy sấy xếp ngay ngắn. Tôi tò mò nên bước vào trong. Hóa ra đây là một không gian uống trà”, Tay chia sẻ.\n\nTại tiệm, Tay và bạn được mời ngồi trước quầy, đối diện người pha trà. Tiệm chủ yếu phục vụ trà theo phong cách Gong Fu, một phương pháp pha và thưởng thức trà truyền thống của Trung Quốc, chú trọng sự tỉ mỉ trong từng công đoạn.\n\nNgười pha sử dụng chén khải, hãm trà qua nhiều lượt nước để thực khách cảm nhận sự thay đổi về hương thơm, vị trà qua từng lần uống. Trong lúc thưởng trà, khách cũng có thể trò chuyện và tìm hiểu thêm về loại trà mình đang thưởng thức.\n\nTay cho biết mình từng nhiều lần uống trà, nhưng đây là lần đầu bắt gặp một tiệm kết hợp trà với dịch vụ giặt sấy. Sự kết hợp lạ lẫm này khiến cô ấn tượng, nhất là khi không gian bên trong mang lại cảm giác gần gũi, thoải mái.\n\nTiệm giặt sấy từ một ý tưởng dành cho mẹ\n\nTiệm nằm trong một con hẻm nhỏ trên đường Trần Quý Khoách (phường Tân Định, TPHCM), do chị Trang Ngọc và cộng sự là anh Khương điều hành, đi vào hoạt động khoảng một tháng.\n\n“Mẹ tôi vốn là công chức, làm việc đến hơn 65 tuổi mới nghỉ hưu. Trước đây, sợ mẹ quen nếp đi làm cũ, ở nhà buồn, tôi từng ấp ủ việc mở một căn tiệm nhỏ, có công việc gì đó để mẹ làm cho vui mà không cần tốn quá nhiều công sức. Giấc mơ ấy cứ âm ỉ trong tôi về một tiệm giặt tự động.\n\nĐến khi gặp ý tưởng của anh Khương, về việc kết hợp tiệm trà với một hoạt động thường ngày, hai ý tưởng gặp nhau. Từ đó, chúng tôi bắt đầu xây dựng nên không gian này”, chị Trang Ngọc chia sẻ.\n\nTheo chị, hiện tại tiệm do hai người trực tiếp điều hành, không phải mở riêng cho mẹ, nhưng chính mong muốn tìm một công việc để mẹ có thêm niềm vui sau khi nghỉ hưu đã khiến chị nghĩ đến mô hình giặt sấy tự động.\n\nViệc kết hợp hai dịch vụ cũng có những điều cần điều chỉnh trong quá trình vận hành. Tiệm vừa phải bảo đảm khách sử dụng máy giặt, máy sấy thuận tiện, vừa tạo được không gian dễ chịu để mọi người ngồi uống trà, trò chuyện.\n\nNgày thường, tiệm mở cửa từ 9h đến 20h, khách thường đông hơn sau 15h. Người tìm đến có cả khách Việt Nam lẫn khách nước ngoài, trong đó khách quốc tế thường ghé vào dịp cuối tuần.\n\nNhững chiếc máy giặt, máy sấy đặt cạnh bàn trà khiến nhiều người tò mò. Có khách vốn nghĩ một không gian trà đạo sẽ mang nét truyền thống, trang trọng và có những nghi thức riêng. Nhưng khi bước vào, họ lại thấy nơi này gần gũi, thoải mái hơn tưởng tượng.\n\nKhách có thể đi một mình, đi cùng bạn bè hoặc ngồi cạnh những người trước đó chưa từng quen biết.\n\nCác phẩm trà tại tiệm trải từ những lựa chọn dễ tiếp cận cho người mới bắt đầu đến các dòng cao cấp dành cho khách muốn khám phá sâu hơn. Người pha trà giới thiệu và gợi ý theo khẩu vị, để khách có thể chọn loại phù hợp dù đã quen uống trà hay mới thử lần đầu.\n\nMột phần trải nghiệm tại tiệm là cùng người pha trà khám phá hương vị qua nhiều lượt nước, từ hương lá trà đến dư vị sau mỗi chén. Các set trà (có người phục vụ pha trà) kèm phần mứt có giá từ 100.000 đồng. Ngoài ra, tiệm còn phục vụ các set trà ủ lạnh (cold brew) để khách có thêm lựa chọn thưởng trà theo sở thích.\n\nChị Trang Ngọc cho biết, khách đến giặt đồ hiện chủ yếu là những người sống trong khu phố. Dịch vụ giặt sấy tại tiệm hoạt động tự động, với giá 50.000 đồng cho một lần giặt và sấy từ 20.000 đồng, đã bao gồm nước giặt và nước xả chuyên dụng.\n\nMỗi lần giặt có thể xử lý khoảng 10kg quần áo. Tiệm vẫn đang trong quá trình hoàn thiện, lắng nghe ý kiến của khách để điều chỉnh giờ hoạt động, chỗ ngồi và cách phục vụ.\n\nTrong thời gian tới, tiệm có thể bố trí thêm chỗ cho nhóm đông người, sắp xếp khu vực riêng hoặc tổ chức các buổi workshop để khách có dịp tìm hiểu, trao đổi về văn hóa.\n\nBàn trà kết nối những người xa lạ\n\nTrong khi chị Trang Ngọc lo việc vận hành, anh Khương dành nhiều tâm huyết cho trà và cách phục vụ khách. Với anh, điều khiến mình gắn bó với trà không chỉ là hương vị hay cách pha, mà còn là những người anh có dịp gặp gỡ bên bàn trà.\n\n“Thông qua tiệm, chúng tôi mong muốn góp phần lan tỏa văn hóa trà phương Đông theo cách gần gũi, dễ tiếp cận, để khách có thể thưởng trà một cách tự nhiên giữa những sinh hoạt hằng ngày.\n\nBên bàn trà, chúng ta không chỉ thưởng thức trà mà còn trò chuyện, kết nối, mở rộng những mối quan hệ của mình. Có lần, sau khi phục vụ hai vị khách khác nhau, vốn không quen biết nhau, tôi thấy họ trò chuyện, làm quen rồi cùng bước ra ngoài như những người bạn”, anh Khương kể.\n\nTheo anh, những cuộc gặp như vậy là điều thú vị khi làm trà. Khách đến tiệm làm nhiều nghề khác nhau, mỗi người có những câu chuyện và trải nghiệm riêng. Qua những lần trò chuyện, anh cũng biết thêm nhiều điều mới, hiểu hơn về các lĩnh vực khác và có thêm góc nhìn về cuộc sống.\n\nNhững cuộc gặp gỡ tình cờ đôi khi còn giúp khách tìm được người hợp chuyện. Có người ban đầu chỉ ghé tiệm vì tò mò về mô hình trà kết hợp giặt sấy, nhưng rồi ngồi lại lâu hơn dự định vì mải trò chuyện với người bên cạnh.\n\nVới chị Trang Ngọc và anh Khương, trà không chỉ để thưởng thức mà còn là dịp để mọi người ngồi lại, trò chuyện và hiểu nhau hơn. Còn với những vị khách nước ngoài một lần ghé tiệm vì tò mò cũng trở thành trải nghiệm thú vị, giúp họ khám phá một góc đời sống bình dị ở TPHCM.","author":"Mộc Khải","category":"Du lịch","publishedAt":"2026-10-19 14:59","source":"dantri.com.vn","url":"https://dantri.com.vn/du-lich/tiem-tra-dao-gay-to-mo-voi-dan-may-giat-doc-la-o-tphcm-20261019145900451.htm","categories":["Du lịch"],"categoryIds":["du-lich"],"thumbnail":"https://cdnphoto.dantri.com.vn/k5XvMPXgn5us1OCtzPa4kTGZQEA=/zoom/1200_630/2026/10/19/img4943-cropped-1792392531260.jpg","crawledAt":"2026-10-21T13:42:49.501Z"},{"id":"dtri-20261019130459687","title":"Các cụ U90 Hà Nội: Tối ngủ với con, sáng dậy \"cắp cặp\"... đi viện dưỡng lão","slug":"cac-cu-u90-ha-noi-toi-ngu-voi-con-sang-day-cap-cap-di-vien-duong-lao","excerpt":"Dù ở chung với các con cháu, nhưng bà Óng vẫn háo hức chờ tới sáng để đến viện dưỡng lão, có bạn bè nói chuyện, không phải ở nhà một mình trong 4 bức tường.","content":"\"Chạnh lòng khi con nói cho đi dưỡng lão, sau lại... mê\"\n\nMỗi sáng từ thứ 2 đến thứ 6, ông Trần Xuân Song (78 tuổi, phường Tây Hồ, Hà Nội) lại chống gậy đi bộ đến cơ sở chăm sóc người cao tuổi ban ngày trên đường Quảng An, cách nhà hơn 500m.\n\nNơi đây có bạn bè của ông cùng trò chuyện, tham gia hoạt động thay vì quanh quẩn một mình trong nhà.\n\nTrước đây, khi con cháu đi làm, đi học, phần lớn thời gian trong ngày của ông Song trôi qua bên chiếc tivi hoặc trên giường. Tuổi cao, chân đau khiến ông ngại đi lại, khoảng thời gian dài thiếu người bầu bạn càng khiến cuộc sống nghỉ hưu thêm tẻ nhạt.\n\n“Ở nhà cứ nằm trên giường suốt, không thì lại xem tivi. Chân đau, sức khỏe giảm sút, tinh thần cũng buồn vì chẳng có ai trò chuyện”, ông kể.\n\nBiết gần nhà có cơ sở chăm sóc người cao tuổi ban ngày, ông cùng con cháu đến tìm hiểu rồi đăng ký tham gia. Từ đó, buổi sáng của ông có thêm một lịch hẹn quen thuộc.\n\nKhông nhờ con cháu đưa đón, ông tự chống gậy đi bộ đến trung tâm chiều lại trở về nhà.\n\nĐiều khiến ông Song vui nhất những ngày qua không chỉ là được vận động mà còn là có người chuyện trò. Ở trung tâm, ông quen những người cùng thế hệ, có người là công nhân nhà máy in, người từng tham gia kháng chiến, người làm trong ngành xây dựng....\n\nCụ ông có thể thoải mái kể về những ngày trẻ, về thời trước của mình mà không lo lắng việc cách biệt thế hệ, những ngày nghỉ hưu của ông càng thêm rộn ràng.\n\n“Đến đây được vận động, tập luyện, nói chuyện với nhau nên tinh thần tôi thoải mái hơn. Tôi thấy mình khỏe ra, bớt cô đơn hơn trước”, ông chia sẻ.\n\nMỗi ngày, ông còn được tham gia các hoạt động như tập dưỡng sinh ngoài trời, ngồi thiền, ngâm chân thảo dược, vẽ tranh, đọc sách hoặc hát karaoke. Với ông, việc có lịch sinh hoạt đều đặn giúp bản thân chủ động hơn, thay vì để thời gian trôi qua trong sự thụ động.\n\n\"Tôi không muốn vào viện dưỡng lão cả ngày lẫn đêm, sống xa con cháu tuổi về già, mô hình này thật sự tốt với những người già như tôi\", cụ ông nhận xét.\n\nCũng tìm thấy niềm vui mới khi tham gia mô hình chăm sóc người cao tuổi ban ngày, bà Trần Thị Nữ (80 tuổi) là một trong những thành viên đầu tiên của trung tâm. Sau hơn 2 tháng gắn bó, bà đã thuộc lòng giờ giấc sinh hoạt, biết hôm nào có hoạt động gì và quen mặt từng người bạn cùng trang lứa.\n\nBà Nữ sống cùng con trai, con dâu và các cháu. Tuy nhiên, khi con cháu đều bận rộn với công việc, bà thường chỉ quanh quẩn trong nhà. Không có người trò chuyện thường xuyên, những ngày ở nhà trở nên dài hơn.\n\n“Tuổi già ai cũng có những vấn đề riêng, nhưng con cháu bận rộn, bản thân tôi cũng ngại nói ra vì sợ các con lo lắng”, bà chia sẻ.\n\nKhi được giới thiệu về trung tâm chăm sóc người cao tuổi ban ngày của phường, bà chủ động đăng ký đến trải nghiệm. Sau tháng đầu tiên được miễn phí, nhận thấy mình được chăm sóc chu đáo, sức khỏe có chuyển biến tích cực và tinh thần vui vẻ hơn, bà quyết định tiếp tục tham gia.\n\nĐiều khiến bà Nữ hài lòng không chỉ là được theo dõi sức khỏe, hỗ trợ xoa bóp, chiếu đèn hoặc châm cứu khi đau tay, mà còn là cảm giác luôn có người bên cạnh. Từ những người xa lạ, các thành viên dần trở thành bạn bè, có thể hỏi han, chia sẻ chuyện gia đình, sức khỏe.\n\nNiềm vui ấy còn hiện diện trong những bữa cơm trưa của bà. Trước đây, khi ở nhà một mình, bà Nữ thường ăn uống qua loa, chỉ chuẩn bị một, hai món cho xong bữa. Tại trung tâm, bà được ăn đúng giờ, thực đơn đa dạng với 5 món, có bữa phụ và đặc biệt là có người cùng ngồi ăn, trò chuyện.\n\nVới bà Nữ, trung tâm dần trở thành một phần quen thuộc trong nhịp sống hằng ngày. Bà được vận động, vui chơi thay vì chỉ quanh quẩn trong bốn bức tường. Những ngày cuối tuần không đến trung tâm, cụ bà lại mong nhanh đến thứ 2 để được gặp mọi người.\n\n“Ở đây ngày nào cũng có chuyện vui, có người trò chuyện nên tôi thấy thoải mái hơn nhiều”, bà nói.\n\nTrung tâm trang bị giường chiếu, đồ dùng vận động để các cụ nghỉ ngơi, tập luyện.\n\nBà Nguyễn Thị Óng (82 tuổi) mới tham gia trung tâm khoảng 10 ngày. Cụ bà chia sẻ, ban đầu, khi nghe con nói sẽ đăng ký cho mình đến trung tâm dưỡng lão, bà Óng không khỏi chạnh lòng.\n\nNhưng sau những ngày trải nghiệm, bà dần thích được đến trung tâm, ở đây bà được nghỉ ngơi, giao lưu và chăm sóc bản thân.\n\nTrước đây, dù con cái thường khuyên mẹ nghỉ ngơi, bà Óng vẫn không thể ngồi yên.\n\n“Ngồi không thì không chịu được, cứ quanh quẩn quét nhà, dọn dẹp, nấu cơm là hết ngày. Nhiều khi mình cũng chẳng thực sự được nghỉ ngơi”, bà kể.\n\nTừ ngày tham gia trung tâm với mức chi phí hơn 2 triệu đồng mỗi tháng, ở phòng cùng 5 người khác, bà Óng bắt đầu có những khoảng thời gian dành riêng cho mình. Buổi sáng, bà cùng vài người bạn hẹn nhau bắt taxi đến trung tâm. Ở đó, bà có thể đọc sách, vẽ tranh, ngồi thiền hoặc làm đồ thủ công, tham gia các hoạt động phù hợp với sức khỏe.\n\nTrong số các hoạt động, bà thích nhất là ngâm chân thư giãn. Những người bạn già ngồi quây quần, vừa ngâm chân vừa trò chuyện về những điều vụn vặt trong cuộc sống. Những lúc như vậy, bà không phải bận tâm đến việc nhà còn gì chưa làm hay con cháu đã ăn uống đầy đủ chưa.\n\n“Chính ra vào đây lại khỏe, mọi việc có các cháu ở nhà tự lo, mình chỉ cần ăn uống, tập luyện, vui chơi”, bà cười nói.\n\nĐiều khiến cụ bà yên tâm nhất là sau một ngày có hoạt động và bạn bè bên cạnh, buổi chiều bà vẫn được trở về nhà, sống cùng con cháu, không phải chịu cảnh mẹ một nơi, con cái một nơi ở tuổi xế chiều.\n\nCháy chỗ\n\nChị Trần Thị Thủy, phụ trách cơ sở chăm sóc người cao tuổi ban ngày tại phường Tây Hồ, Hà Nội, cho biết trung tâm đi vào hoạt động từ tháng 8, với quy mô tối đa 20 giường. Dù mới hoạt động, cơ sở thường xuyên kín chỗ.\n\nTheo chị Thủy, một ngày tại trung tâm bắt đầu từ 7h45, nhân viên đón các cụ, đo huyết áp, theo dõi nhiệt độ, kiểm tra một số chỉ số sức khỏe và ghi sổ. Sau đó, người cao tuổi tham gia các hoạt động như tập thể dục, vận động phòng ngừa té ngã, rèn luyện trí nhớ, vẽ tranh, thiền và trò chơi tập thể.\n\n\"Các bài tập ở trung tâm được điều chỉnh phù hợp với thể trạng của từng người. Với những cụ đi lại khó khăn hoặc có di chứng bệnh lý, nhân viên sẽ hỗ trợ riêng để bảo đảm an toàn trong quá trình vận động\", chị Thuỷ nói.\n\nTrung tâm có 6 nhân viên trực tiếp chăm sóc người cao tuổi. Bên cạnh đó, cơ sở mời các bác sĩ y học cổ truyền và bác sĩ tây y luân phiên đến thăm khám, theo dõi sức khỏe cho các cụ. Trung tâm cũng phối hợp tổ chức các hoạt động chăm sóc như xoa bóp, bấm huyệt, ngâm chân và vật lý trị liệu, tùy theo nhu cầu và tình trạng sức khỏe của từng người.\n\nBữa ăn của các cụ được đặt từ một đơn vị chế biến riêng, nhằm đáp ứng đủ nhu cầu dinh dưỡng trong ngày.\n\n\"Hiện các cụ ăn ở trung tâm 2 bữa là bữa trưa và một bữa phụ khi ngủ dậy, có thể là sữa chua, hoa quả\", chị Thuỷ cho hay.\n\nNgoài trung tâm lồng ghép những trò chơi đố vui, giải câu đố dân gian vào lịch sinh hoạt, khuyến khích người cao tuổi suy nghĩ, gợi nhớ kiến thức và tương tác với bạn bè đồng trang lứa.\n\n“Lịch sinh hoạt cũng được thay đổi thường xuyên để các cụ không cảm thấy nhàm chán, có hôm đố vui, hôm vẽ, cắt dán...”, chị Thủy chia sẻ.\n\nTheo chị Thuỷ, khoảng 16h30-17h, các cụ được gia đình đón về nhà, tiếp tục sinh hoạt cùng con cháu. Chi phí chăm sóc là 100.000 đồng/ngày. Trung tâm hoạt động từ thứ 2 đến thứ 6 hằng tuần, nghỉ thứ 7 và chủ nhật.\n\nĐại diện trung tâm cho hay, mô hình chăm sóc ban ngày phù hợp với những gia đình có con cháu đi làm cả ngày, không thể thường xuyên ở bên chăm sóc người thân. Người cao tuổi vừa được theo dõi sức khỏe, tham gia các hoạt động phù hợp, vừa có thể trở về nhà vào buổi chiều, duy trì cuộc sống quen thuộc bên gia đình.","author":"Nguyễn Ngoan","category":"Đời sống","publishedAt":"2026-10-19 13:04","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/cac-cu-u90-ha-noi-toi-ngu-voi-con-sang-day-cap-cap-di-vien-duong-lao-20261019130459687.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/DsxyNsRcISqnf26XbWHM4L2TPjQ=/zoom/1200_630/2026/10/19/chamsoncttayho-31-cropped-1792389732916.jpg","crawledAt":"2026-10-21T13:42:42.218Z"},{"id":"dtri-20261019095015233","title":"Người trẻ chọn xe xăng hay xe điện?","slug":"nguoi-tre-chon-xe-xang-hay-xe-dien","excerpt":"Dân trí 360 (Dân trí) - Bên cạnh xe xăng và xe điện, ô tô hybrid cũng là một lựa chọn phù hợp với lối sống năng động, thích trải nghiệm của người trẻ.","content":"Dân trí 360 (Dân trí) - Bên cạnh xe xăng và xe điện, ô tô hybrid cũng là một lựa chọn phù hợp với lối sống năng động, thích trải nghiệm của người trẻ.","author":"Dân trí","category":"Xe ++","publishedAt":"2026-10-19 09:50","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/nguoi-tre-chon-xe-xang-hay-xe-dien-20261019095015233.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/btnp0-wDNTJD7oXyeGRbKjvmCKs=/zoom/1200_630/2026/10/19/genz-chon-xe-xang-hay-xe-dien1-cropped-1792377829738.jpg","crawledAt":"2026-10-21T13:43:31.207Z"},{"id":"dtri-20261018142525453","title":"“Có áo phao rồi, em sẽ yên tâm hơn mỗi khi mùa lũ về!”","slug":"co-ao-phao-roi-em-se-yen-tam-hon-moi-khi-mua-lu-ve","excerpt":"Với những học sinh sống ở vùng nguy cơ ngập lụt, chiếc áo phao là sự chuẩn bị cần thiết trước mùa lũ, còn những suất học bổng tiếp thêm động lực giúp các em vượt khó trong học tập.","content":"(Dân trí) - Với những học sinh sống ở vùng nguy cơ ngập lụt, chiếc áo phao là sự chuẩn bị cần thiết trước mùa lũ, còn những suất học bổng tiếp thêm động lực giúp các em vượt khó trong học tập.\n\n“Có áo phao rồi, em sẽ yên tâm hơn mỗi khi mùa lũ về”, Nguyễn Đình Toàn, học sinh lớp 7/4, Trường THCS Mỹ Hòa (xã Đại Lộc, Đà Nẵng) chia sẻ khi nhận quà từ chương trình trao tặng 2.040 áo phao tới người dân xã Đại Lộc và Hà Nha.\n\nChương trình do báo Dân trí phối hợp với Cục Cảnh sát giao thông (CSGT) - Bộ Công an, Quỹ Toyota Việt Nam và chính quyền địa phương tổ chức vào ngày 16/10.\n\nÁo phao đến với học sinh vùng ngập lụt\n\nNgày nhận quà, Toàn được thầy tổng phụ trách Đội chở đến hội trường UBND xã Đại Lộc. Nhà em nằm ở vùng trũng thấp, thường xuyên ngập sâu khi mưa lớn kéo dài, buộc gia đình phải sơ tán mỗi khi nước dâng cao.\n\n“Trước đây, nhà chưa có áo phao nên mỗi lần sơ tán trong lũ, gia đình em đều lo lắng. Giờ có thêm phương tiện phòng thân, em thấy yên tâm hơn khi mùa mưa lũ đến”, Toàn chia sẻ.\n\nBà Nguyễn Thị Thu Thảo (54 tuổi, mẹ của Toàn) chia sẻ, cuộc sống gia đình còn nhiều khó khăn, trong khi ngập lụt là nỗi lo thường trực mỗi mùa mưa. Chiếc áo phao vì thế không chỉ là món quà thiết thực mà còn giúp gia đình có thêm phương tiện ứng phó khi xảy ra tình huống khẩn cấp.\n\nCha của em Phan Ngọc Anh Thư, học sinh lớp 9, Trường THCS Nguyễn Trãi (xã Đại Lộc) đã qua đời, mẹ một mình nuôi 4 người con. Anh cả đã nhập ngũ, em út đang học lớp 2. Gánh nặng mưu sinh khiến việc chăm lo cho các con của người mẹ càng thêm vất vả.\n\nVới Thư, chiếc áo phao được báo Dân trí trao tặng giúp em có thêm phương tiện bảo vệ bản thân khi mưa lũ, còn suất học bổng là sự động viên trong năm học mới.\n\n“Em rất vui, biết ơn báo Dân trí cùng các cô, chú đã tặng áo phao và học bổng. Em sẽ giữ gìn chiếc áo cẩn thận, mong có thêm nhiều học sinh, gia đình khó khăn được nhận những món quà thiết thực như thế này”, Thư bày tỏ.\n\nTiếp sức cho năm học mới\n\nThầy Trương Ngọc Thu, Hiệu trưởng Trường THCS Mỹ Hòa, đánh giá việc trao áo phao cho học sinh sống ở khu vực thường xuyên ngập lụt có ý nghĩa thiết thực, góp phần bổ sung phương tiện phòng tránh đuối nước và nâng cao khả năng ứng phó với thiên tai.\n\nBên cạnh đó, những phần học bổng còn thể hiện sự quan tâm, trách nhiệm của cộng đồng đối với học sinh có hoàn cảnh khó khăn, góp phần động viên các em vươn lên trong học tập.\n\nÔng Lê Đỗ Tuấn Khương, Chủ tịch UBND xã Đại Lộc cho biết, những phần quà dành tặng học sinh khó khăn là nguồn động viên thiết thực, thể hiện sự đồng hành của các đơn vị, nhà hảo tâm với địa phương trong công tác chăm lo cho thế hệ trẻ.\n\nÔng Nguyễn Đình Vĩnh, Phó Bí thư Thành ủy, Chủ tịch Ủy ban Mặt trận Tổ quốc Việt Nam thành phố Đà Nẵng cho biết, những phần quà hỗ trợ được trao vào dịp đầu năm học sẽ giúp các em học sinh có hoàn cảnh khó khăn mua sắm thêm quần áo ấm, chuẩn bị cho mùa đông sắp tới.\n\n“Khi mặc áo, các em sẽ cảm nhận được sự yêu thương từ các cô chú, anh chị\", ông Vĩnh nhấn mạnh, đồng thời mong rằng khi trưởng thành các em sẽ chia sẻ, lan tỏa thêm những tình cảm tốt đẹp.\n\nÔng Vĩnh cũng gửi lời cảm ơn báo Dân trí, các đơn vị đồng hành với chương trình, đồng thời mong muốn những hoạt động ý nghĩa này ngày càng được lan tỏa rộng rãi.\n\nChương trình trao 2.040 áo phao tại 2 xã Đại Lộc và Hà Nha do báo Dân trí phối hợp với Cục CSGT, Quỹ Toyota Việt Nam và chính quyền địa phương tổ chức.\n\nDịp này, 50 hộ dân ngoài được tặng áo phao, bạn đọc báo Dân trí, Quỹ Toyota Việt Nam, Tổng Công ty điện lực miền Trung, Công ty TNHH một thành viên Quang Minh Bảo, Toyota Trang Lê Quảng Nam trao tặng 50 phần quà bằng tiền mặt, trị giá mỗi phần quà 1 triệu đồng nhằm chia sẻ một phần khó khăn với các gia đình.\n\nBan tổ chức cũng trao học bổng tới 10 học sinh có hoàn cảnh khó khăn tại xã Đại Lộc, mỗi suất 1 triệu đồng và áo phao. Tặng quà 2 gia đình có hoàn cảnh đặc biệt khó khăn tại thôn Nghĩa Mỹ, xã Đại Lộc, mỗi phần quà trị giá 5 triệu đồng.\n\nCó 14 đại lý Toyota đồng hành tài trợ áo phao, gồm: Toyota An Sương, Toyota Bắc Giang, Toyota Bắc Ninh, Toyota Bến Tre, Toyota Biên Hòa, Toyota Cần Thơ - Chi nhánh An Giang, Toyota Hùng Vương, Toyota Mỹ Đình, Toyota Ninh Kiều, Toyota Phú Thọ, Toyota Thăng Long, Toyota Tiến Thu Quảng Ngãi, Toyota Tiền Giang và Toyota Trang Lê Quảng Nam.\n\nNỗi ám ảnh về lũ lịch sử chưa hết lại thấp thỏm trước mùa mưa bão mới\n\nVật dụng quý giá giúp giữ mạng sống trong mưa lũ\n\nLớp bảo vệ đầu tiên khi nước lũ dâng lúc nửa đêm\n\nHơn 2.000 áo phao về vùng rốn lũ\n\nLũ cuốn đi cả gia tài, để lại hai phận đời\n\n2.040 áo phao sẵn sàng được trao đến người dân vùng lũ Đà Nẵng\n\nÁo phao sẽ được ưu tiên người dân dễ bị tổn thương khi mưa lũ xảy ra\n\nBáo Dân trí đồng hành cùng Quỹ Toyota Việt Nam trao tặng 2.040 áo phao tới người dân vùng rốn lũ\n\nTrao 2.040 áo phao, thêm điểm tựa cho người dân vùng lũ\n\nPhó Bí thư Thành ủy Đà Nẵng: \"Chúng tôi và bà con cảm thấy ấm áp\"\n\n2.040 áo phao và những tấm lòng hướng về người dân vùng lũ\n\nHơn 2.000 áo phao mang hơi ấm, giúp vơi nỗi lo trước mùa mưa lũ\n\nCách sử dụng áo phao, thoát nạn để đảm bảo an toàn trong mùa mưa lũ","author":"Hoài Sơn","category":"Nhân ái","publishedAt":"2026-10-18 14:25","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/co-ao-phao-roi-em-se-yen-tam-hon-moi-khi-mua-lu-ve-20261018142525453.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/3ixj6bsZQ3WAjEz1aNd3-cZxBU0=/zoom/1200_630/2026/10/18/trao-ao-phao-da-nanghoai-son20-cropped-1792308262034.jpg","crawledAt":"2026-10-21T13:43:38.839Z"},{"id":"dtri-20261018141318844","title":"Cách sử dụng áo phao, thoát nạn để đảm bảo an toàn trong mùa mưa lũ","slug":"cach-su-dung-ao-phao-thoat-nan-de-dam-bao-an-toan-trong-mua-mua-lu","excerpt":"Tại chương trình trao tặng 2040 áo phao đến người dân vùng rốn lũ thành phố Đà Nẵng, lực lượng chức năng đã hướng dẫn cách sử dụng, thoát nạn trong tình huống khẩn cấp do mưa lũ…","content":"(Dân trí) - Tại chương trình trao tặng 2040 áo phao đến người dân vùng rốn lũ thành phố Đà Nẵng, lực lượng chức năng đã hướng dẫn cách sử dụng, thoát nạn trong tình huống khẩn cấp do mưa lũ…\n\nBáo Dân trí phối hợp với Cục Cảnh sát giao thông (SCGT) Bộ Công an, chính quyền địa phương, với sự tài trợ của Quỹ Toyota Việt Nam, cùng 14 đại lý Toyota trên toàn quốc, tổ chức chương trình trao tặng 2.040 áo phao cứu sinh tới người dân xã Đại Lộc và Hà Nha, thành phố Đà Nẵng vào ngày 16/10.\n\nTại sự kiện, Thiếu tá Trương Cao Vỹ, cán bộ đội Cảnh sát đường thủy số 2, Công an thành phố Đà Nẵng, đã hướng dẫn sử dụng áo phao hợp lý và có cách thoát nạn hiệu quả trong trường hợp khẩn cấp tới người dân vùng lũ.\n\nTheo Thiếu tá Trương Cao Vỹ, người sử dụng áo phao cần nắm vững một số kỹ năng an toàn quan trọng trong mùa mưa lũ, luôn sẵn sàng đeo các thiết bị cứu hộ, đặc biệt là mặc áo phao phải đúng cách.\n\n“Áo phao giúp chúng ta nổi trên mặt nước khi gặp tình huống nguy hiểm và tránh bị đuối nước. Khi được trang bị áo phao trong mùa mưa lũ, bà con cần lưu ý các bước mặc áo đúng cách, an toàn”, Thiếu tá Trương Cao Vỹ nhấn mạnh.\n\nThiếu tá Trương Cao Vỹ chia sẻ quy trình chuẩn cần có 5 bước:\n\nBước 1: Chọn áo phao phù hợp với người sử dụng, kiểm tra dây đai, khóa cài và tình trạng bên ngoài; không sử dụng áo phao bị rách, hỏng hoặc không bảo đảm khả năng nổi.\n\nBước 2: Đưa áo phao vào người theo thiết kế của sản phẩm; cài đầy đủ khóa, buộc chặt dây đai và dây buộc theo hướng dẫn của nhà sản xuất.\n\nBước 3: Điều chỉnh áo phao vừa vặn, không quá lỏng để tránh tuột khỏi cơ thể khi rơi xuống nước. Đối với trẻ em, người lớn cần trực tiếp kiểm tra và hỗ trợ mặc áo phao.\n\nBước 4: Giữ bình tĩnh khi có sự cố, làm theo hướng dẫn của thuyền trưởng, người lái phương tiện, hoặc lực lượng cứu nạn; không tự ý tháo áo phao khi chưa đến nơi an toàn.\n\nBước 5: Khi ở dưới nước, giữ đầu và đường thở trên mặt nước, hạn chế vận động không cần thiết, cố gắng duy trì tư thế nổi ổn định và ra hiệu cầu cứu.\n\nTheo Thiếu tá Trương Cao Vỹ, không chờ đến khi gặp sự cố mới tìm áo phao. Khi có tình huống khẩn cấp, người dân cần nhanh chóng mặc áo phao đúng cách; hỗ trợ trẻ em, người cao tuổi, khuyết tật và gặp khó khăn trong di chuyển.\n\nKhi phát hiện người rơi xuống nước cần hô to báo động, chỉ rõ vị trí nạn nhân rơi xuống nước để mọi người cùng biết. Nhanh chóng ném phao tròn, dây cứu sinh hoặc vật nổi phù hợp về phía người gặp nạn.\n\nGọi lực lượng cứu nạn khi cần thiết; cung cấp chính xác vị trí, thời điểm xảy ra sự cố và số người gặp nạn. Không tự ý nhảy xuống nước cứu người nếu không được huấn luyện hoặc không có thiết bị bảo vệ phù hợp.\n\nĐối với người đã rơi xuống nước cố gắng giữ bình tĩnh, không vùng vẫy quá mức gây mất sức. Giữ áo phao đúng cách, ngửa người hoặc duy trì tư thế nổi phù hợp với loại áo phao đang sử dụng. Ra hiệu cầu cứu bằng cách giơ tay hoặc phát tiếng kêu khi có thể.\n\nBám vào phao cứu sinh hoặc vật nổi an toàn nếu ở trong tầm với. Không cố bơi đuổi theo phương tiện đang di chuyển; tập trung giữ nổi và chờ được hỗ trợ.\n\nChương trình trao 2.040 áo phao tại 2 xã Đại Lộc và Hà Nha do báo Dân trí phối hợp với Cục CSGT, Quỹ Toyota Việt Nam và chính quyền địa phương tổ chức.\n\nDịp này, 50 hộ dân ngoài được tặng áo phao, bạn đọc báo Dân trí, Quỹ Toyota Việt Nam, Tổng Công ty điện lực miền Trung, Công ty TNHH một thành viên Quang Minh Bảo, Toyota Trang Lê Quảng Nam trao tặng 50 phần quà bằng tiền mặt, trị giá mỗi phần quà 1 triệu đồng nhằm chia sẻ một phần khó khăn với các gia đình.\n\nBan tổ chức cũng trao học bổng tới 10 học sinh có hoàn cảnh khó khăn tại xã Đại Lộc, mỗi suất 1 triệu đồng và áo phao.\n\nTặng quà 2 gia đình có hoàn cảnh đặc biệt khó khăn tại thôn Nghĩa Mỹ, xã Đại Lộc, mỗi phần quà trị giá 5 triệu đồng.\n\nCó 14 đại lý Toyota đồng hành tài trợ áo phao, gồm: Toyota An Sương, Toyota Bắc Giang, Toyota Bắc Ninh, Toyota Bến Tre, Toyota Biên Hòa, Toyota Cần Thơ - Chi nhánh An Giang, Toyota Hùng Vương, Toyota Mỹ Đình, Toyota Ninh Kiều, Toyota Phú Thọ, Toyota Thăng Long, Toyota Tiến Thu Quảng Ngãi, Toyota Tiền Giang và Toyota Trang Lê Quảng Nam.\n\nTheo kế hoạch, mỗi địa phương sẽ tiếp nhận 1.020 áo phao để phân bổ theo mức độ rủi ro và nhu cầu thực tế, ưu tiên các hộ ở vùng ngập sâu, dễ bị cô lập, gia đình có trẻ nhỏ, người cao tuổi, người bệnh và người khuyết tật. Một phần áo phao cũng được dành cho lực lượng phòng, chống thiên tai tại cơ sở.\n\nNỗi ám ảnh về lũ lịch sử chưa hết lại thấp thỏm trước mùa mưa bão mới.\n\nVật dụng quý giá giúp giữ mạng sống trong mưa lũ.\n\nLớp bảo vệ đầu tiên khi nước lũ dâng lúc nửa đêm.\n\nHơn 2.000 áo phao về vùng rốn lũ.\n\nLũ cuốn đi cả gia tài, để lại hai phận đời.\n\n2.040 áo phao sẵn sàng được trao đến người dân vùng lũ Đà Nẵng.\n\nÁo phao sẽ được ưu tiên người dân dễ bị tổn thương khi mưa lũ xảy ra.\n\nBáo Dân trí đồng hành cùng Quỹ Toyota Việt Nam trao tặng 2.040 áo phao tới người dân vùng rốn lũ.\n\nPhó Bí thư Thành ủy Đà Nẵng: \"Chúng tôi và bà con cảm thấy ấm áp\".\n\nTrao 2040 áo phao, thêm điểm tựa cho người dân vùng lũ.\n\nHơn 2.000 áo phao mang hơi ấm, giúp vơi nỗi lo trước mùa mưa lũ.","author":"Công Bính","category":"Nhân ái","publishedAt":"2026-10-18 14:13","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/cach-su-dung-ao-phao-thoat-nan-de-dam-bao-an-toan-trong-mua-mua-lu-20261018141318844.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/_9_BKMM0dv8y8BTMCdLU42_ZB8A=/zoom/1200_630/2026/10/19/cach-su-dung-ao-phao-de-dam-bao-an-toan-trong-mua-mua-lu-3-edited-cropped-1792379615977.jpg","crawledAt":"2026-10-21T13:43:41.307Z"},{"id":"dtri-20261018132253540","title":"Bạn đọc tiếp sức, góa phụ liệt nửa người hồi phục, tự chăm sóc bản thân","slug":"ban-doc-tiep-suc-goa-phu-liet-nua-nguoi-hoi-phuc-tu-cham-soc-ban-than","excerpt":"Góa phụ 44 tuổi người Dao đột quỵ, liệt nửa người: “Xin thương mẹ con em!”","content":"Mã số: 6036\n\n(Dân trí) - Nhờ bác sĩ tận tình cứu chữa và bạn đọc Dân trí cùng các nhà hảo tâm hỗ trợ hơn 144 triệu đồng, chị Triệu Mùi Pham đã đi lại được sau đột quỵ. Về nhà, chị tự chăm sóc bản thân, phụ con việc nhẹ nhàng.\n\nTrong những hình ảnh mới nhất gia đình gửi tới phóng viên Dân trí, chị Triệu Mùi Pham (SN 1982, dân tộc Dao, trú tại xã Thành Công, tỉnh Cao Bằng) đã có thể làm những việc nhà nhẹ nhàng như nhặt rau, nấu cơm...\n\nCách đây chưa lâu, sau cơn đột quỵ, chị Mùi Pham bị liệt nửa người bên trái, nói khó, mọi sinh hoạt đều phụ thuộc vào con trai. Nay, chị đã đi lại được, tự chăm sóc bản thân và được xuất viện về nhà.\n\nVới Đặng Kiềm Nần (SN 2001, con trai chị Pham), sự hồi phục của mẹ giúp em vơi đi nhiều lo lắng. Những ngày mẹ nằm viện, Nần luôn túc trực chăm sóc, từ ăn uống, xoa bóp tay chân đến vệ sinh cá nhân, đồng thời động viên mẹ kiên trì điều trị. Giờ đây, thấy mẹ dần hồi phục, Nần phần nào yên tâm hơn.\n\nVừa qua, báo Dân trí phối hợp cùng Bệnh viện Châm cứu Trung ương trao biển biểu trưng số tiền 114.776.436 đồng bạn đọc ủng hộ tới gia đình chị Mùi Pham.\n\nToàn bộ số tiền đã được báo Dân trí kết chuyển vào tài khoản của Kiềm Nần trước đó, để kịp thời phục vụ việc chữa bệnh cho mẹ. Ngoài ra, qua tài khoản cá nhân, Nần còn nhận được hơn 30 triệu đồng từ các nhà hảo tâm. Đến nay, tổng số tiền gia đình chị Mùi Pham được hỗ trợ là hơn 144 triệu đồng.\n\nSau quá trình điều trị, sức khỏe chị Mùi Pham đã cải thiện, khả năng vận động dần hồi phục. Từ chỗ nằm trên giường, cần con giúp đỡ từng việc, chị đã có thể tự đi lại. Khi được xuất viện, chị tiếp tục trở về với những sinh hoạt quen thuộc trong gia đình.\n\nChị Triệu Mùi Pham là nhân vật trong bài viết “Góa phụ 44 tuổi người Dao đột quỵ, liệt nửa người: ‘Xin thương mẹ con em!'”, đã được báo Dân trí đăng tải trước đó.\n\nTrước khi đổ bệnh, chị Mùi Pham một mình nuôi con sau khi chồng và con trai út mất trong trận lũ quét 14 năm trước. Kiềm Nần cùng mẹ may mắn sống sót. Hoàn cảnh gia đình khó khăn, học hết lớp 5, Kiềm Nần nghỉ học, theo mẹ làm nương, chăn nuôi.\n\nHai mẹ con vay ngân hàng để có tiền đối ứng xây nhà theo chương trình xóa nhà tạm và phát triển chăn nuôi. Thế nhưng, ngày 19/4, khi căn nhà vừa dựng xong, chị Mùi Pham bất ngờ đột quỵ lúc đang cho lợn ăn.\n\nĐể có tiền chữa bệnh cho mẹ, Kiềm Nần phải bán 3 con trâu cùng đàn lợn. Số tiền nhanh chóng cạn, trong khi khoản nợ hơn 200 triệu đồng vẫn chưa trả được. Mẹ cần tiếp tục điều trị khiến Nần càng thêm lo lắng.\n\nSau khi hoàn cảnh của gia đình được báo Dân trí phản ánh, bạn đọc và các nhà hảo tâm đã chung tay giúp đỡ. Số tiền hơn 144 triệu đồng là nguồn hỗ trợ quý giá, giúp gia đình chị Mùi Pham có thêm điều kiện tiếp tục điều trị trong lúc khó khăn.\n\nChứng kiến mẹ đã có thể đi lại, tự chăm sóc bản thân, Kiềm Nần gửi lời cảm ơn sâu sắc tới các y, bác sĩ, Phòng Công tác xã hội Bệnh viện Châm cứu Trung ương, báo Dân trí, bạn đọc và các nhà hảo tâm đã giúp đỡ hai mẹ con.\n\nChị Nguyễn Thị Lan, cán bộ Phòng Công tác xã hội Bệnh viện Châm cứu Trung ương, cảm ơn báo Dân trí và bạn đọc đã đồng hành cùng bệnh viện, hỗ trợ gia đình chị Triệu Mùi Pham nói riêng và những bệnh nhân có hoàn cảnh khó khăn điều trị tại bệnh viện nói chung.","author":"Hương Hồng","category":"Nhân ái","publishedAt":"2026-10-18 13:22","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/ban-doc-tiep-suc-goa-phu-liet-nua-nguoi-hoi-phuc-tu-cham-soc-ban-than-20261018132253540.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/Bs2xF8xQgqGHeQ67EcjQf3MLs8M=/zoom/1200_630/2026/10/18/1s-edited-cropped-1792304336918.jpg","crawledAt":"2026-10-21T13:43:42.382Z"},{"id":"dtri-20261018001546767","title":"Cận cảnh dòng MPV thuần điện Wuling Darion giá 839 triệu đồng","slug":"can-canh-dong-mpv-thuan-dien-wuling-darion-gia-839-trieu-dong","excerpt":"Tại thị trường Việt Nam, mẫu MPV thuần điện Wuling Darion đến từ Trung Quốc có hai phiên bản, với giá bán lần lượt là 769 triệu đồng và 839 triệu đồng. Xe được lắp ráp tại Việt Nam.","content":"Cụ thể, phiên bản Darion Eco 450km có giá 769 triệu đồng, trong khi phiên bản Darion Luxury 500km giá 839 triệu đồng. Số km trong tên gọi của các phiên bản thể hiện phạm vi di chuyển của xe sau mỗi lần sạc đầy pin.\n\nTrong thời gian đầu mở bán, Wuling triển khai chương trình ưu đãi giảm khoảng 60 triệu đồng cho cả hai phiên bản của Darion. Hãng xe Trung Quốc không công bố thời gian chương trình kết thúc.\n\nVới mức giá trên, Darion có khoảng giá tương đồng với dòng MPV thuần điện BYD M6 (756 triệu đồng) và thấp hơn đáng kể so với các dòng MPV cùng kích cỡ, như Hyundai Custin (820-974 triệu đồng) hay Toyota Innova Cross (730-960 triệu đồng).\n\nThiết kế ngoại thất kiểu MPV truyền thống\n\nWuling Darion có thiết kế ngoại thất khá đơn giản, mang kiểu dáng MPV truyền thống. Điểm nhấn là hệ thống cửa trượt hai bên, trong đó, cửa bên ghế lái có cơ cấu mở điện, còn cửa phía đối diện mở bằng tay.\n\nPhần đầu xe được thiết kế khá liền mạch và ít chi tiết. Hệ thống đèn chiếu sáng trước, đèn hậu và đèn ban ngày đều sử dụng công nghệ LED. Phiên bản Luxury được trang bị hệ thống camera phía trước/sau và hai bên hông để cung cấp hình ảnh 360 độ.\n\nWuling Darion sử dụng bộ mâm 17 inch đi kèm lốp 215/55 R17, có vẻ khá nhỏ so với vóc dáng của xe.\n\nTheo công bố của nhà sản xuất, Darion có kích thước dài x rộng x cao lần lượt là 4.920 x 1.880 x 1.875mm, với chiều dài cơ sở 2.910mm.\n\nKích thước này nhỏ hơn một chút so với Hyundai Custin (4.950 x 1.850 x 1.725mm, chiều dài cơ sở 3.055mm).\n\nHàng ghế thứ hai dạng độc lập\n\nĐiểm nhấn bên trong Wuling Darion là cấu hình ghế ngồi 2+2+3, với hai ghế độc lập ở hàng thứ hai.\n\nKhoang lái của Darion Luxury được thiết kế khá tối giản, với màn hình thông tin giải trí 12,8 inch kết nối Android Auto và Apple CarPlay. Phía sau vô lăng là màn hình hiển thị thông tin cỡ 3,5 inch.\n\nMột số trang bị đáng chú ý của phiên bản Luxury gồm: ghế lái chỉnh điện, cần số sau vô lăng, phanh tay cơ, sạc không dây, ghế bọc da tổng hợp, cửa gió điều hòa cho hàng ghế thứ hai và thứ ba, cổng kết nối USB Type C và Type A, cùng hàng ghế thứ ba có thể ngả.\n\nĐộng cơ điện\n\nDarion được trang bị động cơ điện có công suất 100kW, cho phạm vi di chuyển sau mỗi lần sạc đầy là 500km với bản Luxury và 450km với bản Eco. Xe sử dụng hệ dẫn động cầu trước.\n\nDòng MPV thuần điện Trung Quốc được trang bị bộ pin lithium có dung lượng 60kWh, hỗ trợ cả sạc thường và sạc nhanh; tuy nhiên, Wuling chưa công bố thời gian để sạc đầy pin.\n\nDarion nói riêng và các dòng xe của Wuling nói chung có thể sử dụng hệ thống trạm sạc do MT E-Green phát triển.\n\nCông ty này từng công bố kế hoạch lắp đặt 30.000 trụ sạc chuẩn CCS2 của châu Âu trên toàn quốc đến năm 2030. Tuy nhiên, lộ trình cụ thể cũng như số lượng trạm sạc và súng sạc hiện vẫn chưa được công bố.\n\nNhư vậy, người dùng có thể sạc xe tại nhà, các trạm sạc ở đại lý Wuling, trạm sạc do bên thứ ba phát triển hoặc hệ thống của MT E-Green.\n\nTrang bị an toàn chỉ ở mức cơ bản\n\nWuling Darion Luxury chỉ được trang bị một số tính năng an toàn cơ bản, gồm hệ thống chống bó cứng phanh (ABS), phân phối lực phanh điện tử (EBD), cân bằng điện tử, kiểm soát hành trình, camera 360 độ và cảm biến lùi.\n\nVới thiết kế MPV truyền thống, kích thước rộng rãi, mẫu MPV thuần điện này có thể phù hợp với các gia đình đông người, doanh nghiệp có nhu cầu đưa đón khách hoặc đơn vị kinh doanh dịch vụ vận tải hành khách.\n\nDù có lợi thế về không gian sử dụng và thiết kế cửa trượt, Wuling Darion vẫn phải cạnh tranh với nhiều mẫu MPV trong tầm giá 750-900 triệu đồng.\n\nBản Eco giá niêm yết 769 triệu đồng cao hơn BYD M6 (756 triệu đồng) và VinFast VF MPV 7 (750 triệu đồng). Trong khi đó, bản Luxury giá 839 triệu đồng nằm trong khoảng giá của Hyundai Custin (820-974 triệu đồng), đồng thời cao hơn bản Innova Cross 2.0V chạy xăng (825 triệu đồng).\n\nNếu xét toàn bộ dòng Innova Cross, giá bán dao động từ 730 triệu đồng cho bản 2.0G chạy xăng đến 960 triệu đồng cho bản hybrid 2.0 HEV.\n\nSo với BYD M6, Darion có kích thước tổng thể lớn hơn và bố trí hai ghế độc lập ở hàng thứ hai, tạo lối đi giữa hai ghế để tiếp cận hàng ghế thứ ba. BYD M6 có màn hình trung tâm 12,8 inch, điều hòa tự động và 6 túi khí.\n\nTrong khi đó, VinFast VF MPV 7 có công suất động cơ 150kW, cao hơn mức 100kW của Darion, cùng lợi thế về khả năng tiếp cận hệ thống trạm sạc VinFast.\n\nLợi thế của Wuling Darion nằm ở cấu hình thuần điện, cửa trượt và cách bố trí ghế ngồi. Tuy nhiên, trước khi lựa chọn, người mua cần cân nhắc thêm trang bị an toàn, phạm vi hoạt động thực tế, khả năng tiếp cận trạm sạc và tổng chi phí sở hữu so với các đối thủ cùng tầm giá.","author":"Hội An","category":"Xe ++","publishedAt":"2026-10-18 00:15","source":"dantri.com.vn","url":"https://dantri.com.vn/o-to-xe-may/can-canh-dong-mpv-thuan-dien-wuling-darion-gia-839-trieu-dong-20261018001546767.htm","categories":["Xe ++"],"categoryIds":["o-to-xe-may"],"thumbnail":"https://cdnphoto.dantri.com.vn/Jqb1n66421MUxX59lrwqd6rMDMw=/zoom/1200_630/2026/10/18/dantri-so-sanh-wuling-darion-byd-m6-vietnam4-cropped-1792256663269.jpg?watermark=v1","crawledAt":"2026-10-21T13:43:30.151Z"},{"id":"dtri-20261017202159145","title":"Nhiều học sinh ở TPHCM dương tính với rhinovirus: Bệnh nguy hiểm tới đâu?","slug":"nhieu-hoc-sinh-o-tphcm-duong-tinh-voi-rhinovirus-benh-nguy-hiem-toi-dau","excerpt":"Bên cạnh chùm ca não mô cầu, nhiều học sinh Trường THCS Hai Bà Trưng cũng được ngành y tế TPHCM ghi nhận dương tính với rhinovirus hoặc cúm mùa, phù hợp với bối cảnh dịch bệnh hô hấp đang gia tăng.","content":"(Dân trí) - Bên cạnh chùm ca não mô cầu, nhiều học sinh Trường THCS Hai Bà Trưng cũng được ngành y tế TPHCM ghi nhận dương tính với rhinovirus hoặc cúm mùa, phù hợp với bối cảnh dịch bệnh hô hấp đang gia tăng.\n\n4 ca não mô cầu, nhiều học sinh nhiễm cúm mùa và rhinovirus\n\nTính đến ngày 20/10, TPHCM đã ghi nhận 4 trường hợp mắc não mô cầu nhóm B đều là học sinh Trường THCS Hai Bà Trưng, xã Hiệp Phước. Trong đó, có 1 trường hợp đã tử vong, 3 ca còn lại được điều trị tại Bệnh viện Bệnh Nhiệt đới TPHCM, sức khỏe đã ổn định.\n\nCác chuyên gia nhận định, chùm ca não mô cầu tại Trường THCS Hai Bà Trưng đã được kiểm soát tốt nhờ các biện pháp cắt đứt lây nhiễm theo hướng dẫn của Bộ Y tế; môi trường trường học đủ điều kiện để duy trì việc dạy và học bình thường.\n\nDo đó, Sở Y tế cùng Sở Giáo dục và Đào tạo TPHCM thống nhất việc phụ huynh có thể yên tâm cho con đến trường.\n\nNgoài 4 ca nhiễm não mô cầu, có hơn 20 học sinh cũng nhập Bệnh viện Bệnh Nhiệt đới TPHCM điều trị vì triệu chứng viêm hô hấp. Kết quả xét nghiệm ghi nhận thêm một số em nhiễm cúm A và cúm B (trong đó có trường hợp đồng nhiễm não mô cầu và cúm).\n\nĐồng thời, 21 mẫu phết họng/mũi của các em học sinh do Trung tâm Kiểm soát bệnh tật TPHCM (HCDC) lấy ngày 15/10 cũng ghi nhận nhiều trường hợp dương tính với rhinovirus hoặc virus cúm mùa.\n\nCác chuyên gia lưu ý, thời điểm hiện nay là mùa gia tăng các bệnh viêm hô hấp cấp, nên ngành chức năng cần tiếp tục giám sát, phát hiện sớm và khuyến cáo người có sốt hoặc triệu chứng hô hấp đi khám tại cơ sở y tế, để được hướng dẫn điều trị phù hợp.\n\nRhinovirus có nguy hiểm?\n\nBên cạnh tình hình cúm mùa gia tăng - với chủng cúm A/H1 2009 chiếm ưu thế - đã được ngành y tế TPHCM khuyến cáo từ trước, cộng đồng cũng quan tâm rhinovirus gây bệnh gì, nguy hiểm hay không.\n\nChuyên gia tại Bệnh viện Nhi Trung ương cho biết, bệnh do rhinovirus hay gặp vào mùa đông xuân, với các triệu chứng của cảm lạnh và viêm đường hô hấp trên ở mức độ nhẹ.\n\nTuy nhiên, những đối tượng là trẻ em, đặc biệt là trẻ có bệnh nền, bệnh mạn tính, sức đề kháng kém cần đặc biệt cảnh giác trước nguy cơ nhiễm virus này để tránh trường hợp bệnh diễn biến phức tạp, khó điều trị.\n\nRhinovirus lây truyền theo 2 phương thức: lây trực tiếp từ người sang người do hít phải giọt bắn có dịch tiết đường hô hấp của người bệnh khi tiếp xúc trong khoảng cách gần, hoặc lây gián tiếp qua bàn tay, đồ chơi trẻ em, mặt bàn, ghế... có dính dịch tiết của người bệnh, sau đó xâm nhập vào đường hô hấp và gây bệnh.\n\nTheo Bệnh viện Nguyễn Tri Phương, rhinovirus là loại virus chính gây nên hội chứng cảm lạnh thông thường ở người. Thời gian ủ bệnh là 2-4 ngày, sau đó xuất hiện các triệu chứng: sốt nhẹ, hắt hơi, sổ mũi, đau họng, ho, đau đầu, đôi khi có cảm giác ớn lạnh. 1/3 số trường hợp có triệu chứng ho và khàn giọng.\n\nBệnh thường kéo dài khoảng 1 tuần rồi tự khỏi. Nhưng ở trẻ em suy dinh dưỡng, bị nhiễm lạnh kéo dài, suy giảm miễn dịch có thể dẫn đến viêm phế quản, viêm phế quản phổi hoặc viêm phổi bội nhiễm với tình trạng nặng.\n\nChuyên gia cho biết, rhinovirus lưu hành quanh năm, tính mùa vụ khác nhau tùy vị trí địa lý và điều kiện khí hậu. Do virus có nhiều type và đáp ứng miễn dịch sau nhiễm không bảo vệ đầy đủ trước tất cả các type, một người có thể nhiễm rhinovirus nhiều lần.\n\nTriệu chứng ở người nhiễm rhinovirus thường kéo dài dưới 7 ngày, nhưng có thể tồn tại đến khoảng 2 tuần. Đáng chú ý, các triệu chứng không đặc hiệu cho rhinovirus mà còn có thể gặp trong những bệnh nhiễm virus hô hấp khác, như cúm và Covid-19. Vì vậy, khó xác định chắc chắn nguyên nhân bệnh chỉ dựa vào triệu chứng.\n\nMặc dù phần lớn người nhiễm rhinovirus diễn tiến nhẹ, một số trường hợp có thể gây bệnh nghiêm trọng hơn, hoặc liên quan đến các tình trạng như: viêm tai giữa; viêm xoang; viêm tiểu phế quản; viêm phế quản; viêm phổi; khởi phát cơn hen hoặc làm nặng thêm triệu chứng hen phế quản.\n\nHiện chưa có thuốc kháng virus đặc hiệu được phê duyệt điều trị nhiễm rhinovirus. Phần lớn trường hợp có thể tự hồi phục. Việc chăm sóc chủ yếu nhằm giảm triệu chứng, giúp người bệnh dễ chịu hơn và theo dõi các dấu hiệu bất thường.","author":"Biên Thùy","category":"Sức khỏe","publishedAt":"2026-10-17 20:21","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/nhieu-hoc-sinh-o-tphcm-duong-tinh-voi-rhinovirus-benh-nguy-hiem-toi-dau-20261017202159145.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/kq5BuIOuERWZ3KkqUU4LNqZBXPU=/zoom/1200_630/2026/10/20/rhinovirus-cropped-1792469931799.jpg","crawledAt":"2026-10-21T13:42:35.726Z"},{"id":"dtri-20261017125912399","title":"Hơn 2.000 áo phao mang hơi ấm, giúp vơi nỗi lo trước mùa mưa lũ","slug":"hon-2000-ao-phao-mang-hoi-am-giup-voi-noi-lo-truoc-mua-mua-lu","excerpt":"2.040 chiếc áo phao được trao trước mùa lũ giúp ông bố đơn thân nuôi 3 con nhỏ hay người con chăm mẹ già 96 tuổi, cùng nhiều hộ dân ở xã Đại Lộc, Hà Nha (Đà Nẵng) vơi nỗi lo trước mùa lũ.","content":"Thêm áo phao, vơi nỗi bất an mùa lũ\n\nCầm chiếc áo phao trên tay, ông Nguyễn Trưởng (53 tuổi, trú xã Hà Nha) rất vui mừng, vì từ nay, mẹ con ông có thêm phương tiện bảo vệ bản thân khi nước lũ tràn về. Với người đàn ông sức khỏe suy giảm sau tai biến, không biết bơi và đang chăm sóc mẹ già 96 tuổi nằm một chỗ, món quà này với ông có ý nghĩa đặc biệt.\n\nĐây là món quà ông nhận tại chương trình trao 2.040 áo phao tới người dân xã Đại Lộc và Hà Nha (Đà Nẵng) do báo Dân trí phối hợp với Cục Cảnh sát giao thông (CSGT) - Bộ Công an, Quỹ Toyota Việt Nam và chính quyền địa phương tổ chức vào ngày 16/10.\n\nTrận lũ tháng 10/2025 ám ảnh ông Trưởng mỗi khi trời đổ mưa lớn. Nước dâng cuồn cuộn, bao vây căn nhà, ngập sâu hơn 1,5m. Nhìn dòng nước ngày một cao, ông chẳng còn tâm trí nghĩ đến tài sản, chỉ lo làm sao đưa mẹ già yếu đến nơi an toàn.\n\n“Tôi không biết bơi, mẹ lại không thể tự đi lại. Nếu nước dâng nhanh như năm ngoái rất nguy hiểm. Giờ được tặng áo phao, tôi mừng lắm! Có phương tiện phòng thân, mẹ con cũng yên tâm hơn phần nào khi mùa lũ đến”, ông Trưởng chia sẻ.\n\nAnh Đoàn Ngọc Minh (41 tuổi, trú xã Đại Lộc) đón nhận chiếc áo phao với niềm vui xen lẫn sự nhẹ nhõm. Một mình nuôi 3 con nhỏ, đứa lớn học lớp 6, cháu út mới lớp 2, người cha phải cáng đáng mọi việc trong gia đình, từ chuyện cơm áo đến chăm lo cho các con ăn học.\n\nKhông có công việc ổn định, anh Minh chủ yếu dựa vào việc chăn nuôi để kiếm sống. Trận lũ năm 2025, khiến gia đình càng khó khăn khi nước tràn vào nhà gần 0,5m, gây thiệt hại đàn gà, vịt.\n\nĐiều khiến anh Minh lo lắng hơn cả trong những trận lũ không chỉ là thiệt hại vật chất, mà là sự an toàn của 3 con. Trong nhà trước đây không có áo phao, anh lo nếu tình huống nguy hiểm bất ngờ xảy ra, một mình anh sẽ xoay xở thế nào để đưa các con đến nơi an toàn.\n\nKhi nhận được áo phao trước mùa mưa lũ năm nay, anh Minh chia sẻ: “Giờ đã có áo phao tôi mừng lắm, vì có thêm phương tiện để bảo vệ bản thân và các con khi lũ về. Mình cực khổ thế nào cũng được, chỉ mong các con bình an”.\n\nNgồi bên cha, em Đoàn Ngọc Minh Huy (11 tuổi) cũng vui vì có thêm chiếc áo phao để sử dụng khi cần thiết. “Con sợ nhất là nước lũ dâng cao, nhà bị ngập. Giờ có áo phao, con thấy yên tâm hơn!”, Minh Huy nói.\n\nBà Phan Thị Mãn (73 tuổi, trú xã Hà Nha) vẫn nhớ trận lũ tháng 10/2025, khi nước dâng cuồn cuộn trong đêm, gây sạt lở và cuốn trôi nhà. Sống một mình, không có áo phao, bà được chính quyền hỗ trợ sơ tán đến nơi an toàn. “Lần đầu tôi chứng kiến dòng nước xoáy, hung dữ và dâng nhanh đến vậy”, bà Mãn kể.\n\nĐón nhận chiếc áo phao cùng phần quà trị giá 1 triệu đồng, bà Mãn xúc động cảm ơn báo Dân trí, các đơn vị tài trợ và chính quyền địa phương. Với bà, món quà đến trước mùa mưa lũ không chỉ thiết thực mà còn giúp bà có thêm phương tiện tự bảo vệ mình khi nước dâng.\n\nGiúp người dân chủ động ứng phó thiên tai\n\nBà Nguyễn Thị Thu Huyền, Phó Tổng Giám đốc Công ty Ô tô Toyota Việt Nam cho biết, việc chuẩn bị phương tiện bảo hộ từ sớm có ý nghĩa quan trọng tại những địa bàn thường xuyên chịu ảnh hưởng của mưa bão, lũ lụt.\n\nTriển khai từ năm 2025 thông qua Quỹ Toyota Việt Nam, hàng nghìn chiếc áo phao đã được công ty trao đến người dân, học sinh tại các khu vực nguy cơ cao, góp phần nâng cao ý thức an toàn trong cộng đồng.\n\nRiêng chương trình tại Đà Nẵng, 14 đại lý Toyota trên toàn quốc đã chung tay huy động 2.040 áo phao, phân bổ đến người dân 2 xã Đại Lộc, Hà Nha. Mỗi địa phương nhận 1.020 áo phao để phân bổ theo mức độ rủi ro và nhu cầu thực tế, ưu tiên các hộ ở vùng ngập sâu, dễ bị cô lập, gia đình có trẻ nhỏ, người cao tuổi, người bệnh và khuyết tật. Một phần trong tổng số áo phao cũng được dành cho lực lượng phòng, chống thiên tai tại cơ sở.\n\nTrân trọng món quà của bạn đọc báo Dân trí, Cục CSGT, Quỹ Toyota Việt Nam và các đơn vị đồng hành, ông Lê Đỗ Tuấn Khương, Chủ tịch UBND xã Đại Lộc, cho biết, 2.040 áo phao cùng những phần hỗ trợ là sự sẻ chia thiết thực với người dân Đại Lộc và Hà Nha, nơi thường xuyên chịu ảnh hưởng của mưa lũ. Những thiết bị này cũng giúp người dân chủ động hơn trong ứng phó với thiên tai.\n\nPhó Bí thư Thành ủy, Chủ tịch Ủy ban Mặt trận Tổ quốc Việt Nam thành phố Đà Nẵng Nguyễn Đình Vĩnh chia sẻ, địa phương và người dân cảm thấy ấm áp trước sự quan tâm, sẻ chia của đoàn công tác Bộ Nội vụ, báo Dân trí cùng các đơn vị đồng hành.\n\nTheo ông Vĩnh, thành phố đã triển khai nhiều giải pháp phòng, chống thiên tai. Dù vậy, trước diễn biến thời tiết ngày càng khó lường, công tác phòng, chống phải được triển khai chủ động, từ sớm, từ xa, theo phương châm “4 tại chỗ”, kết hợp “3 sẵn sàng”.\n\nTừ thực tế đó, ông Vĩnh đánh giá chương trình trao tặng áo phao mang ý nghĩa thiết thực, giúp người dân vùng có nguy cơ chịu ảnh hưởng bởi thiên tai có thêm phương tiện bảo vệ bản thân khi xảy ra tình huống khẩn cấp.\n\nChương trình trao 2.040 áo phao tại 2 xã Đại Lộc và Hà Nha do báo Dân trí phối hợp với Cục CSGT, Quỹ Toyota Việt Nam và chính quyền địa phương tổ chức.\n\nDịp này, 50 hộ dân ngoài được tặng áo phao, báo Dân trí cùng với sự đồng hành của Quỹ Toyota Việt Nam, Tổng Công ty điện lực miền Trung, Công ty TNHH một thành viên Quang Minh Bảo, Toyota Trang Lê Quảng Nam, trao tặng 50 phần quà bằng tiền mặt, trị giá mỗi phần quà 1 triệu đồng nhằm chia sẻ một phần khó khăn với các gia đình.\n\nBan tổ chức cũng trao học bổng tới 10 học sinh có hoàn cảnh khó khăn tại xã Đại Lộc, mỗi suất 1 triệu đồng và áo phao. Tặng quà trực tiếp 2 gia đình có hoàn cảnh đặc biệt khó khăn tại thôn Nghĩa Mỹ, xã Đại Lộc, mỗi phần quà trị giá 5 triệu đồng.\n\nCó 14 đại lý Toyota đồng hành tài trợ áo phao, gồm: Toyota An Sương, Toyota Bắc Giang, Toyota Bắc Ninh, Toyota Bến Tre, Toyota Biên Hòa, Toyota Cần Thơ - Chi nhánh An Giang, Toyota Hùng Vương, Toyota Mỹ Đình, Toyota Ninh Kiều, Toyota Phú Thọ, Toyota Thăng Long, Toyota Tiến Thu Quảng Ngãi, Toyota Tiền Giang và Toyota Trang Lê Quảng Nam.\n\nBáo Dân trí đồng hành cùng Quỹ Toyota Việt Nam trao tặng 2.040 áo phao tới người dân vùng rốn lũ\n\nTrao 2040 áo phao, thêm điểm tựa cho người dân vùng lũ\n\nPhó Bí thư Thành ủy Đà Nẵng: \"Chúng tôi và bà con cảm thấy ấm áp\"\n\n2.040 áo phao và những tấm lòng hướng về người dân vùng lũ\n\nÁo phao sẽ được ưu tiên người dân dễ bị tổn thương khi mưa lũ xảy ra\n\n2.040 áo phao sẵn sàng được trao đến người dân vùng lũ Đà Nẵng\n\nLũ cuốn đi cả gia tài, để lại hai phận đời\n\nHơn 2.000 áo phao về vùng rốn lũ\n\nLớp bảo vệ đầu tiên khi nước lũ dâng lúc nửa đêm\n\nVật dụng quý giá giúp giữ mạng sống trong mưa lũ\n\nNỗi ám ảnh về lũ lịch sử chưa hết lại thấp thỏm trước mùa mưa bão mới","author":"Hoài Sơn","category":"Nhân ái","publishedAt":"2026-10-17 12:59","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/hon-2000-ao-phao-mang-hoi-am-giup-voi-noi-lo-truoc-mua-mua-lu-20261017125912399.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/lqiCdZ5S2J5-mJI3midTKGo3GTI=/zoom/1200_630/2026/10/17/trao-ao-phao-da-nanghoai-son1-cropped-1792216369682.jpg","crawledAt":"2026-10-21T13:43:42.509Z"},{"id":"dtri-20261017085820167","title":"Cha phụ hồ nuôi con trai ung thư được bạn đọc giúp gần 240 triệu đồng","slug":"cha-phu-ho-nuoi-con-trai-ung-thu-duoc-ban-doc-giup-gan-240-trieu-dong","excerpt":"Cha nghèo phụ hồ cầu xin cứu con 15 tuổi bị ung thư nguy cơ cắt bỏ chân","content":"Mã số: 6028\n\n(Dân trí) - Nhờ tấm lòng nhân ái của bạn đọc Dân trí, anh Phú kịp thời đưa con trai đi bệnh viện điều trị căn bệnh ung thư cơ đùi trái.\n\nVừa qua, phóng viên báo Dân trí khu vực Đồng bằng sông Cửu Long đã đến thăm và trao số tiền 207.983.589 đồng tới gia đình anh Trần Thanh Phú (44 tuổi, ngụ ấp Trinh Phụ, xã Tân Hòa, tỉnh Vĩnh Long).\n\nAnh Phú là nhân vật trong bài viết \"Cha nghèo phụ hồ cầu xin cứu con 15 tuổi bị ung thư nguy cơ cắt bỏ chân\", đăng ngày 3/8.\n\nThông qua Chương trình Nhân ái của báo Dân trí, bạn đọc khắp nơi nhanh chóng ủng hộ số tiền nói trên để anh Phú kịp thời đưa con đi điều trị. Ngoài ra, thông qua số tài khoản ngân hàng của mình, anh Phú còn nhận được gần 30 triệu đồng. Như vậy, tổng số tiền gia đình được bạn đọc giúp đỡ gần 240 triệu đồng.\n\n\"Tôi vô cùng biết ơn tấm lòng bạn đọc Dân trí đã quan tâm, yêu thương con trai tôi! Nếu không rơi vào cảnh túng quẫn, tôi sẽ không cầu cứu mọi người. Vợ chồng tôi dù có nằm mơ cũng không bao giờ nghĩ trong thời gian ngắn lại có được số tiền lớn đến như thế\", anh Phú xúc động nói.\n\nChị Lữ Thị Thuỳ Dương (42 tuổi, mẹ của Thịnh) kể: \"Sau khi có tiền điều trị tiếp tục, sức khỏe của con tôi tiến triển tốt hơn. Tuy nhiên, đợt tái khám vừa rồi, bác sĩ nói trong vùng bẹn của con có khối u nhỏ nên phải tiếp tục hóa trị. Nếu khối u teo lại thì không ảnh hưởng tính mạng. Vợ chồng tôi lo lắm!\".\n\nNhư Dân trí đã đưa tin, hè năm ngoái, Thịnh mắc căn bệnh ung thư cơ đùi trái. Một năm qua, cậu bé đã trải qua 2 lần phẫu thuật, 12 toa hóa trị, số ngày em sống trong bệnh viện còn nhiều hơn ở nhà.\n\nBan đầu, Thịnh điều trị ở Bệnh viện Đa khoa Trà Vinh, sau đó chuyển lên Bệnh viện Nhi đồng 1 và Bệnh viện Ung bướu cơ sở 2 TPHCM.\n\n\"Mỗi toa hóa trị tốn 35 triệu đồng. Tổng viện phí, tiền phẫu thuật, xét nghiệm, sinh thiết, thuốc men, đi lại và ăn uống đã lên đến 300 triệu đồng. Tôi đã vay mượn họ hàng, người thân 120 triệu đồng\", anh cho biết.","author":"Bảo Kỳ","category":"Nhân ái","publishedAt":"2026-10-17 08:58","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/cha-phu-ho-nuoi-con-trai-ung-thu-duoc-ban-doc-giup-gan-240-trieu-dong-20261017085820167.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/mvra_JVR7Sxlwb3fvqvmJVHH06o=/zoom/1200_630/2026/10/17/trao-tienbao-ky-2-edited-cropped-1792202158283.jpg?watermark=v1","crawledAt":"2026-10-21T13:43:39.905Z"},{"id":"dtri-20261012185502542","title":"Gặp lại phi công hào hoa trong bức ảnh phi đội Quyết Thắng huyền thoại","slug":"gap-lai-phi-cong-hao-hoa-trong-buc-anh-phi-doi-quyet-thang-huyen-thoai","excerpt":"Ở tuổi 78, Đại tá Từ Đễ vẫn giữ đôi mắt tinh anh, nhanh nhạy. Ông kể về người cha lỗi lạc, ký ức chiến đấu và những nỗi niềm, phút lãng mạn của một phi công \"suýt làm họa sĩ\".","content":"Sáu người phi công bước bên nhau trước những chiếc A-37, tay cầm mũ bay, gương mặt rạng rỡ. Bức ảnh huyền thoại ghi lại khoảnh khắc phi đội Quyết Thắng, gồm Nguyễn Văn Lục, Hán Văn Quảng, Nguyễn Thành Trung, Từ Đễ, Hoàng Mai Vượng và Trần Văn On, trở về sân bay Phan Rang chiều tối 28/4/1975, sau trận ném bom sân bay Tân Sơn Nhất.\n\nNgười đứng trung tâm bức ảnh với vóc dáng cao ráo, nở nụ cười tươi là phi công Từ Đễ, khi ấy mới 26 tuổi.\n\n51 năm sau, nụ cười của ông vẫn giữ nguyên nét rạng rỡ như thời trai trẻ. Tiếp phóng viên Dân trí tại nhà riêng ở TPHCM, Đại tá, Anh hùng Lực lượng vũ trang nhân dân (AHLLVTND) Từ Đễ gây ấn tượng bởi đôi mắt tinh anh, nhanh nhạy, ánh lên niềm tự hào mỗi khi nhắc về những năm tháng chiến đấu rực lửa trên bầu trời.\n\nBữa cơm với người từng bên kia chiến tuyến\n\nTên tuổi Đại tá Từ Đễ gắn với chiến công của phi đội Quyết Thắng trong trận ném bom sân bay Tân Sơn Nhất ngày 28/4/1975. Nhưng phía sau trận đánh lịch sử còn là những kỷ niệm ít người biết và nỗi niềm ông mang theo suốt hơn nửa thế kỷ.\n\nSau khi giải phóng Đà Nẵng, quân ta thu được máy bay A-37 cùng cơ sở kỹ thuật của đối phương. Để nhanh chóng làm chủ loại máy bay này, ông Từ Đễ cùng đồng đội đề xuất tìm những phi công có kinh nghiệm trong khu trại giam tù, hàng binh tại Quân khu 5.\n\nĐược cấp trên đồng ý, ông đề nghị tập trung các phi công theo cấp bậc, ưu tiên người trẻ, quân hàm thấp, xuất thân nông dân, lý lịch tốt. Hai người được chọn là Trần Văn On và Nguyễn Văn Xanh.\n\nLúc đến gặp Từ Đễ, cả hai phi công chính quyền cũ còn lo sợ, mặt tái đi. Trước mặt họ là phi đội phó 26 tuổi, đeo súng bên hông, dáng vẻ nghiêm nghị. Ông Từ Đễ từ tốn giải thích rằng mình cần sự giúp đỡ của họ.\n\n“Tôi chọn các anh để nhờ giúp chúng tôi học lái A-37. Các anh sẽ cùng ăn, cùng ở với chúng tôi. Chúng tôi làm gì, các anh làm nấy”, ông kể lại.\n\nĐơn vị bố trí chỗ ở, thực hiện “ba cùng”: Cùng ăn, cùng ở, cùng làm việc. Bữa cơm đầu tiên, mọi người trải chiếu ngồi dưới đất, ăn thịt hộp và rau chuyển từ Đà Lạt xuống. Buổi tối, ông Từ Đễ sang thăm, hỏi han rồi kể vài chuyện tiếu lâm. Cả nhóm cười phá lên.\n\n“Cùng ăn, cùng ở chưa đủ, chúng tôi còn phải tạo tinh thần thoải mái để các anh hòa nhập. Kể chuyện cười cũng là một cách hiểu văn hóa, trí tuệ của nhau”, ông nói.\n\nQua những ngày học chuyển loại gấp rút, khoảng cách giữa những người từng ở hai chiến tuyến dần thu hẹp. “Các anh ấy từng học ở Mỹ, truyền đạt kinh nghiệm rất tốt. Trình độ thì chúng tôi hơn, nhưng kinh nghiệm bay A-37 thì tôi không ngại nói rằng anh On và anh Xanh hơn chúng tôi”, Đại tá Từ Đễ nhìn nhận.\n\nCuối tháng 4, sân bay Tân Sơn Nhất được lựa chọn làm mục tiêu tiến công: Diện tích rộng, dễ nhận biết từ xa, thuận lợi cho việc tiếp cận. Đánh vào đây còn tác động trực tiếp đến cầu hàng không, gây thêm rối loạn trong những ngày cuối của chính quyền Sài Gòn.\n\nTrước giờ xuất kích ngày 28/4/1975, Tư lệnh Quân chủng Phòng không - Không quân Lê Văn Tri căn dặn rất nghiêm. Phi đội phải ném trúng mục tiêu, đồng thời tuân thủ bốn yêu cầu: Không để bom rơi vào nhà ga, khu vực phái đoàn bốn bên, đường băng và khu dân cư Sài Gòn.\n\n“Ai để bom rơi sai vị trí là chết với tôi”, ông Từ Đễ nhớ lại lời người chỉ huy.\n\nNhìn lại chiến công, Đại tá Từ Đễ nhấn mạnh, giá trị tinh thần của đòn đánh là đúng thời điểm, khi đối phương đã suy yếu. Trận tiến công gây rối loạn hoạt động di tản, tác động mạnh đến bộ máy quân sự và chính quyền Sài Gòn. “Chúng tôi không tài giỏi gì. Câu chuyện của chúng tôi cũng như bao người trong chiến tranh. Nhưng cái hay là đánh chính xác về thời điểm”, cựu phi công nói.\n\nÔng kể, trên đường qua khu vực Vũng Tàu để vào Sài Gòn, thời tiết xấu, mây che kín, phi đội phải sử dụng thiết bị dẫn đường. Phía sân bay Tân Sơn Nhất đã phát hiện tốp máy bay và kịp báo động, sơ tán trước khi phi đội đến mục tiêu khoảng 8-9 phút.\n\n“Tôi bay vị trí số 2, ném bom cháy bốn chiếc C-47 tại sân bay Tân Sơn Nhất, không thấy chiếc ô tô nào. Tôi khẳng định, trận đánh không có người chết, chỉ có một người lính bị thương. Chúng tôi ấm ức nhiều năm vì mang tiếng gây thiệt hại tính mạng người dân. Không hề có chuyện này”, ông nói.\n\nCon trai cả của nhà khoa học “huyền thoại”\n\nĐại tá Từ Đễ hiện sống trong căn nhà xanh mát ở phường Tân Sơn Hòa, TPHCM. Trước hiên là khoảng vườn nhỏ với những chậu cây treo, hồ nước, bể cá. Ông nói, nếp sống gần gũi thiên nhiên ấy chịu ảnh hưởng từ cha - Giáo sư, nhà khoa học Từ Giấy.\n\nGia đình có hai thế hệ được phong tặng danh hiệu Anh hùng là điều hiếm có. Với ông Từ Đễ, niềm tự hào về cha còn nằm trong những lời dặn và lý tưởng sống đã theo ông từ thuở nhỏ. “Cha luôn là tấm gương về nhân cách, tinh thần học tập và lao động suốt đời để chúng tôi noi theo”, ông nói.\n\nXuất thân nghèo khó, nhờ bền bỉ tự học, Giáo sư Từ Giấy trở thành nhà khoa học hàng đầu, một trong 20 “huyền thoại sống của ngành dinh dưỡng thế giới”. Trong gia đình, cụ giữ nếp sống khiêm nhường, dạy các con biết đủ, tự trọng và chịu trách nhiệm.\n\nÔng Từ Đễ nhớ cha rất tỉ mỉ, đi đâu cũng mang giấy bút ghi chép, “không thích lý thuyết suông”, vận dụng kiến thức khoa học để chăm lo cuộc sống từ những việc nhỏ nhất.\n\nỞ căn nhà số 51 Quán Thánh (Hà Nội) năm xưa, có một bức tường ghi lại quá trình lớn lên của ba anh em Từ Đễ, Từ Linh, Từ Ngữ. Thỉnh thoảng, cụ Từ Giấy gọi từng người đứng sát tường để đo chiều cao, rồi vạch một nét, ghi số đo cùng ngày, tháng bên cạnh.\n\nCụ dạy các con giữ tóc ngắn gọn gàng, rửa tay trước khi ăn. Khi Từ Đễ bước vào tuổi dậy thì, phần xôi của ông được cha rưới thêm ít mỡ để bồi bổ. Cụ Từ Giấy cũng chọn môn học bổ trợ theo tính cách từng con.\n\nTừ Đễ khỏe mạnh, tính tình mạnh mẽ nhất, được học vẽ để rèn sự mềm dẻo, kiên trì, tỉ mỉ. Từ Linh điềm đạm thì học violin. Cậu út Từ Ngữ thể chất yếu hơn hai anh được học bóng bàn, bóng đá.\n\nLà trưởng nam, ông Từ Đễ tự nhắc mình phải làm được điều gì đó xứng đáng. Cha khuyến khích ông học để mở mang hiểu biết, cống hiến cho đất nước, nhưng để con tự chọn đường đi, tự lo tương lai, không dựa dẫm.\n\n“Trong gia đình, cha là người đã truyền lửa cách mạng cho tôi từ thời niên thiếu”, ông kể.\n\nNăm 1965, khi mới 16 tuổi, Từ Đễ tình nguyện nhập ngũ, sang Liên Xô học lái máy bay. “Thời đó, nghề lái máy bay được nhiều người xem là có \"giá\". Ông bước vào chặng đường mới với bao háo hức, nhưng trải qua thực tế mới thấm thía những vất vả, thử thách.\n\nNăm 18 tuổi, khi còn học ở Liên Xô, ông gặp sự cố trong chuyến bay đơn trên MiG-17: Càng bên phải không thả được khi chuẩn bị hạ cánh. Chỉ huy định cho ông nhảy dù, nhưng trung đoàn trưởng quyết định để người học viên trẻ hạ cánh bằng bụng máy bay.\n\n“Tôi may mắn hạ cánh ngon lành”, cựu phi công kể. Sau lần ấy, ông được Tư lệnh Không quân Liên Xô tặng chiếc đồng hồ Poljot. Còn mẹ ông ở quê nhà nghe tin từ sứ quán thì “sợ chết khiếp nghề bay”.\n\nTrở về nước, chàng trai 18 tuổi bước vào chiến đấu với khoảng 200 giờ bay, tự nhận mình là “chíp hôi” so với những phi công đối phương đã tích lũy 700, 2.000 giờ bay. Qua từng trận đánh, Đại tá Từ Đễ cùng những phi công cùng thế hệ tiếp tục mày mò, rút kinh nghiệm rồi trưởng thành.\n\nTừ những chuyến xuất kích trong kháng chiến chống Mỹ đến thời gian chiến đấu ở Campuchia, ông vẫn mang theo lời cha mẹ dặn làm điểm tựa.\n\n“Trước khó khăn, tôi luôn nhớ: Phải có lòng tự trọng, làm việc nghiêm túc, sống lương thiện, tử tế và giữ danh dự”, ông nói.\n\nTuổi U80 vui thú hội họa bên khu vườn nhỏ\n\nMỗi dịp tháng 10, đến ngày sinh của cha, Đại tá Từ Đễ lại mở những album ảnh, cùng con cháu ôn chuyện cũ. Trong những kỷ niệm ấy, ông nhớ nhất cuộc hội ngộ với cha ngày đất nước vừa hòa bình.\n\nBên bộ bàn ghế tiếp khách, bức ảnh hai cha con được treo trang trọng. Ông xúc động giới thiệu với phóng viên Dân trí khoảnh khắc đã gìn giữ suốt 51 năm.\n\nNgày 4/5/1975, vừa trở về sau chuyến bay tuần tra biển, quần áo còn ướt đẫm, Từ Đễ gặp cha tại sân bay Biên Hòa. Lần gần nhất họ gặp nhau là tháng 2, khi chiến tranh chưa kết thúc. Giữa những lá cờ đỏ sao vàng, hai cha con ôm chầm lấy nhau trong niềm vui đất nước hòa bình.\n\nNgười cha vốn cương nghị, ít biểu lộ cảm xúc, nhưng hôm ấy, phi công Từ Đễ thấy mắt cha ánh lên niềm tự hào. Giáo sư Từ Giấy nhắc con trai cả: “Hòa bình rồi, về nhà thôi, mẹ chờ”.\n\nỞ Hà Nội, mẹ ông vẫn chưa biết tin về chồng và con trong những ngày tham gia chiến dịch. Đến ngày 7/5, đọc bài báo về phi đội Quyết Thắng, bà mới biết con mình còn sống.\n\nHơn nửa thế kỷ trôi qua, lời cha nói trong cuộc trùng phùng ấy vẫn được ông khắc ghi. Nay ở tuổi U80, người phi công năm nào vui thú với hội họa, chăm cây và sống bình yên bên gia đình trong căn nhà trên đường Cửu Long, TPHCM. Con trai làm kiến trúc sư, con gái là họa sĩ. Con dâu, con rể và tám người cháu cùng chung sống dưới một mái nhà.\n\nKhi các con đi làm, cháu đi học, ông cùng vợ - bà Huỳnh Hồng Hoa - chăm chút khoảng vườn nhỏ. Có lúc ông ngồi đọc sách, thư giãn bên hồ nước, có lúc lại cầm bút vẽ. Trong những ngày thảnh thơi ấy, ông càng thấm lời cha dạy về sự tự lập, tinh thần học hỏi và cách sống tận tụy.\n\nĐại tá Từ Đễ trang trí không gian sống bằng mô hình máy bay, xen kẽ cùng những bức tranh, gợi nhắc cuộc đời gắn bó với bầu trời và niềm say mê nghệ thuật của ông (Ảnh: Thái Uyên).\n\nGiới thiệu những bức tranh trong nhà với phóng viên Dân trí, Đại tá Từ Đễ nói vui, nếu không trở thành phi công, có lẽ ông đã là họa sĩ. Thuở nhỏ, tính tình mạnh mẽ, ông được cha cho học vẽ để rèn sự kiên trì, tỉ mỉ. Cha ông tuy là bác sĩ quân y, nhà khoa học nhưng cũng làm báo, yêu nghệ thuật và có nhiều bạn bè trong giới văn chương, hội họa, âm nhạc.\n\nNhờ cha, từ nhỏ ông được nghe nhạc, tiếp xúc với nghệ thuật, luôn ý thức làm phong phú cuộc sống tinh thần. Tình yêu nghệ thuật theo ông cả trong những năm tháng chiến đấu, nuôi dưỡng nét lãng tử của người phi công giữa bom đạn.\n\n\"Nghề bay là nghề mưu sinh nhưng tôi vẫn luôn đam mê hội họa. Cha tôi nói làm nghề gì thì làm, nhưng nghệ thuật mới là nguồn cội cuộc sống, giúp con người sống bền. Đó là lý do vì sao cho đến tuổi này tôi vẫn luôn thích nghệ thuật, vẽ vời\", AHLLVTND Từ Đễ khẽ nói.\n\nĐại tá Từ Đễ là con trai cả của giáo sư, Anh hùng Lao động Từ Giấy. Năm 1965, ông tình nguyện nhập ngũ, sang Liên Xô học lái máy bay. Sau khi trở về nước, ông tham gia kháng chiến chống Mỹ.\n\nÔng từng là phi công lái máy bay MiG-17 tại Đại đội 4, Trung đoàn Không quân 923 (Đoàn Không quân Yên Thế), Sư đoàn 371, Quân chủng Phòng không - Không quân.\n\nTháng 4/1975, ông được lựa chọn tham gia phi đội Quyết Thắng tiến công sân bay Tân Sơn Nhất.\n\nSau này, ông giữ chức Phó cục trưởng Cục Quân huấn, Bộ Tổng tham mưu, Bộ Quốc phòng. Ông có nhiều đóng góp trong biên soạn lịch sử, diễn biến hơn 350 trận không chiến của không quân Việt Nam, để lại những kinh nghiệm, bài học quý cho thế hệ sau.\n\nNgày 22/10/2015, ông được phong tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân vì những thành tích trong thời kỳ kháng chiến chống Mỹ.","author":"Bích Phương","category":"Đời sống","publishedAt":"2026-10-12 18:55","source":"dantri.com.vn","url":"https://dantri.com.vn/doi-song/gap-lai-phi-cong-hao-hoa-trong-buc-anh-phi-doi-quyet-thang-huyen-thoai-20261012185502542.htm","categories":["Đời sống"],"categoryIds":["doi-song"],"thumbnail":"https://cdnphoto.dantri.com.vn/ko1zxIe5jQevrSihElsuoXUUxyE=/zoom/1200_630/2026/10/12/daitatude2-cropped-1791806040557.jpg","crawledAt":"2026-10-21T13:42:42.229Z"},{"id":"dtri-20261011101359497","title":"Cầm cự ở viện bằng cơm từ thiện, người phụ nữ Mông khẩn cầu cứu chồng","slug":"cam-cu-o-vien-bang-com-tu-thien-nguoi-phu-nu-mong-khan-cau-cuu-chong","excerpt":"Cầm cự ở viện bằng cơm từ thiện, người phụ nữ Mông khẩn cầu cứu chồng","content":"Mã số: 6127\n\n(Dân trí) - 20 ngày sau ca phẫu thuật khẩn cấp, người đàn ông trụ cột gia đình vẫn ở thế \"ngàn cân treo sợi tóc\". Cầm cự ở bệnh viện bằng cơm từ thiện, người phụ nữ Mông nghèo khó khẩn cầu sự giúp đỡ.\n\nKiệt sức sau 1 ngày làm lụng vất vả, người bố 2 con gặp tai nạn giao thông nguy kịch tính mạng\n\nNhững ngày qua, hoàn cảnh éo le của anh Sùng A Chứ (SN 1994, trú tại xã Sính Phình, tỉnh Điện Biên), trụ cột của 1 gia đình người Mông nghèo, đang điều trị tại Bệnh viện Đại học Y Hà Nội, khiến các y, bác sĩ, người bệnh và người nhà bệnh nhân không khỏi xót xa.\n\n20 ngày sau ca mổ cấp cứu, A Chứ vẫn trong tình trạng nguy kịch. Quanh giường bệnh là máy thở và đủ các loại máy móc, thiết bị y tế tối tân hỗ trợ anh cầm cự mạng sống.\n\nA Chứ nhắm nghiền đôi mắt, khắp người đầy vết trầy xước. Một vết khâu kéo dài từ tai vòng qua sau gáy đến đỉnh đầu vẫn đang sưng tấy.\n\nQua ô cửa kính của phòng bệnh, đôi mắt chị Chang Thị Dùa (SN 1999, vợ của A Chứ), như dán vào cơ thể người chồng. Thấy chồng vẫn nằm bất động, người vợ trẻ bật khóc:\n\n\"Đã hơn 20 ngày rồi, anh vẫn nằm như thế, chẳng nói với em được một lời. A Chứ ơi, anh mà có mệnh hệ gì thì 3 mẹ con em biết sống sao đây!”.\n\nTiếng gọi chồng nghẹn ngào giữa dòng nước mắt. Nỗi đau đớn, sợ hãi cùng những ngày dài thấp thỏm chờ đợi dồn nén dường như vượt quá sức chịu đựng của người vợ.\n\nGạt nước mắt, chị Dùa thổn thức kể, mong muốn thoát khỏi cảnh sống nghèo khó nơi miền núi, A Chứ rời quê nhà, vượt gần 600km xin làm công nhân tại một công ty đóng gói ở TP Hải Phòng.\n\nLương công nhân ít ỏi, để có thêm chút tiền gửi về nhà chăm lo cho 2 con nhỏ và bố mẹ già yếu, ngoài thời gian làm theo ca, A Chứ tìm việc làm thêm.\n\n\"Chiều tối ngày 19/9, chồng em gọi điện cho biết, hết ca chiều ở nhà máy anh xin làm phục vụ ở quán ăn đêm. Đến khoảng 23h, có người gọi điện báo chồng em bị tai nạn giao thông đang được đưa đi cấp cứu. Em nghe tin mà toát mồ hôi hột, đánh rơi cả cái điện thoại xuống đất…”, người vợ tội nghiệp nức nở.\n\nViện phí ngoài Bảo hiểm y tế lên tới 10 triệu đồng/ngày, người vợ nghèo cầu xin giúp đỡ\n\nChồng gặp nạn, trong nhà không có nổi một đồng, chị Dùa phải vay nóng bà con khắp bản được 8 triệu đồng rồi bắt xe xuống Hà Nội với chồng.\n\nChị Dùa cho biết, theo lời kể của những người đi đường tốt bụng đưa chồng đi cấp cứu, đêm muộn ngày 19/9, họ phát hiện A Chứ nằm bất tỉnh bên vệ đường, chiếc xe máy đổ chỏng chơ gần đó. Nhận định ban đầu, có thể A Chứ quá mệt nên tự ngã.\n\nTình trạng của A Chứ quá nặng, chi phí điều trị lớn, gia đình đã phải bán đi mảnh nương là tài sản giá trị nhất trong nhà cùng tất cả gà, vịt và vay mượn khắp nơi được tổng cộng hơn 97 triệu đồng.\n\nNhưng số tiền đó chỉ được 10 ngày đã hết, viện phí của chồng, chị Dùa đành xin khất nợ.\n\nTrong phòng bệnh, người chồng vẫn hôn mê. Ngoài hành lang, người vợ nghèo ngồi thẫn thờ, bế tắc trước cảnh không còn tiền chạy chữa cho chồng.\n\n\"Bác sĩ nói chồng em phải điều trị tích cực, lâu dài nữa mới có hy vọng. Nhà em nghèo khó quá, không biết bấu víu vào đâu. Giờ em chả còn đồng nào trong người, may mắn được các anh chị cho cơm từ thiện hàng ngày. Cầu xin ông bà, cô, chú, anh chị cứu chồng em với!\", chắp tay trước ngực, chị Dùa bật khóc nức nở.\n\nTrao đổi với phóng viên Dân trí, bác sĩ Trần Huyền Trang, Trung tâm Cấp cứu Hồi sức tích cực, Bệnh viện Đại học Y Hà Nội, cho biết: “Bệnh nhân Sùng A Chứ được chuyển đến lúc 23h26 ngày 20/9 trong tình trạng nguy kịch, hôn mê, đa chấn thương nặng.\n\nĐến 0h ngày 21/9, anh Chứ được phẫu thuật cấp cứu mở sọ giải áp. Phần xương sọ lấy ra trong ca mổ đang được bảo quản tại bệnh viện, chờ ghép lại khi tình trạng sức khỏe của anh cho phép”.\n\nTheo bác sĩ Trang, hiện anh Chứ vẫn phải thở máy qua ống nội khí quản, dùng kháng sinh, dinh dưỡng, tập phục hồi chức năng và tiếp tục điều trị hồi sức tích cực. Chi phí gia đình phải chi trả sau Bảo hiểm y tế khoảng 10 triệu đồng/ngày.\n\nQuá trình điều trị, phục hồi chức năng và phẫu thuật ghép lại xương sọ dự kiến còn kéo dài, cần thêm hàng trăm triệu đồng. Bệnh nhân là người dân tộc Mông, thuộc hộ nghèo ở vùng cao đặc biệt khó khăn.\n\n“Bệnh nhân còn trẻ, hy vọng hồi phục cao. Chúng tôi rất mong bạn đọc Dân trí và các nhà hảo tâm chung tay giúp gia đình có thêm kinh phí để bệnh nhân tiếp tục điều trị”, bác sĩ Trang bày tỏ.","author":"Hương Hồng","category":"Nhân ái","publishedAt":"2026-10-11 10:13","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/cam-cu-o-vien-bang-com-tu-thien-nguoi-phu-nu-mong-khan-cau-cuu-chong-20261011101359497.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/i9jpcH0Euz-FrCRy-CLxviYMoZg=/zoom/1200_630/2026/10/11/1c-cropped-1791690775560.jpg","crawledAt":"2026-10-21T13:43:37.768Z"},{"id":"dtri-20261009151525776","title":"Chồng gặp nạn hôn mê, con gái bại não, người vợ trẻ bật khóc cầu cứu","slug":"chong-gap-nan-hon-me-con-gai-bai-nao-nguoi-vo-tre-bat-khoc-cau-cuu","excerpt":"Chồng gặp nạn hôn mê, con nhỏ bại não, người vợ trẻ bật khóc cầu cứu","content":"Mã số: 6126\n\n(Dân trí) - Chồng gặp nạn đa chấn thương nặng, sau hơn 20 ngày nhập viện vẫn hôn mê sâu. Con gái 3 tuổi mắc bại não, phải nằm viện dài ngày. Nỗi đau chồng chất, thiếu phụ quay cuồng trong cảnh khốn khó.\n\nĐi xe máy mua thuốc cho con, người cha gặp nạn “thập tử nhất sinh”\n\nTrên giường bệnh của khoa Hồi sức tích cực, Bệnh viện Hữu nghị Việt Đức, anh Nguyễn Trung Hiếu (SN 1994, trú tại thôn Vàng, xã Gia Phú, tỉnh Lào Cai) nằm bất động, đôi mắt nhắm nghiền. Người đàn ông 32 tuổi mang vết khâu kéo dài từ vùng thái dương lên đỉnh đầu.\n\nHơn 20 ngày sau tai nạn, anh Hiếu vẫn hôn mê sâu. Quanh giường bệnh là các thiết bị y tế, hệ thống dây truyền dịch, ống sonde và những phương tiện hỗ trợ duy trì sự sống.\n\nNgười thường xuyên túc trực bên giường bệnh là bà Lê Thị Tâm (SN 1970, mẹ ruột anh Hiếu). Nắm chặt tay con, người mẹ rưng rưng nước mắt, nghẹn giọng:\n\n“Hơn 20 ngày từ lúc nhập viện, Hiếu vẫn chưa tỉnh lại. Con tôi mà có mệnh hệ gì thì đứa cháu ốm đau bệnh tật của tôi biết trông cậy vào đâu!”.\n\nNói được vài câu bà Tâm lại nâng vạt áo lên lau nước mắt.\n\nTrong lời kể xen lẫn tiếng nấc, bà Tâm cho biết, anh Hiếu và chị Hoàng Thùy Linh (SN 1997) kết hôn năm 2019. Đứa con đầu lòng của đôi vợ chồng trẻ sinh non, bị suy hô hấp nặng. Dù các y bác sĩ đã nỗ lực cứu chữa, đứa trẻ tội nghiệp chỉ ở trên đời được vài ngày…\n\nNăm 2023, bé Nguyễn Thùy Chi ra đời trong sự vui mừng của gia đình. Thế nhưng, khi được 5 tháng tuổi, bé vẫn chưa biết lật, chân tay co cứng. Đưa con đi khám, vợ chồng chị Linh được bác sĩ thông báo bé mắc chứng bại não, cần điều trị tích cực và lâu dài.\n\nTừ đó, bé Chi thường xuyên phải điều trị tại bệnh viện. Vợ chồng chị Linh thay phiên nhau chăm sóc con, không thể làm việc đều đặn như trước. Thu nhập vốn đã ít ỏi nay càng bấp bênh, trong khi chi phí chữa trị cho con và sinh hoạt hàng ngày vẫn là gánh nặng của gia đình.\n\nTối 20/9, anh Hiếu rời nhà bằng xe máy để đi mua thuốc cho con gái. Chỉ hơn 20 phút sau, gia đình bàng hoàng nhận được cuộc điện thoại báo tin anh gặp tai nạn, nằm bất tỉnh bên vệ đường.\n\nTheo lời bà Tâm, gia đình được biết, 1 hộ dân ven đường quên đóng cổng, khiến con ngựa nuôi trong nhà bất ngờ chạy ra, lao vào đầu xe máy của anh Hiếu. Cú va chạm khiến anh ngã, đập đầu xuống mặt đường.\n\nBác sĩ mong bạn đọc Dân trí chung tay giúp đỡ gia đình anh Hiếu\n\nSau tai nạn, gia đình nuôi ngựa đã đến thăm hỏi, hỗ trợ 10 triệu đồng để anh Hiếu chữa trị. Bà Tâm cho biết, dù đang chật vật lo viện phí cho con, gia đình bà không yêu cầu hỗ trợ thêm, bởi hiểu hoàn cảnh của họ cũng rất éo le.\n\nAnh Hiếu bị chấn thương sọ não nặng, hôn mê sâu. Sau khi được cấp cứu ban đầu tại Bệnh viện Đa khoa số 2 tỉnh Lào Cai, anh được chuyển khẩn cấp đến Bệnh viện Hữu nghị Việt Đức để tiếp tục điều trị.\n\nChồng nguy kịch, con gái nhỏ mắc bại não phải điều trị dài ngày, mọi gánh nặng dồn lên vai người vợ trẻ, đẩy gia đình vốn đã khó khăn vào cảnh túng quẫn.\n\nTrong lúc anh Hiếu nguy kịch, bé Chi lại ốm, phải nhập viện tại Lào Cai. Chị Linh chạy đi chạy lại giữa Lào Cai và Hà Nội, vừa chăm chồng, chăm con, vừa tìm cách lo chi phí điều trị cho cả 2.\n\n“Nhà em đang nợ ngân hàng 120 triệu đồng, nợ anh em, bạn bè hơn 200 triệu đồng nữa. Con ốm, chồng nguy kịch, nợ cũ chưa trả được lại thêm nợ mới. Em bế tắc quá, không biết xoay xở thế nào nữa. Xin ông bà, cô bác, anh chị giúp đỡ gia đình em!”, chị Linh bật khóc khi nói chuyện với phóng viên qua điện thoại.\n\nTrao đổi với phóng viên Dân trí, PGS.TS Lưu Quang Thùy, Giám đốc Trung tâm Gây mê và Hồi sức ngoại khoa, Trưởng khoa Hồi sức tích cực 2, Bệnh viện Hữu nghị Việt Đức, người điều trị trực tiếp cho anh Hiếu chia sẻ, bệnh nhân được chuyển đến trong tình trạng đa chấn thương, trong đó chấn thương sọ não rất nặng (Glasgow 6đ), kèm chấn thương ngực.\n\nBệnh nhân đã được phẫu thuật cấp cứu ngay sau khi nhập viện. Hiện, tri giác của anh Hiếu đã khá hơn, nhưng vẫn phải tiếp tục điều trị tích cực kèm theo phục hồi chức năng. Quá trình điều trị dự kiến kéo dài, chi phí lớn.\n\n“Bệnh nhân là trụ cột gia đình, có bố mẹ già và con nhỏ đang mắc bệnh phải điều trị thường xuyên ở bệnh viện. Chúng tôi rất mong bạn đọc Dân trí chung tay cùng các bác sĩ giúp đỡ gia đình, hỗ trợ bệnh nhân tiếp tục điều trị để có thể trở về cuộc sống bình thường”, PGS.TS Lưu Quang Thùy bày tỏ.","author":"Hương Hồng","category":"Nhân ái","publishedAt":"2026-10-09 15:15","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/chong-gap-nan-hon-me-con-gai-bai-nao-nguoi-vo-tre-bat-khoc-cau-cuu-20261009151525776.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/SwmH2yvWs6aO_SBzCOZRyuLMY1U=/zoom/1200_630/2026/10/09/nhan-ai-vd-lc-huonghong1q-cropped-1791533303660.jpg","crawledAt":"2026-10-21T13:43:38.820Z"},{"id":"dtri-20261008221209549","title":"Mỗi khi mưa bão, vợ chồng mù ôm con lần đường đi tránh trú","slug":"moi-khi-mua-bao-vo-chong-mu-om-con-lan-duong-di-tranh-tru","excerpt":"Mỗi khi mưa bão, vợ chồng mù ôm con lần đường đi tránh trú","content":"Mã số: 6124\n\n(Dân trí) - Chị Côi và anh Đàm đều bị mù, hoàn cảnh đặc biệt khó khăn, sống trong ngôi nhà tường đất đã xuống cấp nghiêm trọng. Khi trời mưa bão, anh chị lại phải ôm 2 con sang nhà người thân trú nhờ.\n\nVợ chồng khiếm thị nương tựa nhau xây dựng tổ ấm\n\nTrò chuyện với phóng viên báo Dân trí, chị Nguyễn Thị Côi (SN 1987, quê gốc Hưng Yên) ngậm ngùi nhớ lại tuổi thơ nhiều thiệt thòi. Là con đẻ của người hoạt động kháng chiến bị nhiễm chất độc hóa học, chị sinh ra đã không nhìn thấy ánh sáng. Khi chị mới tròn 1 tuần tuổi, mẹ đột ngột qua đời do nhiễm trùng đường huyết.\n\nMất mẹ từ khi còn đỏ hỏn, lại chẳng thể nhìn thấy ánh sáng, chị Côi không được đi học như bạn bè cùng trang lứa. Mãi sau này, khi tham gia Hội Người mù tỉnh Hưng Yên, chị mới bắt đầu học chữ nổi, học nghề tẩm quất, bấm huyệt để tự nuôi sống bản thân.\n\nCòn anh Chu Văn Đàm (SN 1988, người dân tộc Nùng, trú tại thôn Nà Mìn, xã Yên Phúc, tỉnh Lạng Sơn, chồng chị Côi) sinh ra vốn khỏe mạnh. Thế nhưng, năm 2011, trong một lần khai thác mỏ đá ở Lạng Sơn, anh bị bột nở tách đá bắn vào mắt, khiến đôi mắt vĩnh viễn mất đi ánh sáng.\n\nThương con, bố mẹ anh Đàm chạy vạy khắp nơi, đưa con đến Bệnh viện Mắt Trung ương tại Hà Nội điều trị, với hy vọng có thể ghép giác mạc. Nhưng sau 4 tháng ròng rã bám trụ bệnh viện, đôi mắt anh vẫn không thể cứu chữa. Gia đình vốn nghèo khó càng thêm kiệt quệ, còn anh Đàm từ đó chỉ quanh quẩn ở nhà, không thể tiếp tục đi làm.\n\nNăm 2018, qua sự giới thiệu của người quen, chị Côi và anh Đàm bén duyên. Cùng mang khiếm khuyết về thị lực, anh chị tìm thấy ở nhau sự đồng cảm, rồi nên duyên vợ chồng, xây dựng tổ ấm.\n\nNăm 2024, anh chị đón con gái đầu lòng Chu Ngọc Hân. Đến tháng 7/2026, gia đình có thêm bé trai Chu Văn Chiến. Cả 2 con sinh ra khỏe mạnh, lành lặn, là niềm hạnh phúc lớn đối với đôi vợ chồng khiếm thị.\n\nĐể chăm sóc 2 con nhỏ, vợ chồng chị Côi cũng nhận được sự hỗ trợ từ người thân. Bà Phùng Thị Dịp (mẹ anh Đàm) hiện sống cùng người con trai út nhưng thỉnh thoảng vẫn qua phụ giúp. Anh Chu Văn Đảng (em trai anh Đàm) đảm nhận việc đưa đón cháu Hân đi học hàng ngày.\n\nNỗi day dứt của cha mẹ mù lòa dưới mái nhà dột nát\n\nLên vùng cao Lạng Sơn sinh sống, chị Côi không còn làm nghề tẩm quất vì không có khách và bận chăm con nhỏ. Anh Đàm ở nhà phụ vợ chăm con, tranh thủ trồng thêm ít ngô, nuôi mấy con gà. Bố mẹ chia cho vợ chồng anh Đàm 2 sào ruộng, nhưng việc cày cấy đều phải nhờ anh em họ hàng và bà con làng xóm giúp đỡ.\n\nNguồn sống của gia đình chủ yếu dựa vào khoản trợ cấp xã hội dành cho người khuyết tật đặc biệt nặng của 2 vợ chồng, với mức hơn 1 triệu đồng/người/tháng.\n\nThu nhập ít ỏi chỉ đủ trang trải những nhu cầu thiết yếu, trong khi nỗi lo lớn nhất của vợ chồng chị Côi là ngôi nhà tường đất đã xuống cấp nghiêm trọng, có nguy cơ sập đổ.\n\nĐược xây dựng từ năm 1998, sau gần 30 năm sử dụng, ngôi nhà đã hư hỏng nhiều nơi. Tường đất nứt nẻ, mục nát; cột kèo bị mối mọt, cong vênh; mái lợp fibro xi măng cũng đã cũ hỏng.\n\nMỗi khi trời mưa lớn hay gió bão, nước mưa lại dột lênh láng khắp nhà. Sợ nhà sập, vợ chồng chị Côi lại ôm con lần tìm đường qua nhà em trai tránh trú.\n\n\"Trước đây, chỉ có 2 vợ chồng nương tựa vào nhau thì sao cũng được. Nay đã có 2 con, để các con phải sống trong ngôi nhà dột nát, vợ chồng tôi day dứt lắm. Nhưng ngặt nỗi, kinh tế quá khó khăn...”, chị Côi nghẹn ngào chia sẻ.\n\nTrao đổi với phóng viên Dân trí, ông Triệu Văn Hòa, Chủ tịch Ủy ban MTTQ Việt Nam xã Yên Phúc, cho biết: \"Gia đình anh Đàm, chị Côi có hoàn cảnh đặc biệt khó khăn. Cả 2 vợ chồng đều là người khuyết tật đặc biệt nặng, không có khả năng lao động, lại đang nuôi con nhỏ. Ngôi nhà tường đất của gia đình hiện đã xuống cấp, không còn đảm bảo an toàn.\n\nDù địa phương đã đưa vào danh sách xóa nhà tạm, nhưng gia đình không có khả năng đối ứng. Chúng tôi rất mong báo Dân trí cùng quý bạn đọc, các nhà hảo tâm chung tay giúp đỡ vợ chồng anh Đàm, chị Côi sớm xây được một ngôi nhà kiên cố, để các cháu nhỏ có chỗ ở an toàn\".","author":"Huyền Nguyễn","category":"Nhân ái","publishedAt":"2026-10-08 22:12","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/moi-khi-mua-bao-vo-chong-mu-om-con-lan-duong-di-tranh-tru-20261008221209549.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/o9FYARY8_HBiD1tMhCiheHoB1ew=/zoom/1200_630/2026/10/08/nhan-ai-hoan-canh-gia-dinh-chi-nguyen-thi-coi-lang-son-3-cropped-1791470382993.jpg","crawledAt":"2026-10-21T13:43:40.984Z"},{"id":"dtri-20261006131358137","title":"Những đứa trẻ lớn lên bằng cách đoán sắc mặt người lớn","slug":"nhung-dua-tre-lon-len-bang-cach-doan-sac-mat-nguoi-lon","excerpt":"Căng thẳng thời thơ ấu có thể khiến cơ thể duy trì trạng thái cảnh giác kéo dài, góp phần gây ra hoặc làm nặng thêm một số triệu chứng thể chất khi trưởng thành.","content":"(Dân trí) - Căng thẳng thời thơ ấu có thể khiến cơ thể duy trì trạng thái cảnh giác kéo dài, góp phần gây ra hoặc làm nặng thêm một số triệu chứng thể chất khi trưởng thành.\n\nTrong phòng tham vấn, một nữ bệnh nhân 24 tuổi nhớ lại những cơn đau quặn bụng dai dẳng, kèm cảm giác khó thở dồn dập mỗi khi nhận tin nhắn từ gia đình.\n\nTrước đó, cô đã nhiều lần đi khám nhưng các kết quả kiểm tra chưa lý giải được nguyên nhân của những triệu chứng này.\n\n“Mỗi lần nghe tiếng mẹ mở cửa, tôi lại thấy tim đập nhanh”\n\nTrao đổi với ThS Hoàng Quốc Lân, chuyên gia tâm lý, người bệnh cho biết từ nhỏ, cô đã thường xuyên cảm thấy bất an mỗi khi nghe tiếng mẹ gọi hoặc tiếng mở cửa.\n\nNhững âm thanh tưởng chừng bình thường này gắn với ký ức về những lần bị trách mắng, trừng phạt nghiêm khắc, khiến cô dần hình thành phản ứng lo sợ mỗi khi nghe thấy.\n\n“Mỗi lần nghe tiếng mẹ mở cửa, tôi lại thấy tim đập nhanh”, vị chuyên gia dẫn lại lời người bệnh trong quá trình tham vấn.\n\nTheo chuyên gia, khi một người sống trong trạng thái căng thẳng kéo dài, cơ thể có thể thường xuyên kích hoạt phản ứng căng thẳng. Điều này có thể ảnh hưởng đến nhịp tim, giấc ngủ, hoạt động tiêu hóa và cách cơ thể cảm nhận cơn đau.\n\nTheo thời gian, những âm thanh vốn bình thường như tiếng bước chân ngoài hành lang, tiếng mở cửa hay tiếng gọi tên cũng có thể trở thành tín hiệu khiến cơ thể lập tức cảnh giác.\n\nNếu trong quá khứ, những âm thanh ấy thường đi kèm với quát mắng, xung đột hoặc trừng phạt, não bộ có thể dần hình thành mối liên hệ giữa âm thanh và cảm giác nguy hiểm.\n\nVì vậy, khi nghe lại tín hiệu quen thuộc, cơ thể có thể phản ứng bằng tình trạng tim đập nhanh, căng cơ, run hoặc khó thở, dù ở thời điểm hiện tại chưa có chuyện gì xảy ra.\n\nẢnh hưởng đến sức khỏe tâm lý khi trưởng thành\n\nSống lâu trong môi trường thường xuyên bị chỉ trích, trừng phạt hoặc chứng kiến xung đột có thể khiến trẻ hình thành thói quen liên tục quan sát nét mặt, giọng nói và thái độ của người lớn để đoán xem điều gì sắp xảy ra.\n\n“Khi còn nhỏ, sự nhạy cảm ấy có thể giúp trẻ hạn chế những tình huống khiến mình bị quát mắng hoặc trừng phạt. Tuy nhiên, khi trưởng thành, phản ứng từng giúp trẻ thích nghi có thể tiếp tục xuất hiện ngay cả trong những mối quan hệ an toàn”, vị chuyên gia phân tích.\n\nKhi đó, người trong cuộc có thể trở nên quá nhạy cảm với thái độ của người khác, luôn sợ mắc lỗi, khó thư giãn và thường xuyên tự nhận trách nhiệm về mình. Một số người gặp khó khăn khi nói lời từ chối, dễ cảm thấy có lỗi và liên tục cố gắng làm hài lòng những người xung quanh.\n\nNếu kéo dài, điều này có thể ảnh hưởng đến cách họ nhìn nhận giá trị của bản thân. Họ dễ nghi ngờ quyết định của chính mình, chịu đựng trong các mối quan hệ hoặc cảm thấy bất an mỗi khi muốn đặt nhu cầu cá nhân lên trước.\n\nKhông chỉ tác động đến cảm xúc và hành vi, trạng thái cảnh giác kéo dài còn có thể ảnh hưởng đến giấc ngủ, khả năng tập trung và khả năng điều hòa cảm xúc. Những phản ứng này có thể xuất hiện từ thời thơ ấu và tiếp tục ảnh hưởng đến sức khỏe tâm lý khi trưởng thành, khiến một số người dễ lo âu, cáu gắt, mệt mỏi hoặc ngày càng thu mình.\n\nMức độ ảnh hưởng ở mỗi người không giống nhau, phụ thuộc vào thời gian và mức độ căng thẳng, độ tuổi, môi trường sống cũng như sự hỗ trợ mà trẻ nhận được trong quá trình lớn lên.\n\nTheo ThS Lân, điều quan trọng là nhận ra mối liên hệ có thể có giữa những phản ứng hiện tại với trải nghiệm trong quá khứ, thay vì xem đó là một nét tính cách cố định.\n\nKhi tình trạng lo âu, mất ngủ, kiệt sức, các triệu chứng thể chất hoặc khó khăn trong quan hệ kéo dài và làm giảm chất lượng cuộc sống, người trong cuộc nên cân nhắc tìm kiếm sự hỗ trợ chuyên môn.\n\nViệc đánh giá sức khỏe thể chất kết hợp với tâm lý, tùy theo tình trạng cụ thể, có thể giúp làm rõ những yếu tố liên quan đến triệu chứng. Từ đó, người bệnh có thể học cách nhận diện phản ứng căng thẳng, điều chỉnh cảm xúc và xây dựng ranh giới phù hợp hơn trong các mối quan hệ.","author":"Hải Yến","category":"Sức khỏe","publishedAt":"2026-10-06 13:13","source":"dantri.com.vn","url":"https://dantri.com.vn/suc-khoe/nhung-dua-tre-lon-len-bang-cach-doan-sac-mat-nguoi-lon-20261006131358137.htm","categories":["Sức khỏe"],"categoryIds":["suc-khoe"],"thumbnail":"https://cdnphoto.dantri.com.vn/Sm4NK27OHQEk6XkX7OCBcPJPaSI=/zoom/1200_630/2026/10/06/so-me-cropped-1791266953178.jpg","crawledAt":"2026-10-21T13:42:40.042Z"},{"id":"dtri-20261005004844727","title":"Mẹ 70 tuổi nhặt ve chai gom từng đồng nuôi con trai tâm thần, suy thận","slug":"me-70-tuoi-nhat-ve-chai-gom-tung-dong-nuoi-con-trai-tam-than-suy-than","excerpt":"Mẹ 70 tuổi nhặt ve chai gom từng đồng nuôi con trai tâm thần, suy thận","content":"Mã số: 6125\n\n(Dân trí) - Vừa chăm con trai bị tâm thần phân liệt, suy thận giai đoạn cuối, bà Lanh vừa tranh thủ đi nhặt ve chai. Tuổi cao, sức yếu, người mẹ góa nghèo khó không biết mình có thể gắng gượng được đến khi nào.\n\nTrong phòng bệnh ngột ngạt, người mẹ gần 70 tuổi kiên nhẫn vỗ về, xoa nhẹ những nốt sẩn ngứa trên người con trai mắc bệnh tâm thần đang chạy thận. Hình ảnh ấy đã trở nên quen thuộc với các y, bác sĩ ở Đơn vị Thận nhân tạo, Trung tâm Y tế Hải Dương.\n\nCó nhà nhưng không thể ở, 2 mẹ con phải tá túc bệnh viện\n\nSau khi kết hôn, bà Vũ Thị Lanh (SN 1957, trú tại tổ dân phố Chung Chính, phường Lê Đại Hành, TP Hải Phòng) mới biết chồng mắc bệnh tâm thần phân liệt. Gạt nước mắt, bà Lanh nhẫn nại gánh vác gia đình. Dù chăm chỉ làm lụng, cuộc sống vẫn rất khó khăn, gia đình luôn trong danh sách hộ nghèo của địa phương.\n\nVợ chồng bà Lanh sinh được 2 con. Người con gái đi lấy chồng xa, hoàn cảnh cũng khó khăn, thỉnh thoảng mới về thăm gia đình. Người con trai Trần Đình Hùng (SN 1987) phát bệnh tâm thần phân liệt khi tròn 18 tuổi.\n\nNăm 2007, chồng bà Lanh qua đời vì căn bệnh ung thư dạ dày. Cách đây 5 năm, anh Hùng lại phát hiện mắc suy thận giai đoạn cuối.\n\nMỗi tuần 3 lần, bà Lanh phải đưa con trai di chuyển hơn 20km từ nhà đến Trung tâm Y tế Hải Dương để lọc máu chu kỳ. Chi phí đi lại tốn kém khiến cuộc sống của 2 mẹ con càng thêm chật vật.\n\nCảm thông với hoàn cảnh khó khăn của bệnh nhân, các bác sĩ đã tạo điều kiện cho mẹ con bà Lanh mượn tạm 1 căn phòng trống tại Trung tâm Y tế để tá túc. Từ đó, anh Hùng thuận tiện hơn trong việc điều trị, còn bà Lanh cũng không phải lo khoản chi phí đi lại.\n\nNhững hôm con trai tỉnh táo và không phải chạy thận, bà Lanh lại tranh thủ đi nhặt ve chai bán lấy chút tiền trang trải cuộc sống.\n\nHiện tại, bên cạnh thu nhập ít ỏi từ công việc nhặt phế liệu, 2 mẹ con bà Lanh chủ yếu trông vào các khoản trợ cấp xã hội. Anh Hùng là người khuyết tật đặc biệt nặng, được trợ cấp 1,4 triệu đồng/tháng; bà Lanh là người chăm sóc, được nhận 700.000 đồng/tháng.\n\nTheo bà Lanh, căn nhà cấp 4 lợp mái fibro xi măng ở quê đã quá xuống cấp, nhưng giờ tiền chữa bệnh cho con cũng không lo nổi, bà không dám nghĩ đến chuyện sửa sang.\n\n\"Đợt trước có việc, 2 mẹ con về qua nhà, nhưng nhà dột nát, không ở được nên lại phải lên viện luôn. Giờ tiền chữa bệnh cho con tôi còn không lo nổi, nói gì đến sửa sang nhà cửa”, bà Lanh ngậm ngùi chia sẻ.\n\nBiết mẹ con bà Lanh khó khăn, chủ quán cơm gần Trung tâm Y tế Hải Dương thường giảm một nửa tiền ăn mỗi khi 2 mẹ con bà ghé quán. Những vỏ chai nhựa, bìa các tông không dùng đến, chủ quán cũng cho bà Lanh.\n\nBác sĩ mong bạn đọc chung tay giúp đỡ mẹ con bà Lanh\n\nBS CKI Nguyễn Thị Lan Phương, Trưởng Đơn vị Thận nhân tạo, Trung tâm Y tế Hải Dương, cho biết: “Việc phải sử dụng thuốc điều trị tâm thần liên tục trong nhiều năm đã ảnh hưởng nghiêm trọng đến chức năng gan. Hiện tại, ngoài suy thận mạn giai đoạn cuối, anh Hùng còn mắc viêm gan C, xơ gan cổ trướng, cao huyết áp và thiếu máu nặng.\n\nThời gian trước, các bác sĩ đã làm thủ tục chuyển tuyến cho bệnh nhân ra Bệnh viện Nhiệt đới Trung ương (Hà Nội) điều trị. Tuy nhiên, ngoài khoản Bảo hiểm y tế chi trả, mỗi tháng gia đình phải thanh toán thêm 5-6 triệu đồng tiền thuốc ngoài danh mục. Không lo được chi phí, gia đình bệnh nhân lại xin quay về Trung tâm Y tế Hải Dương”.\n\nBác sĩ Phương rất mong thông qua báo Dân trí, bạn đọc và các nhà hảo tâm chung tay hỗ trợ, để anh Hùng có điều kiện được chăm sóc y tế tốt hơn, bà Lanh có thể vơi đi phần nào gánh nặng về kinh tế.\n\nXác nhận với phóng viên Dân trí, bà Nguyễn Thị Thắm, Tổ trưởng Tổ dân phố Chung Chính, cho biết, gia đình bà Lanh là hộ nghèo, có hoàn cảnh đặc biệt khó khăn tại địa phương, rất cần sự chung tay giúp đỡ của cộng đồng.\n\nHơn lúc nào hết, 2 mẹ con bà Lanh đang rất cần những vòng tay nhân ái sẻ chia, để người mẹ góa nghèo có thêm sức mạnh, tiếp tục đồng hành cùng con trai trong quá trình điều trị.","author":"Huyền Nguyễn","category":"Nhân ái","publishedAt":"2026-10-05 00:48","source":"dantri.com.vn","url":"https://dantri.com.vn/tam-long-nhan-ai/me-70-tuoi-nhat-ve-chai-gom-tung-dong-nuoi-con-trai-tam-than-suy-than-20261005004844727.htm","categories":["Nhân ái"],"categoryIds":["tam-long-nhan-ai"],"thumbnail":"https://cdnphoto.dantri.com.vn/zTuuJmvbcZwvv0qUiLW8nHK2m_c=/zoom/1200_630/2026/10/04/nhan-ai-hoan-canh-tran-dinh-hung-hp-2-cropped-1791131280042.jpg","crawledAt":"2026-10-21T13:43:39.928Z"},{"id":"dtri-20260219112002920","title":"Lò mì quảng ở Đà Nẵng 25 năm chỉ tráng bằng trấu, hút khách quốc tế","slug":"lo-mi-quang-o-da-nang-25-nam-chi-trang-bang-trau-hut-khach-quoc-te","excerpt":"Trong 25 năm qua, bà Võ Thị An ở Đà Nẵng chỉ dùng trấu để tráng mì quảng, chính cách chế biến mộc mạc, dân dã này đã thu hút đông đảo du khách quốc tế tìm đến mỗi ngày.","content":"(Dân trí) - Trong 25 năm qua, bà Võ Thị An ở Đà Nẵng chỉ dùng trấu để tráng mì quảng, chính cách chế biến mộc mạc, dân dã này đã thu hút đông đảo du khách quốc tế tìm đến mỗi ngày.\n\nTrong con hẻm nhỏ chỉ hơn 2m tại thôn Hà Mỹ (xã Duy Nghĩa, thành phố Đà Nẵng), lò mì Quảng của gia đình bà Võ Thị An (64 tuổi) đã trở thành điểm địa chỉ hấp dẫn, thu hút hàng trăm du khách quốc tế mỗi ngày đến trải nghiệm và khám phá văn hóa ẩm thực địa phương.\n\nMặc dù không gian bếp chật hẹp, chỉ đủ chứa khoảng 20 người, nhưng mỗi ngày, lò mì của bà An đón tiếp 5-7 đoàn du khách, chủ yếu đến từ Mỹ và các nước châu Âu như Pháp, Tây Ban Nha, Đức. Họ tìm đến đây để tìm hiểu văn hóa, phong tục tập quán và hòa mình vào cuộc sống thường nhật của người dân địa phương.\n\nDu khách tỏ ra ngạc nhiên và thích thú khi chứng kiến quy trình làm mì Quảng nổi tiếng, từ khâu xay bột, pha bột đến tráng mì, tất cả đều được thực hiện thủ công từ hạt gạo.\n\nBà An cho biết du khách đặc biệt ấn tượng với việc sử dụng vỏ trấu làm nguyên liệu đốt lò, tạo ra nhiệt lượng đủ để làm nóng lò mì. Sau đó, tàn tro của trấu lại được dùng làm phân bón hữu cơ, tạo nên một vòng tuần hoàn khép kín, bền vững, khiến du khách vô cùng thích thú.\n\nLò mì Quảng của bà An đã hoạt động được 25 năm và chính thức đón khách quốc tế hơn 10 năm nay. Trước đây, bà An từng làm nhiều nghề khác nhau nhưng cuộc sống vẫn khó khăn. Năm 40 tuổi, bà cùng chồng chuyển sang nghề tráng mì và gắn bó cho đến tận bây giờ.\n\n“Tôi vừa tráng mì bán cho các hàng quán địa phương, vừa phục vụ du khách trải nghiệm. Mùa đông là thời điểm đón khách nhiều nhất, ngày nào cũng đón trên dưới 70 người, cao điểm có cả trăm khách”, bà An cho biết.\n\nDu khách được tự tay đổ bánh, tráng bánh và vớt bánh, mỗi công đoạn đều mang lại sự hào hứng đặc biệt.\n\nÔng Oliver, một du khách Mỹ, chia sẻ: “Được tìm hiểu các công đoạn và tự mình làm nên món mì đặc biệt này khiến tôi rất phấn khởi. Chúng tôi còn được trải nghiệm nhiều nghề truyền thống như dệt chiếu, nấu rượu… cùng người dân địa phương”.\n\nTừ một nghề nuôi sống gia đình, bà An giờ đây đã tìm thấy niềm vui trong việc phục vụ du khách mỗi ngày, cuộc sống của bà cũng được cải thiện đáng kể. Bà An dự định sẽ mở rộng không gian lò mì để phục vụ được nhiều du khách hơn trong tương lai.\n\nNăm 2019, mô hình \"Phát triển nghề tráng mì truyền thống gia đình gắn với du lịch trải nghiệm\" của bà An đã đoạt giải Ba cuộc thi Ý tưởng sáng tạo khởi nghiệp do Hội Liên hiệp phụ nữ huyện Duy Xuyên, tỉnh Quảng Nam (cũ) tổ chức, khẳng định giá trị và tiềm năng của mô hình này.","author":"Công Bính","category":"Tết 2026","publishedAt":"2026-02-19 11:20","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/lo-mi-quang-o-da-nang-25-nam-chi-trang-bang-trau-hut-khach-quoc-te-20260219112002920.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/vq1trQQ2plpT8l2myA0WDwHDPdg=/zoom/1200_630/2026/02/19/3-cropped-1771474710876.jpg","crawledAt":"2026-10-21T13:43:15.458Z"},{"id":"dtri-20260218125735669","title":"Thiết Đại triều và nghi lễ Tết trong hoàng cung Huế xưa","slug":"thiet-dai-trieu-va-nghi-le-tet-trong-hoang-cung-hue-xua","excerpt":"Tết hoàng cung Huế xưa là sự kiện quan trọng, với các nghi lễ được tổ chức theo những quy chuẩn nghiêm ngặt, phản ánh nếp sống và tư tưởng của triều Nguyễn.","content":"Lễ thiết Đại triều trong ngày Tết\n\nTriều Nguyễn (1802-1945), trong suốt 143 năm tồn tại đã để lại cho Huế nói riêng, cả nước nói chung một hệ thống di sản đồ sộ. Bên cạnh đó, những nét văn hóa cung đình đặc sắc vẫn còn ảnh hưởng cho tới ngày nay, nhất là các nghi lễ dịp Tết cổ truyền.\n\nTheo Trung tâm Bảo tồn Di tích Cố đô Huế, Tết Nguyên đán là một dịp rất quan trọng của triều Nguyễn. Từ những ngày cuối tháng Chạp, hoàng cung đã rộn ràng không khí chuẩn bị đón xuân. Các quan ở Phủ Nội vụ tất bật quét dọn, trang hoàng, lau chùi đồ thờ tự, sắp đặt lại không gian các cung điện. Cây nêu được dựng lên theo nghi thức long trọng, mang ý nghĩa xua đuổi tà ma, cầu mong một năm mới an lành.\n\nTrong hoàng cung, mọi vật dụng dùng cho Tết đều được chuẩn bị kỹ lưỡng. Những món ăn cung đình được chế biến công phu, không chỉ để dâng cúng tổ tiên mà còn thể hiện sự tinh tế của ẩm thực hoàng gia.\n\nVới triều đình nhà Nguyễn, Tết không chỉ là dịp vui chơi mà còn mang ý nghĩa chính trị, tinh thần sâu sắc. Qua các nghi lễ, hoạt động vui Xuân, nhà vua củng cố đạo lý quân thần, cầu mong quốc thái dân an. Những sinh hoạt ấy góp phần tạo nên bản sắc văn hóa cung đình đặc trưng của kinh đô Huế.\n\nTheo nghi thức truyền thống, nhà Nguyễn thường tổ chức thiết Đại triều tại điện Thái Hòa và thiết Thường triều tại điện Cần Chánh.\n\nTư liệu lịch sử ghi lại, khi thiết Đại triều, nhà vua ngự giá từ điện Cần Chánh, qua Đại Cung Môn và lên điện Thái Hòa để đích thân điều hành buổi lễ. Các quan văn võ triều Nguyễn tham gia buổi lễ xếp hàng theo thứ tự phẩm cấp, trong đó quan đứng đầu các Bộ giữ vị trí hàng đầu.\n\nTrong buổi lễ, các quan dâng biểu chúc mừng nhà vua nhân dịp Tết Nguyên đán. Tiếp đó, triều đình tuyên đọc chỉ dụ ban ân của nhà vua với các nghi thức trang nghiêm, gắn liền với những tiết mục đại nhạc, tiểu nhạc. Sau phần thiết Đại triều, vua rời điện Thái Hòa trở về điện Cần Chánh để tiếp tục các nghi thức Tết cổ truyền khác.\n\nTại điện Cần Chánh, các hoàng đệ, hoàng tử nhỏ tuổi cùng những thân công, hoàng tử làm lễ bái mừng vua. Sau đó là nghi thức tuyên chỉ ban yến tiệc, thưởng xuân. Các yến tiệc được tổ chức tại điện Cần Chánh, các công trình phụ cận như Tả Vu, Hữu Vu, Tả Đãi Lâu Viện và Hữu Đãi Lâu Viện.\n\nTừ năm 2021, hoạt động ý nghĩa nêu trên đã được Trung tâm Bảo tồn Di tích Cố đô Huế tái hiện dưới hình thức sân khấu hóa, giúp công chúng, du khách có dịp tìm hiểu sâu hơn về nghi thức triều đình nhà Nguyễn, đồng thời cảm nhận không khí Tết cổ truyền trong không gian di sản.\n\nVua ban “lửa tình” trong ngày Tết cổ truyền\n\nTheo nhà nghiên cứu Nguyễn Xuân Hoa, nguyên Giám đốc Sở Văn hóa và Thông tin (cũ), vào thời Nguyễn, Tết trong Hoàng cung Huế được tổ chức rất long trọng với nhiều nghi lễ quan trọng.\n\nCác nghi thức Tết kéo dài từ tháng Chạp tới giữa tháng Giêng với nhiều lễ lớn như lễ phát lịch, nghinh xuân (đón ngày lập xuân), phất thức (lau chùi kim ấn và kinh sách), cáp hưởng (mời các vị tiên về ăn Tết), dựng cây nêu, thiết Đại triều, lễ tịch điền,…\n\nCác cuộc tế, viếng lăng miếu, du xuân của hoàng gia cũng được tổ chức cho đến ngày mùng 7 tháng Giêng.\n\nMột nghi lễ khác được triều đình Huế tổ chức trong dịp đầu xuân là lễ tế đạo kỳ, diễn ra vào ngày mùng 7 Tết ở vùng đất quan phòng (phía Nam sông Hương) do một vị võ tướng đại diện thực hiện.\n\nKhông chỉ các nghi lễ, việc chiêu đãi yến tiệc, vui chơi ngày Xuân của vua, quan triều Nguyễn cũng rất đa dạng, đặc sắc. Nhà vua không ăn yến tiệc cùng hoàng thân hay các quan mà sẽ ăn một mình. Đến thời vua Bảo Đại có đổi khác là vua sẽ ăn cùng mâm với vợ con.\n\nTheo cuốn Lễ Tết ăn chơi trong cung Nguyễn của nhà nghiên cứu Nguyễn Đắc Xuân, vào ngày Tết, nhiều trò chơi quý phái được tổ chức trước sân và trong nhà để tránh thời tiết mưa lạnh những ngày đầu xuân ở Huế để phục vụ vua, quan. Một số trò chơi tiêu biểu thường được tổ chức trong hoàng cung xưa dịp Tết như đầu hố (ném thẻ vào cái đầu hẹp của một quả bầu), họa ngự thi, đánh thơ,…\n\nCác vua Nguyễn đều rất thích thơ văn, đặc biệt là hoàng đế Tự Đức. Hằng năm, nhà vua thường chọn 4 quan văn để họa thơ. Đến gần giao thừa, các vị quan được chọn phải đứng trước nhà mình bên cạnh hương án, lính hầu, đợi nhận thơ của vua để họa.\n\nNhà vua ngồi chờ 4 bài phụng họa bên lò hương trầm. Khi nhận đủ, vua duyệt lại rồi giao cho một cận thần đọc trước văn võ bá quan vào ngày đầu năm mới và thưởng cho bài họa hay nhất.\n\nCũng theo nhà nghiên cứu, vào ngày Tết, các bà vợ vua ở trong tam cung lục viện và các bà có chức sắc sẽ mặc lễ phục đứng hai bên Đường lang làm hàng rào danh dự từ điện Càn Thành đến điện Cần Chánh để chào vua đi qua. Không có bà vợ hay người con nào được ngồi ăn Tết với vua. Vì thế, có nhiều bà mang tiếng vợ vua mà quanh năm không được thấy mặt chồng.\n\nĐể tạo cơ hội cho tất cả các bà phi, tần, mỹ nữ được nhìn thấy mặt vua trong những ngày chuẩn bị đón Xuân, triều đình nhà Nguyễn đã nghĩ ra một cách gặp mặt rất độc đáo. Đến ngày đông chí hàng năm, tất cả các bếp lửa trong Tử Cấm thành đều phải tắt hết, chỉ đốt một lò lửa thật lớn tại điện Càn Thành.\n\nĐúng vào lúc nửa đêm, các bà trong tam cung lục viện được phép mang lồng ấp đến điện để nhận lửa, ngụ ý vua ban hơi ấm cho mọi người. Chút “lửa tình” này được các bà giữ quanh năm.\n\nTheo quan niệm xưa, vua là con ông trời (thiên tử), nắm trong tay mọi quyền điều hành. Ngày Tết với bậc thiên tử không chỉ là thời gian nghỉ việc triều chính để chơi mà còn kiểm kê của báu, chuẩn bị cho công việc của năm sau, tưởng nhớ tổ tiên, khuyến khích người dân siêng năng sản xuất.","author":"Cao Tiến","category":"Tết 2026","publishedAt":"2026-02-18 12:57","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/thiet-dai-trieu-va-nghi-le-tet-trong-hoang-cung-hue-xua-20260218125735669.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/ZNz3iIM-bcpvC4JisQ6e3URKQpg=/zoom/1200_630/2026/02/18/thiet-dai-trieu-trong-hoang-cung-hue-xua1-cropped-1771392680887.jpg","crawledAt":"2026-10-21T13:43:15.420Z"},{"id":"dtri-20260214140345062","title":"Thức uống độc lạ từ vỏ cây, người Pa Kô dùng đãi khách dịp Tết","slug":"thuc-uong-doc-la-tu-vo-cay-nguoi-pa-ko-dung-dai-khach-dip-tet","excerpt":"Rượu AVeat là thức uống truyền thống lâu đời của người Pa Kô ở Quảng Trị, được nấu từ vỏ cây rừng kết hợp với chuối hoặc mật mía, ủ tự nhiên tạo nên màu nâu đỏ đặc trưng.","content":"(Dân trí) - Rượu AVeat là thức uống truyền thống lâu đời của người Pa Kô ở Quảng Trị, được nấu từ vỏ cây rừng kết hợp với chuối hoặc mật mía, ủ tự nhiên tạo nên màu nâu đỏ đặc trưng.\n\nBí quyết từ vỏ cây kreaihs\n\nMỗi độ Xuân về, khi núi rừng thay áo mới, bản làng người Pa Kô ở xã Tà Rụt, tỉnh Quảng Trị lại rộn ràng tiếng nói cười, chuẩn bị cho những ngày Tết cổ truyền.\n\nTrong căn bếp ấm cúng của gia đình ông Hồ Văn Phinh (55 tuổi, trú tại thôn Tà Rụt 3, xã Tà Rụt), nồi nước nấu từ vỏ cây và chuối đang sôi lăn tăn, tỏa ra mùi thơm đặc trưng. Bà Hồ Thị Buổi (50 tuổi), vợ ông Phinh nhẹ nhàng đảo nguyên liệu, thỉnh thoảng thêm nước, tạo nên thứ rượu Aveat truyền thống của đồng bào Pa Kô.\n\nNguyên liệu chính để tạo nên rượu AVeat là vỏ cây kreaihs, một loại cây thân to, hoang dã mọc sâu trong rừng. Ông Phinh cho biết từ tháng 5/2025, ông đã vào rừng lấy vỏ cây kreaihs về treo trên gác bếp, đợi đến Tết mới đem ra nấu rượu. Thời điểm tốt nhất để lấy vỏ là vào mùa hè, khi cây tập trung dinh dưỡng vào vỏ, giúp rượu AVeat thơm ngon hơn.\n\n“Bà con chúng tôi đi rừng chỉ lấy mỗi cây một ít vỏ để cây không bị chết. Trước đây cây kreaihs nhiều, nhưng ngày một hiếm, tôi phải đi cả ngày, vào sâu trong rừng mới lấy được”, ông Phinh chia sẻ về sự kỳ công trong việc tìm kiếm nguyên liệu.\n\nVới hơn 30 năm kinh nghiệm, bà Hồ Thị Buổi tiết lộ bí quyết vỏ cây sau khi rửa sạch được cho vào nồi cùng một ít chuối mật mốc chín, đổ nước và đun nhiều giờ trên bếp củi. Khi nước chuyển sang màu cánh gián là đạt yêu cầu.\n\n\"Vỏ kreaihs nấu càng lâu chất gây say tiết ra càng nhiều, rượu AVeat càng thơm, đủ vị. Hỗn hợp vỏ cây và chuối sau khi nấu, để nguội được cho vào chum hoặc bình thủy tinh đậy kín, ủ khoảng một tuần để lên men thành rượu Aveat có màu nâu đỏ đặc trưng”, bà Buổi giải thích.\n\nHương vị của rừng, của tình người Pa Kô\n\nTrong những ngày Tết, dưới mái nhà sàn của đồng bào Pa Kô, tiếng cười nói rộn ràng, hòa cùng tiếng khèn, chiêng. Cỗ Tết tuy không cầu kỳ nhưng luôn có cơm nếp, thịt nướng, rau rừng, đặc biệt là rượu AVeat để mời khách. Với nồng độ thấp, hương thơm dịu nhẹ, AVeat phù hợp cho cả nam và nữ.\n\nAnh Hồ Văn Chinh (39 tuổi, trú tại thôn Tà Rụt 3) cho biết cuộc sống vùng cao còn nhiều vất vả, nhưng bà con vẫn cố gắng dành dụm để có một cái Tết đủ đầy. Khi có khách đến chúc năm mới, chủ nhà sẽ rót rượu AVeat mời trước như lời chào thân tình, tạo sự gắn kết. Rượu có vị chát nhẹ, đắng thoảng qua rồi ngọt dần nơi cổ họng, không nồng gắt.\n\nDù việc tìm kiếm cây kreaihs ngày càng khó khăn, người Pa Kô vẫn duy trì tục nấu AVeat mỗi dịp Xuân về. Đây không chỉ là một thức uống mà còn là cách giữ gìn phong tục, nhắc nhở con cháu nhớ về nguồn cội.\n\n“Những chén rượu AVeat được rót ra trong ngày Tết không phải để uống say mà để chúc nhau sức khỏe, mùa rẫy tốt tươi, gia đình yên ấm”, anh Chinh tâm sự.\n\nNghệ nhân ưu tú Kray Sức, người am hiểu văn hóa Pa Kô, giải thích AVeat là tên gọi chỉ hoạt động vắt nước theo cách hiểu của đồng bào. Vỏ cây kreaihs có vị chát, đắng, chứa chất gây say. Thức uống này được đồng bào Pa Kô đánh giá là tốt cho đường ruột, có giá trị bồi bổ sức khỏe.\n\n“Xưa kia, khi chưa biết nấu và ủ thành rượu, người Pa Kô chỉ lột vỏ cây kreaihs, rửa sạch, phơi khô để sẵn trong nhà. Khi có khách sẽ đem ra nấu với nước mía để thiết đãi, thể hiện sự trân trọng, hiếu khách”, ông Kray Sức kể lại.\n\nÔng Hồ Văn Bước, Chủ tịch Ủy ban Mặt trận Tổ quốc Việt Nam xã Tà Rụt, khẳng định rượu AVeat từ lâu đã trở thành thức uống quen thuộc của đồng bào Pa Kô trong các dịp lễ, Tết, thể hiện sự chân tình, hiếu khách của người vùng cao.\n\nÔng Bước cũng nhấn mạnh, cùng với việc gìn giữ nét văn hóa truyền thống, địa phương thường xuyên tuyên truyền bà con sử dụng rượu một cách chừng mực, không uống say, để AVeat luôn là nét đẹp trong sinh hoạt cộng đồng, không làm ảnh hưởng đến sức khỏe và đời sống.","author":"Nhật Anh","category":"Tết 2026","publishedAt":"2026-02-14 14:03","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/thuc-uong-doc-la-tu-vo-cay-nguoi-pa-ko-dung-dai-khach-dip-tet-20260214140345062.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/yoA-V7kAEsUVOUUHKz9ScNrZsHU=/zoom/1200_630/2026/02/14/loai-ruou-nau-tu-vo-caynhat-anh-4-cropped-1771051574434.jpg?watermark=true","crawledAt":"2026-10-21T13:43:16.532Z"},{"id":"dtri-20260212121727498","title":"Biến tấu bánh dân dã với nhiều hình thù ngộ nghĩnh, “cháy” hàng dịp Tết","slug":"bien-tau-banh-dan-da-voi-nhieu-hinh-thu-ngo-nghinh-chay-hang-dip-tet","excerpt":"Để thu hút khách hàng, một lò bánh thuẫn tại Đà Nẵng đã biến tấu loại bánh quen thuộc này thành nhiều hình thù ngộ nghĩnh như mặt cười, cún con… sản xuất ngày nào bán sạch ngày đó.","content":"(Dân trí) - Để thu hút khách hàng, một lò bánh thuẫn tại Đà Nẵng đã biến tấu loại bánh quen thuộc này thành nhiều hình thù ngộ nghĩnh như mặt cười, cún con… sản xuất ngày nào bán sạch ngày đó.\n\nNhững ngày cận Tết Bính Ngọ, các lò bánh thuẫn tại Đà Nẵng đang tất bật đỏ lửa, sản xuất loại bánh truyền thống đặc trưng của người dân miền Trung để phục vụ thị trường.\n\nTrong bối cảnh cạnh tranh ngày càng gay gắt, vợ chồng ông Nguyễn Quang Ban (40 tuổi, thôn Quý Thạnh, xã Thăng Bình) đã mạnh dạn \"thay áo mới\" cho món bánh dân dã này.\n\nHơn 3 năm nay, cơ sở của ông Ban đã biến tấu bánh thuẫn với nhiều hình thù ngộ nghĩnh như ngôi sao, mặt cười, vỏ sò, cún con… nhằm thu hút và mở rộng tệp khách hàng.\n\nÔng Ban cho biết trước đây, cơ sở của ông cũng sản xuất bánh thuẫn theo khuôn đúc truyền thống, nhưng lượng khách hàng ngày càng giảm. Ý tưởng thay đổi cách sản xuất nảy sinh khi ông tình cờ thấy những khuôn nướng bánh với nhiều hình thù bắt mắt trên mạng xã hội.\n\n“Nướng bằng bếp điện khó hơn bếp than, công thức bánh cũng phải gia giảm cho phù hợp. Chúng tôi phải thử đi thử lại, đổ bỏ nhiều mẻ bánh mới ra vị ưng ý”, ông Ban kể lại quá trình thử nghiệm đầy gian nan.\n\nNguyên liệu làm bánh bao gồm bột mì, bột bình tinh, trứng gà thả vườn, nước cốt gừng, nước cam hoặc các loại nước ép trái cây khác tùy theo yêu cầu của khách hàng. Công đoạn làm bánh khá cầu kỳ và tốn thời gian, đặc biệt là khâu đánh bột - được xem là bước quan trọng nhất để đảm bảo chất lượng bánh.\n\nQuy trình bắt đầu bằng việc đánh trứng gà, sau đó cho đường vào khuấy đều. Tiếp tục cho bột, gừng, nước ép vào hỗn hợp, công đoạn đánh bột này mất hơn 20 phút.\n\nTrước khi đổ bột vào khuôn, một lớp bơ được quét lên, sau đó nướng khoảng 3 phút sẽ cho ra bánh thành phẩm. Bánh khi chín có hình dáng rất bắt mắt, xốp, và tỏa mùi thơm thoang thoảng của gừng, cam…\n\nSản phẩm bánh bông lan ngộ nghĩnh của cơ sở ông Ban đang rất hút khách dịp Tết, với lượng sản xuất ngày nào bán hết ngày đó. Thị trường tiêu thụ chủ yếu ở các địa phương thuộc thành phố Đà Nẵng và được trưng bày tại các hội chợ, hội hoa xuân.\n\n“Ngoài cung cấp ra thị trường, chúng tôi còn dùng thưởng thức trong gia đình nên không dùng chất bảo quản, hay các chất phụ gia khác”, ông Ban khẳng định về chất lượng sản phẩm.\n\nTheo ông Ban, cận Tết, mỗi ngày cơ sở cho ra thị trường 50-70kg bánh thành phẩm, bán với giá khoảng 150.000 đồng/kg. Dù sản xuất quanh năm, nhưng từ khoảng mùng 10 tháng Chạp (âm lịch), lượng sản xuất sẽ tăng cường để phục vụ nhu cầu thị trường Tết.\n\nVợ chồng ông Ban thường nhận đặt hàng online và sản xuất theo yêu cầu của khách. Những ngày cận Tết Bính Ngọ, đơn đặt hàng về liên tục, khiến cơ sở làm việc không kịp thở.\n\nVới sự sáng tạo và khéo léo, từ món bánh truyền thống, bánh thuẫn đã được biến tấu với nhiều hình dáng ngộ nghĩnh nhưng vẫn giữ được hương vị đặc trưng. Nhờ đó, món bánh dân dã này đang dần khẳng định được chỗ đứng trên thị trường.","author":"Công Bính","category":"Tết 2026","publishedAt":"2026-02-12 12:17","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/bien-tau-banh-dan-da-voi-nhieu-hinh-thu-ngo-nghinh-chay-hang-dip-tet-20260212121727498.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/-mOAtByWEyorKXUd5fWVu0ZHXCs=/zoom/1200_630/2026/02/12/2-cropped-1770873370175.jpg","crawledAt":"2026-10-21T13:43:16.573Z"},{"id":"dtri-20260207155907826","title":"Nghề lãi ít nhưng vẫn đỏ lửa ngày đêm phục vụ thị trường Tết","slug":"nghe-lai-it-nhung-van-do-lua-ngay-dem-phuc-vu-thi-truong-tet","excerpt":"Bánh tổ là món không thể thiếu trong mâm lễ cúng tiễn ông Công, ông Táo chầu trời hàng năm của người dân Đà Nẵng mỗi dịp 23 tháng Chạp.","content":"(Dân trí) - Bánh tổ là món không thể thiếu trong mâm lễ cúng tiễn ông Công, ông Táo chầu trời hàng năm của người dân Đà Nẵng mỗi dịp 23 tháng Chạp.\n\nTừ ngày 18 tháng Chạp, không khí tại cơ sở sản xuất bánh tổ truyền thống của gia đình bà Lê Thị Lệ Huyền (57 tuổi, xã Đại Lộc, Đà Nẵng) đã trở nên nhộn nhịp, bếp lò đỏ lửa liên tục để kịp phục vụ nhu cầu tăng cao của thị trường Tết Nguyên đán.\n\nBánh tổ, món bánh mang đậm ý nghĩa cội nguồn \"chim có tổ, người có tông\" trong văn hóa miền Trung, đang được gia đình bà Huyền - một trong số ít những hộ còn lưu giữ nghề truyền thống này tại Đà Nẵng - miệt mài sản xuất.\n\nGắn bó với nghề làm bánh tổ qua ba thế hệ, bà Huyền cho biết dù trải qua nhiều khó khăn trong hơn 20 năm làm nghề, bà vẫn kiên trì giữ lửa bếp, góp phần gìn giữ nét văn hóa ẩm thực đặc trưng của ngày Tết đoàn viên.\n\n“Cơ sở hoạt động thường xuyên, nhưng đến dịp cận Tết nhu cầu thị trường tăng gấp 10 lần. Các đơn hàng đặc biệt tăng cao từ ngày 18 âm lịch đến tận chiều 29 Tết, bận rộn nhưng phấn khởi lắm”, bà Huyền nói.\n\nNguyên liệu làm bánh tổ khá đơn giản, gồm nếp, đường, gừng và mè. Nếp được xay nhuyễn với nước thành bột, sau đó trộn đều với đường đã \"sên\" vừa tới. Hỗn hợp này được đổ vào khuôn hình tròn lót hai lớp lá chuối, tạo hình dáng như một \"tổ chim\", rồi hấp trên lửa lớn khoảng 5 tiếng.\n\nBà Huyền giải thích, lá chuối tươi khi hấp sẽ chuyển sang màu xanh đen, tạo hương thơm nhẹ nhàng cho bánh. Việc giữ lửa to và đều trong suốt quá trình hấp là bí quyết để bánh chín tới, không bị sượng.\n\nSau khi ra lò, bánh tổ được rắc một lớp mè trắng, để nguội cho đến khi khô lại là có thể thưởng thức. Bánh càng để lâu càng dẻo ngọt và có thể kéo dài thời hạn sử dụng bằng cách phơi nắng hoặc bảo quản trong tủ lạnh.\n\n“Nghề làm bánh tổ lời lãi không nhiều, nhưng đây là nghề cha ông truyền dạy nên phải giữ gìn. Người mà “cái nghiệp đã vận vào thân” dù lãi ít họ vẫn theo nghề. Giữa tháng Chạp mà không bày khuôn, nồi ra nấu bánh lại có cảm giác thiếu thiếu”, bà Huyền tâm sự.\n\nDịp Tết Bính Ngọ này, gia đình bà Huyền dự kiến cung ứng khoảng 2.000 chiếc bánh tổ mỗi ngày, phục vụ nhu cầu cúng ông Công ông Táo và Tết cổ truyền tại Đà Nẵng, Quảng Ngãi và cả TPHCM.\n\nĐể đáp ứng nhu cầu sản xuất tăng cao, cơ sở của bà Huyền đã tạo việc làm thời vụ cho hơn 10 lao động địa phương, với mức thu nhập 400.000-500.000 đồng/người/ngày tùy công đoạn.\n\nSố lượng người theo nghề làm bánh tổ tại Đà Nẵng ngày càng ít đi do tính thời vụ của sản phẩm, khiến thợ bánh khó gắn bó lâu dài. Vì vậy, những gia đình như bà Huyền đang nỗ lực không ngừng để giữ gìn và phát huy giá trị của món bánh truyền thống này.","author":"Ngô Linh","category":"Tết 2026","publishedAt":"2026-02-07 15:59","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/nghe-lai-it-nhung-van-do-lua-ngay-dem-phuc-vu-thi-truong-tet-20260207155907826.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/h13lm3sdhrC9djJCo_Ri44yKLT4=/zoom/1200_630/2026/02/07/1-cropped-1770454673408.jpg","crawledAt":"2026-10-21T13:43:18.785Z"},{"id":"dtri-20260206194509973","title":"Tai heo cuộn bắp bò ủ muối - món ngon dễ làm cho mâm cỗ ngày Tết","slug":"tai-heo-cuon-bap-bo-u-muoi-mon-ngon-de-lam-cho-mam-co-ngay-tet","excerpt":"Tai heo cuộn bắp bò ủ muối là món ăn không quá cầu kỳ nhưng đủ tinh tế để làm mới mâm cỗ ngày Tết.","content":"Tai heo cuộn bắp bò ủ muối là món ăn gây sốt trên nhiều hội nhóm ẩm thực những ngày qua. Bên cách các món giò chả quen thuộc, món ăn này được nhiều gia đình lựa chọn cho mâm cỗ ngày Tết bởi hình thức đẹp mắt, hương vị đậm đà mà cách làm lại không quá cầu kỳ. Món ăn có độ giòn sần sật của tai heo, xen lẫn vị mềm ngọt của bắp bò, màu vàng đẹp mắt của gia vị ủ muối.\n\nDưới đây là cách làm món tai heo cuộn bắp bò ủ muối theo gợi ý của chị Nguyễn Thị Thùy Linh (ở Nghệ An).\n\nNguyên liệu\n\n- Tai heo: 1 cái\n\n- Bắp bò 1 cái để cuộn vừa tai\n\n- Gia vị ủ muối mua sẵn\n\n- Sả, gừng\n\n- Chỉ cuộn thực phẩm\n\nCách làm\n\n- Tai heo cắt sát, bỏ bớt phần mỡ, lọc bỏ phần ốc tai gây hôi, rửa thật sạch bên trong với muối và giấm.\n\n- Bắp bò rửa sạch, lọc bỏ phần mỡ nếu có.\n\n- Bọc gọn bắp bò vào bên trong tai heo, dùng dây chỉ quấn đều, chặt tay. Đây là công đoạn cần cẩn thận nhất vì nếu cuộn không chặt, thành phẩm sẽ không liền khối, dễ bị tách rời.\n\n- Pha nước lọc với gia vị ủ muối theo tỷ lệ 1,5l nước với 80gr gia vị ủ muối.\n\n- Thêm 4 cây sả đập dập, 4 lát gừng và khuấy đều, cho tai heo vào ngâm 2 tiếng.\n\n- Cho toàn bộ nước ngâm và tai heo cuộn vào nồi nấu chậm.\n\n- Nấu trong 4 tiếng, nếu tai to cứ 1 tiếng trở 1 lần, còn tai nhỏ thì không cần trở. Việc lật trở để tai được chín và ngấm đều gia vị.\n\n- Sau 4 tiếng thì tắt điện để ngâm thêm 30 phút trong nồi rồi vớt ra.\n\nThành phẩm\n\n- Đợi tai heo nguội hẳn thì cho vào hộp và bỏ ngăn mát tủ lạnh ít nhất 3 tiếng, để qua đêm càng tốt.\n\n- Khi ăn thái miếng mỏng bày ra đĩa.","author":"Hồng Anh","category":"Tết 2026","publishedAt":"2026-02-06 19:45","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/tai-heo-cuon-bap-bo-u-muoi-mon-ngon-de-lam-cho-mam-co-ngay-tet-20260206194509973.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/I4MIjXo5O7YnfrgvwmZCKL9Ngv0=/zoom/1200_630/2026/02/06/tai-heo1-cropped-1770381765472.jpg","crawledAt":"2026-10-21T13:43:18.714Z"},{"id":"dtri-20260206191701866","title":"Mẹ đảm ở TPHCM gợi ý cách làm khô gà lá chanh nhâm nhi ngày Tết","slug":"me-dam-o-tphcm-goi-y-cach-lam-kho-ga-la-chanh-nham-nhi-ngay-tet","excerpt":"Khi chia sẻ cách làm khô gà lá chanh, chị Huệ nhấn mạnh bí quyết ướp gà với nước đá lạnh khoảng 5 phút.","content":"Những ngày cuối năm, căn bếp nhỏ của chị Phạm Thanh Huệ (ở TPHCM) rộn ràng hơn. Người phụ nữ dành nhiều thời gian để nấu những món ngon cho gia đình và bạn bè. Với chị Huệ, Tết sẽ thiếu thiếu nếu trong nhà không có sẵn một hũ khô gà lá chanh để cả gia đình nhâm nhi khi sum họp.\n\nĐây là món ăn vặt “quốc dân” bởi dễ làm, nguyên liệu quen thuộc, vị cay mặn ngọt hài hòa, ăn không ngán. Quan trọng hơn, việc tự làm tại nhà vừa giúp tạo ra những món ngon, đảm bảo vệ sinh, vừa để người làm có thể điều chỉnh độ cay mặn theo khẩu vị của gia đình.\n\nCách làm khô gà lá chanh theo gợi ý của chị Huệ\n\nNguyên liệu\n\n1-1,2kg ức gà\n\nLá chanh thái sợi\n\nỚt tươi, ớt khô (tùy ăn cay).\n\nNước sốt ướp khô gà (công thức dễ làm): 2 muỗng nước mắm, dầu hào, tương ớt, sa tế, đường, ớt bột, bột tỏi, bột hành mỗi loại 1 muỗng, tiêu xay 1/2 muỗng.\n\nSơ chế\n\nGà sau khi rửa sạch sẽ được hấp chín vừa để giữ độ ngọt tự nhiên. Một mẹo nhỏ được chị Huệ chia sẻ là ngâm gà đã hấp vào nước đá lạnh khoảng 5 phút. Bước này giúp thịt gà săn lại, dai ngon hơn, khi xé sợi và sấy sẽ không bị bở.\n\nGà được xé theo thớ dài, trộn đều cùng nước sốt, lá chanh và ớt rồi ướp ít nhất 1-2 tiếng, ngon nhất là để qua đêm cho thấm vị.\n\nDàn đều gà ra khay và sấy ở nhiệt độ khoảng 100°C trong 2,5 tiếng. Trong quá trình sấy, cần đảo và đổi khay để gà khô đồng đều.\n\nThành phẩm\n\nThành phẩm là những sợi khô gà vàng óng, khô vừa, dai nhẹ, dậy mùi lá chanh, cay thơm hấp dẫn. Các gia đình có thể để nguội hẳn rồi cho vào hũ kín, bảo quản tủ mát là có thể ăn dần suốt những ngày Tết.","author":"Hồng Anh","category":"Tết 2026","publishedAt":"2026-02-06 19:17","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/me-dam-o-tphcm-goi-y-cach-lam-kho-ga-la-chanh-nham-nhi-ngay-tet-20260206191701866.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/HFi1Pw_GxA2BelRaroz6rF_KhmY=/zoom/1200_630/2026/02/06/kho-ga-la-chanh10-cropped-1770379062626.jpg","crawledAt":"2026-10-21T13:43:17.663Z"},{"id":"dtri-20260205211349560","title":"Cách làm giò hoa nhiều màu sắc, đẹp mắt cho mâm cỗ Tết","slug":"cach-lam-gio-hoa-nhieu-mau-sac-dep-mat-cho-mam-co-tet","excerpt":"Giò hoa là món ăn quen thuộc trong mâm cỗ Tết, hấp dẫn bởi hình thức nhiều màu sắc và hương vị đậm đà, hòa quyện giữa giò sống, trứng muối, lạp xưởng và các loại rau củ.","content":"Trong mâm cỗ Tết truyền thống, bên cạnh những món quen thuộc như bánh chưng, thịt đông hay dưa hành, giò hoa tạo điểm nhấn riêng nhờ hình thức bắt mắt và hương vị hài hòa của nhiều loại nhân.\n\nKhông chỉ mang đến sự mới lạ, món ăn này còn giúp mâm cỗ thêm sinh động, là lựa chọn lý tưởng để ghi dấu ấn với người thân và khách đến thăm nhà dịp đầu năm.\n\nNếu muốn thử món ăn này, bạn có thể tham khảo công thức chi tiết của chị Tô Hưng Giang ở Hà Nội, để tự tay chế biến món ăn này tại nhà.\n\n1: Nguyên liệu\n\nTrứng gà: 2 quả to\n\nGiò sống: 200g\n\nMộc nhĩ: 3 tai\n\nNấm hương: 4 tai\n\nCà rốt: 1/3 củ\n\nĐậu cove hoặc đậu đũa: 2 quả (có thể thay bằng đậu Hà Lan hoặc thêm hạt đậu Hà Lan)\n\nLạp xưởng: 1 chiếc\n\nTrứng muối: 5 quả\n\nGia vị: bột nêm, hạt tiêu\n\nGiấy bạc hoặc lá chuối, màng bọc thực phẩm\n\n* Cách làm\n\nBước 1: Mộc nhĩ và nấm hương đem ngâm nước ấm cho nở mềm, rửa sạch rồi thái sợi thật nhỏ. Cà rốt bào hoặc thái sợi mảnh. Đậu cove rửa sạch, để nguyên quả hoặc chần sơ cho mềm.\n\nBước 2: Trứng muối ngâm qua chút rượu trắng để khử mùi tanh, sau đó đem hấp khoảng 10 phút cho chín, lấy ra để nguội. Lạp xưởng giữ nguyên chiều dài, chẻ dọc làm bốn phần.\n\nBước 3: Cho giò sống vào âu lớn, thêm mộc nhĩ, nấm hương, cà rốt đã sơ chế. Nêm khoảng 1/3 thìa cà phê bột nêm và 1/3 thìa cà phê hạt tiêu, trộn đều. Không nên nêm quá nhiều gia vị vì giò sống, trứng muối và lạp xưởng vốn đã có độ mặn và vị ngọt tự nhiên, nếu nêm tay sẽ khiến giò bị mặn.\n\nBước 4: Đập 2 quả trứng gà ra bát, thêm khoảng 1/2 thìa canh nước phở hoặc nước lọc, nêm rất nhẹ chút bột nêm hoặc bột canh rồi đánh tan. Bắc chảo chống dính, tráng trứng thật mỏng thành một lá trứng lớn, nhẹ tay để trứng không bị rách. Khi trứng chín, nhẹ nhàng úp ra đĩa và để nguội.\n\nBước 5: Đặt lá trứng lên mặt phẳng sạch, úp mặt đẹp xuống dưới. Phết đều hỗn hợp giò sống lên khắp bề mặt trứng, dàn phẳng. Xếp 5 quả trứng muối thành hàng ở chính giữa, hai bên là các miếng lạp xưởng chẻ dài, tiếp đến đặt đậu cove hoặc đậu Hà Lan dọc theo thân giò để tạo màu sắc.\n\nBước 6: Cuộn giò từ từ và nhẹ tay để trứng không bị rách. Khi cuộn xong, bọc kín bằng một lớp màng bọc thực phẩm, sau đó cuộn thêm một lớp giấy bạc hoặc lá chuối bên ngoài, xoắn chặt hai đầu để cố định.\n\nBước 7: Cho giò vào nồi hấp, hấp khoảng 30 phút đến khi giò chín hoàn toàn. Sau khi hấp, để giò nguội hẳn rồi mới cắt khoanh, khi đó khoanh giò sẽ sắc nét, không bị vỡ.\n\nBước 8: Giò hoa sau khi làm xong có thể bảo quản trong ngăn mát tủ lạnh khoảng 2 ngày. Nếu muốn để lâu hơn, có thể cho vào ngăn đá, khi dùng chỉ cần rã đông tự nhiên và hấp nóng lại.\n\nVới màu sắc hài hòa, hương vị đậm đà, giò hoa không chỉ là món ăn ngon mà còn góp phần làm mâm cỗ Tết thêm trọn vẹn và ấm cúng.","author":"Nam Việt","category":"Tết 2026","publishedAt":"2026-02-05 21:13","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/cach-lam-gio-hoa-nhieu-mau-sac-dep-mat-cho-mam-co-tet-20260205211349560.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/RA4HQIEo6UMpnJRW0trVYrSS9bI=/zoom/1200_630/2026/02/05/anh-1-cropped-cropped-1770300407407.jpg","crawledAt":"2026-10-21T13:43:17.646Z"},{"id":"dtri-20260122100257199","title":"Thể lệ cuộc thi ảnh “Sắc Xuân” 2026 do báo Dân trí tổ chức","slug":"the-le-cuoc-thi-anh-sac-xuan-2026-do-bao-dan-tri-to-chuc","excerpt":"Cuộc thi ảnh “Sắc Xuân” 2026 không chỉ là dịp để bạn đọc thể hiện góc nhìn sáng tạo, mà còn là hành trình lưu giữ vẻ đẹp mùa xuân Việt Nam qua từng khoảnh khắc đời sống,.","content":"(Dân trí) - Cuộc thi ảnh “Sắc Xuân” 2026 không chỉ là dịp để bạn đọc thể hiện góc nhìn sáng tạo, mà còn là hành trình lưu giữ vẻ đẹp mùa xuân Việt Nam qua từng khoảnh khắc đời sống,.\n\nNhằm tôn vinh vẻ đẹp của mùa xuân và ghi lại khoảnh khắc giàu cảm xúc trong những ngày đầu năm mới, báo Dân trí tổ chức cuộc thi ảnh với chủ đề “ Sắc Xuân” 2026 dành cho bạn đọc.\n\nCuộc thi là sân chơi sáng tạo, nơi bạn đọc có thể chia sẻ những khoảnh khắc đời thường, phong cảnh, con người, phong tục, lễ hội… mang đậm không khí mùa xuân Việt Nam.\n\nThông qua từng khuôn hình, “ Sắc Xuân” 2026 kỳ vọng sẽ lan tỏa những giá trị tích cực, cảm xúc ấm áp, niềm tin và hy vọng trong năm mới.\n\nCuộc thi ảnh Sắc Xuân bắt đầu từ ngày 26/1/2026 tới hết ngày 26/2/2026 (tức mồng 10 tết năm Bính Ngọ).\n\nCách thức gửi bài dự thi\n\nĐể gửi bài dự thi cuộc thi ảnh \"Sắc Xuân” 2026 của báo Dân trí, thí sinh thực hiện theo các bước sau:\n\nBước 1: Theo dõi/Yêu thích tài khoản fanpage chính thức của báo Dân trí tại đây\n\nBước 2: Truy cập link gửi bài dự thi tại đây, đăng nhập và thực hiện điền đầy đủ các thông tin bắt buộc.\n\n- Họ và tên\n\n- Số điện thoại tác giả\n\n- Email liên hệ\n\n- Tiêu đề tác phẩm\n\n- Mô tả ngắn bài dự thi\n\n- Nghiên cứu các thông tin cuộc thi và đánh dấu vào nội dung \"Tôi đã đọc, hiểu rõ và đồng ý với thể lệ, quy định, cùng mọi thông tin chi tiết của cuộc thi \" Sắc Xuân\" 2026\".\n\nLưu ý về hình ảnh dự thi\n\n- Định dạng ảnh: JPG, JPEG\n\n- Mỗi tác giả không giới hạn số lượng tác phẩm dự thi\n\n- Tác phẩm dự thi là ảnh đơn hoặc ảnh bộ (tối đa 5 ảnh/tác phẩm ảnh bộ)\n\n- Chấp nhận tác phẩm là ảnh màu hoặc ảnh đơn sắc\n\n- Dung lượng ảnh: Tối đa 10Mb; Tối thiểu 3Mb\n\n- Kích cỡ ảnh: Tối thiểu 3.000 pixel\n\n- Ảnh dự thi tuyệt đối không được chỉnh sửa (cắt ghép), làm sai sự thật.\n\n- Ảnh phải do chính tác giả chụp, ảnh chụp trong thời gian cuộc thi chính thức phát động đến khi kết thúc thời gian ban tổ chức nhận tác phẩm.\n\n- Ảnh có nội dung phản cảm, nhạy cảm, không phù hợp thuần phong mỹ tục và văn hóa Việt Nam sẽ không được chấp nhận.\n\n- Ảnh đã đạt giải tại các cuộc thi khác (nằm trong thời gian từ khi cuộc thi ảnh báo Dân trí phát động trở đi) sẽ không được chấp nhận.\n\n- Ban tổ chức có quyền yêu cầu tác giả gửi ảnh nguyên gốc để kiểm tra, đối chiếu khi xét giải.\n\n- Ban tổ chức có quyền thu hồi giải thưởng đã trao nếu phát hiện tác giả/tác phẩm vi phạm thể lệ của cuộc thi.\n\n- Ban tổ chức được quyền sử dụng các tác phẩm tham dự cuộc thi vào việc truyền thông, quảng bá nét đẹp ngày Tết truyền thống của người dân Việt Nam, cũng như dùng minh hoạ, đưa tin với nội dung phù hợp trên các phương tiện thông tin đại chúng, ấn phẩm báo chí, xuất bản - phi thương mại.\n\nLưu ý về đoạn giới thiệu sản phẩm dự thi\n\n- Tiêu đề bài dự thi không quá 20 chữ (không tính dấu cách).\n\n- Nội dung giới thiệu bài dự thi từ 100 đến 200 chữ (không tính dấu cách).\n\nSau khi gửi bài dự thi, các tác giả sẽ nhận được thông báo đã gửi bài dự thi thành công và đang chờ xét duyệt.\n\nHệ thống của ban tổ chức sẽ gửi email đến tác giả thông báo \"Dân trí đã nhận được bài dự thi của tác giả\" và trạng thái bài dự thi \"đang chờ xét duyệt bởi ban giám khảo cuộc thi\".\n\nTrong quá trình dự thi, ban tổ chức sẽ có thông báo đến email của tác giả về các bình luận trên trang, thời gian chương trình và các nội dung liên quan đến tác phẩm dự thi.\n\nĐây là năm thứ năm liên tiếp báo Dân trí tổ chức cuộc thi ảnh trong dịp Tết Nguyên đán. Cuộc thi ảnh “ Sắc Xuân” 2026 không chỉ là dịp để bạn đọc thể hiện góc nhìn sáng tạo, mà còn là hành trình lưu giữ vẻ đẹp mùa xuân Việt Nam qua từng khoảnh khắc đời sống, góp phần lan tỏa những giá trị nhân văn, tích cực đến cộng đồng.\n\nBan giám khảo cuộc thi là những người có chuyên môn trong lĩnh vực báo chí, nhiếp ảnh và truyền thông. Các tác phẩm xuất sắc sẽ được trao giải thưởng giá trị, đồng thời có cơ hội đăng tải trên báo Dân trí và các nền tảng truyền thông của báo.","author":"Hồng Anh","category":"Tết 2026","publishedAt":"2026-01-22 10:02","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/the-le-cuoc-thi-anh-sac-xuan-2026-do-bao-dan-tri-to-chuc-20260122100257199.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/YzXdZMm25qunYW2b02k2WKMtHI8=/zoom/1200_630/2026/01/22/ruoc-xuan-cropped-1769050928321.jpg","crawledAt":"2026-10-21T13:43:19.843Z"},{"id":"dtri-20260122095623402","title":"Mời bạn đọc tham gia cuộc thi ảnh “Sắc Xuân” 2026","slug":"moi-ban-doc-tham-gia-cuoc-thi-anh-sac-xuan","excerpt":"Nhằm tôn vinh vẻ đẹp mùa xuân và ghi lại những khoảnh khắc giàu cảm xúc trong dịp đầu năm mới, báo Dân trí tổ chức cuộc thi ảnh “Sắc Xuân” dành cho bạn đọc.","content":"(Dân trí) - Nhằm tôn vinh vẻ đẹp mùa xuân và ghi lại những khoảnh khắc giàu cảm xúc trong dịp đầu năm mới, báo Dân trí tổ chức cuộc thi ảnh “Sắc Xuân” dành cho bạn đọc.\n\nMỗi độ xuân về, đất trời khoác lên mình những gam màu tươi mới, mang theo không khí rộn ràng của Tết cổ truyền và niềm hy vọng cho một khởi đầu an lành.\n\nXuân không chỉ hiện diện trong sắc hoa, nắng mới hay phố phường rực rỡ, mà còn lan tỏa trong nhịp sống, ánh mắt, nụ cười và những khoảnh khắc bình dị của đời sống thường ngày.\n\nNhằm tôn vinh vẻ đẹp mùa xuân và ghi lại những khoảnh khắc giàu cảm xúc trong dịp đầu năm mới, báo Dân trí tổ chức cuộc thi ảnh “ Sắc Xuân” dành cho đông đảo bạn đọc.\n\nCuộc thi ảnh Sắc Xuân bắt đầu từ ngày 26/1/2026 tới hết ngày 26/2/2026 (tức mồng 10 tết năm Bính Ngọ).\n\nMời độc giả và những người yêu nghệ thuật nhiếp ảnh gửi ảnh dự thi tại link dưới đây: Cuộc thi ảnh Sắc Xuân 2026 báo Dân trí.\n\nCuộc thi là nơi để những người yêu nhiếp ảnh, dù chuyên nghiệp hay không chuyên, có cơ hội chia sẻ góc nhìn riêng về mùa xuân - từ sắc xuân truyền thống trong gia đình, làng quê, lễ hội, đến sắc xuân hiện đại trong nhịp sống hiện đại hôm nay.\n\nThông qua mỗi bức ảnh dự thi, ban tổ chức mong muốn lan tỏa những giá trị tích cực, những cảm xúc đẹp đẽ của mùa xuân - mùa của đoàn viên, của khởi đầu và của niềm tin, hy vọng.\n\n“Sắc Xuân” không chỉ là cuộc thi ảnh, mà còn là nơi lưu giữ ký ức, kết nối cảm xúc và cùng nhau vẽ nên bức tranh mùa xuân tươi đẹp nhất.\n\nThời gian cuộc thi sẽ được thông tin tới bạn đọc sớm nhất.\n\nNhưng từ bây giờ bạn hãy chuẩn bị và chia sẻ những bức ảnh đẹp và ý nghĩa về Tết và mùa xuân của bạn cùng Dân trí để nhận được những phần quà hấp dẫn.\n\nTổng giải thưởng 35 triệu đồng gồm:\n\n- 1 Giải Nhất: 10 triệu đồng.\n\n- 2 Giải Nhì: Mỗi giải 5 triệu đồng.\n\n- 3 Giải Ba: Mỗi giải 2 triệu đồng.\n\n- 5 Giải Khuyến khích: Mỗi giải 1 triệu đồng.\n\n- 8 Giải Bình chọn: Mỗi giải 500.000 đồng.\n\nMời các tác giả dự thi theo dõi thêm về thể lệ cuộc thi tại link dưới đây: Thể lệ Cuộc thi ảnh \"Sắc Xuân\" .\n\nCuộc thi ảnh do báo Dân trí tổ chức mỗi mùa xuân đã trở thành nét đặc trưng. Mỗi năm, cuộc thi đều nhận được sự quan tâm của độc giả và những người yêu nghệ thuật nhiếp ảnh ở khắp mọi miền.\n\nNăm ngoái, cuộc thi ảnh \"Mang mùa xuân về” đã nhận được 500 tác phẩm với hơn 1.000 ảnh.\n\nCác tác phẩm gửi về phong phú, đa dạng về nội dung, đề tài tạo nên những mảnh ghép cho thấy bức tranh mùa xuân sống động ở khắp mọi miền đất nước.\n\nMỗi tác giả đón Tết ở mỗi địa phương khác nhau, mỗi gia đình có đặc thù khác nhau… đã đem đến những tác phẩm nghệ thuật nhiều sắc màu những ngày xuân.\n\nCông tác tiếp nhận và biên tập tác phẩm đều được thực hiện cẩn trọng, nhằm đảm bảo tính nhất quán và chất lượng nội dung. Từ hơn 500 tác phẩm dự thi, ban tổ chức đã lựa chọn ra 9 tác phẩm xuất sắc nhất để trao giải.\n\nGiải Nhất của cuộc thi thuộc về tác giả Nguyễn Hữu Tấn (ở Quảng Nam) với tác phẩm Vui hội trò chơi dân gian bịt mắt bắt vịt.\n\nHai Giải Nhì thuộc về tác giả Phạm Quốc Dũng với tác phẩm Sới vật đầu Xuân và tác giả Nguyễn Mạnh Cường với tác phẩm Hoa về trên bến Bình Đông.\n\nCuộc thi ảnh “Sắc Xuân” năm nay, ban tổ chức mong muốn sẽ nhận được sự hưởng ứng của đông đảo độc giả trong và ngoài nước để cuộc thi được tổ chức hiệu quả, đáp ứng sự quan tâm của độc giả, lan tỏa những năng lượng tích cực, hướng tới xây dựng cuộc sống tốt đẹp hơn trong năm mới.","author":"Hồng Anh","category":"Tết 2026","publishedAt":"2026-01-22 09:56","source":"dantri.com.vn","url":"https://dantri.com.vn/tet/moi-ban-doc-tham-gia-cuoc-thi-anh-sac-xuan-2026-20260122095623402.htm","categories":["Tết 2026"],"categoryIds":["tet"],"thumbnail":"https://cdnphoto.dantri.com.vn/m9CAkScBRmcICCJG776I79M2lRU=/zoom/1200_630/2026/01/26/tet-2025-cuoc-thi-anh-20250121214124654-2-1738027397759jpg-1738733886826-cropped-1769412090875.jpg","crawledAt":"2026-10-21T13:43:19.878Z"}];
